import * as React from "react";
import { cn } from "@/lib/utils";

type Variant = "default" | "secondary" | "outline" | "ghost" | "brand" | "destructive";
type Size = "sm" | "md" | "lg" | "icon";

const variants: Record<Variant, string> = {
  default: "bg-primary text-primary-foreground hover:bg-primary/90 shadow-control active:shadow-press",
  secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80 border-line border-border shadow-control active:shadow-press",
  outline: "border-line border-input bg-transparent hover:bg-accent hover:text-accent-foreground shadow-control active:shadow-press",
  ghost: "hover:bg-accent hover:text-accent-foreground",
  brand: "bg-brand text-brand-foreground hover:bg-brand/90 shadow-control active:shadow-press",
  destructive: "bg-destructive text-white hover:bg-destructive/90 shadow-control active:shadow-press",
};

const sizes: Record<Size, string> = {
  sm: "h-8 px-3 text-[13px] gap-1.5",
  md: "h-10 px-4 text-sm gap-2",
  lg: "h-12 px-6 text-base gap-2.5",
  icon: "size-10",
};

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
  asChild?: boolean;
}

export function Button({ className, variant = "default", size = "md", type = "button", ...props }: ButtonProps) {
  return (
    <button
      type={type}
      className={cn(
        // Shape, depth, press and motion come from the design-system tokens.
        "inline-flex items-center justify-center whitespace-nowrap rounded-control font-semibold transition-all duration-(--motion) ease-motion",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:pointer-events-none disabled:opacity-50 active:[transform:var(--press)]",
        "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      {...props}
    />
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Content rendered at the inline-start edge (e.g. a country code). */
  startAddon?: React.ReactNode;
  /** Content rendered at the inline-end edge (e.g. a unit or icon). */
  endAddon?: React.ReactNode;
  /** Optional error message; renders below and sets aria-invalid. */
  error?: string;
}

/**
 * ورودی متن. Persian text is RTL by default; pass `dir="ltr"` for phone
 * numbers, emails and codes so digits keep their natural order.
 */
export function Input({ className, type, startAddon, endAddon, error, id, dir, ...props }: InputProps) {
  const grouped = Boolean(startAddon || endAddon);
  const input = (
    <input
      id={id}
      type={type}
      dir={grouped ? undefined : dir}
      aria-invalid={error ? true : undefined}
      className={cn(
        "flex w-full min-w-0 text-sm text-foreground placeholder:text-muted-foreground/70",
        "disabled:cursor-not-allowed disabled:opacity-50",
        grouped
          ? "h-full bg-transparent px-0 outline-none"
          : cn(
              "h-10 rounded-field border-line-field border-input bg-field shadow-field px-3 transition-colors",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:border-transparent",
              "aria-invalid:border-destructive/60",
            ),
        className,
      )}
      {...props}
    />
  );

  if (!grouped) return withError(input, error);

  // The whole group takes the direction, so a `dir="ltr"` phone field puts «+98» on the left.
  return withError(
    <div
      dir={dir}
      className={cn(
        "flex h-10 w-full items-center gap-2 rounded-field border-line-field border-input bg-field shadow-field px-3 text-sm transition-colors",
        "focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60",
        error && "border-destructive/60",
      )}
    >
      {startAddon && <span className="shrink-0 text-muted-foreground">{startAddon}</span>}
      {input}
      {endAddon && <span className="shrink-0 text-muted-foreground">{endAddon}</span>}
    </div>,
    error,
  );
}

function withError(node: React.ReactNode, error?: string) {
  if (!error) return node;
  return (
    <div className="space-y-1.5">
      {node}
      <p className="text-xs text-destructive">{error}</p>
    </div>
  );
}

export function Label({ className, ...props }: React.LabelHTMLAttributes<HTMLLabelElement>) {
  return <label className={cn("text-sm font-medium text-foreground/90", className)} {...props} />;
}

/** Stacks a Label above a control with consistent spacing. */
export function Field({
  label,
  htmlFor,
  hint,
  className,
  children,
}: {
  label: React.ReactNode;
  htmlFor?: string;
  hint?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <Label htmlFor={htmlFor}>{label}</Label>
      {children}
      {hint && <p className="text-xs text-muted-foreground">{hint}</p>}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";

export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  /** Grow with content instead of scrolling. */
  autoResize?: boolean;
  /** Show a «۲۴ / ۱۲۰» counter (requires maxLength). */
  showCount?: boolean;
}

/** متن چندخطی با شمارنده‌ی فارسی و ارتفاع خودکار. */
export function Textarea({ className, autoResize, showCount, maxLength, onChange, value, defaultValue, ...props }: TextareaProps) {
  const ref = React.useRef<HTMLTextAreaElement>(null);
  const [len, setLen] = React.useState(String(value ?? defaultValue ?? "").length);

  const resize = React.useCallback(() => {
    const el = ref.current;
    if (!el || !autoResize) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }, [autoResize]);

  React.useEffect(resize, [resize, value]);

  return (
    <div className="space-y-1">
      <textarea
        ref={ref}
        value={value}
        defaultValue={defaultValue}
        maxLength={maxLength}
        onChange={(e) => {
          setLen(e.target.value.length);
          resize();
          onChange?.(e);
        }}
        className={cn(
          "flex min-h-20 w-full rounded-field border-line-field border-input bg-field shadow-field px-3 py-2 text-sm leading-7 text-foreground",
          "placeholder:text-muted-foreground/70 transition-colors",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:border-transparent",
          "disabled:cursor-not-allowed disabled:opacity-50",
          autoResize ? "resize-none overflow-hidden" : "resize-y",
          className,
        )}
        {...props}
      />
      {showCount && maxLength && (
        <p className="text-end text-[11px] text-muted-foreground" aria-live="polite">
          {fa(len)} / {fa(maxLength)}
        </p>
      )}
    </div>
  );
}

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

export type SelectOption = { value: string; label: string; disabled?: boolean };

export interface SelectProps extends Omit<React.SelectHTMLAttributes<HTMLSelectElement>, "children"> {
  options: SelectOption[];
  placeholder?: string;
}

/**
 * انتخاب. A styled native <select>: keyboard, screen readers and mobile
 * pickers work for free. The chevron sits at the inline-end (left in RTL).
 */
export function Select({ className, options, placeholder, ...props }: SelectProps) {
  return (
    <div className="relative">
      <select
        className={cn(
          "h-10 w-full cursor-pointer appearance-none rounded-field border-line-field border-input bg-field shadow-field ps-3 pe-9 text-sm text-foreground",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:border-transparent",
          "disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
        {...props}
      >
        {placeholder && (
          <option value="" disabled>
            {placeholder}
          </option>
        )}
        {options.map((o) => (
          <option key={o.value} value={o.value} disabled={o.disabled}>
            {o.label}
          </option>
        ))}
      </select>
      <ChevronDown className="pointer-events-none absolute end-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { FloatPortal, useFloat } from "@/lib/float";

export interface ComboboxProps {
  options: string[];
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  emptyText?: string;
  className?: string;
  id?: string;
  /** Hidden input with the picked value, for a plain <form>. */
  name?: string;
  disabled?: boolean;
  /** Only values from `options`: on blur, free text snaps to a matching option or reverts. */
  strict?: boolean;
  "aria-label"?: string;
  "aria-invalid"?: boolean;
  "aria-describedby"?: string;
}

/** Arabic ي/ك, alef-madda, ZWNJ and spaces don't break a match: «علي اباد» finds «علی‌آباد». */
function fold(s: string) {
  return s.replace(/ي/g, "ی").replace(/ى/g, "ی").replace(/ك/g, "ک").replace(/[آأإ]/g, "ا").replace(/[\s‌]+/g, "");
}

/**
 * کمبوباکس: an input with live suggestions. Typing filters by prefix first,
 * then by substring; arrow keys move, Enter picks, Escape closes.
 */
export function Combobox({
  options,
  value = "",
  onChange,
  placeholder = "جست‌وجو…",
  emptyText = "چیزی پیدا نشد",
  className,
  id,
  name,
  disabled,
  strict,
  ...aria
}: ComboboxProps) {
  const [query, setQuery] = React.useState(value);
  const [prevValue, setPrevValue] = React.useState(value);
  const [open, setOpen] = React.useState(false);
  const [index, setIndex] = React.useState(0);
  const listId = React.useId();
  const root = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const { mounted, style, theme, panel } = useFloat(open, root, { matchWidth: true, gap: 4 });

  // The parent changed the value (reset, swap, dependent field): show it.
  if (value !== prevValue) {
    setPrevValue(value);
    setQuery(value);
  }

  const q = query.trim();
  const filtered = React.useMemo(() => {
    const f = fold(q);
    if (!f || q === value) return options;
    const starts = options.filter((o) => fold(o).startsWith(f));
    const contains = options.filter((o) => !fold(o).startsWith(f) && fold(o).includes(f));
    return [...starts, ...contains];
  }, [options, q, value]);

  // Keep the keyboard-active option in view (scrolls only when needed).
  React.useEffect(() => {
    if (!open) return;
    listRef.current?.querySelector(`[data-index="${index}"]`)?.scrollIntoView({ block: "nearest" });
  }, [open, index]);

  function pick(v: string) {
    setQuery(v);
    onChange?.(v);
    setOpen(false);
  }

  function commit() {
    setOpen(false);
    if (!strict || query === value) return;
    const f = fold(query.trim());
    const exact = f ? options.find((o) => fold(o) === f) : undefined;
    if (exact) pick(exact);
    else if (!f && value) pick("");
    else setQuery(value);
  }

  return (
    <div ref={root} className={cn("relative", className)}>
      <div
        className={cn(
          "flex h-10 w-full items-center rounded-field border-line-field bg-field shadow-field pe-2 ps-3 transition-colors focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60",
          aria["aria-invalid"] ? "border-destructive/60" : "border-input",
          disabled && "cursor-not-allowed opacity-50",
        )}
      >
        <input
          id={id}
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          {...aria}
          disabled={disabled}
          autoComplete="off"
          value={query}
          placeholder={placeholder}
          onChange={(e) => {
            setQuery(e.target.value);
            setOpen(true);
            setIndex(0);
          }}
          onFocus={(e) => {
            setOpen(true);
            if (query === value) e.currentTarget.select();
          }}
          onBlur={() => setTimeout(commit, 120)}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setIndex((i) => Math.min(filtered.length - 1, i + 1)); }
            if (e.key === "ArrowUp") { e.preventDefault(); setIndex((i) => Math.max(0, i - 1)); }
            if (e.key === "Enter" && open && filtered[index]) { e.preventDefault(); pick(filtered[index]); }
            if (e.key === "Escape") setOpen(false);
          }}
          className="h-full min-w-0 flex-1 bg-transparent pe-1 text-sm leading-8 outline-none placeholder:text-muted-foreground/70 disabled:cursor-not-allowed"
        />
        <ChevronDown className={cn("size-4 text-muted-foreground transition-transform", open && "rotate-180")} />
      </div>
      {name && <input type="hidden" name={name} value={value} />}
      <FloatPortal open={open} mounted={mounted} style={style} theme={theme} panelRef={panel} className="fixed z-50">
        <ul id={listId} ref={listRef} role="listbox" className="max-h-56 overflow-auto rounded-lg border border-border bg-popover p-1 text-sm leading-7 shadow-lg">
          {filtered.length === 0 && <li className="px-2.5 py-2 text-muted-foreground">{emptyText}</li>}
          {filtered.map((o, i) => (
            <li
              key={o}
              role="option"
              data-index={i}
              aria-selected={o === value}
              onMouseDown={(e) => { e.preventDefault(); pick(o); }}
              onMouseEnter={() => setIndex(i)}
              className={cn("flex cursor-pointer items-center justify-between rounded-md px-2.5 py-2", i === index && "bg-accent")}
            >
              <span className="inline-block pe-[0.2em]">
                {q && q !== value && o.startsWith(q) ? (<><span className="font-semibold">{q}</span>{o.slice(q.length)}</>) : o}
              </span>
              {o === value && <Check className="size-3.5 shrink-0" />}
            </li>
          ))}
        </ul>
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, en, fa } from "@/lib/utils";

export interface OtpFieldProps {
  length?: number;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Called once all boxes are filled. */
  onComplete?: (value: string) => void;
  disabled?: boolean;
  /** sm = 32px boxes (fits narrow cards), md = 36px. */
  size?: "sm" | "md";
  className?: string;
  "aria-label"?: string;
}

/**
 * کد تأیید. Boxes are laid out LTR (the way codes are read from SMS),
 * digits display in Persian, and pasting a full code fills every box.
 * Accepts Persian or Latin digits from the keyboard.
 */
export function OtpField({ length = 6, value, defaultValue = "", onChange, onComplete, disabled, size = "md", className, ...aria }: OtpFieldProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const code = value ?? internal;
  const refs = React.useRef<(HTMLInputElement | null)[]>([]);

  function commit(next: string) {
    const clean = en(next).replace(/\D/g, "").slice(0, length);
    if (value === undefined) setInternal(clean);
    onChange?.(clean);
    if (clean.length === length) onComplete?.(clean);
    refs.current[Math.min(clean.length, length - 1)]?.focus();
  }

  return (
    <div className={cn("inline-flex", size === "sm" ? "gap-1" : "gap-1.5", className)} dir="ltr" role="group" aria-label={aria["aria-label"] ?? "کد تأیید"}>
      {Array.from({ length }, (_, i) => (
        <input
          key={i}
          ref={(el) => { refs.current[i] = el; }}
          inputMode="numeric"
          autoComplete={i === 0 ? "one-time-code" : "off"}
          disabled={disabled}
          value={code[i] ? fa(code[i]) : ""}
          onChange={(e) => {
            const typed = en(e.target.value).replace(/\D/g, "");
            if (typed.length > 1) return commit(code.slice(0, i) + typed); // paste
            commit(code.slice(0, i) + typed + code.slice(i + 1));
          }}
          onKeyDown={(e) => {
            if (e.key === "Backspace" && !code[i] && i > 0) {
              e.preventDefault();
              commit(code.slice(0, i - 1));
            }
            if (e.key === "ArrowLeft") refs.current[i - 1]?.focus();
            if (e.key === "ArrowRight") refs.current[i + 1]?.focus();
          }}
          onFocus={(e) => e.target.select()}
          className={cn(
            "shrink-0 rounded-md border border-input bg-card text-center font-semibold text-foreground caret-transparent",
            size === "sm" ? "h-10 w-8 text-sm" : "h-11 w-9 text-base",
            "transition-colors focus:border-foreground/60 focus:outline-none focus:ring-2 focus:ring-foreground/10",
            "disabled:opacity-50",
          )}
        />
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import { Minus, Plus } from "lucide-react";
import { cn, en, fa } from "@/lib/utils";

export interface NumberFieldProps {
  value?: number;
  defaultValue?: number;
  onChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

/** عدد. Plus sits at the inline-start (right in RTL), display uses Persian digits. */
export function NumberField({ value, defaultValue = 0, onChange, min = -Infinity, max = Infinity, step = 1, disabled, className, ...aria }: NumberFieldProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const n = value ?? internal;

  function set(next: number) {
    const clamped = Math.min(max, Math.max(min, next));
    if (value === undefined) setInternal(clamped);
    onChange?.(clamped);
  }

  const btn = "flex w-10 cursor-pointer items-center justify-center text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40";

  return (
    <div className={cn("inline-flex h-10 items-stretch overflow-hidden rounded-field border-line-field border-input bg-field shadow-field", className)} role="group" aria-label={aria["aria-label"]}>
      <button type="button" aria-label="افزایش" disabled={disabled || n >= max} onClick={() => set(n + step)} className={btn}>
        <Plus className="size-4" />
      </button>
      <input
        inputMode="numeric"
        value={fa(n)}
        disabled={disabled}
        onChange={(e) => {
          const parsed = Number(en(e.target.value).replace(/[^\d.-]/g, ""));
          if (!Number.isNaN(parsed)) set(parsed);
        }}
        className="w-14 border-x border-input bg-transparent text-center text-sm font-semibold outline-none"
      />
      <button type="button" aria-label="کاهش" disabled={disabled || n <= min} onClick={() => set(n - step)} className={btn}>
        <Minus className="size-4" />
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Minus } from "lucide-react";
import { cn } from "@/lib/utils";

export interface CheckboxProps {
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean;
  label?: React.ReactNode;
  description?: React.ReactNode;
  className?: string;
  id?: string;
}

/** چک‌باکس. Box at the inline-start, label after it; supports indeterminate. */
export function Checkbox({ checked, defaultChecked = false, onCheckedChange, disabled, label, description, className, id }: CheckboxProps) {
  const [internal, setInternal] = React.useState(defaultChecked);
  const state = checked ?? internal;
  const autoId = React.useId();
  const boxId = id ?? autoId;

  function toggle() {
    const next = state === "indeterminate" ? true : !state;
    if (checked === undefined) setInternal(next);
    onCheckedChange?.(next);
  }

  const box = (
    <button
      id={boxId}
      type="button"
      role="checkbox"
      aria-checked={state === "indeterminate" ? "mixed" : state}
      disabled={disabled}
      onClick={toggle}
      className={cn(
        "mt-0.5 flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-[min(var(--shape-control),0.25rem)] border-line transition-colors",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        state ? "border-primary bg-primary text-primary-foreground" : "border-input bg-field",
      )}
    >
      {state === "indeterminate" ? <Minus className="size-3" /> : state ? <Check className="size-3" /> : null}
    </button>
  );

  if (!label) return box;
  return (
    <label htmlFor={boxId} className={cn("flex cursor-pointer items-start gap-2.5 text-sm", disabled && "cursor-not-allowed opacity-60", className)}>
      {box}
      <span>
        <span className="block leading-5">{label}</span>
        {description && <span className="block text-xs text-muted-foreground">{description}</span>}
      </span>
    </label>
  );
}

export interface CheckboxGroupProps {
  options: { value: string; label: React.ReactNode; description?: React.ReactNode; disabled?: boolean }[];
  value?: string[];
  defaultValue?: string[];
  onChange?: (value: string[]) => void;
  className?: string;
}

/** گروه چک‌باکس با وضعیت مشترک. */
export function CheckboxGroup({ options, value, defaultValue = [], onChange, className }: CheckboxGroupProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const selected = value ?? internal;
  function toggle(v: string, on: boolean) {
    const next = on ? [...selected, v] : selected.filter((x) => x !== v);
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }
  return (
    <div role="group" className={cn("space-y-2.5", className)}>
      {options.map((o) => (
        <Checkbox key={o.value} label={o.label} description={o.description} disabled={o.disabled} checked={selected.includes(o.value)} onCheckedChange={(on) => toggle(o.value, on)} />
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface RadioOption {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  disabled?: boolean;
}

export interface RadioGroupProps {
  options: RadioOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** "list" = plain radios, "cards" = each option is a selectable card. */
  variant?: "list" | "cards";
  name?: string;
  className?: string;
}

/** گروه رادیویی. Arrow keys move selection; RTL-aware (ArrowLeft = next). */
export function RadioGroup({ options, value, defaultValue, onChange, variant = "list", name, className }: RadioGroupProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? "");
  const selected = value ?? internal;
  const autoName = React.useId();

  function select(v: string) {
    if (value === undefined) setInternal(v);
    onChange?.(v);
  }

  function onKeyDown(e: React.KeyboardEvent, i: number) {
    const dir = e.key === "ArrowLeft" || e.key === "ArrowDown" ? 1 : e.key === "ArrowRight" || e.key === "ArrowUp" ? -1 : 0;
    if (!dir) return;
    e.preventDefault();
    const enabled = options.filter((o) => !o.disabled);
    const cur = enabled.findIndex((o) => o.value === options[i].value);
    const next = enabled[(cur + dir + enabled.length) % enabled.length];
    select(next.value);
    (e.currentTarget.parentElement?.querySelectorAll<HTMLElement>("[role=radio]")[options.indexOf(next)])?.focus();
  }

  return (
    <div role="radiogroup" className={cn(variant === "cards" ? "space-y-2" : "space-y-2.5", className)}>
      {options.map((o, i) => {
        const on = selected === o.value;
        return (
          <button
            key={o.value}
            type="button"
            role="radio"
            name={name ?? autoName}
            aria-checked={on}
            disabled={o.disabled}
            tabIndex={on || (!selected && i === 0) ? 0 : -1}
            onClick={() => select(o.value)}
            onKeyDown={(e) => onKeyDown(e, i)}
            className={cn(
              "flex w-full cursor-pointer items-start gap-2.5 text-start text-sm transition-colors",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
              "disabled:cursor-not-allowed disabled:opacity-50",
              variant === "cards" && "rounded-control border-line p-3",
              variant === "cards" && (on ? "border-foreground/50 bg-accent/60" : "border-border hover:bg-accent/40"),
            )}
          >
            <span className={cn("mt-0.5 flex size-4 shrink-0 items-center justify-center rounded-full border", on ? "border-primary" : "border-input")}>
              {on && <span className="size-2 rounded-full bg-primary" />}
            </span>
            <span>
              <span className="block font-medium leading-5">{o.label}</span>
              {o.description && <span className="block text-xs text-muted-foreground">{o.description}</span>}
            </span>
          </button>
        );
      })}
    </div>
  );
}

