import * as React from "react";
import { cn } from "@/lib/utils";

interface SwitchProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export function Switch({
  className,
  checked,
  defaultChecked = false,
  onCheckedChange,
  ...props
}: SwitchProps) {
  const [internal, setInternal] = React.useState(defaultChecked);
  const isControlled = checked !== undefined;
  const on = isControlled ? checked : internal;

  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={() => {
        if (!isControlled) setInternal(!on);
        onCheckedChange?.(!on);
      }}
      className={cn(
        "relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-[calc(var(--shape-control)*999)] border border-transparent transition-colors duration-(--motion) ease-motion",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        on ? "bg-primary" : "bg-input",
        className,
      )}
      {...props}
    >
      <span
        className={cn(
          "pointer-events-none block size-5 rounded-[calc(var(--shape-control)*999)] shadow transition-[transform,background-color] duration-(--motion) ease-motion",
          on ? "bg-primary-foreground" : "bg-foreground",
          // RTL: the "on" position is the inline-start side; translate toward -x.
          on ? "-translate-x-5" : "-translate-x-0.5",
        )}
      />
    </button>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";

export interface SliderProps {
  value?: number;
  defaultValue?: number;
  onChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Formats the value label, e.g. formatToman. Defaults to Persian digits. */
  format?: (value: number) => string;
  label?: React.ReactNode;
  showValue?: boolean;
  disabled?: boolean;
  className?: string;
}

/**
 * اسلایدر. A styled native range input: the track fills from the inline-start
 * (right in RTL), so the browser handles direction, keyboard and touch.
 */
export function Slider({ value, defaultValue = 0, onChange, min = 0, max = 100, step = 1, format = (v) => fa(v), label, showValue = true, disabled, className }: SliderProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const v = value ?? internal;
  const pct = ((v - min) / (max - min)) * 100;
  const id = React.useId();

  return (
    <div className={cn("space-y-2", className)}>
      {(label || showValue) && (
        <div className="flex items-center justify-between text-xs">
          <label htmlFor={id} className="text-muted-foreground">{label}</label>
          {showValue && <span className="font-medium tabular-nums">{format(v)}</span>}
        </div>
      )}
      <input
        id={id}
        type="range"
        min={min}
        max={max}
        step={step}
        value={v}
        disabled={disabled}
        onChange={(e) => {
          const n = Number(e.target.value);
          if (value === undefined) setInternal(n);
          onChange?.(n);
        }}
        className={cn(
          "h-1.5 w-full cursor-pointer appearance-none rounded-full outline-none disabled:cursor-not-allowed disabled:opacity-50",
          "[&::-webkit-slider-thumb]:size-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-2 [&::-webkit-slider-thumb]:border-primary [&::-webkit-slider-thumb]:bg-background [&::-webkit-slider-thumb]:shadow",
          "[&::-moz-range-thumb]:size-4 [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:border-2 [&::-moz-range-thumb]:border-primary [&::-moz-range-thumb]:bg-background",
          "focus-visible:ring-2 focus-visible:ring-ring/60",
        )}
        style={{ background: `linear-gradient(to left, var(--primary) ${pct}%, var(--input) ${pct}%)` }}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";

export type RangeValue = [number, number];

export interface RangeSliderProps {
  value?: RangeValue;
  defaultValue?: RangeValue;
  onChange?: (value: RangeValue) => void;
  /**
   * Fires once when an interaction ends (thumb or track released, or a key
   * press) and only if the value actually changed. Use it for fetches or
   * scroll-to-results; use onChange for the live preview.
   */
  onCommit?: (value: RangeValue) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Formats each end label, e.g. formatToman. Defaults to Persian digits. */
  format?: (value: number) => string;
  label?: React.ReactNode;
  showValue?: boolean;
  /** Shown instead of the two values while the range covers [min, max], e.g. «همه قیمت‌ها». */
  fullRangeLabel?: React.ReactNode;
  disabled?: boolean;
  className?: string;
  /** Accessible name for the lower (کف) thumb. */
  minThumbLabel?: string;
  /** Accessible name for the upper (سقف) thumb. */
  maxThumbLabel?: string;
}

function clamp(n: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, n));
}

function snap(n: number, min: number, step: number) {
  const snapped = min + Math.round((n - min) / step) * step;
  // Guard float drift on large toman steps.
  const decimals = String(step).includes(".") ? (String(step).split(".")[1]?.length ?? 0) : 0;
  return Number(snapped.toFixed(decimals));
}

function pctOf(value: number, min: number, max: number) {
  if (max <= min) return 0;
  return ((value - min) / (max - min)) * 100;
}

type Thumb = "min" | "max";

/**
 * اسلایدر بازه. Two thumbs on one track; the active band fills from
 * inline-start (right in RTL) via logical inset, never left/right.
 */
export function RangeSlider({
  value,
  defaultValue = [0, 100],
  onChange,
  onCommit,
  min = 0,
  max = 100,
  step = 1,
  format = (v) => fa(v),
  label,
  showValue = true,
  fullRangeLabel,
  disabled,
  className,
  minThumbLabel = "کف",
  maxThumbLabel = "سقف",
}: RangeSliderProps) {
  const [internal, setInternal] = React.useState<RangeValue>(defaultValue);
  const controlled = value !== undefined;
  const [lo, hi] = controlled ? value : internal;
  const loRef = React.useRef(lo);
  const hiRef = React.useRef(hi);
  const trackRef = React.useRef<HTMLDivElement>(null);
  const activeThumb = React.useRef<Thumb | null>(null);
  // Value when the current interaction began; null when none is in progress.
  const startValue = React.useRef<RangeValue | null>(null);
  const [dragging, setDragging] = React.useState<Thumb | null>(null);
  const labelId = React.useId();

  React.useLayoutEffect(() => {
    loRef.current = lo;
    hiRef.current = hi;
  }, [lo, hi]);

  const loPct = pctOf(lo, min, max);
  const hiPct = pctOf(hi, min, max);

  function commit(next: RangeValue) {
    const ordered: RangeValue = next[0] <= next[1] ? next : [next[1], next[0]];
    // Most pointer moves snap to the same step; don't re-render or notify.
    if (ordered[0] === loRef.current && ordered[1] === hiRef.current) return;
    loRef.current = ordered[0];
    hiRef.current = ordered[1];
    if (!controlled) setInternal(ordered);
    onChange?.(ordered);
  }

  function beginInteraction() {
    startValue.current = [loRef.current, hiRef.current];
  }

  // Thumb pointerup bubbles to the track too; the null guard makes the
  // second call a no-op so onCommit fires once per interaction.
  function endInteraction() {
    const start = startValue.current;
    if (!start) return;
    startValue.current = null;
    if (start[0] !== loRef.current || start[1] !== hiRef.current) {
      onCommit?.([loRef.current, hiRef.current]);
    }
  }

  function setThumb(thumb: Thumb, raw: number) {
    const curLo = loRef.current;
    const curHi = hiRef.current;
    const snapped = snap(raw, min, step);
    if (thumb === "min") {
      commit([clamp(snapped, min, curHi), curHi]);
    } else {
      commit([curLo, clamp(snapped, curLo, max)]);
    }
  }

  function clientXToValue(clientX: number) {
    const el = trackRef.current;
    if (!el) return min;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return min;
    const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
    // Value grows toward inline-end: left in RTL, right in LTR.
    const rtl = getComputedStyle(el).direction === "rtl";
    const t = rtl ? 1 - ratio : ratio;
    return snap(min + t * (max - min), min, step);
  }

  function nearestThumb(v: number): Thumb {
    const curLo = loRef.current;
    const curHi = hiRef.current;
    const dMin = Math.abs(v - curLo);
    const dMax = Math.abs(v - curHi);
    if (dMin !== dMax) return dMin < dMax ? "min" : "max";
    return v < (curLo + curHi) / 2 ? "min" : "max";
  }

  function onPointerDownTrack(e: React.PointerEvent<HTMLDivElement>) {
    if (disabled) return;
    e.preventDefault();
    const v = clientXToValue(e.clientX);
    const thumb = nearestThumb(v);
    activeThumb.current = thumb;
    setDragging(thumb);
    beginInteraction();
    setThumb(thumb, v);
    e.currentTarget.setPointerCapture(e.pointerId);
  }

  function onPointerMoveTrack(e: React.PointerEvent<HTMLDivElement>) {
    if (disabled || activeThumb.current === null) return;
    if (!e.currentTarget.hasPointerCapture(e.pointerId)) return;
    setThumb(activeThumb.current, clientXToValue(e.clientX));
  }

  function onPointerUpTrack(e: React.PointerEvent<HTMLDivElement>) {
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    activeThumb.current = null;
    setDragging(null);
    endInteraction();
  }

  function handleKey(thumb: Thumb, e: React.KeyboardEvent<HTMLButtonElement>) {
    if (disabled) return;
    const el = trackRef.current;
    const rtl = el ? getComputedStyle(el).direction === "rtl" : true;
    const current = thumb === "min" ? loRef.current : hiRef.current;
    let next: number | null = null;
    const big = step * 10;

    switch (e.key) {
      case "ArrowRight":
        next = current + (rtl ? -step : step);
        break;
      case "ArrowLeft":
        next = current + (rtl ? step : -step);
        break;
      case "ArrowUp":
        next = current + step;
        break;
      case "ArrowDown":
        next = current - step;
        break;
      case "PageUp":
        next = current + big;
        break;
      case "PageDown":
        next = current - big;
        break;
      case "Home":
        next = thumb === "min" ? min : loRef.current;
        break;
      case "End":
        next = thumb === "max" ? max : hiRef.current;
        break;
      default:
        return;
    }
    e.preventDefault();
    beginInteraction();
    setThumb(thumb, next);
    endInteraction();
  }

  function startThumbDrag(thumb: Thumb, e: React.PointerEvent<HTMLButtonElement>) {
    if (disabled) return;
    e.stopPropagation();
    activeThumb.current = thumb;
    setDragging(thumb);
    beginInteraction();
    e.currentTarget.setPointerCapture(e.pointerId);
  }

  function moveThumbDrag(thumb: Thumb, e: React.PointerEvent<HTMLButtonElement>) {
    if (activeThumb.current !== thumb) return;
    if (!e.currentTarget.hasPointerCapture(e.pointerId)) return;
    setThumb(thumb, clientXToValue(e.clientX));
  }

  function endThumbDrag(e: React.PointerEvent<HTMLButtonElement>) {
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    activeThumb.current = null;
    setDragging(null);
    endInteraction();
  }

  const thumbClass = cn(
    "absolute top-1/2 z-10 flex size-11 -translate-y-1/2 items-center justify-center",
    "cursor-grab touch-none outline-none active:cursor-grabbing",
    "disabled:cursor-not-allowed",
    "focus-visible:[&>span]:ring-2 focus-visible:[&>span]:ring-ring/60",
  );

  const knobClass = cn(
    "block size-4 rounded-full border-2 border-primary bg-background shadow",
    "transition-[box-shadow,transform] duration-150 motion-reduce:transition-none",
  );

  const fullRange = fullRangeLabel != null && lo <= min && hi >= max;

  return (
    // overflow-x-clip: the 44px hit areas reach past the track ends; clipping
    // them keeps a padded, scrollable parent (e.g. Sheet) from scrolling sideways.
    <div className={cn("space-y-2 overflow-x-clip", className)}>
      {(label || showValue) && (
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 text-xs">
          {label && (
            <span id={labelId} className="text-muted-foreground">
              {label}
            </span>
          )}
          {showValue && (
            <span
              className="ms-auto flex flex-wrap items-center gap-x-1.5 font-medium tabular-nums"
              aria-live="polite"
            >
              {fullRange ? (
                fullRangeLabel
              ) : (
                <>
                  <span className="whitespace-nowrap">{format(lo)}</span>
                  <span className="font-normal text-muted-foreground" aria-hidden>
                    تا
                  </span>
                  <span className="whitespace-nowrap">{format(hi)}</span>
                </>
              )}
            </span>
          )}
        </div>
      )}

      <div
        ref={trackRef}
        role="group"
        aria-labelledby={label ? labelId : undefined}
        aria-label={label ? undefined : "محدوده"}
        onPointerDown={onPointerDownTrack}
        onPointerMove={onPointerMoveTrack}
        onPointerUp={onPointerUpTrack}
        onPointerCancel={onPointerUpTrack}
        className={cn(
          // mx-2 = half the visible knob, so the knob sits inside at min/max.
          "relative mx-2 flex h-11 items-center select-none",
          disabled && "pointer-events-none opacity-50",
        )}
      >
        <div
          aria-hidden
          className="h-1.5 w-full rounded-full"
          style={{
            background: `linear-gradient(to left, var(--input) 0%, var(--input) ${loPct}%, var(--primary) ${loPct}%, var(--primary) ${hiPct}%, var(--input) ${hiPct}%, var(--input) 100%)`,
          }}
        />

        <button
          type="button"
          role="slider"
          aria-valuemin={min}
          aria-valuemax={hi}
          aria-valuenow={lo}
          aria-valuetext={format(lo)}
          aria-label={minThumbLabel}
          disabled={disabled}
          tabIndex={disabled ? -1 : 0}
          className={cn(thumbClass, dragging === "min" && "z-30")}
          style={{ insetInlineStart: `calc(${loPct}% - 1.375rem)` }}
          onKeyDown={(e) => handleKey("min", e)}
          onPointerDown={(e) => startThumbDrag("min", e)}
          onPointerMove={(e) => moveThumbDrag("min", e)}
          onPointerUp={endThumbDrag}
          onPointerCancel={endThumbDrag}
        >
          <span className={knobClass} />
        </button>

        <button
          type="button"
          role="slider"
          aria-valuemin={lo}
          aria-valuemax={max}
          aria-valuenow={hi}
          aria-valuetext={format(hi)}
          aria-label={maxThumbLabel}
          disabled={disabled}
          tabIndex={disabled ? -1 : 0}
          className={cn(thumbClass, "z-20", dragging === "max" && "z-30")}
          style={{ insetInlineStart: `calc(${hiPct}% - 1.375rem)` }}
          onKeyDown={(e) => handleKey("max", e)}
          onPointerDown={(e) => startThumbDrag("max", e)}
          onPointerMove={(e) => moveThumbDrag("max", e)}
          onPointerUp={endThumbDrag}
          onPointerCancel={endThumbDrag}
        >
          <span className={knobClass} />
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Star } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface RatingProps {
  value?: number;
  defaultValue?: number;
  onChange?: (value: number) => void;
  max?: number;
  readOnly?: boolean;
  showValue?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
}

/** امتیاز. Stars fill from the right (inline-start); hover previews the value. */
export function Rating({ value, defaultValue = 0, onChange, max = 5, readOnly, showValue, size = "md", className }: RatingProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const [hover, setHover] = React.useState<number | null>(null);
  const v = value ?? internal;
  const shown = hover ?? v;
  const sz = { sm: "size-4", md: "size-5", lg: "size-7" }[size];

  return (
    <div className={cn("inline-flex items-center gap-2", className)}>
      <div role={readOnly ? "img" : "radiogroup"} aria-label={`${fa(v)} از ${fa(max)}`} className="flex" onMouseLeave={() => setHover(null)}>
        {Array.from({ length: max }, (_, i) => i + 1).map((n) => (
          <button
            key={n}
            type="button"
            role={readOnly ? undefined : "radio"}
            aria-checked={readOnly ? undefined : n === v}
            aria-label={`${fa(n)} ستاره`}
            disabled={readOnly}
            onMouseEnter={() => !readOnly && setHover(n)}
            onClick={() => {
              if (value === undefined) setInternal(n);
              onChange?.(n);
            }}
            className={cn("p-0.5 transition-transform", !readOnly && "cursor-pointer hover:scale-110", "disabled:cursor-default")}
          >
            <Star className={cn(sz, "transition-colors", n <= shown ? "fill-foreground text-foreground" : "text-muted-foreground/40")} />
          </button>
        ))}
      </div>
      {showValue && <span className="text-xs text-muted-foreground">{fa(v)} از {fa(max)}</span>}
    </div>
  );
}

"use client";

import * as React from "react";
import { FileUp, X } from "lucide-react";
import { cn, faFileSize } from "@/lib/utils";

export interface FileUploadProps {
  accept?: string;
  multiple?: boolean;
  maxSize?: number;
  onFiles?: (files: File[]) => void;
  hint?: React.ReactNode;
  className?: string;
}

/** آپلود فایل. Drag-and-drop zone with a Persian file list (sizes in مگابایت). */
export function FileUpload({ accept, multiple = true, maxSize, onFiles, hint, className }: FileUploadProps) {
  const [files, setFiles] = React.useState<File[]>([]);
  const [over, setOver] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);

  function add(list: FileList | null) {
    if (!list) return;
    const incoming = Array.from(list);
    const tooBig = maxSize ? incoming.find((f) => f.size > maxSize) : undefined;
    if (tooBig) {
      setError(`«${tooBig.name}» بزرگ‌تر از ${faFileSize(maxSize!)} است.`);
      return;
    }
    setError(null);
    const next = multiple ? [...files, ...incoming] : incoming.slice(0, 1);
    setFiles(next);
    onFiles?.(next);
  }

  return (
    <div className={cn("space-y-2", className)}>
      <div
        role="button"
        tabIndex={0}
        onClick={() => inputRef.current?.click()}
        onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && inputRef.current?.click()}
        onDragOver={(e) => { e.preventDefault(); setOver(true); }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => { e.preventDefault(); setOver(false); add(e.dataTransfer.files); }}
        className={cn(
          "flex cursor-pointer flex-col items-center justify-center gap-1.5 rounded-lg border border-dashed p-6 text-center transition-colors",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
          over ? "border-foreground/60 bg-accent/60" : "border-input hover:bg-accent/40",
        )}
      >
        <FileUp className="size-5 text-muted-foreground" />
        <p className="text-sm">فایل را این‌جا رها کنید یا <span className="font-medium underline underline-offset-4">انتخاب کنید</span></p>
        {hint && <p className="text-xs text-muted-foreground">{hint}</p>}
        <input ref={inputRef} type="file" accept={accept} multiple={multiple} className="sr-only" onChange={(e) => add(e.target.files)} />
      </div>
      {error && <p className="text-xs text-destructive">{error}</p>}
      {files.length > 0 && (
        <ul className="divide-y divide-border rounded-lg border border-border">
          {files.map((f, i) => (
            <li key={`${f.name}-${i}`} className="flex items-center gap-2 px-3 py-2 text-xs">
              <span className="flex-1 truncate" dir="auto">{f.name}</span>
              <span className="text-muted-foreground">{faFileSize(f.size)}</span>
              <button
                type="button"
                aria-label="حذف"
                onClick={() => { const next = files.filter((_, j) => j !== i); setFiles(next); onFiles?.(next); }}
                className="cursor-pointer rounded p-0.5 text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS_SHORT, jalaliMonthLength, jalaliWeekday, toGregorian, toJalali } from "@/lib/jalali";

export interface CalendarProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (date: Date) => void;
  /** Disable dates before/after these. */
  min?: Date;
  max?: Date;
  /** Grey out Fridays (default true). */
  markWeekend?: boolean;
  /** Holiday name for a day, or null. Named days turn red and show the name on hover; pass occasionsOn from the iran-holidays lib. */
  occasion?: (date: Date) => string | null;
  compact?: boolean;
  className?: string;
}

const sameDay = (a: Date | null | undefined, b: Date) =>
  !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

/**
 * تقویم شمسی. Renders a Jalali month; weeks start on شنبه, Fridays are
 * marked, today gets a ring. Values are plain JS Dates so the rest of your
 * app stays Gregorian-agnostic.
 */
export function Calendar({ value, defaultValue = null, onChange, min, max, markWeekend = true, occasion, compact, className }: CalendarProps) {
  const [internal, setInternal] = React.useState<Date | null>(defaultValue);
  const selected = value === undefined ? internal : value;
  const today = React.useMemo(() => new Date(), []);
  const initial = toJalali(selected ?? today);
  const [view, setView] = React.useState({ jy: initial.jy, jm: initial.jm });

  const first = toGregorian(view.jy, view.jm, 1);
  const offset = jalaliWeekday(first);
  const days = jalaliMonthLength(view.jy, view.jm);
  const cells = Array.from({ length: offset + days }, (_, i) => (i < offset ? null : i - offset + 1));

  function move(delta: number) {
    setView((v) => {
      let jm = v.jm + delta;
      let jy = v.jy;
      if (jm < 1) { jm = 12; jy -= 1; }
      if (jm > 12) { jm = 1; jy += 1; }
      return { jy, jm };
    });
  }

  function pick(d: number) {
    const date = toGregorian(view.jy, view.jm, d);
    if (value === undefined) setInternal(date);
    onChange?.(date);
  }

  const nav = "flex size-7 cursor-pointer items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground";

  return (
    <div className={cn("rounded-xl border border-border bg-card p-3", compact ? "w-[220px]" : "w-[260px]", className)}>
      <div className="flex items-center justify-between px-1">
        <span className={cn("font-semibold", compact ? "text-xs" : "text-sm")}>
          {JALALI_MONTHS[view.jm - 1]} {fa(view.jy)}
        </span>
        <div className="flex gap-0.5">
          <button type="button" aria-label="ماه قبل" onClick={() => move(-1)} className={nav}><ChevronRight className="size-4" /></button>
          <button type="button" aria-label="ماه بعد" onClick={() => move(1)} className={nav}><ChevronLeft className="size-4" /></button>
        </div>
      </div>
      <div className={cn("mt-2 grid grid-cols-7 overflow-hidden text-center", compact ? "gap-px text-[10px]" : "gap-0.5 text-[11px]")} role="grid">
        {JALALI_WEEKDAYS_SHORT.map((d) => (
          <span key={d} className="py-1 text-muted-foreground/80" aria-hidden>{d}</span>
        ))}
        {cells.map((d, i) => {
          if (d === null) return <span key={`e${i}`} className={compact ? "h-6" : "h-8"} />;
          const date = toGregorian(view.jy, view.jm, d);
          const isSel = sameDay(selected, date);
          const isToday = sameDay(today, date);
          const fri = i % 7 === 6;
          const disabled = (min && date < min) || (max && date > max);
          const holiday = occasion?.(date) ?? null;
          return (
            <button
              key={d}
              type="button"
              role="gridcell"
              aria-selected={isSel}
              aria-label={`${fa(d)} ${JALALI_MONTHS[view.jm - 1]}${holiday ? `، تعطیل: ${holiday}` : ""}`}
              title={holiday ?? undefined}
              disabled={!!disabled}
              onClick={() => pick(d)}
              className={cn(
                "flex w-full min-w-0 items-center justify-center rounded-md leading-none whitespace-nowrap tabular-nums transition-colors",
                compact ? "h-6" : "h-8",
                isSel && "bg-primary font-semibold text-primary-foreground",
                !isSel && isToday && "ring-1 ring-inset ring-foreground/40",
                !isSel && markWeekend && fri && "text-muted-foreground/60",
                !isSel && holiday && "font-semibold text-destructive underline decoration-dotted underline-offset-4",
                !isSel && !disabled && "cursor-pointer hover:bg-accent",
                disabled && "cursor-not-allowed opacity-30",
              )}
            >
              {fa(d)}
            </button>
          );
        })}
      </div>
    </div>
  );
}

