export interface DatePickerProps extends Omit<CalendarProps, "value" | "onChange" | "className"> {
  value?: Date | null;
  onChange?: (date: Date | null) => void;
  placeholder?: string;
  clearable?: boolean;
  /** Include the weekday, e.g. «شنبه، ۳۱ شهریور ۱۴۰۵». */
  weekday?: boolean;
  className?: string;
}

/** انتخاب تاریخ: a field that opens the Jalali calendar in a popover. */
export function DatePicker({ value, onChange, placeholder = "انتخاب تاریخ", clearable = true, weekday = true, className, ...cal }: DatePickerProps) {
  const [internal, setInternal] = React.useState<Date | null>(null);
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);
  const date = value === undefined ? internal : value;
  const { mounted, style, theme, panel } = useFloat(open, ref);

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, ref.current, panel.current)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open, panel]);

  function set(d: Date | null) {
    if (value === undefined) setInternal(d);
    onChange?.(d);
  }

  return (
    <div ref={ref} className={cn("relative min-w-0", className)}>
      <button
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className={cn(
          "flex h-10 w-full min-w-0 cursor-pointer items-center justify-between gap-2 overflow-hidden rounded-field border-line-field border-input bg-field shadow-field px-3 text-sm transition-colors",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
        )}
      >
        <span className={cn("flex min-w-0 items-center gap-2", !date && "text-muted-foreground/70")}>
          <CalendarDays className="size-4 shrink-0 text-muted-foreground" />
          <span className="truncate whitespace-nowrap">{date ? formatJalali(date, { weekday }) : placeholder}</span>
        </span>
        {clearable && date && (
          <span role="button" aria-label="پاک کردن" onClick={(e) => { e.stopPropagation(); set(null); }} className="rounded p-0.5 text-muted-foreground hover:text-foreground">
            <X className="size-3.5" />
          </span>
        )}
      </button>
      <FloatPortal open={open} mounted={mounted} style={style} theme={theme} panelRef={panel} role="dialog" className="fixed z-50 shadow-xl">
        <Calendar {...cal} value={date} onChange={(d) => { set(d); setOpen(false); }} />
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { CornerDownLeft, Search } from "lucide-react";
import { cn, en } from "@/lib/utils";

function fold(s: string) {
  return en(s)
    .toLowerCase()
    .replace(/\u200c/g, "")
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/آ/g, "ا")
    .replace(/[_\s-]+/g, " ")
    .trim();
}

export interface CommandItem {
  id: string;
  label: string;
  icon?: React.ComponentType<{ className?: string }>;
  shortcut?: string;
  keywords?: string[];
  group?: string;
  onSelect?: () => void;
}

export interface CommandProps {
  items: CommandItem[];
  placeholder?: string;
  emptyText?: string;
  onSelect?: (item: CommandItem) => void;
  className?: string;
  autoFocus?: boolean;
}

/** پالت دستور: filterable list with keyboard navigation. Wrap in CommandDialog for ⌘K. */
export function Command({
  items,
  placeholder = "دستور یا جست‌وجو…",
  emptyText = "چیزی پیدا نشد",
  onSelect,
  className,
  autoFocus,
}: CommandProps) {
  const [q, setQ] = React.useState("");
  const [index, setIndex] = React.useState(0);
  const listId = React.useId();
  const filtered = React.useMemo(() => {
    const t = fold(q);
    if (!t) return items;
    return items.filter((i) => fold(i.label).includes(t) || i.keywords?.some((k) => fold(k).includes(t)));
  }, [items, q]);

  function run(item: CommandItem) {
    item.onSelect?.();
    onSelect?.(item);
  }

  const groups = Array.from(new Set(filtered.map((i) => i.group ?? "")));

  return (
    <div
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground",
        className,
      )}
    >
      <div className="flex items-center gap-2 border-b border-border px-3">
        <Search className="size-4 text-muted-foreground" />
        <input
          autoFocus={autoFocus}
          value={q}
          onChange={(e) => { setQ(e.target.value); setIndex(0); }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              setIndex((i) => Math.min(filtered.length - 1, i + 1));
            }
            if (e.key === "ArrowUp") {
              e.preventDefault();
              setIndex((i) => Math.max(0, i - 1));
            }
            if (e.key === "Enter" && filtered[index]) run(filtered[index]);
          }}
          placeholder={placeholder}
          role="combobox"
          aria-expanded
          aria-controls={listId}
          aria-autocomplete="list"
          className="h-11 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground/70"
        />
        <kbd className="rounded border border-border px-1.5   text-[10px] text-muted-foreground">
          Esc
        </kbd>
      </div>
      <div id={listId} role="listbox" className="max-h-72 overflow-auto p-1.5 text-sm">
        {filtered.length === 0 && (
          <p className="px-2 py-6 text-center text-muted-foreground">
            {emptyText}
          </p>
        )}
        {groups.map((g) => (
          <div key={g}>
            {g && (
              <p className="px-2 pb-1 pt-2 text-[11px] text-muted-foreground">
                {g}
              </p>
            )}
            {filtered
              .filter((i) => (i.group ?? "") === g)
              .map((item) => {
                const i = filtered.indexOf(item);
                return (
                  <button
                    key={item.id}
                    type="button"
                    role="option"
                    aria-selected={i === index}
                    onMouseEnter={() => setIndex(i)}
                    onClick={() => run(item)}
                    className={cn(
                      "flex w-full cursor-pointer items-center justify-between rounded-lg px-2.5 py-2 text-start",
                      i === index && "bg-accent",
                    )}
                  >
                    <span className="flex items-center gap-2.5">
                      {item.icon && (
                        <item.icon className="size-4 text-muted-foreground" />
                      )}
                      {item.label}
                    </span>
                    {i === index ? (
                      <CornerDownLeft className="size-3.5 text-muted-foreground" />
                    ) : (
                      item.shortcut && (
                        <kbd className="  text-[10px] text-muted-foreground">
                          {item.shortcut}
                        </kbd>
                      )
                    )}
                  </button>
                );
              })}
          </div>
        ))}
      </div>
    </div>
  );
}

/** Opens Command in a centered overlay on ⌘K / Ctrl+K. */
export function CommandDialog({
  open,
  onOpenChange,
  hotkey = true,
  ...props
}: CommandProps & { open: boolean; onOpenChange: (open: boolean) => void; hotkey?: boolean }) {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => setMounted(true), []);

  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (hotkey && (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        onOpenChange(!open);
      }
      if (e.key === "Escape" && open) onOpenChange(false);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onOpenChange, hotkey]);

  React.useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, [open]);

  if (!mounted || !open) return null;
  return createPortal(
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[15vh] backdrop-blur-sm"
      onClick={() => onOpenChange(false)}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label="جست‌وجو"
        className="w-full max-w-lg animate-fade-up [animation-duration:250ms]"
        onClick={(e) => e.stopPropagation()}
      >
        <Command
          autoFocus
          {...props}
          onSelect={(i) => {
            props.onSelect?.(i);
            onOpenChange(false);
          }}
        />
      </div>
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

export interface DialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: React.ReactNode;
  description?: React.ReactNode;
  children?: React.ReactNode;
  footer?: React.ReactNode;
  /** alertdialog blocks outside-click dismissal. */
  role?: "dialog" | "alertdialog";
  className?: string;
}

/**
 * پنجره (مودال). Closes on Escape and overlay click, locks body scroll,
 * moves focus inside on open and restores it on close.
 */
export function Dialog({ open, onOpenChange, title, description, children, footer, role = "dialog", className }: DialogProps) {
  const panel = React.useRef<HTMLDivElement>(null);
  const titleId = React.useId();
  const descId = React.useId();

  React.useEffect(() => {
    if (!open) return;
    const prev = document.activeElement as HTMLElement | null;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    panel.current?.querySelector<HTMLElement>("[data-autofocus], button, input, textarea, select, a[href]")?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onOpenChange(false);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      prev?.focus();
    };
  }, [open, onOpenChange]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-black/60 p-4 backdrop-blur-sm sm:items-center"
      onClick={() => role === "dialog" && onOpenChange(false)}
    >
      <div
        ref={panel}
        role={role}
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-describedby={description ? descId : undefined}
        onClick={(e) => e.stopPropagation()}
        className={cn(
          "w-full max-w-md rounded-surface border-line border-border bg-popover p-5 text-popover-foreground shadow-overlay",
          "animate-fade-up [animation-duration:250ms]",
          className,
        )}
      >
        {(title || role === "dialog") && (
          <div className="flex items-start justify-between gap-4">
            <div>
              {title && <h2 id={titleId} className="text-base font-semibold">{title}</h2>}
              {description && <p id={descId} className="mt-1 text-sm text-muted-foreground">{description}</p>}
            </div>
            {role === "dialog" && (
              <button type="button" aria-label="بستن" onClick={() => onOpenChange(false)} className="-me-1 -mt-1 flex size-8 cursor-pointer items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
                <X className="size-4" />
              </button>
            )}
          </div>
        )}
        {children && <div className="mt-4">{children}</div>}
        {footer && <div className="mt-5 flex flex-row-reverse justify-start gap-2 sm:flex-row">{footer}</div>}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Button } from "./button";
import { Dialog } from "./dialog";

export interface AlertDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  confirmText?: string;
  cancelText?: string;
  destructive?: boolean;
  onConfirm: () => void | Promise<void>;
}

/** تأیید عمل: a blocking confirmation for irreversible actions. Cancel is focused first. */
export function AlertDialog({ open, onOpenChange, title, description, confirmText = "تأیید", cancelText = "انصراف", destructive, onConfirm }: AlertDialogProps) {
  const [busy, setBusy] = React.useState(false);
  return (
    <Dialog
      open={open}
      onOpenChange={onOpenChange}
      role="alertdialog"
      title={title}
      description={description}
      className="max-w-sm"
      footer={
        <>
          <Button
            variant={destructive ? "destructive" : "default"}
            disabled={busy}
            onClick={async () => {
              setBusy(true);
              try { await onConfirm(); onOpenChange(false); } finally { setBusy(false); }
            }}
          >
            {busy ? "لطفاً صبر کنید…" : confirmText}
          </Button>
          <Button variant="outline" data-autofocus onClick={() => onOpenChange(false)}>{cancelText}</Button>
        </>
      }
    />
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export type MenuItem =
  | {
      type?: "item";
      label: React.ReactNode;
      icon?: React.ComponentType<{ className?: string }>;
      shortcut?: string;
      danger?: boolean;
      disabled?: boolean;
      onSelect?: () => void;
    }
  | { type: "separator" }
  | { type: "label"; label: React.ReactNode };

export interface DropdownMenuProps {
  trigger: React.ReactNode;
  items: MenuItem[];
  align?: "start" | "end";
  className?: string;
}

/**
 * منوی کشویی. Opens below the trigger aligned to the inline-start; closes on
 * outside click and Escape; arrow keys move between items.
 */
export function DropdownMenu({
  trigger,
  items,
  align = "start",
  className,
}: DropdownMenuProps) {
  const [open, setOpen] = React.useState(false);
  const root = React.useRef<HTMLDivElement>(null);
  const { mounted, style, theme, panel, update } = useFloat(open, root, { align });

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        const els = Array.from(
          panel.current?.querySelectorAll<HTMLElement>(
            "[role=menuitem]:not([disabled])",
          ) ?? [],
        );
        const i = els.indexOf(document.activeElement as HTMLElement);
        els[
          (i + (e.key === "ArrowDown" ? 1 : -1) + els.length) % els.length
        ]?.focus();
      }
    };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    panel.current?.querySelector<HTMLElement>("[role=menuitem]")?.focus();
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open, panel]);

  return (
    <div ref={root} className={cn("inline-block", className)}>
      <span
        onClick={() => { if (!open) update(); setOpen((o) => !o); }}
        aria-haspopup="menu"
        aria-expanded={open}
        className="inline-flex cursor-pointer"
      >
        {trigger}
      </span>
      <FloatPortal
        open={open}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        role="menu"
        className={cn(
          "fixed z-50 min-w-44 rounded-overlay border-line border-border bg-popover p-1 text-sm text-popover-foreground shadow-overlay [backdrop-filter:var(--surface-filter)]",
          "animate-fade-up [animation-duration:150ms]",
        )}
      >
        {items.map((it, i) => {
            if (it.type === "separator")
              return <hr key={i} className="my-1 border-border" />;
            if (it.type === "label")
              return (
                <p
                  key={i}
                  className="px-2 py-1 text-[11px] text-muted-foreground"
                >
                  {it.label}
                </p>
              );
            return (
              <button
                key={i}
                type="button"
                role="menuitem"
                disabled={it.disabled}
                onClick={() => {
                  it.onSelect?.();
                  setOpen(false);
                }}
                className={cn(
                  "flex w-full cursor-pointer items-center justify-between gap-6 rounded-md px-2 py-1.5 text-start outline-none transition-colors",
                  "hover:bg-accent focus:bg-accent disabled:cursor-not-allowed disabled:opacity-50",
                  it.danger ? "text-destructive" : "text-foreground/90",
                )}
              >
                <span className="flex items-center gap-2">
                  {it.icon && <it.icon className="size-4" />}
                  {it.label}
                </span>
                {it.shortcut && (
                  <kbd className="  text-[10px] text-muted-foreground">
                    {it.shortcut}
                  </kbd>
                )}
              </button>
            );
          })}
      </FloatPortal>
    </div>
  );
}

import * as React from "react";
