export interface TooltipProps {
  content: React.ReactNode;
  side?: "top" | "bottom";
  children: React.ReactNode;
  className?: string;
}

/**
 * راهنمای ابزار. CSS-only: shows on hover and keyboard focus, no JS,
 * no positioning library. For rich or delayed tooltips use Popover.
 */
export function Tooltip({ content, side = "top", children, className }: TooltipProps) {
  const id = React.useId();
  return (
    <span className={cn("group/tt relative inline-flex", className)}>
      <span aria-describedby={id} className="inline-flex">{children}</span>
      <span
        id={id}
        role="tooltip"
        className={cn(
          "pointer-events-none absolute left-1/2 z-30 w-max max-w-56 -translate-x-1/2 rounded-control bg-foreground px-2.5 py-1 text-xs text-background opacity-0 shadow transition-opacity duration-150",
          "group-hover/tt:opacity-100 group-focus-within/tt:opacity-100",
          side === "top" ? "bottom-full mb-2" : "top-full mt-2",
        )}
      >
        {content}
        <span className={cn("absolute left-1/2 size-2 -translate-x-1/2 rotate-45 bg-foreground", side === "top" ? "-bottom-1" : "-top-1")} />
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

export interface SheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: React.ReactNode;
  /** "start" slides in from the right in RTL (the natural side for Persian). */
  side?: "start" | "end" | "bottom";
  children: React.ReactNode;
  className?: string;
}

/**
 * Panel spring ≈ Animate UI `{ type: "spring", stiffness: 150, damping: 22 }`.
 * Overlay fade ≈ Animate UI `{ duration: 0.2, ease: "easeInOut" }`.
 */
const PANEL_MS = 480;
const PANEL_EASE = "cubic-bezier(0.32, 0.72, 0, 1)";
const OVERLAY_MS = 200;

function panelHidden(side: NonNullable<SheetProps["side"]>) {
  if (side === "bottom") return "translate-y-full opacity-0";
  if (side === "start") return "ltr:-translate-x-full rtl:translate-x-full opacity-0";
  return "ltr:translate-x-full rtl:-translate-x-full opacity-0";
}

/** کشو. A side panel for filters, carts and mobile navigation. */
export function Sheet({
  open,
  onOpenChange,
  title,
  side = "start",
  children,
  className,
}: SheetProps) {
  const titleId = React.useId();
  const [mounted, setMounted] = React.useState(false);
  const [present, setPresent] = React.useState(open);
  const [shown, setShown] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  React.useEffect(() => {
    if (open) {
      setPresent(true);
      const id = requestAnimationFrame(() => {
        requestAnimationFrame(() => setShown(true));
      });
      return () => cancelAnimationFrame(id);
    }
    setShown(false);
    const t = window.setTimeout(() => setPresent(false), PANEL_MS);
    return () => window.clearTimeout(t);
  }, [open]);

  React.useEffect(() => {
    if (!present) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onOpenChange(false);
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [present, onOpenChange]);

  if (!mounted || !present) return null;

  return createPortal(
    <div className="fixed inset-0 z-50" role="presentation">
      <div
        aria-hidden
        onClick={() => onOpenChange(false)}
        className={cn(
          "absolute inset-0 bg-black/50 transition-[opacity,filter] ease-in-out",
          shown ? "opacity-100 blur-0" : "opacity-0 blur-sm",
        )}
        style={{ transitionDuration: `${OVERLAY_MS}ms` }}
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        className={cn(
          "absolute flex flex-col bg-popover text-popover-foreground shadow-2xl will-change-transform",
          "transition-[transform,opacity]",
          side === "start" && "inset-y-0 start-0 w-full max-w-sm border-e border-border",
          side === "end" && "inset-y-0 end-0 w-full max-w-sm border-s border-border",
          side === "bottom" && "inset-x-0 bottom-0 max-h-[85vh] rounded-t-2xl border-t border-border",
          shown ? "translate-x-0 translate-y-0 opacity-100" : panelHidden(side),
          className,
        )}
        style={{
          transitionDuration: `${PANEL_MS}ms`,
          transitionTimingFunction: PANEL_EASE,
        }}
      >
        <div className="flex items-center justify-between border-b border-border px-4 py-3">
          {title && (
            <h2 id={titleId} className="text-sm font-semibold">
              {title}
            </h2>
          )}
          <button
            type="button"
            aria-label="بستن"
            onClick={() => onOpenChange(false)}
            className="ms-auto flex size-8 cursor-pointer items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            <X className="size-4" />
          </button>
        </div>
        <div className="flex flex-1 flex-col overflow-auto p-4">{children}</div>
      </div>
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

type Ctx = {
  value: string;
  setValue: (v: string) => void;
  variant: "segmented" | "underline";
  id: string;
};
const TabsCtx = React.createContext<Ctx | null>(null);

export interface TabsProps {
  value?: string;
  defaultValue: string;
  onValueChange?: (value: string) => void;
  variant?: "segmented" | "underline";
  className?: string;
  children: React.ReactNode;
}

/** تب‌ها. In RTL the first tab is on the right; ArrowLeft moves to the next tab. */
export function Tabs({ value, defaultValue, onValueChange, variant = "segmented", className, children }: TabsProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const id = React.useId();
  const v = value ?? internal;
  const setValue = (next: string) => {
    if (value === undefined) setInternal(next);
    onValueChange?.(next);
  };
  return (
    <TabsCtx.Provider value={{ value: v, setValue, variant, id }}>
      <div className={className}>{children}</div>
    </TabsCtx.Provider>
  );
}

export function TabsList({
  className,
  children,
  "aria-label": label,
}: {
  className?: string;
  children: React.ReactNode;
  "aria-label"?: string;
}) {
  const ctx = React.useContext(TabsCtx)!;
  const list = React.useRef<HTMLDivElement>(null);
  const [pill, setPill] = React.useState<{ x: number; w: number } | null>(null);

  const measure = React.useCallback(() => {
    if (ctx.variant !== "segmented") {
      setPill(null);
      return;
    }
    const root = list.current;
    const el = root?.querySelector<HTMLElement>('[aria-selected="true"]');
    if (!root || !el) return setPill(null);
    setPill({ x: el.offsetLeft, w: el.offsetWidth });
  }, [ctx.variant, ctx.value]);

  React.useLayoutEffect(measure, [measure, children]);
  React.useEffect(() => {
    const root = list.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    return () => ro.disconnect();
  }, [measure]);

  return (
    <div
      ref={list}
      role="tablist"
      aria-label={label}
      onKeyDown={(e) => {
        const tabs = Array.from(e.currentTarget.querySelectorAll<HTMLElement>("[role=tab]"));
        const i = tabs.indexOf(document.activeElement as HTMLElement);
        const dir = e.key === "ArrowLeft" ? 1 : e.key === "ArrowRight" ? -1 : 0;
        if (!dir || i < 0) return;
        e.preventDefault();
        const next = tabs[(i + dir + tabs.length) % tabs.length];
        next.focus();
        next.click();
      }}
      className={cn(
        "relative isolate",
        ctx.variant === "segmented"
          ? "inline-flex rounded-[calc(var(--shape-control)+2px)] border-line border-border bg-muted p-0.5"
          : "flex gap-1 border-b border-border",
        className,
      )}
    >
      {ctx.variant === "segmented" && pill ? (
        <span
          aria-hidden
          className="absolute inset-y-0.5 -z-10 rounded-control bg-background shadow-sm ring-1 ring-border transition-[transform,width] duration-(--motion) ease-motion"
          style={{ width: pill.w, left: 0, transform: `translateX(${pill.x}px)` }}
        />
      ) : null}
      {children}
    </div>
  );
}

export function TabsTrigger({
  value,
  className,
  children,
}: {
  value: string;
  className?: string;
  children: React.ReactNode;
}) {
  const ctx = React.useContext(TabsCtx)!;
  const active = ctx.value === value;
  return (
    <button
      type="button"
      role="tab"
      id={`${ctx.id}-tab-${value}`}
      aria-selected={active}
      aria-controls={`${ctx.id}-panel-${value}`}
      tabIndex={active ? 0 : -1}
      onClick={() => ctx.setValue(value)}
      className={cn(
        "relative z-10 cursor-pointer text-sm transition-colors duration-(--motion) ease-motion focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
        ctx.variant === "segmented"
          ? cn(
              "rounded-control px-3 py-1.5",
              active ? "font-semibold text-foreground" : "text-muted-foreground hover:text-foreground",
            )
          : cn(
              "-mb-px border-b-2 px-3 py-2",
              active
                ? "border-foreground font-semibold text-foreground"
                : "border-transparent text-muted-foreground hover:text-foreground",
            ),
        className,
      )}
    >
      {children}
    </button>
  );
}

export function TabsContent({
  value,
  className,
  children,
}: {
  value: string;
  className?: string;
  children: React.ReactNode;
}) {
  const ctx = React.useContext(TabsCtx)!;
  if (ctx.value !== value) return null;
  return (
    <div
      role="tabpanel"
      id={`${ctx.id}-panel-${value}`}
      aria-labelledby={`${ctx.id}-tab-${value}`}
      className={cn("mt-3", className)}
    >
      {children}
    </div>
  );
}

import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface PaginationProps {
  page: number;
  total: number;
  onChange: (page: number) => void;
  /** Pages shown around the current one. */
  siblings?: number;
  size?: "sm" | "md";
  className?: string;
}

function range(page: number, total: number, siblings: number): (number | "…")[] {
  const pages = new Set<number>([1, total]);
  for (let p = page - siblings; p <= page + siblings; p++) if (p >= 1 && p <= total) pages.add(p);
  const sorted = Array.from(pages).sort((a, b) => a - b);
  const out: (number | "…")[] = [];
  sorted.forEach((p, i) => {
    if (i > 0 && p - sorted[i - 1] > 1) out.push("…");
    out.push(p);
  });
  return out;
}

/** صفحه‌بندی. «قبلی» points right and «بعدی» points left, as reading order demands. */
export function Pagination({ page, total, onChange, siblings = 1, size = "md", className }: PaginationProps) {
  const btn = cn(size === "sm" ? "size-8 text-xs" : "size-9 text-sm", "flex cursor-pointer items-center justify-center rounded-md border border-border text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40");
  return (
    <nav aria-label="صفحه‌بندی" className={cn("flex items-center gap-1", className)}>
      <button type="button" aria-label="صفحه‌ی قبل" disabled={page <= 1} onClick={() => onChange(page - 1)} className={btn}>
        <ChevronRight className="size-4" />
      </button>
      {range(page, total, siblings).map((p, i) =>
        p === "…" ? (
          <span key={`e${i}`} className="px-1 text-muted-foreground">…</span>
        ) : (
          <button
            key={p}
            type="button"
            aria-current={p === page ? "page" : undefined}
            onClick={() => onChange(p)}
            className={cn(btn, p === page && "border-primary bg-primary font-semibold text-primary-foreground hover:bg-primary hover:text-primary-foreground")}
          >
            {fa(p)}
          </button>
        ),
      )}
      <button type="button" aria-label="صفحه‌ی بعد" disabled={page >= total} onClick={() => onChange(page + 1)} className={btn}>
        <ChevronLeft className="size-4" />
      </button>
    </nav>
  );
}

import { ChevronLeft } from "lucide-react";
import { cn } from "@/lib/utils";

export interface Crumb { label: React.ReactNode; href?: string }

/** مسیر. Separators point left; the last item is the current page. */
export function Breadcrumb({ items, className }: { items: Crumb[]; className?: string }) {
  return (
    <nav aria-label="مسیر" className={className}>
      <ol className="flex flex-wrap items-center gap-1.5 text-sm">
        {items.map((c, i) => {
          const last = i === items.length - 1;
          return (
            <li key={i} className="flex items-center gap-1.5">
              {c.href && !last ? (
                <a href={c.href} className="text-muted-foreground transition-colors hover:text-foreground">{c.label}</a>
              ) : (
                <span aria-current={last ? "page" : undefined} className={cn(last ? "font-medium text-foreground" : "text-muted-foreground")}>{c.label}</span>
              )}
              {!last && <ChevronLeft className="size-3.5 text-muted-foreground/60" aria-hidden />}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

import { Check } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface StepperProps {
  steps: { label: React.ReactNode; description?: React.ReactNode }[];
  /** Zero-based index of the current step. */
  current: number;
  orientation?: "horizontal" | "vertical";
  className?: string;
}

/** مراحل. Completed steps get a check, the current one a ring; flows right-to-left. */
export function Stepper({ steps, current, orientation = "horizontal", className }: StepperProps) {
  const horizontal = orientation === "horizontal";
  return (
    <ol className={cn(horizontal ? "flex items-start" : "flex flex-col gap-5", className)} aria-label="مراحل">
      {steps.map((s, i) => {
        const done = i < current;
        const active = i === current;
        const last = i === steps.length - 1;
        const circle = (
          <span
            className={cn(
              "flex size-7 shrink-0 items-center justify-center rounded-full text-xs font-semibold transition-colors",
              done && "bg-primary text-primary-foreground",
              active && "border-2 border-primary text-foreground",
              !done && !active && "border border-border text-muted-foreground",
            )}
          >
            {done ? <Check className="size-3.5" /> : fa(i + 1)}
          </span>
        );
        const text = (
          <div>
            <p className={cn("text-sm leading-5", active ? "font-semibold" : done ? "" : "text-muted-foreground")}>{s.label}</p>
            {s.description && <p className="text-xs text-muted-foreground">{s.description}</p>}
          </div>
        );
        if (!horizontal) {
          return (
            <li key={i} className="relative flex items-start gap-3" aria-current={active ? "step" : undefined}>
              {!last && <span className={cn("absolute start-3.5 top-8 h-[calc(100%-0.5rem)] w-px", done ? "bg-primary" : "bg-border")} />}
              {circle}
              {text}
            </li>
          );
        }
        return (
          <li key={i} className={cn(last ? "shrink-0" : "flex-1")} aria-current={active ? "step" : undefined}>
            <div className="flex items-center">
              {circle}
              {!last && <span className={cn("mx-2 h-px flex-1", done ? "bg-primary" : "bg-border")} />}
            </div>
            <div className="mt-2 pe-2">{text}</div>
          </li>
        );
      })}
    </ol>
  );
}

