import * as React from "react";
import { cn, faNumber } from "@/lib/utils";
import { JALALI_WEEKDAYS_SHORT, formatJalali, jalaliWeekday } from "@/lib/jalali";

export type Point = { label: string; value: number };

/** Labels for the last `n` days as Jalali day+month («۲۰ شهریور»). */
export function jalaliDayLabels(n: number, end = new Date()): string[] {
  return Array.from({ length: n }, (_, i) => formatJalali(new Date(end.getTime() - (n - 1 - i) * 864e5), { year: false }));
}

/** Saturday-first weekday labels («ش» … «ج») for the last 7 days ending today. */
export function jalaliWeekLabels(end = new Date()): string[] {
  return Array.from({ length: 7 }, (_, i) => JALALI_WEEKDAYS_SHORT[jalaliWeekday(new Date(end.getTime() - (6 - i) * 864e5))]);
}

/** Compact Persian tick: ۱۲٫۵ م / ۸۰۰ هزار / ۹۵۰ */
export function compactFa(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1e9) return `${faNumber(+(n / 1e9).toFixed(1))} میلیارد`;
  if (abs >= 1e6) return `${faNumber(+(n / 1e6).toFixed(1))} میلیون`;
  if (abs >= 1e3) return `${faNumber(Math.round(n / 1e3))} هزار`;
  return faNumber(n);
}

function ticks(max: number, count = 4) {
  const step = Math.pow(10, Math.floor(Math.log10(max || 1)));
  const nice = [1, 2, 2.5, 5, 10].map((m) => m * step).find((s) => max / s <= count) ?? step;
  const top = Math.ceil(max / nice) * nice;
  return { top, values: Array.from({ length: Math.round(top / nice) + 1 }, (_, i) => i * nice) };
}

interface ChartProps {
  data: Point[];
  height?: number;
  format?: (n: number) => string;
  className?: string;
  /** Index to emphasise (e.g. today). */
  highlight?: number;
}

/**
 * نمودار میله‌ای. Pure SVG, RTL by construction: the first point is on the right,
 * the value axis sits on the right edge, ticks are Persian and compact.
 */
export function BarChart({ data, height = 180, format = compactFa, className, highlight }: ChartProps) {
  const [hover, setHover] = React.useState<number | null>(null);
  const W = 600, H = height, padR = 56, padL = 8, padT = 12, padB = 26;
  const { top, values } = ticks(Math.max(...data.map((d) => d.value), 1));
  const plotW = W - padL - padR, plotH = H - padT - padB;
  const slot = plotW / data.length;
  const y = (v: number) => padT + plotH - (v / top) * plotH;
  const x = (i: number) => W - padR - (i + 1) * slot; // right-to-left
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className={cn("w-full", className)} role="img" aria-label="نمودار میله‌ای">
      {values.map((v) => (
        <g key={v}>
          <line x1={padL} x2={W - padR} y1={y(v)} y2={y(v)} stroke="var(--border)" />
          <text x={W - padR + 6} y={y(v) + 3} fontSize="10" fill="var(--muted-foreground)" textAnchor="start">{format(v)}</text>
        </g>
      ))}
      {data.map((d, i) => {
        const bw = slot * 0.6, bx = x(i) + (slot - bw) / 2, by = y(d.value);
        const active = hover === i || highlight === i;
        return (
          <g key={i} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
            <rect x={x(i)} y={padT} width={slot} height={plotH} fill="transparent" />
            <rect x={bx} y={by} width={bw} height={padT + plotH - by} rx="4" fill={active ? "var(--primary)" : "var(--foreground)"} opacity={active ? 1 : 0.22} className="transition-opacity" />
            <text x={bx + bw / 2} y={H - 8} fontSize="11" fill="var(--muted-foreground)" textAnchor="middle">{d.label}</text>
            {hover === i && (
              <g>
                <rect x={bx + bw / 2 - 40} y={Math.max(0, by - 26)} width="80" height="20" rx="6" fill="var(--popover)" stroke="var(--border)" />
                <text x={bx + bw / 2} y={Math.max(0, by - 26) + 13} fontSize="10" fill="var(--foreground)" textAnchor="middle">{faNumber(d.value)}</text>
              </g>
            )}
          </g>
        );
      })}
    </svg>
  );
}

/** نمودار خطی با ناحیه. Same RTL geometry; smooth path with a soft fill. */
export function LineChart({ data, height = 180, format = compactFa, className }: ChartProps) {
  const [hover, setHover] = React.useState<number | null>(null);
  const W = 600, H = height, padR = 56, padL = 8, padT = 12, padB = 26;
  const { top, values } = ticks(Math.max(...data.map((d) => d.value), 1));
  const plotW = W - padL - padR, plotH = H - padT - padB;
  const slot = plotW / Math.max(1, data.length - 1);
  const y = (v: number) => padT + plotH - (v / top) * plotH;
  const x = (i: number) => W - padR - i * slot;
  const pts = data.map((d, i) => [x(i), y(d.value)] as const);
  const path = pts.map(([px, py], i) => {
    if (i === 0) return `M ${px} ${py}`;
    const [qx, qy] = pts[i - 1];
    const cx = (qx + px) / 2;
    return `C ${cx} ${qy}, ${cx} ${py}, ${px} ${py}`;
  }).join(" ");
  const area = `${path} L ${x(data.length - 1)} ${padT + plotH} L ${x(0)} ${padT + plotH} Z`;
  const gid = React.useId();
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className={cn("w-full", className)} role="img" aria-label="نمودار خطی">
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="var(--brand)" stopOpacity="0.35" />
          <stop offset="1" stopColor="var(--brand)" stopOpacity="0" />
        </linearGradient>
      </defs>
      {values.map((v) => (
        <g key={v}>
          <line x1={padL} x2={W - padR} y1={y(v)} y2={y(v)} stroke="var(--border)" />
          <text x={W - padR + 6} y={y(v) + 3} fontSize="10" fill="var(--muted-foreground)" textAnchor="start">{format(v)}</text>
        </g>
      ))}
      <path d={area} fill={`url(#${gid})`} />
      <path d={path} fill="none" stroke="var(--brand)" strokeWidth="2" strokeLinecap="round" />
      {pts.map(([px, py], i) => (
        <g key={i} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
          <rect x={px - slot / 2} y={padT} width={slot} height={plotH} fill="transparent" />
          <circle cx={px} cy={py} r={hover === i ? 5 : 3} fill="var(--background)" stroke="var(--brand)" strokeWidth="2" />
          <text x={px} y={H - 8} fontSize="11" fill="var(--muted-foreground)" textAnchor="middle">{data[i].label}</text>
          {hover === i && (
            <g>
              <rect x={px - 44} y={Math.max(0, py - 30)} width="88" height="20" rx="6" fill="var(--popover)" stroke="var(--border)" />
              <text x={px} y={Math.max(0, py - 30) + 13} fontSize="10" fill="var(--foreground)" textAnchor="middle">{faNumber(data[i].value)}</text>
            </g>
          )}
        </g>
      ))}
    </svg>
  );
}

/** اسپارک‌لاین. Tiny trend line for stat cards; no axes. */
export function Sparkline({ data, className, positive }: { data: number[]; className?: string; positive?: boolean }) {
  const W = 120, H = 32, max = Math.max(...data), min = Math.min(...data);
  const pts = data.map((v, i) => `${W - (i / (data.length - 1)) * W},${H - ((v - min) / (max - min || 1)) * (H - 4) - 2}`).join(" ");
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className={cn("h-8 w-28", className)} aria-hidden>
      <polyline points={pts} fill="none" stroke={positive === false ? "var(--destructive)" : "var(--success)"} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export interface PopoverProps {
  trigger: React.ReactNode;
  children: React.ReactNode;
  side?: "top" | "bottom";
  align?: "start" | "center" | "end";
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/**
 * پاپ‌آور. A small panel anchored to its trigger; closes on outside click and Escape.
 * Rendered into `document.body` so a parent with overflow hidden cannot clip it.
 * `align="start"` hugs the trigger's inline-start (right in RTL).
 */
export function Popover({ trigger, children, side = "bottom", align = "start", open, onOpenChange, className }: PopoverProps) {
  const [internal, setInternal] = React.useState(false);
  const isOpen = open ?? internal;
  const set = (v: boolean) => { if (open === undefined) setInternal(v); onOpenChange?.(v); };
  const root = React.useRef<HTMLDivElement>(null);
  const id = React.useId();
  const { mounted, style, theme, panel, update } = useFloat(isOpen, root, { side, align });

  React.useEffect(() => {
    if (!isOpen) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) set(false); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && set(false);
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  return (
    <div ref={root} className="inline-block">
      <span
        onClick={() => { if (!isOpen) update(); set(!isOpen); }}
        aria-haspopup="dialog"
        aria-expanded={isOpen}
        aria-controls={id}
        className="inline-flex cursor-pointer"
      >
        {trigger}
      </span>
      <FloatPortal
        open={isOpen}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        id={id}
        role="dialog"
        className={cn(
          "fixed z-50 min-w-56 rounded-overlay border-line border-border bg-popover p-4 text-sm text-popover-foreground shadow-overlay [backdrop-filter:var(--surface-filter)]",
          "animate-fade-up [animation-duration:180ms]",
          className,
        )}
      >
        {children}
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, themeOf } from "@/lib/float";
import type { MenuItem } from "./dropdown-menu";

/** منوی راست‌کلیک. Opens at the pointer; Escape, outside click and scroll close it. Rendered into `document.body` so overflow hidden cannot clip it. */
export function ContextMenu({ items, children, className }: { items: MenuItem[]; children: React.ReactNode; className?: string }) {
  const [pos, setPos] = React.useState<{ x: number; y: number } | null>(null);
  const [mounted, setMounted] = React.useState(false);
  const [theme, setTheme] = React.useState<string | undefined>();
  const root = React.useRef<HTMLDivElement>(null);
  const panel = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => setMounted(true), []);

  React.useEffect(() => {
    if (!pos) return;
    const close = () => setPos(null);
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, panel.current)) close(); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && close();
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    window.addEventListener("scroll", close, true);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); window.removeEventListener("scroll", close, true); };
  }, [pos]);

  return (
    <div
      ref={root}
      className={cn("relative", className)}
      onContextMenu={(e) => {
        e.preventDefault();
        setTheme(themeOf(e.currentTarget));
        setPos({ x: e.clientX, y: e.clientY });
      }}
    >
      {children}
      <FloatPortal
        open={!!pos}
        mounted={mounted}
        style={pos ? { top: pos.y, left: pos.x } : {}}
        theme={theme}
        panelRef={panel}
        role="menu"
        className="fixed z-50 min-w-44 rounded-overlay border-line border-border bg-popover p-1 text-sm text-popover-foreground shadow-overlay [backdrop-filter:var(--surface-filter)] animate-fade-up [animation-duration:120ms]"
      >
        {items.map((it, i) => {
          if (it.type === "separator") return <hr key={i} className="my-1 border-border" />;
          if (it.type === "label") return <p key={i} className="px-2 py-1 text-[11px] text-muted-foreground">{it.label}</p>;
          return (
            <button
              key={i}
              type="button"
              role="menuitem"
              disabled={it.disabled}
              onClick={() => { it.onSelect?.(); setPos(null); }}
              className={cn("flex w-full cursor-pointer items-center justify-between gap-6 rounded-md px-2 py-1.5 text-start transition-colors hover:bg-accent focus:bg-accent disabled:opacity-50", it.danger ? "text-destructive" : "text-foreground/90")}
            >
              <span className="flex items-center gap-2">{it.icon && <it.icon className="size-4" />}{it.label}</span>
              {it.shortcut && <kbd className="font-mono text-[10px] text-muted-foreground">{it.shortcut}</kbd>}
            </button>
          );
        })}
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { FloatPortal, useFloat } from "@/lib/float";

export interface HoverCardProps {
  trigger: React.ReactNode;
  children: React.ReactNode;
  openDelay?: number;
  closeDelay?: number;
  className?: string;
}

/** کارت شناور. Opens after a short hover (or keyboard focus) — for author/profile previews. Rendered into `document.body` so a parent with overflow hidden cannot clip it. */
export function HoverCard({ trigger, children, openDelay = 300, closeDelay = 150, className }: HoverCardProps) {
  const [open, setOpen] = React.useState(false);
  const root = React.useRef<HTMLSpanElement>(null);
  const timer = React.useRef<number | undefined>(undefined);
  const { mounted, style, theme, panel, update } = useFloat(open, root);
  const schedule = (v: boolean, d: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      if (v) update();
      setOpen(v);
    }, d);
  };

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  return (
    <span
      ref={root}
      className="inline-block"
      onMouseEnter={() => schedule(true, openDelay)}
      onMouseLeave={() => schedule(false, closeDelay)}
      onFocus={() => schedule(true, 0)}
      onBlur={() => schedule(false, 0)}
    >
      {trigger}
      <FloatPortal
        open={open}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        onMouseEnter={() => schedule(true, 0)}
        onMouseLeave={() => schedule(false, closeDelay)}
        className={cn("fixed z-50 w-72 rounded-overlay border-line border-border bg-popover p-4 text-sm text-popover-foreground shadow-overlay [backdrop-filter:var(--surface-filter)] animate-fade-up [animation-duration:180ms]", className)}
      >
        {children}
      </FloatPortal>
    </span>
  );
}

"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface CarouselProps {
  children: React.ReactNode[];
  /** Fraction of the viewport each slide takes (1 = one per view, 0.5 = two). */
  slideWidth?: number;
  showDots?: boolean;
  className?: string;
}

/**
 * اسلایدر. Native RTL scroll-snap: the first slide sits at the right and «بعدی» scrolls left.
 * In RTL, scrollLeft counts down from 0 into negatives, so we work with |scrollLeft|.
 */
export function Carousel({ children, slideWidth = 1, showDots = true, className }: CarouselProps) {
  const track = React.useRef<HTMLDivElement>(null);
  const [index, setIndex] = React.useState(0);
  const count = React.Children.count(children);

  const step = () => (track.current ? track.current.clientWidth * slideWidth : 0);

  const onScroll = () => {
    const el = track.current;
    if (!el) return;
    setIndex(Math.min(count - 1, Math.round(Math.abs(el.scrollLeft) / step())));
  };

  const go = (i: number) => {
    const el = track.current;
    if (!el) return;
    const target = Math.max(0, Math.min(count - 1, i));
    el.scrollTo({ left: -target * step(), behavior: "smooth" }); // negative = toward the left in RTL
  };

  const nav = "absolute top-1/2 z-10 flex size-9 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full border border-border bg-background/80 text-foreground shadow backdrop-blur transition-opacity hover:bg-accent disabled:opacity-30";

  return (
    <div className={cn("relative", className)} role="region" aria-roledescription="carousel" aria-label="اسلایدر">
      <div
        ref={track}
        onScroll={onScroll}
        className="flex snap-x snap-mandatory overflow-x-auto scroll-smooth [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {React.Children.map(children, (child, i) => (
          <div className="shrink-0 snap-start px-1.5" style={{ width: `${slideWidth * 100}%` }} role="group" aria-roledescription="slide" aria-label={`${fa(i + 1)} از ${fa(count)}`}>
            {child}
          </div>
        ))}
      </div>
      <button type="button" aria-label="قبلی" onClick={() => go(index - 1)} disabled={index === 0} className={cn(nav, "start-2")}><ChevronRight className="size-4" /></button>
      <button type="button" aria-label="بعدی" onClick={() => go(index + 1)} disabled={index >= count - 1} className={cn(nav, "end-2")}><ChevronLeft className="size-4" /></button>
      {showDots && (
        <div className="mt-3 flex justify-center gap-1.5">
          {Array.from({ length: count }, (_, i) => (
            <button key={i} type="button" aria-label={`اسلاید ${fa(i + 1)}`} aria-current={i === index} onClick={() => go(i)} className={cn("h-1.5 cursor-pointer rounded-full transition-all", i === index ? "w-5 bg-foreground" : "w-1.5 bg-foreground/30 hover:bg-foreground/50")} />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { FloatPortal, useFloat } from "@/lib/float";

export interface AsyncOption { value: string; label: string; hint?: string }

export interface ComboboxAsyncProps {
  /** Fetch options for a query. Use the signal to drop stale requests. */
  loadOptions: (query: string, signal: AbortSignal) => Promise<AsyncOption[]>;
  value?: AsyncOption | null;
  onChange?: (option: AsyncOption | null) => void;
  placeholder?: string;
  minChars?: number;
  debounce?: number;
  emptyText?: string;
  errorText?: string;
  className?: string;
}

/** کمبوباکس آنلاین. Debounced remote search with loading, empty and error states; stale responses are aborted. */
export function ComboboxAsync({ loadOptions, value = null, onChange, placeholder = "جست‌وجو…", minChars = 1, debounce = 250, emptyText = "چیزی پیدا نشد", errorText = "خطا در دریافت نتایج", className }: ComboboxAsyncProps) {
  const [q, setQ] = React.useState(value?.label ?? "");
  const [open, setOpen] = React.useState(false);
  const [items, setItems] = React.useState<AsyncOption[]>([]);
  const [state, setState] = React.useState<"idle" | "loading" | "error">("idle");
  const [index, setIndex] = React.useState(0);
  const listId = React.useId();
  const root = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const listOpen = open && q.trim().length >= minChars;
  const { mounted, style, theme, panel } = useFloat(listOpen, root, { matchWidth: true, gap: 4 });

  React.useEffect(() => {
    if (!open || q.trim().length < minChars) return;
    const ctrl = new AbortController();
    const t = window.setTimeout(async () => {
      setState("loading");
      try {
        const res = await loadOptions(q.trim(), ctrl.signal);
        if (!ctrl.signal.aborted) { setItems(res); setIndex(0); setState("idle"); }
      } catch (e) {
        if (!ctrl.signal.aborted) setState(e instanceof DOMException && e.name === "AbortError" ? "idle" : "error");
      }
    }, debounce);
    return () => { window.clearTimeout(t); ctrl.abort(); };
  }, [q, open, minChars, debounce, loadOptions]);

  function pick(o: AsyncOption) { setQ(o.label); onChange?.(o); setOpen(false); }

  // Keep the keyboard-active option in view (scrolls only when needed).
  React.useEffect(() => {
    if (!listOpen) return;
    listRef.current?.querySelector(`[data-index="${index}"]`)?.scrollIntoView({ block: "nearest" });
  }, [listOpen, index]);

  return (
    <div ref={root} className={cn("relative", className)}>
      <div className="flex h-10 items-center overflow-visible rounded-field border-line-field border-input bg-field shadow-field pe-2 ps-3 transition-colors focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60">
        <input
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          value={q}
          placeholder={placeholder}
          onChange={(e) => { setQ(e.target.value); setOpen(true); if (e.target.value.trim().length < minChars) setItems([]); if (value) onChange?.(null); }}
          onFocus={() => setOpen(true)}
          onBlur={() => window.setTimeout(() => setOpen(false), 120)}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") { e.preventDefault(); setIndex((i) => Math.min(items.length - 1, i + 1)); }
            if (e.key === "ArrowUp") { e.preventDefault(); setIndex((i) => Math.max(0, i - 1)); }
            if (e.key === "Enter" && open && items[index]) { e.preventDefault(); pick(items[index]); }
            if (e.key === "Escape") setOpen(false);
          }}
          className="h-full min-w-0 flex-1 bg-transparent pe-2 text-sm/8 outline-none placeholder:text-muted-foreground/70"
        />
        {state === "loading" ? <Loader2 className="size-4 animate-spin text-muted-foreground" /> : <ChevronDown className={cn("size-4 text-muted-foreground transition-transform", open && "rotate-180")} />}
      </div>
      <FloatPortal open={listOpen} mounted={mounted} style={style} theme={theme} panelRef={panel} className="fixed z-50">
        <ul id={listId} ref={listRef} role="listbox" className="max-h-60 overflow-auto rounded-lg border border-border bg-popover p-1.5 text-sm/8 shadow-lg">
          {state === "error" && <li className="px-2.5 py-2 text-destructive">{errorText}</li>}
          {state === "loading" && items.length === 0 && <li className="px-2.5 py-2 text-muted-foreground">در حال جست‌وجو…</li>}
          {state === "idle" && items.length === 0 && <li className="px-2.5 py-2 text-muted-foreground">{emptyText}</li>}
          {items.map((o, i) => (
            <li
              key={o.value}
              role="option"
              data-index={i}
              aria-selected={o.value === value?.value}
              onMouseDown={(e) => { e.preventDefault(); pick(o); }}
              onMouseEnter={() => setIndex(i)}
              className={cn("flex cursor-pointer items-center justify-between overflow-visible rounded-md px-2.5 py-2", i === index && "bg-accent")}
            >
              <span className="flex min-w-0 items-baseline overflow-visible">
                <span className="pb-[0.2em] pe-[0.45em]">{o.label}</span>
