}

/** Contact chip, silver like the ones on Shetab cards. */
function Chip() {
  const id = React.useId();
  return (
    <svg aria-hidden viewBox="0 0 48 36" className="w-[12cqw]">
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#c7d2e2" />
          <stop offset=".45" stopColor="#f5f8fc" />
          <stop offset="1" stopColor="#8e9fb6" />
        </linearGradient>
      </defs>
      <rect x=".5" y=".5" width="47" height="35" rx="6" fill={`url(#${id})`} stroke="#6b7c93" strokeOpacity=".5" />
      <path d="M16 1v34M32 1v34M1 12h15M1 24h15M32 12h15M32 24h15M16 18h16" stroke="#6b7c93" strokeOpacity=".55" fill="none" />
    </svg>
  );
}

/** «۶۰۳۷ ۹۹•• •••• ۴۴۵۵» keeps the BIN and the last four, like a receipt. */
function cardGroups(digits: string, masked: boolean): string[] {
  const padded = digits.padEnd(16, "•");
  const shown = masked ? padded.slice(0, 6) + "••••••" + padded.slice(12) : padded;
  return fa(shown).match(/.{4}/g) ?? [];
}

export interface BankCardProps {
  /** Card number, Persian or Latin digits, spaces allowed. The bank is read from the first six digits. */
  number: string;
  /** Name printed on the card. */
  holder?: string;
  /** Expiry as printed, e.g. «1404/09». */
  expiry?: string;
  /** IBAN printed above the number, as on most Iranian cards. */
  sheba?: string;
  /** Force a bank by name («ملت», «سامان», …) instead of detecting it. */
  bank?: string;
  /** Your own logo, shown before the bank name. */
  logo?: React.ReactNode;
  /** A full card-face image (e.g. your bank's artwork). Replaces the drawn face. */
  image?: string;
  /** Text color to use with `image`. */
  ink?: string;
  /** Hide the middle six digits. */
  masked?: boolean;
  className?: string;
}

/**
 * A bank card face in the look of each Iranian bank's real card. Sizes itself
 * to its container (ID-1 ratio), and every label scales with the card width.
 */
export function BankCard({ number, holder, expiry, sheba, bank, logo, image, ink, masked = false, className }: BankCardProps) {
  const digits = normalizeCardNumber(number);
  const name = bank ?? cardBank(digits);
  const look = bankCardStyle(name);
  const color = ink ?? look.ink;
  const iban = sheba ? normalizeIban(sheba) : "";

  return (
    <div
      dir="rtl"
      role="img"
      aria-label={`${name ? bankLabel(name) : "کارت بانکی"}، شماره‌ی ${fa(digits)}${holder ? `، به نام ${holder}` : ""}`}
      className={cn("@container relative isolate aspect-[1.586/1] w-full select-none overflow-hidden rounded-[3.7%/5.9%] shadow-lg", className)}
      style={{ background: image ? `center / cover no-repeat url(${JSON.stringify(image)})` : look.background, color }}
    >
      {!image && look.pattern && <div aria-hidden className="absolute inset-0 -z-10" style={{ background: PATTERNS[look.pattern] }} />}
      {!image && look.art && <CardArt art={look.art} />}
      <div aria-hidden className="absolute inset-0 -z-10 bg-[linear-gradient(115deg,transparent_35%,rgb(255_255_255/0.16)_48%,transparent_60%)]" />

      <div
        aria-hidden
        className="absolute inset-0 flex flex-col px-[7cqw] pb-[6cqw] pt-[6.5cqw]"
        style={look.lift && !image ? { textShadow: "0 1px 3px rgb(0 0 0 / 0.45)" } : undefined}
      >
        <div className="flex items-center gap-[2cqw] self-start text-[5.6cqw] font-bold leading-none" style={{ color: image ? color : look.accent, textShadow: "none" }}>
          {logo && <span className="flex size-[8cqw] items-center justify-center [&>*]:max-h-full [&>*]:max-w-full">{logo}</span>}
          {name ? bankLabel(name) : "کارت بانکی"}
        </div>

        <div className="mt-[5cqw] self-end">
          <Chip />
        </div>

        <div className="mt-auto space-y-[2.2cqw]">
          {iban && (
            <p dir="ltr" className="text-[3.3cqw] font-medium leading-none tabular-nums opacity-85">
              {fa(formatIban(iban))}
            </p>
          )}
          <div dir="ltr" className="flex justify-between text-[7.2cqw] font-bold leading-none tabular-nums">
            {cardGroups(digits, masked).map((part, i) => (
              <span key={i}>{part}</span>
            ))}
          </div>
          <div className="flex items-end justify-between gap-[3cqw] text-[3.8cqw] leading-tight">
            <span className="min-w-0 truncate font-bold">{holder || " "}</span>
            {expiry && (
              <span className="shrink-0 text-[3.2cqw]">
                <span className="opacity-75">تاریخ انقضا </span>
                <span dir="ltr" className="font-bold tabular-nums">{fa(expiry)}</span>
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export interface CardToCardProps extends Omit<BankCardProps, "masked" | "className"> {
  /** Amount to pay in toman, shown with its own copy button. */
  amount?: number;
  /** Called with what was copied and its raw Latin value. */
  onCopy?: (field: "card" | "sheba" | "amount", value: string) => void;
  className?: string;
}

type Field = "card" | "sheba" | "amount";

/**
 * «کارت به کارت»: the payee's card in its bank colors, the account holder's
 * name to check against the banking app, and one-tap copy for the number,
 * the IBAN and the amount. Copies Latin digits, which every bank app accepts.
 */
export function CardToCard({ number, holder, expiry, sheba, bank, logo, image, ink, amount, onCopy, className }: CardToCardProps) {
  const [copied, setCopied] = React.useState<Field | null>(null);
  const digits = normalizeCardNumber(number);
  const iban = sheba ? normalizeIban(sheba) : "";

  React.useEffect(() => {
    if (!copied) return;
    const t = setTimeout(() => setCopied(null), 1600);
    return () => clearTimeout(t);
  }, [copied]);

  async function copy(field: Field, value: string) {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(field);
      onCopy?.(field, value);
    } catch {
      // Clipboard can be blocked (insecure origin, iframe policy); the numbers stay selectable.
    }
  }

  const mark = (field: Field) => (copied === field ? <Check className="text-success" /> : <Copy />);

  return (
    <div
      dir="rtl"
      className={cn(
        "w-full max-w-sm space-y-4 rounded-surface border-line border-border bg-card p-4 text-card-foreground shadow-surface [--tw-border-style:var(--line-style)]",
        className,
      )}
    >
      <BankCard number={digits} holder={holder} expiry={expiry} sheba={iban || undefined} bank={bank} logo={logo} image={image} ink={ink} />

      {holder && (
        <p className="flex items-start gap-2 text-xs leading-relaxed text-muted-foreground">
          <ShieldCheck className="mt-0.5 size-4 shrink-0 text-success" />
          <span>
            قبل از تأیید انتقال، چک کنید اپ بانک اسم <b className="font-bold text-foreground">{holder}</b> را نشون بده.
          </span>
        </p>
      )}

      {amount !== undefined && (
        <Row label="مبلغ" value={formatToman(amount)} onCopy={() => copy("amount", String(amount))} mark={mark("amount")} copied={copied === "amount"} />
      )}
      {iban && (
        <Row label="شبا" value={fa(formatIban(iban))} ltr onCopy={() => copy("sheba", iban)} mark={mark("sheba")} copied={copied === "sheba"} />
      )}

      <Button variant="brand" className="w-full" onClick={() => copy("card", digits)} disabled={digits.length !== 16}>
        {mark("card")}
        {copied === "card" ? "شماره‌ی کارت کپی شد" : "کپی شماره‌ی کارت"}
      </Button>
    </div>
  );
}

function Row({ label, value, ltr, onCopy, mark, copied }: { label: string; value: string; ltr?: boolean; onCopy: () => void; mark: React.ReactNode; copied: boolean }) {
  return (
    <div className="flex items-center gap-3 rounded-field border-line border-border bg-muted/40 py-1.5 pe-1.5 ps-3 [--tw-border-style:var(--line-style)]">
      <span className="shrink-0 text-xs text-muted-foreground">{label}</span>
      <span dir={ltr ? "ltr" : undefined} className="min-w-0 flex-1 truncate text-end text-sm font-medium tabular-nums select-all">
        {value}
      </span>
      <Button variant="ghost" size="sm" className="size-8 shrink-0 px-0" onClick={onCopy} aria-label={copied ? `${label} کپی شد` : `کپی ${label}`}>
        {mark}
      </Button>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, en, fa } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";
import { EMPTY_PLATE, PLATE_LETTERS, isPlate, parsePlate, plateLetterFromKey, stringifyPlate, type PlateValue } from "@/lib/persian";

export interface PlateInputProps {
  value?: PlateValue;
  defaultValue?: PlateValue;
  onChange?: (value: PlateValue, complete: boolean) => void;
  /** Limit the picker, e.g. ["ت"] on a taxi form or the private letters only. */
  letters?: string[];
  /** Adds a hidden input carrying «12ب345-11» for plain HTML forms. */
  name?: string;
  disabled?: boolean;
  className?: string;
  id?: string;
}

type Segment = "left" | "middle" | "region";
const LENGTH: Record<Segment, number> = { left: 2, middle: 3, region: 2 };
const COLS = 7;

/** Typing into a box that is already full starts it over with the new digit, wherever the caret was. */
function typedInto(old: string, next: string, max: number) {
  if (next.length <= max || old.length < max) return next.slice(0, max);
  let i = 0;
  while (i < old.length && old[i] === next[i]) i++;
  return next.slice(i, i + next.length - old.length).slice(0, max);
}

/**
 * پلاک خودرو. The plate itself is LTR like the metal one (۱۲ ب ۳۴۵ | ایران ۱۱),
 * the letter box opens an RTL picker with every legal letter and what it
 * means, and typing flows through the four boxes as if it were one field.
 * Persian or Latin digits, Arabic ي/ك, and «ا» for «الف» are all accepted.
 */
export function PlateInput({ value, defaultValue = EMPTY_PLATE, onChange, letters, name, disabled, className, id }: PlateInputProps) {
  const [internal, setInternal] = React.useState<PlateValue>(defaultValue);
  const v = value ?? internal;
  const options = React.useMemo(() => (letters ? PLATE_LETTERS.filter((l) => letters.includes(l.letter)) : PLATE_LETTERS), [letters]);
  const allowed = React.useMemo(() => new Set(options.map((l) => l.letter)), [options]);

  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(0);
  const [hovered, setHovered] = React.useState<string | null>(null);
  const root = React.useRef<HTMLDivElement>(null);
  const refs = React.useRef<Record<Segment | "letter", HTMLInputElement | HTMLButtonElement | null>>({ left: null, letter: null, middle: null, region: null });
  const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const listId = React.useId();
  const { mounted, style, theme, panel } = useFloat(open, root);

  function commit(next: PlateValue) {
    if (value === undefined) setInternal(next);
    onChange?.(next, isPlate(next));
  }
  const focus = (k: Segment | "letter") => refs.current[k]?.focus();

  function chooseLetter(letter: string) {
    commit({ ...v, letter });
    setOpen(false);
    focus("middle");
  }

  function openList() {
    setActive(Math.max(0, options.findIndex((l) => l.letter === v.letter)));
    setHovered(null);
    setOpen(true);
  }

  /* ----- digit boxes ----- */
  function onDigits(key: Segment, raw: string, next: Segment | "letter" | null) {
    const text = en(raw);
    // A whole plate pasted into the first box fills all four.
    if (key === "left" && /[^\d]/.test(text)) {
      const p = parsePlate(text);
      if (p.letter || p.middle) {
        commit(p);
        focus(p.region.length === 2 ? "region" : p.middle.length === 3 ? "region" : p.letter ? "middle" : "letter");
        return;
      }
    }
    const d = typedInto(v[key], text.replace(/\D/g, ""), LENGTH[key]);
    commit({ ...v, [key]: d });
    if (d.length === LENGTH[key] && next) focus(next);
  }

  function onDigitsKey(e: React.KeyboardEvent<HTMLInputElement>, key: Segment, prev: Segment | "letter" | null) {
    if (e.key === "Backspace" && !v[key] && prev) {
      e.preventDefault();
      focus(prev);
    }
  }

  /* ----- letter box ----- */
  function onLetterKey(e: React.KeyboardEvent<HTMLButtonElement>) {
    if (e.key === "Backspace") {
      e.preventDefault();
      if (v.letter) commit({ ...v, letter: "" });
      else focus("left");
      return;
    }
    if (e.key === "Enter" || e.key === " " || e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      openList();
      return;
    }
    if (e.key.length === 1) {
      const letter = plateLetterFromKey(e.key);
      if (letter && allowed.has(letter)) {
        e.preventDefault();
        chooseLetter(letter);
      }
    }
  }

  /* ----- listbox ----- */
  function onListKey(e: React.KeyboardEvent<HTMLDivElement>) {
    const n = options.length;
    const move = (i: number) => {
      e.preventDefault();
      setActive(((i % n) + n) % n);
    };
    switch (e.key) {
      // The picker is RTL: «left» is the next letter, «right» the previous one.
      case "ArrowLeft": return move(active + 1);
      case "ArrowRight": return move(active - 1);
      case "ArrowDown": return move(active + COLS);
      case "ArrowUp": return move(active - COLS);
      case "Home": return move(0);
      case "End": return move(n - 1);
      case "Enter":
      case " ":
        e.preventDefault();
        return chooseLetter(options[active].letter);
      case "Escape":
        e.preventDefault();
        setOpen(false);
        return focus("letter");
      case "Tab":
        return setOpen(false);
      default: {
        const letter = e.key.length === 1 ? plateLetterFromKey(e.key) : null;
        if (letter && allowed.has(letter)) {
          e.preventDefault();
          chooseLetter(letter);
        }
      }
    }
  }

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  React.useEffect(() => {
    if (open) optionRefs.current[active]?.focus();
  }, [open, active]);

  const digitBox = "h-full min-w-0 bg-transparent text-center text-lg font-bold tabular-nums text-foreground outline-none placeholder:text-muted-foreground/40 disabled:cursor-not-allowed";
  const complete = isPlate(v);
  const described = (hovered ?? options[active]?.letter) || v.letter;
  const describedLabel = options.find((l) => l.letter === described)?.label;

  return (
    <div ref={root} className={cn("relative inline-block", className)}>
      <div
        role="group"
        aria-label="پلاک خودرو"
        dir="ltr"
        className={cn(
          "flex h-12 items-stretch overflow-hidden rounded-field border-line-field border-input bg-field shadow-field transition-colors focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60",
          disabled && "opacity-50",
        )}
      >
        <div aria-hidden className="flex w-7 shrink-0 flex-col items-center justify-center gap-0.5 bg-foreground text-background">
          <span className="text-[7px] font-bold leading-none">I.R.</span>
          <span className="text-[7px] font-bold leading-none">IRAN</span>
        </div>

        <input
          ref={(el) => { refs.current.left = el; }}
          id={id}
          aria-label="دو رقم اول"
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={fa(v.left)}
          placeholder="۱۲"
          onChange={(e) => onDigits("left", e.target.value, "letter")}
          onKeyDown={(e) => onDigitsKey(e, "left", null)}
          onFocus={(e) => e.target.select()}
          className={cn(digitBox, "w-10")}
        />

        <button
          ref={(el) => { refs.current.letter = el; }}
          type="button"
          aria-label={v.letter ? `حرف پلاک: ${v.letter}` : "حرف پلاک"}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? listId : undefined}
          disabled={disabled}
          onClick={() => (open ? setOpen(false) : openList())}
          onKeyDown={onLetterKey}
          className={cn(
            "flex min-w-10 shrink-0 cursor-pointer items-center justify-center px-1 text-lg font-bold transition-colors hover:bg-accent focus:bg-accent focus:outline-none disabled:cursor-not-allowed",
            !v.letter && "text-muted-foreground/40",
            open && "bg-accent",
          )}
        >
          {v.letter || "ب"}
        </button>

        <input
          ref={(el) => { refs.current.middle = el; }}
          aria-label="سه رقم"
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={fa(v.middle)}
          placeholder="۳۴۵"
          onChange={(e) => onDigits("middle", e.target.value, "region")}
          onKeyDown={(e) => onDigitsKey(e, "middle", "letter")}
          onFocus={(e) => e.target.select()}
          className={cn(digitBox, "w-14")}
        />

        <div className="flex w-11 shrink-0 flex-col items-center border-s border-input">
          <span aria-hidden className="pt-0.5 text-[9px] leading-none text-muted-foreground">ایران</span>
          <input
            ref={(el) => { refs.current.region = el; }}
            aria-label="کد شهر"
            inputMode="numeric"
            autoComplete="off"
            disabled={disabled}
            value={fa(v.region)}
            placeholder="۱۱"
            onChange={(e) => onDigits("region", e.target.value, null)}
            onKeyDown={(e) => onDigitsKey(e, "region", "middle")}
            onFocus={(e) => e.target.select()}
            className={cn(digitBox, "w-full flex-1 text-base")}
          />
        </div>
      </div>

      {name && <input type="hidden" name={name} value={complete ? stringifyPlate(v) : ""} />}

      <FloatPortal
        open={open}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        id={listId}
        role="listbox"
        aria-label="حرف پلاک"
        dir="rtl"
        onKeyDown={onListKey}
        onMouseLeave={() => setHovered(null)}
        className="fixed z-50 w-[252px] rounded-xl border border-border bg-popover p-2 text-popover-foreground shadow-[0_20px_50px_-20px_oklch(0_0_0/80%)] animate-fade-up [animation-duration:180ms]"
      >
          <div className="grid grid-cols-7 gap-1">
            {options.map((l, i) => {
              const selected = l.letter === v.letter;
              return (
                <button
                  key={l.letter}
                  ref={(el) => { optionRefs.current[i] = el; }}
                  id={`${listId}-${i}`}
                  type="button"
                  role="option"
                  aria-selected={selected}
                  aria-label={`${l.letter}، ${l.label}`}
                  tabIndex={i === active ? 0 : -1}
                  onClick={() => chooseLetter(l.letter)}
                  onMouseEnter={() => setHovered(l.letter)}
                  onFocus={() => setActive(i)}
                  className={cn(
                    "flex h-8 cursor-pointer items-center justify-center rounded-md text-sm font-semibold transition-colors focus:outline-none",
                    selected ? "bg-primary text-primary-foreground" : "hover:bg-accent focus:bg-accent",
                    l.label !== "شخصی" && !selected && "text-muted-foreground",
                  )}
                >
                  {l.letter}
                </button>
              );
            })}
          </div>
          <p className="mt-2 border-t border-border pt-1.5 text-[11px] text-muted-foreground" aria-hidden>
            {describedLabel ? <>{described}<span className="mx-1">·</span>{describedLabel}</> : "حرف پلاک را انتخاب کنید"}
          </p>
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { PROVINCES, citiesOf } from "@/lib/iran-divisions";
import { Combobox } from "@/components/ui/combobox";

export type AddressValue = { province: string; city: string };

export interface AddressPickerProps {
  value?: AddressValue;
  defaultValue?: AddressValue;
  /** `complete` is true once both a province and one of its cities are picked. */
  onChange?: (value: AddressValue, complete: boolean) => void;
  /** Limit to the provinces you deliver to, e.g. ["تهران", "البرز"]. */
  provinces?: string[];
  /** Hidden inputs `${name}-province` and `${name}-city` for a plain <form>. */
  name?: string;
  /** Prefix for the two input ids, so labels and errors can point at them. */
  id?: string;
  labels?: { province?: string; city?: string };
  /** Shows the «required» error under an empty field (pass true after submit). */
  invalid?: boolean;
  disabled?: boolean;
  /** "row" puts the fields side by side from the sm breakpoint; "stack" always stacks them. */
  layout?: "row" | "stack";
  className?: string;
}

const EMPTY: AddressValue = { province: "", city: "" };

/**
 * استان و شهر: two linked comboboxes over all 31 provinces. The city list
 * follows the province, picking a new province clears the city, and both
 * fields only accept names from the list (Arabic ي/ك typing still matches).
 */
export function AddressPicker({
  value,
  defaultValue = EMPTY,
  onChange,
  provinces,
  name,
  id,
  labels,
  invalid,
  disabled,
  layout = "row",
  className,
}: AddressPickerProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const current = value ?? internal;
  const auto = React.useId();
  const base = id ?? auto;

  const provinceOptions = React.useMemo(
    () => (provinces ? PROVINCES.filter((p) => provinces.includes(p.name)) : PROVINCES).map((p) => p.name),
    [provinces],
  );
  const cityOptions = React.useMemo(() => citiesOf(current.province), [current.province]);

  function set(next: AddressValue) {
    if (value === undefined) setInternal(next);
    onChange?.(next, !!next.province && citiesOf(next.province).includes(next.city));
  }

  const provinceMissing = invalid && !current.province;
  const cityMissing = invalid && !!current.province && !current.city;

  return (
    <div className={cn("grid grid-cols-1 gap-4", layout === "row" && "sm:grid-cols-2", className)}>
      <div className="flex flex-col gap-1.5">
        <label htmlFor={`${base}-province`} className="text-sm font-medium text-foreground/90">
          {labels?.province ?? "استان"}
        </label>
        <Combobox
          id={`${base}-province`}
          name={name && `${name}-province`}
          strict
          disabled={disabled}
          options={provinceOptions}
          value={current.province}
          onChange={(province) => province !== current.province && set({ province, city: "" })}
          placeholder="انتخاب استان"
          emptyText="استانی با این اسم نیست"
          aria-invalid={provinceMissing || undefined}
          aria-describedby={provinceMissing ? `${base}-province-error` : undefined}
        />
        {provinceMissing && (
          <p id={`${base}-province-error`} className="text-xs text-destructive">
            استان را انتخاب کنید.
          </p>
        )}
      </div>
      <div className="flex flex-col gap-1.5">
        <label htmlFor={`${base}-city`} className="text-sm font-medium text-foreground/90">
          {labels?.city ?? "شهر"}
        </label>
        <Combobox
          id={`${base}-city`}
          name={name && `${name}-city`}
          strict
          disabled={disabled || !current.province}
          options={cityOptions}
          value={current.city}
          onChange={(city) => set({ province: current.province, city })}
          placeholder={current.province ? `شهرهای ${current.province}` : "اول استان را انتخاب کنید"}
          emptyText="این شهر در فهرست نیست"
          aria-invalid={cityMissing || undefined}
          aria-describedby={cityMissing ? `${base}-city-error` : undefined}
        />
        {cityMissing && (
          <p id={`${base}-city-error`} className="text-xs text-destructive">
            شهر را انتخاب کنید.
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Mailbox } from "lucide-react";
import { cn } from "@/lib/utils";
import { formatPostalCode, isPostalCode, normalizePostalCode } from "@/lib/persian";

export interface PostalCodeInputProps {
  value?: string;
  defaultValue?: string;
  /** Receives up to 10 raw Latin digits and validity. */
  onChange?: (digits: string, valid: boolean) => void;
  /** Hidden input with the 10 digits, for a plain <form>. */
  name?: string;
  id?: string;
  autoFocus?: boolean;
  disabled?: boolean;
  /** Show the error even before blur (pass true after a submit attempt). */
  invalid?: boolean;
  className?: string;
}

/**
 * کد پستی. Persian digits in the «۸۱۶۳۸-۴۷۳۵۱» grouping printed on bills,
 * pasting with or without the dash works, and the length error waits for blur.
 */
export function PostalCodeInput({ value, defaultValue = "", onChange, name, id, autoFocus, disabled, invalid, className }: PostalCodeInputProps) {
  const [internal, setInternal] = React.useState(() => normalizePostalCode(defaultValue));
  const [touched, setTouched] = React.useState(false);
  const auto = React.useId();
  const fieldId = id ?? auto;
  const digits = normalizePostalCode(value ?? internal);
  const valid = isPostalCode(digits);
  const showError = !valid && digits.length > 0 && (touched || digits.length === 10 || invalid);
  const missing = invalid && digits.length === 0;

  function set(next: string) {
    const d = normalizePostalCode(next);
    if (value === undefined) setInternal(d);
    onChange?.(d, isPostalCode(d));
  }

  return (
    <div className={cn("space-y-1.5", className)}>
      <div
        className={cn(
          "flex h-10 items-center gap-2 rounded-field border-line-field bg-field shadow-field px-3 transition-colors focus-within:ring-2 focus-within:ring-ring/60",
          showError || missing ? "border-destructive/60" : "border-input",
          disabled && "opacity-50",
        )}
        dir="ltr"
      >
        <Mailbox className="size-4 shrink-0 text-muted-foreground" />
        <input
          id={fieldId}
          inputMode="numeric"
          autoComplete="postal-code"
          autoFocus={autoFocus}
          disabled={disabled}
          value={formatPostalCode(digits)}
          onChange={(e) => set(e.target.value)}
          onBlur={() => setTouched(true)}
          onPaste={(e) => {
            e.preventDefault();
            set(e.clipboardData.getData("text"));
          }}
          placeholder="۱۲۳۴۵-۶۷۸۹۰"
          maxLength={11}
          className="h-full min-w-0 flex-1 bg-transparent text-sm tabular-nums tracking-wide outline-none placeholder:text-muted-foreground/50 disabled:cursor-not-allowed"
          aria-invalid={showError || missing ? true : undefined}
          aria-describedby={`${fieldId}-hint`}
        />
        {valid && <Check className="size-4 shrink-0 text-success" />}
      </div>
      {name && <input type="hidden" name={name} value={valid ? digits : ""} />}
      <p id={`${fieldId}-hint`} className="text-[11px] text-muted-foreground" aria-live="polite">
        {showError ? (
          <span className="text-destructive">{digits.length < 10 ? "کد پستی باید ۱۰ رقم باشد." : "کد پستی معتبر نیست."}</span>
        ) : missing ? (
          <span className="text-destructive">کد پستی را وارد کنید.</span>
        ) : (
          "ده رقم، بدون خط تیره هم قبول میشه"
        )}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { CalendarRange, ChevronLeft, ChevronRight, X } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";
import { JALALI_MONTHS, JALALI_WEEKDAYS_SHORT, formatJalali, jalaliMonthLength, jalaliWeekday, toGregorian, toJalali } from "@/lib/jalali";

export type DateRange = { from: Date | null; to: Date | null };

export interface RangeCalendarProps {
  value?: DateRange;
  defaultValue?: DateRange;
  onChange?: (range: DateRange) => void;
  min?: Date;
  max?: Date;
  /** Two months side by side (they stack under 640px). */
  months?: 1 | 2;
  /** Grey out Fridays (default true). */
  markWeekend?: boolean;
  compact?: boolean;
  /** No border, background or padding — for embedding in your own panel. */
  bare?: boolean;
  className?: string;
}

const EMPTY: DateRange = { from: null, to: null };
const day = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const sameDay = (a: Date | null | undefined, b: Date) => !!a && day(a).getTime() === day(b).getTime();
const ordered = (a: Date, b: Date): [Date, Date] => (a <= b ? [a, b] : [b, a]);

/** Days in the range, both ends included. */
export function rangeLength(range: DateRange) {
  if (!range.from || !range.to) return 0;
  const [a, b] = ordered(day(range.from), day(range.to));
  return Math.round((b.getTime() - a.getTime()) / 864e5) + 1;
}

/** «۱۲ تا ۲۵ مهر ۱۴۰۵»، «۲۸ شهریور تا ۳ مهر ۱۴۰۵»، «۲۵ اسفند ۱۴۰۴ تا ۵ فروردین ۱۴۰۵». */
export function formatJalaliRange(range: DateRange) {
  if (!range.from) return "";
  if (!range.to) return `از ${formatJalali(range.from)}`;
  const [a, b] = ordered(range.from, range.to);
  const ja = toJalali(a);
  const jb = toJalali(b);
  if (ja.jy === jb.jy && ja.jm === jb.jm) return `${fa(ja.jd)} تا ${fa(jb.jd)} ${JALALI_MONTHS[jb.jm - 1]} ${fa(jb.jy)}`;
  if (ja.jy === jb.jy) return `${fa(ja.jd)} ${JALALI_MONTHS[ja.jm - 1]} تا ${fa(jb.jd)} ${JALALI_MONTHS[jb.jm - 1]} ${fa(jb.jy)}`;
  return `${formatJalali(a)} تا ${formatJalali(b)}`;
}

/**
 * تقویم بازه‌ای شمسی. First click sets the start, second the end (clicking an
 * earlier day swaps them), a third click starts over. The band between the two
 * ends runs right-to-left with the week, so it is rounded on logical sides.
 */
export function RangeCalendar({ value, defaultValue = EMPTY, onChange, min, max, months = 1, markWeekend = true, compact, bare, className }: RangeCalendarProps) {
  const [internal, setInternal] = React.useState<DateRange>(defaultValue);
  const range = value ?? internal;
  const [hover, setHover] = React.useState<Date | null>(null);
  const today = React.useMemo(() => day(new Date()), []);
  const initial = toJalali(range.from ?? today);
  const [view, setView] = React.useState({ jy: initial.jy, jm: initial.jm });

  function commit(next: DateRange) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  function pick(date: Date) {
    if (!range.from || range.to) return commit({ from: date, to: null });
    const [from, to] = ordered(range.from, date);
    commit({ from, to });
  }

  function move(delta: number) {
    setView((v) => {
      let jm = v.jm + delta;
      let jy = v.jy;
      if (jm < 1) { jm = 12; jy -= 1; }
      if (jm > 12) { jm = 1; jy += 1; }
      return { jy, jm };
    });
  }

  // Effective ends: the committed range, or the start plus the hovered day while choosing the end.
  const [start, end] = React.useMemo<[Date | null, Date | null]>(() => {
    if (range.from && range.to) return ordered(range.from, range.to);
    if (range.from && hover) return ordered(range.from, hover);
    return [range.from, null];
  }, [range.from, range.to, hover]);
  const previewing = !!range.from && !range.to && !!hover;

  const views = Array.from({ length: months }, (_, i) => {
    let jm = view.jm + i;
    let jy = view.jy;
    if (jm > 12) { jm -= 12; jy += 1; }
    return { jy, jm };
  });

  const nav = "flex size-7 cursor-pointer items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground";
  const length = rangeLength(range);

  return (
    <div className={cn("inline-flex flex-col", !bare && "rounded-xl border border-border bg-card p-3", className)}>
      <div className={cn("flex flex-col gap-4 sm:flex-row", compact ? "sm:gap-3" : "sm:gap-5")} onMouseLeave={() => setHover(null)}>
        {views.map((m, mi) => {
          const first = toGregorian(m.jy, m.jm, 1);
          const offset = jalaliWeekday(first);
          const days = jalaliMonthLength(m.jy, m.jm);
          const cells = Array.from({ length: offset + days }, (_, i) => (i < offset ? null : i - offset + 1));
          return (
            <div key={`${m.jy}-${m.jm}`} className={compact ? "w-[220px]" : "w-[260px]"}>
              <div className="flex items-center justify-between px-1">
                {mi === 0 ? (
                  <button type="button" aria-label="ماه قبل" onClick={() => move(-1)} className={nav}><ChevronRight className="size-4" /></button>
                ) : <span className="size-7" />}
                <span className={cn("font-semibold", compact ? "text-xs" : "text-sm")}>
                  {JALALI_MONTHS[m.jm - 1]} {fa(m.jy)}
                </span>
                {mi === months - 1 ? (
                  <button type="button" aria-label="ماه بعد" onClick={() => move(1)} className={nav}><ChevronLeft className="size-4" /></button>
                ) : <span className="size-7" />}
              </div>
              <div className={cn("mt-2 grid grid-cols-7 gap-y-0.5 overflow-hidden text-center", compact ? "text-[10px]" : "text-[11px]")} role="grid">
                {JALALI_WEEKDAYS_SHORT.map((d) => (
                  <span key={d} className="py-1 text-muted-foreground/80" aria-hidden>{d}</span>
                ))}
                {cells.map((d, i) => {
                  if (d === null) return <span key={`e${i}`} className={compact ? "h-6" : "h-8"} />;
                  const date = toGregorian(m.jy, m.jm, d);
                  const isStart = sameDay(start, date);
                  const isEnd = sameDay(end, date);
                  const between = !!start && !!end && date > start && date < end;
                  const banded = between || (isStart && !!end) || (isEnd && !!start);
                  const isToday = sameDay(today, date);
                  const fri = i % 7 === 6;
                  const disabled = (min && date < day(min)) || (max && date > day(max));
                  return (
                    <div
                      key={d}
                      className={cn(
                        compact ? "h-6" : "h-8",
                        banded && (previewing ? "bg-accent/50" : "bg-accent"),
                        isStart && "rounded-s-md",
                        isEnd && "rounded-e-md",
                      )}
                    >
                      <button
                        type="button"
                        role="gridcell"
                        aria-selected={isStart || isEnd}
                        aria-label={`${fa(d)} ${JALALI_MONTHS[m.jm - 1]}`}
                        disabled={!!disabled}
                        onClick={() => pick(date)}
                        onMouseEnter={() => setHover(date)}
                        onFocus={() => setHover(date)}
                        className={cn(
                          "flex size-full min-w-0 items-center justify-center rounded-md leading-none whitespace-nowrap tabular-nums transition-colors",
                          (isStart || isEnd) && !previewing && "bg-primary font-semibold text-primary-foreground",
                          (isStart || isEnd) && previewing && "bg-primary/80 font-semibold text-primary-foreground",
                          between && "rounded-none",
                          !isStart && !isEnd && isToday && "ring-1 ring-inset ring-foreground/40",
                          !isStart && !isEnd && markWeekend && fri && "text-muted-foreground/60",
                          !isStart && !isEnd && !disabled && "cursor-pointer hover:bg-accent",
                          disabled && "cursor-not-allowed opacity-30",
                        )}
                      >
                        {fa(d)}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
      <p className="mt-2 min-h-4 px-1 text-[11px] text-muted-foreground" aria-live="polite">
        {length ? `${fa(length)} روز` : range.from ? "روز پایان را انتخاب کنید" : "روز شروع را انتخاب کنید"}
      </p>
    </div>
  );
}

export type RangePreset = { label: string; range: () => DateRange };

const ago = (n: number) => { const d = day(new Date()); d.setDate(d.getDate() - n); return d; };

/** «امروز»، «۷ روز گذشته»، «۳۰ روز گذشته»، «این ماه». */
export const defaultRangePresets: RangePreset[] = [
  { label: "امروز", range: () => ({ from: ago(0), to: ago(0) }) },
  { label: "۷ روز گذشته", range: () => ({ from: ago(6), to: ago(0) }) },
  { label: "۳۰ روز گذشته", range: () => ({ from: ago(29), to: ago(0) }) },
  { label: "این ماه", range: () => { const { jy, jm } = toJalali(new Date()); return { from: toGregorian(jy, jm, 1), to: ago(0) }; } },
];

export interface DateRangePickerProps extends Omit<RangeCalendarProps, "value" | "onChange" | "className" | "defaultValue"> {
  value?: DateRange;
  defaultValue?: DateRange;
  onChange?: (range: DateRange) => void;
  placeholder?: string;
  clearable?: boolean;
  /** Quick ranges shown above the calendar; pass [] to hide. */
  presets?: RangePreset[];
  className?: string;
}

/** انتخاب بازه‌ی تاریخ: a field that opens the range calendar; closes once both ends are chosen. */
export function DateRangePicker({ value, defaultValue = EMPTY, onChange, placeholder = "انتخاب بازه", clearable = true, presets = defaultRangePresets, months = 2, className, ...cal }: DateRangePickerProps) {
  const [internal, setInternal] = React.useState<DateRange>(defaultValue);
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);
  const range = value ?? internal;
  const { mounted, style, theme, panel } = useFloat(open, ref);

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, ref.current, panel.current)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open, panel]);

  function set(r: DateRange, close = false) {
    if (value === undefined) setInternal(r);
    onChange?.(r);
    if (close) setOpen(false);
  }

  return (
    <div ref={ref} className={cn("relative", className)}>
      <button
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className={cn(
          "flex h-10 w-full cursor-pointer items-center justify-between gap-2 rounded-field border-line-field border-input bg-field shadow-field px-3 text-sm transition-colors",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
        )}
      >
        <span className={cn("flex min-w-0 items-center gap-2", !range.from && "text-muted-foreground/70")}>
          <CalendarRange className="size-4 shrink-0 text-muted-foreground" />
          <span className="truncate">{formatJalaliRange(range) || placeholder}</span>
        </span>
        {clearable && range.from && (
          <span role="button" aria-label="پاک کردن" onClick={(e) => { e.stopPropagation(); set(EMPTY); }} className="rounded p-0.5 text-muted-foreground hover:text-foreground">
            <X className="size-3.5" />
          </span>
        )}
      </button>
      <FloatPortal open={open} mounted={mounted} style={style} theme={theme} panelRef={panel} role="dialog" className="fixed z-50 rounded-xl border border-border bg-card p-3 shadow-xl">
          {presets.length > 0 && (
            <div className="mb-3 flex flex-wrap gap-1.5">
              {presets.map((p) => (
                <button
                  key={p.label}
                  type="button"
                  onClick={() => set(p.range(), true)}
                  className="cursor-pointer rounded-full border border-border px-2.5 py-0.5 text-[11px] text-muted-foreground transition-colors hover:border-foreground/30 hover:text-foreground"
                >
                  {p.label}
                </button>
              ))}
            </div>
          )}
          <RangeCalendar {...cal} bare months={months} value={range} onChange={(r) => set(r, !!(r.from && r.to))} />
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { Clock, X } from "lucide-react";
import { cn, en, fa } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export interface TimePickerProps {
  /** «HH:mm» with Latin digits, e.g. "14:30". null when empty. */
  value?: string | null;
  defaultValue?: string | null;
  onChange?: (value: string | null) => void;
  /** Minute step of the picker column; typing accepts any minute. */
  step?: 1 | 5 | 10 | 15 | 30;
  /** Earliest / latest allowed time, «HH:mm». */
  min?: string;
  max?: string;
  clearable?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
}

const pad = (n: number | string) => String(n).padStart(2, "0");
const toMinutes = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const parseTime = (t: string | null | undefined) => (t && /^\d{1,2}:\d{2}$/.test(t) ? { h: pad(t.split(":")[0]), m: t.split(":")[1] } : { h: "", m: "" });
/** «14:30» when both segments are complete, otherwise null. */
const segValue = (s: { h: string; m: string }) => (s.h.length === 2 && s.m.length === 2 ? `${s.h}:${s.m}` : null);
/** Typing into a full segment starts it over with the new digit, wherever the caret was. */
function typedInto(old: string, next: string) {
  if (next.length <= 2 || old.length < 2) return next.slice(0, 2);
  let i = 0;
  while (i < old.length && old[i] === next[i]) i++;
  return next.slice(i, i + next.length - old.length).slice(0, 2);
}

/** «۱۴:۳۰» — Persian digits, 24-hour clock, for showing a stored «14:30». */
export function formatTime(value: string | null | undefined) {
  if (!value) return "";
  const { h, m } = parseTime(value);
  return h ? fa(`${h}:${m}`) : "";
}

/**
 * انتخاب ساعت. Two typed segments on a 24-hour clock (Iran does not use
 * AM/PM), Persian digits in and out, ↑/↓ to step, and a dropdown with hour
 * and minute columns for the mouse. The field is LTR because clock time is
 * read hours-then-minutes even inside Persian text.
 */
export function TimePicker({ value, defaultValue = null, onChange, step = 5, min, max, clearable = true, disabled, className, id }: TimePickerProps) {
  const [internal, setInternal] = React.useState<string | null>(defaultValue);
  const current = value === undefined ? internal : value;
  const [seg, setSeg] = React.useState(() => parseTime(current));
  const [open, setOpen] = React.useState(false);
  const root = React.useRef<HTMLDivElement>(null);
  const hourRef = React.useRef<HTMLInputElement>(null);
  const minuteRef = React.useRef<HTMLInputElement>(null);
  const hourCol = React.useRef<HTMLDivElement>(null);
  const minuteCol = React.useRef<HTMLDivElement>(null);
  const listId = React.useId();
  const { mounted, style, theme, panel } = useFloat(open, root);

  // When the value changes from outside (and is not what the segments already spell), reset the segments.
  const [prev, setPrev] = React.useState(current);
  if (current !== prev) {
    setPrev(current);
    if (current !== segValue(seg)) setSeg(parseTime(current));
  }

  const inRange = (t: string) => (!min || toMinutes(t) >= toMinutes(min)) && (!max || toMinutes(t) <= toMinutes(max));
  const invalid = !!current && !inRange(current);

  function commit(next: string | null) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  /** The value is «HH:mm» only while both segments are complete; anything partial reports null. */
  function setSegments(h: string, m: string) {
    setSeg({ h, m });
    const next = segValue({ h, m });
    if (next !== current) commit(next);
  }

  /** Types into a segment the way a native time input does: a high first digit pads itself. */
  function typeInto(kind: "h" | "m", raw: string) {
    const d = typedInto(seg[kind], en(raw).replace(/\D/g, ""));
    const limit = kind === "h" ? 23 : 59;
    const firstMax = kind === "h" ? 2 : 5;
    let out = d;
    let done = false;
    if (d.length === 1 && Number(d) > firstMax) { out = pad(d); done = true; }
    if (d.length === 2) { out = pad(Math.min(Number(d), limit)); done = true; }
    if (kind === "h") { setSegments(out, seg.m); if (done) minuteRef.current?.focus(); }
    else setSegments(seg.h, out);
  }

  function nudge(kind: "h" | "m", delta: number) {
    if (kind === "h") setSegments(pad((((Number(seg.h || 0) + delta) % 24) + 24) % 24), seg.m || "00");
    else setSegments(seg.h || "00", pad((((Number(seg.m || 0) + delta) % 60) + 60) % 60));
  }

  function onSegKey(e: React.KeyboardEvent<HTMLInputElement>, kind: "h" | "m") {
    if (e.key === "ArrowUp") { e.preventDefault(); nudge(kind, kind === "h" ? 1 : step); }
    else if (e.key === "ArrowDown") { e.preventDefault(); nudge(kind, kind === "h" ? -1 : -step); }
    else if (e.key === "Backspace" && kind === "m" && !seg.m) { e.preventDefault(); hourRef.current?.focus(); }
    else if (e.key === "Backspace" && kind === "h" && !seg.h && seg.m) { e.preventDefault(); setSegments("", ""); }
    else if (e.key === ":" || e.key === "ArrowRight") { if (kind === "h") { e.preventDefault(); minuteRef.current?.focus(); } }
    else if (e.key === "ArrowLeft" && kind === "m") { e.preventDefault(); hourRef.current?.focus(); }
  }

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    const scrollTo = (col: HTMLDivElement | null) => col?.querySelector<HTMLElement>("[aria-selected=true]")?.scrollIntoView({ block: "center" });
    scrollTo(hourCol.current);
    scrollTo(minuteCol.current);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open]);

  const hours = Array.from({ length: 24 }, (_, i) => pad(i));
  const minutes = Array.from({ length: Math.ceil(60 / step) }, (_, i) => pad(i * step));
  const segClass = "w-7 bg-transparent text-center text-sm tabular-nums outline-none placeholder:text-muted-foreground/50 disabled:cursor-not-allowed";
  const optionClass = "flex h-8 w-full cursor-pointer items-center justify-center rounded-md text-sm tabular-nums transition-colors hover:bg-accent disabled:cursor-not-allowed disabled:opacity-30 aria-selected:bg-primary aria-selected:text-primary-foreground aria-selected:font-semibold";

  return (
    <div ref={root} className={cn("relative", className)}>
      <div
        role="group"
        aria-label="ساعت"
        dir="ltr"
        className={cn(
          "flex h-10 items-center gap-1 rounded-field border-line-field bg-field shadow-field px-3 transition-colors focus-within:ring-2 focus-within:ring-ring/60",
          invalid ? "border-destructive/60" : "border-input",
          disabled && "opacity-50",
        )}
      >
        <button
          type="button"
          aria-label="باز کردن انتخاب ساعت"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? listId : undefined}
          disabled={disabled}
          onClick={() => setOpen((o) => !o)}
          className="me-1 flex cursor-pointer items-center text-muted-foreground transition-colors hover:text-foreground disabled:cursor-not-allowed"
        >
          <Clock className="size-4" />
        </button>
        <input
          ref={hourRef}
          id={id}
          aria-label="ساعت"
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={fa(seg.h)}
          placeholder="۰۰"
          onChange={(e) => typeInto("h", e.target.value)}
          onKeyDown={(e) => onSegKey(e, "h")}
          onFocus={(e) => e.target.select()}
          onBlur={() => seg.h.length === 1 && setSegments(pad(seg.h), seg.m)}
          className={segClass}
          aria-invalid={invalid ? true : undefined}
        />
        <span className="text-sm text-muted-foreground">:</span>
        <input
          ref={minuteRef}
          aria-label="دقیقه"
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={fa(seg.m)}
          placeholder="۰۰"
          onChange={(e) => typeInto("m", e.target.value)}
          onKeyDown={(e) => onSegKey(e, "m")}
          onFocus={(e) => e.target.select()}
          onBlur={() => seg.m.length === 1 && setSegments(seg.h, pad(seg.m))}
          className={segClass}
          aria-invalid={invalid ? true : undefined}
        />
        <span className="flex-1" />
        {clearable && current && !disabled && (
          <button type="button" aria-label="پاک کردن" onClick={() => setSegments("", "")} className="cursor-pointer rounded p-0.5 text-muted-foreground hover:text-foreground">
            <X className="size-3.5" />
          </button>
        )}
      </div>

      {(min || max) && (
        <p className={cn("mt-1.5 text-[11px]", invalid ? "text-destructive" : "text-muted-foreground")}>
          {min && max ? `از ${formatTime(min)} تا ${formatTime(max)}` : min ? `از ${formatTime(min)} به بعد` : `تا ${formatTime(max)}`}
        </p>
      )}

      <FloatPortal
        open={open}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        id={listId}
        role="dialog"
        aria-label="انتخاب ساعت"
        dir="ltr"
        className="fixed z-50 w-40 rounded-xl border border-border bg-popover p-2 text-popover-foreground shadow-[0_20px_50px_-20px_oklch(0_0_0/80%)] animate-fade-up [animation-duration:180ms]"
      >
          <div className="grid grid-cols-2 gap-2">
            {(
              [
                ["h", "ساعت", hours, hourCol],
                ["m", "دقیقه", minutes, minuteCol],
              ] as const
            ).map(([kind, label, items, ref]) => (
              <div key={kind}>
                <p className="mb-1 text-center text-[11px] text-muted-foreground">{label}</p>
                <div ref={ref} role="listbox" aria-label={label} className="max-h-48 space-y-0.5 overflow-y-auto pe-0.5 [scrollbar-width:thin]">
                  {items.map((it) => {
                    const candidate = kind === "h" ? `${it}:${seg.m || "00"}` : `${seg.h || "00"}:${it}`;
                    const selected = kind === "h" ? seg.h === it : seg.m === it;
                    return (
                      <button
                        key={it}
                        type="button"
                        role="option"
                        aria-selected={selected}
                        disabled={!inRange(candidate)}
                        onClick={() => {
                          if (kind === "h") setSegments(it, seg.m || "00");
                          else { setSegments(seg.h || "00", it); setOpen(false); }
                        }}
                        className={optionClass}
                      >
                        {fa(it)}
                      </button>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
          <div className="mt-2 flex items-center justify-between border-t border-border pt-2" dir="rtl">
            <button
              type="button"
              onClick={() => {
                const now = new Date();
                const m = Math.round(now.getMinutes() / step) * step;
                setSegments(pad((now.getHours() + Math.floor(m / 60)) % 24), pad(m % 60));
                setOpen(false);
              }}
              className="cursor-pointer rounded-md px-2 py-1 text-[11px] text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            >
              الان
            </button>
            <button type="button" onClick={() => setOpen(false)} className="cursor-pointer rounded-md px-2 py-1 text-[11px] font-medium transition-colors hover:bg-accent">
              تأیید
            </button>
          </div>
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, en, fa, faNumber } from "@/lib/utils";
import { amountToWords } from "@/lib/number-to-words";

export interface AmountInputProps {
  value?: number | null;
  defaultValue?: number | null;
  onChange?: (value: number | null) => void;
  /** Unit shown at the end of the field and after the words. */
  unit?: string;
  min?: number;
  max?: number;
  /** Spell the amount out under the field (default true). */
  words?: boolean;
  /** Preset chips that set the value, e.g. [100_000, 500_000, 1_000_000]. */
  quick?: number[];
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  id?: string;
}

/** 100000 → «۱۰۰ هزار», 2500000 → «۲٫۵ میلیون», 1200 → «۱٬۲۰۰». */
export function shortAmount(n: number) {
  if (n >= 1_000_000 && n % 100_000 === 0) return `${fa(String(n / 1_000_000).replace(".", "٫"))} میلیون`;
  if (n >= 1_000 && n % 1_000 === 0) return `${fa(n / 1_000)} هزار`;
  return faNumber(n);
}

/**
 * مبلغ. Thousands separator «٬» and Persian digits while you type, the unit
 * after the number, and the amount spelled out underneath so nobody pays
 * ۱۲٬۵۰۰٬۰۰۰ when they meant ۱٬۲۵۰٬۰۰۰. The value is a plain number.
 */
export function AmountInput({ value, defaultValue = null, onChange, unit = "تومان", min, max, words = true, quick, placeholder = "۰", disabled, className, id }: AmountInputProps) {
  const [internal, setInternal] = React.useState<number | null>(defaultValue);
  const amount = value === undefined ? internal : value;
  const tooLow = amount !== null && min !== undefined && amount < min;
  const tooHigh = amount !== null && max !== undefined && amount > max;
  const invalid = tooLow || tooHigh;

  function set(next: number | null) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  function type(raw: string) {
    const digits = en(raw).replace(/\D/g, "").replace(/^0+(?=\d)/, "").slice(0, 15);
    set(digits ? Number(digits) : null);
  }

  return (
    <div className={cn("space-y-1.5", className)}>
      <div
        className={cn(
          "flex h-10 items-center gap-2 rounded-field border-line-field bg-field shadow-field px-3 transition-colors focus-within:ring-2 focus-within:ring-ring/60",
          invalid ? "border-destructive/60" : "border-input",
          disabled && "opacity-50",
        )}
      >
        <input
          id={id}
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={amount === null ? "" : faNumber(amount)}
          onChange={(e) => type(e.target.value)}
          placeholder={placeholder}
          className="h-full min-w-0 flex-1 bg-transparent text-sm font-medium tabular-nums outline-none placeholder:text-muted-foreground/50 disabled:cursor-not-allowed"
          aria-invalid={invalid ? true : undefined}
          aria-describedby={id ? `${id}-words` : undefined}
        />
        <span className="shrink-0 text-sm text-muted-foreground">{unit}</span>
      </div>
      {(words || invalid) && (
        <p id={id ? `${id}-words` : undefined} className={cn("min-h-4 text-[11px]", invalid ? "text-destructive" : "text-muted-foreground")} aria-live="polite">
          {tooLow ? `حداقل ${faNumber(min!)} ${unit}` : tooHigh ? `حداکثر ${faNumber(max!)} ${unit}` : amount !== null ? amountToWords(amount, unit) : " "}
        </p>
      )}
      {quick && quick.length > 0 && (
        <div className="flex flex-wrap gap-1.5 pt-0.5">
          {quick.map((q) => (
            <button
              key={q}
              type="button"
              disabled={disabled}
              onClick={() => set(q)}
              className={cn(
                "cursor-pointer rounded-full border px-2.5 py-0.5 text-[11px] tabular-nums transition-colors disabled:cursor-not-allowed",
                amount === q ? "border-foreground bg-foreground text-background" : "border-border text-muted-foreground hover:border-foreground/30 hover:text-foreground",
              )}
            >
              {shortAmount(q)}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Loader2, Search, X } from "lucide-react";
import { cn } from "@/lib/utils";

export interface SearchInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "defaultValue" | "onChange" | "size" | "type"> {
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Called after typing pauses for `debounce` ms, on Enter, and when the field is cleared. */
  onSearch?: (value: string) => void;
  debounce?: number;
  /** Swaps the magnifier for a spinner while results load. */
  loading?: boolean;
  size?: "sm" | "md";
  /** Shortcut hint at the inline-end, e.g. "⌘K". Hidden once there is a value. */
  shortcut?: string;
}

/**
 * جست‌وجو. Magnifier at the inline-start (right in RTL), a clear button
 * at the end once there is text; Escape clears, Enter searches at once.
 */
export function SearchInput({
  value,
  defaultValue = "",
  onChange,
  onSearch,
  debounce = 300,
  loading,
  size = "md",
  shortcut,
  placeholder = "جست‌وجو…",
  className,
  disabled,
  onKeyDown,
  ...props
}: SearchInputProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const v = value ?? internal;
  const ref = React.useRef<HTMLInputElement>(null);
  const timer = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const set = React.useCallback(
    (next: string, immediate = false) => {
      if (value === undefined) setInternal(next);
      onChange?.(next);
      if (!onSearch) return;
      if (timer.current) clearTimeout(timer.current);
      if (immediate || !next) onSearch(next);
      else timer.current = setTimeout(() => onSearch(next), debounce);
    },
    [value, onChange, onSearch, debounce],
  );

  React.useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

  const sm = size === "sm";

  return (
    <div
      className={cn(
        "flex w-full items-center gap-2 rounded-field border-line-field border-input bg-field shadow-field text-sm transition-colors",
        "focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60",
        sm ? "h-8 px-2.5" : "h-10 px-3",
        disabled && "cursor-not-allowed opacity-50",
        className,
      )}
    >
      {loading ? (
        <Loader2 className="size-4 shrink-0 animate-spin text-muted-foreground" aria-hidden />
      ) : (
        <Search className="size-4 shrink-0 text-muted-foreground" aria-hidden />
      )}
      <input
        ref={ref}
        type="search"
        inputMode="search"
        enterKeyHint="search"
        autoComplete="off"
        value={v}
        placeholder={placeholder}
        disabled={disabled}
        onChange={(e) => set(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") set(v, true);
          if (e.key === "Escape" && v) { e.preventDefault(); set("", true); }
          onKeyDown?.(e);
        }}
        // The native decoration is replaced by our own clear button.
        className="h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 [&::-webkit-search-cancel-button]:appearance-none [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
        {...props}
      />
      {v ? (
        <button
          type="button"
          aria-label="پاک کردن"
          tabIndex={-1}
          disabled={disabled}
          onClick={() => { set("", true); ref.current?.focus(); }}
          className="flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
        >
          <X className="size-3.5" />
        </button>
      ) : shortcut ? (
        <kbd dir="ltr" className="hidden shrink-0 rounded border border-border bg-muted px-1.5 font-mono text-[11px] leading-5 text-muted-foreground sm:inline-block">
          {shortcut}
        </kbd>
      ) : null}
    </div>
  );
}

"use client";

import * as React from "react";
import { X } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface TagsInputProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  placeholder?: string;
  /** Upper limit; a «۳ / ۵» counter appears when set. */
  max?: number;
  /** Characters that commit a tag while typing. Enter always does. */
  separators?: string[];
  /** Normalize or reject a tag before it is added; return null to drop it. */
  validate?: (tag: string) => string | null;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

/**
 * برچسب‌ها. Type and press Enter (or «،») to make a chip; Backspace on an
 * empty field removes the last chip; pasted lists split into chips.
 */
export function TagsInput({
  value,
  defaultValue = [],
  onChange,
  placeholder = "برچسب را بنویسید و Enter بزنید",
  max,
  separators = ["،", ","],
  validate = (t) => t.trim() || null,
  disabled,
  className,
  ...aria
}: TagsInputProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const tags = value ?? internal;
  const [draft, setDraft] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);

  function commit(next: string[]) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  function add(raw: string | string[]) {
    const incoming = (Array.isArray(raw) ? raw : [raw]).map(validate).filter((t): t is string => Boolean(t));
    const merged = [...tags];
    for (const t of incoming) {
      if (max !== undefined && merged.length >= max) break;
      if (!merged.includes(t)) merged.push(t);
    }
    if (merged.length !== tags.length) commit(merged);
    setDraft("");
  }

  function remove(i: number) {
    commit(tags.filter((_, j) => j !== i));
    inputRef.current?.focus();
  }

  const full = max !== undefined && tags.length >= max;
  const splitter = new RegExp(`[${separators.map((s) => s.replace(/[-.*+?^${}()|[\]\\]/g, "\\$&")).join("")}\\n]`);

  return (
    <div className={cn("space-y-1", className)}>
      <div
        role="group"
        aria-label={aria["aria-label"] ?? "برچسب‌ها"}
        onClick={() => inputRef.current?.focus()}
        className={cn(
          "flex min-h-10 w-full cursor-text flex-wrap items-center gap-1.5 rounded-field border-line-field border-input bg-field shadow-field px-2 py-1.5 text-sm transition-colors",
          "focus-within:border-transparent focus-within:ring-2 focus-within:ring-ring/60",
          disabled && "cursor-not-allowed opacity-50",
        )}
      >
        {tags.map((t, i) => (
          <span
            key={t}
            dir="auto"
            className="inline-flex h-6 items-center gap-1 rounded-md bg-secondary ps-2 pe-1 text-xs font-medium text-secondary-foreground"
          >
            {t}
            <button
              type="button"
              aria-label={`حذف ${t}`}
              disabled={disabled}
              onClick={(e) => { e.stopPropagation(); remove(i); }}
              className="flex size-4 cursor-pointer items-center justify-center rounded text-muted-foreground transition-colors hover:bg-foreground/10 hover:text-foreground"
            >
              <X className="size-3" />
            </button>
          </span>
        ))}
        <input
          ref={inputRef}
          value={draft}
          disabled={disabled || full}
          placeholder={tags.length === 0 ? placeholder : full ? "" : undefined}
          onChange={(e) => {
            const s = e.target.value;
            if (splitter.test(s)) add(s.split(splitter));
            else setDraft(s);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") { e.preventDefault(); if (draft) add(draft); }
            else if (e.key === "Backspace" && !draft && tags.length) { e.preventDefault(); remove(tags.length - 1); }
            else if (e.key === "Escape") setDraft("");
          }}
          onBlur={() => { if (draft) add(draft); }}
          onPaste={(e) => {
            const text = e.clipboardData.getData("text");
            if (!splitter.test(text)) return;
            e.preventDefault();
            add(text.split(splitter));
          }}
          className="h-6 min-w-24 flex-1 bg-transparent px-1 outline-none placeholder:text-muted-foreground/70 disabled:cursor-not-allowed"
        />
      </div>
      {max !== undefined && (
        <p className="text-end text-[11px] text-muted-foreground" aria-live="polite">
          {fa(tags.length)} / {fa(max)}
        </p>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown, Search, X } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export type MultiSelectOption = { value: string; label: string; disabled?: boolean };

export interface MultiSelectProps {
  options: MultiSelectOption[];
  value?: string[];
  defaultValue?: string[];
  onChange?: (value: string[]) => void;
  placeholder?: string;
  /** Adds a filter box at the top of the list. */
  searchable?: boolean;
  /** Chips shown in the field before they collapse into «+۳ مورد دیگر». */
  maxVisible?: number;
  /** Upper limit on selections; the rest of the list is disabled once reached. */
  max?: number;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

/**
 * چندانتخابی. A listbox with checkmarks; picked items show as chips in the
 * field. Arrow keys move, Space/Enter toggles, Escape closes, Backspace
 * removes the last chip when the filter is empty.
 */
export function MultiSelect({
  options,
  value,
  defaultValue = [],
  onChange,
  placeholder = "انتخاب کنید…",
  searchable = true,
  maxVisible = 3,
  max,
  emptyText = "چیزی پیدا نشد",
  disabled,
  className,
  ...aria
}: MultiSelectProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const selected = value ?? internal;
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const [index, setIndex] = React.useState(0);
  const root = React.useRef<HTMLDivElement>(null);
  const search = React.useRef<HTMLInputElement>(null);
  const listId = React.useId();
  const { mounted, style, theme, panel, update } = useFloat(open, root, { matchWidth: true, gap: 4 });

  const q = query.trim();
  const filtered = React.useMemo(() => (q ? options.filter((o) => o.label.includes(q)) : options), [options, q]);
  const full = max !== undefined && selected.length >= max;

  function commit(next: string[]) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  function toggle(v: string) {
    if (selected.includes(v)) commit(selected.filter((x) => x !== v));
    else if (!full) commit([...selected, v]);
  }

  function show(next: boolean) {
    if (disabled) return;
    if (next) update();
    setOpen(next);
    setQuery("");
    setIndex(0);
  }

  React.useEffect(() => {
    if (!open) return;
    search.current?.focus();
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open, panel]);

  function onKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Escape") { e.preventDefault(); show(false); return; }
    if (e.key === "ArrowDown") { e.preventDefault(); if (!open) show(true); else setIndex((i) => Math.min(filtered.length - 1, i + 1)); return; }
    if (e.key === "ArrowUp") { e.preventDefault(); setIndex((i) => Math.max(0, i - 1)); return; }
    if ((e.key === "Enter" || (e.key === " " && !q)) && open && filtered[index] && !filtered[index].disabled) { e.preventDefault(); toggle(filtered[index].value); return; }
    if (e.key === "Backspace" && !q && selected.length) { e.preventDefault(); commit(selected.slice(0, -1)); }
  }

  const chips = selected.map((v) => options.find((o) => o.value === v)).filter((o): o is MultiSelectOption => Boolean(o));
  const hidden = Math.max(0, chips.length - maxVisible);

  return (
    <div ref={root} className={cn("relative", className)}>
      <div
        role="combobox"
        tabIndex={disabled ? -1 : 0}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        aria-label={aria["aria-label"]}
        aria-disabled={disabled || undefined}
        onClick={() => show(!open)}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); show(true); } else onKeyDown(e); }}
        className={cn(
          "flex min-h-10 w-full cursor-pointer flex-wrap items-center gap-1.5 rounded-field border-line-field border-input bg-field shadow-field py-1.5 pe-2 ps-2 text-sm transition-colors",
          "focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
          open && "border-transparent ring-2 ring-ring/60",
          disabled && "cursor-not-allowed opacity-50",
        )}
      >
        {chips.length === 0 && <span className="px-1 text-muted-foreground/70">{placeholder}</span>}
        {chips.slice(0, maxVisible).map((o) => (
          <span key={o.value} className="inline-flex h-6 items-center gap-1 rounded-md bg-secondary ps-2 pe-1 text-xs font-medium text-secondary-foreground">
            {o.label}
            <button
              type="button"
              aria-label={`حذف ${o.label}`}
              tabIndex={-1}
              disabled={disabled}
              onClick={(e) => { e.stopPropagation(); toggle(o.value); }}
              className="flex size-4 cursor-pointer items-center justify-center rounded text-muted-foreground transition-colors hover:bg-foreground/10 hover:text-foreground"
            >
              <X className="size-3" />
            </button>
          </span>
        ))}
        {hidden > 0 && <span className="px-1 text-xs text-muted-foreground">+{fa(hidden)} مورد دیگر</span>}
        <ChevronDown className={cn("ms-auto size-4 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} aria-hidden />
      </div>

      <FloatPortal open={open} mounted={mounted} style={style} theme={theme} panelRef={panel} className="fixed z-50">
        <div className="overflow-hidden rounded-lg border border-border bg-popover text-sm shadow-lg">
          {searchable && (
            <div className="flex items-center gap-2 border-b border-border px-2.5">
              <Search className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
              <input
                ref={search}
                value={query}
                placeholder="جست‌وجو…"
                aria-controls={listId}
                onChange={(e) => { setQuery(e.target.value); setIndex(0); }}
                onKeyDown={onKeyDown}
                className="h-9 min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground/70"
              />
            </div>
          )}
          <ul id={listId} role="listbox" aria-multiselectable className="max-h-56 overflow-auto p-1 leading-7">
            {filtered.length === 0 && <li className="px-2.5 py-2 text-muted-foreground">{emptyText}</li>}
            {filtered.map((o, i) => {
              const on = selected.includes(o.value);
              const off = o.disabled || (full && !on);
              return (
                <li
                  key={o.value}
                  role="option"
                  aria-selected={on}
                  aria-disabled={off || undefined}
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => { if (!off) toggle(o.value); }}
                  onMouseEnter={() => setIndex(i)}
                  className={cn(
                    "flex cursor-pointer items-center gap-2.5 rounded-md px-2.5 py-1.5",
                    i === index && "bg-accent",
                    off && "cursor-not-allowed opacity-40",
                  )}
                >
                  <span className={cn("flex size-4 shrink-0 items-center justify-center rounded border transition-colors", on ? "border-primary bg-primary text-primary-foreground" : "border-input")}>
                    {on && <Check className="size-3" />}
                  </span>
                  <span className="flex-1 truncate">{o.label}</span>
                </li>
              );
            })}
          </ul>
          {selected.length > 0 && (
            <div className="flex items-center justify-between border-t border-border px-3 py-1.5 text-xs text-muted-foreground">
              <span>{fa(selected.length)} مورد انتخاب شده{max !== undefined && ` از ${fa(max)}`}</span>
              <button type="button" onMouseDown={(e) => e.preventDefault()} onClick={() => commit([])} className="cursor-pointer hover:text-foreground">
                پاک کردن
              </button>
            </div>
          )}
        </div>
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

type Size = "sm" | "md" | "lg";
type Variant = "default" | "outline";

const sizes: Record<Size, string> = {
  sm: "h-8 min-w-8 px-2 text-xs [&_svg]:size-3.5",
  md: "h-9 min-w-9 px-2.5 text-sm [&_svg]:size-4",
  lg: "h-10 min-w-10 px-3 text-sm [&_svg]:size-4",
};

const base =
  "inline-flex cursor-pointer items-center justify-center gap-2 rounded-control font-medium whitespace-nowrap transition-colors duration-(--motion) ease-motion " +
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 disabled:pointer-events-none disabled:opacity-50";

function toggleClass(on: boolean, variant: Variant, size: Size, sliding: boolean) {
  return cn(
    base,
    sizes[size],
    variant === "outline" && !sliding && "border-line border-input",
    sliding
      ? on
        ? "text-foreground"
        : "text-muted-foreground hover:text-foreground"
      : on
        ? "bg-secondary text-foreground"
        : "text-muted-foreground hover:bg-accent/60 hover:text-foreground",
  );
}

export interface ToggleProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  variant?: Variant;
  size?: Size;
}

/** دکمه‌ی فشاری. A two-state button (aria-pressed), for things like «پررنگ» or «فقط موجود». */
export function Toggle({
  pressed,
  defaultPressed = false,
  onPressedChange,
  variant = "default",
  size = "md",
  className,
  onClick,
  ...props
}: ToggleProps) {
  const [internal, setInternal] = React.useState(defaultPressed);
  const on = pressed ?? internal;
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={(e) => {
        if (pressed === undefined) setInternal(!on);
        onPressedChange?.(!on);
        onClick?.(e);
      }}
      className={cn(toggleClass(on, variant, size, false), className)}
      {...props}
    />
  );
}

export type ToggleGroupItem = {
  value: string;
  label: React.ReactNode;
  "aria-label"?: string;
  disabled?: boolean;
};

export type ToggleGroupProps = {
  items: ToggleGroupItem[];
  variant?: Variant;
  size?: Size;
  className?: string;
  "aria-label"?: string;
} & (
  | { type?: "single"; value?: string; defaultValue?: string; onChange?: (value: string) => void }
  | { type: "multiple"; value?: string[]; defaultValue?: string[]; onChange?: (value: string[]) => void }
);

/**
 * گروه دکمه‌ی فشاری. `single` behaves like a radio row (one may stay off),
 * `multiple` like a checkbox row. Arrow keys move between items in reading order.
 * In single mode a highlight pill slides under the active item.
 */
export function ToggleGroup(props: ToggleGroupProps) {
  const { items, variant = "default", size = "md", className } = props;
  const multiple = props.type === "multiple";
  const [internal, setInternal] = React.useState<string[]>(() => {
    const d = props.defaultValue;
    return d === undefined ? [] : Array.isArray(d) ? d : [d];
  });
  const selected: string[] =
    props.value === undefined
      ? internal
      : Array.isArray(props.value)
        ? props.value
        : props.value
          ? [props.value]
          : [];

  const list = React.useRef<HTMLDivElement>(null);
  const [pill, setPill] = React.useState<{ x: number; w: number } | null>(null);
  const sliding = !multiple;

  function pick(v: string) {
    const next = multiple
      ? selected.includes(v)
        ? selected.filter((x) => x !== v)
        : [...selected, v]
      : selected[0] === v
        ? []
        : [v];
    if (props.value === undefined) setInternal(next);
    if (props.type === "multiple") props.onChange?.(next);
    else props.onChange?.(next[0] ?? "");
  }

  const measure = React.useCallback(() => {
    if (!sliding) {
      setPill(null);
      return;
    }
    const root = list.current;
    const active = selected[0];
    if (!root || !active) return setPill(null);
    const el = root.querySelector<HTMLElement>(`[data-value="${CSS.escape(active)}"]`);
    if (!el) return setPill(null);
    setPill({ x: el.offsetLeft, w: el.offsetWidth });
  }, [sliding, selected]);

  React.useLayoutEffect(measure, [measure, items.length, size, variant]);
  React.useEffect(() => {
    const root = list.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    return () => ro.disconnect();
  }, [measure]);

  return (
    <div
      ref={list}
      role="group"
      aria-label={props["aria-label"]}
      onKeyDown={(e) => {
        const dir = e.key === "ArrowLeft" ? 1 : e.key === "ArrowRight" ? -1 : 0;
        if (!dir) return;
        const buttons = Array.from(
          e.currentTarget.querySelectorAll<HTMLButtonElement>("button:not(:disabled)"),
        );
        const i = buttons.indexOf(document.activeElement as HTMLButtonElement);
        if (i < 0) return;
        e.preventDefault();
        buttons[(i + dir + buttons.length) % buttons.length].focus();
      }}
      className={cn(
        "relative isolate inline-flex items-center",
        sliding ? "gap-0.5 rounded-[calc(var(--shape-control)+2px)] p-0.5" : "gap-1",
        (variant === "outline" || sliding) && "border-line border-input",
        sliding && "bg-muted",
        className,
      )}
    >
      {sliding && pill ? (
        <span
          aria-hidden
          className="absolute inset-y-0.5 -z-10 rounded-control bg-background shadow-sm ring-1 ring-border transition-[transform,width] duration-(--motion) ease-motion"
          style={{ width: pill.w, left: 0, transform: `translateX(${pill.x}px)` }}
        />
      ) : null}
      {items.map((it) => {
        const on = selected.includes(it.value);
        return (
          <button
            key={it.value}
            type="button"
            data-value={it.value}
            aria-pressed={on}
            aria-label={it["aria-label"]}
            disabled={it.disabled}
            onClick={() => pick(it.value)}
            className={cn(toggleClass(on, variant, size, sliding), sliding && "relative z-10 border-0 shadow-none")}
          >
            {it.label}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type SegmentedOption = { value: string; label: React.ReactNode; disabled?: boolean; "aria-label"?: string };

export interface SegmentedControlProps {
  options: SegmentedOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  size?: "sm" | "md";
  /** Stretch to the container and give every segment the same width. */
  fullWidth?: boolean;
  className?: string;
  "aria-label"?: string;
}

/**
 * کنترل بخشی. One pill slides under the chosen segment. The indicator is
 * measured from the DOM, so it lands on the right segment in RTL and LTR alike.
 */
export function SegmentedControl({ options, value, defaultValue, onChange, size = "md", fullWidth, className, ...aria }: SegmentedControlProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "");
  const selected = value ?? internal;
  const list = React.useRef<HTMLDivElement>(null);
  const [pill, setPill] = React.useState<{ x: number; w: number } | null>(null);

  function select(v: string) {
    if (value === undefined) setInternal(v);
    onChange?.(v);
  }

  const measure = React.useCallback(() => {
    const root = list.current;
    const el = root?.querySelector<HTMLElement>(`[data-value="${CSS.escape(selected)}"]`);
    if (!root || !el) return setPill(null);
    setPill({ x: el.offsetLeft, w: el.offsetWidth });
  }, [selected]);

  React.useLayoutEffect(measure, [measure, options.length, size, fullWidth]);
  React.useEffect(() => {
    const root = list.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    return () => ro.disconnect();
  }, [measure]);

  return (
    <div
      ref={list}
      role="radiogroup"
      aria-label={aria["aria-label"]}
      onKeyDown={(e) => {
        const dir = e.key === "ArrowLeft" || e.key === "ArrowDown" ? 1 : e.key === "ArrowRight" || e.key === "ArrowUp" ? -1 : 0;
        if (!dir) return;
        e.preventDefault();
        const enabled = options.filter((o) => !o.disabled);
        const i = enabled.findIndex((o) => o.value === selected);
        const next = enabled[(i + dir + enabled.length) % enabled.length];
        if (!next) return;
        select(next.value);
        list.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(next.value)}"]`)?.focus();
      }}
      className={cn(
        // Equal-width columns; fr tracks in an inline grid grow to the widest label.
        "relative isolate auto-cols-fr grid-flow-col rounded-[calc(var(--shape-control)+2px)] bg-muted p-0.5",
        fullWidth ? "grid w-full" : "inline-grid",
