}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";

export type CountdownUnit = "days" | "hours" | "minutes" | "seconds";

export type CountdownParts = {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  total: number;
};

const DEFAULT_LABELS: Record<CountdownUnit, string> = {
  days: "روز",
  hours: "ساعت",
  minutes: "دقیقه",
  seconds: "ثانیه",
};

const DEFAULT_UNITS: CountdownUnit[] = ["days", "hours", "minutes", "seconds"];

function split(totalSec: number): CountdownParts {
  const total = Math.max(0, totalSec);
  return {
    days: Math.floor(total / 86400),
    hours: Math.floor((total % 86400) / 3600),
    minutes: Math.floor((total % 3600) / 60),
    seconds: total % 60,
    total,
  };
}

/** Tick every second; server and first client paint stay at null so HTML matches. */
export function useCountdown(target: Date | number | string): CountdownParts | null {
  const end = typeof target === "object" ? target.getTime() : new Date(target).getTime();
  const [now, setNow] = React.useState(0);

  React.useEffect(() => {
    setNow(Date.now());
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, []);

  if (!now || Number.isNaN(end)) return null;
  return split(Math.floor((end - now) / 1000));
}

export interface CountdownProps {
  /** End date, ISO string, or timestamp. */
  target: Date | number | string;
  /** Which cells to show, in visual LTR order. */
  units?: CountdownUnit[];
  labels?: Partial<Record<CountdownUnit, string>>;
  /** Pad each number to two digits (۰۰). Days stay unpadded unless true. */
  pad?: boolean;
  size?: "sm" | "md" | "lg";
  /** cards = bordered cells; inline = ۱۲:۳۴:۵۶ with colons. */
  variant?: "cards" | "inline";
  onComplete?: () => void;
  className?: string;
}

const sizeCls = {
  sm: { num: "text-xl", cell: "rounded-lg py-2", gap: "gap-1.5", label: "text-[10px]" },
  md: { num: "text-3xl sm:text-4xl", cell: "rounded-2xl py-4", gap: "gap-2 sm:gap-3", label: "text-xs" },
  lg: { num: "text-4xl sm:text-5xl", cell: "rounded-2xl py-5", gap: "gap-3", label: "text-sm" },
} as const;

/**
 * شمارش معکوس. Flash-sale / launch timer with Persian digits.
 * Renders placeholders until mounted so SSR and the first client paint match.
 */
export function Countdown({
  target,
  units = DEFAULT_UNITS,
  labels,
  pad = true,
  size = "md",
  variant = "cards",
  onComplete,
  className,
}: CountdownProps) {
  const t = useCountdown(target);
  const done = React.useRef(false);
  const s = sizeCls[size];
  const labelMap = { ...DEFAULT_LABELS, ...labels };

  React.useEffect(() => {
    if (t && t.total === 0 && !done.current) {
      done.current = true;
      onComplete?.();
    }
  }, [t, onComplete]);

  function format(unit: CountdownUnit, n: number | null) {
    if (n === null) return pad || unit !== "days" ? "--" : "-";
    const raw = pad || unit !== "days" ? String(n).padStart(2, "0") : String(n);
    return fa(raw);
  }

  const values: Record<CountdownUnit, number | null> = {
    days: t?.days ?? null,
    hours: t?.hours ?? null,
    minutes: t?.minutes ?? null,
    seconds: t?.seconds ?? null,
  };

  if (variant === "inline") {
    return (
      <time
        dateTime={typeof target === "object" ? target.toISOString() : new Date(target).toISOString()}
        aria-live="off"
        dir="ltr"
        className={cn("inline-flex items-baseline tabular-nums", s.num, "font-bold", className)}
      >
        {units.map((u, i) => (
          <React.Fragment key={u}>
            {i > 0 && <span className="mx-0.5 text-muted-foreground" aria-hidden>:</span>}
            <span>{format(u, values[u])}</span>
          </React.Fragment>
        ))}
      </time>
    );
  }

  return (
    <div
      role="timer"
      aria-live="off"
      dir="ltr"
      className={cn("grid w-full", s.gap, className)}
      style={{ gridTemplateColumns: `repeat(${units.length}, minmax(0, 1fr))` }}
    >
      {units.map((u) => (
        <div key={u} className={cn("border border-border bg-card/70 text-center backdrop-blur", s.cell)}>
          <p className={cn("font-bold tabular-nums", s.num)}>{format(u, values[u])}</p>
          <p className={cn("mt-1 text-muted-foreground", s.label)}>{labelMap[u]}</p>
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import { Maximize, Minimize, Pause, Play, RotateCcw, RotateCw, Volume2, VolumeX } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface VideoChapter {
  /** Start time in seconds. */
  start: number;
  title: string;
}

export interface VideoCaption {
  src: string;
  label: string;
  srclang: string;
  default?: boolean;
}

export interface VideoPlayerProps {
  src: string;
  poster?: string;
  /** Shown on the paused overlay and used as the accessible name. */
  title?: string;
  chapters?: VideoChapter[];
  /** WebVTT subtitle tracks (زیرنویس). */
  captions?: VideoCaption[];
  /** Render the clickable chapter list under the video. */
  showChapters?: boolean;
  /** Seconds to start from, e.g. where the student left off. */
  startAt?: number;
  rates?: number[];
  onTimeUpdate?: (seconds: number, duration: number) => void;
  onEnded?: () => void;
  className?: string;
}

/** ۶۵ → «۱:۰۵»، ۳۷۲۰ → «۱:۰۲:۰۰». */
export function formatDuration(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = String(s % 60).padStart(2, "0");
  return fa(h ? `${h}:${String(m).padStart(2, "0")}:${ss}` : `${m}:${ss}`);
}

const faRate = (r: number) => `${fa(String(r)).replace(".", "٫")}×`;

/**
 * پخش‌کننده‌ی ویدئوی آموزشی. Native <video> with custom controls, chapters
 * and speed. The timeline and transport buttons stay LTR on purpose: media
 * progress follows the direction of time, not of text (Material bidi rule),
 * so only labels are Persian.
 */
export function VideoPlayer({
  src,
  poster,
  title,
  chapters = [],
  captions = [],
  showChapters = true,
  startAt = 0,
  rates = [0.75, 1, 1.25, 1.5, 2],
  onTimeUpdate,
  onEnded,
  className,
}: VideoPlayerProps) {
  const wrap = React.useRef<HTMLDivElement>(null);
  const video = React.useRef<HTMLVideoElement>(null);
  const [playing, setPlaying] = React.useState(false);
  const [started, setStarted] = React.useState(false);
  const [time, setTime] = React.useState(startAt);
  const [duration, setDuration] = React.useState(0);
  const [buffered, setBuffered] = React.useState(0);
  const [muted, setMuted] = React.useState(false);
  const [rate, setRate] = React.useState(1);
  const [rateOpen, setRateOpen] = React.useState(false);
  const [full, setFull] = React.useState(false);
  const seekId = React.useId();

  const sorted = React.useMemo(() => [...chapters].sort((a, b) => a.start - b.start), [chapters]);
  const chapterIndex = sorted.reduce((acc, c, i) => (time >= c.start ? i : acc), -1);
  const chapter = chapterIndex >= 0 ? sorted[chapterIndex] : undefined;

  // Metadata can arrive before hydration attaches React handlers, so subscribe natively
  // and catch up once if the browser already knows the duration.
  React.useEffect(() => {
    const v = video.current;
    if (!v) return;
    const onMeta = () => {
      setDuration(v.duration);
      if (startAt && v.currentTime < 0.1) v.currentTime = startAt;
    };
    v.addEventListener("loadedmetadata", onMeta);
    const raf = v.readyState >= 1 ? requestAnimationFrame(onMeta) : 0;
    return () => {
      v.removeEventListener("loadedmetadata", onMeta);
      cancelAnimationFrame(raf);
    };
  }, [src, startAt]);

  React.useEffect(() => {
    const onFs = () => setFull(document.fullscreenElement === wrap.current);
    document.addEventListener("fullscreenchange", onFs);
    return () => document.removeEventListener("fullscreenchange", onFs);
  }, []);

  React.useEffect(() => {
    if (!rateOpen) return;
    const close = (e: PointerEvent | KeyboardEvent) => {
      if (e instanceof KeyboardEvent ? e.key === "Escape" : !(e.target as Element).closest("[data-rate-menu]")) setRateOpen(false);
    };
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", close);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", close);
    };
  }, [rateOpen]);

  const toggle = () => {
    const v = video.current;
    if (!v) return;
    if (v.paused) void v.play();
    else v.pause();
  };
  const seek = (t: number) => {
    const v = video.current;
    if (!v) return;
    v.currentTime = Math.min(Math.max(0, t), duration || v.duration || 0);
    setTime(v.currentTime);
  };
  const skip = (d: number) => seek((video.current?.currentTime ?? 0) + d);
  const toggleFull = () => {
    const el = wrap.current;
    if (!el) return;
    if (document.fullscreenElement) void document.exitFullscreen();
    else if (el.requestFullscreen) void el.requestFullscreen();
    else (video.current as HTMLVideoElement & { webkitEnterFullscreen?: () => void })?.webkitEnterFullscreen?.();
  };
  const pickRate = (r: number) => {
    if (video.current) video.current.playbackRate = r;
    setRate(r);
    setRateOpen(false);
  };

  const onKey = (e: React.KeyboardEvent) => {
    const tag = (e.target as HTMLElement).tagName;
    // The seek range owns its arrows and buttons own Space; everything else is ours.
    if (tag === "INPUT" && e.key !== "k" && e.key !== "m" && e.key !== "f") return;
    if (tag === "BUTTON" && (e.key === " " || e.key === "Enter")) return;
    if (e.key === " " || e.key === "k") toggle();
    else if (e.key === "ArrowRight") skip(5);
    else if (e.key === "ArrowLeft") skip(-5);
    else if (e.key === "m") setMuted((m) => !m);
    else if (e.key === "f") toggleFull();
    else return;
    e.preventDefault();
  };

  const pct = duration ? (time / duration) * 100 : 0;
  const bufPct = duration ? (buffered / duration) * 100 : 0;
  const btn = "flex size-11 shrink-0 cursor-pointer items-center justify-center rounded-full text-white/90 transition-colors hover:bg-white/15 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70 [&_svg]:size-5";

  return (
    <div className={cn("space-y-3", className)}>
      <div
        ref={wrap}
        role="region"
        aria-label={title ? `ویدئو: ${title}` : "ویدئو"}
        tabIndex={-1}
        onKeyDown={onKey}
        className="group/vp @container relative aspect-video overflow-hidden rounded-surface border-line border-border bg-black text-white [--tw-border-style:var(--line-style)] data-[full=true]:rounded-none data-[full=true]:border-0"
        data-full={full}
      >
        <video
          ref={video}
          src={src}
          poster={poster}
          muted={muted}
          playsInline
          preload="metadata"
          onClick={toggle}
          onPlay={() => { setPlaying(true); setStarted(true); }}
          onPause={() => setPlaying(false)}
          onTimeUpdate={(e) => {
            const v = e.currentTarget;
            setTime(v.currentTime);
            onTimeUpdate?.(v.currentTime, v.duration);
          }}
          onProgress={(e) => {
            const b = e.currentTarget.buffered;
            if (b.length) setBuffered(b.end(b.length - 1));
          }}
          onEnded={() => { setPlaying(false); onEnded?.(); }}
          className="size-full object-contain"
        >
          {captions.map((c) => (
            <track key={c.srclang} kind="subtitles" src={c.src} srcLang={c.srclang} label={c.label} default={c.default} />
          ))}
        </video>

        {!playing && (
          <button
            type="button"
            onClick={toggle}
            aria-label="پخش"
            className="absolute inset-0 flex cursor-pointer flex-col items-center justify-center gap-3 bg-black/35 transition-opacity focus-visible:outline-none"
          >
            <span className="flex size-16 items-center justify-center rounded-full bg-white text-black shadow-xl transition-transform duration-200 group-hover/vp:scale-105 motion-reduce:transition-none">
              <Play className="ms-1 size-6 fill-current" />
            </span>
            {!started && title && <span className="max-w-[80%] text-center text-sm font-medium @max-sm:hidden">{title}</span>}
          </button>
        )}

        <div
          className={cn(
            "absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/85 via-black/50 to-transparent px-2 pb-1 pt-10 transition-opacity duration-200 motion-reduce:transition-none",
            playing ? "opacity-0 group-hover/vp:opacity-100 group-focus-within/vp:opacity-100" : "opacity-100",
          )}
        >
          {chapter && <p className="truncate px-2 pb-1 text-xs text-white/85">{chapter.title}</p>}
          <div dir="ltr" className="relative mx-2 flex h-4 items-center">
            <div className="pointer-events-none absolute inset-x-0 h-1 overflow-hidden rounded-full bg-white/25">
              <div className="absolute inset-y-0 left-0 bg-white/35" style={{ width: `${bufPct}%` }} />
              <div className="absolute inset-y-0 left-0 bg-brand" style={{ width: `${pct}%` }} />
            </div>
            {duration > 0 && sorted.filter((c) => c.start > 0).map((c) => (
              <span key={c.start} aria-hidden className="pointer-events-none absolute h-1 w-0.5 bg-black/70" style={{ left: `${(c.start / duration) * 100}%` }} />
            ))}
            <label htmlFor={seekId} className="sr-only">زمان پخش</label>
            <input
              id={seekId}
              type="range"
              dir="ltr"
              min={0}
              max={duration || 0}
              step={0.1}
              value={time}
              aria-valuetext={`${formatDuration(time)} از ${formatDuration(duration)}`}
              onChange={(e) => seek(Number(e.target.value))}
              className={cn(
                "relative h-4 w-full cursor-pointer appearance-none bg-transparent outline-none",
                "[&::-webkit-slider-thumb]:size-3.5 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow",
                "[&::-moz-range-thumb]:size-3.5 [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:border-0 [&::-moz-range-thumb]:bg-white",
                "focus-visible:[&::-webkit-slider-thumb]:ring-2 focus-visible:[&::-webkit-slider-thumb]:ring-white/70",
              )}
            />
          </div>
          <div dir="ltr" className="flex items-center gap-0.5">
            <button type="button" className={btn} onClick={toggle} aria-label={playing ? "توقف" : "پخش"}>
              {playing ? <Pause className="fill-current" /> : <Play className="fill-current" />}
            </button>
            <button type="button" className={cn(btn, "@max-sm:hidden")} onClick={() => skip(-10)} aria-label="۱۰ ثانیه عقب">
              <RotateCcw />
            </button>
            <button type="button" className={cn(btn, "@max-sm:hidden")} onClick={() => skip(10)} aria-label="۱۰ ثانیه جلو">
              <RotateCw />
            </button>
            <button type="button" className={btn} onClick={() => setMuted((m) => !m)} aria-label={muted ? "صدادار" : "بی‌صدا"}>
              {muted ? <VolumeX /> : <Volume2 />}
            </button>
            <span className="px-1.5 text-xs tabular-nums text-white/85 @max-xs:hidden">
              {formatDuration(time)} / {formatDuration(duration)}
            </span>
            <span className="flex-1" />
            <div className="relative" data-rate-menu>
              <button
                type="button"
                aria-haspopup="menu"
                aria-expanded={rateOpen}
                aria-label="سرعت پخش"
                onClick={() => setRateOpen((o) => !o)}
                className="h-11 min-w-11 cursor-pointer rounded-full px-2 text-xs font-medium tabular-nums text-white/90 transition-colors hover:bg-white/15 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
              >
                {faRate(rate)}
              </button>
              {rateOpen && (
                <div role="menu" dir="rtl" className="absolute bottom-full right-0 mb-2 min-w-28 overflow-hidden rounded-overlay bg-black/90 py-1 text-sm shadow-xl">
                  {rates.map((r) => (
                    <button
                      key={r}
                      type="button"
                      role="menuitemradio"
                      aria-checked={r === rate}
                      onClick={() => pickRate(r)}
                      className={cn("flex w-full cursor-pointer items-center justify-between gap-3 px-3 py-2 text-start hover:bg-white/10", r === rate && "text-brand")}
                    >
                      <span dir={r === 1 ? undefined : "ltr"}>{r === 1 ? "عادی" : faRate(r)}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            <button type="button" className={btn} onClick={toggleFull} aria-label={full ? "خروج از تمام‌صفحه" : "تمام‌صفحه"}>
              {full ? <Minimize /> : <Maximize />}
            </button>
          </div>
        </div>
      </div>

      {showChapters && sorted.length > 0 && (
        <ol className="divide-y divide-border overflow-hidden rounded-surface border-line border-border bg-card [--tw-border-style:var(--line-style)]" aria-label="فصل‌های ویدئو">
          {sorted.map((c, i) => (
            <li key={c.start}>
              <button
                type="button"
                onClick={() => { seek(c.start); if (!playing) void video.current?.play(); }}
                aria-current={i === chapterIndex ? "true" : undefined}
                className={cn(
                  "flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-2 text-start text-sm transition-colors hover:bg-accent/50",
                  i === chapterIndex && "bg-accent/40 font-medium",
                )}
              >
                <span className={cn("w-5 shrink-0 text-xs tabular-nums text-muted-foreground", i === chapterIndex && "text-brand")}>{fa(i + 1)}</span>
                <span className="min-w-0 flex-1 truncate">{c.title}</span>
                <span dir="ltr" className="shrink-0 text-xs tabular-nums text-muted-foreground">{formatDuration(c.start)}</span>
              </button>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { CheckCircle2, ChevronDown, ClipboardCheck, FileText, Lock, PenLine, PlayCircle } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type LessonKind = "video" | "reading" | "quiz" | "assignment";

export interface OutlineLesson {
  id: string;
  title: string;
  kind?: LessonKind;
  /** Length in minutes. */
  minutes?: number;
  done?: boolean;
  locked?: boolean;
  /** Free preview, open even when the course is not purchased. */
  preview?: boolean;
}

export interface OutlineSection {
  id: string;
  title: string;
  lessons: OutlineLesson[];
}

export interface CourseOutlineProps {
  sections: OutlineSection[];
  /** Id of the lesson being watched now. */
  currentId?: string;
  onSelect?: (lesson: OutlineLesson) => void;
  /** Sections open on first render. Defaults to the one containing currentId. */
  defaultOpen?: string[];
  /** Show the «۴ فصل · ۱۲ درس · ۳ ساعت» summary row. */
  showSummary?: boolean;
  className?: string;
}

const kindMeta: Record<LessonKind, { icon: React.ComponentType<{ className?: string }>; label: string }> = {
  video: { icon: PlayCircle, label: "ویدئو" },
  reading: { icon: FileText, label: "درس‌نامه" },
  quiz: { icon: ClipboardCheck, label: "آزمونک" },
  assignment: { icon: PenLine, label: "تمرین" },
};

/** ۱۹۵ → «۳ ساعت و ۱۵ دقیقه»، ۴۰ → «۴۰ دقیقه». */
export function formatMinutes(total: number): string {
  const h = Math.floor(total / 60);
  const m = total % 60;
  if (!h) return `${fa(m)} دقیقه`;
  return m ? `${fa(h)} ساعت و ${fa(m)} دقیقه` : `${fa(h)} ساعت`;
}

/**
 * سرفصل دوره. Collapsible sections with per-section progress, lesson type
 * icons, duration, locked and free-preview states. Height animates with
 * CSS grid rows; the chevron sits at the inline-end.
 */
export function CourseOutline({ sections, currentId, onSelect, defaultOpen, showSummary = true, className }: CourseOutlineProps) {
  const initial = defaultOpen ?? sections.filter((s) => s.lessons.some((l) => l.id === currentId)).map((s) => s.id);
  const [open, setOpen] = React.useState<string[]>(initial.length ? initial : sections.slice(0, 1).map((s) => s.id));
  const toggle = (id: string) => setOpen((o) => (o.includes(id) ? o.filter((x) => x !== id) : [...o, id]));

  const all = sections.flatMap((s) => s.lessons);
  const done = all.filter((l) => l.done).length;
  const minutes = all.reduce((sum, l) => sum + (l.minutes ?? 0), 0);

  return (
    <div className={cn("space-y-3", className)}>
      {showSummary && (
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-muted-foreground">
          <span>{fa(sections.length)} فصل</span>
          <span aria-hidden>·</span>
          <span>{fa(all.length)} درس</span>
          {minutes > 0 && (<><span aria-hidden>·</span><span>{formatMinutes(minutes)}</span></>)}
          {done > 0 && <span className="ms-auto text-foreground">{fa(done)} از {fa(all.length)} درس دیده‌شده</span>}
        </div>
      )}

      <div className="divide-y divide-border overflow-hidden rounded-surface border-line border-border bg-card [--tw-border-style:var(--line-style)]">
        {sections.map((s, si) => {
          const isOpen = open.includes(s.id);
          const sDone = s.lessons.filter((l) => l.done).length;
          const sMin = s.lessons.reduce((sum, l) => sum + (l.minutes ?? 0), 0);
          const pct = s.lessons.length ? (sDone / s.lessons.length) * 100 : 0;
          return (
            <section key={s.id}>
              <h3>
                <button
                  type="button"
                  aria-expanded={isOpen}
                  aria-controls={`outline-${s.id}`}
                  onClick={() => toggle(s.id)}
                  className="flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-3 text-start transition-colors hover:bg-accent/40"
                >
                  <span className="relative flex size-8 shrink-0 items-center justify-center rounded-full text-xs font-semibold tabular-nums">
                    <svg viewBox="0 0 32 32" className="absolute inset-0 -rotate-90" aria-hidden>
                      <circle cx="16" cy="16" r="14" fill="none" stroke="var(--border)" strokeWidth="2.5" />
                      <circle cx="16" cy="16" r="14" fill="none" stroke={pct === 100 ? "var(--success)" : "var(--brand)"} strokeWidth="2.5" strokeLinecap="round" strokeDasharray={`${(pct / 100) * 87.96} 87.96`} />
                    </svg>
                    {fa(si + 1)}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{s.title}</span>
                    <span className="block text-xs text-muted-foreground">
                      {fa(sDone)} از {fa(s.lessons.length)} درس{sMin > 0 && ` · ${formatMinutes(sMin)}`}
                    </span>
                  </span>
                  <ChevronDown className={cn("size-4 shrink-0 text-muted-foreground transition-transform duration-200 motion-reduce:transition-none", isOpen && "rotate-180")} />
                </button>
              </h3>
              <div id={`outline-${s.id}`} className={cn("grid transition-[grid-template-rows] duration-200 ease-out motion-reduce:transition-none", isOpen ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
                <ul className="overflow-hidden" inert={!isOpen}>
                  {s.lessons.map((l) => {
                    const meta = kindMeta[l.kind ?? "video"];
                    const Icon = l.done ? CheckCircle2 : l.locked ? Lock : meta.icon;
                    const current = l.id === currentId;
                    return (
                      <li key={l.id}>
                        <button
                          type="button"
                          disabled={l.locked && !l.preview}
                          aria-current={current ? "step" : undefined}
                          onClick={() => onSelect?.(l)}
                          className={cn(
                            "relative flex min-h-11 w-full cursor-pointer items-center gap-3 py-2.5 pe-4 ps-6 text-start text-sm transition-colors hover:bg-accent/50 disabled:cursor-not-allowed disabled:opacity-55 disabled:hover:bg-transparent",
                            current && "bg-accent/60 font-semibold before:absolute before:inset-y-2 before:start-0 before:w-0.5 before:rounded-full before:bg-brand",
                          )}
                        >
                          <Icon className={cn("size-4 shrink-0", l.done ? "text-success" : current ? "text-brand" : "text-muted-foreground")} />
                          <span className="min-w-0 flex-1">
                            <span className="block truncate">{l.title}</span>
                            <span className="sr-only">{meta.label}{l.done ? "، دیده‌شده" : l.locked ? "، قفل" : ""}</span>
                          </span>
                          {l.preview && !l.done && <span className="shrink-0 rounded-full border border-brand/30 px-2 text-xs leading-5 text-brand">رایگان</span>}
                          {l.minutes != null && <span className="shrink-0 text-xs tabular-nums text-muted-foreground">{fa(l.minutes)} دقیقه</span>}
                        </button>
                      </li>
                    );
                  })}
                </ul>
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

import * as React from "react";
import { AlertTriangle, BookOpen, CheckCircle2, Clock, FlaskConical, Lightbulb, ListChecks, Quote, Target } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface LessonNoteProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  title: React.ReactNode;
  /** Small label above the title, e.g. «فصل ۲ · درس ۳». */
