}

type CalloutKind = "tip" | "definition" | "example" | "warning" | "summary" | "quote";

const kinds: Record<CalloutKind, { label: string; icon: React.ComponentType<{ className?: string }>; box: string; tone: string }> = {
  tip: { label: "نکته", icon: Lightbulb, box: "border-brand/30 bg-brand/8", tone: "text-brand" },
  definition: { label: "تعریف", icon: BookOpen, box: "border-border bg-card", tone: "text-foreground" },
  example: { label: "مثال", icon: FlaskConical, box: "border-success/25 bg-success/8", tone: "text-success" },
  warning: { label: "اشتباه رایج", icon: AlertTriangle, box: "border-warning/30 bg-warning/8", tone: "text-warning" },
  summary: { label: "جمع‌بندی", icon: ListChecks, box: "border-border bg-muted", tone: "text-foreground" },
  quote: { label: "نقل‌قول", icon: Quote, box: "border-border bg-transparent", tone: "text-muted-foreground" },
};

export interface CalloutProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  kind?: CalloutKind;
  /** Overrides the default label («نکته»، «تعریف»، …). */
  title?: React.ReactNode;
}

/** کادر درس‌نامه: نکته، تعریف، مثال، اشتباه رایج، جمع‌بندی. The accent bar sits on the inline-start. */
export function Callout({ kind = "tip", title, className, children, ...props }: CalloutProps) {
  const k = kinds[kind];
  const Icon = k.icon;
  return (
    <aside
      className={cn("rounded-overlay border-line border-s-4 p-4 text-sm leading-7 [--tw-border-style:var(--line-style)]", k.box, className)}
      {...props}
    >
      <p className={cn("mb-1 flex items-center gap-2 font-semibold", k.tone)}>
        <Icon className="size-4 shrink-0" />
        {title ?? k.label}
      </p>
      <div className="text-foreground/90 [&>*+*]:mt-2">{children}</div>
    </aside>
  );
}

export interface FormulaProps extends React.HTMLAttributes<HTMLElement> {
  /** Persian caption under the formula, e.g. «رابطه‌ی ۲-۱». */
  caption?: React.ReactNode;
  /** Inline inside a sentence instead of a centred block. */
  inline?: boolean;
}

/**
 * فرمول. Math reads left-to-right even in a Persian page, so the content is
 * isolated in an LTR box (bdi) and cannot scramble the surrounding sentence.
 */
export function Formula({ caption, inline, className, children, ...props }: FormulaProps) {
  if (inline) {
    return (
      <bdi dir="ltr" className={cn("whitespace-nowrap rounded-control bg-muted px-1.5 py-0.5 tabular-nums", className)} {...props}>
        {children}
      </bdi>
    );
  }
  return (
    <figure className={cn("my-2 space-y-1.5 text-center", className)} {...props}>
      <div dir="ltr" className="overflow-x-auto rounded-overlay bg-muted px-4 py-3 text-lg tabular-nums">{children}</div>
      {caption && <figcaption className="text-xs text-muted-foreground">{caption}</figcaption>}
    </figure>
  );
}

export interface KeyTermsProps {
  terms: { term: React.ReactNode; en?: string; desc: React.ReactNode }[];
  title?: React.ReactNode;
  className?: string;
}

/** واژه‌نامه‌ی درس. Persian term, optional English equivalent in LTR, then the definition. */
export function KeyTerms({ terms, title = "واژه‌های کلیدی", className }: KeyTermsProps) {
  return (
    <section className={cn("space-y-2", className)}>
      <p className="text-sm font-semibold">{title}</p>
      <dl className="divide-y divide-border rounded-surface border-line border-border bg-card [--tw-border-style:var(--line-style)]">
        {terms.map((t, i) => (
          <div key={i} className="grid gap-1 px-4 py-3 text-sm sm:grid-cols-[10rem_1fr] sm:gap-4">
            <dt className="font-medium">
              {t.term}
              {t.en && <bdi dir="ltr" className="ms-1.5 text-xs font-normal text-muted-foreground">{t.en}</bdi>}
            </dt>
            <dd className="leading-7 text-foreground/85">{t.desc}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

"use client";

import * as React from "react";
import { RotateCcw } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { Slider } from "./slider";

export interface PlotParam {
  key: string;
  /** Persian label, e.g. «دامنه (a)». */
  label: string;
  min: number;
  max: number;
  step?: number;
  default: number;
}

export interface FunctionPlotProps {
  /** y = fn(x, params). Return NaN to leave a gap (e.g. outside the domain). */
  fn: (x: number, p: Record<string, number>) => number;
  params?: PlotParam[];
  /** Live formula shown in an LTR box, e.g. (p) => `y = ${p.a}·sin(${p.b}x)`. */
  formula?: (p: Record<string, number>) => string;
  xDomain?: [number, number];
  yDomain?: [number, number];
  /** Keep the curve of the default params as a dashed ghost to compare against. */
  showBaseline?: boolean;
  /** Accessible description of what the figure shows. */
  label?: string;
  className?: string;
}

/** ۱٫۵ / -۲ with at most two decimals and the Persian decimal separator. */
export function faDecimal(n: number, digits = 2): string {
  if (!Number.isFinite(n)) return "—";
  return fa(String(+n.toFixed(digits))).replace(".", "٫");
}

function niceStep(span: number, target = 8) {
  const raw = span / target;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  return ([1, 2, 5, 10].map((m) => m * mag).find((s) => s >= raw) ?? mag * 10);
}

function ticks([a, b]: [number, number]) {
  const step = niceStep(b - a);
  const out: number[] = [];
  for (let v = Math.ceil(a / step) * step; v <= b + 1e-9; v += step) out.push(+v.toFixed(10));
  return out;
}

const W = 600;
const H = 360;
const PAD = 28;

/**
 * نمودار تعاملی. Plots y = f(x) in SVG with sliders for each parameter and a
 * hover tracer. Cartesian axes keep the maths convention (x grows to the
 * right) even in RTL; only tick numbers become Persian and the controls stay RTL.
 */
export function FunctionPlot({
  fn,
  params = [],
  formula,
  xDomain = [-10, 10],
  yDomain = [-6, 6],
  showBaseline = true,
  label = "نمودار تابع",
  className,
}: FunctionPlotProps) {
  const defaults = React.useMemo(() => Object.fromEntries(params.map((p) => [p.key, p.default])), [params]);
  const [values, setValues] = React.useState<Record<string, number>>(defaults);
  const [hoverX, setHoverX] = React.useState<number | null>(null);
  const svg = React.useRef<SVGSVGElement>(null);
  const clip = React.useId().replace(/:/g, "");

  const [x0, x1] = xDomain;
  const [y0, y1] = yDomain;
  const sx = (x: number) => PAD + ((x - x0) / (x1 - x0)) * (W - 2 * PAD);
  const sy = (y: number) => H - PAD - ((y - y0) / (y1 - y0)) * (H - 2 * PAD);

  const path = (p: Record<string, number>) => {
    const n = 400;
    let d = "";
    let pen = false;
    let prev = NaN;
    for (let i = 0; i <= n; i++) {
      const x = x0 + ((x1 - x0) * i) / n;
      const y = fn(x, p);
      // Lift the pen on gaps and across vertical asymptotes (off-screen on one side, then the other).
      const jump = (prev > y1 && y < y0) || (prev < y0 && y > y1);
      const ok = Number.isFinite(y) && !jump;
      if (ok) {
        const cy = Math.max(-H, Math.min(2 * H, sy(y)));
        d += `${pen ? "L" : "M"}${sx(x).toFixed(1)} ${cy.toFixed(1)}`;
      }
      pen = ok;
      prev = y;
    }
    return d;
  };

  const changed = params.some((p) => values[p.key] !== p.default);
  const hy = hoverX == null ? NaN : fn(hoverX, values);
  const xs = ticks(xDomain);
  const ys = ticks(yDomain);
  const axisY = sy(Math.min(Math.max(0, y0), y1));
  const axisX = sx(Math.min(Math.max(0, x0), x1));

  const onMove = (e: React.PointerEvent<SVGSVGElement>) => {
    const r = svg.current!.getBoundingClientRect();
    const px = ((e.clientX - r.left) / r.width) * W;
    const x = x0 + ((px - PAD) / (W - 2 * PAD)) * (x1 - x0);
    setHoverX(x < x0 || x > x1 ? null : x);
  };

  return (
    <figure className={cn("space-y-4 rounded-surface border-line border-border bg-card p-4 [--tw-border-style:var(--line-style)]", className)}>
      {formula && (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <bdi dir="ltr" className="rounded-control bg-muted px-3 py-1.5 text-sm tabular-nums" aria-live="polite">
            {formula(values)}
          </bdi>
          {params.length > 0 && (
            <button
              type="button"
              onClick={() => setValues(defaults)}
              disabled={!changed}
              className="flex h-11 cursor-pointer items-center gap-1.5 rounded-control px-3 text-xs text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
            >
              <RotateCcw className="size-3.5" />
              حالت اول
            </button>
          )}
        </div>
      )}

      <div dir="ltr" className="relative">
        <svg
          ref={svg}
          viewBox={`0 0 ${W} ${H}`}
          role="img"
          aria-label={label}
          className="w-full touch-none select-none"
          onPointerMove={onMove}
          onPointerDown={onMove}
          onPointerLeave={() => setHoverX(null)}
        >
          <defs>
            <clipPath id={clip}><rect x={PAD} y={PAD} width={W - 2 * PAD} height={H - 2 * PAD} /></clipPath>
          </defs>
          {xs.map((v) => <line key={`gx${v}`} x1={sx(v)} x2={sx(v)} y1={PAD} y2={H - PAD} stroke="var(--border)" />)}
          {ys.map((v) => <line key={`gy${v}`} x1={PAD} x2={W - PAD} y1={sy(v)} y2={sy(v)} stroke="var(--border)" />)}
          <line x1={PAD} x2={W - PAD} y1={axisY} y2={axisY} stroke="var(--muted-foreground)" strokeWidth={1.25} />
          <line x1={axisX} x2={axisX} y1={PAD} y2={H - PAD} stroke="var(--muted-foreground)" strokeWidth={1.25} />
          {xs.filter((v) => v !== 0).map((v) => (
            <text key={`tx${v}`} x={sx(v)} y={Math.min(axisY + 16, H - 6)} textAnchor="middle" fontSize={11} fill="var(--muted-foreground)">{faDecimal(v)}</text>
          ))}
          {ys.filter((v) => v !== 0).map((v) => (
            <text key={`ty${v}`} x={axisX - 6} y={sy(v) + 4} textAnchor="end" fontSize={11} fill="var(--muted-foreground)">{faDecimal(v)}</text>
          ))}
          <g clipPath={`url(#${clip})`}>
            {showBaseline && changed && <path d={path(defaults)} fill="none" stroke="var(--muted-foreground)" strokeOpacity={0.6} strokeWidth={1.5} strokeDasharray="5 5" />}
            <path d={path(values)} fill="none" stroke="var(--brand)" strokeWidth={2.5} strokeLinejoin="round" strokeLinecap="round" />
            {hoverX != null && (
              <>
                <line x1={sx(hoverX)} x2={sx(hoverX)} y1={PAD} y2={H - PAD} stroke="var(--foreground)" strokeOpacity={0.25} strokeDasharray="3 3" />
                {Number.isFinite(hy) && <circle cx={sx(hoverX)} cy={sy(hy)} r={5} fill="var(--background)" stroke="var(--brand)" strokeWidth={2.5} />}
              </>
            )}
          </g>
        </svg>
        {hoverX != null && (
          <div className="pointer-events-none absolute left-2 top-2 rounded-control bg-popover px-2 py-1 text-xs tabular-nums text-popover-foreground shadow">
            x = {faDecimal(hoverX)}<span className="px-1.5 opacity-50">|</span>y = {faDecimal(hy)}
          </div>
        )}
      </div>

      {params.length > 0 && (
        <div className="grid gap-4 sm:grid-cols-2">
          {params.map((p) => (
            <Slider
              key={p.key}
              label={p.label}
              min={p.min}
              max={p.max}
              step={p.step ?? 0.1}
              value={values[p.key]}
              format={(v) => faDecimal(v)}
              onChange={(v) => setValues((s) => ({ ...s, [p.key]: v }))}
            />
          ))}
        </div>
      )}
      {showBaseline && changed && (
        <figcaption className="flex items-center gap-2 text-xs text-muted-foreground">
          <span aria-hidden className="inline-block w-5 border-t-2 border-dashed border-muted-foreground/60" />
          منحنی خط‌چین، حالت اول تابع است.
        </figcaption>
      )}
    </figure>
  );
}

"use client";

import * as React from "react";
import { Check, X } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface Hotspot {
  id: string;
  /** Position on the picture in percent, measured from its left edge (pictures do not mirror). */
  x: number;
  /** Position in percent from the top edge. */
  y: number;
  title: string;
  desc?: React.ReactNode;
}

export interface HotspotFigureProps {
  hotspots: Hotspot[];
  /** The picture: an <img>, an inline <svg> or any element that fills the box. */
  children: React.ReactNode;
  /** CSS aspect-ratio of the picture, reserved before it loads. */
  ratio?: string;
  caption?: React.ReactNode;
  /** Numbered legend with «دیده‌شده» ticks under the figure. */
  showLegend?: boolean;
  onExplore?: (visited: string[]) => void;
  className?: string;
}

/**
 * شکل تعاملی. Numbered hotspots on a picture; each opens a card with the
 * name and explanation, and the legend tracks which parts the learner has
 * already explored. Hotspot coordinates are physical (left/top) because an
 * image is not mirrored in RTL; everything textual stays RTL.
 */
export function HotspotFigure({ hotspots, children, ratio = "16 / 10", caption, showLegend = true, onExplore, className }: HotspotFigureProps) {
  const [active, setActive] = React.useState<string | null>(null);
  const [visited, setVisited] = React.useState<string[]>([]);
  const baseId = React.useId();

  const open = (id: string) => {
    setActive((a) => (a === id ? null : id));
    if (visited.includes(id)) return;
    const next = [...visited, id];
    setVisited(next);
    onExplore?.(next);
  };

  React.useEffect(() => {
    if (!active) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setActive(null);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [active]);

  const current = hotspots.find((h) => h.id === active);
  const idx = (id: string) => hotspots.findIndex((h) => h.id === id);

  return (
    <figure className={cn("space-y-3", className)}>
      <div dir="ltr" className="relative rounded-surface border-line border-border bg-card [--tw-border-style:var(--line-style)]" style={{ aspectRatio: ratio }}>
        <div className="absolute inset-0 overflow-hidden rounded-[inherit] [&>img]:size-full [&>img]:object-cover [&>svg]:size-full">{children}</div>

        {hotspots.map((h, i) => {
          const isActive = h.id === active;
          const seen = visited.includes(h.id);
          return (
            <button
              key={h.id}
              type="button"
              aria-expanded={isActive}
              aria-controls={`${baseId}-card`}
              aria-label={`${fa(i + 1)}. ${h.title}`}
              onClick={() => open(h.id)}
              className="group/hs absolute flex size-11 -translate-x-1/2 -translate-y-1/2 cursor-pointer items-center justify-center focus-visible:outline-none"
              style={{ left: `${h.x}%`, top: `${h.y}%` }}
            >
              {!seen && !isActive && <span aria-hidden className="absolute size-7 animate-ping rounded-full bg-brand/50 motion-reduce:hidden" />}
              <span
                className={cn(
                  "relative flex size-7 items-center justify-center rounded-full border-2 text-xs font-bold shadow-lg transition-transform duration-200 group-hover/hs:scale-110 group-focus-visible/hs:ring-2 group-focus-visible/hs:ring-ring motion-reduce:transition-none",
                  isActive ? "scale-110 border-brand bg-brand text-brand-foreground" : seen ? "border-background bg-foreground text-background" : "border-background bg-brand text-brand-foreground",
                )}
              >
                {fa(i + 1)}
              </span>
            </button>
          );
        })}

        {current && (
          <div
            id={`${baseId}-card`}
            dir="rtl"
            role="dialog"
            aria-label={current.title}
            className={cn(
              "absolute z-10 w-64 max-w-[calc(100%-1rem)] rounded-overlay border border-border bg-popover p-3 text-popover-foreground shadow-overlay",
              current.y > 55 ? "-translate-y-full -mt-6" : "mt-6",
            )}
            // Centre on the hotspot, clamped so the card never leaves the picture sideways.
            style={{ left: `clamp(0.5rem, calc(${current.x}% - 8rem), calc(100% - 16.5rem))`, top: `${current.y}%` }}
          >
            <div className="flex items-start gap-2">
              <span className="mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full bg-brand text-xs font-bold text-brand-foreground">{fa(idx(current.id) + 1)}</span>
              <p className="flex-1 text-sm font-semibold leading-6">{current.title}</p>
              <button type="button" onClick={() => setActive(null)} aria-label="بستن" className="-m-2 flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground">
                <X className="size-4" />
              </button>
            </div>
            {current.desc && <div className="mt-1.5 text-sm leading-7 text-foreground/85">{current.desc}</div>}
          </div>
        )}
      </div>

      {showLegend && (
        <div className="space-y-2">
          <p className="text-xs text-muted-foreground" aria-live="polite">
            {visited.length === hotspots.length ? "همه‌ی بخش‌ها را دیده‌اید." : `${fa(visited.length)} از ${fa(hotspots.length)} بخش را دیده‌اید. روی شماره‌ها بزنید.`}
          </p>
          <ol className="grid gap-1.5 sm:grid-cols-2">
            {hotspots.map((h, i) => {
              const seen = visited.includes(h.id);
              return (
                <li key={h.id}>
                  <button
                    type="button"
                    onClick={() => open(h.id)}
                    aria-pressed={h.id === active}
                    className={cn(
                      "flex min-h-11 w-full cursor-pointer items-center gap-2.5 rounded-control px-2.5 py-1.5 text-start text-sm transition-colors hover:bg-accent/60",
                      h.id === active && "bg-accent",
                    )}
                  >
                    <span className={cn("flex size-6 shrink-0 items-center justify-center rounded-full text-xs font-bold", seen ? "bg-success/15 text-success" : "bg-muted text-muted-foreground")}>
                      {seen ? <Check className="size-3.5" /> : fa(i + 1)}
                    </span>
                    <span className="truncate">{h.title}</span>
                  </button>
                </li>
              );
            })}
          </ol>
        </div>
      )}
      {caption && <figcaption className="text-center text-xs text-muted-foreground">{caption}</figcaption>}
    </figure>
  );
}

"use client";

import * as React from "react";
import { ArrowLeft, ArrowRight, CheckCircle2, RotateCcw, XCircle } from "lucide-react";
import { cn, fa, faPercent } from "@/lib/utils";
import { Button } from "./button";
import { Progress } from "./progress";

export interface QuizOption {
  id: string;
  label: React.ReactNode;
}

export interface QuizQuestion {
  id: string;
  prompt: React.ReactNode;
  options: QuizOption[];
  /** Correct option id, or several ids for a multiple-answer question. */
  answer: string | string[];
  /** Shown after answering: why the right option is right. */
  explanation?: React.ReactNode;
}

export interface QuizResult {
  correct: number;
  total: number;
  percent: number;
  passed: boolean;
  answers: Record<string, string[]>;
}

export interface QuizProps {
  questions: QuizQuestion[];
  title?: React.ReactNode;
  /** instant = check every question before moving on; end = exam mode, grade at the end. */
  feedback?: "instant" | "end";
  /** Percent needed to pass. */
  passPercent?: number;
  onComplete?: (result: QuizResult) => void;
  className?: string;
}

/** Persian option letters: الف، ب، ج، د … */
export const OPTION_LETTERS = ["الف", "ب", "ج", "د", "ه", "و", "ز", "ح"];

const keyOf = (a: string | string[]) => (Array.isArray(a) ? a : [a]);
const isRight = (q: QuizQuestion, picked: string[] = []) => {
  const want = keyOf(q.answer);
  return picked.length === want.length && want.every((w) => picked.includes(w));
};

/**
 * ارزیابی / آزمونک. Single and multiple-answer questions with Persian option
 * letters, instant feedback with explanations (or exam mode), a progress bar
 * and a result screen with review and retry. «بعدی» uses ArrowLeft in RTL.
 */
export function Quiz({ questions, title, feedback = "instant", passPercent = 70, onComplete, className }: QuizProps) {
  const [index, setIndex] = React.useState(0);
  const [answers, setAnswers] = React.useState<Record<string, string[]>>({});
  const [checked, setChecked] = React.useState<Record<string, boolean>>({});
  const [done, setDone] = React.useState(false);
  const groupId = React.useId();

  const q = questions[index];
  const multi = Array.isArray(q?.answer) && q.answer.length > 1;
  const picked = answers[q?.id] ?? [];
  const revealed = feedback === "instant" && checked[q?.id];
  const last = index === questions.length - 1;

  const pick = (optId: string) => {
    if (revealed) return;
    setAnswers((a) => {
      const cur = a[q.id] ?? [];
      const next = multi ? (cur.includes(optId) ? cur.filter((x) => x !== optId) : [...cur, optId]) : [optId];
      return { ...a, [q.id]: next };
    });
  };

  const finish = () => {
    const correct = questions.filter((qq) => isRight(qq, answers[qq.id])).length;
    const percent = questions.length ? (correct / questions.length) * 100 : 0;
    setDone(true);
    onComplete?.({ correct, total: questions.length, percent, passed: percent >= passPercent, answers });
  };

  const restart = () => {
    setAnswers({});
    setChecked({});
    setIndex(0);
    setDone(false);
  };

  const shell = "rounded-surface border-line border-border bg-card p-5 [--tw-border-style:var(--line-style)]";

  if (done) {
    const correct = questions.filter((qq) => isRight(qq, answers[qq.id])).length;
    const percent = questions.length ? (correct / questions.length) * 100 : 0;
    const passed = percent >= passPercent;
    return (
      <section className={cn(shell, "space-y-5", className)} aria-live="polite">
        <div className="flex items-center gap-4">
          <div className="relative flex size-20 shrink-0 items-center justify-center">
            <svg viewBox="0 0 80 80" className="absolute inset-0 -rotate-90" aria-hidden>
              <circle cx="40" cy="40" r="34" fill="none" stroke="var(--border)" strokeWidth="6" />
              <circle cx="40" cy="40" r="34" fill="none" stroke={passed ? "var(--success)" : "var(--warning)"} strokeWidth="6" strokeLinecap="round" strokeDasharray={`${(percent / 100) * 213.6} 213.6`} className="transition-[stroke-dasharray] duration-700 motion-reduce:transition-none" />
            </svg>
            <span className="text-lg font-bold tabular-nums">{faPercent(percent)}</span>
          </div>
          <div>
            <p className={cn("text-lg font-bold", passed ? "text-success" : "text-warning")}>{passed ? "قبول شدید" : "نیاز به مرور دارید"}</p>
            <p className="mt-1 text-sm text-muted-foreground">
              {fa(correct)} پاسخ درست از {fa(questions.length)} سؤال · حد قبولی {faPercent(passPercent)}
            </p>
          </div>
        </div>
        <ol className="divide-y divide-border rounded-overlay border border-border">
          {questions.map((qq, i) => {
            const ok = isRight(qq, answers[qq.id]);
            const right = keyOf(qq.answer).map((id) => qq.options.findIndex((o) => o.id === id));
            return (
              <li key={qq.id} className="flex items-start gap-3 px-4 py-3 text-sm">
                {ok ? <CheckCircle2 className="mt-1 size-4 shrink-0 text-success" /> : <XCircle className="mt-1 size-4 shrink-0 text-destructive" />}
                <div className="min-w-0 flex-1 leading-7">
                  <span className="text-muted-foreground">{fa(i + 1)}. </span>
                  {qq.prompt}
                  {!ok && <p className="text-xs text-muted-foreground">پاسخ درست: {right.length > 1 ? "گزینه‌های" : "گزینه‌ی"} {right.map((r) => `«${OPTION_LETTERS[r]}»`).join(" و ")}</p>}
                </div>
              </li>
            );
          })}
        </ol>
        <Button variant="outline" onClick={restart}><RotateCcw />دوباره امتحان کنید</Button>
      </section>
    );
  }

  if (!q) return null;
  const ok = isRight(q, picked);

  return (
    <section className={cn(shell, "space-y-5", className)} aria-labelledby={`${groupId}-q`}>
      <div className="space-y-2">
        <div className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
          <span className="font-medium text-foreground">{title}</span>
          <span className="tabular-nums">سؤال {fa(index + 1)} از {fa(questions.length)}</span>
        </div>
        <Progress value={index + (revealed || (feedback === "end" && picked.length > 0) ? 1 : 0)} max={questions.length} size="sm" />
      </div>

      <div>
        <p id={`${groupId}-q`} className="text-base font-semibold leading-8">{q.prompt}</p>
        {multi && <p className="mt-1 text-xs text-muted-foreground">چند گزینه درست است؛ همه را انتخاب کنید.</p>}
      </div>

      <div role={multi ? "group" : "radiogroup"} aria-labelledby={`${groupId}-q`} className="space-y-2">
        {q.options.map((o, i) => {
          const sel = picked.includes(o.id);
          const correct = keyOf(q.answer).includes(o.id);
          const state = revealed ? (correct ? "right" : sel ? "wrong" : "idle") : sel ? "selected" : "idle";
          return (
            <label
              key={o.id}
              className={cn(
                "flex min-h-12 cursor-pointer items-center gap-3 rounded-overlay border px-3 py-2.5 text-sm transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
                state === "idle" && "border-border hover:border-foreground/25 hover:bg-accent/40",
                state === "selected" && "border-brand bg-brand/10",
                state === "right" && "border-success/50 bg-success/10",
                state === "wrong" && "border-destructive/50 bg-destructive/10",
                revealed && "cursor-default",
              )}
            >
              <input
                type={multi ? "checkbox" : "radio"}
                name={`${groupId}-${q.id}`}
                checked={sel}
                disabled={revealed}
                onChange={() => pick(o.id)}
                className="sr-only"
              />
              <span
                className={cn(
                  "flex size-7 shrink-0 items-center justify-center rounded-full border text-xs font-semibold",
                  multi && "rounded-control",
                  state === "idle" && "border-border text-muted-foreground",
                  state === "selected" && "border-brand bg-brand text-brand-foreground",
                  state === "right" && "border-success bg-success text-background",
                  state === "wrong" && "border-destructive bg-destructive text-white",
                )}
              >
                {OPTION_LETTERS[i]}
              </span>
              <span className="flex-1 leading-7">{o.label}</span>
              {state === "right" && <CheckCircle2 className="size-4 shrink-0 text-success" aria-label="پاسخ درست" />}
              {state === "wrong" && <XCircle className="size-4 shrink-0 text-destructive" aria-label="پاسخ نادرست" />}
            </label>
          );
        })}
      </div>

      <div aria-live="polite">
        {revealed && (
          <div className={cn("rounded-overlay border-s-4 p-4 text-sm leading-7", ok ? "border-success bg-success/8" : "border-destructive bg-destructive/8")}>
            <p className={cn("font-semibold", ok ? "text-success" : "text-destructive")}>{ok ? "درست است!" : "پاسخ درست نبود."}</p>
            {q.explanation && <div className="mt-1 text-foreground/85">{q.explanation}</div>}
          </div>
        )}
      </div>

      <div className="flex items-center justify-between gap-3">
        {feedback === "end" ? (
          <Button variant="ghost" onClick={() => setIndex((i) => i - 1)} disabled={index === 0}><ArrowRight />قبلی</Button>
        ) : <span />}
        {feedback === "instant" && !revealed ? (
          <Button onClick={() => setChecked((c) => ({ ...c, [q.id]: true }))} disabled={!picked.length}>بررسی پاسخ</Button>
        ) : last ? (
          <Button variant="brand" onClick={finish} disabled={!picked.length}>پایان و دیدن نتیجه</Button>
        ) : (
          <Button onClick={() => setIndex((i) => i + 1)} disabled={feedback === "end" && !picked.length}>سؤال بعدی<ArrowLeft /></Button>
        )}
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { Check, Copy, RotateCcw, ThumbsDown, ThumbsUp, TriangleAlert } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type ChatRole = "user" | "assistant";

export interface ChatMessageProps {
  role: ChatRole;
  /** Shown above an assistant message, e.g. the model name. */
  name?: string;
  /** Avatar node for the assistant. User messages have none. */
  avatar?: React.ReactNode;
  /** Sent time; rendered as «۱۴:۳۰». */
  time?: Date;
  /** "streaming" marks the message busy for screen readers; "error" shows the retry row. */
  status?: "streaming" | "error";
  onRetry?: () => void;
  /** Row under an assistant message, usually <MessageActions />. */
  actions?: React.ReactNode;
  /** Files or images attached to a user message. */
  attachments?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}

const clock = (d: Date) => fa(`${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`);

/**
 * پیام چت. The user's message is a bubble at the inline-start (right in RTL); the
 * assistant's answer is plain text across the column, which reads better for long
 * Persian paragraphs, code and tables.
 */
export function ChatMessage({ role, name, avatar, time, status, onRetry, actions, attachments, className, children }: ChatMessageProps) {
  if (role === "user") {
    return (
      <div className={cn("flex flex-col items-start gap-1", className)}>
        <span className="sr-only">شما:</span>
        {attachments && <div className="flex max-w-[85%] flex-wrap gap-2">{attachments}</div>}
        <div dir="auto" className="max-w-[85%] whitespace-pre-wrap rounded-2xl rounded-ss-md bg-secondary px-4 py-2.5 text-sm leading-7 break-words">{children}</div>
        {time && <time dateTime={time.toISOString()} className="px-1 text-[11px] text-muted-foreground">{clock(time)}</time>}
      </div>
    );
  }
  return (
    <div className={cn("group/message flex gap-3", className)} aria-busy={status === "streaming" || undefined}>
      {avatar && <div className="mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-full border border-border bg-card [&_svg]:size-4">{avatar}</div>}
      <div className="min-w-0 flex-1">
        <p className="mb-1 flex items-center gap-2 text-xs text-muted-foreground">
          <span className="font-medium text-foreground">{name ?? "دستیار"}</span>
          {time && <time dateTime={time.toISOString()}>{clock(time)}</time>}
        </p>
        <div className="text-sm leading-8">{children}</div>
        {status === "error" ? (
          <div role="alert" className="mt-3 flex flex-wrap items-center gap-3 rounded-xl border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm text-destructive">
            <TriangleAlert className="size-4 shrink-0" />
            <span className="flex-1">پاسخ کامل نشد. اتصال را بررسی کنید و دوباره امتحان کنید.</span>
            {onRetry && <button type="button" onClick={onRetry} className="flex cursor-pointer items-center gap-1.5 font-medium underline underline-offset-4"><RotateCcw className="size-3.5" />تلاش دوباره</button>}
          </div>
        ) : (
          status !== "streaming" && actions && <div className="mt-2">{actions}</div>
        )}
      </div>
    </div>
  );
}

export interface MessageActionsProps {
  /** Plain text of the message, for the copy button. */
  text: string;
  onRegenerate?: () => void;
  /** Called with "up", "down", or null when the vote is taken back. */
  onFeedback?: (vote: "up" | "down" | null) => void;
  className?: string;
}

const actionButton = "flex size-8 cursor-pointer items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-4";

/** کپی، بازنویسی و بازخورد. The row of small icon buttons under an assistant message. */
export function MessageActions({ text, onRegenerate, onFeedback, className }: MessageActionsProps) {
  const [copied, setCopied] = React.useState(false);
  const [vote, setVote] = React.useState<"up" | "down" | null>(null);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard blocked */
    }
  }

  function cast(next: "up" | "down") {
    const value = vote === next ? null : next;
    setVote(value);
    onFeedback?.(value);
  }

  return (
    <div className={cn("flex items-center gap-0.5", className)}>
      <button type="button" className={actionButton} onClick={copy} aria-label="کپی پاسخ" title="کپی">{copied ? <Check className="text-success" /> : <Copy />}</button>
      {onRegenerate && <button type="button" className={actionButton} onClick={onRegenerate} aria-label="نوشتن دوباره‌ی پاسخ" title="دوباره بنویس"><RotateCcw /></button>}
      {onFeedback && (
        <>
          <button type="button" className={cn(actionButton, vote === "up" && "bg-secondary text-foreground")} aria-pressed={vote === "up"} onClick={() => cast("up")} aria-label="پاسخ خوب بود" title="خوب بود"><ThumbsUp /></button>
          <button type="button" className={cn(actionButton, vote === "down" && "bg-secondary text-foreground")} aria-pressed={vote === "down"} onClick={() => cast("down")} aria-label="پاسخ خوب نبود" title="خوب نبود"><ThumbsDown /></button>
        </>
      )}
      <span role="status" className="sr-only">{copied ? "کپی شد" : ""}</span>
    </div>
  );
}

export interface ChatThreadProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Keeps the view pinned to the newest message while the reader is at the bottom. */
  follow?: boolean;
}

/**
 * رشته‌ی گفت‌وگو. A scrolling log that follows new text while you are at the bottom and
 * leaves you alone once you scroll up to read.
 */
export function ChatThread({ follow = true, className, children, ...props }: ChatThreadProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const pinned = React.useRef(true);

  React.useEffect(() => {
    const el = ref.current;
    if (!el || !follow) return;
    const onScroll = () => { pinned.current = el.scrollHeight - el.scrollTop - el.clientHeight < 48; };
    const observer = new MutationObserver(() => { if (pinned.current) el.scrollTop = el.scrollHeight; });
    observer.observe(el, { childList: true, subtree: true, characterData: true });
    el.addEventListener("scroll", onScroll, { passive: true });
    el.scrollTop = el.scrollHeight;
    return () => { observer.disconnect(); el.removeEventListener("scroll", onScroll); };
  }, [follow]);

  return (
    <div ref={ref} role="log" aria-label="گفت‌وگو" aria-live="polite" tabIndex={0} className={cn("flex flex-col gap-6 overflow-y-auto focus-visible:outline-none", className)} {...props}>
      {children}
    </div>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { CodeBlock } from "@/components/ui/code-block";

/* ------------------------------------------------------------------ direction */

const RTL_LETTERS = /[֐-ࣿיִ-﷿ﹰ-ﻼ]/g;
const LTR_LETTERS = /[A-Za-z]/g;

/**
 * Direction of a block of mixed text. `dir="auto"` only looks at the first strong
 * character, so «React یک کتابخانه است» would flip to LTR; this counts letters instead.
 * Inline code and URLs are ignored because they are always Latin.
 */
export function textDir(text: string): "rtl" | "ltr" | undefined {
  const plain = text.replace(/`[^`]*`/g, "").replace(/https?:\/\/\S+/g, "");
  const rtl = plain.match(RTL_LETTERS)?.length ?? 0;
  const ltr = plain.match(LTR_LETTERS)?.length ?? 0;
  if (rtl === 0) return ltr > 0 ? "ltr" : undefined;
  return rtl >= ltr * 0.3 ? "rtl" : "ltr";
}

/* --------------------------------------------------------------------- parser */

type ListItem = { depth: number; ordered: boolean; text: string; checked?: boolean };
type MdBlock =
  | { type: "heading"; level: number; text: string }
  | { type: "paragraph"; text: string }
  | { type: "code"; lang: string; code: string }
  | { type: "quote"; text: string }
  | { type: "list"; items: ListItem[] }
  | { type: "table"; head: string[]; rows: string[][] }
  | { type: "hr" };

const LIST_RE = /^(\s*)([-*+]|(?:\d+|[۰-۹]+)[.)])\s+(.*)$/;
const TABLE_SEP_RE = /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/;

const cells = (line: string) => line.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((c) => c.trim());

/** Markdown to blocks. Tolerates an unfinished stream: an unclosed fence is still a code block. */
export function parseMarkdownBlocks(src: string): MdBlock[] {
  const lines = src.replace(/\r\n?/g, "\n").split("\n");
  const blocks: MdBlock[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    const fence = line.match(/^\s*```\s*([\w+-]*)\s*$/);
    if (fence) {
      const body: string[] = [];
      i++;
      while (i < lines.length && !/^\s*```\s*$/.test(lines[i])) body.push(lines[i++]);
      i++;
      blocks.push({ type: "code", lang: fence[1], code: body.join("\n") });
      continue;
    }

    const heading = line.match(/^(#{1,4})\s+(.*)$/);
    if (heading) { blocks.push({ type: "heading", level: heading[1].length, text: heading[2].trim() }); i++; continue; }

    if (/^\s*([-*_])\s*(\1\s*){2,}$/.test(line)) { blocks.push({ type: "hr" }); i++; continue; }

    if (/^\s*>/.test(line)) {
      const body: string[] = [];
      while (i < lines.length && /^\s*>/.test(lines[i])) body.push(lines[i++].replace(/^\s*>\s?/, ""));
      blocks.push({ type: "quote", text: body.join("\n") });
      continue;
    }

    if (line.includes("|") && i + 1 < lines.length && TABLE_SEP_RE.test(lines[i + 1])) {
      const head = cells(line);
      const rows: string[][] = [];
      i += 2;
      while (i < lines.length && lines[i].includes("|") && lines[i].trim()) rows.push(cells(lines[i++]));
      blocks.push({ type: "table", head, rows });
      continue;
    }

    if (LIST_RE.test(line)) {
      const items: ListItem[] = [];
      while (i < lines.length) {
        const m = lines[i].match(LIST_RE);
        if (m) {
          const task = m[3].match(/^\[([ xX])\]\s+(.*)$/);
          items.push({ depth: Math.min(3, Math.floor(m[1].length / 2)), ordered: !/^[-*+]$/.test(m[2]), text: task ? task[2] : m[3], checked: task ? task[1] !== " " : undefined });
          i++;
        } else if (lines[i].trim() && /^\s{2,}/.test(lines[i]) && items.length) {
          // A wrapped line belongs to the item above it.
          items[items.length - 1].text += " " + lines[i].trim();
          i++;
        } else break;
      }
      blocks.push({ type: "list", items });
      continue;
    }

    const body: string[] = [];
    while (i < lines.length && lines[i].trim() && !/^\s*```/.test(lines[i]) && !/^#{1,4}\s/.test(lines[i]) && !/^\s*>/.test(lines[i]) && !LIST_RE.test(lines[i])) body.push(lines[i++]);
    blocks.push({ type: "paragraph", text: body.join("\n") });
  }
  return blocks;
}

/* --------------------------------------------------------------------- inline */

const INLINE_RE = /(`[^`\n]+`)|(\*\*[^*\n]+\*\*)|(__[^_\n]+__)|(~~[^~\n]+~~)|(\*[^*\n]+\*)|(\[[^\]\n]+\]\([^)\s]+\))/;
const SAFE_HREF = /^(https?:|mailto:|tel:|\/|#)/i;

function inline(text: string, keyBase = "i"): React.ReactNode[] {
  const out: React.ReactNode[] = [];
  let rest = text;
  let n = 0;
  while (rest) {
    const m = rest.match(INLINE_RE);
    if (!m || m.index === undefined) { out.push(rest); break; }
    if (m.index > 0) out.push(rest.slice(0, m.index));
    const tok = m[0];
    const key = `${keyBase}-${n++}`;
    if (tok.startsWith("`")) {
      // Code is isolated and LTR so the surrounding Persian cannot reorder its punctuation.
      out.push(<bdi key={key} dir="ltr"><code className="rounded-md border border-border bg-secondary px-1.5 py-0.5 font-mono text-[0.85em]">{tok.slice(1, -1)}</code></bdi>);
    } else if (tok.startsWith("**") || tok.startsWith("__")) {
      out.push(<strong key={key} className="font-semibold">{inline(tok.slice(2, -2), key)}</strong>);
    } else if (tok.startsWith("~~")) {
      out.push(<del key={key}>{inline(tok.slice(2, -2), key)}</del>);
    } else if (tok.startsWith("*")) {
      out.push(<em key={key}>{inline(tok.slice(1, -1), key)}</em>);
    } else {
      const link = tok.match(/^\[([^\]]+)\]\(([^)\s]+)\)$/)!;
      const href = SAFE_HREF.test(link[2]) ? link[2] : "#";
      const external = /^https?:/i.test(href);
      out.push(
        <a key={key} href={href} target={external ? "_blank" : undefined} rel={external ? "noopener noreferrer" : undefined} className="text-brand underline underline-offset-4 hover:opacity-80">
          <bdi>{inline(link[1], key)}</bdi>
        </a>,
      );
    }
    rest = rest.slice(m.index + tok.length);
  }
  return out;
}

/** Soft line breaks inside a paragraph become <br>. */
function withBreaks(text: string, keyBase: string) {
  return text.split("\n").flatMap((line, i) => (i === 0 ? inline(line, `${keyBase}-${i}`) : [<br key={`${keyBase}-br-${i}`} />, ...inline(line, `${keyBase}-${i}`)]));
}

/* ------------------------------------------------------------------- renderer */

export interface MarkdownProps {
  children: string;
  /** Shows a soft caret after the last block while a model is still writing. */
  streaming?: boolean;
  /** Base direction for blocks with no letters at all (numbers, emoji). */
  dir?: "rtl" | "ltr";
  className?: string;
}

const HEADING = ["", "text-xl font-bold mt-6", "text-lg font-bold mt-6", "text-base font-semibold mt-5", "text-sm font-semibold mt-4"];

/**
 * مارک‌داون راست‌چین. Renders model output where Persian, English and code are mixed:
 * every block gets its own direction, code blocks stay LTR, inline code is bidi-isolated,
 * and ordered lists count in Persian digits when the list is Persian.
 */
export function Markdown({ children, streaming, dir = "rtl", className }: MarkdownProps) {
  const blocks = React.useMemo(() => parseMarkdownBlocks(children), [children]);
  const caret = streaming ? <span aria-hidden className="ms-1 inline-block h-[1em] w-[3px] translate-y-[0.15em] rounded-full bg-foreground/70 motion-safe:animate-pulse" /> : null;

  return (
    <div className={cn("space-y-3 text-sm leading-8 [&>:first-child]:mt-0", className)}>
      {blocks.map((b, i) => {
        const last = i === blocks.length - 1;
        switch (b.type) {
          case "heading": {
            const Tag = `h${Math.min(6, b.level + 1)}` as "h2" | "h3" | "h4" | "h5";
            return <Tag key={i} dir={textDir(b.text) ?? dir} className={HEADING[b.level]}>{inline(b.text, `h${i}`)}{last && caret}</Tag>;
          }
          case "paragraph":
            return <p key={i} dir={textDir(b.text) ?? dir}>{withBreaks(b.text, `p${i}`)}{last && caret}</p>;
          case "code":
            return <CodeBlock key={i} code={b.code} language={b.lang || undefined} />;
          case "quote":
            return <blockquote key={i} dir={textDir(b.text) ?? dir} className="border-s-2 border-border ps-4 text-muted-foreground">{withBreaks(b.text, `q${i}`)}{last && caret}</blockquote>;
          case "hr":
            return <hr key={i} className="border-border" />;
          case "table":
            return (
              <div key={i} dir={textDir(b.head.join(" ")) ?? dir} className="overflow-x-auto rounded-surface border-line border-border">
                <table className="w-full border-collapse text-sm">
                  <thead className="bg-secondary/60">
                    <tr>{b.head.map((h, c) => <th key={c} scope="col" className="px-3 py-2 text-start font-semibold">{inline(h, `th${i}-${c}`)}</th>)}</tr>
                  </thead>
                  <tbody>
                    {b.rows.map((row, r) => (
                      <tr key={r} className="border-t border-border">
                        {row.map((cell, c) => <td key={c} className="px-3 py-2 align-top"><bdi>{inline(cell, `td${i}-${r}-${c}`)}</bdi></td>)}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          case "list": {
            const listDir = textDir(b.items.map((it) => it.text).join(" ")) ?? dir;
            const ordered = b.items[0]?.ordered;
            const List = ordered ? "ol" : "ul";
            return (
              <List key={i} dir={listDir} className={cn("space-y-1 ps-6", ordered ? (listDir === "rtl" ? "[list-style-type:persian]" : "list-decimal") : "list-disc", "marker:text-muted-foreground")}>
                {b.items.map((it, k) => (
                  <li key={k} style={{ marginInlineStart: it.depth ? `${it.depth * 1.25}rem` : undefined }} className={cn(it.checked !== undefined && "list-none -ms-6 flex items-start gap-2")}>
                    {it.checked !== undefined && <input type="checkbox" checked={it.checked} readOnly disabled className="mt-2 size-4 accent-[var(--brand)]" aria-label={it.checked ? "انجام‌شده" : "انجام‌نشده"} />}
                    <span>{inline(it.text, `l${i}-${k}`)}{last && k === b.items.length - 1 && caret}</span>
                  </li>
                ))}
              </List>
            );
          }
        }
      })}
      {blocks.length === 0 && caret}
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Copy } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface CodeBlockProps {
  code: string;
  /** Shown in the header, e.g. "tsx". */
  language?: string;
  /** File name shown instead of the language. */
  filename?: string;
  lineNumbers?: boolean;
  /** 1-based line numbers to tint. */
  highlight?: number[];
  /** CSS max height; the block scrolls beyond it. */
  maxHeight?: string;
  /** Pre-highlighted markup (e.g. from shiki) rendered instead of the plain text. `code` is still what gets copied. */
  children?: React.ReactNode;
  className?: string;
}

/**
 * بلوک کد. Always left-to-right, whatever the page direction: code is never mirrored.
 * The copy button sits at the physical top-right corner of the header, which is where
 * a Persian reader's eye starts.
 */
export function CodeBlock({ code, language, filename, lineNumbers, highlight = [], maxHeight, children, className }: CodeBlockProps) {
  const [copied, setCopied] = React.useState(false);
  const lines = React.useMemo(() => code.replace(/\n$/, "").split("\n"), [code]);
  const marked = React.useMemo(() => new Set(highlight), [highlight]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard blocked; the text stays selectable */
    }
  }

  return (
    <figure dir="ltr" className={cn("my-0 overflow-hidden rounded-surface border-line border-border bg-card text-start", className)}>
      <figcaption className="flex h-10 items-center justify-between gap-3 border-b border-border ps-4 pe-1.5">
        <span className="truncate font-mono text-xs text-muted-foreground">{filename ?? language ?? "code"}</span>
        <button
          type="button"
          onClick={copy}
          dir="rtl"
          className="flex h-7 cursor-pointer items-center gap-1.5 rounded-md px-2 text-xs text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {copied ? <Check className="size-3.5 text-success" /> : <Copy className="size-3.5" />}
          <span aria-live="polite">{copied ? "کپی شد" : "کپی"}</span>
        </button>
      </figcaption>
      <pre tabIndex={0} className="overflow-auto py-3 font-mono text-[13px] leading-6 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring" style={{ maxHeight }}>
        {children ? (
          <code className="block px-4">{children}</code>
        ) : (
          <code className="block w-max min-w-full">
            {lines.map((line, i) => (
              <span key={i} className={cn("flex px-4", marked.has(i + 1) && "bg-brand/10 shadow-[inset_2px_0_0_var(--brand)]")}>
                {lineNumbers && <span aria-hidden className="w-8 shrink-0 select-none pe-4 text-end text-muted-foreground/60">{i + 1}</span>}
                <span className="whitespace-pre">{line || " "}</span>
              </span>
            ))}
          </code>
        )}
      </pre>
      <span className="sr-only" dir="rtl">{fa(lines.length)} خط کد</span>
    </figure>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown, CircleDashed, LoaderCircle, Wrench, X } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type ToolStatus = "pending" | "running" | "success" | "error";

export interface ToolCallProps {
  /** Function name as the model called it, e.g. "search_orders". Shown left-to-right. */
  name: string;
  /** What it does in Persian, e.g. «جست‌وجو در سفارش‌ها». */
  label?: string;
  status: ToolStatus;
  /** Arguments the model sent. Objects are printed as JSON. */
  input?: unknown;
  /** What the tool returned. */
  output?: unknown;
  /** Error message when status is "error". */
  error?: string;
  /** Run time in milliseconds. */
  duration?: number;
  icon?: React.ReactNode;
  defaultOpen?: boolean;
  className?: string;
}

const STATUS: Record<ToolStatus, { label: string; tone: string }> = {
  pending: { label: "در صف", tone: "text-muted-foreground" },
  running: { label: "در حال اجرا", tone: "text-brand" },
  success: { label: "انجام شد", tone: "text-success" },
  error: { label: "ناموفق", tone: "text-destructive" },
};

function StatusIcon({ status }: { status: ToolStatus }) {
  if (status === "running") return <LoaderCircle className="size-4 motion-safe:animate-spin" />;
  if (status === "success") return <Check className="size-4" />;
  if (status === "error") return <X className="size-4" />;
  return <CircleDashed className="size-4" />;
}

const print = (value: unknown) => (typeof value === "string" ? value : JSON.stringify(value, null, 2));

/** Seconds with one decimal under ten seconds: 1240 -> «۱٫۲ ثانیه». */
function formatDuration(ms: number) {
  if (ms < 1000) return `${fa(Math.round(ms))} میلی‌ثانیه`;
  return `${fa((ms / 1000).toFixed(ms < 10_000 ? 1 : 0)).replace(".", "٫")} ثانیه`;
}

/** فراخوانی ابزار. One tool call of an agent: what ran, its state, and the raw input and output on demand. */
export function ToolCall({ name, label, status, input, output, error, duration, icon, defaultOpen = false, className }: ToolCallProps) {
  const [open, setOpen] = React.useState(defaultOpen);
  const id = React.useId();
  const hasBody = input !== undefined || output !== undefined || Boolean(error);
  const s = STATUS[status];

  return (
    <div className={cn("overflow-hidden rounded-surface border-line border-border bg-card text-sm", status === "error" && "border-destructive/40", className)}>
      <button
        type="button"
        disabled={!hasBody}
        aria-expanded={hasBody ? open : undefined}
        aria-controls={hasBody ? id : undefined}
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center gap-3 px-3 py-2.5 text-start transition-colors enabled:cursor-pointer enabled:hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
      >
        <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-secondary text-muted-foreground [&_svg]:size-4">{icon ?? <Wrench />}</span>
        <span className="flex min-w-0 flex-1 flex-col">
          <span className="truncate font-medium">{label ?? name}</span>
          {label && <bdi dir="ltr" className="truncate text-end font-mono text-[11px] text-muted-foreground">{name}</bdi>}
        </span>
        <span className={cn("flex shrink-0 items-center gap-1.5 text-xs", s.tone)}>
          <StatusIcon status={status} />
          <span>{s.label}</span>
          {duration !== undefined && status !== "running" && status !== "pending" && <span className="text-muted-foreground">· {formatDuration(duration)}</span>}
        </span>
        {hasBody && <ChevronDown className={cn("size-4 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} />}
      </button>
      {hasBody && (
        <div id={id} className={cn("grid transition-[grid-template-rows] duration-200 ease-out", open ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
          <div className="min-h-0 overflow-hidden" inert={!open}>
            <div className="space-y-3 border-t border-border p-3">
              {input !== undefined && (
                <div>
                  <p className="mb-1.5 text-xs font-medium text-muted-foreground">ورودی</p>
                  <pre dir="ltr" tabIndex={0} className="max-h-48 overflow-auto rounded-lg bg-secondary/60 p-3 text-start font-mono text-xs leading-6">{print(input)}</pre>
                </div>
              )}
              {output !== undefined && (
                <div>
                  <p className="mb-1.5 text-xs font-medium text-muted-foreground">خروجی</p>
                  <pre dir="ltr" tabIndex={0} className="max-h-64 overflow-auto rounded-lg bg-secondary/60 p-3 text-start font-mono text-xs leading-6">{print(output)}</pre>
                </div>
              )}
              {error && <p role="alert" className="rounded-lg bg-destructive/10 p-3 text-xs leading-6 text-destructive">{error}</p>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/** Groups consecutive tool calls under one caption such as «۳ ابزار اجرا شد». */
export function ToolCallGroup({ children, className }: { children: React.ReactNode; className?: string }) {
  const count = React.Children.count(children);
  return (
    <div className={cn("space-y-2", className)}>
      <p className="text-xs text-muted-foreground">{fa(count)} ابزار اجرا شد</p>
      {children}
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown, Globe } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface Source {
  title: string;
  url: string;
  /** A sentence from the page that backs the claim. */
  snippet?: string;
  /** Your own favicon element. A globe is drawn without it. */
  icon?: React.ReactNode;
}

/** Host of a URL without "www.", or the raw string when it is not a URL. */
export function sourceHost(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

export interface CitationProps {
  /** 1-based number of the source. */
  index: number;
  source?: Source;
  className?: string;
}

/** ارجاع درون‌متنی. A small numbered chip placed after a sentence; it links to the source and to its row in the list. */
export function Citation({ index, source, className }: CitationProps) {
  const label = source ? `منبع ${fa(index)}: ${source.title}` : `منبع ${fa(index)}`;
  return (
    <a
      href={source?.url ?? `#source-${index}`}
      target={source ? "_blank" : undefined}
      rel={source ? "noopener noreferrer" : undefined}
      aria-label={label}
      title={source?.title}
      className={cn("mx-0.5 inline-flex h-5 min-w-5 -translate-y-px items-center justify-center rounded-full bg-secondary px-1.5 align-middle text-[11px] font-medium leading-none text-muted-foreground no-underline transition-colors hover:bg-brand hover:text-brand-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", className)}
    >
      {fa(index)}
    </a>
  );
}

export interface SourcesProps {
  sources: Source[];
  /** "list" shows every source with its snippet; "chips" is a compact wrapping row. */
  variant?: "list" | "chips";
  /** Starts folded behind a «۴ منبع» button. */
  collapsible?: boolean;
  defaultOpen?: boolean;
  title?: string;
  className?: string;
}

/** منابع. The numbered sources of an answer; titles follow their own language and hosts stay left-to-right. */
export function Sources({ sources, variant = "list", collapsible = false, defaultOpen = false, title = "منابع", className }: SourcesProps) {
  const [open, setOpen] = React.useState(!collapsible || defaultOpen);
  const id = React.useId();
  if (sources.length === 0) return null;

  const body =
    variant === "chips" ? (
      <ol className="flex flex-wrap gap-2">
