          <li key={s.url} id={`source-${i + 1}`}>
            <a href={s.url} target="_blank" rel="noopener noreferrer" title={s.title} className="flex h-8 max-w-56 items-center gap-2 rounded-full border border-border bg-card ps-1 pe-3 text-xs transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
              <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-secondary text-[11px] font-medium text-muted-foreground">{fa(i + 1)}</span>
              <bdi dir="ltr" className="truncate text-muted-foreground">{sourceHost(s.url)}</bdi>
            </a>
          </li>
        ))}
      </ol>
    ) : (
      <ol className="grid grid-cols-1 gap-2 sm:grid-cols-2">
        {sources.map((s, i) => (
          <li key={s.url} id={`source-${i + 1}`}>
            <a href={s.url} target="_blank" rel="noopener noreferrer" className="flex h-full gap-3 rounded-xl border border-border bg-card p-3 transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
              <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-secondary text-[11px] font-medium text-muted-foreground">{fa(i + 1)}</span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span dir="auto" className="line-clamp-2 text-sm font-medium leading-6">{s.title}</span>
                {s.snippet && <span dir="auto" className="mt-1 line-clamp-2 text-xs leading-6 text-muted-foreground">{s.snippet}</span>}
                <span className="mt-1.5 flex items-center gap-1.5 text-[11px] text-muted-foreground">
                  <span className="flex size-3.5 items-center justify-center [&_img]:size-full [&_svg]:size-full">{s.icon ?? <Globe />}</span>
                  <bdi dir="ltr" className="truncate">{sourceHost(s.url)}</bdi>
                </span>
              </span>
            </a>
          </li>
        ))}
      </ol>
    );

  if (!collapsible) {
    return (
      <section aria-label={title} className={className}>
        <h3 className="mb-2 text-xs font-semibold text-muted-foreground">{title}</h3>
        {body}
      </section>
    );
  }
  return (
    <section aria-label={title} className={className}>
      <button type="button" aria-expanded={open} aria-controls={id} onClick={() => setOpen((o) => !o)} className="flex h-8 cursor-pointer items-center gap-2 rounded-full border border-border ps-1.5 pe-3 text-xs text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
        <span className="flex -space-x-1.5 space-x-reverse">
          {sources.slice(0, 3).map((s) => <span key={s.url} className="flex size-5 items-center justify-center rounded-full border border-background bg-secondary [&_img]:size-full [&_img]:rounded-full [&_svg]:size-3">{s.icon ?? <Globe />}</span>)}
        </span>
        {fa(sources.length)} منبع
        <ChevronDown className={cn("size-3.5 transition-transform", open && "rotate-180")} />
      </button>
      <div id={id} className={cn("grid transition-[grid-template-rows] duration-200 ease-out", open ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
        <div className="min-h-0 overflow-hidden" inert={!open}><div className="pt-3">{body}</div></div>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export interface ModelOption {
  id: string;
  /** Display name. Latin model names are isolated so they do not reorder Persian text around them. */
  name: string;
  /** One line on what it is good at. */
  description?: string;
  /** Short tag such as «سریع» or «جدید». */
  badge?: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  /** Why it is disabled, e.g. «در پلن حرفه‌ای». */
  disabledReason?: string;
}

export interface ModelPickerProps {
  models: ModelOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (id: string) => void;
  /** Where the panel opens. A picker in a bottom composer usually wants "top". */
  side?: "top" | "bottom";
  align?: "start" | "end";
  size?: "sm" | "md";
  className?: string;
  "aria-label"?: string;
}

/** Index of the next enabled model from `from` in steps of `delta`, wrapping around. */
function stepEnabled(models: ModelOption[], from: number, delta: number) {
  let next = from;
  for (let n = 0; n < models.length; n++) {
    next = (next + delta + models.length) % models.length;
    if (!models[next].disabled) break;
  }
  return next;
}

/** Arrow, Home and End handling shared by the popover and the inline list. Returns true when handled. */
function listKeys(e: React.KeyboardEvent, models: ModelOption[], active: number, setActive: (i: number) => void) {
  if (e.key === "ArrowDown") setActive(stepEnabled(models, active, 1));
  else if (e.key === "ArrowUp") setActive(stepEnabled(models, active, -1));
  else if (e.key === "Home") setActive(models.findIndex((m) => !m.disabled));
  else if (e.key === "End") setActive(models.length - 1 - [...models].reverse().findIndex((m) => !m.disabled));
  else return false;
  e.preventDefault();
  return true;
}

function ModelRows({ models, selected, active, setActive, choose, id }: { models: ModelOption[]; selected: string; active: number; setActive: (i: number) => void; choose: (m: ModelOption) => void; id: string }) {
  return models.map((m, i) => {
    const on = m.id === selected;
    return (
      <div
        key={m.id}
        id={`${id}-${i}`}
        role="option"
        aria-selected={on}
        aria-disabled={m.disabled || undefined}
        onMouseEnter={() => !m.disabled && setActive(i)}
        onClick={() => choose(m)}
        className={cn("flex items-start gap-3 rounded-lg px-2.5 py-2", m.disabled ? "cursor-not-allowed opacity-50" : "cursor-pointer", i === active && !m.disabled && "bg-accent")}
      >
        {m.icon && <span className="mt-0.5 flex size-5 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4">{m.icon}</span>}
        <span className="flex min-w-0 flex-1 flex-col">
          <span className="flex items-center gap-2">
            <bdi className="font-medium">{m.name}</bdi>
            {m.badge && <span className="rounded-full bg-brand/15 px-1.5 py-0.5 text-[10px] font-medium leading-none text-brand">{m.badge}</span>}
          </span>
          {(m.description || (m.disabled && m.disabledReason)) && <span className="mt-0.5 text-xs leading-5 text-muted-foreground">{m.disabled && m.disabledReason ? m.disabledReason : m.description}</span>}
        </span>
        {on && <Check className="mt-1 size-4 shrink-0 text-brand" />}
      </div>
    );
  });
}

export type ModelListProps = Omit<ModelPickerProps, "side" | "align" | "size">;

/**
 * The picker's list on its own, always open: a focusable listbox for a settings page or a
 * model step in onboarding. Arrows move, Enter or Space picks.
 */
export function ModelList({ models, value, defaultValue, onChange, className, "aria-label": ariaLabel = "انتخاب مدل" }: ModelListProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? models.find((m) => !m.disabled)?.id ?? "");
  const selected = value ?? internal;
  const [active, setActive] = React.useState(() => Math.max(0, models.findIndex((m) => m.id === selected)));
  const id = React.useId();
  const choose = (m: ModelOption) => {
    if (m.disabled) return;
    if (value === undefined) setInternal(m.id);
    onChange?.(m.id);
  };
  return (
    <div
      role="listbox"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-activedescendant={`${id}-${active}`}
      onKeyDown={(e) => {
        if (listKeys(e, models, active, setActive)) return;
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); choose(models[active]); }
      }}
      className={cn("rounded-overlay border-line border-border bg-popover p-1.5 text-sm text-popover-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring", className)}
    >
      <ModelRows models={models} selected={selected} active={active} setActive={setActive} choose={choose} id={id} />
    </div>
  );
}

/** انتخاب مدل. A compact trigger that opens a listbox of models with a description and a tag each. */
export function ModelPicker({ models, value, defaultValue, onChange, side = "top", align = "start", size = "sm", className, "aria-label": ariaLabel = "انتخاب مدل" }: ModelPickerProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? models.find((m) => !m.disabled)?.id ?? "");
  const selected = value ?? internal;
  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(0);
  const root = React.useRef<HTMLDivElement>(null);
  const trigger = React.useRef<HTMLButtonElement>(null);
  const id = React.useId();
  const { mounted, style, theme, panel, update } = useFloat(open, root, { side, align });
  const current = models.find((m) => m.id === selected);

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (!eventInside(e, root.current, panel.current)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open, panel]);

  // Once the panel has its real height, re-place it (it may need to flip) and move focus in.
  React.useEffect(() => {
    if (!open) return;
    update();
    panel.current?.focus();
  }, [open, update, panel]);

  function show() {
    setActive(Math.max(0, models.findIndex((m) => m.id === selected)));
    update();
    setOpen(true);
  }

  function close(focusTrigger = true) {
    setOpen(false);
    if (focusTrigger) trigger.current?.focus();
  }

  function choose(m: ModelOption) {
    if (m.disabled) return;
    if (value === undefined) setInternal(m.id);
    onChange?.(m.id);
    close();
  }

  function onKeyDown(e: React.KeyboardEvent) {
    if (listKeys(e, models, active, setActive)) return;
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); choose(models[active]); }
    else if (e.key === "Escape") { e.preventDefault(); close(); }
    else if (e.key === "Tab") close(false);
  }

  return (
    <div ref={root} className={cn("inline-block", className)}>
      <button
        ref={trigger}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        aria-label={`${ariaLabel}: ${current?.name ?? ""}`}
        onClick={() => (open ? close() : show())}
        onKeyDown={(e) => { if (!open && (e.key === "ArrowDown" || e.key === "ArrowUp")) { e.preventDefault(); show(); } }}
        className={cn(
          "flex cursor-pointer items-center gap-1.5 rounded-control text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          size === "sm" ? "h-8 px-2.5 text-xs" : "h-10 border-line border-input px-3 text-sm",
        )}
      >
        {current?.icon && <span className="flex size-4 items-center justify-center [&_svg]:size-4">{current.icon}</span>}
        <bdi>{current?.name ?? "انتخاب مدل"}</bdi>
        <ChevronDown className={cn("size-3.5 transition-transform", open && "rotate-180")} />
      </button>
      <FloatPortal
        open={open}
        mounted={mounted}
        style={style}
        theme={theme}
        panelRef={panel}
        id={id}
        role="listbox"
        tabIndex={-1}
        aria-label={ariaLabel}
        aria-activedescendant={`${id}-${active}`}
        onKeyDown={onKeyDown}
        className="fixed z-50 w-72 max-w-[calc(100vw-1rem)] rounded-overlay border-line border-border bg-popover p-1.5 text-sm text-popover-foreground shadow-overlay outline-none [backdrop-filter:var(--surface-filter)] animate-fade-up [animation-duration:180ms]"
      >
        <ModelRows models={models} selected={selected} active={active} setActive={setActive} choose={choose} id={id} />
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, formatJalali, jalaliMonthLength, toGregorian, toJalali } from "@/lib/jalali";

const ITEM = 40;
const VISIBLE = 5;

export interface WheelOption { value: number; label: string }

export interface WheelPickerProps {
  options: WheelOption[];
  value: number;
  onChange: (value: number) => void;
  "aria-label": string;
  className?: string;
}

/**
 * چرخ انتخاب. One scroll-snap column: the row under the center band is the value.
 * Touch, wheel and trackpad scroll natively; ArrowUp/Down, PageUp/Down, Home and End
 * move it from the keyboard.
 */
export function WheelPicker({ options, value, onChange, className, ...aria }: WheelPickerProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const timer = React.useRef<number | undefined>(undefined);
  const id = React.useId();
  const index = Math.max(0, options.findIndex((o) => o.value === value));

  // Keep the scroll position in step with the value (also when the option list shrinks).
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const target = index * ITEM;
    if (Math.abs(el.scrollTop - target) > 1) el.scrollTo({ top: target, behavior: el.dataset.ready ? "smooth" : "auto" });
    el.dataset.ready = "1";
  }, [index, options.length]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  function onScroll() {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      const el = ref.current;
      if (!el) return;
      const next = options[Math.min(options.length - 1, Math.max(0, Math.round(el.scrollTop / ITEM)))];
      if (next && next.value !== value) onChange(next.value);
    }, 90);
  }

  function step(delta: number) {
    const next = options[Math.min(options.length - 1, Math.max(0, index + delta))];
    if (next && next.value !== value) onChange(next.value);
  }

  function onKeyDown(e: React.KeyboardEvent) {
    const map: Record<string, number> = { ArrowDown: 1, ArrowUp: -1, PageDown: VISIBLE, PageUp: -VISIBLE, Home: -options.length, End: options.length };
    const delta = map[e.key];
    if (delta === undefined) return;
    e.preventDefault();
    step(delta);
  }

  return (
    <div className={cn("relative flex-1", className)} style={{ height: ITEM * VISIBLE }}>
      <div
        ref={ref}
        role="listbox"
        tabIndex={0}
        aria-label={aria["aria-label"]}
        aria-activedescendant={`${id}-${index}`}
        onScroll={onScroll}
        onKeyDown={onKeyDown}
        className="h-full snap-y snap-mandatory overflow-y-auto overscroll-contain rounded-lg [scrollbar-width:none] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring [&::-webkit-scrollbar]:hidden"
        style={{ paddingBlock: ITEM * ((VISIBLE - 1) / 2), maskImage: "linear-gradient(to bottom, transparent, black 30%, black 70%, transparent)" }}
      >
        {options.map((o, i) => (
          <div
            key={o.value}
            id={`${id}-${i}`}
            role="option"
            aria-selected={i === index}
            onClick={() => onChange(o.value)}
            className={cn("flex cursor-pointer snap-center items-center justify-center text-base tabular-nums transition-colors", i === index ? "font-semibold text-foreground" : "text-muted-foreground")}
            style={{ height: ITEM }}
          >
            {o.label}
          </div>
        ))}
      </div>
    </div>
  );
}

export interface WheelDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (date: Date) => void;
  /** First and last Jalali year on the year wheel. Defaults to 100 years back through 5 ahead. */
  minYear?: number;
  maxYear?: number;
  /** Hides the line that reads the chosen date back. */
  hideSummary?: boolean;
  className?: string;
}

/**
 * تاریخ چرخشی. The three-wheel Jalali picker Iranian apps use for birthdays and
 * appointments: روز on the right, ماه in the middle, سال on the left. The day wheel
 * shortens for 30-day months and for اسفند outside leap years.
 */
export function WheelDatePicker({ value, defaultValue = null, onChange, minYear, maxYear, hideSummary, className }: WheelDatePickerProps) {
  const [internal, setInternal] = React.useState<Date | null>(defaultValue);
  const [today] = React.useState(() => new Date());
  const date = (value !== undefined ? value : internal) ?? today;
  const { jy, jm, jd } = toJalali(date);
  const thisYear = toJalali(today).jy;
  const from = minYear ?? thisYear - 100;
  const to = maxYear ?? thisYear + 5;

  const years = React.useMemo(() => Array.from({ length: to - from + 1 }, (_, i) => ({ value: to - i, label: fa(to - i) })), [from, to]);
  const months = React.useMemo(() => JALALI_MONTHS.map((m, i) => ({ value: i + 1, label: m })), []);
  const dayCount = jalaliMonthLength(jy, jm);
  const days = React.useMemo(() => Array.from({ length: dayCount }, (_, i) => ({ value: i + 1, label: fa(i + 1) })), [dayCount]);

  function set(y: number, m: number, d: number) {
    const next = toGregorian(y, m, Math.min(d, jalaliMonthLength(y, m)));
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  return (
    <div className={cn("w-full max-w-xs", className)}>
      <div role="group" aria-label="انتخاب تاریخ" className="relative flex gap-1 rounded-surface border-line border-border bg-card px-2">
        <div aria-hidden className="pointer-events-none absolute inset-x-2 top-1/2 -translate-y-1/2 rounded-lg bg-secondary" style={{ height: ITEM }} />
        <WheelPicker aria-label="روز" options={days} value={Math.min(jd, dayCount)} onChange={(d) => set(jy, jm, d)} />
        <WheelPicker aria-label="ماه" options={months} value={jm} onChange={(m) => set(jy, m, jd)} className="flex-[1.4]" />
        <WheelPicker aria-label="سال" options={years} value={Math.min(to, Math.max(from, jy))} onChange={(y) => set(y, jm, jd)} />
      </div>
      {!hideSummary && <p aria-live="polite" className="mt-3 text-center text-sm text-muted-foreground">{formatJalali(date, { weekday: true, year: true })}</p>}
    </div>
  );
}

"use client";

import * as React from "react";
import { Select } from "@/components/ui/select";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, jalaliMonthLength, toGregorian, toJalali } from "@/lib/jalali";

export interface BirthdayPickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  /** Called with a Date once all three parts make a real day, and with null while incomplete or invalid. */
  onChange?: (date: Date | null, age: number | null) => void;
  /** Rejects dates younger than this many full years. */
  minAge?: number;
  /** Oldest age on the year list. */
  maxAge?: number;
  /** Form field name; submits the Gregorian date as YYYY-MM-DD. */
  name?: string;
  id?: string;
  disabled?: boolean;
  className?: string;
}

/** Full years between a birth date and now, counted on the Jalali calendar. */
export function jalaliAge(birth: Date, now = new Date()): number {
  const b = toJalali(birth);
  const n = toJalali(now);
  return n.jy - b.jy - (n.jm < b.jm || (n.jm === b.jm && n.jd < b.jd) ? 1 : 0);
}

const pad = (n: number) => String(n).padStart(2, "0");

/**
 * تاریخ تولد. Three native selects (روز، ماه، سال) instead of a calendar: nobody wants to
 * page back forty years month by month. Days follow the month length and leap years,
 * and the age is shown as soon as the date is complete.
 */
export function BirthdayPicker({ value, defaultValue = null, onChange, minAge = 0, maxAge = 100, name, id, disabled, className }: BirthdayPickerProps) {
  const initial = value ?? defaultValue;
  const [parts, setParts] = React.useState(() => (initial ? toJalali(initial) : { jy: 0, jm: 0, jd: 0 }));
  const [seen, setSeen] = React.useState(value);
  // Controlled value changed from outside: adopt it during render.
  if (value !== undefined && value !== seen) {
    setSeen(value);
    if (value) setParts(toJalali(value));
  }

  const [thisYear] = React.useState(() => toJalali(new Date()).jy);
  const autoId = React.useId();
  const base = id ?? autoId;

  const dayCount = parts.jy && parts.jm ? jalaliMonthLength(parts.jy, parts.jm) : parts.jm > 6 ? 30 : 31;
  const complete = parts.jy > 0 && parts.jm > 0 && parts.jd > 0;
  const realDay = complete && parts.jd <= jalaliMonthLength(parts.jy, parts.jm);
  const date = realDay ? toGregorian(parts.jy, parts.jm, parts.jd) : null;
  const age = date ? jalaliAge(date) : null;
  const tooYoung = age !== null && age < minAge;
  const inFuture = age !== null && age < 0;
  const error = complete && !realDay ? `${JALALI_MONTHS[parts.jm - 1]} ${fa(parts.jy)} فقط ${fa(jalaliMonthLength(parts.jy, parts.jm))} روز دارد.` : inFuture ? "این تاریخ هنوز نرسیده است." : tooYoung ? `سن باید دست‌کم ${fa(minAge)} سال باشد.` : "";

  function update(next: typeof parts) {
    setParts(next);
    const ok = next.jy > 0 && next.jm > 0 && next.jd > 0 && next.jd <= jalaliMonthLength(next.jy, next.jm);
    const d = ok ? toGregorian(next.jy, next.jm, next.jd) : null;
    const a = d ? jalaliAge(d) : null;
    onChange?.(d && a !== null && a >= Math.max(0, minAge) ? d : null, a);
  }

  const years = React.useMemo(() => Array.from({ length: maxAge + 1 }, (_, i) => ({ value: String(thisYear - i), label: fa(thisYear - i) })), [thisYear, maxAge]);
  const months = JALALI_MONTHS.map((m, i) => ({ value: String(i + 1), label: m }));
  const days = Array.from({ length: 31 }, (_, i) => ({ value: String(i + 1), label: fa(i + 1), disabled: i + 1 > dayCount }));

  return (
    <fieldset disabled={disabled} className={cn("min-w-0", className)} aria-describedby={`${base}-hint`}>
      <legend className="sr-only">تاریخ تولد</legend>
      <div className="grid grid-cols-[1fr_1.4fr_1.2fr] gap-2">
        <Select id={`${base}-day`} aria-label="روز" autoComplete="bday-day" placeholder="روز" value={parts.jd ? String(parts.jd) : ""} options={days} aria-invalid={error ? true : undefined} onChange={(e) => update({ ...parts, jd: Number(e.target.value) })} />
        <Select id={`${base}-month`} aria-label="ماه" placeholder="ماه" value={parts.jm ? String(parts.jm) : ""} options={months} onChange={(e) => update({ ...parts, jm: Number(e.target.value) })} />
        <Select id={`${base}-year`} aria-label="سال" placeholder="سال" value={parts.jy ? String(parts.jy) : ""} options={years} onChange={(e) => update({ ...parts, jy: Number(e.target.value) })} />
      </div>
      {name && <input type="hidden" name={name} value={date && !error ? `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` : ""} />}
      <p id={`${base}-hint`} aria-live="polite" className={cn("mt-1.5 min-h-5 text-xs", error ? "text-destructive" : "text-muted-foreground")}>
        {error || (age !== null ? `${fa(age)} ساله` : "")}
      </p>
    </fieldset>
  );
}

"use client";

import * as React from "react";
import { Check, Droplets, Flame, Landmark, Phone, Receipt, Smartphone, TrafficCone, Zap, type LucideIcon } from "lucide-react";
import { cn, fa, faNumber } from "@/lib/utils";
import { billAmountRial, billType, isBillId, isPaymentId, normalizeBillId } from "@/lib/persian";

export type BillValue = { billId: string; paymentId: string };

export interface BillInputProps {
  value?: BillValue;
  defaultValue?: BillValue;
  /** `valid` is true only when both ids pass their check digits together. `amount` is in toman. */
  onChange?: (value: BillValue, info: { valid: boolean; type: string | null; amount: number }) => void;
  disabled?: boolean;
  className?: string;
  id?: string;
}

const ICONS: Record<string, LucideIcon> = {
  "آب": Droplets,
  "برق": Zap,
  "گاز": Flame,
  "تلفن ثابت": Phone,
  "تلفن همراه": Smartphone,
  "عوارض شهرداری": Landmark,
  "مالیات": Landmark,
  "جریمه‌ی رانندگی": TrafficCone,
};

/** Icon for a bill kind, with a receipt for unknown kinds. */
function BillIcon({ type, className }: { type: string | null; className?: string }) {
  return React.createElement((type && ICONS[type]) || Receipt, { className });
}

const field = "h-10 w-full rounded-field border-line-field bg-field shadow-field px-3 font-mono text-sm tracking-wide outline-none transition-colors placeholder:text-muted-foreground/50 focus-visible:ring-2 focus-visible:ring-ring/60 disabled:cursor-not-allowed disabled:opacity-50";

/**
 * شناسه‌ی قبض و پرداخت. Both ids are checked with the bill check-digit algorithm; the
 * bill kind (آب، برق، گاز، …) and the amount are read out of the numbers themselves,
 * so the user sees what they are about to pay before any request is made.
 */
export function BillInput({ value, defaultValue, onChange, disabled, className, id }: BillInputProps) {
  const [internal, setInternal] = React.useState<BillValue>(defaultValue ?? { billId: "", paymentId: "" });
  const v = value ?? internal;
  const autoId = React.useId();
  const base = id ?? autoId;

  const billOk = isBillId(v.billId);
  const type = billOk ? billType(v.billId) : null;
  const payOk = billOk && isPaymentId(v.billId, v.paymentId);
  const amount = payOk ? billAmountRial(v.paymentId) / 10 : 0;
  const billError = v.billId.length >= 6 && !billOk;
  const payError = billOk && v.paymentId.length >= 6 && !payOk;

  function set(patch: Partial<BillValue>) {
    const next = { ...v, ...patch };
    if (value === undefined) setInternal(next);
    const ok = isBillId(next.billId) && isPaymentId(next.billId, next.paymentId);
    onChange?.(next, { valid: ok, type: isBillId(next.billId) ? billType(next.billId) : null, amount: ok ? billAmountRial(next.paymentId) / 10 : 0 });
  }

  return (
    <div className={cn("space-y-3", className)}>
      <div>
        <label htmlFor={`${base}-bill`} className="text-sm font-medium">شناسه‌ی قبض</label>
        <div className="relative mt-1.5" dir="ltr">
          <input
            id={`${base}-bill`}
            inputMode="numeric"
            autoComplete="off"
            disabled={disabled}
            value={v.billId}
            onChange={(e) => set({ billId: normalizeBillId(e.target.value) })}
            placeholder="0000000000000"
            aria-invalid={billError || undefined}
            aria-describedby={`${base}-bill-hint`}
            className={cn(field, "pe-9", billError ? "border-destructive/60" : "border-input")}
          />
          {billOk && <Check className="pointer-events-none absolute end-3 top-1/2 size-4 -translate-y-1/2 text-success" />}
        </div>
        <p id={`${base}-bill-hint`} className={cn("mt-1.5 flex items-center gap-1.5 text-[11px]", billError ? "text-destructive" : "text-muted-foreground")}>
          {billError ? "شناسه‌ی قبض درست نیست." : type ? (<><BillIcon type={type} className="size-3" />قبض {type}</>) : "تا ۱۳ رقم، روی قبض چاپ شده"}
        </p>
      </div>
      <div>
        <label htmlFor={`${base}-pay`} className="text-sm font-medium">شناسه‌ی پرداخت</label>
        <div className="relative mt-1.5" dir="ltr">
          <input
            id={`${base}-pay`}
            inputMode="numeric"
            autoComplete="off"
            disabled={disabled}
            value={v.paymentId}
            onChange={(e) => set({ paymentId: normalizeBillId(e.target.value) })}
            placeholder="0000000000000"
            aria-invalid={payError || undefined}
            aria-describedby={`${base}-pay-hint`}
            className={cn(field, "pe-9", payError ? "border-destructive/60" : "border-input")}
          />
          {payOk && <Check className="pointer-events-none absolute end-3 top-1/2 size-4 -translate-y-1/2 text-success" />}
        </div>
        <p id={`${base}-pay-hint`} className={cn("mt-1.5 text-[11px]", payError ? "text-destructive" : "text-muted-foreground")}>
          {payError ? "شناسه‌ی پرداخت با این قبض جور نیست." : "با هر دوره‌ی قبض عوض میشه"}
        </p>
      </div>
      <div aria-live="polite">
        {payOk && (
          <div className="flex items-center gap-3 rounded-surface border-line border-border bg-card p-3">
            <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-secondary"><BillIcon type={type} className="size-5" /></span>
            <div className="min-w-0 flex-1">
              <p className="text-sm font-medium">قبض {type ?? "خدمات"}</p>
              <p className="text-xs text-muted-foreground">شناسه‌ی {fa(v.billId)}</p>
            </div>
            <p className="text-end">
              <span className="text-base font-bold tabular-nums">{faNumber(amount)}</span>{" "}
              <span className="text-xs text-muted-foreground">تومان</span>
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Building2, Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { isLegalId, normalizeLegalId } from "@/lib/persian";

export interface LegalIdInputProps {
  value?: string;
  onChange?: (id: string, valid: boolean) => void;
  disabled?: boolean;
  className?: string;
  id?: string;
  name?: string;
}

/** شناسه‌ی ملی. The 11-digit id of companies and organisations, with its check digit verified as you type. */
export function LegalIdInput({ value, onChange, disabled, className, id, name }: LegalIdInputProps) {
  const [internal, setInternal] = React.useState("");
  const digits = normalizeLegalId(value ?? internal);
  const complete = digits.length === 11;
  const valid = complete && isLegalId(digits);
  const autoId = React.useId();
  const hintId = `${id ?? autoId}-hint`;

  function set(raw: string) {
    const next = normalizeLegalId(raw);
    if (value === undefined) setInternal(next);
    onChange?.(next, isLegalId(next));
  }

  return (
    <div className={cn("space-y-1.5", className)}>
      <div dir="ltr" className={cn("flex h-10 items-center gap-2 rounded-field border-line-field bg-field shadow-field px-3 transition-colors focus-within:ring-2 focus-within:ring-ring/60", complete && !valid ? "border-destructive/60" : "border-input", disabled && "opacity-50")}>
        <Building2 className="size-4 shrink-0 text-muted-foreground" />
        <input
          id={id}
          name={name}
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={digits}
          onChange={(e) => set(e.target.value)}
          placeholder="00000000000"
          aria-invalid={complete && !valid ? true : undefined}
          aria-describedby={hintId}
          className="h-full min-w-0 flex-1 bg-transparent font-mono text-sm tracking-widest outline-none placeholder:text-muted-foreground/50 disabled:cursor-not-allowed"
        />
        {valid && <Check className="size-4 shrink-0 text-success" />}
      </div>
      <p id={hintId} className={cn("text-[11px]", complete && !valid ? "text-destructive" : "text-muted-foreground")}>
        {complete && !valid ? "شناسه‌ی ملی معتبر نیست." : valid ? "شناسه‌ی ملی معتبر است." : "۱۱ رقم، برای شرکت‌ها و سازمان‌ها"}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { Slider } from "@/components/ui/slider";
import { cn, fa, faNumber, faPercent } from "@/lib/utils";

export interface InstallmentPlan {
  /** Amount financed after the down payment. */
  principal: number;
  downPayment: number;
  /** One instalment, rounded up to the nearest 1,000 toman. */
  monthly: number;
  /** Everything paid: down payment plus all instalments. */
  total: number;
  /** Total minus the cash price. */
  interest: number;
  months: number;
}

/**
 * Equal instalments on a reducing balance (the formula Iranian banks publish):
 * monthly = P·r·(1+r)^n / ((1+r)^n − 1), with r the yearly rate divided by 1200.
 * A zero rate simply divides the principal.
 */
export function calculateInstallments(price: number, downPayment: number, months: number, yearlyRate: number): InstallmentPlan {
  const principal = Math.max(0, price - downPayment);
  const r = yearlyRate / 1200;
  const raw = months <= 0 ? 0 : r === 0 ? principal / months : (principal * r * (1 + r) ** months) / ((1 + r) ** months - 1);
  const monthly = Math.ceil(raw / 1000) * 1000;
  const total = downPayment + monthly * months;
  return { principal, downPayment, monthly, total, interest: Math.max(0, total - price), months };
}

export interface InstallmentCalculatorProps {
  /** Cash price in toman. */
  price: number;
  /** Offered terms in months. */
  terms?: number[];
  defaultTerm?: number;
  /** Yearly rate in percent. Pass a function to charge longer terms more. */
  rate?: number | ((months: number) => number);
  /** Down payment bounds as a share of the price, 0 to 1. */
  minDownPayment?: number;
  maxDownPayment?: number;
  defaultDownPayment?: number;
  onChange?: (plan: InstallmentPlan) => void;
  /** Slot under the result, e.g. a «ثبت درخواست» button. */
  footer?: React.ReactNode;
  className?: string;
}

/** محاسبه‌گر اقساط. Down payment and term on top, the monthly instalment and the cost of credit underneath. */
export function InstallmentCalculator({ price, terms = [6, 12, 18, 24], defaultTerm, rate = 23, minDownPayment = 0.2, maxDownPayment = 0.8, defaultDownPayment = 0.3, onChange, footer, className }: InstallmentCalculatorProps) {
  const [share, setShare] = React.useState(Math.round(defaultDownPayment * 100));
  const [months, setMonths] = React.useState(defaultTerm ?? terms[Math.min(1, terms.length - 1)]);
  const name = React.useId();

  const yearly = typeof rate === "function" ? rate(months) : rate;
  const downPayment = Math.round((price * share) / 100 / 1000) * 1000;
  const plan = calculateInstallments(price, downPayment, months, yearly);

  function update(nextShare: number, nextMonths: number) {
    setShare(nextShare);
    setMonths(nextMonths);
    const y = typeof rate === "function" ? rate(nextMonths) : rate;
    onChange?.(calculateInstallments(price, Math.round((price * nextShare) / 100 / 1000) * 1000, nextMonths, y));
  }

  return (
    <div className={cn("w-full rounded-surface border-line border-border bg-card p-5", className)}>
      <div className="flex items-baseline justify-between gap-3">
        <span className="text-sm text-muted-foreground">قیمت نقدی</span>
        <span className="text-sm font-semibold tabular-nums">{faNumber(price)} تومان</span>
      </div>

      <Slider
        className="mt-5"
        label="پیش‌پرداخت"
        value={share}
        onChange={(v) => update(v, months)}
        min={Math.round(minDownPayment * 100)}
        max={Math.round(maxDownPayment * 100)}
        step={5}
        format={(v) => `${faNumber(Math.round((price * v) / 100 / 1000) * 1000)} تومان (${faPercent(v)})`}
      />

      <fieldset className="mt-5">
        <legend className="text-sm font-medium">مدت بازپرداخت</legend>
        <div className="mt-2 grid gap-2" style={{ gridTemplateColumns: `repeat(${Math.min(terms.length, 4)}, minmax(0, 1fr))` }}>
          {terms.map((t) => (
            <label key={t} className={cn("flex h-10 cursor-pointer items-center justify-center rounded-control border-line text-sm transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring", t === months ? "border-foreground/50 bg-secondary font-semibold" : "border-border text-muted-foreground hover:bg-accent")}>
              <input type="radio" name={name} value={t} checked={t === months} onChange={() => update(share, t)} className="sr-only" />
              {fa(t)} ماهه
            </label>
          ))}
        </div>
      </fieldset>

      <div aria-live="polite" className="mt-5 rounded-xl bg-secondary/60 p-4">
        <p className="text-xs text-muted-foreground">مبلغ هر قسط</p>
        <p className="mt-1 flex items-baseline gap-2">
          <span className="text-3xl font-bold tabular-nums">{faNumber(plan.monthly)}</span>
          <span className="text-sm text-muted-foreground">تومان در ماه</span>
        </p>
        <dl className="mt-4 space-y-2 border-t border-border pt-3 text-sm">
          <div className="flex justify-between gap-3"><dt className="text-muted-foreground">مبلغ تسهیلات</dt><dd className="tabular-nums">{faNumber(plan.principal)} تومان</dd></div>
          <div className="flex justify-between gap-3"><dt className="text-muted-foreground">نرخ سود سالانه</dt><dd className="tabular-nums">{faPercent(yearly)}</dd></div>
          <div className="flex justify-between gap-3"><dt className="text-muted-foreground">سود کل دوره</dt><dd className="tabular-nums">{faNumber(plan.interest)} تومان</dd></div>
          <div className="flex justify-between gap-3 font-semibold"><dt>جمع پرداختی</dt><dd className="tabular-nums">{faNumber(plan.total)} تومان</dd></div>
        </dl>
      </div>
      {footer && <div className="mt-4">{footer}</div>}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, faNumber } from "@/lib/utils";

export type CurrencyUnit = "toman" | "rial";

const LABEL: Record<CurrencyUnit, string> = { toman: "تومان", rial: "ریال" };
const STORAGE_KEY = "currency-unit";

type CurrencyContextValue = { unit: CurrencyUnit; setUnit: (unit: CurrencyUnit) => void };
const CurrencyContext = React.createContext<CurrencyContextValue | null>(null);

/** Amount in the chosen unit. Amounts are always stored in toman; rial is ten times that. */
export function convertToman(toman: number, unit: CurrencyUnit) {
  return unit === "rial" ? toman * 10 : toman;
}

/** «۱۲٬۴۵۰٬۰۰۰ تومان» or «۱۲۴٬۵۰۰٬۰۰۰ ریال». */
export function formatMoney(toman: number, unit: CurrencyUnit) {
  return `${faNumber(convertToman(toman, unit))} ${LABEL[unit]}`;
}

const listeners = new Set<() => void>();
function readStored(fallback: CurrencyUnit): CurrencyUnit {
  try {
    const v = window.localStorage.getItem(STORAGE_KEY);
    return v === "rial" || v === "toman" ? v : fallback;
  } catch {
    return fallback;
  }
}

export interface CurrencyProviderProps {
  /** Unit used on the server and before any choice is stored. */
  defaultUnit?: CurrencyUnit;
  /** Remember the choice in localStorage. */
  persist?: boolean;
  children: React.ReactNode;
}

/**
 * واحد پول. Holds the visitor's choice between تومان and ریال for every <Money> below it.
 * People say prices in toman while invoices, bank receipts and the tax system are in rial,
 * so shops and accounting apps let the reader switch.
 */
export function CurrencyProvider({ defaultUnit = "toman", persist = true, children }: CurrencyProviderProps) {
  const [memory, setMemory] = React.useState(defaultUnit);
  // The stored value is read through useSyncExternalStore so server and first client render agree.
  const stored = React.useSyncExternalStore(
    (notify) => { listeners.add(notify); window.addEventListener("storage", notify); return () => { listeners.delete(notify); window.removeEventListener("storage", notify); }; },
    () => readStored(defaultUnit),
    () => defaultUnit,
  );
  const unit = persist ? stored : memory;

  const setUnit = React.useCallback((next: CurrencyUnit) => {
    setMemory(next);
    if (!persist) return;
    try { window.localStorage.setItem(STORAGE_KEY, next); } catch { /* private mode */ }
    listeners.forEach((notify) => notify());
  }, [persist]);

  const ctx = React.useMemo(() => ({ unit, setUnit }), [unit, setUnit]);
  return <CurrencyContext.Provider value={ctx}>{children}</CurrencyContext.Provider>;
}

/** The current unit and its setter. Falls back to toman outside a provider. */
export function useCurrency(): CurrencyContextValue {
  return React.useContext(CurrencyContext) ?? { unit: "toman", setUnit: () => {} };
}

export interface MoneyProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Amount in toman. */
  amount: number;
  /** Hides the unit word, for table columns whose header already names it. */
  bare?: boolean;
}

/** مبلغ. Renders a toman amount in whichever unit the provider holds. */
export function Money({ amount, bare, className, ...props }: MoneyProps) {
  const { unit } = useCurrency();
  return (
    <span className={cn("whitespace-nowrap tabular-nums", className)} {...props}>
      {faNumber(convertToman(amount, unit))}
      {!bare && <span className="ms-1 text-[0.8em] font-normal text-muted-foreground">{LABEL[unit]}</span>}
    </span>
  );
}

export interface CurrencyToggleProps {
  size?: "sm" | "md";
  className?: string;
}

/** کلید تومان و ریال. A two-option switch; ArrowLeft and ArrowRight move between the units. */
export function CurrencyToggle({ size = "md", className }: CurrencyToggleProps) {
  const { unit, setUnit } = useCurrency();
  const units: CurrencyUnit[] = ["toman", "rial"];

  function onKeyDown(e: React.KeyboardEvent<HTMLDivElement>) {
    if (e.key !== "ArrowLeft" && e.key !== "ArrowRight" && e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
    e.preventDefault();
    const next = unit === "toman" ? "rial" : "toman";
    setUnit(next);
    e.currentTarget.querySelector<HTMLElement>(`[data-unit="${next}"]`)?.focus();
  }

  return (
    <div role="radiogroup" aria-label="واحد پول" onKeyDown={onKeyDown} className={cn("inline-flex rounded-control border-line border-border bg-secondary/60 p-0.5", className)}>
      {units.map((u) => (
        <button
          key={u}
          type="button"
          role="radio"
          data-unit={u}
          aria-checked={unit === u}
          tabIndex={unit === u ? 0 : -1}
          onClick={() => setUnit(u)}
          className={cn(
            "cursor-pointer rounded-[calc(var(--shape-control)-2px)] font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            size === "sm" ? "h-7 px-2.5 text-xs" : "h-8 px-3.5 text-sm",
            unit === u ? "bg-card text-foreground shadow-control" : "text-muted-foreground hover:text-foreground",
          )}
        >
          {LABEL[u]}
        </button>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

const UNITS: [limit: number, seconds: number, name: string][] = [
  [60, 1, "ثانیه"],
  [3600, 60, "دقیقه"],
  [86400, 3600, "ساعت"],
  [86400 * 30, 86400, "روز"],
  [86400 * 365, 86400 * 30, "ماه"],
  [Infinity, 86400 * 365, "سال"],
];

/**
 * Persian relative time in both directions: «همین حالا»، «۵ دقیقه پیش»، «دیروز»،
 * «۳ روز دیگر»، «فردا». Past uses «پیش» and future uses «دیگر».
 */
export function relativeTime(date: Date, now = new Date()): string {
  const diff = Math.round((date.getTime() - now.getTime()) / 1000);
  const abs = Math.abs(diff);
  if (abs < 45) return "همین حالا";
  const [, size, name] = UNITS.find(([limit]) => abs < limit)!;
  const n = Math.max(1, Math.round(abs / size));
  if (name === "روز" && n === 1) return diff < 0 ? "دیروز" : "فردا";
  if (name === "روز" && n === 2) return diff < 0 ? "پریروز" : "پس‌فردا";
  return `${fa(n)} ${name} ${diff < 0 ? "پیش" : "دیگر"}`;
}

/** Seconds until the label would change, so the timer wakes only when it has to. */
function nextTick(date: Date, now: Date) {
  const abs = Math.abs(date.getTime() - now.getTime()) / 1000;
  if (abs < 60) return 10;
  if (abs < 3600) return 30;
  if (abs < 86400) return 300;
  return 3600;
}

export interface RelativeTimeProps extends Omit<React.TimeHTMLAttributes<HTMLTimeElement>, "dateTime"> {
  date: Date | string | number;
  /** Keep the label fresh while the page is open. */
  live?: boolean;
  /** After this many days the full Jalali date is shown instead of «… پیش». */
  absoluteAfterDays?: number;
}

/**
 * زمان نسبی. A <time> element that says «۳ دقیقه پیش» and keeps itself up to date. The exact
 * Jalali date and time are in the tooltip and in `dateTime` for machines. It renders the
 * absolute date on the server and switches after mount, so hydration never mismatches.
 */
export function RelativeTime({ date, live = true, absoluteAfterDays = 30, className, ...props }: RelativeTimeProps) {
  const d = React.useMemo(() => new Date(date), [date]);
  const [now, setNow] = React.useState<Date | null>(null);

  React.useEffect(() => {
    let id: number;
    const tick = () => {
      const current = new Date();
      setNow(current);
      if (live) id = window.setTimeout(tick, nextTick(d, current) * 1000);
    };
    id = window.setTimeout(tick, 0);
    return () => window.clearTimeout(id);
  }, [d, live]);

  const clock = fa(`${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`);
  const full = `${formatJalali(d, { weekday: true, year: true })}، ساعت ${clock}`;
  const absolute = formatJalali(d, { year: true });
  const old = now ? Math.abs(now.getTime() - d.getTime()) > absoluteAfterDays * 864e5 : true;

  return (
    <time dateTime={d.toISOString()} title={full} className={cn("whitespace-nowrap", className)} {...props}>
      {now && !old ? relativeTime(d, now) : absolute}
    </time>
  );
}

"use client";

import * as React from "react";
import { Bike, Mailbox, Package, Store, Truck, type LucideIcon } from "lucide-react";
import { cn, faNumber } from "@/lib/utils";

export type ShippingKind = "post" | "express" | "courier" | "freight" | "pickup";

const KIND_ICON: Record<ShippingKind, LucideIcon> = { post: Mailbox, express: Package, courier: Bike, freight: Truck, pickup: Store };

export interface ShippingMethod {
  id: string;
  /** e.g. «پست پیشتاز», «تیپاکس», «پیک موتوری». */
  name: string;
  /** Picks the icon. */
  kind?: ShippingKind;
  /** Delivery estimate, e.g. «۲ تا ۴ روز کاری». */
  eta: string;
  /** Fee in toman. 0 reads «رایگان». Leave undefined for «پس‌کرایه». */
  price?: number;
  /** Orders at or above this total ship free with this method. */
  freeFrom?: number;
  description?: string;
  disabled?: boolean;
  /** Why it is unavailable, e.g. «فقط در تهران». */
  disabledReason?: string;
}

export interface ShippingMethodsProps {
  methods: ShippingMethod[];
  value?: string;
  defaultValue?: string;
  onChange?: (id: string, fee: number) => void;
  /** Cart total in toman, used to apply `freeFrom`. */
  orderTotal?: number;
  name?: string;
  className?: string;
}

/** Fee of a method for a given cart total; undefined means paid on delivery. */
export function shippingFee(method: ShippingMethod, orderTotal = 0): number | undefined {
  if (method.price === undefined) return undefined;
  return method.freeFrom !== undefined && orderTotal >= method.freeFrom ? 0 : method.price;
}

/** روش ارسال. Radio cards for post, Tipax, courier and pickup with the delivery estimate and the fee. */
export function ShippingMethods({ methods, value, defaultValue, onChange, orderTotal = 0, name, className }: ShippingMethodsProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? "");
  const selected = value ?? internal;
  const autoName = React.useId();

  function select(m: ShippingMethod) {
    if (value === undefined) setInternal(m.id);
    onChange?.(m.id, shippingFee(m, orderTotal) ?? 0);
  }

  return (
    <fieldset className={cn("min-w-0 space-y-2", className)}>
      <legend className="sr-only">روش ارسال</legend>
      {methods.map((m) => {
        const on = selected === m.id;
        const fee = shippingFee(m, orderTotal);
        const Icon = KIND_ICON[m.kind ?? "post"];
        const becameFree = fee === 0 && m.price !== undefined && m.price > 0;
        return (
          <label key={m.id} className={cn("flex items-center gap-3 rounded-control border-line p-3 transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring", m.disabled ? "cursor-not-allowed border-border opacity-55" : "cursor-pointer", on ? "border-foreground/50 bg-accent/60" : !m.disabled && "border-border hover:bg-accent/40")}>
            <input type="radio" name={name ?? autoName} value={m.id} checked={on} disabled={m.disabled} onChange={() => select(m)} className="sr-only" />
            <span aria-hidden className={cn("flex size-4 shrink-0 items-center justify-center rounded-full border", on ? "border-primary" : "border-input")}>{on && <span className="size-2 rounded-full bg-primary" />}</span>
            <span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-secondary"><Icon className="size-5" /></span>
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="text-sm font-medium">{m.name}</span>
              <span className="mt-0.5 text-xs text-muted-foreground">{m.disabled && m.disabledReason ? m.disabledReason : m.eta}</span>
              {m.description && !m.disabled && <span className="mt-0.5 text-xs text-muted-foreground">{m.description}</span>}
            </span>
            <span className="flex shrink-0 flex-col items-end text-sm">
              {fee === undefined ? (
                <span className="text-muted-foreground">پس‌کرایه</span>
              ) : fee === 0 ? (
                <span className="font-semibold text-success">رایگان</span>
              ) : (
                <span className="font-semibold tabular-nums">{faNumber(fee)} <span className="text-xs font-normal text-muted-foreground">تومان</span></span>
              )}
              {becameFree && <span className="text-xs text-muted-foreground line-through tabular-nums">{faNumber(m.price!)}</span>}
            </span>
          </label>
        );
      })}
    </fieldset>
  );
}

