  /** Number badge; above 99 shows «۹۹+». True shows a dot. */
  badge?: number | boolean;
  href?: string;
};

export interface BottomNavProps {
  items: BottomNavItem[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** A raised center action, like «ثبت آگهی» or a scan button. Sits in the middle of the bar. */
  action?: { label: string; icon: LucideIcon; onClick: () => void };
  /** «fixed» sticks to the viewport bottom (default); «static» flows in the page, for previews. */
  position?: "fixed" | "static";
  /** Hide labels except on the active tab. */
  labels?: "always" | "active";
  className?: string;
}

function NavIcon({ icon, className }: { icon: LucideIcon; className?: string }) {
  return React.createElement(icon, { className, "aria-hidden": true });
}

/**
 * نوار پایین موبایل. The tab bar of Iranian super-apps and shops: up to five items with
 * an active pill, number badges, an optional raised center action and room for the
 * home indicator (safe-area inset). First item on the right.
 */
export function BottomNav({ items, value, defaultValue, onChange, action, position = "fixed", labels = "always", className }: BottomNavProps) {
  const [internal, setInternal] = React.useState(defaultValue ?? items[0]?.value);
  const current = value ?? internal;
  const half = Math.ceil(items.length / 2);
  const select = (v: string) => {
    if (value === undefined) setInternal(v);
    onChange?.(v);
  };

  const render = (it: BottomNavItem) => {
    const on = it.value === current;
    const badge = it.badge === true ? "" : typeof it.badge === "number" && it.badge > 0 ? (it.badge > 99 ? "۹۹+" : fa(it.badge)) : null;
    const content = (
      <>
        <span className={cn("relative flex h-8 w-14 items-center justify-center rounded-full transition-colors duration-(--motion) ease-motion", on ? "bg-primary/10 text-primary" : "text-muted-foreground")}>
          <NavIcon icon={on && it.activeIcon ? it.activeIcon : it.icon} className="size-[22px]" />
          {badge !== null && (
            <span className={cn("absolute top-0.5 flex items-center justify-center rounded-full bg-destructive text-[10px] font-bold leading-none text-white ring-2 ring-background", badge ? "end-2 h-4 min-w-4 px-1" : "end-3.5 size-2")}>
              {badge}
            </span>
          )}
        </span>
        <span className={cn("text-[11px] leading-4 transition-opacity", on ? "font-semibold text-foreground" : "text-muted-foreground", labels === "active" && !on && "sr-only")}>
          {it.label}
          {typeof it.badge === "number" && it.badge > 0 && <span className="sr-only">، {fa(it.badge)} مورد جدید</span>}
        </span>
      </>
    );
    const cls = "flex min-w-0 flex-1 cursor-pointer flex-col items-center justify-center gap-0.5 py-1.5 outline-none focus-visible:[&>span:first-child]:ring-2 focus-visible:[&>span:first-child]:ring-ring";
    return (
      <li key={it.value} className="flex flex-1">
        {it.href ? (
          <a href={it.href} aria-current={on ? "page" : undefined} onClick={() => select(it.value)} className={cls}>{content}</a>
        ) : (
          <button type="button" aria-current={on ? "page" : undefined} onClick={() => select(it.value)} className={cls}>{content}</button>
        )}
      </li>
    );
  };

  return (
    <nav
      aria-label="ناوبری اصلی"
      className={cn(
        "z-40 border-t border-border bg-background/95 pb-[env(safe-area-inset-bottom)] backdrop-blur",
        position === "fixed" ? "fixed inset-x-0 bottom-0" : "relative",
        className,
      )}
    >
      <ul className="mx-auto flex max-w-lg items-stretch px-1">
        {items.slice(0, action ? half : items.length).map(render)}
        {action && (
          <li className="flex flex-1 items-start justify-center">
            <button type="button" onClick={action.onClick} aria-label={action.label} title={action.label} className="-mt-5 flex size-14 cursor-pointer items-center justify-center rounded-full bg-primary text-primary-foreground shadow-overlay ring-4 ring-background transition-transform ease-motion active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">
              <NavIcon icon={action.icon} className="size-6" />
            </button>
          </li>
        )}
        {action && items.slice(half).map(render)}
      </ul>
    </nav>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";

export interface DrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: React.ReactNode;
  description?: React.ReactNode;
  /** Heights as a share of the viewport, smallest first. Default [0.5, 0.92]. */
  snapPoints?: number[];
  /** Index into snapPoints to open at. Default 0. */
  defaultSnap?: number;
  /** Sticky area under the content, e.g. a submit button. */
  footer?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
}

const noop = () => () => {};
const FOCUSABLE = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';

/**
 * کشوی پایین. A mobile bottom sheet you drag by its handle: it snaps between heights,
 * closes when flung down, keeps focus inside while open and returns it on close.
 * The handle is a button too, so the keyboard can switch heights.
 */
export function Drawer({ open, onOpenChange, title, description, snapPoints = [0.5, 0.92], defaultSnap = 0, footer, children, className }: DrawerProps) {
  const titleId = React.useId();
  const descId = React.useId();
  const panel = React.useRef<HTMLDivElement>(null);
  const restore = React.useRef<HTMLElement | null>(null);
  const drag = React.useRef<{ y0: number; t0: number; h0: number } | null>(null);
  const mounted = React.useSyncExternalStore(noop, () => true, () => false);
  const [present, setPresent] = React.useState(open);
  const [snap, setSnap] = React.useState(defaultSnap);
  const [offset, setOffset] = React.useState<number | null>(null);
  const [shown, setShown] = React.useState(false);
  const [vh, setVh] = React.useState(800);
  const [wasOpen, setWasOpen] = React.useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) { setPresent(true); setSnap(defaultSnap); }
    else setShown(false);
  }

  React.useEffect(() => {
    if (open) {
      restore.current = document.activeElement as HTMLElement | null;
      let inner = 0;
      const id = requestAnimationFrame(() => {
        setVh(window.innerHeight);
        inner = requestAnimationFrame(() => setShown(true));
      });
      return () => { cancelAnimationFrame(id); cancelAnimationFrame(inner); };
    }
    const t = window.setTimeout(() => {
      setPresent(false);
      restore.current?.focus?.();
    }, 280);
    return () => window.clearTimeout(t);
  }, [open]);

  React.useEffect(() => {
    if (!present) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const first = panel.current?.querySelector<HTMLElement>(FOCUSABLE);
    (first ?? panel.current)?.focus();
    return () => { document.body.style.overflow = prev; };
  }, [present]);

  function onKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Escape") { e.stopPropagation(); onOpenChange(false); return; }
    if (e.key !== "Tab" || !panel.current) return;
    const f = [...panel.current.querySelectorAll<HTMLElement>(FOCUSABLE)];
    if (!f.length) return;
    const a = f[0], z = f[f.length - 1];
    if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); }
    else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
  }

  const height = snapPoints[snap] * vh;

  function down(e: React.PointerEvent) {
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    drag.current = { y0: e.clientY, t0: performance.now(), h0: height };
    setOffset(0);
  }
  function move(e: React.PointerEvent) {
    if (!drag.current) return;
    setOffset(e.clientY - drag.current.y0);
  }
  function up(e: React.PointerEvent) {
    const d = drag.current;
    drag.current = null;
    if (!d) return;
    const dy = e.clientY - d.y0;
    const speed = dy / Math.max(1, performance.now() - d.t0);
    setOffset(null);
    const h = d.h0 - dy;
    // A quick fling or dragging below the smallest snap closes it.
    if (speed > 0.6 || h < snapPoints[0] * vh * 0.6) { onOpenChange(false); return; }
    if (speed < -0.6) { setSnap(snapPoints.length - 1); return; }
    let best = 0;
    snapPoints.forEach((p, i) => { if (Math.abs(p * vh - h) < Math.abs(snapPoints[best] * vh - h)) best = i; });
    setSnap(best);
  }

  if (!mounted || !present) return null;
  const dragging = offset !== null;
  const translate = shown ? Math.max(0, offset ?? 0) : height;
  const extra = shown && offset !== null && offset < 0 ? -offset : 0;

  return createPortal(
    <div className="fixed inset-0 z-50" role="presentation">
      <div aria-hidden onClick={() => onOpenChange(false)} className={cn("absolute inset-0 bg-black/50 transition-opacity duration-300", shown ? "opacity-100" : "opacity-0")} />
      <div
        ref={panel}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        aria-describedby={description ? descId : undefined}
        tabIndex={-1}
        onKeyDown={onKeyDown}
        className={cn("absolute inset-x-0 bottom-0 mx-auto flex max-w-xl flex-col rounded-t-overlay border-t border-border bg-popover text-popover-foreground shadow-overlay outline-none", className)}
        style={{
          height: Math.min(vh - 8, height + extra),
          transform: `translateY(${translate}px)`,
          transition: dragging ? "none" : "transform 280ms cubic-bezier(0.32,0.72,0,1), height 280ms cubic-bezier(0.32,0.72,0,1)",
        }}
      >
        <button
          type="button"
          aria-label={snap < snapPoints.length - 1 ? "باز کردن کامل" : "کوچک کردن"}
          onClick={() => setSnap((s) => (s < snapPoints.length - 1 ? s + 1 : 0))}
          onPointerDown={down}
          onPointerMove={move}
          onPointerUp={up}
          onPointerCancel={up}
          className="flex w-full shrink-0 cursor-grab touch-none justify-center pb-2 pt-3 outline-none active:cursor-grabbing focus-visible:[&>span]:bg-ring"
        >
          <span className="h-1.5 w-10 rounded-full bg-muted-foreground/30" />
        </button>
        {(title || description) && (
          <div className="shrink-0 px-5 pb-3">
            {title && <h2 id={titleId} className="font-display text-base font-bold">{title}</h2>}
            {description && <p id={descId} className="mt-0.5 text-sm text-muted-foreground">{description}</p>}
          </div>
        )}
        <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 pb-4">{children}</div>
        {footer && <div className="shrink-0 border-t border-border px-5 py-3 pb-[max(0.75rem,env(safe-area-inset-bottom))]">{footer}</div>}
      </div>
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";
import { ChevronLeft, File, Folder, FolderOpen, type LucideIcon } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type TreeNode = {
  id: string;
  label: string;
  icon?: LucideIcon;
  /** Small text on the far side, e.g. a count or a size. */
  meta?: string | number;
  children?: TreeNode[];
  disabled?: boolean;
};

export interface TreeViewProps {
  items: TreeNode[];
  selected?: string | null;
  defaultSelected?: string | null;
  onSelect?: (node: TreeNode) => void;
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (ids: string[]) => void;
  /** Folder and file icons for nodes without their own. Default true. */
  icons?: boolean;
  /** Guide lines down each level. Default true. */
  guides?: boolean;
  "aria-label"?: string;
  className?: string;
}

type Flat = { node: TreeNode; level: number; parent: string | null };

function flatten(items: TreeNode[], open: Set<string>, level = 1, parent: string | null = null, out: Flat[] = []) {
  for (const node of items) {
    out.push({ node, level, parent });
    if (node.children?.length && open.has(node.id)) flatten(node.children, open, level + 1, node.id, out);
  }
  return out;
}

function TreeIcon({ icon, className }: { icon: LucideIcon; className?: string }) {
  return React.createElement(icon, { className, "aria-hidden": true });
}

/**
 * درخت. Folders, categories or org charts with the WAI-ARIA tree pattern. In RTL the
 * arrows are mirrored: ArrowLeft opens a branch or steps into it, ArrowRight closes it
 * or goes to the parent. Up/Down, Home/End, * opens siblings, and typing jumps by letter.
 */
export function TreeView({ items, selected, defaultSelected = null, onSelect, expanded, defaultExpanded = [], onExpandedChange, icons = true, guides = true, className, ...aria }: TreeViewProps) {
  const [openInternal, setOpenInternal] = React.useState<string[]>(defaultExpanded);
  const [selInternal, setSelInternal] = React.useState<string | null>(defaultSelected);
  const open = React.useMemo(() => new Set(expanded ?? openInternal), [expanded, openInternal]);
  const sel = selected !== undefined ? selected : selInternal;
  const rows = flatten(items, open);
  const [focus, setFocus] = React.useState<string | null>(null);
  const focusId = focus && rows.some((r) => r.node.id === focus) ? focus : sel && rows.some((r) => r.node.id === sel) ? sel : rows[0]?.node.id;
  const refs = React.useRef(new Map<string, HTMLLIElement>());
  const typed = React.useRef({ text: "", at: 0 });

  const setOpen = (ids: string[]) => {
    if (expanded === undefined) setOpenInternal(ids);
    onExpandedChange?.(ids);
  };
  const toggle = (id: string, to?: boolean) => {
    const on = to ?? !open.has(id);
    setOpen(on ? [...open, id] : [...open].filter((x) => x !== id));
  };
  const choose = (n: TreeNode) => {
    if (n.disabled) return;
    if (selected === undefined) setSelInternal(n.id);
    onSelect?.(n);
  };
  const move = (id: string | undefined) => {
    if (!id) return;
    setFocus(id);
    refs.current.get(id)?.focus();
  };

  function onKeyDown(e: React.KeyboardEvent) {
    const i = rows.findIndex((r) => r.node.id === focusId);
    const r = rows[i];
    if (!r) return;
    const branch = !!r.node.children?.length;
    let handled = true;
    switch (e.key) {
      case "ArrowDown": move(rows[i + 1]?.node.id); break;
      case "ArrowUp": move(rows[i - 1]?.node.id); break;
      case "Home": move(rows[0]?.node.id); break;
      case "End": move(rows[rows.length - 1]?.node.id); break;
      case "ArrowLeft":
        if (branch && !open.has(r.node.id)) toggle(r.node.id, true);
        else if (branch) move(rows[i + 1]?.node.id);
        break;
      case "ArrowRight":
        if (branch && open.has(r.node.id)) toggle(r.node.id, false);
        else move(r.parent ?? undefined);
        break;
      case "Enter":
      case " ":
        choose(r.node);
        if (branch && e.key === "Enter") toggle(r.node.id);
        break;
      case "*": {
        const siblings = rows.filter((x) => x.parent === r.parent && x.node.children?.length).map((x) => x.node.id);
        setOpen([...new Set([...open, ...siblings])]);
        break;
      }
      default:
        if (e.key.length === 1 && !e.metaKey && !e.ctrlKey) {
          const now = e.timeStamp;
          typed.current = { text: (now - typed.current.at < 600 ? typed.current.text : "") + e.key, at: now };
          const q = typed.current.text;
          const after = [...rows.slice(i + 1), ...rows.slice(0, i + 1)];
          move(after.find((x) => x.node.label.startsWith(q))?.node.id);
        } else handled = false;
    }
    if (handled) e.preventDefault();
  }

  return (
    <ul role="tree" aria-label={aria["aria-label"]} onKeyDown={onKeyDown} className={cn("text-sm", className)}>
      {rows.map(({ node, level }) => {
        const branch = !!node.children?.length;
        const isOpen = open.has(node.id);
        const on = node.id === sel;
        const icon = node.icon ?? (branch ? (isOpen ? FolderOpen : Folder) : File);
        return (
          <li
            key={node.id}
            ref={(el) => { if (el) refs.current.set(node.id, el); else refs.current.delete(node.id); }}
            role="treeitem"
            aria-level={level}
            aria-expanded={branch ? isOpen : undefined}
            aria-selected={on}
            aria-disabled={node.disabled || undefined}
            tabIndex={node.id === focusId ? 0 : -1}
            onFocus={() => setFocus(node.id)}
            onClick={(e) => { e.stopPropagation(); setFocus(node.id); choose(node); if (branch) toggle(node.id); }}
            className={cn(
              "relative flex h-8 cursor-pointer select-none items-center gap-1.5 rounded-control pe-2 outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/60",
              on ? "bg-accent font-medium text-accent-foreground" : "hover:bg-accent/50",
              node.disabled && "cursor-not-allowed opacity-50",
            )}
            style={{ paddingInlineStart: (level - 1) * 18 + 6 }}
          >
            {guides && Array.from({ length: level - 1 }, (_, g) => (
              <span key={g} aria-hidden className="absolute inset-y-0 border-s border-border" style={{ insetInlineStart: g * 18 + 13 }} />
            ))}
            <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
              {branch && <ChevronLeft aria-hidden className={cn("size-3.5 transition-transform duration-(--motion) ease-motion", isOpen && "-rotate-90")} />}
            </span>
            {icons && <TreeIcon icon={icon} className={cn("size-4 shrink-0", branch ? "text-brand" : "text-muted-foreground")} />}
            <span className="min-w-0 flex-1 truncate">{node.label}</span>
            {node.meta !== undefined && <span className="shrink-0 text-xs tabular-nums text-muted-foreground">{typeof node.meta === "number" ? fa(node.meta) : node.meta}</span>}
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import * as React from "react";
import { GripVertical } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export interface SortableListProps<T> {
  items: T[];
  /** Stable key of an item. */
  getKey: (item: T) => string;
  /** Spoken name of an item for the announcements. */
  getLabel: (item: T) => string;
  onReorder: (items: T[]) => void;
  renderItem: (item: T, state: { dragging: boolean; index: number }) => React.ReactNode;
  /** Name of the list, e.g. «ترتیب منو». */
  label: string;
  className?: string;
}

const moveItem = <T,>(list: T[], from: number, to: number) => {
  const next = [...list];
  const [it] = next.splice(from, 1);
  next.splice(to, 0, it);
  return next;
};

/**
 * فهرست مرتب‌شدنی. Drag rows by the handle with mouse or touch, or from the keyboard:
 * Space picks a row up, Up/Down move it, Space drops it and Escape puts it back.
 * Every step is announced, like «برداشته شد، جای ۲ از ۵».
 */
export function SortableList<T>({ items, getKey, getLabel, onReorder, renderItem, label, className }: SortableListProps<T>) {
  const [drag, setDrag] = React.useState<{ key: string; from: number; dy: number; h: number } | null>(null);
  const [over, setOver] = React.useState<number | null>(null);
  const [grabbed, setGrabbed] = React.useState<{ key: string; origin: T[] } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const rowRefs = React.useRef(new Map<string, HTMLLIElement>());
  const handleRefs = React.useRef(new Map<string, HTMLButtonElement>());
  const start = React.useRef({ y: 0, mids: [] as number[] });
  const n = items.length;

  function pointerDown(e: React.PointerEvent, key: string, index: number) {
    if (e.button !== 0) return;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    const rects = items.map((it) => rowRefs.current.get(getKey(it))!.getBoundingClientRect());
    start.current = { y: e.clientY, mids: rects.map((r) => r.top + r.height / 2) };
    setDrag({ key, from: index, dy: 0, h: rects[index].height });
    setOver(index);
  }
  function pointerMove(e: React.PointerEvent) {
    if (!drag) return;
    const dy = e.clientY - start.current.y;
    const y = start.current.mids[drag.from] + dy;
    let to = drag.from;
    start.current.mids.forEach((m, i) => { if (i < drag.from && y < m) to = Math.min(to, i); if (i > drag.from && y > m) to = Math.max(to, i); });
    setDrag({ ...drag, dy });
    setOver(to);
  }
  function pointerUp() {
    if (drag && over !== null && over !== drag.from) {
      onReorder(moveItem(items, drag.from, over));
      setAnnounce(`${getLabel(items[drag.from])} به جای ${fa(over + 1)} از ${fa(n)} رفت.`);
    }
    setDrag(null);
    setOver(null);
  }

  function keyDown(e: React.KeyboardEvent, item: T, index: number) {
    const key = getKey(item);
    const name = getLabel(item);
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      if (grabbed?.key === key) { setGrabbed(null); setAnnounce(`${name} در جای ${fa(index + 1)} گذاشته شد.`); }
      else { setGrabbed({ key, origin: items }); setAnnounce(`${name} برداشته شد، جای ${fa(index + 1)} از ${fa(n)}. با بالا و پایین جابه‌جا کنید و با فاصله رها کنید.`); }
    } else if (grabbed?.key === key && (e.key === "ArrowUp" || e.key === "ArrowDown")) {
      e.preventDefault();
      const to = e.key === "ArrowUp" ? index - 1 : index + 1;
      if (to < 0 || to >= n) return;
      onReorder(moveItem(items, index, to));
      setAnnounce(`جای ${fa(to + 1)} از ${fa(n)}`);
      requestAnimationFrame(() => handleRefs.current.get(key)?.focus());
    } else if (e.key === "Escape" && grabbed?.key === key) {
      e.preventDefault();
      onReorder(grabbed.origin);
      setGrabbed(null);
      setAnnounce(`جابه‌جایی ${name} لغو شد.`);
      requestAnimationFrame(() => handleRefs.current.get(key)?.focus());
    }
  }

  return (
    <div className={className}>
      <ul aria-label={label} className="space-y-2">
        {items.map((item, i) => {
          const key = getKey(item);
          const dragging = drag?.key === key;
          const lifted = dragging || grabbed?.key === key;
          // Neighbours slide out of the way while a row is dragged across them.
          let shift = 0;
          if (drag && over !== null && !dragging) {
            if (drag.from < over && i > drag.from && i <= over) shift = -drag.h - 8;
            if (drag.from > over && i < drag.from && i >= over) shift = drag.h + 8;
          }
          return (
            <li
              key={key}
              ref={(el) => { if (el) rowRefs.current.set(key, el); else rowRefs.current.delete(key); }}
              className={cn("relative flex items-center gap-2 rounded-surface border-line bg-card p-2 pe-3", lifted ? "z-10 border-primary shadow-overlay" : "border-border", !dragging && "transition-transform duration-200 ease-motion")}
              style={{ transform: dragging ? `translateY(${drag.dy}px) scale(1.02)` : shift ? `translateY(${shift}px)` : undefined }}
            >
              <button
                type="button"
                ref={(el) => { if (el) handleRefs.current.set(key, el); else handleRefs.current.delete(key); }}
                aria-label={`جابه‌جا کردن ${getLabel(item)}`}
                aria-pressed={grabbed?.key === key}
                aria-describedby={undefined}
                onPointerDown={(e) => pointerDown(e, key, i)}
                onPointerMove={pointerMove}
                onPointerUp={pointerUp}
                onPointerCancel={pointerUp}
                onKeyDown={(e) => keyDown(e, item, i)}
                onBlur={() => grabbed?.key === key && setGrabbed(null)}
                className={cn("flex size-8 shrink-0 touch-none items-center justify-center rounded-control text-muted-foreground outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring", drag ? "cursor-grabbing" : "cursor-grab")}
              >
                <GripVertical className="size-4" />
              </button>
              <div className="min-w-0 flex-1">{renderItem(item, { dragging: lifted, index: i })}</div>
            </li>
          );
        })}
      </ul>
      <p className="sr-only" aria-live="assertive">{announce}</p>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";

/** Keeps the resize cursor while the pointer is outside the thin separator. */
function bodyCursor(cursor: string) {
  document.body.style.cursor = cursor;
}

export interface ResizablePanelsProps {
  /** «horizontal» puts panels side by side; the first one is on the right in RTL. */
  direction?: "horizontal" | "vertical";
  /** Starting sizes in percent, one per child. Defaults to equal. */
  defaultSizes?: number[];
  sizes?: number[];
  onSizesChange?: (sizes: number[]) => void;
  /** Smallest size of any panel in percent. Default 15. */
  min?: number;
  /** Panels below this size snap closed, like a collapsible sidebar. Off by default. */
  collapseBelow?: number;
  /** Names of the panels for the separators' labels. */
  labels?: string[];
  /** Height for horizontal groups. Default 100%. */
  className?: string;
  children: React.ReactNode;
}

/**
 * پنل‌های قابل تغییر اندازه. Split a view into panels with draggable separators. Each
 * separator is a focusable role=separator: arrows resize by 2%, Shift by 10%, Home and End
 * jump to the limits, and Enter collapses and restores the panel before it.
 */
export function ResizablePanels({ direction = "horizontal", defaultSizes, sizes, onSizesChange, min = 15, collapseBelow, labels, className, children }: ResizablePanelsProps) {
  const panels = React.Children.toArray(children);
  const count = panels.length;
  const [internal, setInternal] = React.useState<number[]>(() => defaultSizes ?? panels.map(() => 100 / count));
  const current = sizes ?? internal;
  const root = React.useRef<HTMLDivElement>(null);
  const memory = React.useRef<Record<number, number>>({});
  const horizontal = direction === "horizontal";

  const commit = React.useCallback((next: number[]) => {
    if (sizes === undefined) setInternal(next);
    onSizesChange?.(next);
  }, [sizes, onSizesChange]);

  /** Move the separator after panel `i` by `delta` percent toward panel i+1 (growing panel i). */
  const resize = React.useCallback((i: number, delta: number, base = current) => {
    const pair = base[i] + base[i + 1];
    let a = Math.min(pair - min, Math.max(min, base[i] + delta));
    if (collapseBelow !== undefined && base[i] + delta < collapseBelow) a = 0;
    if (collapseBelow !== undefined && pair - (base[i] + delta) < collapseBelow) a = pair;
    const next = [...base];
    next[i] = a;
    next[i + 1] = pair - a;
    commit(next);
  }, [current, min, collapseBelow, commit]);

  function onPointerDown(e: React.PointerEvent, i: number) {
    e.preventDefault();
    const el = root.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const rtl = getComputedStyle(el).direction === "rtl";
    const total = horizontal ? rect.width : rect.height;
    const p0 = horizontal ? e.clientX : e.clientY;
    const base = current;
    const target = e.currentTarget as HTMLElement;
    target.setPointerCapture(e.pointerId);
    const move = (ev: PointerEvent) => {
      let d = ((horizontal ? ev.clientX : ev.clientY) - p0) / total * 100;
      if (horizontal && rtl) d = -d;
      resize(i, d, base);
    };
    const up = () => { target.removeEventListener("pointermove", move); target.removeEventListener("pointerup", up); bodyCursor(""); };
    target.addEventListener("pointermove", move);
    target.addEventListener("pointerup", up);
    bodyCursor(horizontal ? "col-resize" : "row-resize");
  }

  function onKeyDown(e: React.KeyboardEvent, i: number) {
    const step = e.shiftKey ? 10 : 2;
    const rtl = root.current ? getComputedStyle(root.current).direction === "rtl" : true;
    // Toward the next panel grows this one: left in RTL, right in LTR, down when vertical.
    const grow = horizontal ? (rtl ? "ArrowLeft" : "ArrowRight") : "ArrowDown";
    const shrink = horizontal ? (rtl ? "ArrowRight" : "ArrowLeft") : "ArrowUp";
    if (e.key === grow) resize(i, step);
    else if (e.key === shrink) resize(i, -step);
    else if (e.key === "Home") resize(i, -100);
    else if (e.key === "End") resize(i, 100);
    else if (e.key === "Enter") {
      if (current[i] > 0) { memory.current[i] = current[i]; commit(Object.assign([...current], { [i]: 0, [i + 1]: current[i] + current[i + 1] })); }
      else { const back = memory.current[i] ?? 30; commit(Object.assign([...current], { [i]: back, [i + 1]: current[i + 1] - back })); }
    } else return;
    e.preventDefault();
  }

  return (
    <div ref={root} className={cn("flex min-h-0 overflow-hidden", horizontal ? "h-full flex-row" : "h-full flex-col", className)}>
      {panels.map((child, i) => (
        <React.Fragment key={i}>
          <div className="min-h-0 min-w-0 overflow-auto" style={{ flexBasis: `${current[i]}%`, flexGrow: 0, flexShrink: 0, display: current[i] === 0 ? "none" : undefined }}>
            {child}
          </div>
          {i < count - 1 && (
            <div
              role="separator"
              tabIndex={0}
              aria-orientation={horizontal ? "vertical" : "horizontal"}
              aria-valuenow={Math.round(current[i])}
              aria-valuemin={collapseBelow !== undefined ? 0 : min}
              aria-valuemax={100 - min}
              aria-valuetext={`${fa(Math.round(current[i]))}٪`}
              aria-label={`اندازه‌ی ${labels?.[i] ?? `پنل ${fa(i + 1)}`}`}
              onPointerDown={(e) => onPointerDown(e, i)}
              onKeyDown={(e) => onKeyDown(e, i)}
              onDoubleClick={() => { const even = (current[i] + current[i + 1]) / 2; commit(Object.assign([...current], { [i]: even, [i + 1]: even })); }}
              className={cn(
                "group relative z-10 flex shrink-0 touch-none items-center justify-center outline-none",
                horizontal ? "w-px cursor-col-resize bg-border" : "h-px cursor-row-resize bg-border",
                "after:absolute after:content-[''] focus-visible:bg-ring",
                horizontal ? "after:inset-y-0 after:-inset-x-2" : "after:inset-x-0 after:-inset-y-2",
              )}
            >
              <span aria-hidden className={cn("rounded-full border border-border bg-background opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100", horizontal ? "h-6 w-1.5" : "h-1.5 w-6")} />
            </div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Pipette } from "lucide-react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

const noop = () => () => {};

/* ---------- color math ---------- */

export type Hsv = { h: number; s: number; v: number };

export function hexToHsv(hex: string): Hsv | null {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return null;
  const full = m[1].length === 3 ? m[1].replace(/./g, (c) => c + c) : m[1];
  const n = parseInt(full, 16);
  const r = (n >> 16) / 255, g = ((n >> 8) & 255) / 255, b = (n & 255) / 255;
  const max = Math.max(r, g, b), d = max - Math.min(r, g, b);
  let h = 0;
  if (d) h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return { h: (h * 60 + 360) % 360, s: max ? d / max : 0, v: max };
}

export function hsvToHex({ h, s, v }: Hsv) {
  const f = (n: number) => {
    const k = (n + h / 60) % 6;
    return Math.round((v - v * s * Math.max(0, Math.min(k, 4 - k, 1))) * 255).toString(16).padStart(2, "0");
  };
  return `#${f(5)}${f(3)}${f(1)}`;
}

/** WCAG relative-luminance contrast between two hex colors. */
export function contrastRatio(a: string, b: string) {
  const lum = (hex: string) => {
    const n = parseInt(hex.replace("#", ""), 16);
    const c = [n >> 16, (n >> 8) & 255, n & 255].map((x) => { const v = x / 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; });
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  };
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
}

const DEFAULT_SWATCHES = ["#ef4444", "#f97316", "#eab308", "#22c55e", "#14b8a6", "#3b82f6", "#6366f1", "#a855f7", "#ec4899", "#71717a", "#18181b", "#ffffff"];

/* ---------- panel ---------- */

export interface ColorPickerProps {
  value?: string;
  defaultValue?: string;
  onChange?: (hex: string) => void;
  swatches?: string[];
  /** Show the contrast of the color against white and black text. Default true. */
  contrast?: boolean;
  className?: string;
}

/**
 * انتخاب رنگ. A saturation and brightness square, a hue strip, a hex field, swatches and
 * the screen eyedropper where the browser has one. Color spaces don't mirror: the square
 * and the strip stay left to right in RTL. Everything works with the arrow keys.
 */
export function ColorPicker({ value, defaultValue = "#6366f1", onChange, swatches = DEFAULT_SWATCHES, contrast = true, className }: ColorPickerProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const hex = (value ?? internal).toLowerCase();
  // Keep hue across gray and black, where the hex alone loses it.
  const [hsv, setHsv] = React.useState<Hsv>(() => hexToHsv(hex) ?? { h: 0, s: 0, v: 0 });
  const [seen, setSeen] = React.useState(hex);
  if (seen !== hex) {
    setSeen(hex);
    const next = hexToHsv(hex);
    if (next && hsvToHex(hsv) !== hex) setHsv(next.s === 0 || next.v === 0 ? { ...next, h: hsv.h } : next);
  }
  const [draft, setDraft] = React.useState<string | null>(null);

  const emit = (next: Hsv) => {
    setHsv(next);
    const h = hsvToHex(next);
    setSeen(h);
    if (value === undefined) setInternal(h);
    onChange?.(h);
  };
  const setHex = (h: string) => {
    const p = hexToHsv(h);
    if (!p) return;
    emit(p.s === 0 || p.v === 0 ? { ...p, h: hsv.h } : p);
  };

  const area = React.useRef<HTMLDivElement>(null);
  const strip = React.useRef<HTMLDivElement>(null);
  const drag = (el: HTMLElement | null, e: React.PointerEvent, fn: (x: number, y: number) => void) => {
    if (!el) return;
    el.setPointerCapture(e.pointerId);
    const at = (ev: { clientX: number; clientY: number }) => {
      const r = el.getBoundingClientRect();
      fn(Math.min(1, Math.max(0, (ev.clientX - r.left) / r.width)), Math.min(1, Math.max(0, (ev.clientY - r.top) / r.height)));
    };
    at(e);
    const move = (ev: PointerEvent) => at(ev);
    const up = () => { el.removeEventListener("pointermove", move); el.removeEventListener("pointerup", up); };
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerup", up);
  };

  // Read after hydration so the server and first client render agree.
  const hasDropper = React.useSyncExternalStore(noop, () => "EyeDropper" in window, () => false);
  async function pick() {
    try {
      const ED = (window as unknown as { EyeDropper: new () => { open: () => Promise<{ sRGBHex: string }> } }).EyeDropper;
      const res = await new ED().open();
      setHex(res.sRGBHex);
    } catch {
      /* cancelled */
    }
  }

  const step = (e: React.KeyboardEvent) => (e.shiftKey ? 0.1 : 0.01);
  const white = contrastRatio(hex, "#ffffff");
  const black = contrastRatio(hex, "#000000");

  return (
    <div className={cn("w-64 space-y-3", className)}>
      <div
        ref={area}
        dir="ltr"
        role="slider"
        tabIndex={0}
        aria-label="اشباع و روشنایی"
        aria-valuetext={`اشباع ${Math.round(hsv.s * 100)}٪، روشنایی ${Math.round(hsv.v * 100)}٪`}
        aria-valuenow={Math.round(hsv.s * 100)}
        onPointerDown={(e) => drag(area.current, e, (x, y) => emit({ ...hsv, s: x, v: 1 - y }))}
        onKeyDown={(e) => {
          const d = step(e);
          const k = { ArrowRight: [d, 0], ArrowLeft: [-d, 0], ArrowUp: [0, d], ArrowDown: [0, -d] }[e.key];
          if (!k) return;
          e.preventDefault();
          emit({ ...hsv, s: Math.min(1, Math.max(0, hsv.s + k[0])), v: Math.min(1, Math.max(0, hsv.v + k[1])) });
        }}
        className="relative h-40 cursor-crosshair touch-none rounded-control outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        style={{ background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, hsl(${hsv.h} 100% 50%))` }}
      >
        <span aria-hidden className="pointer-events-none absolute size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow-[0_0_0_1px_rgb(0_0_0/0.3)]" style={{ left: `${hsv.s * 100}%`, top: `${(1 - hsv.v) * 100}%`, background: hex }} />
      </div>
      <div
        ref={strip}
        dir="ltr"
        role="slider"
        tabIndex={0}
        aria-label="رنگ‌مایه"
        aria-valuemin={0}
        aria-valuemax={360}
        aria-valuenow={Math.round(hsv.h)}
        aria-valuetext={`${Math.round(hsv.h)} درجه`}
        onPointerDown={(e) => drag(strip.current, e, (x) => emit({ ...hsv, h: x * 359.9 }))}
        onKeyDown={(e) => {
          const d = e.shiftKey ? 30 : 3;
          const k = e.key === "ArrowRight" || e.key === "ArrowUp" ? d : e.key === "ArrowLeft" || e.key === "ArrowDown" ? -d : 0;
          if (!k) return;
          e.preventDefault();
          emit({ ...hsv, h: (hsv.h + k + 360) % 360 });
        }}
        className="relative h-3 cursor-pointer touch-none rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        style={{ background: "linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)" }}
      >
        <span aria-hidden className="pointer-events-none absolute top-1/2 size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow-[0_0_0_1px_rgb(0_0_0/0.3)]" style={{ left: `${(hsv.h / 360) * 100}%`, background: `hsl(${hsv.h} 100% 50%)` }} />
      </div>
      <div className="flex items-center gap-2">
        <span aria-hidden className="size-9 shrink-0 rounded-control border border-border" style={{ background: hex }} />
        <label className="relative flex-1">
          <span className="sr-only">کد رنگ</span>
          <input
            dir="ltr"
            value={draft ?? hex.toUpperCase()}
            onChange={(e) => { setDraft(e.target.value); if (/^#?[0-9a-f]{6}$/i.test(e.target.value.trim())) setHex(e.target.value.startsWith("#") ? e.target.value : `#${e.target.value}`); }}
            onBlur={() => setDraft(null)}
            spellCheck={false}
            className="h-9 w-full rounded-field border-line-field border-input bg-field px-2.5 font-mono text-sm uppercase shadow-field outline-none focus-visible:ring-2 focus-visible:ring-ring/60"
          />
        </label>
        {hasDropper && (
          <button type="button" onClick={pick} aria-label="برداشتن رنگ از صفحه" className="flex size-9 shrink-0 items-center justify-center rounded-control border-line border-border hover:bg-accent"><Pipette className="size-4" /></button>
        )}
      </div>
      {swatches.length > 0 && (
        <div role="radiogroup" aria-label="رنگ‌های آماده" className="grid grid-cols-6 gap-1.5">
          {swatches.map((s) => {
            const on = s.toLowerCase() === hex;
            return (
              <button key={s} type="button" role="radio" aria-checked={on} aria-label={s} onClick={() => setHex(s)} className="relative aspect-square rounded-md border border-black/10 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1" style={{ background: s }}>
                {on && <Check className="absolute inset-0 m-auto size-3.5" style={{ color: contrastRatio(s, "#fff") > 3 ? "#fff" : "#000" }} />}
              </button>
            );
          })}
        </div>
      )}
      {contrast && (
        <dl className="grid grid-cols-2 gap-1.5 text-[11px]">
          {([["متن سفید", white, "#fff"], ["متن مشکی", black, "#000"]] as const).map(([k, r, fg]) => (
            <div key={k} className="flex items-center justify-between rounded-md px-2 py-1" style={{ background: hex, color: fg }}>
              <dt>{k}</dt>
              <dd dir="ltr" className="font-mono">{r.toFixed(1)} {r >= 7 ? "AAA" : r >= 4.5 ? "AA" : r >= 3 ? "AA درشت" : "✕"}</dd>
            </div>
          ))}
        </dl>
      )}
    </div>
  );
}

/* ---------- trigger + popover ---------- */

export interface ColorInputProps extends Omit<ColorPickerProps, "className"> {
  label?: string;
  className?: string;
}

/** A swatch button with the hex that opens the picker in a popover. */
export function ColorInput({ label = "رنگ", className, value, defaultValue = "#6366f1", onChange, ...rest }: ColorInputProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const hex = value ?? internal;
  const [open, setOpen] = React.useState(false);
  const btn = React.useRef<HTMLButtonElement>(null);
  const f = useFloat(open, btn, { align: "start" });

  React.useEffect(() => {
    if (!open) return;
    const close = (e: Event) => { if (!eventInside(e, btn.current, f.panel.current)) setOpen(false); };
    const esc = (e: KeyboardEvent) => { if (e.key === "Escape") { setOpen(false); btn.current?.focus(); } };
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("pointerdown", close); document.removeEventListener("keydown", esc); };
  }, [open, f.panel]);

  return (
    <>
      <button
        ref={btn}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={`${label}: ${hex}`}
        onClick={() => setOpen((o) => !o)}
        className={cn("inline-flex h-10 items-center gap-2 rounded-field border-line-field border-input bg-field ps-1.5 pe-3 shadow-field outline-none focus-visible:ring-2 focus-visible:ring-ring/60", className)}
      >
        <span aria-hidden className="size-7 rounded-md border border-black/10" style={{ background: hex }} />
        <bdi dir="ltr" className="font-mono text-sm uppercase">{hex}</bdi>
      </button>
      <FloatPortal open={open} mounted={f.mounted} style={{ ...f.style, position: "fixed" }} theme={f.theme} panelRef={f.panel} role="dialog" aria-label={label} className="z-50 rounded-overlay border border-border bg-popover p-3 text-popover-foreground shadow-overlay">
        <ColorPicker {...rest} value={hex} onChange={(h) => { if (value === undefined) setInternal(h); onChange?.(h); }} />
      </FloatPortal>
    </>
  );
}

"use client";

import * as React from "react";
import { RotateCw, ZoomIn, ZoomOut } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type CropArea = { x: number; y: number; width: number; height: number; rotation: number };

export interface ImageCropperProps {
  src: string;
  /** Width / height of the crop frame. Default 1. */
  aspect?: number;
  /** Round frame for avatars. */
  round?: boolean;
  /** Max zoom. Default 4. */
  maxZoom?: number;
  /** Called as the crop changes, with the area in the image's own pixels. */
  onCropChange?: (area: CropArea) => void;
  /** Width of the frame on screen in px. Default 280. */
  size?: number;
  className?: string;
}

/**
 * برش تصویر. Drag to move the photo under a fixed frame, pinch or use the slider to zoom,
 * rotate by quarter turns. Arrow keys move it, + and − zoom. The image always covers the
 * frame, so the result never has empty corners. Pair with `cropToBlob` to get the file.
 */
export function ImageCropper({ src, aspect = 1, round, maxZoom = 4, onCropChange, size = 280, className }: ImageCropperProps) {
  const fw = size, fh = size / aspect;
  const [nat, setNat] = React.useState<{ w: number; h: number } | null>(null);
  const [zoom, setZoom] = React.useState(1);
  const [rot, setRot] = React.useState(0);
  const [pos, setPos] = React.useState({ x: 0, y: 0 });
  const pointers = React.useRef(new Map<number, { x: number; y: number }>());
  const pinch = React.useRef<{ d: number; z: number } | null>(null);

  // Size of the (rotated) image at zoom 1, scaled to just cover the frame.
  const turned = rot % 180 !== 0;
  const iw = nat ? (turned ? nat.h : nat.w) : 1;
  const ih = nat ? (turned ? nat.w : nat.h) : 1;
  const cover = Math.max(fw / iw, fh / ih);
  const dw = iw * cover * zoom, dh = ih * cover * zoom;
  const clamp = React.useCallback((p: { x: number; y: number }, z = zoom) => {
    const w = iw * cover * z, h = ih * cover * z;
    const mx = (w - fw) / 2, my = (h - fh) / 2;
    return { x: Math.max(-mx, Math.min(mx, p.x)), y: Math.max(-my, Math.min(my, p.y)) };
  }, [iw, ih, cover, zoom, fw, fh]);

  React.useEffect(() => {
    if (!nat || !onCropChange) return;
    const s = cover * zoom;
    // Frame position inside the rotated image, then expressed in source pixels.
    const left = (dw - fw) / 2 - pos.x, top = (dh - fh) / 2 - pos.y;
    onCropChange({ x: Math.round(left / s), y: Math.round(top / s), width: Math.round(fw / s), height: Math.round(fh / s), rotation: rot });
  }, [nat, cover, zoom, pos, dw, dh, fw, fh, rot, onCropChange]);

  const setZoomTo = (z: number) => {
    const nz = Math.min(maxZoom, Math.max(1, z));
    setZoom(nz);
    setPos((p) => clamp(p, nz));
  };

  function down(e: React.PointerEvent) {
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.current.size === 2) {
      const [a, b] = [...pointers.current.values()];
      pinch.current = { d: Math.hypot(a.x - b.x, a.y - b.y), z: zoom };
    }
  }
  function move(e: React.PointerEvent) {
    const prev = pointers.current.get(e.pointerId);
    if (!prev) return;
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.current.size === 2 && pinch.current) {
      const [a, b] = [...pointers.current.values()];
      setZoomTo(pinch.current.z * (Math.hypot(a.x - b.x, a.y - b.y) / pinch.current.d));
    } else if (pointers.current.size === 1) {
      setPos((p) => clamp({ x: p.x + e.clientX - prev.x, y: p.y + e.clientY - prev.y }));
    }
  }
  function up(e: React.PointerEvent) {
    pointers.current.delete(e.pointerId);
    if (pointers.current.size < 2) pinch.current = null;
  }
  function key(e: React.KeyboardEvent) {
    const d = e.shiftKey ? 40 : 10;
    const moves: Record<string, [number, number]> = { ArrowLeft: [d, 0], ArrowRight: [-d, 0], ArrowUp: [0, d], ArrowDown: [0, -d] };
    if (moves[e.key]) { e.preventDefault(); setPos((p) => clamp({ x: p.x + moves[e.key][0], y: p.y + moves[e.key][1] })); }
    else if (e.key === "+" || e.key === "=") { e.preventDefault(); setZoomTo(zoom + 0.2); }
    else if (e.key === "-") { e.preventDefault(); setZoomTo(zoom - 0.2); }
  }

  return (
    <div className={cn("inline-flex flex-col items-center gap-3", className)} style={{ width: fw + 40 }}>
      <div
        role="application"
        tabIndex={0}
        aria-label="ناحیه‌ی برش. با کشیدن یا کلیدهای جهت تصویر را جابه‌جا کنید و با + و − بزرگ‌نمایی کنید."
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={up}
        onPointerCancel={up}
        onWheel={(e) => setZoomTo(zoom - e.deltaY * 0.002)}
        onKeyDown={key}
        className="relative cursor-grab touch-none select-none overflow-hidden rounded-surface bg-black outline-none active:cursor-grabbing focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        style={{ width: fw + 40, height: fh + 40 }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={src}
          alt=""
          draggable={false}
          onLoad={(e) => setNat({ w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight })}
          className="pointer-events-none absolute left-1/2 top-1/2 max-w-none"
          style={{
            width: nat ? (turned ? dh : dw) : "100%",
            height: nat ? (turned ? dw : dh) : "auto",
            transform: `translate(-50%, -50%) translate(${pos.x}px, ${pos.y}px) rotate(${rot}deg)`,
          }}
        />
        {/* Dim everything outside the frame with one huge shadow. */}
        <div aria-hidden className={cn("pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 border-2 border-white/90 shadow-[0_0_0_9999px_rgb(0_0_0/0.55)]", round ? "rounded-full" : "rounded-md")} style={{ width: fw, height: fh }}>
          {!round && (
            <span className="absolute inset-0 grid grid-cols-3 grid-rows-3">
              {Array.from({ length: 9 }, (_, i) => <span key={i} className="border-[0.5px] border-white/25" />)}
            </span>
          )}
        </div>
      </div>
      <div dir="ltr" className="flex w-full items-center gap-2 text-muted-foreground">
        <button type="button" aria-label="کوچک‌نمایی" onClick={() => setZoomTo(zoom - 0.25)} className="rounded-control p-1.5 hover:bg-accent hover:text-foreground"><ZoomOut className="size-4" /></button>
        <input type="range" min={1} max={maxZoom} step={0.01} value={zoom} onChange={(e) => setZoomTo(Number(e.target.value))} aria-label="بزرگ‌نمایی" aria-valuetext={`${fa(Math.round(zoom * 100))}٪`} className="h-1 flex-1 cursor-pointer accent-[var(--primary)]" />
        <button type="button" aria-label="بزرگ‌نمایی" onClick={() => setZoomTo(zoom + 0.25)} className="rounded-control p-1.5 hover:bg-accent hover:text-foreground"><ZoomIn className="size-4" /></button>
        <button type="button" aria-label="چرخش ۹۰ درجه" onClick={() => { setRot((r) => (r + 90) % 360); setPos({ x: 0, y: 0 }); }} className="rounded-control p-1.5 hover:bg-accent hover:text-foreground"><RotateCw className="size-4" /></button>
      </div>
    </div>
  );
}

/** Draws the crop to a canvas and returns a Blob (JPEG by default) at `outputWidth` px wide. */
export async function cropToBlob(src: string, area: CropArea, { outputWidth = 512, type = "image/jpeg", quality = 0.9, round = false }: { outputWidth?: number; type?: string; quality?: number; round?: boolean } = {}): Promise<Blob> {
  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = src;
  await img.decode();
  const scale = outputWidth / area.width;
  const canvas = document.createElement("canvas");
  canvas.width = outputWidth;
  canvas.height = Math.round(area.height * scale);
  const ctx = canvas.getContext("2d")!;
  if (round) { ctx.beginPath(); ctx.ellipse(canvas.width / 2, canvas.height / 2, canvas.width / 2, canvas.height / 2, 0, 0, Math.PI * 2); ctx.clip(); }
  // Rotate the whole image about its rotated bounding box, then shift so the crop sits at 0,0.
  const turned = area.rotation % 180 !== 0;
  const bw = turned ? img.naturalHeight : img.naturalWidth, bh = turned ? img.naturalWidth : img.naturalHeight;
  ctx.scale(scale, scale);
  ctx.translate(-area.x + bw / 2, -area.y + bh / 2);
  ctx.rotate((area.rotation * Math.PI) / 180);
  ctx.drawImage(img, -img.naturalWidth / 2, -img.naturalHeight / 2);
  return new Promise((res, rej) => canvas.toBlob((b) => (b ? res(b) : rej(new Error("crop failed"))), type, quality));
}

"use client";

import * as React from "react";
import { Eraser, Undo2 } from "lucide-react";
import { cn, fa } from "@/lib/utils";

type Point = { x: number; y: number; p: number };
type Stroke = Point[];

export interface SignaturePadHandle {
  clear: () => void;
  undo: () => void;
  isEmpty: () => boolean;
  /** PNG with a transparent background, trimmed to the ink. */
  toDataURL: (type?: string) => string;
  /** The strokes as an SVG string, which stays sharp when printed. */
  toSVG: () => string;
}

export interface SignaturePadProps {
  /** Height in px; the width fills the container. Default 180. */
  height?: number;
  /** Ink color. Defaults to the text color so it works in dark mode. */
  color?: string;
  /** Pen width in px. Pressure varies it up to ±40%. Default 2.5. */
  penWidth?: number;
  /** Called after each stroke with whether the pad has ink. */
  onChange?: (empty: boolean) => void;
  /** Placeholder on the baseline. Default «این‌جا امضا کنید». */
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

function path(stroke: Stroke) {
  if (stroke.length < 2) return "";
  let d = `M${stroke[0].x.toFixed(1)},${stroke[0].y.toFixed(1)}`;
  for (let i = 1; i < stroke.length - 1; i++) {
    const a = stroke[i], b = stroke[i + 1];
    d += ` Q${a.x.toFixed(1)},${a.y.toFixed(1)} ${((a.x + b.x) / 2).toFixed(1)},${((a.y + b.y) / 2).toFixed(1)}`;
  }
  const l = stroke[stroke.length - 1];
  return `${d} L${l.x.toFixed(1)},${l.y.toFixed(1)}`;
}

/**
 * امضا. A pad for signing with finger, pen or mouse: smooth curves, pressure from
 * styluses, undo and clear, and export to a trimmed PNG or SVG. The strokes are kept
 * as data, so resizing the page redraws them instead of losing them.
 */
export const SignaturePad = React.forwardRef<SignaturePadHandle, SignaturePadProps>(function SignaturePad(
  { height = 180, color, penWidth = 2.5, onChange, placeholder = "این‌جا امضا کنید", disabled, className },
  ref,
) {
  const wrap = React.useRef<HTMLDivElement>(null);
  const canvas = React.useRef<HTMLCanvasElement>(null);
  const [strokes, setStrokes] = React.useState<Stroke[]>([]);
  const live = React.useRef<Stroke | null>(null);
  const [width, setWidth] = React.useState(0);
  const ink = React.useRef("#000");

  const draw = React.useCallback((list: Stroke[]) => {
    const c = canvas.current;
    if (!c) return;
    const ctx = c.getContext("2d")!;
    const dpr = window.devicePixelRatio || 1;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, c.width, c.height);
    ctx.strokeStyle = ink.current;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    for (const s of list) {
      const avg = s.reduce((n, p) => n + p.p, 0) / s.length;
      ctx.lineWidth = penWidth * (0.6 + avg * 0.8);
      if (s.length === 1) { ctx.beginPath(); ctx.arc(s[0].x, s[0].y, ctx.lineWidth / 2, 0, Math.PI * 2); ctx.fillStyle = ink.current; ctx.fill(); continue; }
      ctx.stroke(new Path2D(path(s)));
    }
  }, [penWidth]);

  React.useLayoutEffect(() => {
    const el = wrap.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setWidth(Math.round(e.contentRect.width)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  React.useEffect(() => {
    const c = canvas.current;
    if (!c || !width) return;
    ink.current = color ?? getComputedStyle(c).color;
    const dpr = window.devicePixelRatio || 1;
    c.width = width * dpr;
    c.height = height * dpr;
    draw(strokes);
  }, [width, height, color, strokes, draw]);

  const point = (e: React.PointerEvent): Point => {
    const r = canvas.current!.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top, p: e.pointerType === "pen" && e.pressure ? e.pressure : 0.5 };
  };

  function down(e: React.PointerEvent) {
    if (disabled || e.button > 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    live.current = [point(e)];
  }
  function move(e: React.PointerEvent) {
    if (!live.current) return;
    const events = e.nativeEvent.getCoalescedEvents?.() ?? [e.nativeEvent];
    for (const ev of events) live.current.push(point(ev as unknown as React.PointerEvent));
    draw([...strokes, live.current]);
  }
  function up() {
    if (!live.current) return;
    const next = [...strokes, live.current];
    live.current = null;
    setStrokes(next);
    onChange?.(false);
  }

  const bounds = (list: Stroke[]) => {
    const pts = list.flat();
    const pad = penWidth * 2;
    const xs = pts.map((p) => p.x), ys = pts.map((p) => p.y);
    return { x: Math.max(0, Math.min(...xs) - pad), y: Math.max(0, Math.min(...ys) - pad), x2: Math.max(...xs) + pad, y2: Math.max(...ys) + pad };
  };

  React.useImperativeHandle(ref, () => ({
    clear: () => { setStrokes([]); onChange?.(true); },
    undo: () => setStrokes((s) => { const n = s.slice(0, -1); onChange?.(n.length === 0); return n; }),
    isEmpty: () => strokes.length === 0,
    toDataURL: (type = "image/png") => {
      const c = canvas.current;
      if (!c || !strokes.length) return "";
      const b = bounds(strokes);
      const dpr = window.devicePixelRatio || 1;
      const out = document.createElement("canvas");
      out.width = (b.x2 - b.x) * dpr;
      out.height = (b.y2 - b.y) * dpr;
      out.getContext("2d")!.drawImage(c, b.x * dpr, b.y * dpr, out.width, out.height, 0, 0, out.width, out.height);
      return out.toDataURL(type);
    },
    toSVG: () => {
      if (!strokes.length) return "";
      const b = bounds(strokes);
      const paths = strokes.map((s) => `<path d="${path(s.length === 1 ? [s[0], { ...s[0], x: s[0].x + 0.1 }] : s)}"/>`).join("");
      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${b.x.toFixed(1)} ${b.y.toFixed(1)} ${(b.x2 - b.x).toFixed(1)} ${(b.y2 - b.y).toFixed(1)}" fill="none" stroke="${ink.current}" stroke-width="${penWidth}" stroke-linecap="round" stroke-linejoin="round">${paths}</svg>`;
    },
  }));

  const empty = strokes.length === 0;
  return (
    <div className={cn("space-y-2", className)}>
      <div ref={wrap} className={cn("relative overflow-hidden rounded-surface border-line border-dashed border-border bg-card", disabled && "opacity-60")} style={{ height }}>
        <canvas
          ref={canvas}
          role="img"
          aria-label={empty ? "کادر امضا، خالی" : `کادر امضا، ${fa(strokes.length)} خط کشیده شده`}
          onPointerDown={down}
          onPointerMove={move}
          onPointerUp={up}
          onPointerCancel={up}
          className={cn("absolute inset-0 touch-none text-foreground", disabled ? "cursor-not-allowed" : "cursor-crosshair")}
          style={{ width: "100%", height }}
        />
        <div aria-hidden className="pointer-events-none absolute inset-x-6 bottom-10 flex items-end gap-2 border-b border-border">
          <span className="pb-1 text-lg text-muted-foreground/60">×</span>
          {empty && <span className="pb-1.5 text-xs text-muted-foreground">{placeholder}</span>}
        </div>
      </div>
      <div className="flex justify-end gap-1">
        <button type="button" disabled={empty || disabled} onClick={() => { const n = strokes.slice(0, -1); setStrokes(n); onChange?.(n.length === 0); }} className="inline-flex h-8 items-center gap-1.5 rounded-control px-2.5 text-xs text-muted-foreground hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40"><Undo2 className="size-3.5" />برگشت</button>
        <button type="button" disabled={empty || disabled} onClick={() => { setStrokes([]); onChange?.(true); }} className="inline-flex h-8 items-center gap-1.5 rounded-control px-2.5 text-xs text-muted-foreground hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40"><Eraser className="size-3.5" />پاک کردن</button>
      </div>
    </div>
  );
});

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/* ---------- encoder: byte mode, versions 1–40, written from ISO/IEC 18004 ---------- */

export type QrEcc = "L" | "M" | "Q" | "H";
const ECC_FORMAT: Record<QrEcc, number> = { L: 1, M: 0, Q: 3, H: 2 };
const ECC_INDEX: Record<QrEcc, number> = { L: 0, M: 1, Q: 2, H: 3 };

// Per version 1..40 (index 0 unused): error-correction codewords per block, and number of blocks.
const ECC_PER_BLOCK = [
  [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
  [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
];
const BLOCKS = [
  [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
  [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
  [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
  [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81],
];

function rawModules(ver: number) {
  let n = (16 * ver + 128) * ver + 64;
  if (ver >= 2) {
    const align = Math.floor(ver / 7) + 2;
    n -= (25 * align - 10) * align - 55;
    if (ver >= 7) n -= 36;
  }
  return n;
}

const dataCodewords = (ver: number, e: number) => Math.floor(rawModules(ver) / 8) - ECC_PER_BLOCK[e][ver] * BLOCKS[e][ver];

function gfMul(x: number, y: number) {
  let z = 0;
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d);
    z ^= ((y >>> i) & 1) * x;
  }
  return z;
}

function rsDivisor(degree: number) {
  const out = new Array<number>(degree).fill(0);
  out[degree - 1] = 1;
  let root = 1;
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      out[j] = gfMul(out[j], root);
      if (j + 1 < degree) out[j] ^= out[j + 1];
    }
    root = gfMul(root, 2);
  }
  return out;
}

function rsRemainder(data: number[], div: number[]) {
  const out = new Array<number>(div.length).fill(0);
  for (const b of data) {
    const factor = b ^ (out.shift() as number);
    out.push(0);
    div.forEach((c, i) => (out[i] ^= gfMul(c, factor)));
  }
  return out;
}

const bit = (x: number, i: number) => ((x >>> i) & 1) !== 0;

/**
 * The module matrix (true = dark) for `text` in byte mode (UTF-8), so Persian text,
 * URLs and Wi-Fi strings all work. Picks the smallest version that fits.
 */
export function encodeQR(text: string, ecc: QrEcc = "M"): boolean[][] {
  const bytes = Array.from(new TextEncoder().encode(text));
  const e = ECC_INDEX[ecc];
  let ver = 1;
  for (; ver <= 40; ver++) {
    const used = 4 + (ver <= 9 ? 8 : 16) + bytes.length * 8;
    if (used <= dataCodewords(ver, e) * 8) break;
  }
  if (ver > 40) throw new Error("QR: text is too long");

  // Bit stream: mode, count, data, terminator, padding.
  const bits: number[] = [];
  const push = (v: number, n: number) => { for (let i = n - 1; i >= 0; i--) bits.push((v >>> i) & 1); };
  push(4, 4);
  push(bytes.length, ver <= 9 ? 8 : 16);
  bytes.forEach((b) => push(b, 8));
  const cap = dataCodewords(ver, e) * 8;
  push(0, Math.min(4, cap - bits.length));
  push(0, (8 - (bits.length % 8)) % 8);
  for (let pad = 0xec; bits.length < cap; pad ^= 0xec ^ 0x11) push(pad, 8);
  const data: number[] = [];
  for (let i = 0; i < bits.length; i += 8) data.push(bits.slice(i, i + 8).reduce((a, b) => (a << 1) | b, 0));

  // Split into blocks, add error correction, interleave.
  const nBlocks = BLOCKS[e][ver];
  const eccLen = ECC_PER_BLOCK[e][ver];
  const raw = Math.floor(rawModules(ver) / 8);
  const nShort = nBlocks - (raw % nBlocks);
  const shortLen = Math.floor(raw / nBlocks);
  const div = rsDivisor(eccLen);
  const blocks: number[][] = [];
  for (let i = 0, k = 0; i < nBlocks; i++) {
    const dat = data.slice(k, k + shortLen - eccLen + (i < nShort ? 0 : 1));
    k += dat.length;
    const rem = rsRemainder(dat, div);
    if (i < nShort) dat.push(0);
    blocks.push(dat.concat(rem));
  }
  const codewords: number[] = [];
  for (let i = 0; i < blocks[0].length; i++) blocks.forEach((b, j) => { if (i !== shortLen - eccLen || j >= nShort) codewords.push(b[i]); });

  // Function patterns.
  const size = ver * 4 + 17;
  const m: boolean[][] = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const fn: boolean[][] = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const set = (x: number, y: number, dark: boolean) => { m[y][x] = dark; fn[y][x] = true; };
  for (let i = 0; i < size; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }
  const finder = (cx: number, cy: number) => {
    for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) {
      const x = cx + dx, y = cy + dy;
      if (x < 0 || y < 0 || x >= size || y >= size) continue;
      const d = Math.max(Math.abs(dx), Math.abs(dy));
      set(x, y, d !== 2 && d !== 4);
    }
  };
  finder(3, 3); finder(size - 4, 3); finder(3, size - 4);
  if (ver > 1) {
    const n = Math.floor(ver / 7) + 2;
    const step = ver === 32 ? 26 : Math.ceil((ver * 4 + 4) / (n * 2 - 2)) * 2;
    const pos = [6];
    for (let p = size - 7; pos.length < n; p -= step) pos.splice(1, 0, p);
    pos.forEach((a, i) => pos.forEach((b, j) => {
      if ((i === 0 && j === 0) || (i === 0 && j === n - 1) || (i === n - 1 && j === 0)) return;
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) set(a + dx, b + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
    }));
  }
  const format = (mask: number) => {
    const d = (ECC_FORMAT[ecc] << 3) | mask;
    let r = d;
    for (let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
    const b = ((d << 10) | r) ^ 0x5412;
    for (let i = 0; i <= 5; i++) set(8, i, bit(b, i));
    set(8, 7, bit(b, 6)); set(8, 8, bit(b, 7)); set(7, 8, bit(b, 8));
    for (let i = 9; i < 15; i++) set(14 - i, 8, bit(b, i));
    for (let i = 0; i < 8; i++) set(size - 1 - i, 8, bit(b, i));
    for (let i = 8; i < 15; i++) set(8, size - 15 + i, bit(b, i));
    set(8, size - 8, true);
  };
  format(0);
  if (ver >= 7) {
    let r = ver;
    for (let i = 0; i < 12; i++) r = (r << 1) ^ ((r >>> 11) * 0x1f25);
    const b = (ver << 12) | r;
    for (let i = 0; i < 18; i++) {
      const a = size - 11 + (i % 3), c = Math.floor(i / 3);
      set(a, c, bit(b, i)); set(c, a, bit(b, i));
    }
  }

  // Data in the zigzag order.
  let i = 0;
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let v = 0; v < size; v++) for (let j = 0; j < 2; j++) {
      const x = right - j;
      const y = ((right + 1) & 2) === 0 ? size - 1 - v : v;
      if (!fn[y][x] && i < codewords.length * 8) { m[y][x] = bit(codewords[i >>> 3], 7 - (i & 7)); i++; }
    }
  }

  // Try all eight masks and keep the one with the lowest penalty.
  const masks = [
    (x: number, y: number) => (x + y) % 2 === 0,
    (_: number, y: number) => y % 2 === 0,
    (x: number) => x % 3 === 0,
    (x: number, y: number) => (x + y) % 3 === 0,
    (x: number, y: number) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,
    (x: number, y: number) => ((x * y) % 2) + ((x * y) % 3) === 0,
    (x: number, y: number) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
    (x: number, y: number) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
  ];
  const apply = (k: number) => { for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) if (!fn[y][x] && masks[k](x, y)) m[y][x] = !m[y][x]; };
  let best = 0, bestScore = Infinity;
  for (let k = 0; k < 8; k++) {
    apply(k); format(k);
    const s = penalty(m);
    if (s < bestScore) { bestScore = s; best = k; }
    apply(k);
  }
  apply(best); format(best);
  return m;
}

/** The four standard penalty rules, close enough to pick a well-readable mask. */
function penalty(m: boolean[][]) {
  const n = m.length;
  let score = 0, dark = 0;
  const line = (get: (i: number) => boolean) => {
    let run = 1;
    let s = "";
    for (let i = 0; i < n; i++) {
      const v = get(i);
      s += v ? "1" : "0";
      if (i > 0 && v === get(i - 1)) { run++; if (run === 5) score += 3; else if (run > 5) score += 1; }
      else run = 1;
    }
    for (const p of ["10111010000", "00001011101"]) for (let at = s.indexOf(p); at >= 0; at = s.indexOf(p, at + 1)) score += 40;
  };
  for (let y = 0; y < n; y++) line((x) => m[y][x]);
  for (let x = 0; x < n; x++) line((y) => m[y][x]);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (m[y][x]) dark++;
    if (x < n - 1 && y < n - 1 && m[y][x] === m[y][x + 1] && m[y][x] === m[y + 1][x] && m[y][x] === m[y + 1][x + 1]) score += 3;
  }
  return score + Math.floor(Math.abs(dark * 20 - n * n * 10) / (n * n)) * 10;
}

/* ---------- component ---------- */

export interface QRCodeProps {
  value: string;
  /** Rendered size in px. Default 168. */
  size?: number;
  /** Error correction. A center logo needs "H". Default "M". */
  ecc?: QrEcc;
  /** Quiet zone in modules. Scanners want 4; 2 is usually fine on a plain card. */
  margin?: number;
  /** Rounded dots instead of squares. Finder eyes stay square-ish so scanners lock on. */
  rounded?: boolean;
  /** Dark color. Light is always the card background, so dark mode still scans. */
  color?: string;
  /** Spoken name, e.g. «لینک پرداخت». Defaults to the value. */
  label?: string;
  /** Something small for the middle, like a logo slot. Forces ecc "H". */
  children?: React.ReactNode;
  className?: string;
}

/**
 * کد QR. Generated in the browser with no dependency: byte mode with UTF-8, so
 * Persian text works, the smallest version that fits, and the best of eight masks.
 * Drawn as one SVG path. Light modules use a fixed white so it scans in dark mode.
 */
export function QRCode({ value, size = 168, ecc = "M", margin = 4, rounded, color = "#111", label, children, className }: QRCodeProps) {
  const level = children ? "H" : ecc;
  const matrix = React.useMemo(() => encodeQR(value, level), [value, level]);
  const n = matrix.length;
  const total = n + margin * 2;
  const isEye = (x: number, y: number) => (x < 7 && y < 7) || (x >= n - 7 && y < 7) || (x < 7 && y >= n - 7);
  let d = "";
  let dots = "";
  matrix.forEach((row, y) => row.forEach((on, x) => {
    if (!on) return;
    const X = x + margin, Y = y + margin;
    if (rounded && !isEye(x, y)) dots += `M${X + 0.5},${Y + 0.08}a0.42,0.42 0 1,0 0.001,0Z`;
    else d += `M${X},${Y}h1v1h-1z`;
  }));
  // Leave a clear square in the middle for the logo (H recovers up to 30%).
  const hole = Math.ceil(n * 0.22) | 1;
  const h0 = margin + (n - hole) / 2;

  return (
    <div role="img" aria-label={`کد QR: ${label ?? value}`} className={cn("relative inline-block overflow-hidden rounded-control bg-white", className)} style={{ width: size, height: size }}>
      <svg viewBox={`0 0 ${total} ${total}`} width={size} height={size} shapeRendering={rounded ? "geometricPrecision" : "crispEdges"} aria-hidden>
        <path d={d} fill={color} />
        {dots && <path d={dots} fill={color} />}
        {children && <rect x={h0} y={h0} width={hole} height={hole} rx={1} fill="#fff" />}
      </svg>
      {children && (
        <span className="absolute inset-0 m-auto flex items-center justify-center" style={{ width: (hole / total) * size * 0.86, height: (hole / total) * size * 0.86 }}>
          {children}
        </span>
      )}
    </div>
  );
}

/** «WIFI:T:WPA;S:name;P:pass;;» for a Wi-Fi QR code, with the special characters escaped. */
export function wifiQR({ ssid, password, security = "WPA", hidden }: { ssid: string; password?: string; security?: "WPA" | "WEP" | "nopass"; hidden?: boolean }) {
  const esc = (s: string) => s.replace(/([\\;,:"])/g, "\\$1");
  return `WIFI:T:${security};S:${esc(ssid)};${password ? `P:${esc(password)};` : ""}${hidden ? "H:true;" : ""};`;
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type MentionUser = { id: string; name: string; handle: string; subtitle?: string; avatar?: string };

export interface MentionInputProps {
  value?: string;
  defaultValue?: string;
  onChange?: (value: string, mentions: MentionUser[]) => void;
  users: MentionUser[];
  /** Character that opens the list. Default "@". */
  trigger?: string;
  placeholder?: string;
  rows?: number;
  /** Most suggestions shown. Default 6. */
  limit?: number;
  id?: string;
  "aria-label"?: string;
  className?: string;
}

/** Folds Arabic ي/ك into Persian ی/ک and drops ZWNJ so «علی» matches «علي». */
const fold = (s: string) => s.toLowerCase().replace(/ي/g, "ی").replace(/ك/g, "ک").replace(/‌/g, "");

/** The users mentioned as @handle in `text`. */
export function parseMentions(text: string, users: MentionUser[], trigger = "@") {
  const found = new Map<string, MentionUser>();
  for (const u of users) if (new RegExp(`(^|\\s)${trigger}${u.handle}(?![\\w\\u0600-\\u06FF])`, "u").test(text)) found.set(u.id, u);
  return [...found.values()];
}

/**
 * منشن. A textarea that suggests people after @, matching Persian or Latin names and
 * handles (ي and ک fold to ی and ک). The list is an ARIA combobox: Up/Down to choose,
 * Enter or Tab to insert «@handle», Escape to close. Handles are Latin and stay LTR.
 */
export function MentionInput({ value, defaultValue = "", onChange, users, trigger = "@", placeholder, rows = 3, limit = 6, id, className, ...aria }: MentionInputProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const text = value ?? internal;
  const ta = React.useRef<HTMLTextAreaElement>(null);
  const [query, setQuery] = React.useState<{ at: number; q: string } | null>(null);
  const [active, setActive] = React.useState(0);
  const autoId = React.useId();
  const base = id ?? autoId;

  const matches = query
    ? users.filter((u) => fold(u.name).includes(fold(query.q)) || u.handle.toLowerCase().startsWith(query.q.toLowerCase())).slice(0, limit)
    : [];
  const open = !!query && matches.length > 0;

  const set = (next: string) => {
    if (value === undefined) setInternal(next);
    onChange?.(next, parseMentions(next, users, trigger));
  };

  /** Find an open «@query» that ends at the caret. */
  const scan = (el: HTMLTextAreaElement) => {
    const upto = el.value.slice(0, el.selectionStart ?? 0);
    const at = upto.lastIndexOf(trigger);
    if (at < 0 || (at > 0 && !/\s/.test(upto[at - 1]))) return setQuery(null);
    const q = upto.slice(at + trigger.length);
    if (/\s/.test(q) || q.length > 24) return setQuery(null);
    setQuery({ at, q });
    setActive(0);
  };

  function insert(u: MentionUser) {
    if (!query || !ta.current) return;
    const caret = ta.current.selectionStart ?? text.length;
    const token = `${trigger}${u.handle} `;
    const next = text.slice(0, query.at) + token + text.slice(caret);
    set(next);
    setQuery(null);
    const pos = query.at + token.length;
    requestAnimationFrame(() => { ta.current?.focus(); ta.current?.setSelectionRange(pos, pos); });
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (!open) return;
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (a + 1) % matches.length); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (a - 1 + matches.length) % matches.length); }
    else if (e.key === "Enter" || e.key === "Tab") { e.preventDefault(); insert(matches[active]); }
    else if (e.key === "Escape") { e.preventDefault(); setQuery(null); }
  }

  return (
    <div className={cn("relative", className)}>
      <textarea
        ref={ta}
        id={base}
        rows={rows}
        value={text}
        placeholder={placeholder}
        aria-label={aria["aria-label"]}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={open}
        aria-controls={`${base}-list`}
        aria-activedescendant={open ? `${base}-opt-${matches[active]?.id}` : undefined}
        onChange={(e) => { set(e.target.value); scan(e.target); }}
        onKeyDown={onKeyDown}
        onClick={(e) => scan(e.currentTarget)}
        onBlur={() => setTimeout(() => setQuery(null), 120)}
        className="w-full resize-y rounded-field border-line-field border-input bg-field px-3 py-2.5 text-sm leading-7 shadow-field outline-none placeholder:text-muted-foreground/60 focus-visible:ring-2 focus-visible:ring-ring/60"
      />
      <ul
        id={`${base}-list`}
        role="listbox"
        aria-label="پیشنهاد افراد"
        hidden={!open}
        className="absolute inset-x-0 top-full z-30 mt-1 max-h-64 overflow-y-auto rounded-overlay border border-border bg-popover p-1 text-popover-foreground shadow-overlay"
      >
        {matches.map((u, i) => (
          <li
            key={u.id}
            id={`${base}-opt-${u.id}`}
            role="option"
            aria-selected={i === active}
            onPointerDown={(e) => { e.preventDefault(); insert(u); }}
            onPointerEnter={() => setActive(i)}
            className={cn("flex cursor-pointer items-center gap-2.5 rounded-control px-2 py-1.5", i === active && "bg-accent")}
          >
            {u.avatar ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={u.avatar} alt="" className="size-7 rounded-full object-cover" />
            ) : (
              <span aria-hidden className="flex size-7 shrink-0 items-center justify-center rounded-full bg-secondary text-xs font-semibold">{u.name.charAt(0)}</span>
            )}
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm font-medium">{u.name}</span>
              {u.subtitle && <span className="block truncate text-[11px] text-muted-foreground">{u.subtitle}</span>}
            </span>
            <bdi dir="ltr" className="shrink-0 text-xs text-muted-foreground">{trigger}{u.handle}</bdi>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** Renders text with each @handle as a highlighted chip, for showing a sent message. */
export function MentionText({ children, users, trigger = "@", className }: { children: string; users: MentionUser[]; trigger?: string; className?: string }) {
  const handles = new Map(users.map((u) => [u.handle.toLowerCase(), u]));
  const parts = children.split(new RegExp(`(${trigger}[A-Za-z0-9_.]+)`, "g"));
  return (
    <p className={cn("whitespace-pre-wrap leading-7", className)}>
      {parts.map((p, i) => {
        const u = p.startsWith(trigger) ? handles.get(p.slice(trigger.length).toLowerCase()) : undefined;
        return u ? (
          <bdi key={i} dir="ltr" title={u.name} className="rounded bg-brand/10 px-1 font-medium text-brand">{p}</bdi>
        ) : (
          <React.Fragment key={i}>{p}</React.Fragment>
        );
      })}
    </p>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { cn, fa } from "@/lib/utils";

export type TourStep = {
  /** CSS selector of the element to highlight. Without one the step is a centered card. */
  target?: string;
  title: string;
  body: React.ReactNode;
  /** Card side relative to the target. Default "bottom". */
  side?: "top" | "bottom";
};

export interface ProductTourProps {
  steps: TourStep[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Called after the last step's «تموم». Skipping only calls onOpenChange(false). */
  onFinish?: () => void;
  /** Space around the highlighted element in px. Default 8. */
  padding?: number;
}

const noop = () => () => {};

type Box = { top: number; left: number; width: number; height: number };

/**
 * تور معرفی. Walks a new user through the page: dims everything except one element,
 * places a card next to it with «بعدی» and «قبلی», and scrolls each target into view.
 * The card is a dialog that takes focus; Escape skips, and arrows move in RTL order.
 */
export function ProductTour({ steps, open, onOpenChange, onFinish, padding = 8 }: ProductTourProps) {
  const [i, setI] = React.useState(0);
  const [box, setBox] = React.useState<Box | null>(null);
  const mounted = React.useSyncExternalStore(noop, () => true, () => false);
  const card = React.useRef<HTMLDivElement>(null);
  const titleId = React.useId();
  const step = steps[i];
  const last = i === steps.length - 1;

  const [wasOpen, setWasOpen] = React.useState(open);
  if (wasOpen !== open) { setWasOpen(open); if (open) setI(0); }

  const measure = React.useCallback(() => {
    const el = step?.target ? document.querySelector<HTMLElement>(step.target) : null;
    if (!el) return setBox(null);
    const r = el.getBoundingClientRect();
    setBox({ top: r.top - padding, left: r.left - padding, width: r.width + padding * 2, height: r.height + padding * 2 });
  }, [step, padding]);

  React.useLayoutEffect(() => {
    if (!open || !step) return;
    const el = step.target ? document.querySelector<HTMLElement>(step.target) : null;
    el?.scrollIntoView({ block: "center", behavior: "smooth" });
    const raf = requestAnimationFrame(measure);
    const t = window.setTimeout(measure, 350);
    window.addEventListener("resize", measure);
    window.addEventListener("scroll", measure, true);
    card.current?.focus();
    return () => { cancelAnimationFrame(raf); window.clearTimeout(t); window.removeEventListener("resize", measure); window.removeEventListener("scroll", measure, true); };
  }, [open, step, measure]);

  if (!mounted || !open || !step) return null;

  const close = () => onOpenChange(false);
  const next = () => { if (last) { onFinish?.(); close(); } else setI(i + 1); };
  const prev = () => i > 0 && setI(i - 1);

  const vw = typeof window !== "undefined" ? window.innerWidth : 1024;
  const vh = typeof window !== "undefined" ? window.innerHeight : 768;
  const cardW = Math.min(320, vw - 24);
  const side = step.side ?? (box && box.top + box.height + 220 > vh ? "top" : "bottom");
  const style: React.CSSProperties = box
    ? {
        width: cardW,
        left: Math.min(vw - cardW - 12, Math.max(12, box.left + box.width / 2 - cardW / 2)),
        ...(side === "bottom" ? { top: Math.min(vh - 12, box.top + box.height + 12) } : { bottom: Math.max(12, vh - box.top + 12) }),
      }
    : { width: cardW, left: "50%", top: "50%", transform: "translate(-50%, -50%)" };

  return createPortal(
    <div className="fixed inset-0 z-[60]" role="presentation">
      {/* The spotlight: one transparent box whose huge shadow dims the page around it. */}
      <div
        aria-hidden
        onClick={close}
        className="fixed rounded-surface transition-all duration-300 ease-motion"
        style={box ? { ...box, boxShadow: "0 0 0 9999px rgb(0 0 0 / 0.55)" } : { inset: 0, background: "rgb(0 0 0 / 0.55)" }}
      />
      {box && <div aria-hidden className="pointer-events-none fixed rounded-surface ring-2 ring-white/80 transition-all duration-300 ease-motion" style={box} />}
      <div
        ref={card}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        onKeyDown={(e) => {
          if (e.key === "Escape") close();
          else if (e.key === "ArrowLeft") next();
          else if (e.key === "ArrowRight") prev();
        }}
        className="fixed rounded-overlay border border-border bg-popover p-4 text-popover-foreground shadow-overlay outline-none"
        style={style}
      >
        <div className="flex items-start justify-between gap-3">
          <h2 id={titleId} className="font-semibold">{step.title}</h2>
          <button type="button" aria-label="رد کردن تور" onClick={close} className="-me-1 -mt-1 rounded-control p-1 text-muted-foreground hover:bg-accent hover:text-foreground"><X className="size-4" /></button>
        </div>
        <div className="mt-1.5 text-sm leading-7 text-muted-foreground">{step.body}</div>
        <div className="mt-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-1" aria-label={`مرحله‌ی ${fa(i + 1)} از ${fa(steps.length)}`} role="img">
            {steps.map((_, k) => <span key={k} className={cn("h-1.5 rounded-full transition-all", k === i ? "w-4 bg-primary" : "w-1.5 bg-border")} />)}
          </div>
          <div className="flex gap-2">
            {i > 0 && <button type="button" onClick={prev} className="h-8 rounded-control px-3 text-sm text-muted-foreground hover:bg-accent">قبلی</button>}
            <button type="button" onClick={next} className="h-8 rounded-control bg-primary px-3.5 text-sm font-medium text-primary-foreground hover:bg-primary/90">{last ? "تموم" : "بعدی"}</button>
          </div>
        </div>
      </div>
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { eventInside, FloatPortal, useFloat } from "@/lib/float";

export type MenubarItem =
  | { type?: "item"; label: string; shortcut?: string; disabled?: boolean; danger?: boolean; onSelect?: () => void }
  | { type: "checkbox"; label: string; checked: boolean; onCheckedChange: (checked: boolean) => void; shortcut?: string }
  | { type: "separator" };

export type MenubarMenu = { label: string; items: MenubarItem[] };

export interface MenubarProps {
  menus: MenubarMenu[];
  className?: string;
}

const actionable = (it: MenubarItem) => it.type !== "separator" && !(it.type !== "checkbox" && it.disabled);

/**
 * نوار منو. The «فایل، ویرایش، نما» bar of desktop-style apps: role=menubar, the first
 * menu on the right. ArrowLeft goes to the next menu (RTL), Down opens it, and once one
 * menu is open hovering another switches to it. Shortcuts show as LTR kbd on the far side.
 */
export function Menubar({ menus, className }: MenubarProps) {
  const [open, setOpen] = React.useState<number | null>(null);
  const [focusTop, setFocusTop] = React.useState(0);
  const [active, setActive] = React.useState(-1);
  const tops = React.useRef<(HTMLButtonElement | null)[]>([]);
  const anchor = React.useRef<HTMLButtonElement | null>(null);
  // Point the float anchor at the open menu's button before useFloat measures it.
  React.useLayoutEffect(() => {
    anchor.current = open !== null ? tops.current[open] : null;
  }, [open]);
  const f = useFloat(open !== null, anchor, { align: "start", gap: 4 });
  const bar = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (open === null) return;
    f.update();
    const close = (e: Event) => { if (!eventInside(e, bar.current, f.panel.current)) setOpen(null); };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open, f]);

  const items = open !== null ? menus[open].items : [];
  const moveTop = (to: number, keepOpen: boolean) => {
    const n = (to + menus.length) % menus.length;
    setFocusTop(n);
    tops.current[n]?.focus();
    if (keepOpen) { setOpen(n); setActive(menus[n].items.findIndex(actionable)); }
  };
  const step = (dir: 1 | -1) => {
    if (!items.length) return;
    let k = active;
    for (let t = 0; t < items.length; t++) {
      k = (k + dir + items.length) % items.length;
      if (actionable(items[k])) { setActive(k); return; }
    }
  };
  const run = (it: MenubarItem) => {
    if (it.type === "separator") return;
    if (it.type === "checkbox") it.onCheckedChange(!it.checked);
    else if (!it.disabled) it.onSelect?.();
    setOpen(null);
    tops.current[focusTop]?.focus();
  };

  function onKeyDown(e: React.KeyboardEvent) {
    const k = e.key;
    if (k === "ArrowLeft") moveTop(focusTop + 1, open !== null);
    else if (k === "ArrowRight") moveTop(focusTop - 1, open !== null);
    else if (k === "ArrowDown") { if (open === null) { setOpen(focusTop); setActive(menus[focusTop].items.findIndex(actionable)); } else step(1); }
    else if (k === "ArrowUp") { if (open === null) { setOpen(focusTop); setActive(menus[focusTop].items.map(actionable).lastIndexOf(true)); } else step(-1); }
    else if ((k === "Enter" || k === " ") && open !== null && active >= 0) run(items[active]);
    else if ((k === "Enter" || k === " ") && open === null) { setOpen(focusTop); setActive(menus[focusTop].items.findIndex(actionable)); }
    else if (k === "Escape") setOpen(null);
    else if (k === "Home") moveTop(0, open !== null);
    else if (k === "End") moveTop(menus.length - 1, open !== null);
    else return;
    e.preventDefault();
  }

  const menuId = (i: number) => `menubar-${i}`;
  return (
    <div ref={bar} role="menubar" aria-orientation="horizontal" onKeyDown={onKeyDown} className={cn("flex h-10 items-center gap-0.5 rounded-control border-line border-border bg-background p-1", className)}>
      {menus.map((m, i) => (
        <button
          key={m.label}
          ref={(el) => { tops.current[i] = el; }}
          type="button"
          role="menuitem"
          aria-haspopup="menu"
          aria-expanded={open === i}
          aria-controls={open === i ? menuId(i) : undefined}
          tabIndex={i === focusTop ? 0 : -1}
          onClick={() => { setFocusTop(i); setOpen(open === i ? null : i); setActive(-1); }}
          onPointerEnter={() => { if (open !== null && open !== i) { setOpen(i); setFocusTop(i); setActive(-1); } }}
          className={cn("h-8 cursor-default rounded-[calc(var(--radius-control,8px)-2px)] px-3 text-sm outline-none transition-colors focus-visible:bg-accent", open === i ? "bg-accent" : "hover:bg-accent/60")}
        >
          {m.label}
        </button>
      ))}
      <FloatPortal
        open={open !== null}
        mounted={f.mounted}
        style={{ ...f.style, position: "fixed" }}
        theme={f.theme}
        panelRef={f.panel}
        id={open !== null ? menuId(open) : undefined}
        role="menu"
        aria-label={open !== null ? menus[open].label : undefined}
        aria-activedescendant={open !== null && active >= 0 ? `${menuId(open)}-${active}` : undefined}
        dir="rtl"
        className="z-50 min-w-52 rounded-overlay border border-border bg-popover p-1 text-sm text-popover-foreground shadow-overlay"
      >
        {items.map((it, k) => {
          if (it.type === "separator") return <div key={k} role="separator" className="-mx-1 my-1 h-px bg-border" />;
          const disabled = it.type !== "checkbox" && it.disabled;
          return (
            <div
              key={k}
              id={`${menuId(open!)}-${k}`}
              role={it.type === "checkbox" ? "menuitemcheckbox" : "menuitem"}
              aria-checked={it.type === "checkbox" ? it.checked : undefined}
              aria-disabled={disabled || undefined}
              onPointerEnter={() => !disabled && setActive(k)}
              onClick={() => !disabled && run(it)}
              className={cn(
                "flex h-8 cursor-default items-center gap-2 rounded-control ps-7 pe-2",
                k === active && "bg-accent",
                disabled && "opacity-45",
                it.type !== "checkbox" && it.danger && "text-destructive",
                "relative",
              )}
            >
              {it.type === "checkbox" && it.checked && <Check className="absolute start-2 size-3.5" />}
              <span className="flex-1">{it.label}</span>
              {it.shortcut && <kbd dir="ltr" className="font-sans text-[11px] tracking-wider text-muted-foreground">{it.shortcut}</kbd>}
            </div>
          );
        })}
      </FloatPortal>
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown, type LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

export type NavLink = { title: string; href: string; description?: string; icon?: LucideIcon };

export type NavMenuEntry = {
  label: string;
  /** A plain link at the top level. */
  href?: string;
  /** Links in the dropdown panel. */
  links?: NavLink[];
  /** A highlighted card on the start side of the panel. */
  featured?: { title: string; description: string; href: string; cta?: string };
  /** Columns for the links. Default 2. */
  columns?: 1 | 2 | 3;
};

export interface NavigationMenuProps {
  items: NavMenuEntry[];
  /** ms before a hovered trigger opens and before leaving closes. Default 120 / 220. */
  openDelay?: number;
  closeDelay?: number;
  className?: string;
}

function LinkIcon({ icon }: { icon: LucideIcon }) {
  return React.createElement(icon, { className: "size-4", "aria-hidden": true });
}

/**
 * منوی ناوبری سایت. Header links where some entries open a wide panel of links with
 * descriptions and a featured card. Hover with a short delay so the panel doesn't flicker,
 * or click; moving between triggers while open slides the panel over. It's a disclosure
 * nav (not role=menu): Tab moves through links, Escape closes and returns focus.
 */
export function NavigationMenu({ items, openDelay = 120, closeDelay = 220, className }: NavigationMenuProps) {
  const [open, setOpen] = React.useState<number | null>(null);
  const [hoverOpened, setHoverOpened] = React.useState(false);
  const timer = React.useRef<number | undefined>(undefined);
  const triggers = React.useRef<(HTMLButtonElement | null)[]>([]);
  const root = React.useRef<HTMLElement>(null);
  const [x, setX] = React.useState<{ start: number } | null>(null);
  const id = React.useId();

  const schedule = (fn: () => void, ms: number) => { window.clearTimeout(timer.current); timer.current = window.setTimeout(fn, ms); };
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useEffect(() => {
    if (open === null) return;
    const t = triggers.current[open];
    const r = root.current;
    if (t && r) {
      const rr = r.getBoundingClientRect(), tr = t.getBoundingClientRect();
      // Inline-start offset of the trigger inside the bar (from the right in RTL).
      const rtl = getComputedStyle(r).direction === "rtl";
      setX({ start: rtl ? rr.right - tr.right : tr.left - rr.left });
    }
    const close = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(null); };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);

  const entry = open !== null ? items[open] : null;

  return (
    <nav
      ref={root}
      aria-label="اصلی"
      className={cn("relative", className)}
      onPointerLeave={() => hoverOpened && schedule(() => setOpen(null), closeDelay)}
      onPointerEnter={() => window.clearTimeout(timer.current)}
      onKeyDown={(e) => { if (e.key === "Escape" && open !== null) { triggers.current[open]?.focus(); setOpen(null); } }}
    >
      <ul className="flex items-center gap-1">
        {items.map((it, i) => (
          <li key={it.label}>
            {it.links ? (
              <button
                ref={(el) => { triggers.current[i] = el; }}
                type="button"
                aria-expanded={open === i}
                aria-controls={`${id}-panel`}
                onClick={() => { setHoverOpened(false); setOpen(open === i ? null : i); }}
                onPointerEnter={(e) => {
                  if (e.pointerType !== "mouse") return;
                  if (open !== null) { window.clearTimeout(timer.current); setOpen(i); }
                  else schedule(() => { setHoverOpened(true); setOpen(i); }, openDelay);
                }}
                className={cn("flex h-9 items-center gap-1 rounded-control px-3 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/60", open === i ? "bg-accent" : "hover:bg-accent/60")}
              >
                {it.label}
                <ChevronDown aria-hidden className={cn("size-3.5 text-muted-foreground transition-transform duration-(--motion) ease-motion", open === i && "rotate-180")} />
              </button>
            ) : (
              <a href={it.href} className="flex h-9 items-center rounded-control px-3 text-sm font-medium outline-none hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/60">{it.label}</a>
            )}
          </li>
        ))}
      </ul>

      <div
        id={`${id}-panel`}
        hidden={!entry}
        className="absolute top-full z-40 pt-2 transition-[inset-inline-start] duration-200 ease-motion"
        style={{ insetInlineStart: Math.max(0, (x?.start ?? 0) - 8) }}
      >
        {entry && (
          <div className="flex gap-2 rounded-overlay border border-border bg-popover p-2 text-popover-foreground shadow-overlay">
            {entry.featured && (
              <a href={entry.featured.href} className="flex w-52 shrink-0 flex-col justify-end rounded-surface bg-[linear-gradient(160deg,oklch(from_var(--brand)_l_c_h/22%),oklch(from_var(--brand)_l_c_h/6%))] p-4 outline-none focus-visible:ring-2 focus-visible:ring-ring">
                <span className="font-display text-base font-bold">{entry.featured.title}</span>
                <span className="mt-1 text-xs leading-6 text-muted-foreground">{entry.featured.description}</span>
                {entry.featured.cta && <span className="mt-3 text-xs font-semibold text-brand">{entry.featured.cta} ←</span>}
              </a>
            )}
            <ul className={cn("grid gap-0.5", (entry.columns ?? 2) === 1 ? "w-64 grid-cols-1" : (entry.columns ?? 2) === 2 ? "w-[30rem] grid-cols-2" : "w-[42rem] grid-cols-3")}>
              {entry.links!.map((l) => (
                <li key={l.href + l.title}>
                  <a href={l.href} onClick={() => setOpen(null)} className="flex gap-3 rounded-control p-2.5 outline-none transition-colors hover:bg-accent focus-visible:bg-accent">
                    {l.icon && <span className="flex size-8 shrink-0 items-center justify-center rounded-control border-line border-border bg-background text-muted-foreground"><LinkIcon icon={l.icon} /></span>}
                    <span className="min-w-0">
                      <span className="block text-sm font-medium">{l.title}</span>
                      {l.description && <span className="mt-0.5 line-clamp-2 block text-xs leading-5 text-muted-foreground">{l.description}</span>}
                    </span>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </nav>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { compactFa, extent, jalaliLabel, niceTicks, textWidth, type Domain } from "@/lib/chart-utils";

/* ---------- data model ---------- */

/** One row of chart data, e.g. { month: "فروردین", sales: 120, cost: 80 }. */
export type Row = Record<string, unknown>;

export type Series = {
  /** Field of each row that holds this series' number. */
  key: string;
  /** Persian name for the legend and tooltip. */
  label: string;
  /** Any CSS color; defaults to the palette slot of this series. */
  color?: string;
  /** Dashed stroke, e.g. a forecast or last year. */
  dashed?: boolean;
};

export type Reference = { value: number; label?: string; color?: string };

/**
 * Series colors. Each slot reads `--chart-N` first, so a design system can set
 * its own palette; the fallbacks are hue-separated and work on light and dark.
 */
export const CHART_COLORS = [
  "var(--chart-1, var(--brand))",
  "var(--chart-2, oklch(0.66 0.14 250))",
  "var(--chart-3, oklch(0.7 0.14 165))",
  "var(--chart-4, oklch(0.65 0.19 20))",
  "var(--chart-5, oklch(0.62 0.16 300))",
  "var(--chart-6, oklch(0.75 0.11 200))",
  "var(--chart-7, oklch(0.6 0.03 260))",
];

export function colorAt(i: number, own?: string) {
  return own ?? CHART_COLORS[i % CHART_COLORS.length];
}

/** Number at `key`, or null for missing/NaN so lines can break instead of falling to zero. */
export function num(row: Row | undefined, key: string): number | null {
  const v = row?.[key];
  if (typeof v === "number") return isFinite(v) ? v : null;
  if (typeof v === "string" && v.trim() !== "" && isFinite(+v)) return +v;
  return null;
}

/** Default category label: Date → «۱۲ مهر», number → Persian digits, anything else as text. */
export function defaultLabel(v: unknown): string {
  if (v instanceof Date) return jalaliLabel(v);
  if (typeof v === "number") return fa(v);
  return String(v ?? "");
}

export type ValueFormat = (n: number) => string;
export const defaultFormat: ValueFormat = compactFa;

/* ---------- hooks ---------- */

/** Width of an element, kept current with ResizeObserver. 0 until mounted. */
export function useWidth<T extends HTMLElement>(): [React.RefObject<T | null>, number] {
  const ref = React.useRef<T>(null);
  const [w, setW] = React.useState(0);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setW(el.clientWidth);
    const ro = new ResizeObserver(([e]) => setW(Math.round(e.contentRect.width)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, w];
}

/** Hidden series keys, toggled from the legend. Never hides the last visible one. */
export function useHidden(series: { key: string }[]) {
  const [hidden, setHidden] = React.useState<Set<string>>(() => new Set());
  const toggle = React.useCallback(
    (key: string) =>
      setHidden((h) => {
        const next = new Set(h);
        if (next.has(key)) next.delete(key);
        else if (series.length - next.size > 1) next.add(key);
        return next;
      }),
    [series.length],
  );
  return { hidden, toggle };
}

/**
 * Active item for hover and keyboard. In RTL the next item is on the left,
 * so ArrowLeft moves forward and ArrowRight moves back; Home/End jump.
 */
export function useActive(count: number) {
  const [active, setActive] = React.useState<number | null>(null);
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!count) return;
    const cur = active ?? -1;
    let next: number | null = null;
    if (e.key === "ArrowLeft" || e.key === "ArrowDown") next = Math.min(count - 1, cur + 1);
    else if (e.key === "ArrowRight" || e.key === "ArrowUp") next = Math.max(0, cur < 0 ? 0 : cur - 1);
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = count - 1;
    else if (e.key === "Escape") { setActive(null); return; }
    if (next !== null) { e.preventDefault(); setActive(next); }
  };
  return { active, setActive, onKeyDown, onBlur: () => setActive(null) };
}

/* ---------- styles ---------- */

const CSS = `
.vf-chart{--vf-ease:var(--motion-ease,cubic-bezier(.2,0,0,1));--vf-dur:calc(var(--motion,200ms)*4)}
.vf-chart text{font-family:inherit}
@keyframes vf-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@keyframes vf-grow{from{transform:scale(var(--vf-sx,1),var(--vf-sy,0))}}
@keyframes vf-fade{from{opacity:0}}
@keyframes vf-pop{from{opacity:0;transform:scale(.85)}}
.vf-draw{stroke-dasharray:1;animation:vf-draw var(--vf-dur) var(--vf-ease) both}
.vf-grow{transform-box:fill-box;animation:vf-grow var(--vf-dur) var(--vf-ease) both}
.vf-fade{animation:vf-fade var(--vf-dur) var(--vf-ease) both}
.vf-pop{transform-box:fill-box;transform-origin:center;animation:vf-pop var(--vf-dur) var(--vf-ease) both}
.vf-mark{transition:opacity var(--motion,200ms) var(--vf-ease)}
@media (prefers-reduced-motion:reduce){.vf-draw,.vf-grow,.vf-fade,.vf-pop{animation:none}}
`;

/** Keyframes shared by every chart, hoisted and de-duplicated by React 19. */
export function ChartStyles() {
  return (
    <style href="vf-chart" precedence="default">
      {CSS}
    </style>
  );
}

/* ---------- svg text ---------- */

/**
 * Persian label in SVG. `anchor` is the physical edge at `x`: "right" means the
 * text ends at x and runs leftward. The text is always laid out RTL so «۱۲ میلیون»
 * keeps the number on the right.
 */
export function Label({
  anchor = "middle",
  size = 11,
  muted = true,
  className,
  ...rest
}: Omit<React.SVGProps<SVGTextElement>, "textAnchor"> & { anchor?: "right" | "left" | "middle"; size?: number; muted?: boolean }) {
  return (
    <text
      direction="rtl"
      textAnchor={anchor === "right" ? "start" : anchor === "left" ? "end" : "middle"}
      fontSize={size}
      fill={muted ? "var(--muted-foreground)" : "var(--foreground)"}
      className={className}
      {...rest}
    />
  );
}

/* ---------- legend ---------- */

export function Legend({
  items,
  hidden,
  onToggle,
  className,
}: {
  items: { key: string; label: string; color: string; dashed?: boolean; value?: string }[];
  hidden?: Set<string>;
  onToggle?: (key: string) => void;
  className?: string;
}) {
  return (
    <ul className={cn("flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs", className)}>
      {items.map((s) => {
        const off = hidden?.has(s.key);
        const body = (
          <>
            <span
              aria-hidden
              className={cn("inline-block shrink-0", s.dashed ? "h-0 w-3.5 border-t-2 border-dashed" : "size-2.5 rounded-[3px]")}
              style={s.dashed ? { borderColor: s.color } : { background: s.color }}
            />
            <span className={cn("text-muted-foreground", off && "line-through opacity-60")}>{s.label}</span>
            {s.value && <span className="font-medium tabular-nums text-foreground">{s.value}</span>}
          </>
        );
        return (
          <li key={s.key}>
            {onToggle ? (
              <button
                type="button"
                aria-pressed={!off}
                onClick={() => onToggle(s.key)}
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-md px-1 py-0.5 outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60"
              >
                {body}
              </button>
            ) : (
              <span className="inline-flex items-center gap-1.5 px-1 py-0.5">{body}</span>
            )}
          </li>
        );
      })}
    </ul>
  );
}

/* ---------- tooltip ---------- */

export type TooltipRow = { key: string; label: string; value: string; color?: string; dashed?: boolean };
export type TooltipState = { x: number; y: number; title?: React.ReactNode; rows: TooltipRow[]; footer?: React.ReactNode };

/** HTML tooltip over the chart. Sits on the left of the point (reading direction) and flips near the left edge. */
export function ChartTooltip({ state, width }: { state: TooltipState | null; width: number }) {
  if (!state) return null;
  const flip = state.x < Math.min(220, width / 2);
  return (
    <div
      role="presentation"
      className="pointer-events-none absolute z-10 min-w-36 max-w-64 rounded-lg border border-border bg-popover/95 px-3 py-2 text-xs shadow-lg backdrop-blur-sm"
      style={{
        left: state.x,
        top: state.y,
        transform: `translate(${flip ? "12px" : "calc(-100% - 12px)"}, -50%)`,
      }}
    >
      {state.title && <div className="mb-1.5 font-medium text-foreground">{state.title}</div>}
      <ul className="space-y-1">
        {state.rows.map((r) => (
          <li key={r.key} className="flex items-center gap-2">
            {r.color && (
              <span
                aria-hidden
                className={cn("inline-block shrink-0", r.dashed ? "h-0 w-3 border-t-2 border-dashed" : "size-2 rounded-[2px]")}
                style={r.dashed ? { borderColor: r.color } : { background: r.color }}
              />
            )}
            <span className="text-muted-foreground">{r.label}</span>
            <span className="ms-auto ps-3 font-medium tabular-nums text-foreground">{r.value}</span>
          </li>
        ))}
      </ul>
      {state.footer && <div className="mt-1.5 border-t border-border pt-1.5 text-muted-foreground">{state.footer}</div>}
    </div>
  );
}

/** «فروردین، فروش ۱۲۰، هزینه ۸۰» for the live region. */
export function announceRows(title: string, rows: TooltipRow[]) {
  return [title, ...rows.map((r) => `${r.label} ${r.value}`)].filter(Boolean).join("، ");
}

/* ---------- frame ---------- */

export type ChartFrameProps = {
  /** Accessible name, e.g. «فروش ماهانه». Also the caption of the hidden data table. */
  title: string;
  description?: string;
  height: number;
  /** Height that depends on the measured width (grids whose cells stay square). Wins over `height`. */
  autoHeight?: (width: number) => number;
  /** Rendered with the measured width once the box is on screen. */
  children: (width: number) => React.ReactNode;
  legend?: React.ReactNode;
  legendPosition?: "top" | "bottom";
  /** Text for the polite live region, e.g. the active point read aloud for keyboard users. */
  announce?: string;
  /** Hidden table read by screen readers: header row plus body rows. */
  table?: { head: string[]; rows: (string | number)[][] };
  keyboard?: { onKeyDown: (e: React.KeyboardEvent) => void; onBlur: () => void };
  onPointerLeave?: () => void;
  empty?: boolean;
  emptyText?: string;
  className?: string;
};

/**
 * Shared shell: measures width, hosts the legend, a polite live region for
 * keyboard users, and an sr-only table with the raw numbers. Charts render
 * their own <ChartTooltip> inside `children`, where the geometry is known.
 */
export function ChartFrame({
  title,
  description,
  height,
  autoHeight,
  children,
  legend,
  legendPosition = "top",
  announce,
  table,
  keyboard,
  onPointerLeave,
  empty,
  emptyText = "داده‌ای برای نمایش نیست",
  className,
}: ChartFrameProps) {
  const [ref, width] = useWidth<HTMLDivElement>();
  return (
    <figure className={cn("vf-chart m-0 flex w-full min-w-0 flex-col gap-3", className)}>
      <ChartStyles />
      {legend && legendPosition === "top" && legend}
      <div
        ref={ref}
        className="relative w-full rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring/60"
        style={{ height: autoHeight ? (width > 0 ? autoHeight(width) : 140) : height }}
        tabIndex={keyboard && !empty ? 0 : undefined}
        role="group"
        aria-label={title}
        aria-roledescription="نمودار"
        onKeyDown={keyboard?.onKeyDown}
        onBlur={keyboard?.onBlur}
        onPointerLeave={onPointerLeave}
      >
        {empty ? (
          <div className="flex h-full items-center justify-center rounded-md border border-dashed border-border text-xs text-muted-foreground">{emptyText}</div>
        ) : (
          width > 0 && children(width)
        )}
        <div className="sr-only" aria-live="polite">{announce}</div>
      </div>
      {legend && legendPosition === "bottom" && legend}
      {description && <figcaption className="sr-only">{description}</figcaption>}
      {table && (
        // Wrapped: a <table> ignores the 1px box of sr-only and would widen the page.
        <div className="sr-only">
          <table>
            <caption>{title}</caption>
            <thead>
              <tr>{table.head.map((h, j) => <th key={j} scope="col">{h}</th>)}</tr>
            </thead>
            <tbody>
              {table.rows.map((r, i) => (
                <tr key={i}>{r.map((c, j) => (j === 0 ? <th key={j} scope="row">{c}</th> : <td key={j}>{c}</td>))}</tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </figure>
  );
}

/* ---------- cartesian pieces ---------- */

export type Box = { left: number; right: number; top: number; bottom: number; width: number; height: number };

/** Plot rectangle after reserving room for the right value axis, an optional left axis, and the category axis. */
export function plotBox(width: number, height: number, opts: { yLabels?: string[]; y2Labels?: string[]; xAxis?: boolean; yAxis?: boolean; top?: number }): Box {
  const yw = opts.yAxis === false ? 4 : Math.max(24, ...(opts.yLabels ?? []).map((l) => textWidth(l, 10))) + 10;
  const y2w = opts.y2Labels?.length ? Math.max(24, ...opts.y2Labels.map((l) => textWidth(l, 10))) + 10 : 6;
  const top = opts.top ?? 10;
  const bottom = height - (opts.xAxis === false ? 6 : 26);
  return { left: y2w, right: width - yw, top, bottom, width, height };
}

/** Horizontal grid lines with value labels on the right edge (and the zero line a little stronger). */
export function ValueGrid({ box, ticks, y, format, grid = true, axis = true, side = "right" }: { box: Box; ticks: number[]; y: (v: number) => number; format: ValueFormat; grid?: boolean; axis?: boolean; side?: "right" | "left" }) {
  return (
    <g aria-hidden>
      {ticks.map((t) => (
        <g key={t}>
          {grid && side === "right" && (
            <line x1={box.left} x2={box.right} y1={y(t)} y2={y(t)} stroke="var(--border)" strokeOpacity={t === 0 ? 1 : 0.6} strokeDasharray={t === 0 ? undefined : "3 3"} />
          )}
          {axis && (
            <Label anchor={side === "right" ? "right" : "left"} x={side === "right" ? box.width - 2 : 2} y={y(t)} dy="0.35em" size={10}>
              {format(t)}
            </Label>
          )}
        </g>
      ))}
    </g>
  );
}

/** Category labels under the plot, thinned so they never overlap. */
export function CategoryAxis({ box, labels, x, stride = 1, highlight }: { box: Box; labels: string[]; x: (i: number) => number; stride?: number; highlight?: number | null }) {
  return (
    <g aria-hidden>
      {labels.map((l, i) =>
        i % stride === 0 || i === highlight ? (
          <Label key={i} x={x(i)} y={box.bottom + 17} muted={i !== highlight} size={11}>
            {l}
          </Label>
        ) : null,
      )}
    </g>
  );
}

/** Dashed horizontal reference lines, e.g. a target or an average, labelled at the left end. */
export function References({ box, refs, y }: { box: Box; refs?: Reference[]; y: (v: number) => number }) {
  if (!refs?.length) return null;
  return (
    <g aria-hidden>
      {refs.map((r, i) => {
        const yy = y(r.value);
        if (yy < box.top - 1 || yy > box.bottom + 1) return null;
        const c = r.color ?? "var(--foreground)";
        return (
          <g key={i}>
            <line x1={box.left} x2={box.right} y1={yy} y2={yy} stroke={c} strokeOpacity={0.55} strokeDasharray="6 4" />
            {r.label && (
              <Label anchor="right" x={box.left + textWidth(r.label, 10) + 6} y={yy - 5} size={10} fill={c}>
                {r.label}
              </Label>
            )}
          </g>
        );
      })}
    </g>
  );
}

export type DomainOption = "auto" | "zero" | [number, number];

/** Round ticks for the values on screen. "zero" keeps 0 in range (bars, areas); a fixed pair is used as is. */
export function valueTicks(values: number[], domain: DomainOption, height: number): { domain: Domain; ticks: number[] } {
  const count = Math.max(3, Math.min(7, Math.floor((height - 40) / 48)));
  if (Array.isArray(domain)) {
    return { domain, ticks: niceTicks(domain[0], domain[1], count).ticks.filter((t) => t >= domain[0] - 1e-9 && t <= domain[1] + 1e-9) };
  }
  const [lo, hi] = extent(values, domain === "zero");
  return niceTicks(lo, hi, count);
}

/** Pointer x → nearest index, using the plot box's own coordinates. */
export function pointerX(e: React.PointerEvent<SVGElement>) {
  const r = (e.currentTarget.ownerSVGElement ?? (e.currentTarget as SVGSVGElement)).getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}

"use client";

import * as React from "react";
import { compactFa, fullFa, labelStride, linePath, linearScale, pointScale, segments, textWidth, type Curve } from "@/lib/chart-utils";
import {
  CategoryAxis,
  ChartFrame,
  ChartTooltip,
  Legend,
  References,
  ValueGrid,
  announceRows,
  colorAt,
  defaultLabel,
  num,
  plotBox,
  pointerX,
  useActive,
  useHidden,
  valueTicks,
  type DomainOption,
  type Reference,
  type Row,
  type Series,
  type ValueFormat,
} from "@/components/charts/chart-core";

export interface LineChartProps {
  data: Row[];
  /** Field holding the category or date of each row. */
  x: string;
  series: Series[];
  /** Accessible name and caption of the hidden data table. */
  title: string;
  description?: string;
  height?: number;
  curve?: Curve;
  /** Tooltip and table format. Default: full Persian number. */
  format?: ValueFormat;
  /** Value-axis ticks. Default: compact «۱۲ میلیون». */
  axisFormat?: ValueFormat;
  xFormat?: (value: unknown, index: number) => string;
  /** "auto" fits the data, "zero" starts at 0, or a fixed [min, max]. */
  domain?: DomainOption;
  /** Dots on every point; "auto" shows them up to 16 points. */
  dots?: boolean | "auto";
  references?: Reference[];
  /** Index to emphasise, e.g. today. */
  highlight?: number;
  legend?: boolean;
  grid?: boolean;
  yAxis?: boolean;
  xAxis?: boolean;
  animate?: boolean;
  onSelect?: (row: Row, index: number) => void;
  className?: string;
}

/**
 * نمودار خطی. Time runs right to left, the value axis sits on the right,
 * missing values break the line, and dashed series read as forecasts.
 */
export function LineChart({
  data,
  x,
  series,
  title,
  description,
  height = 260,
  curve = "monotone",
  format = (n) => fullFa(n, 2),
  axisFormat = compactFa,
  xFormat = defaultLabel,
  domain = "auto",
  dots = "auto",
  references,
  highlight,
  legend = series.length > 1,
  grid = true,
  yAxis = true,
  xAxis = true,
  animate = true,
  onSelect,
  className,
}: LineChartProps) {
  const { hidden, toggle } = useHidden(series);
  const kb = useActive(data.length);
  const active = kb.active;
  const all = series.map((s, i) => ({ ...s, color: colorAt(i, s.color) }));
  const visible = all.filter((s) => !hidden.has(s.key));
  const labels = data.map((r, i) => xFormat(r[x], i));

  const values = visible.flatMap((s) => data.map((r) => num(r, s.key)).filter((v): v is number => v !== null));
  references?.forEach((r) => values.push(r.value));
  const { domain: dom, ticks } = valueTicks(values, domain, height);
  const showDots = dots === "auto" ? data.length <= 16 : dots;

  const rowsAt = (i: number) =>
    visible.map((s) => {
      const v = num(data[i], s.key);
      return { key: s.key, label: s.label, color: s.color, dashed: s.dashed, value: v === null ? "—" : format(v) };
    });

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rowsAt(active)) : ""}
      legend={legend ? <Legend items={all} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: ["", ...series.map((s) => s.label)], rows: data.map((r, i) => [labels[i], ...series.map((s) => { const v = num(r, s.key); return v === null ? "—" : format(v); })]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: ticks.map(axisFormat), xAxis, yAxis });
        const px = pointScale(data.length, box.left + 6, box.right - 6);
        const y = linearScale(dom, [box.bottom, box.top]);
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 8);
        const ax = active !== null ? px.x(active) : 0;
        const ay = active !== null ? Math.min(box.bottom, ...visible.map((s) => num(data[active], s.key)).filter((v): v is number => v !== null).map(y)) : 0;

        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <ValueGrid box={box} ticks={ticks} y={y} format={axisFormat} grid={grid} axis={yAxis} />
              <References box={box} refs={references} y={y} />
              {highlight !== undefined && highlight < data.length && (
                <line x1={px.x(highlight)} x2={px.x(highlight)} y1={box.top} y2={box.bottom} stroke="var(--foreground)" strokeOpacity={0.15} />
              )}
              {visible.map((s) => {
                const segs = segments(data.map((r) => num(r, s.key)), px.x, y);
                return (
                  <g key={s.key}>
                    {segs.map((seg, j) => (
                      <path
                        key={j}
                        d={linePath(seg.pts, curve)}
                        fill="none"
                        stroke={s.color}
                        strokeWidth={2}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeDasharray={s.dashed ? "5 4" : undefined}
                        pathLength={animate && !s.dashed ? 1 : undefined}
                        className={animate ? (s.dashed ? "vf-fade" : "vf-draw") : undefined}
                      />
                    ))}
                    {segs.flatMap((seg) =>
                      seg.idx.map((i, k) => {
                        const on = i === active || i === highlight;
                        if (!showDots && !on && seg.idx.length > 1) return null;
                        return <circle key={i} cx={seg.pts[k][0]} cy={seg.pts[k][1]} r={on ? 4.5 : 3} fill="var(--background)" stroke={s.color} strokeWidth={2} />;
                      }),
                    )}
                  </g>
                );
              })}
              {active !== null && <line x1={ax} x2={ax} y1={box.top} y2={box.bottom} stroke="var(--foreground)" strokeOpacity={0.3} strokeDasharray="2 3" />}
              {xAxis && <CategoryAxis box={box} labels={labels} x={px.x} stride={stride} highlight={active ?? highlight} />}
              <rect
                x={box.left}
                y={box.top}
                width={Math.max(0, box.right - box.left)}
                height={Math.max(0, box.bottom - box.top)}
                fill="transparent"
                style={{ cursor: onSelect ? "pointer" : "crosshair" }}
                onPointerMove={(e) => kb.setActive(px.index(pointerX(e).x))}
                onClick={() => active !== null && onSelect?.(data[active], active)}
              />
            </svg>
            {active !== null && <ChartTooltip state={{ x: ax, y: ay, title: labels[active], rows: rowsAt(active) }} width={width} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { areaPath, compactFa, fullFa, labelStride, linePath, linearScale, percentFa, pointScale, stackRows, textWidth, type Curve, type Pt, type StackMode } from "@/lib/chart-utils";
import {
  CategoryAxis,
  ChartFrame,
  ChartTooltip,
  Legend,
  References,
  ValueGrid,
  announceRows,
  colorAt,
  defaultLabel,
  num,
  plotBox,
  pointerX,
  useActive,
  useHidden,
  valueTicks,
  type DomainOption,
  type Reference,
  type Row,
  type Series,
  type ValueFormat,
} from "@/components/charts/chart-core";

export interface AreaChartProps {
  data: Row[];
  x: string;
  series: Series[];
  title: string;
  description?: string;
  height?: number;
  curve?: Curve;
  /** "none" overlaps the areas, "stacked" piles them, "percent" shows each one's share of 100٪. */
  stack?: StackMode;
  format?: ValueFormat;
  axisFormat?: ValueFormat;
  xFormat?: (value: unknown, index: number) => string;
  domain?: DomainOption;
  /** Fill style: soft vertical gradient or flat tint. */
  fill?: "gradient" | "solid";
  references?: Reference[];
  legend?: boolean;
  grid?: boolean;
  yAxis?: boolean;
  xAxis?: boolean;
  animate?: boolean;
  onSelect?: (row: Row, index: number) => void;
  className?: string;
}

/**
 * نمودار ناحیه‌ای. Same RTL geometry as the line chart, with overlap, stacked and
 * 100٪ modes. In stacked modes the tooltip also shows the total.
 */
export function AreaChart({
  data,
  x,
  series,
  title,
  description,
  height = 260,
  curve = "monotone",
  stack = "none",
  format = (n) => fullFa(n, 2),
  axisFormat,
  xFormat = defaultLabel,
  domain = "zero",
  fill = "gradient",
  references,
  legend = series.length > 1,
  grid = true,
  yAxis = true,
  xAxis = true,
  animate = true,
  onSelect,
  className,
}: AreaChartProps) {
  const { hidden, toggle } = useHidden(series);
  const kb = useActive(data.length);
  const active = kb.active;
  const gid = React.useId().replace(/:/g, "");
  const all = series.map((s, i) => ({ ...s, color: colorAt(i, s.color) }));
  const visible = all.filter((s) => !hidden.has(s.key));
  const labels = data.map((r, i) => xFormat(r[x], i));
  const percent = stack === "percent";
  const axisFmt = axisFormat ?? (percent ? (n: number) => percentFa(n) : compactFa);

  const raw = data.map((r) => visible.map((s) => num(r, s.key) ?? 0));
  const stacked = stackRows(raw, stack);
  const values = stacked.flatMap((col) => col.flatMap(([a, b]) => [a, b]));
  references?.forEach((r) => values.push(r.value));
  const { domain: dom, ticks } = percent ? { domain: [0, 100] as [number, number], ticks: [0, 25, 50, 75, 100] } : valueTicks(values, domain, height);

  const rowsAt = (i: number) => {
    const rows = visible.map((s, j) => {
      const v = num(data[i], s.key);
      const share = percent && v !== null ? ` (${percentFa(stacked[j][i][1] - stacked[j][i][0], 1)})` : "";
      return { key: s.key, label: s.label, color: s.color, value: v === null ? "—" : format(v) + share };
    });
    return rows;
  };
  const totalAt = (i: number) => raw[i].reduce((a, b) => a + b, 0);

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rowsAt(active)) : ""}
      legend={legend ? <Legend items={all} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: ["", ...series.map((s) => s.label)], rows: data.map((r, i) => [labels[i], ...series.map((s) => { const v = num(r, s.key); return v === null ? "—" : format(v); })]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: ticks.map(axisFmt), xAxis, yAxis });
        const px = pointScale(data.length, box.left + 2, box.right - 2);
        const y = linearScale(dom, [box.bottom, box.top]);
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 8);
        const ax = active !== null ? px.x(active) : 0;
        const tops = visible.map((_, j) => data.map((_, i) => [px.x(i), y(stacked[j][i][1])] as Pt));
        const bottoms = visible.map((_, j) => data.map((_, i) => [px.x(i), y(stack === "none" ? Math.max(dom[0], Math.min(0, dom[1])) : stacked[j][i][0])] as Pt));
        // Draw the last stacked layer first so its line isn't covered by the next fill.
        const order = visible.map((_, j) => j);
        if (stack === "none") order.reverse();

        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <defs>
                {visible.map((s, j) => (
                  <linearGradient key={s.key} id={`${gid}-${j}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stopColor={s.color} stopOpacity={stack === "none" ? 0.32 : 0.55} />
                    <stop offset="1" stopColor={s.color} stopOpacity={stack === "none" ? 0.02 : 0.2} />
                  </linearGradient>
                ))}
              </defs>
              <ValueGrid box={box} ticks={ticks} y={y} format={axisFmt} grid={grid} axis={yAxis} />
              {order.map((j) => {
                const s = visible[j];
                return (
                  <g key={s.key}>
                    <path
                      d={areaPath(tops[j], bottoms[j], curve)}
                      fill={fill === "gradient" ? `url(#${gid}-${j})` : s.color}
                      fillOpacity={fill === "gradient" ? 1 : stack === "none" ? 0.18 : 0.4}
                      className={animate ? "vf-fade" : undefined}
                    />
                    <path
                      d={linePath(tops[j], curve)}
                      fill="none"
                      stroke={s.color}
                      strokeWidth={2}
                      strokeLinejoin="round"
                      strokeDasharray={s.dashed ? "5 4" : undefined}
                      pathLength={animate && !s.dashed ? 1 : undefined}
                      className={animate ? (s.dashed ? "vf-fade" : "vf-draw") : undefined}
                    />
                  </g>
                );
              })}
              <References box={box} refs={references} y={y} />
              {active !== null && (
                <>
                  <line x1={ax} x2={ax} y1={box.top} y2={box.bottom} stroke="var(--foreground)" strokeOpacity={0.3} strokeDasharray="2 3" />
                  {visible.map((s, j) => (
                    <circle key={s.key} cx={ax} cy={tops[j][active][1]} r={4} fill="var(--background)" stroke={s.color} strokeWidth={2} />
                  ))}
                </>
              )}
              {xAxis && <CategoryAxis box={box} labels={labels} x={px.x} stride={stride} highlight={active} />}
              <rect
                x={box.left}
                y={box.top}
                width={Math.max(0, box.right - box.left)}
                height={Math.max(0, box.bottom - box.top)}
                fill="transparent"
                style={{ cursor: onSelect ? "pointer" : "crosshair" }}
                onPointerMove={(e) => kb.setActive(px.index(pointerX(e).x))}
                onClick={() => active !== null && onSelect?.(data[active], active)}
              />
            </svg>
            {active !== null && (
              <ChartTooltip
                width={width}
                state={{
                  x: ax,
                  y: Math.min(...tops.map((t) => t[active][1])),
                  title: labels[active],
                  rows: [...rowsAt(active)].reverse(),
                  footer: stack !== "none" && visible.length > 1 ? `جمع: ${format(totalAt(active))}` : undefined,
                }}
              />
            )}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { areaPath, compactFa, linePath, percentFa, type Pt } from "@/lib/chart-utils";
import { colorAt, useWidth } from "@/components/charts/chart-core";

type SparkBase = {
  data: number[];
  /** Accessible summary prefix, e.g. «فروش هفت روز اخیر». */
  label: string;
  height?: number;
  /** Fixed width; default fills the parent. */
  width?: number;
  color?: string;
  className?: string;
};

/** «فروش هفت روز اخیر: از ۱۲ هزار به ۱۸ هزار، ۵۰٪ افزایش» */
function summary(label: string, data: number[]) {
  if (data.length < 2) return label;
  const a = data[0], b = data[data.length - 1];
  const ch = a ? ((b - a) / Math.abs(a)) * 100 : 0;
  return `${label}: از ${compactFa(a)} به ${compactFa(b)}، ${percentFa(Math.abs(ch))} ${ch >= 0 ? "افزایش" : "کاهش"}`;
}

/** Width of the parent unless a fixed one is given. */
function useBoxWidth(fixed?: number): [React.RefObject<HTMLSpanElement | null>, number] {
  const [ref, w] = useWidth<HTMLSpanElement>();
  return [ref, fixed ?? w];
}

export interface SparklineProps extends SparkBase {
  /** Soft fill under the line. */
  area?: boolean;
  /** Mark the highest and lowest points. */
  extremes?: boolean;
  /** Colour by trend: green when the last value beats the first, red otherwise. */
  trend?: boolean;
  /** For metrics where lower is better (cancellations, response time), pass "down" to flip the trend colours. */
  goodWhen?: "up" | "down";
}

/**
 * اسپارک‌لاین. A tiny trend for stat cards and table cells. The oldest value is
 * on the right like the full charts, the latest gets a dot on the left end.
 */
export function Sparkline({ data, label, height = 32, width, color, area = true, extremes = false, trend = false, goodWhen = "up", className }: SparklineProps) {
  const [ref, w] = useBoxWidth(width);
  const gid = React.useId().replace(/:/g, "");
  const up = data.length > 1 && data[data.length - 1] >= data[0];
  const good = goodWhen === "up" ? up : !up;
  const c = color ?? (trend ? (good ? "var(--success)" : "var(--destructive)") : colorAt(0));
  const min = Math.min(...data), max = Math.max(...data);
  const pad = 3;
  const x = (i: number) => (data.length > 1 ? w - pad - (i / (data.length - 1)) * (w - pad * 2) : w / 2);
  const y = (v: number) => height - pad - ((v - min) / (max - min || 1)) * (height - pad * 2);
  const pts: Pt[] = data.map((v, i) => [x(i), y(v)]);
  const iMax = data.indexOf(max), iMin = data.indexOf(min);
  return (
    <span ref={ref} role="img" aria-label={summary(label, data)} className={cn("inline-block align-middle", !width && "w-full", className)} style={{ height, width }}>
      {w > 0 && data.length > 0 && (
        <svg width={w} height={height} className="block overflow-visible" aria-hidden>
          {area && (
            <>
              <defs>
                <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0" stopColor={c} stopOpacity={0.28} />
                  <stop offset="1" stopColor={c} stopOpacity={0} />
                </linearGradient>
              </defs>
              <path d={areaPath(pts, pts.map(([px]) => [px, height] as Pt))} fill={`url(#${gid})`} />
            </>
          )}
          <path d={linePath(pts)} fill="none" stroke={c} strokeWidth={1.75} strokeLinejoin="round" strokeLinecap="round" />
          {extremes && data.length > 2 && (
            <>
              <circle cx={x(iMax)} cy={y(max)} r={2.25} fill="var(--success)" />
              <circle cx={x(iMin)} cy={y(min)} r={2.25} fill="var(--destructive)" />
            </>
          )}
          <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r={2.75} fill={c} stroke="var(--background)" strokeWidth={1.5} />
        </svg>
      )}
    </span>
  );
}

export interface SparkBarProps extends SparkBase {
  /** Index drawn in full colour, e.g. today. Default: the last one. */
  highlight?: number;
}

/** میله‌ی کوچک. Mini column chart for daily counts; negative values hang below a baseline. */
export function SparkBar({ data, label, height = 32, width, color, highlight, className }: SparkBarProps) {
  const [ref, w] = useBoxWidth(width);
  const c = color ?? colorAt(0);
  const hi = Math.max(0, ...data), lo = Math.min(0, ...data);
  const step = w / Math.max(1, data.length);
  const bw = Math.max(1, step * 0.7);
  const y = (v: number) => ((hi - v) / (hi - lo || 1)) * height;
  const on = highlight ?? data.length - 1;
  return (
    <span ref={ref} role="img" aria-label={summary(label, data)} className={cn("inline-block align-middle", !width && "w-full", className)} style={{ height, width }}>
      {w > 0 && (
        <svg width={w} height={height} className="block" aria-hidden>
          {data.map((v, i) => {
            const top = y(Math.max(0, v)), bottom = y(Math.min(0, v));
            return <rect key={i} x={w - (i + 1) * step + (step - bw) / 2} y={top} width={bw} height={Math.max(1, bottom - top)} rx={Math.min(2, bw / 3)} fill={v < 0 ? "var(--destructive)" : c} fillOpacity={i === on ? 1 : 0.4} />;
          })}
        </svg>
      )}
    </span>
  );
}

"use client";

import * as React from "react";
import { bandScale, compactFa, fullFa, labelStride, linearScale, percentFa, roundedRect, stackRows, textWidth, type StackMode } from "@/lib/chart-utils";
import {
  CategoryAxis,
  ChartFrame,
  ChartTooltip,
  Label,
  Legend,
  References,
  ValueGrid,
  announceRows,
  colorAt,
  defaultLabel,
  num,
  plotBox,
  useActive,
  useHidden,
  valueTicks,
  type Reference,
  type Row,
  type Series,
  type ValueFormat,
} from "@/components/charts/chart-core";

export interface BarChartProps {
  data: Row[];
  x: string;
  series: Series[];
  title: string;
  description?: string;
  height?: number;
  /** "vertical" columns, or "horizontal" bars that grow right-to-left from the labels. */
  orientation?: "vertical" | "horizontal";
  /** "none" groups series side by side, "stacked" piles them, "percent" fills to 100٪. */
  stack?: StackMode;
  format?: ValueFormat;
  axisFormat?: ValueFormat;
  xFormat?: (value: unknown, index: number) => string;
  /** Print each bar's value at its end (stack total in stacked modes). */
  showValues?: boolean;
  /** One color per category when there is a single series, e.g. one per bank. */
  colors?: string[];
  /** Index drawn in full color while the rest fade, e.g. the current month. */
  highlight?: number;
  radius?: number;
  references?: Reference[];
  legend?: boolean;
  grid?: boolean;
  animate?: boolean;
  onSelect?: (row: Row, index: number) => void;
  className?: string;
}

/**
 * نمودار میله‌ای. Columns run right to left; horizontal bars start at the
 * category labels on the right and grow leftward. Negative values hang below
 * (or to the right of) zero, and only the far end of each bar is rounded.
 */
export function BarChart({
  data,
  x,
  series,
  title,
  description,
  height,
  orientation = "vertical",
  stack = "none",
  format = (n) => fullFa(n, 2),
  axisFormat,
  xFormat = defaultLabel,
  showValues = false,
  colors,
  highlight,
  radius = 4,
  references,
  legend = series.length > 1,
  grid = true,
  animate = true,
  onSelect,
  className,
}: BarChartProps) {
  const horizontal = orientation === "horizontal";
  const h = height ?? (horizontal ? Math.max(160, data.length * (stack === "none" ? 18 * series.length + 14 : 34) + 40) : 260);
  const { hidden, toggle } = useHidden(series);
  const kb = useActive(data.length);
  const active = kb.active;
  const all = series.map((s, i) => ({ ...s, color: colorAt(i, s.color) }));
  const visible = all.filter((s) => !hidden.has(s.key));
  const labels = data.map((r, i) => xFormat(r[x], i));
  const percent = stack === "percent";
  const axisFmt = axisFormat ?? (percent ? (n: number) => percentFa(n) : compactFa);

  const raw = data.map((r) => visible.map((s) => num(r, s.key) ?? 0));
  const stacked = stackRows(raw, stack);
  const values = stacked.flatMap((col) => col.flatMap(([a, b]) => [a, b]));
  references?.forEach((r) => values.push(r.value));
  const { domain: dom, ticks } = percent ? { domain: [0, 100] as [number, number], ticks: [0, 25, 50, 75, 100] } : valueTicks(values, "zero", horizontal ? 300 : h);

  const colorOf = (j: number, i: number) => (visible.length === 1 && colors?.[i]) || visible[j].color;
  const rowsAt = (i: number) =>
    visible.map((s, j) => {
      const v = num(data[i], s.key);
      return { key: s.key, label: s.label, color: colorOf(j, i), value: v === null ? "—" : format(v) + (percent ? ` (${percentFa(stacked[j][i][1] - stacked[j][i][0], 1)})` : "") };
    });
  /** Only the outermost segment of a stack gets rounded corners. */
  const outer = (j: number, i: number) => {
    if (stack === "none") return true;
    const v = raw[i][j];
    for (let k = j + 1; k < visible.length; k++) if (raw[i][k] !== 0 && Math.sign(raw[i][k]) === Math.sign(v)) return false;
    return true;
  };
  const totalAt = (i: number) => raw[i].reduce((a, b) => a + b, 0);

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rowsAt(active)) : ""}
      legend={legend ? <Legend items={all} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: ["", ...series.map((s) => s.label)], rows: data.map((r, i) => [labels[i], ...series.map((s) => { const v = num(r, s.key); return v === null ? "—" : format(v); })]) }}
    >
      {(width) => {
        if (horizontal) {
          const labelW = Math.min(width * 0.35, Math.max(...labels.map((l) => textWidth(l, 12))) + 12);
          const box = { left: 8, right: width - labelW, top: 4, bottom: h - 24, width, height: h };
          const vx = linearScale(dom, [box.right, box.left]);
          const band = (() => {
            const step = (box.bottom - box.top) / Math.max(1, data.length);
            const bw = step * 0.72;
            return { step, bw, y: (i: number) => box.top + i * step + (step - bw) / 2 };
          })();
          const sub = stack === "none" ? band.bw / Math.max(1, visible.length) : band.bw;
          const z = vx(0);
          return (
            <>
              <svg width={width} height={h} className="block overflow-visible" aria-hidden>
                <g aria-hidden>
                  {ticks.map((t) => (
                    <g key={t}>
                      {grid && <line x1={vx(t)} x2={vx(t)} y1={box.top} y2={box.bottom} stroke="var(--border)" strokeOpacity={t === 0 ? 1 : 0.6} strokeDasharray={t === 0 ? undefined : "3 3"} />}
                      <Label x={vx(t)} y={box.bottom + 16} size={10}>{axisFmt(t)}</Label>
                    </g>
                  ))}
                </g>
                {data.map((_, i) => (
                  <g key={i} onPointerEnter={() => kb.setActive(i)} onClick={() => onSelect?.(data[i], i)} style={{ cursor: onSelect ? "pointer" : undefined }}>
                    <rect x={0} y={box.top + i * band.step} width={width} height={band.step} fill={active === i ? "var(--foreground)" : "transparent"} fillOpacity={0.04} />
                    <Label anchor="right" x={width - 2} y={band.y(i) + band.bw / 2} dy="0.35em" size={12} muted={active !== i}>
                      {labels[i]}
                    </Label>
                    {visible.map((s, j) => {
                      const [a, b] = stacked[j][i];
                      const x0 = vx(Math.max(a, b)), x1 = vx(Math.min(a, b));
                      const yy = stack === "none" ? band.y(i) + j * sub : band.y(i);
                      const neg = b < a || (stack === "none" && b < 0);
                      const r = outer(j, i) ? radius : 0;
                      const dim = highlight !== undefined && highlight !== i;
                      return (
                        <path
                          key={s.key}
                          d={roundedRect(x0, yy + (stack === "none" ? 1 : 0), Math.max(0, x1 - x0), Math.max(0, sub - (stack === "none" ? 2 : 0)), r, neg ? { tr: true, br: true } : { tl: true, bl: true })}
                          fill={colorOf(j, i)}
                          fillOpacity={dim ? 0.35 : 1}
                          className={animate ? "vf-grow vf-mark" : "vf-mark"}
                          style={animate ? ({ transformOrigin: neg ? "left" : "right", "--vf-sx": 0, "--vf-sy": 1 } as React.CSSProperties) : undefined}
                        />
                      );
                    })}
                    {showValues && (
                      <Label anchor="right" x={vx(stack === "none" ? Math.max(0, ...raw[i]) : Math.max(...stacked.map((c) => c[i][1]))) - 4} y={band.y(i) + band.bw / 2} dy="0.35em" size={10}>
                        {stack === "none" && visible.length > 1 ? "" : percent ? "" : axisFmt(stack === "none" ? raw[i][0] : totalAt(i))}
                      </Label>
                    )}
                  </g>
                ))}
                <line x1={z} x2={z} y1={box.top} y2={box.bottom} stroke="var(--border)" />
              </svg>
              {active !== null && (
                <ChartTooltip
                  width={width}
                  state={{
                    x: Math.min(...visible.map((_, j) => vx(Math.max(...stacked[j][active])))),
                    y: band.y(active) + band.bw / 2,
                    title: labels[active],
                    rows: rowsAt(active),
                    footer: stack !== "none" && visible.length > 1 ? `جمع: ${format(totalAt(active))}` : undefined,
                  }}
                />
              )}
            </>
          );
        }

        const box = plotBox(width, h, { yLabels: ticks.map(axisFmt), top: showValues ? 18 : 10 });
        const bs = bandScale(data.length, box.left, box.right, data.length > 20 ? 0.18 : 0.3);
        const y = linearScale(dom, [box.bottom, box.top]);
        const sub = stack === "none" ? bs.band / Math.max(1, visible.length) : bs.band;
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 8);
        const z = y(0);
        return (
          <>
            <svg width={width} height={h} className="block overflow-visible" aria-hidden>
              <ValueGrid box={box} ticks={ticks} y={y} format={axisFmt} grid={grid} />
              {data.map((_, i) => (
                <g key={i} onPointerEnter={() => kb.setActive(i)} onClick={() => onSelect?.(data[i], i)} style={{ cursor: onSelect ? "pointer" : undefined }}>
                  <rect x={bs.x(i) - (bs.step - bs.band) / 2} y={box.top} width={bs.step} height={box.bottom - box.top} fill={active === i ? "var(--foreground)" : "transparent"} fillOpacity={0.05} rx={4} />
                  {visible.map((s, j) => {
                    const [a, b] = stacked[j][i];
                    const top = y(Math.max(a, b)), bottom = y(Math.min(a, b));
                    // Grouped bars keep series order right-to-left inside the band.
                    const xx = stack === "none" ? bs.x(i) + (visible.length - 1 - j) * sub : bs.x(i);
                    const neg = b < a || (stack === "none" && b < 0);
                    const r = outer(j, i) ? radius : 0;
                    const dim = highlight !== undefined && highlight !== i;
                    const gap = stack === "none" && visible.length > 1 ? Math.min(2, sub * 0.15) : 0;
                    return (
                      <path
                        key={s.key}
                        d={roundedRect(xx + gap / 2, top, Math.max(0, sub - gap), Math.max(0, bottom - top), r, neg ? { bl: true, br: true } : { tl: true, tr: true })}
                        fill={colorOf(j, i)}
                        fillOpacity={dim ? 0.35 : 1}
                        className={animate ? "vf-grow vf-mark" : "vf-mark"}
                        style={animate ? ({ transformOrigin: neg ? "top" : "bottom", "--vf-sx": 1, "--vf-sy": 0 } as React.CSSProperties) : undefined}
                      />
                    );
                  })}
                  {showValues &&
                    (stack === "none"
                      ? visible.map((s, j) => {
                          const v = raw[i][j];
                          return (
                            <Label key={s.key} x={bs.x(i) + (visible.length - 1 - j) * sub + sub / 2} y={v >= 0 ? y(v) - 5 : y(v) + 12} size={10} muted={false}>
                              {visible.length > 3 || v === 0 ? "" : axisFmt(v)}
                            </Label>
                          );
                        })
                      : !percent && (
                          <Label x={bs.center(i)} y={y(Math.max(0, ...stacked.map((c) => c[i][1]))) - 5} size={10} muted={false}>
                            {axisFmt(totalAt(i))}
                          </Label>
                        ))}
                </g>
              ))}
              {dom[0] < 0 && <line x1={box.left} x2={box.right} y1={z} y2={z} stroke="var(--foreground)" strokeOpacity={0.3} />}
              <References box={box} refs={references} y={y} />
              <CategoryAxis box={box} labels={labels} x={bs.center} stride={stride} highlight={active ?? highlight} />
            </svg>
            {active !== null && (
              <ChartTooltip
                width={width}
                state={{
                  x: bs.center(active),
                  y: Math.min(box.bottom, ...visible.map((_, j) => y(Math.max(...stacked[j][active])))),
                  title: labels[active],
                  rows: stack === "none" ? rowsAt(active) : [...rowsAt(active)].reverse(),
                  footer: stack !== "none" && visible.length > 1 ? `جمع: ${format(totalAt(active))}` : undefined,
                }}
              />
            )}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { areaPath, bandScale, compactFa, fullFa, labelStride, linePath, linearScale, roundedRect, segments, textWidth, type Curve, type Pt } from "@/lib/chart-utils";
import {
  CategoryAxis,
  ChartFrame,
  ChartTooltip,
  Legend,
  ValueGrid,
  announceRows,
  colorAt,
  defaultLabel,
  num,
  plotBox,
  pointerX,
  useActive,
  useHidden,
  valueTicks,
  type Row,
  type Series,
  type ValueFormat,
} from "@/components/charts/chart-core";

export type ComboSeries = Series & {
  type: "bar" | "line" | "area";
  /** "right" is the main axis (RTL); "left" is a second scale, e.g. a percentage. */
  axis?: "right" | "left";
};

export interface ComboChartProps {
  data: Row[];
  x: string;
  series: ComboSeries[];
  title: string;
  description?: string;
  height?: number;
  curve?: Curve;
  /** Per-axis formats for tooltip values and ticks. */
  format?: ValueFormat;
  formatLeft?: ValueFormat;
  axisFormat?: ValueFormat;
  axisFormatLeft?: ValueFormat;
  xFormat?: (value: unknown, index: number) => string;
  legend?: boolean;
  grid?: boolean;
  animate?: boolean;
  onSelect?: (row: Row, index: number) => void;
  className?: string;
}

/**
 * نمودار ترکیبی. Bars, lines and areas on one band scale with two value axes:
 * the main one on the right, a secondary one on the left (e.g. revenue as bars,
 * conversion rate as a line).
 */
export function ComboChart({
  data,
  x,
  series,
  title,
  description,
  height = 280,
  curve = "monotone",
  format = (n) => fullFa(n, 2),
  formatLeft,
  axisFormat = compactFa,
  axisFormatLeft,
  xFormat = defaultLabel,
  legend = true,
  grid = true,
  animate = true,
  onSelect,
  className,
}: ComboChartProps) {
  const { hidden, toggle } = useHidden(series);
  const kb = useActive(data.length);
  const active = kb.active;
  const gid = React.useId().replace(/:/g, "");
  const all = series.map((s, i) => ({ ...s, color: colorAt(i, s.color) }));
  const visible = all.filter((s) => !hidden.has(s.key));
  const labels = data.map((r, i) => xFormat(r[x], i));
  const fmtL = formatLeft ?? format;
  const axisL = axisFormatLeft ?? axisFormat;

  const side = (s: ComboSeries) => s.axis ?? "right";
  const valuesOn = (ax: "right" | "left") => visible.filter((s) => side(s) === ax).flatMap((s) => data.map((r) => num(r, s.key)).filter((v): v is number => v !== null));
  const right = valueTicks(valuesOn("right"), "zero", height);
  const hasLeft = visible.some((s) => side(s) === "left");
  const left = valueTicks(valuesOn("left"), "zero", height);
  // Align the left axis to the same number of grid lines as the right one.
  const leftTicks = hasLeft ? right.ticks.map((_, i) => left.domain[0] + ((left.domain[1] - left.domain[0]) * i) / (right.ticks.length - 1)) : [];
  const bars = visible.filter((s) => s.type === "bar");

  const rowsAt = (i: number) =>
    visible.map((s) => {
      const v = num(data[i], s.key);
      return { key: s.key, label: s.label, color: s.color, dashed: s.dashed, value: v === null ? "—" : (side(s) === "left" ? fmtL : format)(v) };
    });

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rowsAt(active)) : ""}
      legend={legend ? <Legend items={all} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: ["", ...series.map((s) => s.label)], rows: data.map((r, i) => [labels[i], ...series.map((s) => { const v = num(r, s.key); return v === null ? "—" : (side(s) === "left" ? fmtL : format)(v); })]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: right.ticks.map(axisFormat), y2Labels: hasLeft ? leftTicks.map(axisL) : undefined });
        const bs = bandScale(data.length, box.left, box.right, 0.3);
        const yR = linearScale(right.domain, [box.bottom, box.top]);
        const yL = linearScale(hasLeft ? [leftTicks[0], leftTicks[leftTicks.length - 1]] : right.domain, [box.bottom, box.top]);
        const yOf = (s: ComboSeries) => (side(s) === "left" ? yL : yR);
        const sub = bs.band / Math.max(1, bars.length);
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 8);
        const ax = active !== null ? bs.center(active) : 0;

        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <ValueGrid box={box} ticks={right.ticks} y={yR} format={axisFormat} grid={grid} />
              {hasLeft && <ValueGrid box={box} ticks={leftTicks} y={yL} format={axisL} grid={false} side="left" />}
              {active !== null && <rect x={bs.x(active) - (bs.step - bs.band) / 2} y={box.top} width={bs.step} height={box.bottom - box.top} fill="var(--foreground)" fillOpacity={0.05} rx={4} />}
              {bars.map((s, j) =>
                data.map((r, i) => {
                  const v = num(r, s.key);
                  if (v === null) return null;
                  const y = yOf(s), top = y(Math.max(0, v)), bottom = y(Math.min(0, v));
                  return (
                    <path
                      key={`${s.key}-${i}`}
                      d={roundedRect(bs.x(i) + (bars.length - 1 - j) * sub + 1, top, Math.max(0, sub - 2), Math.max(0, bottom - top), 4, v >= 0 ? { tl: true, tr: true } : { bl: true, br: true })}
                      fill={s.color}
                      className={animate ? "vf-grow" : undefined}
                      style={animate ? ({ transformOrigin: v >= 0 ? "bottom" : "top", "--vf-sx": 1, "--vf-sy": 0 } as React.CSSProperties) : undefined}
                    />
                  );
                }),
              )}
              {visible
                .filter((s) => s.type !== "bar")
                .map((s, k) => {
                  const y = yOf(s);
                  const segs = segments(data.map((r) => num(r, s.key)), bs.center, y);
                  const base = y(Math.max(y.domain[0], Math.min(0, y.domain[1])));
                  return (
                    <g key={s.key}>
                      {s.type === "area" && (
                        <>
                          <defs>
                            <linearGradient id={`${gid}-${k}`} x1="0" y1="0" x2="0" y2="1">
                              <stop offset="0" stopColor={s.color} stopOpacity={0.3} />
                              <stop offset="1" stopColor={s.color} stopOpacity={0.02} />
                            </linearGradient>
                          </defs>
                          {segs.map((seg, j) => (
                            <path key={j} d={areaPath(seg.pts, seg.pts.map(([px]) => [px, base] as Pt), curve)} fill={`url(#${gid}-${k})`} className={animate ? "vf-fade" : undefined} />
                          ))}
                        </>
                      )}
                      {segs.map((seg, j) => (
                        <path
                          key={j}
                          d={linePath(seg.pts, curve)}
                          fill="none"
                          stroke={s.color}
                          strokeWidth={2.25}
                          strokeLinejoin="round"
                          strokeLinecap="round"
                          strokeDasharray={s.dashed ? "5 4" : undefined}
                          pathLength={animate && !s.dashed ? 1 : undefined}
                          className={animate ? (s.dashed ? "vf-fade" : "vf-draw") : undefined}
                        />
                      ))}
                      {segs.flatMap((seg) => seg.idx.map((i, n) => (data.length <= 16 || i === active ? <circle key={i} cx={seg.pts[n][0]} cy={seg.pts[n][1]} r={i === active ? 4.5 : 3} fill="var(--background)" stroke={s.color} strokeWidth={2} /> : null)))}
                    </g>
                  );
                })}
              <CategoryAxis box={box} labels={labels} x={bs.center} stride={stride} highlight={active} />
              <rect
                x={box.left}
                y={box.top}
                width={Math.max(0, box.right - box.left)}
                height={Math.max(0, box.bottom - box.top)}
                fill="transparent"
                style={{ cursor: onSelect ? "pointer" : undefined }}
                onPointerMove={(e) => kb.setActive(bs.index(pointerX(e).x))}
                onClick={() => active !== null && onSelect?.(data[active], active)}
              />
            </svg>
            {active !== null && (
              <ChartTooltip
                width={width}
                state={{
                  x: ax,
                  y: Math.min(box.bottom, ...visible.map((s) => num(data[active], s.key)).map((v, k) => (v === null ? box.bottom : yOf(visible[k])(Math.max(0, v))))),
                  title: labels[active],
                  rows: rowsAt(active),
                }}
              />
            )}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fullFa, niceTicks, polar } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, Legend, announceRows, colorAt, num, useActive, useHidden, type Row, type Series, type ValueFormat } from "@/components/charts/chart-core";

export interface RadarChartProps {
  data: Row[];
  /** Field with each axis name, e.g. «سرعت». */
  axis: string;
  series: Series[];
  title: string;
  description?: string;
  size?: number;
  /** Fixed outer value; default is a round number above the data. */
  max?: number;
  /** Grid shape: polygon rings or circles. */
  grid?: "polygon" | "circle";
  /** Number of grid rings. */
  levels?: number;
  format?: ValueFormat;
  legend?: boolean;
  animate?: boolean;
  className?: string;
}

/**
 * نمودار راداری. Compares several series over the same axes (product specs,
 * skill profiles). The first axis points up and the rest follow clockwise.
 */
export function RadarChart({
  data,
  axis,
  series,
  title,
  description,
  size = 280,
  max,
  grid = "polygon",
  levels = 4,
  format = (n) => fullFa(n, 1),
  legend = series.length > 1,
  animate = true,
  className,
}: RadarChartProps) {
  const { hidden, toggle } = useHidden(series);
  const kb = useActive(data.length);
  const active = kb.active;
  const all = series.map((s, i) => ({ ...s, color: colorAt(i, s.color) }));
  const visible = all.filter((s) => !hidden.has(s.key));
  const values = visible.flatMap((s) => data.map((r) => num(r, s.key) ?? 0));
  const top = max ?? niceTicks(0, Math.max(1, ...values), levels + 1).domain[1];
  const n = data.length;
  const angle = (i: number) => (i / n) * Math.PI * 2;
  const rowsAt = (i: number) => visible.map((s) => ({ key: s.key, label: s.label, color: s.color, value: format(num(data[i], s.key) ?? 0) }));
  const h = size + 40;

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={n < 3}
      emptyText="نمودار راداری دست‌کم سه محور لازم داره"
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(String(data[active][axis]), rowsAt(active)) : ""}
      legendPosition="bottom"
      legend={legend ? <Legend className="justify-center" items={all} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: ["", ...series.map((s) => s.label)], rows: data.map((r) => [String(r[axis]), ...series.map((s) => format(num(r, s.key) ?? 0))]) }}
    >
      {(width) => {
        const cx = width / 2, cy = h / 2, R = size / 2 - 8;
        const ring = (f: number) =>
          grid === "circle" ? null : data.map((_, i) => polar(cx, cy, R * f, angle(i)).join(",")).join(" ");
        return (
          <>
            <svg width={width} height={h} className="block overflow-visible" aria-hidden>
              {Array.from({ length: levels }, (_, k) => {
                const f = (k + 1) / levels;
                return grid === "circle" ? (
                  <circle key={k} cx={cx} cy={cy} r={R * f} fill="none" stroke="var(--border)" />
                ) : (
                  <polygon key={k} points={ring(f)!} fill={k === levels - 1 ? "var(--foreground)" : "none"} fillOpacity={0.02} stroke="var(--border)" />
                );
              })}
              {data.map((r, i) => {
                const [x2, y2] = polar(cx, cy, R, angle(i));
                const [lx, ly] = polar(cx, cy, R + 16, angle(i));
                const s = Math.sin(angle(i));
                return (
                  <g key={i} onPointerEnter={() => kb.setActive(i)}>
                    <line x1={cx} y1={cy} x2={x2} y2={y2} stroke="var(--border)" />
                    <Label x={lx} y={ly} dy="0.35em" anchor={Math.abs(s) < 0.2 ? "middle" : s > 0 ? "left" : "right"} size={11} muted={active !== i} fontWeight={active === i ? 600 : undefined}>
                      {String(r[axis])}
                    </Label>
                    <circle cx={x2} cy={y2} r={14} fill="transparent" />
                  </g>
                );
              })}
              {Array.from({ length: levels }, (_, k) => (
                <Label key={k} anchor="right" x={cx - 5} y={cy - (R * (k + 1)) / levels} dy="0.35em" size={9}>
                  {format((top * (k + 1)) / levels)}
                </Label>
              ))}
              {visible.map((s) => {
                const pts = data.map((r, i) => polar(cx, cy, (R * Math.min(top, Math.max(0, num(r, s.key) ?? 0))) / top, angle(i)));
                return (
                  <g key={s.key} className={animate ? "vf-pop" : undefined}>
                    <polygon points={pts.map((p) => p.join(",")).join(" ")} fill={s.color} fillOpacity={0.16} stroke={s.color} strokeWidth={2} strokeLinejoin="round" strokeDasharray={s.dashed ? "5 4" : undefined} />
                    {pts.map(([px, py], i) => (
                      <circle key={i} cx={px} cy={py} r={active === i ? 4.5 : 2.5} fill={active === i ? "var(--background)" : s.color} stroke={s.color} strokeWidth={2} />
                    ))}
                  </g>
                );
              })}
            </svg>
            {active !== null && (() => {
              const [tx, ty] = polar(cx, cy, R * 0.55, angle(active));
              return <ChartTooltip width={width} state={{ x: tx, y: ty, title: String(data[active][axis]), rows: rowsAt(active) }} />;
            })()}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fullFa, percentFa, textWidth } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type BulletRow = {
  label: string;
  /** Small line under the label, e.g. «میلیون تومان». */
  sublabel?: string;
  value: number;
  /** The goal; drawn as a vertical tick. */
  target?: number;
  /** Ascending band edges from poor to good, e.g. [60, 85, 100]. The last one is the scale max unless `max` is set. */
  ranges?: number[];
  max?: number;
};

export interface BulletChartProps {
  data: BulletRow[];
  title: string;
  description?: string;
  format?: ValueFormat;
  /** Row height in px. */
  row?: number;
  color?: string;
  /** Names of the bands for the tooltip, poor to good. */
  rangeLabels?: string[];
  animate?: boolean;
  className?: string;
}

/**
 * نمودار گلوله‌ای. A compact KPI bar: the measure, a target tick and qualitative bands
 * behind it. Bars start at the labels on the right and grow leftward.
 */
export function BulletChart({ data, title, description, format = (n) => fullFa(n), row = 34, color = colorAt(0), rangeLabels = ["ضعیف", "قابل قبول", "خوب"], animate = true, className }: BulletChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const gap = 14;
  const h = data.length * row + Math.max(0, data.length - 1) * gap;
  const maxOf = (d: BulletRow) => d.max ?? Math.max(d.value, d.target ?? 0, ...(d.ranges ?? [0])) * (d.ranges?.length ? 1 : 1.15);
  const band = (d: BulletRow) => {
    const i = (d.ranges ?? []).findIndex((r) => d.value <= r);
    return i < 0 ? undefined : rangeLabels[i];
  };
  const rows = (i: number) => {
    const d = data[i];
    return [
      { key: "v", label: "مقدار", value: format(d.value), color },
      ...(d.target !== undefined ? [{ key: "t", label: "هدف", value: format(d.target) }, { key: "p", label: "تحقق هدف", value: percentFa((d.value / (d.target || 1)) * 100) }] : []),
      ...(band(d) ? [{ key: "b", label: "وضعیت", value: band(d)! }] : []),
    ];
  };

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(data[active].label, rows(active)) : ""}
      table={{ head: ["شاخص", "مقدار", "هدف", "درصد هدف"], rows: data.map((d) => [d.label, format(d.value), d.target !== undefined ? format(d.target) : "—", d.target ? percentFa((d.value / d.target) * 100) : "—"]) }}
    >
      {(width) => {
        const labelW = Math.min(width * 0.32, Math.max(...data.map((d) => Math.max(textWidth(d.label, 12), textWidth(d.sublabel ?? "", 10)))) + 16);
        const valueW = Math.min(width * 0.18, Math.max(...data.map((d) => textWidth(format(d.value), 12))) + 12);
        const right = width - labelW;
        const left = valueW;
        const span = Math.max(10, right - left);
        const y = (i: number) => i * (row + gap);
        return (
          <>
            <svg width={width} height={h} className="block overflow-visible" aria-hidden>
              {data.map((d, i) => {
                const max = maxOf(d) || 1;
                const px = (v: number) => (Math.max(0, Math.min(max, v)) / max) * span;
                const on = active === i;
                const ranges = d.ranges ?? [max];
                const barH = row * 0.36;
                return (
                  <g key={d.label} onPointerEnter={() => kb.setActive(i)} opacity={active === null || on ? 1 : 0.55} className="vf-mark">
                    {ranges.map((r, k) => {
                      const from = k === 0 ? 0 : ranges[k - 1];
                      return <rect key={k} x={right - px(r)} y={y(i)} width={px(r) - px(from)} height={row} fill="var(--foreground)" fillOpacity={0.05 + (ranges.length - 1 - k) * 0.05} rx={k === ranges.length - 1 ? 4 : 0} />;
                    })}
                    <rect
                      x={right - px(d.value)}
                      y={y(i) + (row - barH) / 2}
                      width={px(d.value)}
                      height={barH}
                      rx={2}
                      fill={color}
                      className={animate ? "vf-grow" : undefined}
                      style={animate ? ({ transformOrigin: "right", "--vf-sx": 0, "--vf-sy": 1 } as React.CSSProperties) : undefined}
                    />
                    {d.target !== undefined && <rect x={right - px(d.target) - 1.5} y={y(i) + row * 0.16} width={3} height={row * 0.68} rx={1} fill="var(--foreground)" />}
                    <Label anchor="right" x={width - 2} y={y(i) + (d.sublabel ? row / 2 - 6 : row / 2)} dy="0.35em" size={12} muted={!on} fontWeight={on ? 600 : 500}>{d.label}</Label>
                    {d.sublabel && <Label anchor="right" x={width - 2} y={y(i) + row / 2 + 9} dy="0.35em" size={10}>{d.sublabel}</Label>}
                    <Label anchor="left" x={2} y={y(i) + row / 2} dy="0.35em" size={12} muted={false} fontWeight={600}>{format(d.value)}</Label>
                  </g>
                );
              })}
            </svg>
            {active !== null && <ChartTooltip width={width} state={{ x: right - ((Math.min(maxOf(data[active]), data[active].value) / (maxOf(data[active]) || 1)) * span), y: y(active) + row / 2, title: data[active].label, rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { arcPath, fullFa, percentFa, polar } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, Legend, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type Slice = { label: string; value: number; color?: string };

export interface PieChartProps {
  data: Slice[];
  title: string;
  description?: string;
  /** "donut" leaves room for a total in the middle. */
  variant?: "pie" | "donut";
  /** Diameter in px; the chart is centred in its box. */
  size?: number;
  format?: ValueFormat;
  /** Text under the number in the donut hole. Default «جمع». */
  centerLabel?: string;
  /** Number in the hole. Default: the sum of all slices. */
  centerValue?: string;
  /** Slices under this share (%) merge into «سایر». 0 keeps them all. */
  minShare?: number;
  /** Largest first; turn off to keep your own order. */
  sort?: boolean;
  /** Write the percentage on slices big enough to hold it. */
  showPercent?: boolean;
  legend?: boolean;
  animate?: boolean;
  onSelect?: (slice: Slice, index: number) => void;
  className?: string;
}

/**
 * نمودار دایره‌ای و دونات. Slices start at 12 o'clock, the hovered slice
 * slides out, small ones fold into «سایر», and the legend lists value and share.
 */
export function PieChart({
  data,
  title,
  description,
  variant = "donut",
  size = 220,
  format = (n) => fullFa(n),
  centerLabel = "جمع",
  centerValue,
  minShare = 0,
  sort = true,
  showPercent = variant === "pie",
  legend = true,
  animate = true,
  onSelect,
  className,
}: PieChartProps) {
  const slices = React.useMemo(() => {
    const total = data.reduce((s, d) => s + Math.max(0, d.value), 0) || 1;
    let list = data.map((d, i) => ({ ...d, color: colorAt(i, d.color) })).filter((d) => d.value > 0);
    if (sort) list = [...list].sort((a, b) => b.value - a.value);
    if (minShare > 0) {
      const small = list.filter((d) => (d.value / total) * 100 < minShare);
      if (small.length > 1) {
        list = list.filter((d) => !small.includes(d));
        list.push({ label: "سایر", value: small.reduce((s, d) => s + d.value, 0), color: "var(--chart-other, var(--muted-foreground))" });
      }
    }
    return { list, total };
  }, [data, sort, minShare]);

  const kb = useActive(slices.list.length);
  const active = kb.active;
  const { list, total } = slices;
  const share = (v: number) => (v / total) * 100;
  const row = (i: number) => [{ key: "v", label: list[i].label, color: list[i].color, value: `${format(list[i].value)} · ${percentFa(share(list[i].value), 1)}` }];
  const pad = 10;
  const h = size + pad * 2;

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={list.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows("", row(active)) : ""}
      legendPosition="bottom"
      legend={
        legend ? (
          <Legend className="justify-center" items={list.map((d, i) => ({ key: String(i), label: d.label, color: d.color, value: percentFa(share(d.value)) }))} />
        ) : undefined
      }
      table={{ head: ["", "مقدار", "سهم"], rows: list.map((d) => [d.label, format(d.value), percentFa(share(d.value), 1)]) }}
    >
      {(width) => {
        const cx = width / 2, cy = h / 2, r = size / 2;
        const inner = variant === "donut" ? r * 0.62 : 0;
        let a = 0;
        const arcs = list.map((d) => {
          const sweep = (d.value / total) * Math.PI * 2;
          const arc = { a0: a, a1: a + sweep, mid: a + sweep / 2 };
          a += sweep;
          return arc;
        });
        const gap = list.length > 1 ? 0.012 : 0;
        return (
          <>
            <svg width={width} height={h} className="block overflow-visible" aria-hidden>
              <g className={animate ? "vf-pop" : undefined}>
                {list.map((d, i) => {
                  const { a0, a1, mid } = arcs[i];
                  const on = active === i;
                  const [dx, dy] = on ? polar(0, 0, 6, mid) : [0, 0];
                  return (
                    <path
                      key={i}
                      d={arcPath(cx, cy, inner, r, a0 + gap, a1 - gap)}
                      fill={d.color}
                      fillOpacity={active === null || on ? 1 : 0.45}
                      transform={`translate(${dx} ${dy})`}
                      className="vf-mark"
                      style={{ cursor: onSelect ? "pointer" : undefined, transition: "transform var(--motion,200ms) var(--vf-ease), fill-opacity var(--motion,200ms)" }}
                      onPointerEnter={() => kb.setActive(i)}
                      onClick={() => onSelect?.(list[i], i)}
                    />
                  );
                })}
                {showPercent &&
                  list.map((d, i) => {
                    const { a0, a1, mid } = arcs[i];
                    if (a1 - a0 < 0.35) return null;
                    const [lx, ly] = polar(cx, cy, inner ? (inner + r) / 2 : r * 0.64, mid);
                    return (
                      <Label key={i} x={lx} y={ly} dy="0.35em" size={11} muted={false} fill="var(--background)" fontWeight={600} pointerEvents="none">
                        {percentFa(share(d.value))}
                      </Label>
                    );
                  })}
              </g>
              {variant === "donut" && (
                <g pointerEvents="none">
                  <Label x={cx} y={cy - 2} size={Math.max(14, Math.min(22, inner / 3.2))} muted={false} fontWeight={700}>
                    {active !== null ? percentFa(share(list[active].value), 1) : (centerValue ?? format(total))}
                  </Label>
                  <Label x={cx} y={cy + 18} size={11}>
                    {active !== null ? list[active].label : centerLabel}
                  </Label>
                </g>
              )}
            </svg>
            {active !== null && variant === "pie" && (
              <ChartTooltip width={width} state={{ x: polar(cx, cy, r * 0.7, arcs[active].mid)[0], y: polar(cx, cy, r * 0.7, arcs[active].mid)[1], rows: row(active) }} />
            )}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { arcPath, fullFa, percentFa } from "@/lib/chart-utils";
import { ChartFrame, Label, Legend, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type Ring = { label: string; value: number; max?: number; color?: string };

export interface RadialChartProps {
  data: Ring[];
  title: string;
  description?: string;
  size?: number;
  /** Total sweep in degrees: 360 for full rings, 270 for an open «C». */
  sweep?: number;
  format?: ValueFormat;
  /** Big number in the middle, e.g. the overall score. */
  centerValue?: string;
  centerLabel?: string;
  legend?: boolean;
  animate?: boolean;
  className?: string;
}

/**
 * نمودار شعاعی. Concentric progress rings, one per metric (goal, quota,
 * storage), each against its own max. Rings fill clockwise from 12 o'clock.
 */
export function RadialChart({
  data,
  title,
  description,
  size = 220,
  sweep = 360,
  format = (n) => fullFa(n),
  centerValue,
  centerLabel,
  legend = true,
  animate = true,
  className,
}: RadialChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const rings = data.map((d, i) => ({ ...d, color: colorAt(i, d.color), max: d.max ?? 100 }));
  const pct = (d: (typeof rings)[number]) => Math.max(0, Math.min(1, d.value / (d.max || 1)));
  const row = (i: number) => [{ key: "v", label: rings[i].label, color: rings[i].color, value: `${format(rings[i].value)} از ${format(rings[i].max)} · ${percentFa(pct(rings[i]) * 100)}` }];
  const span = (Math.min(360, sweep) / 180) * Math.PI;
  const start = -span / 2;
  const h = size + 12;

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={rings.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows("", row(active)) : ""}
      legendPosition="bottom"
      legend={legend ? <Legend className="justify-center" items={rings.map((d, i) => ({ key: String(i), label: d.label, color: d.color, value: percentFa(pct(d) * 100) }))} /> : undefined}
      table={{ head: ["", "مقدار", "سقف", "درصد"], rows: rings.map((d) => [d.label, format(d.value), format(d.max), percentFa(pct(d) * 100)]) }}
    >
      {(width) => {
        const cx = width / 2, cy = h / 2, outer = size / 2;
        const inner = centerValue ? outer * 0.42 : outer * 0.3;
        const step = (outer - inner) / Math.max(1, rings.length);
        const thick = step * 0.72;
        const a0 = sweep >= 360 ? 0 : start;
        return (
          <svg width={width} height={h} className="block overflow-visible" aria-hidden>
            {rings.map((d, i) => {
              const r1 = outer - i * step, r0 = r1 - thick;
              const end = a0 + (sweep >= 360 ? Math.PI * 2 : span) * pct(d);
              const dim = active !== null && active !== i;
              const cap = thick / 2;
              const [ex, ey] = [cx + ((r0 + r1) / 2) * Math.sin(end), cy - ((r0 + r1) / 2) * Math.cos(end)];
              const [sx, sy] = [cx + ((r0 + r1) / 2) * Math.sin(a0), cy - ((r0 + r1) / 2) * Math.cos(a0)];
              return (
                <g key={i} onPointerEnter={() => kb.setActive(i)} opacity={dim ? 0.4 : 1} className="vf-mark">
                  <path d={arcPath(cx, cy, r0, r1, a0, a0 + (sweep >= 360 ? Math.PI * 2 : span))} fill="var(--foreground)" fillOpacity={0.07} />
                  {pct(d) > 0 && (
                    <g className={animate ? "vf-fade" : undefined}>
                      <path d={arcPath(cx, cy, r0, r1, a0, end)} fill={d.color} />
                      <circle cx={sx} cy={sy} r={cap} fill={d.color} />
                      <circle cx={ex} cy={ey} r={cap} fill={d.color} />
                    </g>
                  )}
                </g>
              );
            })}
            {(centerValue || active !== null) && (
              <g pointerEvents="none">
                <Label x={cx} y={cy - 2} size={Math.max(13, inner / 2.6)} muted={false} fontWeight={700}>
                  {active !== null ? percentFa(pct(rings[active]) * 100) : centerValue}
                </Label>
                <Label x={cx} y={cy + 16} size={10}>
                  {active !== null ? rings[active].label : centerLabel}
                </Label>
              </g>
            )}
          </svg>
        );
      }}
    </ChartFrame>
  );
}

export type GaugeBand = { to: number; color: string; label?: string };

export interface GaugeChartProps {
  value: number;
  min?: number;
  max?: number;
  title: string;
  description?: string;
  /** Coloured zones up to each `to`, e.g. bad / ok / good. */
  bands?: GaugeBand[];
  format?: ValueFormat;
  /** Line under the value, e.g. «رضایت مشتری». */
  label?: string;
  size?: number;
  animate?: boolean;
  className?: string;
}

/**
 * گیج. A half circle that reads right to left: the minimum sits on the right
 * end, the maximum on the left, with optional coloured zones and a needle.
 */
export function GaugeChart({ value, min = 0, max = 100, title, description, bands, format = (n) => fullFa(n), label, size = 240, animate = true, className }: GaugeChartProps) {
  const t = Math.max(0, Math.min(1, (value - min) / (max - min || 1)));
  // Angle 0 = up; +90° = right (min), −90° = left (max).
  const ang = (v: number) => Math.PI / 2 - ((v - min) / (max - min || 1)) * Math.PI;
  const h = size / 2 + 40;
  const zones = bands?.length ? bands : [{ to: max, color: colorAt(0) }];
  const current = zones.find((b) => value <= b.to) ?? zones[zones.length - 1];

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      announce=""
      table={{ head: ["", "مقدار"], rows: [[label ?? title, format(value)], ["کمینه", format(min)], ["بیشینه", format(max)]] }}
    >
      {(width) => {
        const cx = width / 2, cy = size / 2 + 8, r1 = size / 2, r0 = r1 * 0.74;
        let from = min;
        const needle = ang(min + t * (max - min));
        return (
          <svg width={width} height={h} className="block overflow-visible" aria-hidden>
            <path d={arcPath(cx, cy, r0, r1, -Math.PI / 2, Math.PI / 2)} fill="var(--foreground)" fillOpacity={0.07} />
            {zones.map((b, i) => {
              const a = ang(Math.min(max, b.to)), z = ang(from);
              from = b.to;
              return <path key={i} d={arcPath(cx, cy, r1 + 4, r1 + 8, a, z)} fill={b.color} fillOpacity={0.55} />;
            })}
            <path d={arcPath(cx, cy, r0, r1, needle, Math.PI / 2)} fill={current.color} className={animate ? "vf-fade" : undefined} />
            <g
              style={{ transform: `rotate(${(needle * 180) / Math.PI}deg)`, transformOrigin: `${cx}px ${cy}px`, transition: "transform calc(var(--motion,200ms)*3) var(--motion-ease,ease)" }}
            >
              <path d={`M${cx - 4},${cy} L${cx},${cy - r0 + 6} L${cx + 4},${cy} Z`} fill="var(--foreground)" />
            </g>
            <circle cx={cx} cy={cy} r={7} fill="var(--background)" stroke="var(--foreground)" strokeWidth={2} />
            <Label anchor="right" x={cx + r1} y={cy + 18} size={10}>{format(min)}</Label>
            <Label anchor="left" x={cx - r1} y={cy + 18} size={10}>{format(max)}</Label>
            <Label x={cx} y={cy - r0 * 0.38} size={Math.max(18, size / 9)} muted={false} fontWeight={700}>
              {format(value)}
            </Label>
            {(label || current.label) && (
              <Label x={cx} y={cy + 24} size={11}>
                {current.label ?? label}
              </Label>
            )}
          </svg>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fullFa, percentFa, squarify, textWidth } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Legend, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type TreemapItem = { label: string; value: number; group?: string; color?: string };

export interface TreemapChartProps {
  data: TreemapItem[];
  title: string;
  description?: string;
  height?: number;
  format?: ValueFormat;
  /** Colour by `group` (with a legend) instead of one colour per item. */
  colorBy?: "item" | "group";
  animate?: boolean;
  onSelect?: (item: TreemapItem, index: number) => void;
  className?: string;
}

/**
 * نقشه‌ی درختی. Area is proportional to value (squarified layout). The largest
 * tile lands top-right where Persian reading starts; labels show only when they fit.
 */
export function TreemapChart({ data, title, description, height = 300, format = (n) => fullFa(n), colorBy = data.some((d) => d.group) ? "group" : "item", animate = true, onSelect, className }: TreemapChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const total = data.reduce((s, d) => s + Math.max(0, d.value), 0) || 1;
  const groups = Array.from(new Set(data.map((d) => d.group ?? "")));
  const colorOf = (d: TreemapItem, i: number) => d.color ?? (colorBy === "group" ? colorAt(groups.indexOf(d.group ?? "")) : colorAt(i));
  const rows = (i: number) => [
    { key: "v", label: "مقدار", value: format(data[i].value), color: colorOf(data[i], i) },
    { key: "s", label: "سهم", value: percentFa((data[i].value / total) * 100, 1) },
    ...(data[i].group ? [{ key: "g", label: "گروه", value: data[i].group! }] : []),
  ];

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(data[active].label, rows(active)) : ""}
      legend={colorBy === "group" && groups.length > 1 ? <Legend items={groups.map((g, i) => ({ key: g, label: g, color: colorAt(i) }))} /> : undefined}
      table={{ head: ["", "مقدار", "سهم"], rows: data.map((d) => [d.label, format(d.value), percentFa((d.value / total) * 100, 1)]) }}
    >
      {(width) => {
        const rects = squarify(data.map((d) => d.value), { x: 0, y: 0, w: width, h: height });
        return (
          <>
            <svg width={width} height={height} className="block" aria-hidden>
              {data.map((d, i) => {
                const r = rects[i];
                if (!r || r.w < 1 || r.h < 1) return null;
                const on = active === i;
                const fits = r.w > textWidth(d.label, 12) + 12 && r.h > 38;
                const tiny = !fits && r.w > textWidth(d.label, 10) + 8 && r.h > 18;
                return (
                  <g key={i} onPointerEnter={() => kb.setActive(i)} onClick={() => onSelect?.(d, i)} style={{ cursor: onSelect ? "pointer" : undefined }} className={animate ? "vf-fade" : undefined}>
                    <rect
                      x={r.x + 1}
                      y={r.y + 1}
                      width={Math.max(0, r.w - 2)}
                      height={Math.max(0, r.h - 2)}
                      rx={6}
                      fill={colorOf(d, i)}
                      fillOpacity={active === null ? 0.85 : on ? 1 : 0.45}
                      stroke={on ? "var(--foreground)" : "none"}
                      strokeWidth={2}
                      className="vf-mark"
                    />
                    {(fits || tiny) && (
                      <text direction="rtl" textAnchor="start" x={r.x + r.w - 8} y={r.y + (fits ? 20 : r.h / 2 + 4)} fontSize={fits ? 12 : 10} fontWeight={600} fill="var(--background)" pointerEvents="none">
                        {d.label}
                      </text>
                    )}
                    {fits && (
                      <text direction="rtl" textAnchor="start" x={r.x + r.w - 8} y={r.y + 36} fontSize={11} fill="var(--background)" fillOpacity={0.85} pointerEvents="none">
                        {percentFa((d.value / total) * 100, 1)}
                      </text>
                    )}
                  </g>
                );
              })}
            </svg>
            {active !== null && rects[active] && <ChartTooltip width={width} state={{ x: rects[active].x + rects[active].w / 2, y: rects[active].y + rects[active].h / 2, title: data[active].label, rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { compactFa, extent, fullFa, linearScale, niceTicks, textWidth } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, Legend, ValueGrid, announceRows, colorAt, num, plotBox, useActive, useHidden, type Reference, type Row, type ValueFormat } from "@/components/charts/chart-core";

export interface ScatterChartProps {
  data: Row[];
  /** Numeric field on the horizontal axis (grows right to left). */
  x: string;
  /** Numeric field on the vertical axis. */
  y: string;
  /** Optional numeric field that sets bubble area. */
  size?: string;
  /** Optional field that groups points into colours and legend entries. */
  group?: string;
  /** Field shown as the tooltip title, e.g. a product or city name. */
  name?: string;
  title: string;
  description?: string;
  xLabel?: string;
  yLabel?: string;
  sizeLabel?: string;
  height?: number;
  xFormat?: ValueFormat;
  yFormat?: ValueFormat;
  sizeFormat?: ValueFormat;
  /** Vertical / horizontal reference lines, e.g. the averages that split a quadrant chart. */
  xReferences?: Reference[];
  yReferences?: Reference[];
  legend?: boolean;
  animate?: boolean;
  onSelect?: (row: Row, index: number) => void;
  className?: string;
}

/**
 * نمودار پراکندگی و حبابی. Origin at the bottom-right like every chart here:
 * x grows to the left, y grows up, the optional third value sets bubble area.
 */
export function ScatterChart({
  data,
  x,
  y,
  size,
  group,
  name,
  title,
  description,
  xLabel,
  yLabel,
  sizeLabel = "اندازه",
  height = 300,
  xFormat = compactFa,
  yFormat = compactFa,
  sizeFormat = (n) => fullFa(n),
  xReferences,
  yReferences,
  legend,
  animate = true,
  onSelect,
  className,
}: ScatterChartProps) {
  const groups = React.useMemo(() => (group ? Array.from(new Set(data.map((r) => String(r[group])))) : ["all"]), [data, group]);
  const groupSeries = groups.map((g, i) => ({ key: g, label: g, color: colorAt(i) }));
  const { hidden, toggle } = useHidden(groupSeries);
  const pts = data
    .map((r, i) => ({ r, i, xv: num(r, x), yv: num(r, y), sv: size ? num(r, size) ?? 0 : 0, g: group ? String(r[group]) : "all" }))
    .filter((p) => p.xv !== null && p.yv !== null && !hidden.has(p.g)) as { r: Row; i: number; xv: number; yv: number; sv: number; g: string }[];
  const kb = useActive(pts.length);
  const active = kb.active;
  const xt = niceTicks(...extent(pts.map((p) => p.xv), false), 6);
  const yt = niceTicks(...extent(pts.map((p) => p.yv), false), Math.max(3, Math.floor((height - 40) / 50)));
  const sMax = Math.max(1, ...pts.map((p) => p.sv));
  const colorOf = (g: string) => groupSeries[groups.indexOf(g)]?.color ?? colorAt(0);
  const rowsOf = (p: (typeof pts)[number]) => [
    { key: "x", label: xLabel ?? x, value: xFormat(p.xv) },
    { key: "y", label: yLabel ?? y, value: yFormat(p.yv) },
    ...(size ? [{ key: "s", label: sizeLabel, value: sizeFormat(p.sv) }] : []),
  ];
  const titleOf = (p: (typeof pts)[number]) => (name ? String(p.r[name]) : group ? p.g : "");

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={pts.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null && pts[active] ? announceRows(titleOf(pts[active]), rowsOf(pts[active])) : ""}
      legend={(legend ?? !!group) ? <Legend items={groupSeries} hidden={hidden} onToggle={toggle} /> : undefined}
      table={{ head: [name ?? "", xLabel ?? x, yLabel ?? y, ...(size ? [sizeLabel] : [])], rows: pts.map((p) => [titleOf(p), xFormat(p.xv), yFormat(p.yv), ...(size ? [sizeFormat(p.sv)] : [])]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: yt.ticks.map(yFormat), top: 14 });
        box.bottom -= yLabel || xLabel ? 14 : 0;
        const sx = linearScale(xt.domain, [box.right - 4, box.left + 4]);
        const sy = linearScale(yt.domain, [box.bottom, box.top]);
        const maxR = Math.max(10, Math.min(34, (box.right - box.left) / 16));
        const rad = (v: number) => (size ? 3 + Math.sqrt(v / sMax) * maxR : 5);
        const stride = Math.max(1, Math.ceil((xt.ticks.length * Math.max(...xt.ticks.map((t) => textWidth(xFormat(t), 10)))) / (box.right - box.left)));
        const order = pts.map((_, k) => k).sort((a, b) => pts[b].sv - pts[a].sv);
        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <ValueGrid box={box} ticks={yt.ticks} y={sy} format={yFormat} />
              {xt.ticks.map((t, k) => (
                <g key={t}>
                  <line x1={sx(t)} x2={sx(t)} y1={box.top} y2={box.bottom} stroke="var(--border)" strokeOpacity={0.5} strokeDasharray="3 3" />
                  {k % stride === 0 && <Label x={sx(t)} y={box.bottom + 16} size={10}>{xFormat(t)}</Label>}
                </g>
              ))}
              {xLabel && <Label anchor="left" x={box.left} y={height - 2} size={10}>{`← ${xLabel}`}</Label>}
              {yLabel && <Label anchor="right" x={box.right - 2} y={box.top - 4} size={10}>{yLabel}</Label>}
              {xReferences?.map((r, k) => (
                <g key={`x${k}`}>
                  <line x1={sx(r.value)} x2={sx(r.value)} y1={box.top} y2={box.bottom} stroke={r.color ?? "var(--foreground)"} strokeOpacity={0.5} strokeDasharray="6 4" />
                  {r.label && <Label anchor="left" x={sx(r.value) + 4} y={box.top + 10} size={10}>{r.label}</Label>}
                </g>
              ))}
              {yReferences?.map((r, k) => (
                <g key={`y${k}`}>
                  <line x1={box.left} x2={box.right} y1={sy(r.value)} y2={sy(r.value)} stroke={r.color ?? "var(--foreground)"} strokeOpacity={0.5} strokeDasharray="6 4" />
                  {r.label && <Label anchor="left" x={box.left + 2} y={sy(r.value) - 5} size={10}>{r.label}</Label>}
                </g>
              ))}
              <g className={animate ? "vf-fade" : undefined}>
                {order.map((k) => {
                  const p = pts[k];
                  const on = active === k;
                  const c = colorOf(p.g);
                  return (
                    <circle
                      key={p.i}
                      cx={sx(p.xv)}
                      cy={sy(p.yv)}
                      r={rad(p.sv) + (on ? 2 : 0)}
                      fill={c}
                      fillOpacity={active === null ? (size ? 0.55 : 0.8) : on ? 0.95 : 0.25}
                      stroke={on ? "var(--foreground)" : c}
                      strokeWidth={on ? 2 : 1}
                      className="vf-mark"
                      style={{ cursor: onSelect ? "pointer" : undefined }}
                      onPointerEnter={() => kb.setActive(k)}
                      onClick={() => onSelect?.(p.r, p.i)}
                    />
                  );
                })}
              </g>
            </svg>
            {active !== null && pts[active] && (
              <ChartTooltip width={width} state={{ x: sx(pts[active].xv), y: sy(pts[active].yv), title: titleOf(pts[active]) || undefined, rows: rowsOf(pts[active]) }} />
            )}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fa } from "@/lib/utils";
import { addDays, dayKey, fullFa, satWeekday, textWidth } from "@/lib/chart-utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, JALALI_WEEKDAYS_SHORT, toJalali } from "@/lib/jalali";
import { ChartFrame, ChartTooltip, Label, colorAt, type ValueFormat } from "@/components/charts/chart-core";

/** 0 → empty cell, then four steps of the colour. */
const LEVELS = [0.07, 0.3, 0.5, 0.75, 1];

function levelOf(v: number, max: number) {
  if (!v || v <= 0) return 0;
  return Math.min(4, 1 + Math.floor((v / (max || 1)) * 3.999));
}

function ScaleLegend({ color }: { color: string }) {
  return (
    <div className="flex items-center justify-end gap-1.5 text-[11px] text-muted-foreground" aria-hidden>
      <span>کمتر</span>
      {LEVELS.map((o, i) => (
        <span key={i} className="size-2.5 rounded-[3px]" style={{ background: i === 0 ? "var(--foreground)" : color, opacity: o }} />
      ))}
      <span>بیشتر</span>
    </div>
  );
}

export type DayValue = { date: Date | string; value: number };

export interface CalendarHeatmapProps {
  data: DayValue[];
  title: string;
  description?: string;
  /** Last day shown. Default: today. */
  end?: Date;
  /** How many days back from `end`. Default: one year. */
  days?: number;
  /** Days to ring as official holidays (تعطیل رسمی). */
  holidays?: (Date | string)[];
  /** Unit after the number in the tooltip, e.g. «سفارش». */
  unit?: string;
  format?: ValueFormat;
  color?: string;
  legend?: boolean;
  onSelect?: (date: Date, value: number) => void;
  className?: string;
}

const toKey = (d: Date | string) => (typeof d === "string" ? d.slice(0, 10) : dayKey(d));

/**
 * نقشه‌ی حرارتی تقویم شمسی. A year of days as a week grid: weeks run right to
 * left, rows go شنبه to جمعه, months are labelled in Jalali, and holidays get a ring.
 * Arrow keys move by day (up/down) and by week (left = next week).
 */
export function CalendarHeatmap({
  data,
  title,
  description,
  end,
  days = 365,
  holidays,
  unit = "",
  format = (n) => fullFa(n),
  color = colorAt(0),
  legend = true,
  onSelect,
  className,
}: CalendarHeatmapProps) {
  const last = React.useMemo(() => { const e = end ?? new Date(); return new Date(e.getFullYear(), e.getMonth(), e.getDate()); }, [end]);
  const { cells, weeks, max, total } = React.useMemo(() => {
    const map = new Map<string, number>();
    data.forEach((d) => map.set(toKey(d.date), (map.get(toKey(d.date)) ?? 0) + d.value));
    let first = addDays(last, -(days - 1));
    first = addDays(first, -satWeekday(first));
    const out: { date: Date; key: string; value: number; week: number; dow: number; inRange: boolean }[] = [];
    for (let d = first, i = 0; d <= last; d = addDays(d, 1), i++) {
      const key = dayKey(d);
      out.push({ date: d, key, value: map.get(key) ?? 0, week: Math.floor(i / 7), dow: satWeekday(d), inRange: i >= satWeekday(addDays(last, -(days - 1))) });
    }
    const vals = out.filter((c) => c.inRange).map((c) => c.value);
    return { cells: out, weeks: Math.ceil(out.length / 7), max: Math.max(1, ...vals), total: vals.reduce((a, b) => a + b, 0) };
  }, [data, last, days]);
  const holidaySet = React.useMemo(() => new Set((holidays ?? []).map(toKey)), [holidays]);
  const [active, setActive] = React.useState<number | null>(null);

  const describe = (c: (typeof cells)[number]) => {
    const { jy, jm, jd } = toJalali(c.date);
    return `${JALALI_WEEKDAYS[c.dow]} ${fa(jd)} ${JALALI_MONTHS[jm - 1]} ${fa(jy)}${holidaySet.has(c.key) ? " (تعطیل)" : ""}`;
  };
  const valueText = (v: number) => (v ? `${format(v)}${unit ? ` ${unit}` : ""}` : `بدون ${unit || "داده"}`);

  const onKeyDown = (e: React.KeyboardEvent) => {
    const step: Record<string, number> = { ArrowDown: 1, ArrowUp: -1, ArrowLeft: 7, ArrowRight: -7 };
    if (e.key === "Escape") return setActive(null);
    if (e.key === "Enter" && active !== null) return onSelect?.(cells[active].date, cells[active].value);
    if (e.key === "End") { e.preventDefault(); return setActive(cells.length - 1); }
    if (e.key === "Home") { e.preventDefault(); return setActive(cells.findIndex((c) => c.inRange)); }
    if (!(e.key in step)) return;
    e.preventDefault();
    setActive((a) => Math.max(0, Math.min(cells.length - 1, (a ?? cells.length - 1) + (a === null ? 0 : step[e.key]))));
  };

  const head = 18, side = 22, gap = 3;
  /** Cell size for this width; on narrow screens the oldest weeks drop off instead of cells shrinking below 10px. */
  const fit = (width: number) => {
    const ideal = (width - side) / weeks - gap;
    if (ideal >= 10) return { cell: Math.min(18, ideal), skip: 0 };
    const shown = Math.max(1, Math.floor((width - side) / (10 + gap)));
    return { cell: 10, skip: weeks - shown };
  };
  return (
    <ChartFrame
      title={title}
      description={description ?? `جمع ${valueText(total)} در ${fa(days)} روز`}
      height={0}
      className={className}
      keyboard={{ onKeyDown, onBlur: () => setActive(null) }}
      onPointerLeave={() => setActive(null)}
      announce={active !== null ? `${describe(cells[active])}، ${valueText(cells[active].value)}` : ""}
      legendPosition="bottom"
      legend={legend ? <ScaleLegend color={color} /> : undefined}
      table={{ head: ["روز", "مقدار"], rows: cells.filter((c) => c.inRange && c.value).map((c) => [describe(c), format(c.value)]) }}
      autoHeight={(width) => head + 7 * (fit(width).cell + gap)}
    >
      {(width) => {
        const { cell, skip } = fit(width);
        const pitch = cell + gap;
        const h = head + 7 * pitch;
        const gridRight = width - side;
        const cx = (w: number) => gridRight - (w - skip + 1) * pitch + gap / 2;
        const cy = (dow: number) => head + dow * pitch;
        // A month label goes over the first week that contains day 1 of that month.
        const months: { week: number; label: string }[] = [];
        cells.forEach((c) => {
          if (!c.inRange || c.week < skip) return;
          const { jd, jm } = toJalali(c.date);
          if (jd === 1 || (months.length === 0 && c.dow === 0)) months.push({ week: c.week, label: JALALI_MONTHS[jm - 1] });
        });
        // Drop the partial first month when the next label would collide with it, then any later collision.
        if (months.length > 1 && (months[1].week - months[0].week) * pitch < textWidth(months[0].label, 10) + 6) months.shift();
        for (let k = 1; k < months.length; k++) {
          if ((months[k].week - months[k - 1].week) * pitch < textWidth(months[k - 1].label, 10) + 6) months.splice(k--, 1);
        }
        const ac = active !== null ? cells[active] : null;
        return (
          <>
            <svg width={width} height={h} className="block" aria-hidden>
              {months.map((m, i) => (
                <Label key={i} anchor="right" x={cx(m.week) + cell} y={11} size={10}>
                  {m.label}
                </Label>
              ))}
              {JALALI_WEEKDAYS_SHORT.map((d, i) => (cell < 11 && i % 2 === 1 ? null :
                <Label key={d} anchor="right" x={width - 2} y={cy(i) + cell / 2} dy="0.35em" size={9} muted={i !== 6}>
                  {d}
                </Label>
              ))}
              {cells.map((c, i) =>
                c.inRange && c.week >= skip ? (
                  <rect
                    key={c.key}
                    x={cx(c.week)}
                    y={cy(c.dow)}
                    width={cell}
                    height={cell}
                    rx={Math.min(4, cell / 4)}
                    fill={levelOf(c.value, max) === 0 ? "var(--foreground)" : color}
                    fillOpacity={LEVELS[levelOf(c.value, max)]}
                    stroke={active === i ? "var(--foreground)" : holidaySet.has(c.key) ? "var(--destructive)" : "none"}
                    strokeWidth={active === i ? 2 : 1.25}
                    style={{ cursor: onSelect ? "pointer" : undefined }}
                    onPointerEnter={() => setActive(i)}
                    onClick={() => onSelect?.(c.date, c.value)}
                  />
                ) : null,
              )}
            </svg>
            {ac && ac.week >= skip && <ChartTooltip width={width} state={{ x: cx(ac.week) + cell / 2, y: cy(ac.dow) + cell / 2, title: describe(ac), rows: [{ key: "v", label: unit || "مقدار", value: ac.value ? format(ac.value) : "—", color }] }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

export interface MatrixHeatmapProps {
  /** Row names top to bottom, e.g. weekdays. */
  rows: string[];
  /** Column names right to left, e.g. hours. */
  cols: string[];
  /** values[row][col]. */
  values: number[][];
  title: string;
  description?: string;
  format?: ValueFormat;
  /** Show every n-th column label. Default: as many as fit. */
  colStride?: number;
  /** Write each value inside its cell when there is room. */
  showValues?: boolean;
  color?: string;
  legend?: boolean;
  className?: string;
}

/**
 * نقشه‌ی حرارتی جدولی. Any rows × columns grid, such as weekday × hour traffic
 * or city × month sales. Column 0 is on the right; arrow keys move between cells.
 */
export function MatrixHeatmap({ rows, cols, values, title, description, format = (n) => fullFa(n), colStride, showValues = false, color = colorAt(1), legend = true, className }: MatrixHeatmapProps) {
  const [active, setActive] = React.useState<[number, number] | null>(null);
  const max = Math.max(1, ...values.flat());
  const sideW = Math.max(...rows.map((r) => r.length * 7 + 10));
  const onKeyDown = (e: React.KeyboardEvent) => {
    const d: Record<string, [number, number]> = { ArrowDown: [1, 0], ArrowUp: [-1, 0], ArrowLeft: [0, 1], ArrowRight: [0, -1] };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in d)) return;
    e.preventDefault();
    setActive((a) => (a === null ? [0, 0] : [Math.max(0, Math.min(rows.length - 1, a[0] + d[e.key][0])), Math.max(0, Math.min(cols.length - 1, a[1] + d[e.key][1]))]));
  };
  const head = 18, gap = 2;
  return (
    <ChartFrame
      title={title}
      description={description}
      height={0}
      className={className}
      keyboard={{ onKeyDown, onBlur: () => setActive(null) }}
      onPointerLeave={() => setActive(null)}
      announce={active ? `${rows[active[0]]}، ${cols[active[1]]}: ${format(values[active[0]]?.[active[1]] ?? 0)}` : ""}
      legendPosition="bottom"
      legend={legend ? <ScaleLegend color={color} /> : undefined}
      table={{ head: ["", ...cols], rows: rows.map((r, i) => [r, ...cols.map((_, j) => format(values[i]?.[j] ?? 0))]) }}
      autoHeight={(width) => {
        const cw = (width - sideW) / cols.length;
        return head + rows.length * Math.max(14, Math.min(34, cw * 0.8));
      }}
    >
      {(width) => {
        const cw = (width - sideW) / cols.length;
        const ch = Math.max(14, Math.min(34, cw * 0.8));
        const right = width - sideW;
        const stride = colStride ?? Math.max(1, Math.ceil(28 / cw));
        const x = (j: number) => right - (j + 1) * cw;
        const y = (i: number) => head + i * ch;
        return (
          <>
            <svg width={width} height={head + rows.length * ch} className="block" aria-hidden>
              {cols.map((c, j) => (j % stride === 0 ? <Label key={j} x={x(j) + cw / 2} y={11} size={10}>{c}</Label> : null))}
              {rows.map((r, i) => (
                <Label key={r} anchor="right" x={width - 2} y={y(i) + ch / 2} dy="0.35em" size={11} muted={active?.[0] !== i}>
                  {r}
                </Label>
              ))}
              {rows.map((_, i) =>
                cols.map((_, j) => {
                  const v = values[i]?.[j] ?? 0;
                  const on = active?.[0] === i && active?.[1] === j;
                  const lvl = v / max;
                  return (
                    <g key={`${i}-${j}`} onPointerEnter={() => setActive([i, j])}>
                      <rect x={x(j) + gap / 2} y={y(i) + gap / 2} width={cw - gap} height={ch - gap} rx={3} fill={v ? color : "var(--foreground)"} fillOpacity={v ? 0.12 + lvl * 0.88 : 0.05} stroke={on ? "var(--foreground)" : "none"} strokeWidth={2} />
                      {showValues && cw > 26 && v > 0 && (
                        <Label x={x(j) + cw / 2} y={y(i) + ch / 2} dy="0.35em" size={9} muted={false} fill={lvl > 0.55 ? "var(--background)" : "var(--foreground)"} pointerEvents="none">
                          {format(v)}
                        </Label>
                      )}
                    </g>
                  );
                }),
              )}
            </svg>
            {active && <ChartTooltip width={width} state={{ x: x(active[1]) + cw / 2, y: y(active[0]) + ch / 2, title: `${rows[active[0]]}، ${cols[active[1]]}`, rows: [{ key: "v", label: "مقدار", value: format(values[active[0]]?.[active[1]] ?? 0), color }] }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fullFa, percentFa } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, announceRows, colorAt, type ValueFormat } from "@/components/charts/chart-core";
import { cn } from "@/lib/utils";

/**
 * Tile positions [column west→east, row north→south]. Each province is one equal tile placed
 * near where it really is, so Tehran and Sistan-Baluchestan weigh the same: the map shows
 * the numbers, not the land area. Geography is never mirrored for RTL; east stays on the right.
 */
export const IRAN_TILES: Record<string, [number, number]> = {
  "آذربایجان غربی": [0, 0], "آذربایجان شرقی": [1, 0], "اردبیل": [2, 0], "گیلان": [3, 0], "مازندران": [4, 0], "گلستان": [5, 0], "خراسان شمالی": [6, 0],
  "کردستان": [0, 1], "زنجان": [1, 1], "قزوین": [2, 1], "البرز": [3, 1], "تهران": [4, 1], "سمنان": [5, 1], "خراسان رضوی": [6, 1],
  "کرمانشاه": [0, 2], "همدان": [1, 2], "مرکزی": [2, 2], "قم": [3, 2], "اصفهان": [4, 2], "یزد": [5, 2], "خراسان جنوبی": [6, 2],
  "ایلام": [0, 3], "لرستان": [1, 3], "چهارمحال و بختیاری": [2, 3], "کهگیلویه و بویراحمد": [3, 3], "فارس": [4, 3], "کرمان": [5, 3], "سیستان و بلوچستان": [6, 3],
  "خوزستان": [1, 4], "بوشهر": [3, 4], "هرمزگان": [5, 4],
};

/** Short names for narrow tiles. */
export const IRAN_SHORT: Record<string, string> = {
  "آذربایجان غربی": "آذ. غربی", "آذربایجان شرقی": "آذ. شرقی", "خراسان شمالی": "خ. شمالی", "خراسان رضوی": "خ. رضوی", "خراسان جنوبی": "خ. جنوبی",
  "چهارمحال و بختیاری": "چهارمحال", "کهگیلویه و بویراحمد": "کهگیلویه", "سیستان و بلوچستان": "سیستان",
};

const COLS = 7;
const ROWS = 5;

export type ProvinceDatum = { province: string; value: number };

export interface IranMapChartProps {
  data: ProvinceDatum[];
  title: string;
  description?: string;
  format?: ValueFormat;
  /** Number of color steps in the legend. */
  steps?: number;
  color?: string;
  /** Unit after the legend numbers, e.g. «سفارش». */
  unit?: string;
  onSelect?: (province: string, value: number | null) => void;
  className?: string;
}

/** Visit order for the keyboard: north to south, and east to west inside a row (reading order). */
const KEY_ORDER = Object.entries(IRAN_TILES)
  .sort(([, a], [, b]) => a[1] - b[1] || b[0] - a[0])
  .map(([name]) => name);

/**
 * نقشه‌ی استان‌ها. A tile-grid choropleth of Iran's 31 provinces: each tile is shaded by
 * its value in equal steps, with a stepped legend, tooltip, keyboard navigation and a
 * hidden table. Provinces without data are drawn hatched, never as zero.
 */
export function IranMapChart({ data, title, description, format = (n) => fullFa(n), steps = 5, color = colorAt(0), unit, onSelect, className }: IranMapChartProps) {
  const values = React.useMemo(() => new Map(data.map((d) => [d.province, d.value])), [data]);
  const [active, setActive] = React.useState<string | null>(null);
  const known = data.filter((d) => IRAN_TILES[d.province]);
  const min = known.length ? Math.min(...known.map((d) => d.value)) : 0;
  const max = known.length ? Math.max(...known.map((d) => d.value)) : 1;
  const total = known.reduce((s, d) => s + d.value, 0);
  const step = (v: number) => (max === min ? steps - 1 : Math.min(steps - 1, Math.floor(((v - min) / (max - min)) * steps)));
  const shade = (k: number) => `color-mix(in oklab, ${color} ${Math.round(18 + (k / Math.max(1, steps - 1)) * 82)}%, var(--card))`;

  const rows = (name: string) => {
    const v = values.get(name);
    return v === undefined
      ? [{ key: "n", label: "مقدار", value: "داده‌ای ثبت نشده" }]
      : [{ key: "v", label: unit ?? "مقدار", value: format(v), color: shade(step(v)) }, { key: "s", label: "سهم از کل", value: percentFa((v / (total || 1)) * 100, 1) }];
  };

  function onKeyDown(e: React.KeyboardEvent) {
    const i = active ? KEY_ORDER.indexOf(active) : -1;
    let next: number | null = null;
    if (e.key === "ArrowLeft" || e.key === "ArrowDown") next = Math.min(KEY_ORDER.length - 1, i + 1);
    else if (e.key === "ArrowRight" || e.key === "ArrowUp") next = Math.max(0, i < 0 ? 0 : i - 1);
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = KEY_ORDER.length - 1;
    else if (e.key === "Escape") { setActive(null); return; }
    else if (e.key === "Enter" && active) { onSelect?.(active, values.get(active) ?? null); return; }
    if (next !== null) { e.preventDefault(); setActive(KEY_ORDER[next]); }
  }

  const legend = (
    <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
      <div className="flex items-center gap-1.5">
        <span>{format(min)}</span>
        <span className="flex overflow-hidden rounded-[3px]">{Array.from({ length: steps }, (_, k) => <span key={k} className="h-2.5 w-6" style={{ background: shade(k) }} />)}</span>
        <span>{format(max)}</span>
        {unit && <span>{unit}</span>}
      </div>
      <span className="flex items-center gap-1.5"><span aria-hidden className="size-2.5 rounded-[3px] border border-border" style={{ backgroundImage: "repeating-linear-gradient(45deg, var(--border) 0 2px, transparent 2px 5px)" }} />بدون داده</span>
    </div>
  );

  return (
    <ChartFrame
      title={title}
      description={description}
      height={0}
      autoHeight={(w) => (w / COLS) * ROWS * 0.82}
      className={className}
      empty={data.length === 0}
      keyboard={{ onKeyDown, onBlur: () => setActive(null) }}
      onPointerLeave={() => setActive(null)}
      legend={legend}
      legendPosition="bottom"
      announce={active ? announceRows(active, rows(active)) : ""}
      table={{ head: ["استان", unit ?? "مقدار", "سهم از کل"], rows: Object.keys(IRAN_TILES).map((p) => { const v = values.get(p); return [p, v === undefined ? "—" : format(v), v === undefined ? "—" : percentFa((v / (total || 1)) * 100, 1)]; }) }}
    >
      {(width) => {
        const gap = Math.max(3, width * 0.008);
        const cellW = (width - gap * (COLS - 1)) / COLS;
        const cellH = cellW * 0.82 - gap * 0.18;
        const narrow = cellW < 92;
        const pos = (name: string) => { const [c, r] = IRAN_TILES[name]; return { left: c * (cellW + gap), top: r * (cellH + gap) }; };
        return (
          <>
            {/* The map keeps compass order (east on the right) whatever the page direction. */}
            <div dir="ltr" className="absolute inset-0" aria-hidden>
              {Object.keys(IRAN_TILES).map((name) => {
                const v = values.get(name);
                const k = v === undefined ? -1 : step(v);
                const on = active === name;
                const dark = k >= Math.ceil(steps / 2);
                const { left, top } = pos(name);
                return (
                  <div
                    key={name}
                    onPointerEnter={() => setActive(name)}
                    onClick={() => onSelect?.(name, v ?? null)}
                    dir="rtl"
                    className={cn("vf-mark absolute flex flex-col items-center justify-center rounded-md border px-1 text-center leading-tight transition-[opacity,box-shadow]", onSelect && "cursor-pointer", on ? "z-10 border-foreground shadow-[0_0_0_1px_var(--foreground)]" : "border-transparent", active && !on && "opacity-60")}
                    style={{ left, top, width: cellW, height: cellH, background: k < 0 ? "repeating-linear-gradient(45deg, var(--border) 0 2px, transparent 2px 6px)" : shade(k), color: dark ? "var(--primary-foreground, white)" : "var(--foreground)" }}
                  >
                    <span className="truncate font-medium" style={{ fontSize: narrow ? 10 : 12, maxWidth: "100%" }}>{narrow ? IRAN_SHORT[name] ?? name : name}</span>
                    {v !== undefined && cellH > 38 && <span className="mt-0.5 tabular-nums opacity-80" style={{ fontSize: narrow ? 9 : 11 }}>{format(v)}</span>}
                  </div>
                );
              })}
            </div>
            {active && <ChartTooltip width={width} state={{ x: pos(active).left + cellW / 2, y: pos(active).top + cellH / 2, title: active, rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

/** Edges of each legend step, for building your own legend or a table. */
export function iranMapSteps(values: number[], steps = 5) {
  const min = Math.min(...values), max = Math.max(...values);
  return Array.from({ length: steps + 1 }, (_, i) => min + ((max - min) * i) / steps);
}

"use client";

import * as React from "react";
import { fullFa, percentFa, textWidth } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type FunnelStep = { label: string; value: number };

export interface FunnelChartProps {
  data: FunnelStep[];
  title: string;
  description?: string;
  format?: ValueFormat;
  /** Row height in px. */
  row?: number;
  color?: string;
  /** "centered" funnel or "aligned" bars that start from the label edge. */
  shape?: "centered" | "aligned";
  animate?: boolean;
  onSelect?: (step: FunnelStep, index: number) => void;
  className?: string;
}

/**
 * نمودار قیف. Conversion through steps (visit → cart → pay). Each row shows its
 * count and share of the first step, and the gap between rows shows the
 * step-to-step conversion and drop-off.
 */
export function FunnelChart({ data, title, description, format = (n) => fullFa(n), row = 44, color = colorAt(0), shape = "centered", animate = true, onSelect, className }: FunnelChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const first = data[0]?.value || 1;
  const conv = (i: number) => (i === 0 ? 100 : (data[i].value / (data[i - 1].value || 1)) * 100);
  const rows = (i: number) => [
    { key: "v", label: "تعداد", value: format(data[i].value) },
    { key: "a", label: "از مرحله‌ی اول", value: percentFa((data[i].value / first) * 100, 1) },
    ...(i > 0 ? [{ key: "c", label: "از مرحله‌ی قبل", value: percentFa(conv(i), 1) }, { key: "d", label: "ریزش", value: format(data[i - 1].value - data[i].value) }] : []),
  ];
  const gapH = 18;
  const h = data.length * row + (data.length - 1) * gapH;

  return (
    <ChartFrame
      title={title}
      description={description}
      height={h}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(data[active].label, rows(active)) : ""}
      table={{ head: ["مرحله", "تعداد", "از مرحله‌ی اول", "از مرحله‌ی قبل"], rows: data.map((d, i) => [d.label, format(d.value), percentFa((d.value / first) * 100, 1), i ? percentFa(conv(i), 1) : "—"]) }}
    >
      {(width) => {
        const labelW = Math.min(width * 0.3, Math.max(...data.map((d) => textWidth(d.label, 12))) + 14);
        const valueW = Math.min(width * 0.25, Math.max(...data.map((d) => textWidth(format(d.value), 12))) + 50);
        const right = width - labelW, left = valueW;
        const span = right - left;
        const y = (i: number) => i * (row + gapH);
        const wOf = (v: number) => Math.max(4, (v / first) * span);
        const xOf = (v: number) => (shape === "centered" ? left + (span - wOf(v)) / 2 : right - wOf(v));
        return (
          <>
            <svg width={width} height={h} className="block overflow-visible" aria-hidden>
              {data.map((d, i) => {
                const on = active === i;
                const x0 = xOf(d.value), w = wOf(d.value);
                const next = data[i + 1];
                return (
                  <g key={i} onPointerEnter={() => kb.setActive(i)} onClick={() => onSelect?.(d, i)} style={{ cursor: onSelect ? "pointer" : undefined }}>
                    <rect x={0} y={y(i)} width={width} height={row} fill={on ? "var(--foreground)" : "transparent"} fillOpacity={0.04} rx={6} />
                    <rect
                      x={x0}
                      y={y(i)}
                      width={w}
                      height={row}
                      rx={6}
                      fill={color}
                      fillOpacity={1 - (i / Math.max(1, data.length)) * 0.55}
                      className={animate ? "vf-grow" : undefined}
                      style={animate ? ({ transformOrigin: shape === "centered" ? "center" : "right", "--vf-sx": 0, "--vf-sy": 1 } as React.CSSProperties) : undefined}
                    />
                    {next && (
                      <path
                        d={`M${x0},${y(i) + row} L${x0 + w},${y(i) + row} L${xOf(next.value) + wOf(next.value)},${y(i + 1)} L${xOf(next.value)},${y(i + 1)} Z`}
                        fill={color}
                        fillOpacity={0.12}
                      />
                    )}
                    <Label anchor="right" x={width - 2} y={y(i) + row / 2} dy="0.35em" size={12} muted={!on} fontWeight={on ? 600 : undefined}>
                      {d.label}
                    </Label>
                    <Label anchor="left" x={2} y={y(i) + row / 2 - 7} dy="0.35em" size={12} muted={false} fontWeight={600}>
                      {format(d.value)}
                    </Label>
                    <Label anchor="left" x={2} y={y(i) + row / 2 + 9} dy="0.35em" size={10}>
                      {percentFa((d.value / first) * 100, 1)}
                    </Label>
                    {next && (
                      <Label x={left + span / 2} y={y(i) + row + gapH / 2} dy="0.35em" size={10} muted={false}>
                        {`↓ ${percentFa(conv(i + 1), 1)}`}
                      </Label>
                    )}
                  </g>
                );
              })}
            </svg>
            {active !== null && <ChartTooltip width={width} state={{ x: xOf(data[active].value), y: y(active) + row / 2, title: data[active].label, rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { fullFa, percentFa, textWidth } from "@/lib/chart-utils";
import { ChartFrame, ChartTooltip, Label, announceRows, colorAt, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type SankeyNode = { id: string; label: string; color?: string };
export type SankeyLink = { source: string; target: string; value: number };

export interface SankeyChartProps {
  nodes: SankeyNode[];
  links: SankeyLink[];
  title: string;
  description?: string;
  height?: number;
  format?: ValueFormat;
  /** Node bar thickness in px. */
  nodeWidth?: number;
  /** Vertical gap between nodes in a column. */
  nodePadding?: number;
  animate?: boolean;
  className?: string;
}

type Placed = SankeyNode & { col: number; value: number; x: number; y: number; h: number; color: string; inOff: number; outOff: number };
type Band = SankeyLink & { from: Placed; to: Placed; y0: number; y1: number; w: number };

/** Column of each node: its longest distance from a source. Cycles are cut at the first repeat. */
function columns(nodes: SankeyNode[], links: SankeyLink[]) {
  const col = new Map(nodes.map((n) => [n.id, 0]));
  for (let pass = 0; pass < nodes.length; pass++) {
    let changed = false;
    for (const l of links) {
      const next = (col.get(l.source) ?? 0) + 1;
      if (next > (col.get(l.target) ?? 0) && next < nodes.length) { col.set(l.target, next); changed = true; }
    }
    if (!changed) break;
  }
  return col;
}

/**
 * نمودار سنکی. Flow between stages (traffic source → page → outcome, budget → department
 * → expense). Sources sit on the right and the flow runs leftward, like the text.
 * Band width is proportional to the value.
 */
export function SankeyChart({ nodes, links, title, description, height = 320, format = (n) => fullFa(n), nodeWidth = 12, nodePadding = 14, animate = true, className }: SankeyChartProps) {
  const valid = links.filter((l) => l.value > 0 && nodes.some((n) => n.id === l.source) && nodes.some((n) => n.id === l.target));
  const kb = useActive(valid.length);
  const active = kb.active;
  const total = (id: string) => Math.max(valid.filter((l) => l.source === id).reduce((s, l) => s + l.value, 0), valid.filter((l) => l.target === id).reduce((s, l) => s + l.value, 0));
  const label = (id: string) => nodes.find((n) => n.id === id)?.label ?? id;
  const rows = (i: number) => {
    const l = valid[i];
    return [
      { key: "v", label: "مقدار", value: format(l.value) },
      { key: "s", label: `از کل ${label(l.source)}`, value: percentFa((l.value / (total(l.source) || 1)) * 100, 1) },
    ];
  };

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={valid.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(`${label(valid[active].source)} به ${label(valid[active].target)}`, rows(active)) : ""}
      table={{ head: ["از", "به", "مقدار"], rows: valid.map((l) => [label(l.source), label(l.target), format(l.value)]) }}
    >
      {(width) => {
        const col = columns(nodes, valid);
        const cols = Math.max(...col.values()) + 1;
        const labelW = Math.min(width * 0.22, Math.max(...nodes.map((n) => textWidth(n.label, 11))) + 10);
        // Labels of the first column sit right of their bars, all others left, so inset both edges.
        const innerRight = width - labelW;
        const innerLeft = labelW;
        const xOf = (c: number) => (cols === 1 ? innerRight - nodeWidth : innerRight - nodeWidth - (c / (cols - 1)) * (innerRight - innerLeft - nodeWidth));

        const byCol: Placed[][] = Array.from({ length: cols }, () => []);
        nodes.forEach((n, i) => {
          const v = total(n.id);
          if (!v) return;
          const c = col.get(n.id) ?? 0;
          byCol[c].push({ ...n, col: c, value: v, x: xOf(c), y: 0, h: 0, color: n.color ?? colorAt(i), inOff: 0, outOff: 0 });
        });
        const scale = Math.min(...byCol.filter((c) => c.length).map((c) => (height - nodePadding * (c.length - 1)) / c.reduce((s, n) => s + n.value, 0)));
        for (const list of byCol) {
          const used = list.reduce((s, n) => s + n.value * scale, 0) + nodePadding * (list.length - 1);
          let y = (height - used) / 2;
          for (const n of list) { n.h = Math.max(1, n.value * scale); n.y = y; y += n.h + nodePadding; }
        }
        const placed = new Map(byCol.flat().map((n) => [n.id, n]));
        const bands: Band[] = [];
        // Keep bands in the order of their far end so they do not cross needlessly.
        const order = [...valid].map((l, i) => ({ l, i })).sort((a, b) => (placed.get(a.l.target)?.y ?? 0) - (placed.get(b.l.target)?.y ?? 0));
        const tmp = new Map<number, Band>();
        for (const { l, i } of order) {
          const from = placed.get(l.source), to = placed.get(l.target);
          if (!from || !to) continue;
          const w = l.value * scale;
          tmp.set(i, { ...l, from, to, w, y0: from.y + from.outOff + w / 2, y1: 0 });
          from.outOff += w;
        }
        const order2 = [...tmp.entries()].sort((a, b) => a[1].from.y - b[1].from.y);
        for (const [, b] of order2) { b.y1 = b.to.y + b.to.inOff + b.w / 2; b.to.inOff += b.w; }
        valid.forEach((_, i) => { const b = tmp.get(i); if (b) bands[i] = b; });

        const path = (b: Band) => {
          const x0 = b.from.x, x1 = b.to.x + nodeWidth;
          const mid = (x0 + x1) / 2;
          return `M${x0},${b.y0} C${mid},${b.y0} ${mid},${b.y1} ${x1},${b.y1}`;
        };
        const tip = active !== null && bands[active] ? bands[active] : null;

        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <g fill="none">
                {bands.map((b, i) => b && (
                  <path
                    key={i}
                    d={path(b)}
                    stroke={b.from.color}
                    strokeOpacity={active === null ? 0.32 : active === i ? 0.6 : 0.1}
                    strokeWidth={Math.max(1, b.w)}
                    onPointerEnter={() => kb.setActive(i)}
                    className={animate ? "vf-mark vf-fade" : "vf-mark"}
                  />
                ))}
              </g>
              {[...placed.values()].map((n) => (
                <g key={n.id}>
                  <rect x={n.x} y={n.y} width={nodeWidth} height={n.h} rx={2} fill={n.color} />
                  {/* Sources label on their right edge; every other column labels to the left of its bar. */}
                  <Label anchor="right" x={n.col === 0 ? width - 2 : n.x - 6} y={n.y + n.h / 2 - (n.h > 26 ? 6 : 0)} dy="0.35em" muted={false} fontWeight={500}>{n.label}</Label>
                  {n.h > 26 && <Label anchor="right" x={n.col === 0 ? width - 2 : n.x - 6} y={n.y + n.h / 2 + 8} dy="0.35em" size={10}>{format(n.value)}</Label>}
                </g>
              ))}
            </svg>
            {tip && <ChartTooltip width={width} state={{ x: (tip.from.x + tip.to.x + nodeWidth) / 2, y: (tip.y0 + tip.y1) / 2, title: `${tip.from.label} ← ${tip.to.label}`, rows: rows(active!) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { bandScale, compactFa, fullFa, labelStride, linearScale, roundedRect, textWidth } from "@/lib/chart-utils";
import { CategoryAxis, ChartFrame, ChartTooltip, Label, Legend, ValueGrid, announceRows, plotBox, useActive, valueTicks, type ValueFormat } from "@/components/charts/chart-core";

export type WaterfallStep = {
  label: string;
  /** Change for normal steps; ignored for totals. */
  value: number;
  /** Draw the running total here (e.g. «سود ناخالص») instead of a change. */
  total?: boolean;
};

export interface WaterfallChartProps {
  data: WaterfallStep[];
  title: string;
  description?: string;
  height?: number;
  format?: ValueFormat;
  axisFormat?: ValueFormat;
  /** Value printed above or below each bar. */
  showValues?: boolean;
  colors?: { up?: string; down?: string; total?: string };
  legend?: boolean;
  animate?: boolean;
  className?: string;
}

/**
 * نمودار آبشاری. How a starting amount turns into a final one: rises in green,
 * falls in red, totals in the neutral colour, joined by dashed connectors.
 * Steps run right to left like a Persian income statement.
 */
export function WaterfallChart({
  data,
  title,
  description,
  height = 280,
  format = (n) => fullFa(n),
  axisFormat = compactFa,
  showValues = true,
  colors,
  legend = true,
  animate = true,
  className,
}: WaterfallChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const up = colors?.up ?? "var(--success)", down = colors?.down ?? "var(--destructive)", tot = colors?.total ?? "var(--chart-1, var(--brand))";

  const bars = React.useMemo(() => {
    const out: { from: number; to: number; kind: "up" | "down" | "total"; delta: number }[] = [];
    for (const d of data) {
      const run = out.length ? out[out.length - 1].to : 0;
      if (d.total) out.push({ from: 0, to: run, kind: "total", delta: run });
      else out.push({ from: run, to: run + d.value, kind: d.value >= 0 ? "up" : "down", delta: d.value });
    }
    return out;
  }, [data]);
  const { domain, ticks } = valueTicks(bars.flatMap((b) => [b.from, b.to]), "zero", height);
  const colorOf = (k: "up" | "down" | "total") => (k === "up" ? up : k === "down" ? down : tot);
  const sign = (b: (typeof bars)[number]) => (b.kind === "total" ? format(b.to) : `${b.delta >= 0 ? "+" : "−"}${format(Math.abs(b.delta))}`);
  const rows = (i: number) => [
    { key: "d", label: bars[i].kind === "total" ? "جمع" : "تغییر", value: sign(bars[i]), color: colorOf(bars[i].kind) },
    ...(bars[i].kind !== "total" ? [{ key: "r", label: "مانده", value: format(bars[i].to) }] : []),
  ];
  const labels = data.map((d) => d.label);

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rows(active)) : ""}
      legend={
        legend ? (
          <Legend
            items={[
              { key: "up", label: "افزایش", color: up },
              { key: "down", label: "کاهش", color: down },
              { key: "total", label: "جمع", color: tot },
            ]}
          />
        ) : undefined
      }
      table={{ head: ["", "تغییر", "مانده"], rows: data.map((d, i) => [d.label, sign(bars[i]), format(bars[i].to)]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: ticks.map(axisFormat), top: showValues ? 20 : 10 });
        const bs = bandScale(data.length, box.left, box.right, 0.28);
        const y = linearScale(domain, [box.bottom, box.top]);
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 8);
        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <ValueGrid box={box} ticks={ticks} y={y} format={axisFormat} />
              {bars.map((b, i) => {
                const top = y(Math.max(b.from, b.to)), bottom = y(Math.min(b.from, b.to));
                const on = active === i;
                const next = bars[i + 1];
                return (
                  <g key={i} onPointerEnter={() => kb.setActive(i)}>
                    <rect x={bs.x(i) - (bs.step - bs.band) / 2} y={box.top} width={bs.step} height={box.bottom - box.top} fill={on ? "var(--foreground)" : "transparent"} fillOpacity={0.05} rx={4} />
                    <path
                      d={roundedRect(bs.x(i), top, bs.band, Math.max(1, bottom - top), 3, { tl: true, tr: true, bl: true, br: true })}
                      fill={colorOf(b.kind)}
                      fillOpacity={b.kind === "total" ? 1 : 0.85}
                      className={animate ? "vf-fade" : undefined}
                    />
                    {next && <line x1={bs.x(i)} x2={bs.x(i + 1) + bs.band} y1={y(b.to)} y2={y(b.to)} stroke="var(--muted-foreground)" strokeDasharray="3 3" strokeOpacity={0.7} />}
                    {showValues && (
                      <Label x={bs.center(i)} y={b.kind !== "down" ? top - 6 : bottom + 13} size={10} muted={false} fill={b.kind === "total" ? "var(--foreground)" : colorOf(b.kind)}>
                        {b.kind === "total" ? axisFormat(b.to) : `${b.delta >= 0 ? "+" : "−"}${axisFormat(Math.abs(b.delta))}`}
                      </Label>
                    )}
                  </g>
                );
              })}
              <CategoryAxis box={box} labels={labels} x={bs.center} stride={stride} highlight={active} />
            </svg>
            {active !== null && <ChartTooltip width={width} state={{ x: bs.center(active), y: y(Math.max(bars[active].from, bars[active].to)), title: labels[active], rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { bandScale, compactFa, fullFa, labelStride, linePath, linearScale, niceTicks, percentFa, segments, textWidth } from "@/lib/chart-utils";
import { CategoryAxis, ChartFrame, ChartTooltip, Legend, ValueGrid, announceRows, colorAt, defaultLabel, plotBox, pointerX, useActive, type ValueFormat } from "@/components/charts/chart-core";

export type Candle = { date: Date | string; open: number; high: number; low: number; close: number; volume?: number };

export interface CandlestickChartProps {
  data: Candle[];
  title: string;
  description?: string;
  height?: number;
  /** Price format for the tooltip; default full Persian number. */
  format?: ValueFormat;
  axisFormat?: ValueFormat;
  xFormat?: (value: unknown, index: number) => string;
  /** Moving averages to overlay, in candles, e.g. [7, 21]. */
  movingAverages?: number[];
  /** Volume bars under the candles when the data has `volume`. */
  volume?: boolean;
  colors?: { up?: string; down?: string };
  animate?: boolean;
  className?: string;
}

function sma(values: number[], n: number) {
  return values.map((_, i) => (i + 1 < n ? null : values.slice(i + 1 - n, i + 1).reduce((a, b) => a + b, 0) / n));
}

/**
 * نمودار شمعی. Daily prices like the Tehran exchange: green when the close is
 * above the open, red when below, newest candle on the left, optional volume
 * and moving averages.
 */
export function CandlestickChart({
  data,
  title,
  description,
  height = 320,
  format = (n) => fullFa(n),
  axisFormat = compactFa,
  xFormat = defaultLabel,
  movingAverages = [],
  volume = true,
  colors,
  animate = true,
  className,
}: CandlestickChartProps) {
  const kb = useActive(data.length);
  const active = kb.active;
  const up = colors?.up ?? "var(--success)", down = colors?.down ?? "var(--destructive)";
  const hasVol = volume && data.some((d) => d.volume);
  const closes = data.map((d) => d.close);
  // Blue and purple slots, so averages never read as the green/red candle colours.
  const mas = movingAverages.map((n, k) => ({ n, values: sma(closes, n), color: colorAt([1, 4, 5, 6][k % 4]) }));
  const lo = Math.min(...data.map((d) => d.low)), hi = Math.max(...data.map((d) => d.high));
  const { domain, ticks } = niceTicks(lo - (hi - lo) * 0.04, hi + (hi - lo) * 0.04, Math.max(3, Math.floor((height - 60) / 50)));
  const labels = data.map((d, i) => xFormat(typeof d.date === "string" ? new Date(d.date) : d.date, i));
  const vMax = Math.max(1, ...data.map((d) => d.volume ?? 0));

  const rows = (i: number) => {
    const d = data[i];
    const prev = data[i - 1]?.close ?? d.open;
    const ch = ((d.close - prev) / (prev || 1)) * 100;
    return [
      { key: "o", label: "باز شدن", value: format(d.open) },
      { key: "h", label: "بیشترین", value: format(d.high) },
      { key: "l", label: "کمترین", value: format(d.low) },
      { key: "c", label: "پایانی", value: format(d.close), color: d.close >= d.open ? up : down },
      { key: "p", label: "تغییر", value: `${ch >= 0 ? "+" : "−"}${percentFa(Math.abs(ch), 2)}` },
      ...(d.volume ? [{ key: "v", label: "حجم", value: compactFa(d.volume) }] : []),
    ];
  };

  return (
    <ChartFrame
      title={title}
      description={description}
      height={height}
      className={className}
      empty={data.length === 0}
      keyboard={kb}
      onPointerLeave={() => kb.setActive(null)}
      announce={active !== null ? announceRows(labels[active], rows(active)) : ""}
      legend={
        mas.length ? (
          <Legend
            items={[
              { key: "up", label: "مثبت", color: up },
              { key: "down", label: "منفی", color: down },
              ...mas.map((m) => ({ key: `ma${m.n}`, label: `میانگین ${fullFa(m.n)} روزه`, color: m.color, dashed: true })),
            ]}
          />
        ) : undefined
      }
      table={{ head: ["", "باز شدن", "بیشترین", "کمترین", "پایانی"], rows: data.map((d, i) => [labels[i], format(d.open), format(d.high), format(d.low), format(d.close)]) }}
    >
      {(width) => {
        const box = plotBox(width, height, { yLabels: ticks.map(axisFormat) });
        const volH = hasVol ? Math.round((box.bottom - box.top) * 0.18) : 0;
        const priceBottom = box.bottom - volH - (hasVol ? 6 : 0);
        const bs = bandScale(data.length, box.left, box.right, data.length > 60 ? 0.2 : 0.35);
        const y = linearScale(domain, [priceBottom, box.top]);
        const yv = linearScale([0, vMax], [box.bottom, box.bottom - volH]);
        const priceBox = { ...box, bottom: priceBottom };
        const stride = labelStride(data.length, box.right - box.left, Math.max(0, ...labels.map((l) => textWidth(l))) + 10);
        return (
          <>
            <svg width={width} height={height} className="block overflow-visible" aria-hidden>
              <ValueGrid box={priceBox} ticks={ticks} y={y} format={axisFormat} />
              {active !== null && <rect x={bs.x(active) - (bs.step - bs.band) / 2} y={box.top} width={bs.step} height={box.bottom - box.top} fill="var(--foreground)" fillOpacity={0.06} />}
              <g className={animate ? "vf-fade" : undefined}>
                {data.map((d, i) => {
                  const c = d.close >= d.open ? up : down;
                  const cx = bs.center(i);
                  const top = y(Math.max(d.open, d.close)), bottom = y(Math.min(d.open, d.close));
                  return (
                    <g key={i}>
                      {hasVol && d.volume ? <rect x={bs.x(i)} y={yv(d.volume)} width={bs.band} height={box.bottom - yv(d.volume)} fill={c} fillOpacity={0.3} /> : null}
                      <line x1={cx} x2={cx} y1={y(d.high)} y2={y(d.low)} stroke={c} strokeWidth={1} />
                      <rect x={bs.x(i)} y={top} width={bs.band} height={Math.max(1, bottom - top)} fill={c} rx={Math.min(1.5, bs.band / 4)} />
                    </g>
                  );
                })}
              </g>
              {mas.map((m) =>
                segments(m.values, bs.center, y).map((seg, j) => (
                  <path key={`${m.n}-${j}`} d={linePath(seg.pts, "monotone")} fill="none" stroke={m.color} strokeWidth={1.5} strokeDasharray="4 3" />
                )),
              )}
              {active !== null && <line x1={box.left} x2={box.right} y1={y(data[active].close)} y2={y(data[active].close)} stroke="var(--foreground)" strokeOpacity={0.35} strokeDasharray="2 3" />}
              <CategoryAxis box={box} labels={labels} x={bs.center} stride={stride} highlight={active} />
              <rect
                x={box.left}
                y={box.top}
                width={Math.max(0, box.right - box.left)}
                height={Math.max(0, box.bottom - box.top)}
                fill="transparent"
                style={{ cursor: "crosshair" }}
                onPointerMove={(e) => kb.setActive(bs.index(pointerX(e).x))}
              />
            </svg>
            {active !== null && <ChartTooltip width={width} state={{ x: bs.center(active), y: y(data[active].high), title: labels[active], rows: rows(active) }} />}
          </>
        );
      }}
    </ChartFrame>
  );
}

"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, JALALI_WEEKDAYS_SHORT, jalaliMonthLength, jalaliWeekday, toGregorian, toJalali } from "@/lib/jalali";
import { HIJRI_MONTHS, toHijri } from "@/lib/hijri";
import { iranOccasions, type Occasion, type OccasionProvider } from "@/lib/iran-holidays";
import { addDays, addJalaliMonths, dayKey, eventColor, formatTimeRange, fromKey, startOfJalaliWeek, TEHRAN, type CalendarEvent } from "@/lib/calendar-utils";

/* ---------- context ---------- */

export type CalendarView = "month" | "week" | "day" | "agenda";
/** Second date shown under each Jalali day. */
export type Secondary = "hijri" | "gregorian" | null;

export type CalendarSettings = {
  /** IANA zone used to place timed events. Default Asia/Tehran. */
  timeZone: string;
  /** Holiday and occasion lookup; null hides them. */
  occasions: OccasionProvider | null;
  secondary: Secondary;
  /** Weekdays off, 0 = شنبه … 6 = جمعه. */
  weekend: number[];
};

const Ctx = React.createContext<CalendarSettings>({ timeZone: TEHRAN, occasions: iranOccasions, secondary: "hijri", weekend: [6] });

export interface CalendarProviderProps extends Partial<Omit<CalendarSettings, "occasions">> {
  /** Built-in Iranian holidays by default; pass your own provider, or false to hide them. */
  occasions?: OccasionProvider | false;
  children: React.ReactNode;
}

/**
 * Shared settings for every calendar view below it: time zone, holidays,
 * the secondary date and the weekend. Every view also works without it.
 */
export function CalendarProvider({ timeZone = TEHRAN, occasions = iranOccasions, secondary = "hijri", weekend = [6], children }: CalendarProviderProps) {
  const weekendKey = weekend.join(",");
  const value = React.useMemo(
    () => ({ timeZone, occasions: occasions || null, secondary, weekend: weekendKey ? weekendKey.split(",").map(Number) : [] }),
    [timeZone, occasions, secondary, weekendKey],
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useCalendar() {
  return React.useContext(Ctx);
}

/** Today as a local calendar day, fixed for the life of the component. */
export function useToday() {
  const [today] = React.useState(() => {
    const n = new Date();
    return new Date(n.getFullYear(), n.getMonth(), n.getDate());
  });
  return today;
}

const subscribeMinute = (cb: () => void) => {
  const id = setInterval(cb, 30_000);
  return () => clearInterval(id);
};
const minuteSnapshot = () => Math.floor(Date.now() / 60_000);
const noMinute = () => null;

/** The current minute, updated every 30 seconds. Null during server render so "now" lines never mismatch. */
export function useNow() {
  const m = React.useSyncExternalStore(subscribeMinute, minuteSnapshot, noMinute);
  return React.useMemo(() => (m === null ? null : new Date(m * 60_000)), [m]);
}

/** Controlled or uncontrolled state with one setter. */
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (v: T) => void): [T, (v: T) => void] {
  const [internal, setInternal] = React.useState(defaultValue);
  const current = value === undefined ? internal : value;
  const set = React.useCallback(
    (v: T) => {
      if (value === undefined) setInternal(v);
      onChange?.(v);
    },
    [value, onChange],
  );
  return [current, set];
}

/* ---------- day facts ---------- */

export type DayInfo = {
  key: string;
  date: Date;
  isToday: boolean;
  isWeekend: boolean;
  occasions: Occasion[];
  holiday: Occasion | undefined;
  /** Accessible name: «چهارشنبه ۲۳ مهر ۱۴۰۵، تعطیل: …». */
  label: string;
};

export function dayInfo(date: Date, settings: CalendarSettings, today: Date): DayInfo {
  const key = dayKey(date);
  const occasions = settings.occasions?.(key) ?? [];
  const holiday = occasions.find((o) => o.holiday);
  const { jy, jm, jd } = toJalali(date);
  const isToday = key === dayKey(today);
  let label = `${JALALI_WEEKDAYS[jalaliWeekday(date)]} ${fa(jd)} ${JALALI_MONTHS[jm - 1]} ${fa(jy)}`;
  if (isToday) label += "، امروز";
  if (holiday) label += `، تعطیل: ${occasions.filter((o) => o.holiday).map((o) => o.title).join("، ")}`;
  return { key, date, isToday, isWeekend: settings.weekend.includes(jalaliWeekday(date)), occasions, holiday, label };
}

export function useDayInfo(date: Date) {
  const settings = useCalendar();
  const today = useToday();
  return dayInfo(date, settings, today);
}

const GREGORIAN_MONTHS = ["ژانویه", "فوریه", "مارس", "آوریل", "مه", "ژوئن", "ژوئیه", "اوت", "سپتامبر", "اکتبر", "نوامبر", "دسامبر"];

/** Small second date for a day cell: Hijri or Gregorian day in Persian digits. */
export function secondaryDay(date: Date, secondary: Secondary) {
  if (secondary === "hijri") return fa(toHijri(date).hd);
  if (secondary === "gregorian") return fa(date.getDate());
  return null;
}

/** Second title line for a Jalali month: «ربیع‌الثانی – جمادی‌الاول ۱۴۴۸» or «سپتامبر – اکتبر ۲۰۲۶». */
export function secondaryMonthTitle(jy: number, jm: number, secondary: Secondary) {
  if (!secondary) return null;
  const a = toGregorian(jy, jm, 1);
  const b = toGregorian(jy, jm, jalaliMonthLength(jy, jm));
  if (secondary === "gregorian") {
    const ma = GREGORIAN_MONTHS[a.getMonth()];
    const mb = GREGORIAN_MONTHS[b.getMonth()];
    return `${ma === mb ? ma : `${ma} – ${mb}`} ${fa(b.getFullYear())}`;
  }
  const ha = toHijri(a);
  const hb = toHijri(b);
  const names = ha.hm === hb.hm ? HIJRI_MONTHS[ha.hm - 1] : `${HIJRI_MONTHS[ha.hm - 1]} – ${HIJRI_MONTHS[hb.hm - 1]}`;
  return `${names} ${fa(hb.hy)}${ha.approximate || hb.approximate ? " (تقریبی)" : ""}`;
}

/* ---------- toolbar ---------- */

export interface CalendarToolbarProps {
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  onPrev: () => void;
  onNext: () => void;
  onToday?: () => void;
  prevLabel?: string;
  nextLabel?: string;
  /** Extra controls on the far side, e.g. a view switcher. */
  children?: React.ReactNode;
  className?: string;
}

/** Title, «امروز» and previous/next. Previous points right because time runs right to left. */
export function CalendarToolbar({ title, subtitle, onPrev, onNext, onToday, prevLabel = "قبلی", nextLabel = "بعدی", children, className }: CalendarToolbarProps) {
  const nav = "flex size-8 cursor-pointer items-center justify-center rounded-control text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring";
  return (
    <div className={cn("flex flex-wrap items-center gap-x-3 gap-y-2", className)}>
      <div className="flex items-center gap-1">
        <button type="button" aria-label={prevLabel} onClick={onPrev} className={nav}>
          <ChevronRight className="size-4" />
        </button>
        <button type="button" aria-label={nextLabel} onClick={onNext} className={nav}>
          <ChevronLeft className="size-4" />
        </button>
        {onToday && (
          <button type="button" onClick={onToday} className="h-8 cursor-pointer rounded-control border border-border px-3 text-xs font-medium transition-colors hover:bg-accent">
            امروز
          </button>
        )}
      </div>
      <div className="min-w-0" aria-live="polite">
        <p className="truncate font-display text-base font-bold">{title}</p>
        {subtitle && <p className="truncate text-[11px] text-muted-foreground">{subtitle}</p>}
      </div>
      {children && <div className="ms-auto flex items-center gap-2">{children}</div>}
    </div>
  );
}

/* ---------- day pieces ---------- */

/** شنبه … جمعه header row; the weekend is muted. */
export function WeekdayHeader({ short, className }: { short?: boolean; className?: string }) {
  const { weekend } = useCalendar();
  return (
    <div className={cn("grid grid-cols-7 text-center text-[11px] text-muted-foreground", className)} aria-hidden>
      {(short ? JALALI_WEEKDAYS_SHORT : JALALI_WEEKDAYS).map((d, i) => (
        <span key={d} className={cn("py-1.5", weekend.includes(i) && "text-destructive/80")}>
          {d}
        </span>
      ))}
    </div>
  );
}

export interface DayNumberProps {
  info: DayInfo;
  /** Dim days that belong to the neighbouring month. */
  outside?: boolean;
  selected?: boolean;
  size?: "sm" | "md";
  className?: string;
}

/**
 * The Jalali day number with its states: today is a ring, selected is filled,
 * holidays and the weekend are red and also carry a dot so color is not the
 * only cue. The secondary date sits under it.
 */
export function DayNumber({ info, outside, selected, size = "md", className }: DayNumberProps) {
  const { secondary } = useCalendar();
  const off = !!info.holiday || info.isWeekend;
  const second = secondaryDay(info.date, secondary);
  const approx = info.occasions.some((o) => o.approximate);
  return (
    <span className={cn("inline-flex flex-col items-center leading-none", outside && "opacity-40", className)}>
      <span
        className={cn(
          "relative flex items-center justify-center rounded-full tabular-nums",
          size === "sm" ? "size-6 text-[11px]" : "size-7 text-sm",
          selected ? "bg-primary font-bold text-primary-foreground" : info.isToday ? "font-bold ring-2 ring-inset ring-foreground/70" : "",
          !selected && off && "text-destructive",
        )}
      >
        {fa(toJalali(info.date).jd)}
        {info.holiday && <span aria-hidden className="absolute -bottom-0.5 size-1 rounded-full bg-destructive" />}
      </span>
      {second && size === "md" && (
        <span className={cn("mt-0.5 text-[9px] tabular-nums text-muted-foreground", approx && "italic")}>{second}</span>
      )}
    </span>
  );
}

/** First holiday or occasion name of a day, clipped to one line. */
export function OccasionLine({ info, className }: { info: DayInfo; className?: string }) {
  const o = info.holiday ?? info.occasions[0];
  if (!o) return null;
  return (
    <span title={info.occasions.map((x) => x.title + (x.approximate ? " (تقریبی)" : "")).join("، ")} className={cn("block truncate text-[10px] leading-4", o.holiday ? "text-destructive" : "text-muted-foreground", className)}>
      {o.title}
      {o.approximate && " ؟"}
    </span>
  );
}

/* ---------- events ---------- */

export interface EventChipProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "color"> {
  event: CalendarEvent;
  /** Palette slot when the event has no color. */
  index?: number;
  /** Show «۱۰:۰۰ تا ۱۱:۰۰» under the title. */
  showTime?: boolean;
  timeZone?: string;
  compact?: boolean;
  /** Short text before the title, e.g. the start time. */
  lead?: string;
}

/** A tinted event pill with a colored edge on the start (right) side. */
export function EventChip({ event, index = 0, showTime, timeZone = TEHRAN, compact, lead, className, style, ...props }: EventChipProps) {
  const color = eventColor(event.color, index);
  return (
    <button
      type="button"
      {...props}
      style={{ ...style, "--ev": color } as React.CSSProperties}
      className={cn(
        "flex w-full min-w-0 cursor-pointer flex-col items-start overflow-hidden rounded-control border-s-[3px] border-[var(--ev)] bg-[color-mix(in_oklch,var(--ev)_16%,transparent)] text-start text-foreground transition-colors hover:bg-[color-mix(in_oklch,var(--ev)_26%,transparent)] focus-visible:outline-2 focus-visible:outline-ring",
        compact ? "px-1.5 py-0.5 text-[11px] leading-4" : "px-2 py-1 text-xs",
        className,
      )}
    >
      <span className="w-full truncate font-medium">
        {lead && <span className="me-1 font-normal text-muted-foreground tabular-nums">{lead}</span>}
        {event.title}
      </span>
      {showTime && !event.allDay && <span className="w-full truncate text-[10px] text-muted-foreground tabular-nums">{formatTimeRange(event.start, event.end, timeZone)}</span>}
    </button>
  );
}

/* ---------- keyboard ---------- */

/**
 * Roving focus over day cells marked with `data-key`. ArrowLeft is the next
 * day (it sits to the left in RTL), ArrowRight the previous, Up/Down a week,
 * PageUp/PageDown a month, Home/End the week's شنبه/جمعه.
 */
export function useRovingDays(activeKey: string, onMove?: (key: string) => void) {
  const container = React.useRef<HTMLDivElement>(null);
  const [focusKey, setFocusKey] = React.useState(activeKey);
  const [prev, setPrev] = React.useState(activeKey);
  if (prev !== activeKey) {
    setPrev(activeKey);
    setFocusKey(activeKey);
  }
  const pending = React.useRef(false);
  React.useEffect(() => {
    if (!pending.current) return;
    pending.current = false;
    container.current?.querySelector<HTMLElement>(`[data-key="${focusKey}"]`)?.focus();
  }, [focusKey]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    const d = fromKey(focusKey);
    const next =
      e.key === "ArrowLeft" ? addDays(d, 1)
      : e.key === "ArrowRight" ? addDays(d, -1)
      : e.key === "ArrowDown" ? addDays(d, 7)
      : e.key === "ArrowUp" ? addDays(d, -7)
      : e.key === "PageDown" ? addJalaliMonths(d, 1)
      : e.key === "PageUp" ? addJalaliMonths(d, -1)
      : e.key === "Home" ? startOfJalaliWeek(d)
      : e.key === "End" ? addDays(startOfJalaliWeek(d), 6)
      : null;
    if (!next) return;
    e.preventDefault();
    const k = dayKey(next);
    pending.current = true;
    setFocusKey(k);
    onMove?.(k);
  };
  return { container, focusKey, setFocusKey, onKeyDown };
}

/* ---------- layout helpers ---------- */

/** Width of an element, kept current with ResizeObserver. 0 until mounted. */
export function useWidth<T extends HTMLElement>(): [React.RefObject<T | null>, number] {
  const ref = React.useRef<T>(null);
  const [w, setW] = React.useState(0);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setW(el.clientWidth);
    const ro = new ResizeObserver(([e]) => setW(Math.round(e.contentRect.width)));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, w];
}

/** Screen-reader-only block. Wraps tables in a div so they cannot widen the page. */
export function SrOnly({ children }: { children: React.ReactNode }) {
  return <div className="sr-only">{children}</div>;
}

/** Empty-state line for views with nothing to show. */
export function CalendarEmpty({ children = "رویدادی نیست.", className }: { children?: React.ReactNode; className?: string }) {
  return <p className={cn("rounded-control border border-dashed border-border px-4 py-6 text-center text-sm text-muted-foreground", className)}>{children}</p>;
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_WEEKDAYS, jalaliWeekday, toJalali } from "@/lib/jalali";
import { addDays, addJalaliMonths, monthTitle, shortDay, weekDates, type CalendarEvent } from "@/lib/calendar-utils";
import type { OccasionProvider } from "@/lib/iran-holidays";
import { SegmentedControl } from "@/components/ui/segmented-control";
import { CalendarProvider, CalendarToolbar, secondaryMonthTitle, useControllable, useToday, type CalendarView, type Secondary } from "@/components/calendar/calendar-core";
import { MonthView } from "@/components/calendar/month-view";
import { TimeGrid } from "@/components/calendar/time-grid";
import { AgendaView } from "@/components/calendar/agenda-view";

const VIEW_LABELS: Record<CalendarView, string> = { month: "ماه", week: "هفته", day: "روز", agenda: "فهرست" };
const AGENDA_DAYS = 14;

export interface EventCalendarProps {
  events?: CalendarEvent[];
  view?: CalendarView;
  defaultView?: CalendarView;
  onViewChange?: (view: CalendarView) => void;
  /** The day the views are centred on (controlled). */
  date?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  /** Which views the switcher offers, in order. */
  views?: CalendarView[];
  timeZone?: string;
  /** Built-in Iranian holidays by default; your own provider, or false. */
  occasions?: OccasionProvider | false;
  secondary?: Secondary;
  weekend?: number[];
  startHour?: number;
  endHour?: number;
  slotMinutes?: number;
  onSlotSelect?: (start: Date, end: Date) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onEventChange?: (event: CalendarEvent, start: Date, end: Date) => void;
  /** Clicking a day in the month view. Default: open that day. */
  onDayClick?: (date: Date) => void;
  className?: string;
}

/**
 * تقویم رویدادها. One component with month, week, day and list views, a
 * shared toolbar and Iranian holidays. Every view is also its own component
 * (MonthView, TimeGrid, AgendaView) if you only need one.
 */
export function EventCalendar({
  events = [],
  view,
  defaultView = "month",
  onViewChange,
  date,
  defaultDate,
  onDateChange,
  views = ["month", "week", "day", "agenda"],
  timeZone,
  occasions,
  secondary = "hijri",
  weekend,
  startHour,
  endHour,
  slotMinutes,
  onSlotSelect,
  onEventClick,
  onEventChange,
  onDayClick,
  className,
}: EventCalendarProps) {
  const today = useToday();
  const [current, setView] = useControllable(view, defaultView, onViewChange);
  const [cursor, setCursor] = useControllable(date, defaultDate ?? today, onDateChange);

  const step = (dir: 1 | -1) =>
    setCursor(current === "month" ? addJalaliMonths(cursor, dir) : addDays(cursor, dir * (current === "week" ? 7 : current === "day" ? 1 : AGENDA_DAYS)));

  const { jy, jm } = toJalali(cursor);
  const week = weekDates(cursor);
  const title =
    current === "month" ? monthTitle(jy, jm)
    : current === "week" ? `${shortDay(week[0])} تا ${shortDay(week[6])} ${fa(toJalali(week[6]).jy)}`
    : current === "day" ? `${JALALI_WEEKDAYS[jalaliWeekday(cursor)]} ${shortDay(cursor)} ${fa(jy)}`
    : `${shortDay(cursor)} تا ${shortDay(addDays(cursor, AGENDA_DAYS - 1))}`;
  const subtitle = current === "month" || current === "day" ? secondaryMonthTitle(jy, jm, secondary) : monthTitle(jy, jm);

  const shared = { events, date: cursor, onDateChange: setCursor, toolbar: false, onEventClick };
  const grid = { startHour, endHour, slotMinutes, onSlotSelect, onEventChange };

  return (
    <CalendarProvider timeZone={timeZone} occasions={occasions} secondary={secondary} weekend={weekend}>
      <div className={cn("w-full space-y-3", className)}>
        <CalendarToolbar
          title={title}
          subtitle={subtitle}
          onPrev={() => step(-1)}
          onNext={() => step(1)}
          onToday={() => setCursor(today)}
          prevLabel="قبلی"
          nextLabel="بعدی"
        >
          {views.length > 1 && (
            <SegmentedControl size="sm" aria-label="نما" value={current} onChange={(v) => setView(v as CalendarView)} options={views.map((v) => ({ value: v, label: VIEW_LABELS[v] }))} />
          )}
        </CalendarToolbar>
        {current === "month" && (
          <MonthView
            events={events}
            month={cursor}
            onMonthChange={setCursor}
            toolbar={false}
            onEventClick={onEventClick}
            onDayClick={(d) => {
              if (onDayClick) onDayClick(d);
              else if (views.includes("day")) {
                setCursor(d);
                setView("day");
              }
            }}
          />
        )}
        {current === "week" && <TimeGrid {...shared} {...grid} days={7} />}
        {current === "day" && <TimeGrid {...shared} {...grid} days={1} />}
        {current === "agenda" && <AgendaView {...shared} days={AGENDA_DAYS} />}
      </div>
    </CalendarProvider>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { toGregorian, toJalali } from "@/lib/jalali";
import { addJalaliMonths, dayKey, eventColor, formatTime, fromKey, layoutSpans, monthGrid, monthTitle, shortDay, type CalendarEvent } from "@/lib/calendar-utils";
import { Popover } from "@/components/ui/popover";
import {
  CalendarToolbar,
  DayNumber,
  EventChip,
  OccasionLine,
  WeekdayHeader,
  dayInfo,
  secondaryMonthTitle,
  useCalendar,
  useControllable,
  useRovingDays,
  useToday,
  useWidth,
  type DayInfo,
} from "@/components/calendar/calendar-core";

export interface MonthViewProps {
  events?: CalendarEvent[];
  /** Any day in the month to show (controlled). */
  month?: Date;
  defaultMonth?: Date;
  onMonthChange?: (month: Date) => void;
  /** Selected day key "YYYY-MM-DD". */
  selected?: string;
  onDayClick?: (date: Date, info: DayInfo) => void;
  onEventClick?: (event: CalendarEvent) => void;
  /** Event rows per week before «+۲ مورد دیگر». Default 3. */
  maxLanes?: number;
  /** Always six weeks, so the height never jumps. Default true. */
  fixedWeeks?: boolean;
  /** Show the built-in title and arrows. EventCalendar turns this off. */
  toolbar?: boolean;
  className?: string;
}

const HEAD = 46;
const LANE = 22;

/**
 * نمای ماه. A Jalali month with multi-day events drawn as bars across the
 * week (right to left), holidays named in their cell and overflow behind
 * «+۲ مورد دیگر». Below ~560px the bars turn into colored dots.
 */
export function MonthView({ events = [], month, defaultMonth, onMonthChange, selected, onDayClick, onEventClick, maxLanes = 3, fixedWeeks = true, toolbar = true, className }: MonthViewProps) {
  const settings = useCalendar();
  const today = useToday();
  const [cursor, setCursor] = useControllable(month, defaultMonth ?? today, onMonthChange);
  const { jy, jm } = toJalali(cursor);
  const weeks = React.useMemo(() => monthGrid(jy, jm, { fixedWeeks }), [jy, jm, fixedWeeks]);
  const [box, width] = useWidth<HTMLDivElement>();
  const compact = width > 0 && width < 560;
  const indexOf = React.useMemo(() => new Map(events.map((e, i) => [e, i])), [events]);

  const { container: gridRef, focusKey, setFocusKey, onKeyDown: onGridKey } = useRovingDays(selected ?? dayKey(today), (k) => {
    const j = toJalali(fromKey(k));
    if (j.jy !== jy || j.jm !== jm) setCursor(fromKey(k));
  });
  const firstKey = dayKey(toGregorian(jy, jm, 1));
  // Below ~560px cells have no room for names, so the month's occasions are listed under the grid.
  const monthOccasions = compact && settings.occasions ? weeks.flat().filter((d) => toJalali(d).jm === jm).flatMap((d) => settings.occasions!(dayKey(d))) : [];
  const visible = new Set(weeks.flat().map(dayKey));
  const tabKey = visible.has(focusKey) && toJalali(fromKey(focusKey)).jm === jm ? focusKey : selected && visible.has(selected) ? selected : firstKey;

  return (
    <div ref={box} className={cn("w-full", className)}>
      {toolbar && (
        <CalendarToolbar
          className="mb-3"
          title={monthTitle(jy, jm)}
          subtitle={secondaryMonthTitle(jy, jm, settings.secondary)}
          onPrev={() => setCursor(addJalaliMonths(cursor, -1))}
          onNext={() => setCursor(addJalaliMonths(cursor, 1))}
          onToday={() => setCursor(today)}
          prevLabel="ماه قبل"
          nextLabel="ماه بعد"
        />
      )}
      <div className="overflow-hidden rounded-surface border-line bg-card">
        <WeekdayHeader short={compact} className="border-b bg-muted/40" />
        <div ref={gridRef} role="grid" aria-label={monthTitle(jy, jm)} onKeyDown={onGridKey}>
          {weeks.map((week, r) => {
            const keys = week.map(dayKey);
            const bars = layoutSpans(events, keys, settings.timeZone);
            const lanes = compact ? 0 : maxLanes;
            const hidden = keys.map((_, c) => bars.filter((b) => b.lane >= lanes && b.from <= c && b.to >= c));
            return (
              <div key={keys[0]} role="row" className={cn("relative grid grid-cols-7", r > 0 && "border-t")}>
                {week.map((date, c) => {
                  const info = dayInfo(date, settings, today);
                  const outside = toJalali(date).jm !== jm;
                  const dayBars = bars.filter((b) => b.from <= c && b.to >= c);
                  return (
                    <div
                      key={info.key}
                      className={cn("relative flex flex-col", c > 0 && "border-s", (info.holiday || info.isWeekend) && "bg-destructive/[0.04]")}
                      style={{ minHeight: compact ? 64 : HEAD + lanes * LANE + 20 }}
                    >
                      <button
                        type="button"
                        role="gridcell"
                        data-key={info.key}
                        tabIndex={info.key === tabKey ? 0 : -1}
                        aria-selected={selected === info.key}
                        aria-label={info.label + (dayBars.length ? `، ${fa(dayBars.length)} رویداد` : "")}
                        onClick={() => {
                          setFocusKey(info.key);
                          onDayClick?.(date, info);
                        }}
                        className="absolute inset-0 cursor-pointer outline-none transition-colors hover:bg-accent/50 focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                      />
                      <div className="pointer-events-none relative flex flex-col items-center px-1 pt-1.5" style={{ height: compact ? undefined : HEAD }}>
                        <DayNumber info={info} outside={outside} selected={selected === info.key} size={compact ? "sm" : "md"} />
                        {!compact && <OccasionLine info={info} className={cn("w-full text-center", outside && "opacity-40")} />}
                      </div>
                      {compact && dayBars.length > 0 && (
                        <div className="pointer-events-none relative mt-1 flex justify-center gap-0.5" aria-hidden>
                          {dayBars.slice(0, 3).map((b) => (
                            <span key={b.event.id} className="size-1.5 rounded-full" style={{ background: eventColor(b.event.color, indexOf.get(b.event) ?? 0) }} />
                          ))}
                        </div>
                      )}
                      {hidden[c].length > 0 && !compact && (
                        <div className="relative mt-auto px-1 pb-1 [&>div]:block [&>div>span]:flex">
                          <Popover
                            align="start"
                            trigger={
                              <span
                                role="button"
                                tabIndex={0}
                                onKeyDown={(e) => {
                                  if (e.key !== "Enter" && e.key !== " ") return;
                                  e.preventDefault();
                                  e.currentTarget.click();
                                }}
                                className="block w-full cursor-pointer truncate rounded-control px-1 text-start text-[11px] text-muted-foreground hover:bg-accent hover:text-foreground">
                                +{fa(hidden[c].length)} مورد دیگر
                              </span>
                            }
                          >
                            <div className="w-56 space-y-1">
                              <p className="px-1 pb-1 text-xs font-semibold">{info.label.split("،")[0]}</p>
                              {dayBars.map((b) => (
                                <EventChip key={b.event.id} event={b.event} index={indexOf.get(b.event)} showTime timeZone={settings.timeZone} onClick={() => onEventClick?.(b.event)} />
                              ))}
                            </div>
                          </Popover>
                        </div>
                      )}
                    </div>
                  );
                })}
                {!compact && (
                  <div className="pointer-events-none absolute inset-x-0" style={{ top: HEAD }}>
                    {bars
                      .filter((b) => b.lane < lanes)
                      .map((b) => {
                        const timed = !b.event.allDay && b.from === b.to && !b.continuesBefore && !b.continuesAfter;
                        return (
                          <div
                            key={b.event.id}
                            className="pointer-events-auto absolute px-0.5"
                            style={{ insetInlineStart: `${(b.from / 7) * 100}%`, width: `${((b.to - b.from + 1) / 7) * 100}%`, top: b.lane * LANE, height: LANE - 2 }}
                          >
                            <EventChip
                              event={b.event}
                              index={indexOf.get(b.event)}
                              compact
                              tabIndex={-1}
                              aria-label={`${b.event.title}${timed ? `، ساعت ${formatTime(b.event.start, settings.timeZone)}` : ""}`}
                              onClick={() => onEventClick?.(b.event)}
                              lead={timed ? formatTime(b.event.start, settings.timeZone) : undefined}
                              className={cn("h-full justify-center", b.continuesBefore && "rounded-s-none", b.continuesAfter && "rounded-e-none")}
                            />
                          </div>
                        );
                      })}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
      {compact && monthOccasions.length > 0 && (
        <ul className="mt-2 space-y-0.5 text-[11px]">
          {monthOccasions.map((o) => (
            <li key={o.key + o.title} className={cn("flex gap-2", o.holiday ? "text-destructive" : "text-muted-foreground")}>
              <span className="w-12 shrink-0 tabular-nums">{shortDay(o.date)}</span>
              <span className="truncate">
                {o.title}
                {o.approximate && " (تقریبی)"}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_WEEKDAYS, jalaliWeekday, toJalali } from "@/lib/jalali";
import {
  addDays,
  atMinutes,
  dayKey,
  eventColor,
  formatMinutes,
  formatTimeRange,
  isSpanning,
  layoutSpans,
  layoutTimed,
  minutesOfDay,
  monthTitle,
  shortDay,
  weekDates,
  zonedKey,
  type CalendarEvent,
} from "@/lib/calendar-utils";
import {
  CalendarToolbar,
  DayNumber,
  EventChip,
  OccasionLine,
  dayInfo,
  secondaryMonthTitle,
  useCalendar,
  useControllable,
  useNow,
  useToday,
} from "@/components/calendar/calendar-core";

export interface TimeGridProps {
  events?: CalendarEvent[];
  /** Any day in the week (or the day) to show (controlled). */
  date?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  /** 7 = week (شنبه to جمعه), 1 = one day. */
  days?: 1 | 7;
  /** Visible hours, 0–24. Default 7 to 22. */
  startHour?: number;
  endHour?: number;
  /** Snap step for selecting and dragging. Default 30. */
  slotMinutes?: number;
  /** Pixels per hour. Default 48. */
  hourHeight?: number;
  /** Max height of the scrolling body. Default 560. */
  maxHeight?: number;
  /** Fired after dragging over empty time. */
  onSlotSelect?: (start: Date, end: Date) => void;
  onEventClick?: (event: CalendarEvent) => void;
  /** Turns on drag to move and resize (and Alt+arrows on a focused event). */
  onEventChange?: (event: CalendarEvent, start: Date, end: Date) => void;
  toolbar?: boolean;
  className?: string;
}

type Drag =
  | { kind: "select"; col: number; a: number; b: number }
  | { kind: "move" | "resize"; event: CalendarEvent; col: number; grab: number; start: number; end: number; moved: boolean };

const GUTTER = 52;

/**
 * نمای هفته و روز. Hours run down the right edge, شنبه is the rightmost
 * column, overlapping events sit side by side and a line marks now. Drag over
 * empty time to create; with onEventChange, drag an event to move it or its
 * bottom edge to resize it.
 */
export function TimeGrid({
  events = [],
  date,
  defaultDate,
  onDateChange,
  days = 7,
  startHour = 7,
  endHour = 22,
  slotMinutes = 30,
  hourHeight = 48,
  maxHeight = 560,
  onSlotSelect,
  onEventClick,
  onEventChange,
  toolbar = true,
  className,
}: TimeGridProps) {
  const settings = useCalendar();
  const tz = settings.timeZone;
  const today = useToday();
  const now = useNow();
  const [cursor, setCursor] = useControllable(date, defaultDate ?? today, onDateChange);
  const dates = days === 7 ? weekDates(cursor) : [new Date(cursor.getFullYear(), cursor.getMonth(), cursor.getDate())];
  const keys = dates.map(dayKey);
  const total = (endHour - startHour) * hourHeight;
  const toMin = (y: number) => startHour * 60 + (y / hourHeight) * 60;
  const snap = (m: number) => Math.round(m / slotMinutes) * slotMinutes;
  const indexOf = React.useMemo(() => new Map(events.map((e, i) => [e, i])), [events]);

  const spanning = events.filter((e) => isSpanning(e, tz));
  const timed = events.filter((e) => !isSpanning(e, tz));
  const bars = layoutSpans(spanning, keys, tz);
  const lanes = bars.reduce((n, b) => Math.max(n, b.lane + 1), 0);

  const body = React.useRef<HTMLDivElement>(null);
  const cols = React.useRef<HTMLDivElement>(null);
  const [drag, setDrag] = React.useState<Drag | null>(null);

  React.useEffect(() => {
    const el = body.current;
    if (!el) return;
    const n = new Date();
    const target = (minutesOfDay(n, tz) / 60 - startHour - 1) * hourHeight;
    el.scrollTop = Math.max(0, Math.min(target, total));
    // Only on mount and when the visible hours change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [startHour, hourHeight]);

  function pointAt(e: React.PointerEvent) {
    const rect = cols.current!.getBoundingClientRect();
    const colW = rect.width / dates.length;
    // RTL: column 0 is on the right.
    const col = Math.max(0, Math.min(dates.length - 1, Math.floor((rect.right - e.clientX) / colW)));
    const min = Math.max(startHour * 60, Math.min(endHour * 60, toMin(e.clientY - rect.top)));
    return { col, min };
  }

  function onDown(e: React.PointerEvent) {
    if (e.button !== 0 || !onSlotSelect) return;
    const { col, min } = pointAt(e);
    const a = Math.floor(min / slotMinutes) * slotMinutes;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    setDrag({ kind: "select", col, a, b: a + slotMinutes });
  }

  function onEventDown(e: React.PointerEvent, ev: CalendarEvent, col: number, kind: "move" | "resize") {
    e.stopPropagation();
    if (e.button !== 0 || !onEventChange) return;
    const start = minutesOfDay(ev.start, tz);
    const end = start + Math.round((ev.end.getTime() - ev.start.getTime()) / 60_000);
    (cols.current as HTMLElement).setPointerCapture(e.pointerId);
    setDrag({ kind, event: ev, col, grab: pointAt(e).min - start, start, end, moved: false });
  }

  function onMove(e: React.PointerEvent) {
    if (!drag) return;
    const { col, min } = pointAt(e);
    if (drag.kind === "select") {
      const b = Math.ceil(min / slotMinutes) * slotMinutes;
      setDrag({ ...drag, b: Math.max(b, drag.a + slotMinutes) });
    } else if (drag.kind === "move") {
      const len = drag.end - drag.start;
      const start = Math.max(startHour * 60, Math.min(endHour * 60 - len, snap(min - drag.grab)));
      setDrag({ ...drag, col, start, end: start + len, moved: true });
    } else {
      setDrag({ ...drag, end: Math.max(drag.start + slotMinutes, snap(min)), moved: true });
    }
  }

  function onUp() {
    if (!drag) return;
    if (drag.kind === "select") onSlotSelect?.(atMinutes(keys[drag.col], drag.a, tz), atMinutes(keys[drag.col], drag.b, tz));
    else if (drag.moved) onEventChange?.(drag.event, atMinutes(keys[drag.col], drag.start, tz), atMinutes(keys[drag.col], drag.end, tz));
    else onEventClick?.(drag.event);
    setDrag(null);
  }

  function onEventKey(e: React.KeyboardEvent, ev: CalendarEvent) {
    if (!onEventChange || !e.altKey) return;
    const ms = e.key === "ArrowDown" ? slotMinutes : e.key === "ArrowUp" ? -slotMinutes : e.key === "ArrowLeft" ? 1440 : e.key === "ArrowRight" ? -1440 : 0;
    if (!ms) return;
    e.preventDefault();
    const d = ms * 60_000;
    onEventChange(ev, new Date(ev.start.getTime() + d), new Date(ev.end.getTime() + d));
  }

  const { jy, jm } = toJalali(dates[0]);
  const title = days === 7 ? `${shortDay(dates[0])} تا ${shortDay(dates[6])} ${fa(toJalali(dates[6]).jy)}` : `${JALALI_WEEKDAYS[jalaliWeekday(dates[0])]} ${shortDay(dates[0])} ${fa(jy)}`;
  const hours = Array.from({ length: endHour - startHour }, (_, i) => startHour + i);
  const nowKey = now ? zonedKey(now, tz) : null;
  const nowMin = now ? minutesOfDay(now, tz) : 0;

  return (
    <div className={cn("w-full", className)}>
      {toolbar && (
        <CalendarToolbar
          className="mb-3"
          title={title}
          subtitle={days === 7 ? monthTitle(jy, jm) : secondaryMonthTitle(jy, jm, settings.secondary)}
          onPrev={() => setCursor(addDays(cursor, -days))}
          onNext={() => setCursor(addDays(cursor, days))}
          onToday={() => setCursor(today)}
          prevLabel={days === 7 ? "هفته‌ی قبل" : "روز قبل"}
          nextLabel={days === 7 ? "هفته‌ی بعد" : "روز بعد"}
        />
      )}
      <div className="overflow-x-auto rounded-surface border-line bg-card">
        <div style={{ minWidth: days === 7 ? 640 : undefined }}>
          {/* day headers */}
          <div className="flex border-b">
            <div className="shrink-0" style={{ width: GUTTER }} />
            <div className="grid flex-1" style={{ gridTemplateColumns: `repeat(${dates.length}, minmax(0, 1fr))` }}>
              {dates.map((d) => {
                const info = dayInfo(d, settings, today);
                return (
                  <div key={info.key} className={cn("flex min-w-0 flex-col items-center gap-0.5 border-s px-1 py-1.5", (info.holiday || info.isWeekend) && "bg-destructive/[0.04]")}>
                    <span className={cn("text-[11px] text-muted-foreground", (info.holiday || info.isWeekend) && "text-destructive/80")}>{JALALI_WEEKDAYS[jalaliWeekday(d)]}</span>
                    <DayNumber info={info} />
                    <OccasionLine info={info} className="w-full text-center" />
                  </div>
                );
              })}
            </div>
          </div>
          {/* all-day lane */}
          {lanes > 0 && (
            <div className="flex border-b">
              <div className="shrink-0 self-center px-1 text-center text-[10px] text-muted-foreground" style={{ width: GUTTER }}>
                تمام روز
              </div>
              <div className="relative flex-1 border-s" style={{ height: lanes * 24 + 4 }}>
                {bars.map((b) => (
                  <div key={b.event.id} className="absolute px-0.5" style={{ insetInlineStart: `${(b.from / dates.length) * 100}%`, width: `${((b.to - b.from + 1) / dates.length) * 100}%`, top: 2 + b.lane * 24, height: 22 }}>
                    <EventChip event={b.event} index={indexOf.get(b.event)} compact onClick={() => onEventClick?.(b.event)} className={cn("h-full justify-center", b.continuesBefore && "rounded-s-none", b.continuesAfter && "rounded-e-none")} />
                  </div>
                ))}
              </div>
            </div>
          )}
          {/* timed body */}
          <div ref={body} className="overflow-y-auto" style={{ maxHeight }}>
            <div className="flex" style={{ height: total }}>
              <div className="relative shrink-0" style={{ width: GUTTER }} aria-hidden>
                {hours.map((h, i) => (
                  <span key={h} className="absolute inset-x-0 -translate-y-1/2 text-center text-[10px] text-muted-foreground tabular-nums" style={{ top: i * hourHeight }}>
                    {i === 0 ? "" : formatMinutes(h * 60)}
                  </span>
                ))}
              </div>
              <div
                ref={cols}
                className={cn("relative grid flex-1 touch-none select-none", onSlotSelect && "cursor-crosshair")}
                style={{ gridTemplateColumns: `repeat(${dates.length}, minmax(0, 1fr))`, backgroundImage: `repeating-linear-gradient(to bottom, var(--color-border) 0 1px, transparent 1px ${hourHeight}px)` }}
                onPointerDown={onDown}
                onPointerMove={onMove}
                onPointerUp={onUp}
                onPointerCancel={() => setDrag(null)}
              >
                {dates.map((d, c) => {
                  const key = keys[c];
                  const info = dayInfo(d, settings, today);
                  const boxes = layoutTimed(timed, key, tz, { startHour, endHour });
                  return (
                    <div key={key} className={cn("relative border-s", (info.holiday || info.isWeekend) && "bg-destructive/[0.04]")} aria-label={info.label}>
                      {boxes.map((b) => {
                        const dragging = drag && drag.kind !== "select" && drag.event.id === b.event.id;
                        return (
                          <div
                            key={b.event.id}
                            className={cn("absolute px-px", dragging && "opacity-40")}
                            style={{ top: b.top * total, height: Math.max(18, b.height * total - 2), insetInlineStart: `${(b.col / b.cols) * 100}%`, width: `${100 / b.cols}%` }}
                          >
                            <EventChip
                              event={b.event}
                              index={indexOf.get(b.event)}
                              showTime={b.height * total > 36}
                              timeZone={tz}
                              compact={b.height * total < 36}
                              aria-label={`${b.event.title}، ${formatTimeRange(b.event.start, b.event.end, tz)}`}
                              onPointerDown={(e) => onEventDown(e, b.event, c, "move")}
                              onClick={onEventChange ? undefined : () => onEventClick?.(b.event)}
                              onKeyDown={(e) => {
                                if (e.key === "Enter" && onEventChange) onEventClick?.(b.event);
                                onEventKey(e, b.event);
                              }}
                              className={cn("h-full justify-start", onEventChange && "cursor-grab active:cursor-grabbing")}
                            />
                            {onEventChange && (
                              <span
                                aria-hidden
                                onPointerDown={(e) => onEventDown(e, b.event, c, "resize")}
                                className="absolute inset-x-1 bottom-0 h-1.5 cursor-ns-resize rounded-full hover:bg-foreground/20"
                              />
                            )}
                          </div>
                        );
                      })}
                      {nowKey === key && nowMin >= startHour * 60 && nowMin <= endHour * 60 && (
                        <div className="pointer-events-none absolute inset-x-0 z-10 flex items-center" style={{ top: ((nowMin - startHour * 60) / 60) * hourHeight }}>
                          <span className="size-2 -translate-x-1/2 rounded-full bg-destructive rtl:translate-x-1/2" />
                          <span className="h-px flex-1 bg-destructive" />
                        </div>
                      )}
                    </div>
                  );
                })}
                {drag && drag.kind === "select" && (
                  <div
                    className="pointer-events-none absolute rounded-control border-2 border-dashed border-primary bg-primary/10 px-1 text-[10px] tabular-nums"
                    style={{ insetInlineStart: `${(drag.col / dates.length) * 100}%`, width: `${100 / dates.length}%`, top: ((drag.a - startHour * 60) / 60) * hourHeight, height: ((drag.b - drag.a) / 60) * hourHeight }}
                  >
                    {formatMinutes(drag.a)} تا {formatMinutes(drag.b)}
                  </div>
                )}
                {drag && drag.kind !== "select" && drag.moved && (
                  <div
                    className="pointer-events-none absolute z-20 px-px"
                    style={{ insetInlineStart: `${(drag.col / dates.length) * 100}%`, width: `${100 / dates.length}%`, top: ((drag.start - startHour * 60) / 60) * hourHeight, height: ((drag.end - drag.start) / 60) * hourHeight }}
                  >
                    <div className="flex h-full flex-col rounded-control border-s-[3px] px-2 py-1 text-xs shadow-overlay" style={{ borderColor: eventColor(drag.event.color, indexOf.get(drag.event) ?? 0), background: `color-mix(in oklch, ${eventColor(drag.event.color, indexOf.get(drag.event) ?? 0)} 30%, var(--color-card))` }}>
                      <span className="truncate font-medium">{drag.event.title}</span>
                      <span className="text-[10px] tabular-nums text-muted-foreground">
                        {formatMinutes(drag.start)} تا {formatMinutes(drag.end)}
                      </span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { MapPin } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";
import { formatHijri } from "@/lib/hijri";
import { addDays, dayKey, dayLabel, eventColor, eventDayRange, formatTimeRange, type CalendarEvent } from "@/lib/calendar-utils";
import { CalendarEmpty, CalendarToolbar, dayInfo, useCalendar, useControllable, useToday } from "@/components/calendar/calendar-core";

const RELATIVE = ["امروز", "فردا", "دیروز"];

export interface AgendaViewProps {
  events?: CalendarEvent[];
  /** First day of the list (controlled). Default today. */
  date?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  /** Days covered. Default 14. */
  days?: number;
  /** Also list holidays and occasions on their days. Default true. */
  showOccasions?: boolean;
  onEventClick?: (event: CalendarEvent) => void;
  emptyText?: React.ReactNode;
  toolbar?: boolean;
  className?: string;
}

/**
 * فهرست رویدادها. Days with something on them, labelled «امروز»، «فردا» or
 * by weekday, each event with its time, color and place. Holidays show up as
 * their own line, so a quiet day off is not mistaken for an empty one.
 */
export function AgendaView({ events = [], date, defaultDate, onDateChange, days = 14, showOccasions = true, onEventClick, emptyText = "در این بازه رویدادی نیست.", toolbar = true, className }: AgendaViewProps) {
  const settings = useCalendar();
  const today = useToday();
  const [from, setFrom] = useControllable(date, defaultDate ?? today, onDateChange);
  const indexOf = React.useMemo(() => new Map(events.map((e, i) => [e, i])), [events]);
  const ranges = React.useMemo(() => events.map((e) => [e, ...eventDayRange(e, settings.timeZone)] as const), [events, settings.timeZone]);

  const groups = Array.from({ length: days }, (_, i) => {
    const d = addDays(from, i);
    const key = dayKey(d);
    const info = dayInfo(d, settings, today);
    const list = ranges
      .filter(([, a, b]) => a <= key && b >= key)
      .map(([e]) => e)
      .sort((x, y) => Number(!!y.allDay) - Number(!!x.allDay) || x.start.getTime() - y.start.getTime());
    const label = dayLabel(d, today);
    return { d, key, info, list, label, relative: RELATIVE.includes(label), occasions: showOccasions ? info.occasions : [] };
  }).filter((g) => g.list.length || g.occasions.length);

  const last = addDays(from, days - 1);
  return (
    <div className={cn("@container w-full", className)}>
      {toolbar && (
        <CalendarToolbar
          className="mb-3"
          title={`${formatJalali(from, { year: false })} تا ${formatJalali(last)}`}
          onPrev={() => setFrom(addDays(from, -days))}
          onNext={() => setFrom(addDays(from, days))}
          onToday={() => setFrom(today)}
          prevLabel="بازه‌ی قبل"
          nextLabel="بازه‌ی بعد"
        />
      )}
      {!groups.length ? (
        <CalendarEmpty>{emptyText}</CalendarEmpty>
      ) : (
        <ol className="divide-y overflow-hidden rounded-surface border-line bg-card">
          {groups.map((g) => (
            <li key={g.key} className="grid grid-cols-1 gap-2 p-3 @lg:grid-cols-[9rem_1fr] @lg:gap-4">
              <div>
                <p className={cn("text-sm font-bold", g.info.isToday && "text-primary", (g.info.holiday || g.info.isWeekend) && "text-destructive")}>{g.label}</p>
                <p className="text-[11px] text-muted-foreground">
                  {g.relative ? formatJalali(g.d, { weekday: true }) : formatJalali(g.d)}
                  {settings.secondary === "hijri" && <span className="block">{formatHijri(g.d)}</span>}
                </p>
              </div>
              <ul className="space-y-1.5">
                {g.occasions.map((o) => (
                  <li key={o.title} className={cn("flex items-center gap-2 text-xs", o.holiday ? "text-destructive" : "text-muted-foreground")}>
                    <span aria-hidden className={cn("size-1.5 rounded-full", o.holiday ? "bg-destructive" : "bg-muted-foreground/50")} />
                    {o.title}
                    {o.holiday && <span className="rounded-full border border-destructive/30 px-1.5 text-[10px]">تعطیل</span>}
                    {o.approximate && <span className="text-[10px] text-muted-foreground">تقریبی</span>}
                  </li>
                ))}
                {g.list.map((e) => (
                  <li key={e.id}>
                    <button
                      type="button"
                      onClick={() => onEventClick?.(e)}
                      className="flex w-full cursor-pointer items-start gap-3 rounded-control px-2 py-1.5 text-start transition-colors hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring"
                    >
                      <span className="w-[5.5rem] shrink-0 pt-0.5 text-xs text-muted-foreground tabular-nums">{e.allDay ? "تمام روز" : formatTimeRange(e.start, e.end, settings.timeZone)}</span>
                      <span aria-hidden className="mt-1.5 size-2 shrink-0 rounded-full" style={{ background: eventColor(e.color, indexOf.get(e) ?? 0) }} />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-medium">{e.title}</span>
                        {e.location && (
                          <span className="flex items-center gap-1 text-[11px] text-muted-foreground">
                            <MapPin className="size-3" />
                            {e.location}
                          </span>
                        )}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ol>
      )}
      <p className="sr-only" aria-live="polite">
        {fa(groups.reduce((n, g) => n + g.list.length, 0))} رویداد در این بازه
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS_SHORT, jalaliMonthLength, toGregorian, toJalali } from "@/lib/jalali";
import { addDays, dayKey, eventColor, eventDayRange, fromKey, monthGrid, type CalendarEvent } from "@/lib/calendar-utils";
import { CalendarToolbar, dayInfo, useCalendar, useControllable, useRovingDays, useToday, type CalendarSettings, type DayInfo } from "@/components/calendar/calendar-core";

export interface YearViewProps {
  /** Jalali year (controlled). Default this year. */
  year?: number;
  defaultYear?: number;
  onYearChange?: (year: number) => void;
  /** Days with events get a dot. */
  events?: CalendarEvent[];
  selected?: string;
  onDayClick?: (date: Date, info: DayInfo) => void;
  /** Months per row on wide screens. Default 4. */
  columns?: 3 | 4 | 6;
  toolbar?: boolean;
  className?: string;
}

/** First event color of every day an event covers. */
function eventDots(events: CalendarEvent[], tz: string) {
  const map = new Map<string, string>();
  events.forEach((e, i) => {
    const [a, b] = eventDayRange(e, tz);
    for (let d = fromKey(a); dayKey(d) <= b; d = addDays(d, 1)) {
      const k = dayKey(d);
      if (!map.has(k)) map.set(k, eventColor(e.color, i));
    }
  });
  return map;
}

/** Official holidays of a Jalali year, Fridays aside. */
function countHolidays(jy: number, settings: CalendarSettings, today: Date) {
  let n = 0;
  for (let jm = 1; jm <= 12; jm += 1) {
    for (let jd = 1; jd <= jalaliMonthLength(jy, jm); jd += 1) if (dayInfo(toGregorian(jy, jm, jd), settings, today).holiday) n += 1;
  }
  return n;
}

const COLS = { 3: "lg:grid-cols-3", 4: "lg:grid-cols-4", 6: "lg:grid-cols-6" } as const;

/**
 * نمای سال. Twelve Jalali months at a glance with every holiday marked, so
 * planning a trip or a release around تعطیلات takes one look. Arrow keys move
 * across days and months.
 */
export function YearView({ year, defaultYear, onYearChange, events = [], selected, onDayClick, columns = 4, toolbar = true, className }: YearViewProps) {
  const settings = useCalendar();
  const today = useToday();
  const [jy, setYear] = useControllable(year, defaultYear ?? toJalali(today).jy, onYearChange);

  const dots = React.useMemo(() => eventDots(events, settings.timeZone), [events, settings.timeZone]);

  const { container: gridRef, focusKey, setFocusKey, onKeyDown: onGridKey } = useRovingDays(selected ?? dayKey(toJalali(today).jy === jy ? today : toGregorian(jy, 1, 1)), (k) => {
    const y = toJalali(fromKey(k)).jy;
    if (y !== jy) setYear(y);
  });
  const holidays = React.useMemo(() => countHolidays(jy, settings, today), [jy, settings, today]);
  const inYear = toJalali(fromKey(focusKey)).jy === jy;
  const tabKey = inYear ? focusKey : dayKey(toGregorian(jy, 1, 1));

  return (
    <div className={cn("w-full", className)}>
      {toolbar && (
        <CalendarToolbar
          className="mb-3"
          title={`سال ${fa(jy)}`}
          subtitle={settings.occasions ? `${fa(holidays)} روز تعطیل رسمی به‌علاوه‌ی جمعه‌ها` : undefined}
          onPrev={() => setYear(jy - 1)}
          onNext={() => setYear(jy + 1)}
          onToday={() => setYear(toJalali(today).jy)}
          prevLabel="سال قبل"
          nextLabel="سال بعد"
        />
      )}
      <div ref={gridRef} onKeyDown={onGridKey} className={cn("grid grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-3", COLS[columns])}>
        {JALALI_MONTHS.map((name, i) => {
          const jm = i + 1;
          const weeks = monthGrid(jy, jm);
          return (
            <section key={name} className="rounded-surface border-line bg-card p-3" aria-label={`${name} ${fa(jy)}`}>
              <h3 className="mb-2 px-1 text-sm font-bold">{name}</h3>
              <div className="grid grid-cols-7 text-center text-[10px] text-muted-foreground" aria-hidden>
                {JALALI_WEEKDAYS_SHORT.map((d, c) => (
                  <span key={d} className={cn("py-0.5", settings.weekend.includes(c) && "text-destructive/70")}>
                    {d}
                  </span>
                ))}
              </div>
              <div role="grid" aria-label={name}>
                {weeks.map((week) => (
                  <div key={dayKey(week[0])} role="row" className="grid grid-cols-7">
                    {week.map((d) => {
                      if (toJalali(d).jm !== jm) return <span key={dayKey(d)} role="presentation" className="h-7" />;
                      const info = dayInfo(d, settings, today);
                      const off = info.holiday || info.isWeekend;
                      const dot = dots.get(info.key);
                      return (
                        <button
                          key={info.key}
                          type="button"
                          role="gridcell"
                          data-key={info.key}
                          tabIndex={info.key === tabKey ? 0 : -1}
                          aria-selected={selected === info.key}
                          aria-label={info.label}
                          title={info.occasions.map((o) => o.title).join("، ") || undefined}
                          onClick={() => {
                            setFocusKey(info.key);
                            onDayClick?.(d, info);
                          }}
                          className={cn(
                            "relative flex h-7 cursor-pointer items-center justify-center rounded-control text-[11px] tabular-nums transition-colors hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring",
                            off && "text-destructive",
                            info.holiday && "bg-destructive/10 font-semibold",
                            info.isToday && "ring-2 ring-inset ring-foreground/70",
                            selected === info.key && "bg-primary text-primary-foreground",
                          )}
                        >
                          {fa(toJalali(d).jd)}
                          {dot && <span aria-hidden className="absolute bottom-0.5 size-1 rounded-full" style={{ background: dot }} />}
                        </button>
                      );
                    })}
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, jalaliMonthLength, jalaliWeekday, toGregorian, toJalali } from "@/lib/jalali";
import { formatHijri } from "@/lib/hijri";
import type { Occasion } from "@/lib/iran-holidays";
import { addDays, dayKey, dayLabel, diffDays, startOfJalaliWeek } from "@/lib/calendar-utils";
import { CalendarEmpty, useCalendar, useToday } from "@/components/calendar/calendar-core";

/** «تعطیل» pill; with `approximate`, adds «تقریبی» so a guessed lunar date is never shown as certain. */
export function HolidayBadge({ approximate, className }: { approximate?: boolean; className?: string }) {
  return (
    <span className={cn("inline-flex shrink-0 items-center gap-1 rounded-full border border-destructive/30 bg-destructive/10 px-2 text-[10px] font-medium leading-5 text-destructive", className)}>
      تعطیل
      {approximate && <span className="text-destructive/70">· تقریبی</span>}
    </span>
  );
}

export type OccasionsRange = "today" | "week" | "month" | "upcoming";

export interface OccasionsListProps {
  /** Which days to list. «upcoming» shows the next `limit` from today. Default "month". */
  range?: OccasionsRange;
  /** Day the range is built around. Default today. */
  date?: Date;
  holidaysOnly?: boolean;
  /** Max rows. Default 6 for «upcoming», unlimited otherwise. */
  limit?: number;
  title?: React.ReactNode;
  /** Show the Hijri date of each row. Default true. */
  showHijri?: boolean;
  emptyText?: React.ReactNode;
  className?: string;
}

const TITLES: Record<OccasionsRange, string> = { today: "مناسبت‌های امروز", week: "مناسبت‌های این هفته", month: "مناسبت‌های این ماه", upcoming: "تعطیلات و مناسبت‌های پیش رو" };

function daysOf(range: OccasionsRange, anchor: Date): Date[] {
  if (range === "today") return [anchor];
  if (range === "week") {
    const s = startOfJalaliWeek(anchor);
    return Array.from({ length: 7 }, (_, i) => addDays(s, i));
  }
  if (range === "month") {
    const { jy, jm } = toJalali(anchor);
    return Array.from({ length: jalaliMonthLength(jy, jm) }, (_, i) => toGregorian(jy, jm, i + 1));
  }
  return Array.from({ length: 400 }, (_, i) => addDays(anchor, i));
}

/**
 * فهرست مناسبت‌ها. Holidays and occasions for today, this week, this month
 * or the next few, each with its Jalali and Hijri date and how far away it
 * is. Lunar dates outside the official table are marked «تقریبی».
 */
export function OccasionsList({ range = "month", date, holidaysOnly, limit, title, showHijri = true, emptyText = "مناسبتی در این بازه نیست.", className }: OccasionsListProps) {
  const { occasions } = useCalendar();
  const today = useToday();
  const anchor = date ?? today;
  const max = limit ?? (range === "upcoming" ? 6 : Infinity);

  const rows = React.useMemo(() => {
    if (!occasions) return [];
    const out: Occasion[] = [];
    for (const d of daysOf(range, anchor)) {
      for (const o of occasions(dayKey(d))) if (!holidaysOnly || o.holiday) out.push(o);
      if (out.length >= max) break;
    }
    return out.slice(0, max);
  }, [occasions, range, anchor, holidaysOnly, max]);

  return (
    <section className={cn("rounded-surface border-line bg-card p-4", className)}>
      <h3 className="mb-3 text-sm font-bold">{title ?? TITLES[range]}</h3>
      {rows.length === 0 ? (
        <CalendarEmpty>{emptyText}</CalendarEmpty>
      ) : (
        <ul className="space-y-2">
          {rows.map((o) => {
            const { jm, jd } = toJalali(o.date);
            const away = diffDays(today, o.date);
            return (
              <li key={o.key + o.title} className="flex items-center gap-3">
                <span className={cn("flex w-12 shrink-0 flex-col items-center rounded-control border py-1 leading-tight", o.holiday ? "border-destructive/30 bg-destructive/5 text-destructive" : "border-border")}>
                  <span className="text-base font-bold tabular-nums">{fa(jd)}</span>
                  <span className="text-[10px]">{JALALI_MONTHS[jm - 1]}</span>
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-2">
                    <span className="truncate text-sm font-medium">{o.title}</span>
                    {o.holiday && <HolidayBadge approximate={o.approximate} />}
                    {!o.holiday && o.approximate && <span className="text-[10px] text-muted-foreground">تقریبی</span>}
                  </span>
                  <span className="flex flex-wrap gap-x-1.5 text-[11px] text-muted-foreground [&>span]:whitespace-nowrap [&>span+span]:before:me-1.5 [&>span+span]:before:content-['·']">
                    <span>{JALALI_WEEKDAYS[jalaliWeekday(o.date)]}</span>
                    {showHijri && o.kind === "lunar" && <span>{formatHijri(o.date)}</span>}
                    {away > 1 && <span>{fa(away)} روز دیگر</span>}
                    {away >= -1 && away <= 1 && <span>{dayLabel(o.date, today)}</span>}
                  </span>
                </span>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, JALALI_WEEKDAYS_SHORT, jalaliWeekday, toJalali } from "@/lib/jalali";
import { addDays, formatTime, formatTimeRange, fromKey, generateSlots, minutesOfDay, shortDay, zonedKey, type Slot } from "@/lib/calendar-utils";
import { CalendarEmpty, dayInfo, useCalendar, useControllable, useNow, useToday } from "@/components/calendar/calendar-core";

export type SlotValue = { start: Date; end: Date } | null;
type Hours = [string, string][];

export interface SlotPickerProps {
  value?: SlotValue;
  defaultValue?: SlotValue;
  onChange?: (slot: SlotValue) => void;
  /** First day of the strip. Default today. */
  from?: Date;
  /** Days in the strip. Default 14. */
  days?: number;
  /** Opening hours for every day, or per weekday (0 = شنبه). Default 09–13 and 16–20. */
  hours?: Hours | Partial<Record<number, Hours>>;
  /** Weekdays closed. Default [6] (جمعه). */
  closedWeekdays?: number[];
  /** Close on official holidays. Default true. */
  closeOnHolidays?: boolean;
  /** Extra closed days, "YYYY-MM-DD". */
  closedDays?: string[];
  /** Your own reason a day is closed, e.g. «دکتر سه‌شنبه‌ها نیستن»; return null to fall back to the rules above. */
  closedReason?: (date: Date) => string | null;
  /** Minutes per appointment. Default 30. */
  duration?: number;
  /** Minutes between starts. Default = duration. */
  step?: number;
  /** Seats per slot. Default 1; above 1 shows seats left. */
  capacity?: number;
  /** Booked intervals, or a function per day key. */
  busy?: { start: Date; end: Date }[] | ((key: string) => { start: Date; end: Date }[]);
  className?: string;
}

const DEFAULT_HOURS: Hours = [["09:00", "13:00"], ["16:00", "20:00"]];

function hoursFor(hours: SlotPickerProps["hours"], weekday: number): Hours {
  if (!hours) return DEFAULT_HOURS;
  if (Array.isArray(hours)) return hours;
  return hours[weekday] ?? [];
}

function part(min: number) {
  return min < 12 * 60 ? "صبح" : min < 17 * 60 ? "بعدازظهر" : "عصر";
}

/**
 * انتخاب نوبت. A strip of days (Fridays, holidays and closed days disabled,
 * with the reason) above the free times of the chosen day, grouped into
 * صبح، بعدازظهر and عصر. Past and full slots stay visible but disabled.
 */
export function SlotPicker({
  value,
  defaultValue = null,
  onChange,
  from,
  days = 14,
  hours,
  closedWeekdays = [6],
  closeOnHolidays = true,
  closedDays = [],
  closedReason,
  duration = 30,
  step,
  capacity = 1,
  busy = [],
  className,
}: SlotPickerProps) {
  const settings = useCalendar();
  const tz = settings.timeZone;
  const today = useToday();
  const now = useNow();
  const start = from ?? today;
  const [slot, setSlot] = useControllable<SlotValue>(value, defaultValue, onChange);

  const strip = Array.from({ length: days }, (_, i) => {
    const d = addDays(start, i);
    const info = dayInfo(d, settings, today);
    const wd = jalaliWeekday(d);
    const reason =
      closedReason?.(d) ??
      (closedWeekdays.includes(wd) ? `${JALALI_WEEKDAYS[wd]}‌ها تعطیل است`
      : closeOnHolidays && info.holiday ? `تعطیل رسمی: ${info.holiday.title}`
      : closedDays.includes(info.key) ? "این روز تعطیل است"
      : hoursFor(hours, wd).length === 0 ? "این روز نوبت‌دهی نداریم"
      : null);
    return { d, info, wd, reason };
  });

  const firstOpen = strip.find((s) => !s.reason)?.info.key ?? strip[0].info.key;
  const [day, setDay] = React.useState(() => (slot ? zonedKey(slot.start, tz) : firstOpen));
  const current = strip.find((s) => s.info.key === day) ?? strip[0];

  const slots: Slot[] = current.reason
    ? []
    : generateSlots({
        key: current.info.key,
        open: hoursFor(hours, current.wd),
        duration,
        step,
        capacity,
        busy: typeof busy === "function" ? busy(current.info.key) : busy,
        tz,
        now: now ?? new Date(0),
      });
  const groups = ["صبح", "بعدازظهر", "عصر"].map((name) => ({ name, items: slots.filter((s) => part(minutesOfDay(s.start, tz)) === name) })).filter((g) => g.items.length);
  const free = slots.filter((s) => s.state === "free").length;
  const nextOpen = strip.find((s) => s.info.key > current.info.key && !s.reason);

  const stripRef = React.useRef<HTMLDivElement>(null);
  function onStripKey(e: React.KeyboardEvent) {
    const dir = e.key === "ArrowLeft" ? 1 : e.key === "ArrowRight" ? -1 : 0;
    if (!dir) return;
    e.preventDefault();
    const i = strip.findIndex((s) => s.info.key === day);
    const n = strip[Math.max(0, Math.min(strip.length - 1, i + dir))];
    setDay(n.info.key);
    stripRef.current?.querySelector<HTMLElement>(`[data-key="${n.info.key}"]`)?.focus();
  }

  const selectedKey = slot ? slot.start.getTime() : null;
  return (
    <div className={cn("w-full space-y-4", className)}>
      <div ref={stripRef} role="listbox" aria-label="روز" onKeyDown={onStripKey} className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1">
        {strip.map(({ d, info, reason }) => {
          const { jm, jd } = toJalali(d);
          const active = info.key === day;
          return (
            <button
              key={info.key}
              type="button"
              role="option"
              data-key={info.key}
              aria-selected={active}
              aria-disabled={!!reason}
              tabIndex={active ? 0 : -1}
              title={reason ?? info.holiday?.title}
              aria-label={`${info.label}${reason ? `، ${reason}` : ""}`}
              onClick={() => !reason && setDay(info.key)}
              className={cn(
                "flex w-14 shrink-0 cursor-pointer flex-col items-center gap-0.5 rounded-control border-line border-border py-2 transition-colors focus-visible:outline-2 focus-visible:outline-ring",
                active ? "border-primary bg-primary text-primary-foreground" : "hover:bg-accent",
                reason && "cursor-not-allowed opacity-45 hover:bg-transparent",
                !active && info.holiday && "text-destructive",
              )}
            >
              <span className="text-[10px] opacity-80">{info.isToday ? "امروز" : JALALI_WEEKDAYS_SHORT[jalaliWeekday(d)]}</span>
              <span className="text-base font-bold tabular-nums leading-none">{fa(jd)}</span>
              <span className="text-[10px] opacity-80">{JALALI_MONTHS[jm - 1]}</span>
              {reason && <span aria-hidden className="h-0.5 w-5 rounded-full bg-current opacity-60" />}
            </button>
          );
        })}
      </div>

      {current.reason ? (
        <CalendarEmpty>{current.reason}</CalendarEmpty>
      ) : groups.length === 0 || free === 0 ? (
        <div className="space-y-2">
          <CalendarEmpty>برای {shortDay(fromKey(current.info.key))} وقت خالی نمانده.</CalendarEmpty>
          {nextOpen && (
            <button type="button" onClick={() => setDay(nextOpen.info.key)} className="w-full cursor-pointer rounded-control border-line border-border py-2 text-sm transition-colors hover:bg-accent">
              اولین روز بعدی: {nextOpen.info.label.split("،")[0]}
            </button>
          )}
        </div>
      ) : (
        <div className="space-y-3">
          {groups.map((g) => (
            <div key={g.name}>
              <p className="mb-1.5 text-xs font-medium text-muted-foreground">{g.name}</p>
              <div role="radiogroup" aria-label={g.name} className="grid grid-cols-3 gap-2 sm:grid-cols-4">
                {g.items.map((s) => {
                  const on = selectedKey === s.start.getTime();
                  const off = s.state !== "free";
                  return (
                    <button
                      key={s.start.getTime()}
                      type="button"
                      role="radio"
                      aria-checked={on}
                      disabled={off}
                      aria-label={`${formatTimeRange(s.start, s.end, tz)}${s.state === "full" ? "، پر شده" : s.state === "past" ? "، گذشته" : capacity > 1 ? `، ${fa(s.left)} جای خالی` : ""}`}
                      onClick={() => setSlot(on ? null : { start: s.start, end: s.end })}
                      className={cn(
                        "flex h-11 cursor-pointer flex-col items-center justify-center rounded-control border-line border-border text-sm tabular-nums transition-colors focus-visible:outline-2 focus-visible:outline-ring",
                        on ? "border-primary bg-primary text-primary-foreground" : "hover:bg-accent",
                        off && "cursor-not-allowed line-through opacity-40 hover:bg-transparent",
                      )}
                    >
                      {formatTime(s.start, tz)}
                      {capacity > 1 && !off && <span className={cn("text-[10px] no-underline", on ? "opacity-80" : "text-muted-foreground")}>{fa(s.left)} جای خالی</span>}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      <p className="text-xs text-muted-foreground" aria-live="polite">
        {slot ? `${dayInfo(fromKey(zonedKey(slot.start, tz)), settings, today).label.split("،")[0]}، ساعت ${formatTimeRange(slot.start, slot.end, tz)}` : `${fa(free)} وقت خالی در ${shortDay(fromKey(current.info.key))}`}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, formatJalali, toJalali } from "@/lib/jalali";
import { addDays, dayKey, diffDays, eventColor, shortDay, timeTicks, type Zoom } from "@/lib/calendar-utils";
import { SegmentedControl } from "@/components/ui/segmented-control";
import { SrOnly, dayInfo, useCalendar, useControllable, useToday } from "@/components/calendar/calendar-core";

export type GanttTask = {
  id: string;
  title: string;
  /** First day (local calendar day). */
  start: Date;
  /** Last day, included. Same as start for a one-day task or a milestone. */
  end: Date;
  /** 0–1 */
  progress?: number;
  /** 1–7 palette slot or a CSS color. */
  color?: number | string;
  /** Tasks that must finish before this one starts (drawn as arrows). */
  dependsOn?: string[];
  milestone?: boolean;
  /** Optional group label shown above its first task. */
  group?: string;
};

export interface GanttChartProps {
  tasks: GanttTask[];
  zoom?: Zoom;
  defaultZoom?: Zoom;
  onZoomChange?: (zoom: Zoom) => void;
  /** Visible range. Defaults to the tasks' span plus a few days. */
  from?: Date;
  to?: Date;
  onTaskClick?: (task: GanttTask) => void;
  /** Turns on drag to move, drag the edges to resize, and Alt+arrows on a focused bar. */
  onTaskChange?: (task: GanttTask, start: Date, end: Date) => void;
  /** Width of the task list on the right. Default 200. */
  listWidth?: number;
  rowHeight?: number;
  /** Tint holidays (and the weekend at day zoom). Default true. */
  showHolidays?: boolean;
  className?: string;
}

const DAY_WIDTH: Record<Zoom, number> = { day: 34, week: 16, month: 5 };
const ZOOM_LABELS: Record<Zoom, string> = { day: "روز", week: "هفته", month: "ماه" };
const HEAD = 48;

type Drag = { id: string; mode: "move" | "start" | "end"; x0: number; delta: number };

/**
 * گانت. Tasks on a Jalali time axis that runs right to left, with the list
 * on the right, progress inside each bar, dependency arrows, milestones, a
 * today line and holidays tinted. Zoom by day, week or month.
 */
export function GanttChart({ tasks, zoom, defaultZoom = "day", onZoomChange, from, to, onTaskClick, onTaskChange, listWidth = 200, rowHeight = 36, showHolidays = true, className }: GanttChartProps) {
  const settings = useCalendar();
  const today = useToday();
  const [z, setZoom] = useControllable(zoom, defaultZoom, onZoomChange);
  const [drag, setDrag] = React.useState<Drag | null>(null);
  const dw = DAY_WIDTH[z];

  const range = React.useMemo(() => {
    if (from && to) return { start: from, end: to };
    const s = tasks.reduce((m, t) => (t.start < m ? t.start : m), tasks[0]?.start ?? today);
    const e = tasks.reduce((m, t) => (t.end > m ? t.end : m), tasks[0]?.end ?? today);
    const pad = z === "day" ? 3 : z === "week" ? 7 : 20;
    return { start: from ?? addDays(s, -pad), end: to ?? addDays(e, pad) };
  }, [tasks, from, to, z, today]);

  const days = diffDays(range.start, range.end) + 1;
  const width = days * dw;
  const off = (d: Date) => diffDays(range.start, d) * dw;

  // Apply an in-progress drag to a task's days.
  const shown = (t: GanttTask) => {
    if (!drag || drag.id !== t.id) return { start: t.start, end: t.end };
    const s = drag.mode === "end" ? t.start : addDays(t.start, drag.delta);
    const e = drag.mode === "start" ? t.end : addDays(t.end, drag.delta);
    return s > e ? { start: e, end: e } : { start: s, end: e };
  };

  const rows: ({ kind: "group"; label: string } | { kind: "task"; task: GanttTask; index: number })[] = [];
  tasks.forEach((task, index) => {
    if (task.group && task.group !== tasks[index - 1]?.group) rows.push({ kind: "group", label: task.group });
    rows.push({ kind: "task", task, index });
  });
  const rowOf = new Map(rows.map((r, i) => [r.kind === "task" ? r.task.id : `g${i}`, i]));
  const height = rows.length * rowHeight;

  const dayTicks = timeTicks(range.start, addDays(range.end, 1), z === "day" ? "day" : z === "week" ? "week" : "month");
  const monthTicks = timeTicks(range.start, addDays(range.end, 1), "month");
  // Name the month the range starts in, unless it starts on the 1st.
  if (toJalali(range.start).jd > 1 && toJalali(range.start).jd < 25) monthTicks.unshift({ date: range.start, label: JALALI_MONTHS[toJalali(range.start).jm - 1], major: false });
  const offDays = showHolidays
    ? Array.from({ length: days }, (_, i) => addDays(range.start, i)).filter((d) => {
        const info = dayInfo(d, settings, today);
        return info.holiday || (z === "day" && info.isWeekend);
      })
    : [];

  function onDown(e: React.PointerEvent, task: GanttTask, mode: Drag["mode"]) {
    e.stopPropagation();
    if (e.button !== 0) return;
    if (!onTaskChange) return;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    setDrag({ id: task.id, mode, x0: e.clientX, delta: 0 });
  }
  function onMove(e: React.PointerEvent) {
    if (!drag) return;
    // Moving left is later in time.
    setDrag({ ...drag, delta: -Math.round((e.clientX - drag.x0) / dw) });
  }
  function onUp(task: GanttTask) {
    if (!drag) return onTaskClick?.(task);
    const s = shown(task);
    if (drag.delta) onTaskChange?.(task, s.start, s.end);
    else onTaskClick?.(task);
    setDrag(null);
  }
  function onKey(e: React.KeyboardEvent, task: GanttTask) {
    if (e.key === "Enter") return onTaskClick?.(task);
    if (!onTaskChange || !e.altKey) return;
    const dir = e.key === "ArrowLeft" ? 1 : e.key === "ArrowRight" ? -1 : 0;
    if (!dir) return;
    e.preventDefault();
    if (e.shiftKey) onTaskChange(task, task.start, addDays(task.end, dir) < task.start ? task.start : addDays(task.end, dir));
    else onTaskChange(task, addDays(task.start, dir), addDays(task.end, dir));
  }

  const todayOff = diffDays(range.start, today);
  const scroller = React.useRef<HTMLDivElement>(null);
  // Open with today in view. In RTL, scrollLeft runs from 0 (right edge) to negative.
  React.useEffect(() => {
    const el = scroller.current;
    if (!el || todayOff < 0 || todayOff >= days) return;
    el.scrollLeft = -Math.max(0, todayOff * dw - el.clientWidth / 2);
    // Only when the zoom or range changes, not while dragging.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dw, range.start.getTime()]);
  const byId = new Map(tasks.map((t) => [t.id, t]));

  return (
    <div className={cn("w-full space-y-3", className)}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">
          {formatJalali(range.start, { year: toJalali(range.start).jy !== toJalali(range.end).jy })} تا {formatJalali(range.end)}
        </p>
        <SegmentedControl size="sm" aria-label="بزرگ‌نمایی" value={z} onChange={(v) => setZoom(v as Zoom)} options={(["day", "week", "month"] as Zoom[]).map((v) => ({ value: v, label: ZOOM_LABELS[v] }))} />
      </div>
      <div className="flex overflow-hidden rounded-surface border-line bg-card">
        {/* task list (right) */}
        <div className="shrink-0 border-e" style={{ width: listWidth }}>
          <div className="flex items-end border-b px-3 pb-1.5 text-[11px] text-muted-foreground" style={{ height: HEAD }}>
            کار
          </div>
          {rows.map((r, i) =>
            r.kind === "group" ? (
              <div key={`g${i}`} className="flex items-center bg-muted/40 px-3 text-xs font-bold" style={{ height: rowHeight }}>
                {r.label}
              </div>
            ) : (
              <div key={r.task.id} className="flex items-center gap-2 border-b border-border/60 px-3" style={{ height: rowHeight }}>
                <span aria-hidden className="size-2 shrink-0 rounded-full" style={{ background: eventColor(r.task.color, r.index) }} />
                <span className="min-w-0 flex-1 truncate text-sm">{r.task.title}</span>
                <span className="shrink-0 text-[10px] text-muted-foreground tabular-nums">{r.task.milestone ? "نقطه" : `${fa(diffDays(r.task.start, r.task.end) + 1)} روز`}</span>
              </div>
            ),
          )}
        </div>
        {/* timeline (scrolls) */}
        <div ref={scroller} className="min-w-0 flex-1 overflow-x-auto">
          <div className="relative" style={{ width, height: HEAD + height }}>
            {/* header */}
            <div className="absolute inset-x-0 top-0 border-b" style={{ height: HEAD }}>
              {monthTicks.map((t) => (
                <span key={`m${dayKey(t.date)}`} className="absolute top-1 border-s px-1.5 text-[11px] font-semibold whitespace-nowrap" style={{ insetInlineStart: off(t.date) }}>
                  {t.label} {fa(toJalali(t.date).jy)}
                </span>
              ))}
              {z !== "month" &&
                dayTicks.map((t) => (
                  <span
                    key={`d${dayKey(t.date)}`}
                    className={cn("absolute bottom-1 text-center text-[10px] tabular-nums text-muted-foreground", t.major && "font-semibold text-foreground")}
                    style={{ insetInlineStart: off(t.date), width: z === "day" ? dw : undefined, paddingInlineStart: z === "week" ? 4 : undefined }}
                  >
                    {t.label}
                  </span>
                ))}
            </div>
            {/* grid, holidays, today */}
            <div className="absolute inset-x-0 bottom-0" style={{ top: HEAD }}>
              {offDays.map((d) => (
                <span key={dayKey(d)} className="absolute inset-y-0 bg-destructive/[0.06]" style={{ insetInlineStart: off(d), width: Math.max(dw, 2) }} />
              ))}
              {(z === "day" ? dayTicks : monthTicks).map((t) => (
                <span key={`l${dayKey(t.date)}`} className={cn("absolute inset-y-0 border-s", t.major ? "border-border" : "border-border/40")} style={{ insetInlineStart: off(t.date) }} />
              ))}
              {rows.map((r, i) => (
                <span key={`r${i}`} className={cn("absolute inset-x-0 border-b border-border/60", r.kind === "group" && "bg-muted/40")} style={{ top: i * rowHeight, height: rowHeight }} />
              ))}
              {todayOff >= 0 && todayOff < days && (
                <span className="absolute inset-y-0 z-10 w-0.5 bg-destructive" style={{ insetInlineStart: todayOff * dw + dw / 2 }} title={`امروز، ${shortDay(today)}`} />
              )}
            </div>
            {/* dependency arrows (physical coords: x = width - offset) */}
            <svg className="pointer-events-none absolute inset-x-0 z-10 overflow-visible" style={{ top: HEAD }} width={width} height={height} aria-hidden>
              <defs>
                <marker id="gantt-arrow" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto">
                  <path d="M0,0 L6,3 L0,6 z" fill="var(--color-muted-foreground)" />
                </marker>
              </defs>
              {tasks.flatMap((t) =>
                (t.dependsOn ?? []).map((id) => {
                  const p = byId.get(id);
                  if (!p) return null;
                  const ps = shown(p);
                  const ts = shown(t);
                  const x1 = width - (off(ps.end) + dw);
                  const y1 = rowOf.get(p.id)! * rowHeight + rowHeight / 2;
                  const x2 = width - off(ts.start);
                  const y2 = rowOf.get(t.id)! * rowHeight + rowHeight / 2;
                  return <path key={`${id}-${t.id}`} d={`M${x1},${y1} H${x1 - 6} V${y2} H${x2 + 2}`} fill="none" stroke="var(--color-muted-foreground)" strokeWidth={1.25} markerEnd="url(#gantt-arrow)" opacity={0.7} />;
                }),
              )}
            </svg>
            {/* bars */}
            <div className="absolute inset-x-0 z-20" style={{ top: HEAD, height }} onPointerMove={onMove} onPointerCancel={() => setDrag(null)}>
              {rows.map((r) => {
                if (r.kind !== "task") return null;
                const t = r.task;
                const s = shown(t);
                const color = eventColor(t.color, r.index);
                const top = rowOf.get(t.id)! * rowHeight;
                const label = `${t.title}، ${formatJalali(s.start, { year: false })} تا ${formatJalali(s.end, { year: false })}${t.progress != null ? `، ${fa(Math.round(t.progress * 100))}٪ انجام شده` : ""}`;
                if (t.milestone) {
                  return (
                    <button
                      key={t.id}
                      type="button"
                      aria-label={`نقطه‌ی عطف: ${label}`}
                      onPointerDown={(e) => onDown(e, t, "move")}
                      onPointerUp={() => onUp(t)}
                      onKeyDown={(e) => onKey(e, t)}
                      className="absolute flex cursor-pointer items-center gap-1.5 focus-visible:outline-2 focus-visible:outline-ring"
                      style={{ insetInlineStart: off(s.start) + dw / 2 - 7, top: top + rowHeight / 2 - 7, height: 14 }}
                    >
                      <span className="size-3.5 rotate-45 rounded-[2px]" style={{ background: color }} />
                      <span className="text-[11px] font-medium whitespace-nowrap">{t.title}</span>
                    </button>
                  );
                }
                const w = (diffDays(s.start, s.end) + 1) * dw;
                return (
                  <div key={t.id} className="absolute" style={{ insetInlineStart: off(s.start), width: w, top: top + 6, height: rowHeight - 12 }}>
                    <button
                      type="button"
                      aria-label={label}
                      onPointerDown={(e) => onDown(e, t, "move")}
                      onPointerUp={() => onUp(t)}
                      onKeyDown={(e) => onKey(e, t)}
                      className={cn("relative flex size-full items-center overflow-hidden rounded-control text-start focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-ring", onTaskChange ? "cursor-grab touch-none active:cursor-grabbing" : "cursor-pointer")}
                      style={{ background: `color-mix(in oklch, ${color} 28%, var(--color-card))` }}
                    >
                      <span className="absolute inset-y-0 start-0" style={{ width: `${(t.progress ?? 0) * 100}%`, background: color }} />
                      {w > 56 && <span className="relative truncate px-2 text-[11px] font-medium mix-blend-normal">{t.title}</span>}
                    </button>
                    {onTaskChange && (
                      <>
                        <span aria-hidden onPointerDown={(e) => onDown(e, t, "start")} onPointerUp={() => onUp(t)} className="absolute inset-y-0 start-0 w-1.5 cursor-ew-resize" />
                        <span aria-hidden onPointerDown={(e) => onDown(e, t, "end")} onPointerUp={() => onUp(t)} className="absolute inset-y-0 end-0 w-1.5 cursor-ew-resize" />
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
      <SrOnly>
        <table>
          <caption>برنامه‌ی کارها</caption>
          <thead>
            <tr>
              <th>کار</th>
              <th>شروع</th>
              <th>پایان</th>
              <th>پیشرفت</th>
            </tr>
          </thead>
          <tbody>
            {tasks.map((t) => (
              <tr key={t.id}>
                <td>{t.title}</td>
                <td>{formatJalali(t.start)}</td>
                <td>{formatJalali(t.end)}</td>
                <td>{t.progress != null ? `${fa(Math.round(t.progress * 100))}٪` : "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </SrOnly>
    </div>
  );
}

"use client";

import * as React from "react";
import { AlertTriangle, Check, Plus } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { JALALI_WEEKDAYS, jalaliWeekday } from "@/lib/jalali";
import { addDays, dayKey, eventColor, formatDuration, parseHm, shortDay, startOfJalaliWeek, weekDates, type Resource } from "@/lib/calendar-utils";
import { Popover } from "@/components/ui/popover";
import { CalendarToolbar, dayInfo, useCalendar, useControllable, useToday } from "@/components/calendar/calendar-core";

export type ShiftType = { id: string; label: string; start: string; end: string; color?: number | string };
export type Shift = { id: string; resourceId: string; date: Date; type: string };

export const DEFAULT_SHIFTS: ShiftType[] = [
  { id: "morning", label: "صبح", start: "07:00", end: "15:00", color: 3 },
  { id: "evening", label: "عصر", start: "15:00", end: "23:00", color: 2 },
  { id: "night", label: "شب", start: "23:00", end: "07:00", color: 5 },
];

export interface ShiftSchedulerProps {
  resources: Resource[];
  shifts?: Shift[];
  defaultShifts?: Shift[];
  onShiftsChange?: (shifts: Shift[]) => void;
  shiftTypes?: ShiftType[];
  /** Any day in the week to show (controlled). */
  week?: Date;
  defaultWeek?: Date;
  onWeekChange?: (week: Date) => void;
  /** Weekly hours before a warning. Default 44, the Iranian labour-law week. */
  maxHours?: number;
  /** Minimum rest between two shifts, in hours. Default 12. */
  minRest?: number;
  /** Replace the built-in shift menu, e.g. to open your own dialog. */
  onCellClick?: (resourceId: string, date: Date) => void;
  className?: string;
}

/** Enter and Space click a span that acts as a button. */
const pressOnKey = (e: React.KeyboardEvent<HTMLElement>) => {
  if (e.key !== "Enter" && e.key !== " ") return;
  e.preventDefault();
  e.currentTarget.click();
};

const mins = (t: ShiftType) => {
  const a = parseHm(t.start);
  let b = parseHm(t.end);
  if (b <= a) b += 1440;
  return [a, b] as const;
};

/** Per person: hours this week, and cells where rest is too short or shifts overlap. */
function analyse(resourceId: string, shifts: Shift[], types: Map<string, ShiftType>, weekStart: Date, minRest: number) {
  const items = shifts
    .filter((s) => s.resourceId === resourceId && types.has(s.type))
    .map((s) => {
      const [a, b] = mins(types.get(s.type)!);
      const base = Math.round((s.date.getTime() - weekStart.getTime()) / 86_400_000) * 1440;
      return { s, a: base + a, b: base + b };
    })
    .sort((x, y) => x.a - y.a);
  const minutes = items.reduce((n, i) => n + (i.b - i.a), 0);
  const flags = new Map<string, string>();
  for (let i = 1; i < items.length; i += 1) {
    const gap = items[i].a - items[i - 1].b;
    const k = dayKey(items[i].s.date);
    if (gap < 0) flags.set(k, "دو شیفت هم‌پوشانی دارند");
    else if (gap < minRest * 60) flags.set(k, `فقط ${formatDuration(gap)} استراحت بین دو شیفت`);
  }
  return { minutes, flags };
}

/**
 * برنامه‌ی شیفت. People down the right, شنبه to جمعه across, shift chips in
 * each cell, weekly hours per person with a warning past the limit, and a
 * flag when rest between shifts is too short. Holidays are tinted so you can
 * see who works on them.
 */
export function ShiftScheduler({
  resources,
  shifts,
  defaultShifts = [],
  onShiftsChange,
  shiftTypes = DEFAULT_SHIFTS,
  week,
  defaultWeek,
  onWeekChange,
  maxHours = 44,
  minRest = 12,
  onCellClick,
  className,
}: ShiftSchedulerProps) {
  const settings = useCalendar();
  const today = useToday();
  const [list, setList] = useControllable(shifts, defaultShifts, onShiftsChange);
  const [cursor, setCursor] = useControllable(week, defaultWeek ?? today, onWeekChange);
  const days = weekDates(cursor);
  const keys = days.map(dayKey);
  const start = startOfJalaliWeek(cursor);
  const types = React.useMemo(() => new Map(shiftTypes.map((t) => [t.id, t])), [shiftTypes]);
  const typeIndex = new Map(shiftTypes.map((t, i) => [t.id, i]));

  const cell = (rid: string, key: string) => list.filter((s) => s.resourceId === rid && dayKey(s.date) === key).sort((a, b) => (typeIndex.get(a.type) ?? 0) - (typeIndex.get(b.type) ?? 0));
  const toggle = (rid: string, date: Date, type: string) => {
    const k = dayKey(date);
    const hit = list.find((s) => s.resourceId === rid && dayKey(s.date) === k && s.type === type);
    setList(hit ? list.filter((s) => s !== hit) : [...list, { id: `${rid}-${k}-${type}`, resourceId: rid, date, type }]);
  };

  return (
    <div className={cn("w-full space-y-3", className)}>
      <CalendarToolbar
        title={`${shortDay(days[0])} تا ${shortDay(days[6])}`}
        subtitle={`${fa(list.filter((s) => keys.includes(dayKey(s.date))).length)} شیفت این هفته`}
        onPrev={() => setCursor(addDays(cursor, -7))}
        onNext={() => setCursor(addDays(cursor, 7))}
        onToday={() => setCursor(today)}
        prevLabel="هفته‌ی قبل"
        nextLabel="هفته‌ی بعد"
      >
        <ul className="flex flex-wrap gap-3 text-[11px] text-muted-foreground">
          {shiftTypes.map((t, i) => (
            <li key={t.id} className="flex items-center gap-1">
              <span aria-hidden className="size-2 rounded-full" style={{ background: eventColor(t.color, i) }} />
              {t.label} <span className="tabular-nums">{fa(t.start)}–{fa(t.end)}</span>
            </li>
          ))}
        </ul>
      </CalendarToolbar>
      <div className="overflow-x-auto rounded-surface border-line bg-card">
        <table className="w-full min-w-[760px] border-collapse text-sm">
          <thead>
            <tr className="border-b">
              <th scope="col" className="w-44 px-3 py-2 text-start text-[11px] font-medium text-muted-foreground">
                نفر
              </th>
              {days.map((d) => {
                const info = dayInfo(d, settings, today);
                const off = info.holiday || info.isWeekend;
                return (
                  <th key={info.key} scope="col" title={info.holiday?.title} className={cn("border-s px-1 py-2 text-center font-medium", off && "bg-destructive/[0.05] text-destructive", info.isToday && "bg-accent")}>
                    <span className="block text-[11px]">{JALALI_WEEKDAYS[jalaliWeekday(d)]}</span>
                    <span className="block text-xs tabular-nums">{shortDay(d)}</span>
                    {info.holiday && <span className="block truncate text-[9px] font-normal">{info.holiday.title}</span>}
                  </th>
                );
              })}
              <th scope="col" className="w-20 border-s px-2 py-2 text-center text-[11px] font-medium text-muted-foreground">
                ساعت
              </th>
            </tr>
          </thead>
          <tbody>
            {resources.map((r) => {
              const { minutes, flags } = analyse(r.id, list.filter((s) => keys.includes(dayKey(s.date))), types, start, minRest);
              const over = minutes > maxHours * 60;
              return (
                <tr key={r.id} className="border-b last:border-b-0">
                  <th scope="row" className="px-3 py-2 text-start font-normal">
                    <span className="block truncate text-sm font-medium">{r.title}</span>
                    {r.subtitle && <span className="block truncate text-[11px] text-muted-foreground">{r.subtitle}</span>}
                  </th>
                  {days.map((d) => {
                    const info = dayInfo(d, settings, today);
                    const items = cell(r.id, info.key);
                    const flag = flags.get(info.key);
                    const label = `${r.title}، ${info.label}، ${items.length ? items.map((s) => types.get(s.type)?.label).join(" و ") : "بدون شیفت"}${flag ? `، هشدار: ${flag}` : ""}`;
                    const chips = (
                      <span className="flex min-h-14 w-full flex-col items-stretch justify-center gap-1 p-1">
                        {items.map((s) => {
                          const t = types.get(s.type);
                          if (!t) return null;
                          const color = eventColor(t.color, typeIndex.get(t.id) ?? 0);
                          return (
                            <span key={s.id} className="truncate rounded-control border-s-[3px] px-1.5 py-0.5 text-start text-[11px] font-medium" style={{ borderColor: color, background: `color-mix(in oklch, ${color} 16%, transparent)` }}>
                              {t.label}
                            </span>
                          );
                        })}
                        {!items.length && <Plus aria-hidden className="mx-auto size-3.5 text-muted-foreground/40" />}
                      </span>
                    );
                    return (
                      <td key={info.key} className={cn("relative border-s p-0 align-middle [&>div]:block [&>div>span]:flex", (info.holiday || info.isWeekend) && "bg-destructive/[0.04]", flag && "ring-2 ring-inset ring-warning/70")}>
                        {flag && <AlertTriangle aria-hidden className="absolute top-1 end-1 size-3 text-warning" />}
                        {onCellClick ? (
                          <button type="button" aria-label={label} title={flag} onClick={() => onCellClick(r.id, d)} className="block w-full cursor-pointer transition-colors hover:bg-accent/60 focus-visible:outline-2 focus-visible:outline-ring">
                            {chips}
                          </button>
                        ) : (
                          <Popover
                            align="center"
                            trigger={
                              <span role="button" tabIndex={0} aria-label={label} title={flag} onKeyDown={pressOnKey} className="block w-full cursor-pointer transition-colors hover:bg-accent/60 focus-visible:outline-2 focus-visible:outline-ring">
                                {chips}
                              </span>
                            }
                          >
                            <div className="w-48" role="menu" aria-label={`شیفت ${r.title}، ${shortDay(d)}`}>
                              <p className="px-2 pb-1 pt-0.5 text-[11px] text-muted-foreground">
                                {r.title} · {shortDay(d)}
                              </p>
                              {shiftTypes.map((t, i) => {
                                const on = items.some((s) => s.type === t.id);
                                return (
                                  <button
                                    key={t.id}
                                    type="button"
                                    role="menuitemcheckbox"
                                    aria-checked={on}
                                    onClick={() => toggle(r.id, d, t.id)}
                                    className="flex w-full cursor-pointer items-center gap-2 rounded-control px-2 py-1.5 text-start text-sm hover:bg-accent"
                                  >
                                    <span aria-hidden className="size-2 rounded-full" style={{ background: eventColor(t.color, i) }} />
                                    <span className="flex-1">{t.label}</span>
                                    <span className="text-[10px] tabular-nums text-muted-foreground">
                                      {fa(t.start)}–{fa(t.end)}
                                    </span>
                                    <Check className={cn("size-3.5", on ? "opacity-100" : "opacity-0")} />
                                  </button>
                                );
                              })}
                            </div>
                          </Popover>
                        )}
                      </td>
                    );
                  })}
                  <td className={cn("border-s px-2 text-center text-xs tabular-nums", over && "font-bold text-warning")} title={over ? `بیشتر از ${fa(maxHours)} ساعت در هفته` : undefined}>
                    {fa(Math.round((minutes / 60) * 10) / 10).replace(".", "٫")}
                    {over && <AlertTriangle aria-label="بیش از حد مجاز" className="mx-auto mt-0.5 size-3" />}
                  </td>
                </tr>
              );
            })}
          </tbody>
          <tfoot>
            <tr className="border-t bg-muted/40 text-[11px] text-muted-foreground">
              <th scope="row" className="px-3 py-1.5 text-start font-medium">
                پوشش
              </th>
              {keys.map((k) => (
                <td key={k} className="border-s px-1 py-1.5 text-center">
                  {shiftTypes.map((t) => {
                    const n = list.filter((s) => dayKey(s.date) === k && s.type === t.id).length;
                    return (
                      <span key={t.id} className={cn("block tabular-nums", !n && "text-destructive/80")}>
                        {t.label} {fa(n)}
                      </span>
                    );
                  })}
                </td>
              ))}
              <td className="border-s" />
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { MapPin, Moon, Sun, Sunrise, Sunset } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";
import { formatHijri } from "@/lib/hijri";
import { addDays, formatDuration, formatTime, TEHRAN } from "@/lib/calendar-utils";
import { CalendarToolbar, useNow, useToday } from "@/components/calendar/calendar-core";

export type PrayerLocation = { name: string; lat: number; lng: number; /** Meters above sea level. Official Iranian tables leave it out, so only pass it to match a sea-level-corrected source. */ elevation?: number };

/** Provincial capitals and big cities. Coordinates of the city center. */
export const IRAN_CITIES: PrayerLocation[] = [
  { name: "تهران", lat: 35.6892, lng: 51.389 },
  { name: "مشهد", lat: 36.297, lng: 59.6062 },
  { name: "اصفهان", lat: 32.6539, lng: 51.666 },
  { name: "شیراز", lat: 29.5918, lng: 52.5837 },
  { name: "تبریز", lat: 38.08, lng: 46.2919 },
  { name: "کرج", lat: 35.84, lng: 50.9391 },
  { name: "قم", lat: 34.6399, lng: 50.8759 },
  { name: "اهواز", lat: 31.3183, lng: 48.6706 },
  { name: "کرمانشاه", lat: 34.3142, lng: 47.065 },
  { name: "ارومیه", lat: 37.5527, lng: 45.0761 },
  { name: "رشت", lat: 37.2808, lng: 49.5832 },
  { name: "ساری", lat: 36.5633, lng: 53.0601 },
  { name: "همدان", lat: 34.7983, lng: 48.5148 },
  { name: "یزد", lat: 31.8974, lng: 54.3569 },
  { name: "کرمان", lat: 30.2839, lng: 57.0834 },
  { name: "زاهدان", lat: 29.4963, lng: 60.8629 },
  { name: "بندرعباس", lat: 27.1832, lng: 56.2666 },
  { name: "بوشهر", lat: 28.9234, lng: 50.8203 },
];

export type PrayerKey = "fajr" | "sunrise" | "dhuhr" | "sunset" | "maghrib" | "midnight";
export type PrayerTimesResult = Record<PrayerKey, Date>;

export const PRAYER_LABELS: Record<PrayerKey, string> = {
  fajr: "اذان صبح",
  sunrise: "طلوع آفتاب",
  dhuhr: "اذان ظهر",
  sunset: "غروب آفتاب",
  maghrib: "اذان مغرب",
  midnight: "نیمه‌شب شرعی",
};

/** Sun depression angles of the Institute of Geophysics, University of Tehran. */
export type PrayerMethod = { fajr: number; maghrib: number };
export const TEHRAN_METHOD: PrayerMethod = { fajr: 17.7, maghrib: 4.5 };

const rad = (d: number) => (d * Math.PI) / 180;
const deg = (r: number) => (r * 180) / Math.PI;
const fix = (a: number, b: number) => ((a % b) + b) % b;

/** Declination and equation of time for a Julian date. */
function sun(jd: number) {
  const D = jd - 2451545;
  const g = fix(357.529 + 0.98560028 * D, 360);
  const q = fix(280.459 + 0.98564736 * D, 360);
  const L = fix(q + 1.915 * Math.sin(rad(g)) + 0.02 * Math.sin(rad(2 * g)), 360);
  const e = 23.439 - 0.00000036 * D;
  const ra = fix(deg(Math.atan2(Math.cos(rad(e)) * Math.sin(rad(L)), Math.cos(rad(L)))) / 15, 24);
  return { decl: deg(Math.asin(Math.sin(rad(e)) * Math.sin(rad(L)))), eqt: q / 15 - ra };
}

function julian(y: number, m: number, d: number) {
  if (m <= 2) { y -= 1; m += 12; }
  const a = Math.floor(y / 100);
  return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + d + (2 - a + Math.floor(a / 4)) - 1524.5;
}

/**
 * Prayer times of one calendar day (the local day of `date`) at a place, as instants.
 * Shia times as published in Iran: Maghrib at 4.5° below the horizon and midnight halfway
 * from sunset to the next Fajr. Accurate to about a minute; official tables may round.
 */
export function prayerTimes(date: Date, loc: PrayerLocation, method: PrayerMethod = TEHRAN_METHOD): PrayerTimesResult {
  const y = date.getFullYear(), m = date.getMonth() + 1, d = date.getDate();
  const jd = julian(y, m, d) - loc.lng / 360;
  const lat = rad(loc.lat);
  const noon = (t: number) => fix(12 - sun(jd + t).eqt, 24);
  const angleTime = (angle: number, t: number, before: boolean) => {
    const { decl } = sun(jd + t);
    const cos = (-Math.sin(rad(angle)) - Math.sin(rad(decl)) * Math.sin(lat)) / (Math.cos(rad(decl)) * Math.cos(lat));
    const T = deg(Math.acos(Math.max(-1, Math.min(1, cos)))) / 15;
    return noon(t) + (before ? -T : T);
  };
  const horizon = 0.833 + 0.0347 * Math.sqrt(loc.elevation ?? 0);
  // One refinement pass from rough guesses (hours / 24) is enough for minute accuracy.
  const h = {
    fajr: angleTime(method.fajr, 5 / 24, true),
    sunrise: angleTime(horizon, 6 / 24, true),
    dhuhr: noon(12 / 24),
    sunset: angleTime(horizon, 18 / 24, false),
    maghrib: angleTime(method.maghrib, 18 / 24, false),
  };
  const midnight = h.sunset + (h.fajr + 24 - h.sunset) / 2;
  // Hours here are local mean solar time; shift to UTC and build real instants.
  const at = (hours: number) => new Date(Date.UTC(y, m - 1, d) + (hours - loc.lng / 15) * 3_600_000);
  return { fajr: at(h.fajr), sunrise: at(h.sunrise), dhuhr: at(h.dhuhr), sunset: at(h.sunset), maghrib: at(h.maghrib), midnight: at(midnight) };
}

const ORDER: PrayerKey[] = ["fajr", "sunrise", "dhuhr", "sunset", "maghrib", "midnight"];
const ICON: Record<PrayerKey, typeof Sun> = { fajr: Moon, sunrise: Sunrise, dhuhr: Sun, sunset: Sunset, maghrib: Sunset, midnight: Moon };
const AZAN: PrayerKey[] = ["fajr", "dhuhr", "maghrib"];

function PrayerIcon({ k, className }: { k: PrayerKey; className?: string }) {
  return React.createElement(ICON[k], { className, "aria-hidden": true });
}

export interface PrayerTimesProps {
  /** A city from IRAN_CITIES by name, or any place. Default تهران. */
  location?: string | PrayerLocation;
  /** Lets the user pick another city. Pass a list or true for IRAN_CITIES. */
  cities?: PrayerLocation[] | boolean;
  onLocationChange?: (loc: PrayerLocation) => void;
  /** Day shown. Defaults to today; previous/next buttons move it. */
  date?: Date;
  method?: PrayerMethod;
  timeZone?: string;
  /** Show only the three azan times. */
  azanOnly?: boolean;
  /** «list» rows or a compact «strip» of tiles. */
  variant?: "list" | "strip";
  className?: string;
}

/**
 * اوقات شرعی. Today's azan and sun times for an Iranian city, computed in the browser
 * with the Tehran University method, with the next one highlighted and a live countdown.
 */
export function PrayerTimes({ location = "تهران", cities, onLocationChange, date, method, timeZone = TEHRAN, azanOnly, variant = "list", className }: PrayerTimesProps) {
  const today = useToday();
  const now = useNow();
  const [offset, setOffset] = React.useState(0);
  const list = cities === true ? IRAN_CITIES : cities || null;
  const initial = typeof location === "string" ? IRAN_CITIES.find((c) => c.name === location) ?? IRAN_CITIES[0] : location;
  const [picked, setPicked] = React.useState<PrayerLocation>(initial);
  const loc = list ? picked : initial;
  const day = date ?? addDays(today, offset);
  const times = React.useMemo(() => prayerTimes(day, loc, method), [day, loc, method]);
  const keys = azanOnly ? AZAN : ORDER;
  const next = now ? keys.find((k) => times[k] > now) : undefined;
  const left = next && now ? Math.max(1, Math.ceil((times[next].getTime() - now.getTime()) / 60_000)) : 0;
  const selectId = React.useId();

  const head = (
    <div className="flex flex-wrap items-center justify-between gap-2">
      {date ? (
        <div>
          <p className="font-display text-base font-bold">{formatJalali(day, { weekday: true })}</p>
          <p className="text-[11px] text-muted-foreground">{formatHijri(day)}</p>
        </div>
      ) : (
        <CalendarToolbar
          title={formatJalali(day, { weekday: true })}
          subtitle={formatHijri(day)}
          onPrev={() => setOffset((o) => o - 1)}
          onNext={() => setOffset((o) => o + 1)}
          onToday={offset ? () => setOffset(0) : undefined}
          prevLabel="روز قبل"
          nextLabel="روز بعد"
        />
      )}
      {list ? (
        <label htmlFor={selectId} className="flex items-center gap-1.5 text-sm">
          <MapPin className="size-4 text-muted-foreground" aria-hidden />
          <span className="sr-only">شهر</span>
          <select
            id={selectId}
            value={loc.name}
            onChange={(e) => {
              const c = list.find((x) => x.name === e.target.value);
              if (c) { setPicked(c); onLocationChange?.(c); }
            }}
            className="h-8 cursor-pointer rounded-field border-line-field border-input bg-field px-2 text-sm shadow-field outline-none focus-visible:ring-2 focus-visible:ring-ring/60"
          >
            {list.map((c) => <option key={c.name} value={c.name}>{c.name}</option>)}
          </select>
        </label>
      ) : (
        <span className="flex items-center gap-1.5 text-sm text-muted-foreground"><MapPin className="size-4" aria-hidden />{loc.name}</span>
      )}
    </div>
  );

  const countdown = next && offset === 0 && !date && (
    <p className="text-xs text-muted-foreground" aria-live="polite">
      <span className="font-medium text-foreground">{PRAYER_LABELS[next]}</span> {left < 60 ? `${fa(left)} دقیقه` : formatDuration(left)} دیگه
    </p>
  );

  return (
    <section aria-label={`اوقات شرعی ${loc.name}`} className={cn("space-y-3 rounded-surface border-line border-border bg-card p-4", className)}>
      {head}
      {variant === "strip" ? (
        <ol className={cn("grid gap-2", keys.length === 3 ? "grid-cols-3" : "grid-cols-3 sm:grid-cols-6")}>
          {keys.map((k) => {
            const on = k === next && offset === 0 && !date;
            return (
              <li key={k} aria-current={on ? "time" : undefined} className={cn("flex flex-col items-center gap-1 rounded-control border px-2 py-2.5 text-center", on ? "border-primary bg-primary text-primary-foreground" : "border-border")}>
                <PrayerIcon k={k} className={cn("size-4", !on && "text-muted-foreground")} />
                <span className={cn("text-[11px]", !on && "text-muted-foreground")}>{PRAYER_LABELS[k]}</span>
                <span className="text-sm font-bold tabular-nums">{formatTime(times[k], timeZone)}</span>
              </li>
            );
          })}
        </ol>
      ) : (
        <ol className="divide-y divide-border">
          {keys.map((k) => {
            const on = k === next && offset === 0 && !date;
            const past = !!now && offset === 0 && !date && times[k] <= now;
            return (
              <li key={k} aria-current={on ? "time" : undefined} className={cn("flex items-center gap-3 py-2.5", past && "text-muted-foreground")}>
                <span className={cn("flex size-8 shrink-0 items-center justify-center rounded-full", on ? "bg-primary text-primary-foreground" : "bg-secondary")}>
                  <PrayerIcon k={k} className="size-4" />
                </span>
                <span className={cn("flex-1 text-sm", AZAN.includes(k) && "font-medium")}>{PRAYER_LABELS[k]}</span>
                {on && <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">بعدی</span>}
                <span className="text-sm font-semibold tabular-nums">{formatTime(times[k], timeZone)}</span>
              </li>
            );
          })}
        </ol>
      )}
      {countdown}
    </section>
  );
}

"use client";

import * as React from "react";
import { cn, fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, jalaliWeekday, toJalali } from "@/lib/jalali";
import { HIJRI_MONTHS, toHijri } from "@/lib/hijri";
import { addDays } from "@/lib/calendar-utils";
import { CalendarToolbar, useCalendar, useDayInfo, useToday } from "@/components/calendar/calendar-core";

export const GREGORIAN_MONTHS_FA = ["ژانویه", "فوریه", "مارس", "آوریل", "مه", "ژوئن", "ژوئیه", "اوت", "سپتامبر", "اکتبر", "نوامبر", "دسامبر"];
const GREGORIAN_MONTHS_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const WEEKDAYS_AR = ["السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"];
const WEEKDAYS_EN = ["Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];

export type TripleDateParts = {
  jalali: { y: number; m: number; d: number; month: string; weekday: string };
  hijri: { y: number; m: number; d: number; month: string; weekday: string; approximate: boolean };
  gregorian: { y: number; m: number; d: number; month: string; monthEn: string; weekday: string };
};

/** The same day in all three calendars, with month and weekday names. */
export function tripleDate(date: Date): TripleDateParts {
  const w = jalaliWeekday(date);
  const { jy, jm, jd } = toJalali(date);
  const h = toHijri(date);
  return {
    jalali: { y: jy, m: jm, d: jd, month: JALALI_MONTHS[jm - 1], weekday: JALALI_WEEKDAYS[w] },
    hijri: { y: h.hy, m: h.hm, d: h.hd, month: HIJRI_MONTHS[h.hm - 1], weekday: WEEKDAYS_AR[w], approximate: h.approximate },
    gregorian: { y: date.getFullYear(), m: date.getMonth() + 1, d: date.getDate(), month: GREGORIAN_MONTHS_FA[date.getMonth()], monthEn: GREGORIAN_MONTHS_EN[date.getMonth()], weekday: WEEKDAYS_EN[w] },
  };
}

export interface TripleDateProps {
  /** Day shown. Defaults to today. */
  date?: Date;
  /** Previous/next day buttons (only when `date` is not set). */
  navigable?: boolean;
  /** «card» with the Jalali day large, or one «inline» line for headers. */
  variant?: "card" | "inline";
  /** Gregorian in English with Latin digits, the way it's written on documents. Default Persian. */
  latinGregorian?: boolean;
  /** Show today's occasions under the card. Default true. */
  occasions?: boolean;
  className?: string;
}

/**
 * تاریخ سه‌گانه. One day in Jalali, Hijri (Iran's official sighting table) and Gregorian,
 * like the date block on top of Iranian calendars and newspapers, with the day's occasions.
 */
export function TripleDate({ date, navigable, variant = "card", latinGregorian, occasions = true, className }: TripleDateProps) {
  const today = useToday();
  const { occasions: provider } = useCalendar();
  const [offset, setOffset] = React.useState(0);
  const day = date ?? addDays(today, offset);
  const info = useDayInfo(day);
  const p = tripleDate(day);
  const hijriText = `${fa(p.hijri.d)} ${p.hijri.month} ${fa(p.hijri.y)}`;
  const gregText = latinGregorian ? `${p.gregorian.monthEn} ${p.gregorian.d}, ${p.gregorian.y}` : `${fa(p.gregorian.d)} ${p.gregorian.month} ${fa(p.gregorian.y)}`;
  const approx = p.hijri.approximate && <abbr title="خارج از جدول رسمی رؤیت هلال؛ ممکنه یک روز جابه‌جا باشه" className="ms-1 text-[10px] text-muted-foreground no-underline">(تقریبی)</abbr>;

  if (variant === "inline") {
    return (
      <p className={cn("flex flex-wrap items-center gap-x-2 gap-y-0.5 text-sm", className)}>
        <time dateTime={info.key} className="font-medium">{p.jalali.weekday} {fa(p.jalali.d)} {p.jalali.month} {fa(p.jalali.y)}</time>
        <span aria-hidden className="text-muted-foreground/50">|</span>
        <span className="text-muted-foreground">{hijriText}{approx}</span>
        <span aria-hidden className="text-muted-foreground/50">|</span>
        {latinGregorian ? <bdi dir="ltr" className="text-muted-foreground">{gregText}</bdi> : <span className="text-muted-foreground">{gregText}</span>}
      </p>
    );
  }

  const list = provider && occasions ? info.occasions : [];
  return (
    <section aria-label="تاریخ امروز در سه تقویم" className={cn("overflow-hidden rounded-surface border-line border-border bg-card", className)}>
      {navigable && !date && (
        <CalendarToolbar
          className="border-b border-border px-3 py-2"
          title={offset === 0 ? "امروز" : offset === 1 ? "فردا" : offset === -1 ? "دیروز" : `${fa(Math.abs(offset))} روز ${offset > 0 ? "بعد" : "قبل"}`}
          onPrev={() => setOffset((o) => o - 1)}
          onNext={() => setOffset((o) => o + 1)}
          onToday={offset ? () => setOffset(0) : undefined}
          prevLabel="روز قبل"
          nextLabel="روز بعد"
        />
      )}
      <div className="flex items-stretch">
        <div className={cn("flex w-28 shrink-0 flex-col items-center justify-center gap-0.5 py-4", info.holiday || info.isWeekend ? "bg-destructive/10 text-destructive" : "bg-secondary")}>
          <span className="text-xs font-medium">{p.jalali.weekday}</span>
          <time dateTime={info.key} className="font-display text-5xl font-black leading-none tabular-nums">{fa(p.jalali.d)}</time>
          <span className="text-sm font-semibold">{p.jalali.month}</span>
          <span className="text-[11px] opacity-70">{fa(p.jalali.y)}</span>
        </div>
        <dl className="flex min-w-0 flex-1 flex-col justify-center divide-y divide-border px-4">
          <div className="flex items-baseline justify-between gap-3 py-2.5">
            <dt className="text-xs text-muted-foreground">قمری</dt>
            <dd className="text-sm font-medium" lang="fa">{hijriText}{approx}</dd>
          </div>
          <div className="flex items-baseline justify-between gap-3 py-2.5">
            <dt className="text-xs text-muted-foreground">میلادی</dt>
            <dd className="text-sm font-medium">{latinGregorian ? <bdi dir="ltr" lang="en">{gregText}</bdi> : gregText}</dd>
          </div>
        </dl>
      </div>
      {list.length > 0 && (
        <ul className="space-y-1 border-t border-border px-4 py-2.5 text-xs">
          {list.map((o) => (
            <li key={o.title} className={cn("flex items-center gap-2", o.holiday ? "text-destructive" : "text-muted-foreground")}>
              <span aria-hidden className={cn("size-1.5 shrink-0 rounded-full", o.holiday ? "bg-destructive" : "bg-muted-foreground/50")} />
              {o.title}
              {o.holiday && <span className="sr-only">(تعطیل)</span>}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

"use client";

import * as React from "react";
import { Plus } from "lucide-react";
import { cn, fa } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";
import { addDays, atMinutes, dayKey, eventColor, formatDuration, formatMinutes, formatTimeRange, minutesOfDay, zonedKey, type CalendarEvent, type Resource } from "@/lib/calendar-utils";
import { CalendarToolbar, useCalendar, useControllable, useDayInfo, useNow, useToday } from "@/components/calendar/calendar-core";

export interface ResourceTimelineProps {
  /** Rooms, people, cars, tables: each one is a row. */
  resources: Resource[];
  /** Events with a `resourceId`. Events of other days are ignored. */
  events: CalendarEvent[];
  date?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  /** Visible hours. Default 8 to 20. */
  startHour?: number;
  endHour?: number;
  /** Width of one hour in px. Default 88. */
  hourWidth?: number;
  /** Width of the resource column on the right. Default 180. */
  resourceWidth?: number;
  onEventClick?: (event: CalendarEvent) => void;
  /** Turns empty time into buttons, one per `slotMinutes`. */
  onSlotClick?: (resourceId: string, start: Date, end: Date) => void;
  slotMinutes?: number;
  /** Booked hours and share of the day under each resource. Default true. */
  showLoad?: boolean;
  toolbar?: boolean;
  className?: string;
}

type Placed = { event: CalendarEvent; from: number; to: number; lane: number; index: number };

/** Clips events to the visible hours of the day and stacks overlaps into lanes. */
function place(events: CalendarEvent[], key: string, startMin: number, endMin: number, tz: string): { items: Placed[]; lanes: number } {
  const lo = atMinutes(key, startMin, tz).getTime();
  const hi = atMinutes(key, endMin, tz).getTime();
  const items = events
    .map((event, index) => ({ event, index, s: Math.max(lo, event.start.getTime()), e: Math.min(hi, event.end.getTime()) }))
    .filter((x) => !x.event.allDay && x.e > x.s)
    .sort((a, b) => a.s - b.s || b.e - a.e);
  const ends: number[] = [];
  const out: Placed[] = [];
  for (const x of items) {
    let lane = ends.findIndex((end) => end <= x.s);
    if (lane < 0) { lane = ends.length; ends.push(0); }
    ends[lane] = x.e;
    out.push({ event: x.event, index: x.index, lane, from: startMin + (x.s - lo) / 60_000, to: startMin + (x.e - lo) / 60_000 });
  }
  return { items: out, lanes: Math.max(1, ends.length) };
}

/**
 * تایم‌لاین منابع. One day for many rooms, people or cars: resources down the right,
 * hours running right to left, bookings as bars with overlaps stacked, free time
 * clickable, a now line and each resource's load for the day.
 */
export function ResourceTimeline({
  resources,
  events,
  date,
  defaultDate,
  onDateChange,
  startHour = 8,
  endHour = 20,
  hourWidth = 88,
  resourceWidth = 180,
  onEventClick,
  onSlotClick,
  slotMinutes = 30,
  showLoad = true,
  toolbar = true,
  className,
}: ResourceTimelineProps) {
  const { timeZone } = useCalendar();
  const today = useToday();
  const now = useNow();
  const [day, setDay] = useControllable(date, defaultDate ?? today, onDateChange);
  const key = dayKey(day);
  const info = useDayInfo(day);
  const startMin = startHour * 60;
  const endMin = endHour * 60;
  const span = endMin - startMin;
  const trackW = (span / 60) * hourWidth;
  const px = (min: number) => ((min - startMin) / 60) * hourWidth;
  const hours = Array.from({ length: endHour - startHour }, (_, i) => startHour + i);
  const nowMin = now && zonedKey(now, timeZone) === key ? minutesOfDay(now, timeZone) : null;
  const laneH = 34;

  /** Start of the first slot that is neither past nor booked, in minutes. */
  const firstFree = (items: Placed[]) => {
    for (let a = startMin; a + slotMinutes <= endMin; a += slotMinutes) {
      if (now && atMinutes(key, a + slotMinutes, timeZone) < now) continue;
      if (!items.some((p) => p.from < a + slotMinutes && p.to > a)) return a;
    }
    return null;
  };

  const rows = resources.map((r) => {
    const mine = events.filter((e) => e.resourceId === r.id);
    const { items, lanes } = place(mine, key, startMin, endMin, timeZone);
    // Busy minutes without double counting overlaps.
    let busy = 0, edge = -Infinity;
    for (const p of [...items].sort((a, b) => a.from - b.from)) {
      if (p.to > edge) { busy += p.to - Math.max(p.from, edge); edge = p.to; }
    }
    return { r, items, lanes, busy };
  });
  const total = rows.reduce((n, x) => n + x.items.length, 0);

  return (
    <div className={cn("w-full space-y-3", className)}>
      {toolbar && (
        <CalendarToolbar
          title={formatJalali(day, { weekday: true })}
          subtitle={info.holiday ? `تعطیل: ${info.holiday.title}` : `${fa(total)} رزرو در ${fa(resources.length)} منبع`}
          onPrev={() => setDay(addDays(day, -1))}
          onNext={() => setDay(addDays(day, 1))}
          onToday={() => setDay(today)}
          prevLabel="روز قبل"
          nextLabel="روز بعد"
        />
      )}
      <div className="overflow-x-auto rounded-surface border-line border-border bg-card">
        <div style={{ width: resourceWidth + trackW }} className="relative">
          {/* hours header */}
          <div aria-hidden className="sticky top-0 z-20 flex border-b border-border bg-card">
            <div style={{ width: resourceWidth }} className="sticky start-0 z-10 shrink-0 border-e border-border bg-card px-3 py-2 text-[11px] font-medium text-muted-foreground">منبع</div>
            {hours.map((h) => (
              <div key={h} style={{ width: hourWidth }} className="shrink-0 border-e border-border/60 px-1.5 py-2 text-[11px] tabular-nums text-muted-foreground">
                {formatMinutes(h * 60)}
              </div>
            ))}
          </div>

          {rows.map(({ r, items, lanes, busy }) => {
            const h = Math.max(52, lanes * laneH + 12);
            const free = onSlotClick ? firstFree(items) : null;
            return (
              <div key={r.id} role="group" aria-label={`${r.title}، ${items.length ? `${formatDuration(Math.round(busy))} رزرو` : "بدون رزرو"}`} className="flex border-b border-border last:border-b-0">
                <div style={{ width: resourceWidth, height: h }} className="sticky start-0 z-10 flex shrink-0 items-center gap-2.5 border-e border-border bg-card px-3">
                  {r.avatar && (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={r.avatar} alt="" className="size-8 shrink-0 rounded-full object-cover" />
                  )}
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium">{r.title}</p>
                    {showLoad ? (
                      <div className="mt-1 flex items-center gap-1.5">
                        <span className="h-1 flex-1 overflow-hidden rounded-full bg-secondary">
                          <span className="block h-full rounded-full bg-primary" style={{ width: `${(busy / span) * 100}%` }} />
                        </span>
                        <span className="text-[10px] tabular-nums text-muted-foreground">{fa(Math.round((busy / span) * 100))}٪</span>
                      </div>
                    ) : r.subtitle && <p className="truncate text-[11px] text-muted-foreground">{r.subtitle}</p>}
                  </div>
                  {free !== null && (
                    <button
                      type="button"
                      aria-label={`رزرو ${r.title} از ساعت ${formatMinutes(free)}`}
                      title={`اولین زمان آزاد: ${formatMinutes(free)}`}
                      onClick={() => onSlotClick?.(r.id, atMinutes(key, free, timeZone), atMinutes(key, free + slotMinutes, timeZone))}
                      className="flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-control text-muted-foreground transition-colors hover:bg-accent hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
                    >
                      <Plus className="size-3.5" />
                    </button>
                  )}
                </div>

                <div className="relative shrink-0" style={{ width: trackW, height: h }}>
                  {/* hour lines, and free slots as buttons when booking is on */}
                  <div className="absolute inset-0 flex">
                    {onSlotClick
                      ? Array.from({ length: span / slotMinutes }, (_, i) => {
                          const a = startMin + i * slotMinutes;
                          const past = now ? atMinutes(key, a + slotMinutes, timeZone) < now : false;
                          return (
                            <button
                              key={a}
                              type="button"
                              tabIndex={-1}
                              aria-hidden
                              disabled={past}
                              onClick={() => onSlotClick(r.id, atMinutes(key, a, timeZone), atMinutes(key, a + slotMinutes, timeZone))}
                              style={{ width: (slotMinutes / 60) * hourWidth }}
                              className={cn("h-full shrink-0 border-border/60 transition-colors", (a + slotMinutes) % 60 === 0 ? "border-e" : "border-e border-dashed border-e-border/30", past ? "cursor-not-allowed bg-muted/40" : "cursor-pointer hover:bg-primary/5")}
                            />
                          );
                        })
                      : hours.map((hh) => <div key={hh} style={{ width: hourWidth }} className="h-full shrink-0 border-e border-border/60" />)}
                  </div>

                  {items.map(({ event, from, to, lane, index }) => {
                    const color = eventColor(event.color, index);
                    const wide = px(to) - px(from) > 70;
                    return (
                      <button
                        key={event.id}
                        type="button"
                        onClick={() => onEventClick?.(event)}
                        aria-label={`${event.title}، ${formatTimeRange(event.start, event.end, timeZone)}`}
                        title={`${event.title}، ${formatTimeRange(event.start, event.end, timeZone)}`}
                        style={{ insetInlineStart: px(from) + 1, width: Math.max(6, px(to) - px(from) - 2), top: 6 + lane * laneH, height: laneH - 4, "--ev": color } as React.CSSProperties}
                        className="absolute z-[1] flex min-w-0 cursor-pointer flex-col justify-center overflow-hidden rounded-control border-s-[3px] border-[var(--ev)] bg-[color-mix(in_oklch,var(--ev)_18%,var(--card))] px-1.5 text-start text-foreground transition-colors hover:bg-[color-mix(in_oklch,var(--ev)_28%,var(--card))] focus-visible:z-[3] focus-visible:outline-2 focus-visible:outline-ring"
                      >
                        <span className="w-full truncate text-[11px] font-medium leading-4">{event.title}</span>
                        {wide && <span className="w-full truncate text-[10px] leading-3 tabular-nums text-muted-foreground">{formatTimeRange(event.start, event.end, timeZone)}</span>}
                      </button>
                    );
                  })}

                  {nowMin !== null && nowMin >= startMin && nowMin <= endMin && (
                    <div className="pointer-events-none absolute inset-y-0 z-[2] w-0.5 bg-destructive" style={{ insetInlineStart: px(nowMin) - 1 }} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

    </div>
  );
}

import { cn } from "@/lib/utils";

/**
 * متن درخشان. A highlight sweeps across the text — the standard "thinking"
 * indicator. Needs the `shimmer` keyframes (see the CSS tab).
 */
export function TextShimmer({ children, className, duration = 3 }: { children: React.ReactNode; className?: string; duration?: number }) {
  return (
    <span
      className={cn("inline-block bg-clip-text text-transparent", className)}
      style={{
        backgroundImage: "linear-gradient(90deg, var(--muted-foreground) 0%, var(--foreground) 45%, var(--foreground) 55%, var(--muted-foreground) 100%)",
        backgroundSize: "250% auto",
        animation: `shimmer ${duration}s linear infinite`,
      }}
    >
      {children}
    </span>
  );
}

animations/text-shimmer.css:
@keyframes shimmer {
  from { background-position: 200% center; }
  to { background-position: -200% center; }
}

