"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface TypewriterProps {
  text: string;
  /** Milliseconds per character. */
  speed?: number;
  /** Pause at the end before restarting (0 = no loop). */
  loopDelay?: number;
  cursor?: boolean;
  className?: string;
}

/** تایپ‌شونده. Reveals text character by character; Persian letters join correctly as they appear. */
export function Typewriter({ text, speed = 70, loopDelay = 0, cursor = true, className }: TypewriterProps) {
  const [n, setN] = React.useState(0);
  React.useEffect(() => {
    const id = window.setInterval(() => {
      setN((x) => {
        if (x < text.length) return x + 1;
        if (loopDelay) { window.setTimeout(() => setN(0), loopDelay); }
        return x;
      });
    }, speed);
    return () => window.clearInterval(id);
  }, [text, speed, loopDelay]);

  return (
    <span className={className} aria-label={text}>
      <span aria-hidden>{text.slice(0, n)}</span>
      {cursor && <span aria-hidden className={cn("ms-0.5 inline-block h-[1em] w-px translate-y-[0.15em] bg-current align-baseline", n >= text.length && loopDelay === 0 ? "animate-pulse-soft" : "")} />}
    </span>
  );
}

"use client";

import * as React from "react";
import { cn, faNumber } from "@/lib/utils";

export interface CounterProps {
  to: number;
  from?: number;
  duration?: number;
  /** Format the number only; defaults to Persian thousands. */
  format?: (n: number) => string;
  /** Unit rendered outside the animating box, so it never moves (e.g. «تومان»). */
  unit?: React.ReactNode;
  className?: string;
}

/**
 * شمارنده. Counts up when scrolled into view, eased, with Persian digits.
 * The final value is rendered invisibly to reserve the box width, the live
 * value is anchored to the units digit, and the unit sits outside the box —
 * so nothing shifts when the digit count changes (e.g. crossing ۱۰٬۰۰۰٬۰۰۰).
 */
export function Counter({ to, from = 0, duration = 1600, format = faNumber, unit, className }: CounterProps) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [v, setV] = React.useState(from);

  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    const run = () => {
      const start = performance.now();
      const tick = (t: number) => {
        const p = Math.min(1, (t - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setV(Math.round(from + (to - from) * eased));
        if (p < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    };
    if (typeof IntersectionObserver === "undefined") { run(); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { run(); io.disconnect(); } });
    io.observe(el);
    return () => { io.disconnect(); cancelAnimationFrame(raf); };
  }, [to, from, duration]);

  return (
    <span ref={ref} className={cn("inline-flex items-baseline gap-[0.35em] tabular-nums", className)}>
      <span className="relative inline-block">
        <span aria-hidden className="invisible">{format(Math.max(to, from))}</span>
        <span className="absolute inset-0 text-right" dir="ltr">{format(v)}</span>
      </span>
      {unit && <span className="text-[0.5em] font-normal text-muted-foreground">{unit}</span>}
    </span>
  );
}

import { cn } from "@/lib/utils";

/** ظهور تار. Each word fades in from a blur, right to left. Needs the `blur-in` keyframes. */
export function BlurText({ text, delay = 120, className }: { text: string; delay?: number; className?: string }) {
  return (
    <span className={cn("inline", className)} aria-label={text}>
      {text.split(" ").map((w, i) => (
        <span key={i} aria-hidden className="inline-block" style={{ animation: `blur-in 0.9s cubic-bezier(0.16,1,0.3,1) ${i * delay}ms both` }}>
          {w}&nbsp;
        </span>
      ))}
    </span>
  );
}

