"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/** کارت سه‌بعدی. Tilts toward the pointer; resets on leave. `max` is the tilt in degrees. */
export function TiltCard({ children, max = 14, className }: { children: React.ReactNode; max?: number; className?: string }) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [t, setT] = React.useState({ x: 0, y: 0 });
  return (
    <div
      ref={ref}
      onMouseMove={(e) => {
        const r = ref.current!.getBoundingClientRect();
        const px = (e.clientX - r.left) / r.width - 0.5;
        const py = (e.clientY - r.top) / r.height - 0.5;
        setT({ x: py * -max, y: px * max });
      }}
      onMouseLeave={() => setT({ x: 0, y: 0 })}
      className={cn("rounded-xl border border-border bg-card transition-transform duration-150 [transform-style:preserve-3d]", className)}
      style={{ transform: `perspective(600px) rotateX(${t.x}deg) rotateY(${t.y}deg)` }}
    >
      {children}
    </div>
  );
}

import { cn } from "@/lib/utils";

/** نقاط بارگذاری. Three bouncing dots for short waits. Needs the `bounce-dot` keyframes. */
export function LoadingDots({ label, className }: { label?: React.ReactNode; className?: string }) {
  return (
    <span role="status" className={cn("inline-flex items-center gap-2 text-sm text-muted-foreground", className)}>
      <span className="flex gap-1" aria-hidden>
        {[0, 1, 2].map((i) => (
          <span key={i} className="size-1.5 rounded-full bg-foreground" style={{ animation: `bounce-dot 1.2s ease-in-out ${i * 160}ms infinite` }} />
        ))}
      </span>
      {label}
    </span>
  );
}

