"use client";

import * as React from "react";

const POOL = "ابپتثجچحخدذرزژسشصضطظعغفقکگلمنوهی";

/** رمزگشایی متن. Letters churn through random Persian glyphs and settle one by one, from the start of the string. */
export function TextScramble({ text, speed = 40, className }: { text: string; speed?: number; className?: string }) {
  const [out, setOut] = React.useState(text);
  React.useEffect(() => {
    let frame = 0;
    let resolved = 0;
    const id = window.setInterval(() => {
      frame += 1;
      if (frame % 2 === 0) resolved += 1;
      const next = Array.from(text)
        .map((ch, i) => (i < resolved || ch === " " || ch === "‌" ? ch : POOL[(frame * 7 + i * 13) % POOL.length]))
        .join("");
      setOut(next);
      if (resolved >= text.length) window.clearInterval(id);
    }, speed);
    return () => window.clearInterval(id);
  }, [text, speed]);
  return <span className={className} aria-label={text}><span aria-hidden>{out}</span></span>;
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

const FA = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];

function Digit({ d }: { d: number }) {
  return (
    <span className="inline-block h-[1em] overflow-hidden align-baseline leading-none">
      <span className="flex flex-col transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)]" style={{ transform: `translateY(-${d}em)` }}>
        {FA.map((f) => <span key={f} className="h-[1em] leading-none">{f}</span>)}
      </span>
    </span>
  );
}

/**
 * شماره‌انداز. Each digit rolls to its new value like a mechanical counter.
 * Ideal for prices that update live. Digits are laid out LTR inside the number.
 */
export function Odometer({ value, unit, className }: { value: number; unit?: string; className?: string }) {
  const chars = Math.round(value).toLocaleString("en-US").replace(/,/g, "٬").split("");
  return (
    <span className={cn("inline-flex items-baseline gap-1.5 tabular-nums", className)}>
      <span className="inline-flex" dir="ltr">
        {chars.map((c, i) => (/\d/.test(c) ? <Digit key={`${chars.length}-${i}`} d={Number(c)} /> : <span key={`s${i}`} className="leading-none">{c}</span>))}
      </span>
      {unit && <span className="text-[0.5em] text-muted-foreground">{unit}</span>}
    </span>
  );
}

"use client";

import * as React from "react";
import { Button, type ButtonProps } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** دکمه‌ی موجی. A ring expands from the tap point. Needs the `ripple` keyframes. */
export function RippleButton({ className, children, onClick, ...props }: ButtonProps) {
  const [ripples, setRipples] = React.useState<{ id: number; x: number; y: number }[]>([]);
  return (
    <Button
      className={cn("relative overflow-hidden", className)}
      onClick={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        const id = Date.now();
        setRipples((l) => [...l, { id, x: e.clientX - r.left, y: e.clientY - r.top }]);
        window.setTimeout(() => setRipples((l) => l.filter((p) => p.id !== id)), 650);
        onClick?.(e);
      }}
      {...props}
    >
      {ripples.map((p) => (
        <span key={p.id} aria-hidden className="pointer-events-none absolute size-10 rounded-full bg-current" style={{ left: p.x, top: p.y, animation: "ripple 0.65s ease-out forwards" }} />
      ))}
      <span className="relative inline-flex items-center gap-2">{children}</span>
    </Button>
  );
}

animations/ripple-button.css:
@keyframes ripple {
  from { transform: translate(-50%, -50%) scale(0); opacity: 0.35; }
  to { transform: translate(-50%, -50%) scale(4); opacity: 0; }
}

