"use client";

import * as React from "react";
import { Button, type ButtonProps } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** دکمه‌ی آهنربایی. Leans toward the pointer while it's nearby, then springs back. `strength` is the max offset in px. */
export function MagneticButton({ strength = 10, className, ...props }: ButtonProps & { strength?: number }) {
  const [t, setT] = React.useState({ x: 0, y: 0 });
  return (
    <span
      className="inline-block p-5"
      onMouseMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        const px = (e.clientX - r.left) / r.width - 0.5;
        const py = (e.clientY - r.top) / r.height - 0.5;
        setT({ x: px * strength * 2, y: py * strength * 2 });
      }}
      onMouseLeave={() => setT({ x: 0, y: 0 })}
    >
      <Button className={cn("transition-transform duration-200 ease-out", className)} style={{ transform: `translate(${t.x}px, ${t.y}px)` }} {...props} />
    </span>
  );
}

"use client";

import * as React from "react";
import { cn, faPercent } from "@/lib/utils";

/** حلقه‌ی پیشرفت. An SVG ring that fills when it scrolls into view; label in Persian percent. */
export function ProgressRing({ value, size = 96, stroke = 8, label, className }: { value: number; size?: number; stroke?: number; label?: React.ReactNode; className?: string }) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [shown, setShown] = React.useState(0);
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  React.useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") { setShown(value); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setShown(value); io.disconnect(); } });
    io.observe(el);
    return () => io.disconnect();
  }, [value]);
  return (
    <div ref={ref} className={cn("relative inline-flex items-center justify-center", className)} style={{ width: size, height: size }} role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}>
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--input)" strokeWidth={stroke} />
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--primary)" strokeWidth={stroke} strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c - (c * shown) / 100} className="transition-[stroke-dashoffset] duration-[1200ms] ease-[cubic-bezier(0.16,1,0.3,1)]" />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-lg font-bold tabular-nums">{faPercent(shown)}</span>
        {label && <span className="text-[10px] text-muted-foreground">{label}</span>}
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";

/** تیک موفقیت. The circle pops in, then the check draws itself. Needs the `pop` and `draw` keyframes. */
export function SuccessCheck({ size = 72, label, className }: { size?: number; label?: React.ReactNode; className?: string }) {
  return (
    <div className={cn("inline-flex flex-col items-center gap-3", className)} role="status">
      <svg width={size} height={size} viewBox="0 0 72 72" style={{ animation: "pop 0.5s cubic-bezier(0.16,1,0.3,1) both" }}>
        <circle cx="36" cy="36" r="34" fill="var(--success)" opacity="0.15" />
        <circle cx="36" cy="36" r="34" fill="none" stroke="var(--success)" strokeWidth="2" />
        <path d="M22 37 L32 47 L51 27" fill="none" stroke="var(--success)" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="48" strokeDashoffset="48" style={{ animation: "draw 0.5s ease-out 0.35s forwards" }} />
      </svg>
      {label && <p className="text-sm font-medium" style={{ animation: "word-in 0.5s ease-out 0.6s both" }}>{label}</p>}
    </div>
  );
}

