"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/** هایلایت متن. A marker stroke sweeps under the phrase from the right once it scrolls into view. */
export function HighlightText({ children, delay = 0, className }: { children: React.ReactNode; delay?: number; className?: string }) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [on, setOn] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") { setOn(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setOn(true); io.disconnect(); } }, { threshold: 0.6 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    <span
      ref={ref}
      className={cn("box-decoration-clone rounded-[0.2em] bg-no-repeat px-[0.12em] transition-[background-size] duration-1000 ease-[cubic-bezier(0.16,1,0.3,1)]", className)}
      style={{
        backgroundImage: "linear-gradient(oklch(from var(--brand) l c h / 45%), oklch(from var(--brand) l c h / 45%))",
        backgroundPosition: "100% 100%", // anchored to the right, so it grows from the RTL start
        backgroundSize: `${on ? 100 : 0}% 0.5em`,
        transitionDelay: `${delay}ms`,
      }}
    >
      {children}
    </span>
  );
}

import { cn } from "@/lib/utils";

/** متن گرادیانی. A foreground→brand gradient pans slowly across the text; the text stays selectable. Needs the `gradient-pan` keyframes. */
export function GradientText({ children, duration = 6, className }: { children: React.ReactNode; duration?: number; className?: string }) {
  return (
    <span
      className={cn("inline-block bg-clip-text text-transparent", className)}
      style={{
        backgroundImage: "linear-gradient(90deg, var(--foreground), var(--brand), var(--foreground), var(--brand), var(--foreground))",
        backgroundSize: "300% 100%",
        animation: `gradient-pan ${duration}s linear infinite`,
      }}
    >
      {children}
    </span>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/** کارت برگردان. Turns over on hover/focus (or on click) to show its back; both faces share the front's size. */
export function FlipCard({ front, back, trigger = "hover", className }: { front: React.ReactNode; back: React.ReactNode; trigger?: "hover" | "click"; className?: string }) {
  const [flipped, setFlipped] = React.useState(false);
  const click = trigger === "click";
  const toggle = () => setFlipped((f) => !f);
  return (
    <div
      className={cn("group relative [perspective:1200px]", click && "cursor-pointer outline-none", className)}
      role={click ? "button" : undefined}
      tabIndex={click ? 0 : undefined}
      aria-pressed={click ? flipped : undefined}
      onClick={click ? toggle : undefined}
      onKeyDown={click ? (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); } } : undefined}
    >
      <div
        className={cn(
          "relative h-full w-full transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] [transform-style:preserve-3d]",
          !click && "group-hover:[transform:rotateY(180deg)] group-focus-within:[transform:rotateY(180deg)]",
          click && flipped && "[transform:rotateY(180deg)]",
        )}
      >
        <div className="[backface-visibility:hidden]">{front}</div>
        <div className="absolute inset-0 [backface-visibility:hidden] [transform:rotateY(180deg)]">{back}</div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface AnimatedBeamProps {
  containerRef: React.RefObject<HTMLElement | null>;
  fromRef: React.RefObject<HTMLElement | null>;
  toRef: React.RefObject<HTMLElement | null>;
  /** Bend of the curve in px; positive bows it downward. */
  curvature?: number;
  duration?: number;
  delay?: number;
  /** Send the light from `to` back to `from`. */
  reverse?: boolean;
  className?: string;
}

/** پرتو اتصال. Draws a curve between two elements inside a `relative isolate` container and sends a pulse of light along it; the line sits behind the endpoints. Needs the `beam-travel` keyframes. */
export function AnimatedBeam({ containerRef, fromRef, toRef, curvature = 0, duration = 4, delay = 0, reverse = false, className }: AnimatedBeamProps) {
  const [d, setD] = React.useState("");
  const [size, setSize] = React.useState({ w: 0, h: 0 });
  React.useEffect(() => {
    const c = containerRef.current, a = fromRef.current, b = toRef.current;
    if (!c || !a || !b) return;
    const update = () => {
      const cr = c.getBoundingClientRect(), ar = a.getBoundingClientRect(), br = b.getBoundingClientRect();
      const x1 = ar.left - cr.left + ar.width / 2, y1 = ar.top - cr.top + ar.height / 2;
      const x2 = br.left - cr.left + br.width / 2, y2 = br.top - cr.top + br.height / 2;
      setSize({ w: cr.width, h: cr.height });
      setD(`M ${x1},${y1} Q ${(x1 + x2) / 2},${(y1 + y2) / 2 + curvature} ${x2},${y2}`);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(c);
    return () => ro.disconnect();
  }, [containerRef, fromRef, toRef, curvature]);
  // pathLength=100 makes the dash math independent of the real length: the 28-unit dash travels from just before the start to just past the end.
  const travel = { strokeDasharray: "28 100", animation: `beam-travel ${duration}s cubic-bezier(0.4,0,0.2,1) ${delay}s infinite ${reverse ? "reverse" : "normal"}` };
  return (
    <svg aria-hidden className={cn("pointer-events-none absolute inset-0 -z-10 overflow-visible", className)} width={size.w} height={size.h} viewBox={`0 0 ${size.w || 1} ${size.h || 1}`} fill="none">
      <path d={d} stroke="var(--foreground)" strokeOpacity="0.14" strokeWidth="2" />
      <path d={d} pathLength={100} stroke="var(--brand)" strokeOpacity="0.35" strokeWidth="6" strokeLinecap="round" style={travel} />
      <path d={d} pathLength={100} stroke="var(--brand)" strokeWidth="2" strokeLinecap="round" style={travel} />
    </svg>
  );
}

import type { CSSProperties } from "react";
import { cn, mulberry32 } from "@/lib/utils";

const COLORS = [
  "var(--brand)",
  "var(--foreground)",
  "var(--success)",
  "var(--warning)",
  "var(--destructive)",
];

export type ConfettiProps = {
  count: number;
  spreadX: number;
  peakMin: number;
  peakMax: number;
  fallMin: number;
  fallMax: number;
  rotateMax: number;
  durationMin: number;
  durationMax: number;
  delayMax: number;
  sizeMin: number;
  sizeMax: number;
  colors: string[];
  seed: number;
  className: string;
};

export function Confetti({
  count = 60,
  spreadX = 200,
  peakMin = 130,
  peakMax = 370,
  fallMin = 40,
  fallMax = 160,
  rotateMax = 1080,
  durationMin = 1,
  durationMax = 2.5,
  delayMax = 0.6,
  sizeMin = 6,
  sizeMax = 12,
  colors = COLORS,
  seed = 0,
  className,
}: Partial<ConfettiProps>) {
  return (
    <div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 -z-10", className)}
    >
      {Array.from({ length: count }, (_, i) => {
        const rand = mulberry32(seed * 9973 + i * 7919 + 1);

        const style = {
          background: colors[i % colors.length],
          borderRadius: i % 3 ? 2 : 999,
          width: `${(rand() + rand() * 0.5) * (sizeMax - sizeMin) + sizeMin}px`,
          height: `${((rand() + rand() * 0.5) * (sizeMax - sizeMin) + sizeMin) * 0.6}px`,
          "--spread-x": `${(rand() + rand() + rand() - 1.5) * spreadX}px`,
          "--peak-y": `${-(peakMin + rand() * (peakMax - peakMin))}px`,
          "--fall-y": `${fallMin + rand() * (fallMax - fallMin)}px`,
          "--rotate": `${(rand() - 0.5) * rotateMax}deg`,
          "--rotate-mid": `${(rand() - 0.5) * rotateMax * (0.4 + rand() * 0.3)}deg`,
          "--duration": `${durationMin + rand() * (durationMax - durationMin)}s`,
          "--delay": `${rand() * delayMax}s`,
          "--size": `${sizeMin + rand() * (sizeMax - sizeMin)}px`,
          animation: `confetti var(--duration) linear var(--delay) both`,
        } as CSSProperties;

        return (
          <span
            key={i}
            className="absolute top-1/2 -translate-y-1/2 left-1/2 block"
            style={style}
          />
        );
      })}
    </div>
  );
}

