"use client";

import * as React from "react";
import { Check, ChevronsLeft } from "lucide-react";
import { cn } from "@/lib/utils";

const HANDLE = 56; // handle (3rem) + track padding (0.5rem), in px

/** کشیدن برای تأیید. Drag the handle from the right edge to the left to confirm; it snaps back if released early. Enter or Space confirms for keyboard users. */
export function SwipeToConfirm({ label = "برای پرداخت بکشید", doneLabel = "پرداخت انجام شد", onConfirm, className }: { label?: string; doneLabel?: string; onConfirm?: () => void; className?: string }) {
  const track = React.useRef<HTMLDivElement>(null);
  const startX = React.useRef(0);
  const pRef = React.useRef(0);
  const dragRef = React.useRef(false); // refs, not state: pointer events can arrive before a re-render
  const [p, setPState] = React.useState(0); // 0..1 along the track
  const [drag, setDragState] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const setP = (v: number) => { pRef.current = v; setPState(v); };
  const setDrag = (v: boolean) => { dragRef.current = v; setDragState(v); };

  const confirm = () => { setP(1); setDone(true); onConfirm?.(); };
  const onDown = (e: React.PointerEvent<HTMLButtonElement>) => { if (done) return; e.currentTarget.setPointerCapture(e.pointerId); startX.current = e.clientX; setDrag(true); };
  const onMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (!dragRef.current || done || !track.current) return;
    const dir = getComputedStyle(track.current).direction === "rtl" ? -1 : 1;
    const travel = track.current.getBoundingClientRect().width - HANDLE;
    setP(Math.min(1, Math.max(0, ((e.clientX - startX.current) * dir) / travel)));
  };
  const onUp = () => { if (!dragRef.current) return; setDrag(false); if (pRef.current >= 0.9) confirm(); else setP(0); };

  return (
    <div ref={track} className={cn("relative h-14 w-full max-w-sm select-none overflow-hidden rounded-full border border-border bg-secondary p-1", className)}>
      <span aria-hidden className={cn("absolute inset-y-0 start-0 rounded-full", done ? "bg-success/25" : "bg-brand/15", !drag && "transition-[width] duration-300")} style={{ width: `calc(${p} * (100% - ${HANDLE}px) + ${HANDLE}px)` }} />
      <span aria-hidden className="absolute inset-0 flex items-center justify-center gap-1 text-sm font-medium text-muted-foreground transition-opacity duration-150" style={{ opacity: done ? 0 : Math.max(0, 1 - p * 1.6) }}>
        {label}
        <ChevronsLeft className="size-4 animate-pulse-soft" />
      </span>
      <span aria-hidden className="absolute inset-0 flex items-center justify-center gap-1.5 text-sm font-semibold text-success transition-opacity duration-300" style={{ opacity: done ? 1 : 0 }}>
        <Check className="size-4" />
        {doneLabel}
      </span>
      <button
        type="button"
        aria-label={done ? doneLabel : label}
        disabled={done}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={onUp}
        onPointerCancel={onUp}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); if (!done) confirm(); } }}
        className={cn(
          "absolute top-1 flex size-12 cursor-grab touch-none items-center justify-center rounded-full bg-primary text-primary-foreground shadow-md outline-none focus-visible:ring-2 focus-visible:ring-ring",
          drag ? "cursor-grabbing" : "transition-[inset-inline-start] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)]",
          done && "bg-success cursor-default",
        )}
        style={{ insetInlineStart: `calc(0.25rem + ${p} * (100% - ${HANDLE}px))` }}
      >
        {done ? <Check className="size-5" /> : <ChevronsLeft className="size-5" />}
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TerminalLine = { type: "cmd" | "out" | "ok" | "err"; text: string };

/** ترمینال. Types each command letter by letter, then prints its output; commands are LTR mono, Persian output stays RTL. Starts when scrolled into view. */
export function Terminal({ lines, speed = 45, title = "ترمینال", className }: { lines: TerminalLine[]; speed?: number; title?: string; className?: string }) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [go, setGo] = React.useState(false);
  const [n, setN] = React.useState(0); // lines fully shown
  const [typed, setTyped] = React.useState(0); // characters of the current command

  React.useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") { setGo(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setGo(true); io.disconnect(); } }, { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  React.useEffect(() => {
    if (!go || n >= lines.length) return;
    const line = lines[n];
    const typing = line.type === "cmd" && typed < line.text.length;
    const id = window.setTimeout(() => {
      if (typing) setTyped((t) => t + 1);
      else { setN((x) => x + 1); setTyped(0); }
    }, typing ? speed : line.type === "cmd" ? 400 : 180);
    return () => window.clearTimeout(id);
  }, [go, n, typed, lines, speed]);

  const shown = lines.slice(0, n);
  const current = n < lines.length && lines[n].type === "cmd" ? { ...lines[n], text: lines[n].text.slice(0, typed) } : null;
  const row = (l: TerminalLine, i: number, cursor = false) =>
    l.type === "cmd" ? (
      <div key={i} className="flex gap-2 text-foreground" dir="ltr">
        <span className="select-none text-muted-foreground">$</span>
        <span>{l.text}{cursor && <span aria-hidden className="ms-0.5 inline-block h-[1.1em] w-[0.55em] translate-y-[0.2em] bg-foreground animate-pulse-soft" />}</span>
      </div>
    ) : (
      <div key={i} className={cn("flex gap-2 ps-4", l.type === "ok" && "text-success", l.type === "err" && "text-destructive", l.type === "out" && "text-muted-foreground")}>
        {l.type === "ok" && <span aria-hidden>✓</span>}
        {l.type === "err" && <span aria-hidden>✗</span>}
        <span>{l.text}</span>
      </div>
    );

  return (
    <div ref={ref} role="log" aria-live="polite" className={cn("w-full max-w-md overflow-hidden rounded-xl border border-border bg-card text-[13px] leading-6", className)}>
      <div className="flex items-center gap-1.5 border-b border-border px-3 py-2">
        {["bg-destructive", "bg-warning", "bg-success"].map((c) => <span key={c} aria-hidden className={cn("size-2.5 rounded-full opacity-70", c)} />)}
        <span className="ms-2 text-xs text-muted-foreground">{title}</span>
      </div>
      <div className="min-h-32 space-y-0.5 p-3">
        {shown.map((l, i) => row(l, i))}
        {current && row(current, n, true)}
        {!current && n >= lines.length && <div className="flex gap-2 text-foreground" dir="ltr"><span className="text-muted-foreground">$</span><span aria-hidden className="inline-block h-[1.1em] w-[0.55em] translate-y-[0.2em] bg-foreground animate-pulse-soft" /></div>}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/** پشته‌ی کارت. Cards sit stacked; every few seconds the front card slides to the back. Pauses on hover. A small ring counts down to the next swap. Give it a height via className. */
export function CardStack({ items, interval = 3200, offset = 12, scale = 0.05, className }: { items: React.ReactNode[]; interval?: number; offset?: number; scale?: number; className?: string }) {
  const [order, setOrder] = React.useState(() => items.map((_, i) => i));
  const [paused, setPaused] = React.useState(false);
  const [cycle, setCycle] = React.useState(0);
  React.useEffect(() => {
    if (paused || items.length < 2) return;
    setCycle((c) => c + 1);
    const id = window.setInterval(() => {
      setOrder((o) => [...o.slice(1), o[0]]);
      setCycle((c) => c + 1);
    }, interval);
    return () => window.clearInterval(id);
  }, [interval, paused, items.length]);

  const size = 16;
  const stroke = 2;
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;

  return (
    <div className={cn("relative h-48 w-full max-w-sm", className)} onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      {items.map((node, i) => {
        const depth = order.indexOf(i);
        return (
          <div
            key={i}
            aria-hidden={depth !== 0}
            className="absolute inset-0 origin-top rounded-xl border border-border bg-card shadow-lg transition-[transform,opacity] duration-700 ease-[cubic-bezier(0.16,1,0.3,1)]"
            style={{ zIndex: items.length - depth, transform: `translateY(${depth * offset}px) scale(${1 - depth * scale})`, opacity: depth > 2 ? 0 : 1 }}
          >
            {node}
          </div>
        );
      })}
      {items.length > 1 && (
        <svg
          key={cycle}
          aria-hidden
          width={size}
          height={size}
          className="pointer-events-none absolute end-2.5 top-2.5 z-20 -rotate-90"
          style={{ opacity: paused ? 0.35 : 1 }}
        >
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--border)" strokeWidth={stroke} />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke="var(--muted-foreground)"
            strokeWidth={stroke}
            strokeLinecap="round"
            strokeDasharray={c}
            strokeDashoffset={c}
            style={{ animation: `draw ${interval}ms linear forwards`, animationPlayState: paused ? "paused" : "running" }}
          />
        </svg>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

type Phase = "idle" | "loading" | "done";

/** دکمه‌ی سه‌حالته. One button for idle → loading → done; the states cross-fade in place and the width never jumps. */
export function MorphButton({ children, loadingText = "در حال انجام…", doneText = "انجام شد", onAction, resetAfter = 2200, className }: { children: React.ReactNode; loadingText?: string; doneText?: string; onAction?: () => Promise<unknown> | void; resetAfter?: number; className?: string }) {
  const [phase, setPhase] = React.useState<Phase>("idle");
  const timer = React.useRef<number | undefined>(undefined);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  async function run() {
    if (phase !== "idle") return;
    setPhase("loading");
    try { await (onAction?.() ?? new Promise((r) => setTimeout(r, 1200))); } finally { setPhase("done"); }
    if (resetAfter) timer.current = window.setTimeout(() => setPhase("idle"), resetAfter);
  }
  // All three states share one grid cell, so the button is as wide as the widest state from the start.
  const layer = (on: boolean) => cn("col-start-1 row-start-1 flex items-center justify-center gap-2 transition-[opacity,transform] duration-300", on ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-2 opacity-0");
  return (
    <button
      type="button"
      onClick={run}
      aria-live="polite"
      aria-busy={phase === "loading"}
      disabled={phase !== "idle"}
      className={cn("inline-grid h-10 cursor-pointer rounded-lg px-4 text-sm font-semibold text-primary-foreground transition-colors duration-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-default", phase === "done" ? "bg-success" : "bg-primary", className)}
    >
      <span className={layer(phase === "idle")}>{children}</span>
      <span className={layer(phase === "loading")}><Loader2 className="size-4 animate-spin" />{loadingText}</span>
      <span className={layer(phase === "done")}><Check className="size-4" />{doneText}</span>
    </button>
  );
}

"use client";

import * as React from "react";
import { ChevronsLeftRight } from "lucide-react";
import { cn, fa } from "@/lib/utils";

/** مقایسه‌ی قبل و بعد. Two layers with a draggable divider; «قبل» sits on the right (the RTL start). The divider is a real range input, so it works with the keyboard too. */
export function CompareSlider({ before, after, beforeLabel = "قبل", afterLabel = "بعد", defaultValue = 50, className }: { before: React.ReactNode; after: React.ReactNode; beforeLabel?: string; afterLabel?: string; defaultValue?: number; className?: string }) {
  const [v, setV] = React.useState(defaultValue); // percent of the width, measured from the right
  const tag = "pointer-events-none absolute top-2 rounded-md bg-background/80 px-2 py-0.5 text-[11px] font-medium backdrop-blur";
  return (
    <div className={cn("relative w-full select-none overflow-hidden rounded-xl border border-border", className)}>
      <div aria-hidden>{before}</div>
      <div aria-hidden className="absolute inset-0" style={{ clipPath: `inset(0 ${v}% 0 0)` }}>{after}</div>
      <span className={cn(tag, "start-2")}>{beforeLabel}</span>
      <span className={cn(tag, "end-2")}>{afterLabel}</span>
      <span aria-hidden className="pointer-events-none absolute inset-y-0 w-0.5 bg-foreground shadow-[0_0_0_1px_var(--background)]" style={{ right: `calc(${v}% - 1px)` }}>
        <span className="absolute top-1/2 left-1/2 flex size-9 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-border bg-background text-foreground shadow-md">
          <ChevronsLeftRight className="size-4" />
        </span>
      </span>
      <input
        type="range"
        min={0}
        max={100}
        value={v}
        onChange={(e) => setV(Number(e.target.value))}
        aria-label="جابه‌جایی خط مقایسه"
        aria-valuetext={`${fa(v)}٪`}
        className="absolute inset-0 h-full w-full cursor-col-resize opacity-0"
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/** کارت خراشیدنی. A canvas cover you scratch off with the pointer; once `threshold` of it is gone it clears itself. Enter reveals it for keyboard users. */
export function ScratchCard({ children, coverText = "اینجا را بخراشید", brushSize = 22, threshold = 0.45, onReveal, className }: { children: React.ReactNode; coverText?: string; brushSize?: number; threshold?: number; onReveal?: () => void; className?: string }) {
  const canvas = React.useRef<HTMLCanvasElement>(null);
  const moves = React.useRef(0);
  const [revealed, setRevealed] = React.useState(false);

  React.useEffect(() => {
    const c = canvas.current;
    if (!c) return;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = c.getBoundingClientRect();
    c.width = width * dpr;
    c.height = height * dpr;
    const ctx = c.getContext("2d")!;
    ctx.scale(dpr, dpr);
    const cs = getComputedStyle(c);
    ctx.fillStyle = cs.getPropertyValue("--secondary").trim() || "#333";
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = "rgba(128,128,128,0.18)"; // diagonal foil stripes
    for (let x = -height; x < width; x += 14) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x + height, height); ctx.lineTo(x + height + 5, height); ctx.lineTo(x + 5, 0); ctx.fill(); }
    ctx.fillStyle = cs.getPropertyValue("--muted-foreground").trim() || "#999";
    ctx.font = `600 14px ${cs.fontFamily}`;
    ctx.textAlign = "center";
    ctx.direction = "rtl";
    ctx.fillText(coverText, width / 2, height / 2 + 5);
  }, [coverText]);

  const reveal = () => { if (!revealed) { setRevealed(true); onReveal?.(); } };
  const scratch = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (e.buttons !== 1 || revealed) return;
    const c = e.currentTarget, r = c.getBoundingClientRect(), ctx = c.getContext("2d")!;
    ctx.globalCompositeOperation = "destination-out";
    ctx.beginPath();
    ctx.arc(e.clientX - r.left, e.clientY - r.top, brushSize, 0, Math.PI * 2);
    ctx.fill();
    if (++moves.current % 10 === 0) {
      const { data } = ctx.getImageData(0, 0, c.width, c.height);
      let clear = 0, total = 0;
      for (let i = 3; i < data.length; i += 32) { total++; if (data[i] === 0) clear++; } // sample every 8th pixel's alpha
      if (clear / total > threshold) reveal();
    }
  };

  return (
    <div className={cn("relative overflow-hidden rounded-xl border border-border bg-card", className)}>
      {children}
      <canvas
        ref={canvas}
        role="button"
        tabIndex={revealed ? -1 : 0}
        aria-label={coverText}
        onPointerDown={scratch}
        onPointerMove={scratch}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); reveal(); } }}
        className={cn("absolute inset-0 h-full w-full cursor-crosshair touch-none rounded-xl outline-none transition-opacity duration-500 focus-visible:ring-2 focus-visible:ring-ring", revealed && "pointer-events-none opacity-0")}
      />
    </div>
  );
}

import { cn } from "@/lib/utils";

/** جرقه. Little four-point stars twinkle around the children; positions are stable across renders (no Math.random). Needs the `sparkle` keyframes. */
export function Sparkles({ children, count = 7, className }: { children: React.ReactNode; count?: number; className?: string }) {
  return (
    <span className={cn("relative inline-block", className)}>
      {Array.from({ length: count }, (_, i) => {
        const r = (n: number) => ((i * 9973 + n * 7919) % 100) / 100;
        return (
          <svg
            key={i}
            aria-hidden
            viewBox="0 0 24 24"
            className="pointer-events-none absolute size-3 text-brand"
            style={{ left: `${r(1) * 110 - 5}%`, top: `${r(2) * 110 - 15}%`, animation: `sparkle ${1.6 + r(3)}s ease-in-out ${r(4) * 2}s infinite` }}
          >
            <path fill="currentColor" d="M12 0c.6 6.9 5.1 11.4 12 12-6.9.6-11.4 5.1-12 12-.6-6.9-5.1-11.4-12-12 6.9-.6 11.4-5.1 12-12z" />
          </svg>
        );
      })}
      <span className="relative">{children}</span>
    </span>
  );
}

