"use client";

import * as React from "react";
import { Pin } from "lucide-react";
import { cn } from "@/lib/utils";

export type PinListItem = {
  id: string;
  name: string;
  info: string;
  icon: React.ElementType;
  pinned: boolean;
};

export type PinListProps = {
  items: PinListItem[];
  labels?: { pinned?: string; unpinned?: string };
  className?: string;
  onChange?: (items: PinListItem[]) => void;
};

type RectMap = Map<string, DOMRect>;

/**
 * فهرست سنجاق. Click a row to pin / unpin it; items animate between the two
 * groups with a lightweight FLIP so the motion stays springy without a library.
 */
export function PinList({
  items: initial,
  labels = { pinned: "سنجاق‌شده", unpinned: "همه" },
  className,
  onChange,
}: PinListProps) {
  const [items, setItems] = React.useState(initial);
  const root = React.useRef<HTMLDivElement>(null);
  const pending = React.useRef<RectMap | null>(null);

  const pinned = items.filter((i) => i.pinned);
  const unpinned = items.filter((i) => !i.pinned);

  const measure = (): RectMap => {
    const map: RectMap = new Map();
    root.current?.querySelectorAll<HTMLElement>("[data-pin-id]").forEach((el) => {
      map.set(el.dataset.pinId!, el.getBoundingClientRect());
    });
    return map;
  };

  React.useLayoutEffect(() => {
    const first = pending.current;
    if (!first || !root.current) return;
    pending.current = null;
    root.current.querySelectorAll<HTMLElement>("[data-pin-id]").forEach((el) => {
      const id = el.dataset.pinId!;
      const a = first.get(id);
      if (!a) return;
      const b = el.getBoundingClientRect();
      const dx = a.left - b.left;
      const dy = a.top - b.top;
      if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) return;
      el.style.transform = `translate(${dx}px, ${dy}px)`;
      el.style.transition = "none";
      requestAnimationFrame(() => {
        el.style.transition = "transform 420ms cubic-bezier(0.16, 1, 0.3, 1)";
        el.style.transform = "";
        const clear = () => {
          el.style.transition = "";
          el.removeEventListener("transitionend", clear);
        };
        el.addEventListener("transitionend", clear);
      });
    });
  }, [items]);

  const toggle = (id: string) => {
    pending.current = measure();
    setItems((prev) => {
      const idx = prev.findIndex((u) => u.id === id);
      if (idx === -1) return prev;
      const next = [...prev];
      const [item] = next.splice(idx, 1);
      const toggled = { ...item, pinned: !item.pinned };
      if (toggled.pinned) next.push(toggled);
      else next.unshift(toggled);
      onChange?.(next);
      return next;
    });
  };

  const row = (item: PinListItem, showPin: boolean) => (
    <button
      key={item.id}
      type="button"
      data-pin-id={item.id}
      onClick={() => toggle(item.id)}
      className={cn(
        "flex w-full cursor-pointer items-center justify-between gap-3 rounded-2xl bg-secondary p-2 text-start will-change-transform",
        !showPin && "group",
      )}
    >
      <span className="flex min-w-0 items-center gap-2">
        <span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-background">
          <item.icon className="size-4 text-muted-foreground" />
        </span>
        <span className="min-w-0">
          <span className="block truncate text-sm font-semibold">{item.name}</span>
          <span className="block truncate text-xs text-muted-foreground">{item.info}</span>
        </span>
      </span>
      <span
        className={cn(
          "flex size-8 shrink-0 items-center justify-center rounded-full bg-muted-foreground/40 transition-opacity duration-200",
          showPin ? "opacity-100" : "opacity-0 group-hover:opacity-100 group-focus-visible:opacity-100",
        )}
      >
        <Pin className={cn("size-3.5 text-background", showPin && "fill-background")} />
      </span>
    </button>
  );

  return (
    <div ref={root} className={cn("space-y-8", className)}>
      {pinned.length > 0 && (
        <div className="space-y-2">
          <p className="px-2 text-xs font-medium text-muted-foreground">{labels.pinned}</p>
          <div className="space-y-2">{pinned.map((i) => row(i, true))}</div>
        </div>
      )}
      {unpinned.length > 0 && (
        <div className="space-y-2">
          <p className="px-2 text-xs font-medium text-muted-foreground">{labels.unpinned}</p>
          <div className="space-y-2">{unpinned.map((i) => row(i, false))}</div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type RadialIntroItem = {
  id: string;
  name: string;
  src: string;
};

export type RadialIntroProps = {
  items: RadialIntroItem[];
  stageSize?: number;
  imageSize?: number;
  /** Seconds for one full orbit once spinning. */
  duration?: number;
  className?: string;
};

type Phase = "idle" | "lift" | "place" | "spin";

/**
 * معرفی شعاعی. Avatars gather at the centre, lift in, fan out to equal
 * angles, then orbit forever while staying upright. Needs `radial-orbit`
 * and `radial-counter` keyframes.
 */
export function RadialIntro({
  items,
  stageSize = 280,
  imageSize = 52,
  duration = 28,
  className,
}: RadialIntroProps) {
  const [phase, setPhase] = React.useState<Phase>("idle");
  const step = 360 / Math.max(items.length, 1);

  React.useEffect(() => {
    const t1 = window.setTimeout(() => setPhase("lift"), 120);
    const t2 = window.setTimeout(() => setPhase("place"), 520);
    const t3 = window.setTimeout(() => setPhase("spin"), 1100);
    return () => {
      window.clearTimeout(t1);
      window.clearTimeout(t2);
      window.clearTimeout(t3);
    };
  }, []);

  const radius = (stageSize - imageSize) / 2 - 4;
  const ease = "520ms cubic-bezier(0.16, 1, 0.3, 1)";

  return (
    <div
      className={cn("relative overflow-visible", className)}
      style={{ width: stageSize, height: stageSize, ["--orbit-r" as string]: `${radius}px` }}
      role="img"
      aria-label={items.map((i) => i.name).join("، ")}
    >
      <span
        aria-hidden
        className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full border border-dashed border-border"
        style={{ width: radius * 2, height: radius * 2 }}
      />
      {items.map((item, i) => {
        const angle = i * step;
        const placed = phase === "place" || phase === "spin";
        const spinning = phase === "spin";
        const lifted = phase !== "idle";
        return (
          <div
            key={item.id}
            className="absolute inset-0 will-change-transform"
            style={{
              zIndex: items.length - i,
              ["--start-angle" as string]: `${angle}deg`,
              transform: placed ? `rotate(${angle}deg)` : "rotate(0deg)",
              transition: spinning ? undefined : `transform ${ease}`,
              animation: spinning ? `radial-orbit ${duration}s linear infinite` : undefined,
            }}
          >
            <img
              src={item.src}
              alt=""
              draggable={false}
              className="absolute left-1/2 top-1/2 aspect-square rounded-full object-cover shadow-md will-change-transform"
              style={{
                width: imageSize,
                height: imageSize,
                opacity: lifted || i === 0 ? 1 : 0,
                ["--start-angle" as string]: `${angle}deg`,
                transform: placed
                  ? `translate(-50%, calc(-50% - ${radius}px)) rotate(${-angle}deg)`
                  : lifted
                    ? "translate(-50%, -50%) rotate(0deg)"
                    : "translate(-50%, -50%) scale(0.85) rotate(0deg)",
                transition: spinning
                  ? undefined
                  : `transform ${ease}, opacity 280ms ease`,
                animation: spinning ? `radial-counter ${duration}s linear infinite` : undefined,
              }}
            />
          </div>
        );
      })}
    </div>
  );
}

animations/radial-intro.css:
@keyframes radial-orbit {
  from { transform: rotate(var(--start-angle, 0deg)); }
  to { transform: rotate(calc(var(--start-angle, 0deg) + 360deg)); }
}
@keyframes radial-counter {
  from { transform: translate(-50%, calc(-50% - var(--orbit-r, 80px))) rotate(calc(var(--start-angle, 0deg) * -1)); }
  to { transform: translate(-50%, calc(-50% - var(--orbit-r, 80px))) rotate(calc(var(--start-angle, 0deg) * -1 - 360deg)); }
}

