import { cn } from "@/lib/utils";

const FROM = {
  start: "ltr:[--px:-16px] rtl:[--px:16px] [--py:0px]",
  end: "ltr:[--px:16px] rtl:[--px:-16px] [--py:0px]",
  bottom: "[--px:0px] [--py:16px]",
  top: "[--px:0px] [--py:-16px]",
};

/**
 * ظهور پنل. A panel that slides into its region through a cross-blur; closed it
 * is invisible and inert, so nothing behind it is focusable by accident.
 * `from="start"` enters from the reading edge — the right in RTL.
 */
export function PanelReveal({
  open,
  from = "start",
  children,
  className,
}: {
  open: boolean;
  from?: keyof typeof FROM;
  children: React.ReactNode;
  className?: string;
}) {
  const ease = "cubic-bezier(0.22,1,0.36,1)";
  const dur = open ? 400 : 350;
  return (
    <div
      inert={!open}
      aria-hidden={!open}
      className={cn("will-change-[transform,opacity,filter]", FROM[from], className)}
      style={{
        transform: open ? "translate(0, 0)" : "translate(var(--px), var(--py))",
        opacity: open ? 1 : 0,
        filter: open ? "blur(0)" : "blur(2px)",
        transition: `transform ${dur}ms ${ease}, opacity ${dur}ms ${ease}, filter ${dur}ms ${ease}`,
      }}
    >
      {children}
    </div>
  );
}

import { cn } from "@/lib/utils";

/**
 * جابه‌جایی صفحه. Pages share one grid cell; the active one is visible and the
 * rest wait on either side. Going forward the new page enters from the "next"
 * side of the reading direction — the left in RTL — while the old one slides out
 * the other way, both through a light blur. Height follows the tallest page.
 */
export function PageSlide({
  index,
  pages,
  distance = 12,
  className,
}: {
  index: number;
  pages: React.ReactNode[];
  distance?: number;
  className?: string;
}) {
  const ease = "cubic-bezier(0.22,1,0.36,1)";
  return (
    <div className={cn("relative grid ltr:[--fwd:1] rtl:[--fwd:-1]", className)}>
      {pages.map((page, i) => {
        const active = i === index;
        // Pages after the active one wait on the "next" side, earlier ones on the "previous" side.
        const side = i > index ? 1 : i < index ? -1 : 0;
        return (
          <div
            key={i}
            inert={!active}
            aria-hidden={!active}
            className="col-start-1 row-start-1 will-change-[transform,opacity,filter]"
            style={{
              opacity: active ? 1 : 0,
              transform: `translateX(calc(${side * distance}px * var(--fwd)))`,
              filter: active ? "blur(0)" : "blur(3px)",
              transition: `opacity 250ms ease-out, transform 250ms ${ease}, filter 250ms ${ease}`,
              transitionDelay: active ? "40ms" : "0ms",
            }}
          >
            {page}
          </div>
        );
      })}
    </div>
  );
}

import { cn } from "@/lib/utils";

/**
 * تعویض آیکون. Two icons share one slot; the active one scales and un-blurs in
 * while the other shrinks and blurs out. With `rotate` they also turn a quarter
 * on the way, which reads well for menu ↔ close.
 */
export function IconSwap({
  state,
  a,
  b,
  rotate = false,
  duration = 250,
  className,
}: {
  state: "a" | "b";
  a: React.ReactNode;
  b: React.ReactNode;
  rotate?: boolean;
  duration?: number;
  className?: string;
}) {
  const layer = (on: boolean, turn: number): React.CSSProperties => ({
    opacity: on ? 1 : 0,
    filter: on ? "blur(0)" : "blur(2px)",
    transform: `scale(${on ? 1 : 0.5})${rotate ? ` rotate(${on ? 0 : turn}deg)` : ""}`,
    transition: `opacity ${duration}ms ease-in-out, filter ${duration}ms ease-in-out, transform ${duration}ms ease-in-out`,
  });
  return (
    <span className={cn("inline-grid", className)}>
      <span aria-hidden={state !== "a"} className="col-start-1 row-start-1 flex will-change-[transform,opacity,filter]" style={layer(state === "a", -90)}>{a}</span>
      <span aria-hidden={state !== "b"} className="col-start-1 row-start-1 flex will-change-[transform,opacity,filter]" style={layer(state === "b", 90)}>{b}</span>
    </span>
  );
}

"use client";

import * as React from "react";
import { Avatar } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";

/**
 * هاور آواتارها. The hovered avatar springs up and its neighbours follow with a
 * distance falloff; on leave the whole row bounces back with an overshoot.
 * The person's name floats above the active one. Works in either direction
 * because the falloff is measured by index, not by side.
 */
export function AvatarHover({
  people,
  lift = 8,
  falloff = 0.45,
  size = "md",
  className,
}: {
  people: { name: string; src?: string }[];
  /** Pixels the hovered avatar rises. */
  lift?: number;
  /** Each neighbour rises this fraction of the previous one. */
  falloff?: number;
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  const [active, setActive] = React.useState<number | null>(null);
  const ease = active === null ? "cubic-bezier(0.34,3.85,0.64,1)" : "cubic-bezier(0.22,1,0.36,1)";
  return (
    <div className={cn("flex items-end", className)} onMouseLeave={() => setActive(null)}>
      {people.map((p, i) => {
        const on = i === active;
        const shift = active === null ? 0 : -lift * Math.pow(falloff, Math.abs(i - active));
        return (
          <div
            key={p.name}
            className={cn("relative will-change-transform", i > 0 && "-ms-2")}
            onMouseEnter={() => setActive(i)}
            style={{ transform: `translateY(${shift.toFixed(2)}px) scale(${on ? 1.08 : 1})`, transition: `transform 320ms ${ease}`, zIndex: on ? 2 : 1 }}
          >
            <span
              aria-hidden
              className="pointer-events-none absolute bottom-full left-1/2 mb-1.5 whitespace-nowrap rounded-md bg-foreground px-1.5 py-0.5 text-[10px] font-medium text-background"
              style={{ opacity: on ? 1 : 0, transform: `translate(-50%, ${on ? 0 : 4}px)`, transition: "opacity 200ms ease-out, transform 200ms ease-out" }}
            >
              {p.name}
            </span>
            <Avatar name={p.name} src={p.src} size={size} className="ring-2 ring-background" />
          </div>
        );
      })}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * لرزش خطا. Wrap any field. When `error` becomes a string the box shakes with a
 * decaying swing, a red ring fades in and the message appears below; after
 * `revertAfter` everything quietly returns to neutral on its own. Children are
 * never remounted, so the input keeps focus and its value. Needs the `error-shake` keyframes.
 */
export function ErrorShake({
  error,
  revertAfter = 3000,
  onRevert,
  children,
  className,
}: {
  /** Each new string replays the shake; null or "" clears the state. */
  error?: string | null;
  /** Milliseconds before the error state clears itself; 0 keeps it. */
  revertAfter?: number;
  onRevert?: () => void;
  children: React.ReactNode;
  className?: string;
}) {
  const [prev, setPrev] = React.useState(error);
  const [on, setOn] = React.useState(Boolean(error));
  // The last message stays rendered while it fades out.
  const [msg, setMsg] = React.useState(error ?? "");
  if (error !== prev) {
    setPrev(error);
    setOn(Boolean(error));
    if (error) setMsg(error);
  }
  const box = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!error) return;
    const el = box.current;
    if (el) {
      // Replay from a clean baseline even if the previous shake is still running.
      el.style.animation = "none";
      void el.offsetWidth;
      el.style.animation = "error-shake 0.4s linear";
    }
    if (!revertAfter) return;
    const id = window.setTimeout(() => {
      setOn(false);
      onRevert?.();
    }, revertAfter);
    return () => window.clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [error, revertAfter]);

  return (
    <div className={cn("grid gap-1.5", className)}>
      <div
        ref={box}
        data-error={on || undefined}
        className="rounded-lg will-change-transform"
        style={{
          boxShadow: on ? "0 0 0 1px var(--destructive), 0 0 0 4px color-mix(in oklab, var(--destructive) 18%, transparent)" : "0 0 0 0 transparent, 0 0 0 0 transparent",
          transition: `box-shadow ${on ? 150 : 280}ms ease-out`,
        }}
      >
        {children}
      </div>
      <p
        role="alert"
        className="min-h-4 text-xs text-destructive"
        style={{ opacity: on ? 1 : 0, visibility: on ? "visible" : "hidden", transition: `opacity 280ms ease-out, visibility 0s linear ${on ? 0 : 280}ms` }}
      >
        {msg}
      </p>
    </div>
  );
}

animations/error-shake.css:
@keyframes error-shake {
  0% { transform: translateX(0); animation-timing-function: cubic-bezier(0.36, 0.07, 0.19, 0.97); }
  20% { transform: translateX(8px); animation-timing-function: cubic-bezier(0.36, 0.07, 0.19, 0.97); }
  40% { transform: translateX(-7px); animation-timing-function: cubic-bezier(0.36, 0.07, 0.19, 0.97); }
  60% { transform: translateX(5px); animation-timing-function: cubic-bezier(0.36, 0.07, 0.19, 0.97); }
  80% { transform: translateX(-3px); animation-timing-function: cubic-bezier(0.36, 0.07, 0.19, 0.97); }
  100% { transform: translateX(0); }
}

