import { cn } from "@/lib/utils";

/**
 * ظهور از اسکلت. Two layers share one grid cell. While `loading` the skeleton
 * pulses; when data arrives it blurs out as the real content un-blurs in and
 * settles up by a few pixels. Nothing shifts, because both layers were always
 * in the same slot. Needs the `pulse-soft` keyframes.
 */
export function SkeletonReveal({
  loading,
  skeleton,
  children,
  duration = 400,
  className,
}: {
  loading: boolean;
  skeleton: React.ReactNode;
  children: React.ReactNode;
  duration?: number;
  className?: string;
}) {
  const fade = (on: boolean): React.CSSProperties => ({
    opacity: on ? 1 : 0,
    filter: on ? "blur(0)" : "blur(2px)",
    transition: `opacity ${duration}ms ease-in-out, filter ${duration}ms ease-in-out, transform ${duration}ms cubic-bezier(0.22,1,0.36,1)`,
  });
  return (
    <div className={cn("grid", className)} aria-busy={loading}>
      <div aria-hidden className="col-start-1 row-start-1 will-change-[opacity,filter]" style={fade(loading)}>
        <div style={loading ? { animation: "pulse-soft 1.2s ease-in-out infinite" } : undefined}>{skeleton}</div>
      </div>
      <div inert={loading} className="col-start-1 row-start-1 will-change-[transform,opacity,filter]" style={{ ...fade(!loading), transform: loading ? "translateY(4px)" : "translateY(0)" }}>
        {children}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Plus } from "lucide-react";
import { cn } from "@/lib/utils";

export type FabMorphItem = { label: string; icon?: React.ReactNode; onSelect?: () => void };

/**
 * دکمه‌ی شناور بازشونده. The round + button grows into the menu itself — width,
 * height and corner radius tween — while the plus turns into an × and the
 * items slide in one after another. It is pinned to the inline-end corner, so in
 * RTL it sits bottom-left and opens up and to the right. Outside click and Escape close it.
 */
export function FabMorph({
  items,
  open: openProp,
  onOpenChange,
  width = 200,
  className,
}: {
  items: FabMorphItem[];
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Open panel width in px. Height follows the items. */
  width?: number;
  className?: string;
}) {
  const [inner, setInner] = React.useState(false);
  const open = openProp ?? inner;
  const setOpen = React.useCallback((v: boolean) => { setInner(v); onOpenChange?.(v); }, [onOpenChange]);
  const root = React.useRef<HTMLDivElement>(null);
  const height = 16 + items.length * 38 + 44;

  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("pointerdown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("pointerdown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open, setOpen]);

  const bouncy = "cubic-bezier(0.34,1.3,0.64,1)";
  const calm = "cubic-bezier(0.22,1,0.36,1)";
  const box = open ? `300ms ${bouncy}` : `220ms ${calm}`;
  return (
    // The anchor is sized to the open footprint so the panel grows out of a fixed corner.
    <div ref={root} className={cn("relative ltr:[--sx:12px] rtl:[--sx:-12px]", className)} style={{ width, height }}>
      <div
        className="absolute bottom-0 end-0 overflow-hidden bg-foreground text-background shadow-lg will-change-[width,height,border-radius]"
        style={{ width: open ? width : 44, height: open ? height : 44, borderRadius: open ? 16 : 22, transition: `width ${box}, height ${box}, border-radius ${box}` }}
      >
        <ul className="absolute inset-x-0 top-0 flex flex-col gap-0.5 p-2" style={{ width }}>
          {items.map((it, i) => (
            <li key={it.label}>
              <button
                type="button"
                tabIndex={open ? 0 : -1}
                onClick={() => { it.onSelect?.(); setOpen(false); }}
                className="flex h-9 w-full cursor-pointer items-center gap-2.5 rounded-lg px-2.5 text-sm hover:bg-background/15 focus-visible:bg-background/15 focus-visible:outline-none"
                style={{
                  opacity: open ? 1 : 0,
                  transform: open ? "translateX(0)" : "translateX(var(--sx))",
                  filter: open ? "blur(0)" : "blur(2px)",
                  pointerEvents: open ? "auto" : "none",
                  transition: `opacity 200ms ease-out, transform 300ms ${calm}, filter 200ms ease-out`,
                  transitionDelay: open ? `${60 + i * 40}ms` : "0ms",
                }}
              >
                {it.icon && <span className="flex size-4 items-center justify-center [&>svg]:size-4">{it.icon}</span>}
                {it.label}
              </button>
            </li>
          ))}
        </ul>
        <button
          type="button"
          aria-expanded={open}
          aria-label={open ? "بستن" : "باز کردن منو"}
          onClick={() => setOpen(!open)}
          className="absolute bottom-0 end-0 grid size-11 cursor-pointer place-items-center rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-background/60"
        >
          <Plus className="size-5" style={{ transform: open ? "rotate(135deg) scale(0.9)" : "rotate(0) scale(1)", transition: `transform 300ms ${calm}` }} />
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Heart } from "lucide-react";
import { cn, faNumber, mulberry32 } from "@/lib/utils";

/**
 * دکمه‌ی پسندیدن. The heart fills and pops, eight particles spray outward —
 * on like only; unliking just drains the colour — and the count nudges up with
 * the new number popping in. The spray is seeded, so every like looks a little
 * different. Needs the `like-pop`, `like-burst` and `digit-pop` keyframes.
 */
export function LikeButton({
  liked: likedProp,
  defaultLiked = false,
  count,
  onChange,
  className,
}: {
  liked?: boolean;
  defaultLiked?: boolean;
  /** Likes by everyone else; the user's own like is added on top. */
  count?: number;
  onChange?: (liked: boolean) => void;
  className?: string;
}) {
  const [inner, setInner] = React.useState(defaultLiked);
  const liked = likedProp ?? inner;
  const [burst, setBurst] = React.useState(0);

  const toggle = () => {
    const next = !liked;
    setInner(next);
    onChange?.(next);
    if (next) setBurst((n) => n + 1);
  };

  const rnd = mulberry32(burst * 7 + 1);
  const particles = Array.from({ length: 8 }, (_, i) => {
    const a = (i / 8) * Math.PI * 2 + rnd() * 0.6;
    const r = 14 + rnd() * 10;
    return { x: Math.cos(a) * r, y: Math.sin(a) * r, s: 0.6 + rnd() * 0.8, d: rnd() * 80 };
  });

  return (
    <button
      type="button"
      aria-pressed={liked}
      onClick={toggle}
      className={cn(
        "relative inline-flex h-9 cursor-pointer items-center gap-2 rounded-full border px-3.5 text-sm font-medium transition-colors duration-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        liked ? "border-rose-500/40 bg-rose-500/10 text-rose-500" : "border-border hover:bg-accent",
        className,
      )}
    >
      <span className="relative grid place-items-center">
        {/* The pop lives on a wrapper, not the svg: transforming an inline svg makes Chromium rasterise it at 1×. */}
        <span key={burst} className="flex" style={liked ? { animation: "like-pop 0.4s cubic-bezier(0.34,1.56,0.64,1)" } : undefined}>
          <Heart className="size-4 transition-[fill] duration-300" style={{ fill: liked ? "currentColor" : "transparent" }} />
        </span>
        {liked && burst > 0 && (
          <span key={`burst-${burst}`} aria-hidden className="pointer-events-none absolute left-1/2 top-1/2 size-0">
            {particles.map((p, i) => (
              <i
                key={i}
                className="absolute rounded-full bg-current"
                style={{
                  width: 4 * p.s,
                  height: 4 * p.s,
                  left: -2 * p.s,
                  top: -2 * p.s,
                  ["--px" as string]: `${p.x.toFixed(1)}px`,
                  ["--py" as string]: `${p.y.toFixed(1)}px`,
                  animation: `like-burst 600ms ease-out ${p.d.toFixed(0)}ms both`,
                }}
              />
            ))}
          </span>
        )}
      </span>
      {count != null && (
        <span className="inline-grid tabular-nums">
          <span key={liked ? "on" : "off"} className="col-start-1 row-start-1" style={{ ["--pop-y" as string]: liked ? 1 : -1, animation: "digit-pop 0.35s cubic-bezier(0.34,1.45,0.64,1) both" }}>
            {faNumber(count + (liked ? 1 : 0))}
          </span>
        </span>
      )}
    </button>
  );
}

animations/like-button.css:
@keyframes like-pop {
  0% { transform: scale(1); }
  30% { transform: scale(0.8); }
  65% { transform: scale(1.25); }
  100% { transform: scale(1); }
}
@keyframes like-burst {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4); }
  20% { opacity: 1; transform: translate(calc(var(--px) * 0.25), calc(var(--py) * 0.25)) scale(1); }
  100% { opacity: 0; transform: translate(var(--px), var(--py)) scale(0.5); }
}
@keyframes digit-pop {
  from { opacity: 0; filter: blur(2px); transform: translate(calc(var(--pop-x, 0) * 8px), calc(var(--pop-y, 1) * 8px)); }
  to { opacity: 1; filter: blur(0); transform: translate(0, 0); }
}

