"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * جریان استدلال. A small card that plays back an agent's reasoning: the
 * transcript steps up a couple of lines at a time, holds, and loops without a
 * visible jump because the text is cloned once underneath. The fades at the top
 * and bottom are a mask, so any card background works. Hover pauses it.
 */
export function ReasoningStream({
  text,
  lines = 2,
  hold = 1200,
  height = 104,
  className,
}: {
  text: string | string[];
  /** Lines per step. */
  lines?: number;
  /** Milliseconds between steps. */
  hold?: number;
  height?: number;
  className?: string;
}) {
  const scroll = React.useRef<HTMLDivElement>(null);
  const copy = React.useRef<HTMLDivElement>(null);
  const paused = React.useRef(false);
  const paragraphs = Array.isArray(text) ? text : [text];

  React.useEffect(() => {
    const el = scroll.current;
    const first = copy.current;
    if (!el || !first) return;
    let offset = 0;
    let alive = true;
    let id = 0;
    const step = () => {
      id = window.setTimeout(() => {
        if (!alive) return;
        if (paused.current) return step();
        const lineH = parseFloat(getComputedStyle(first).lineHeight) || 20;
        offset += lineH * lines;
        el.style.transition = "transform 500ms cubic-bezier(0.22,1,0.36,1)";
        el.style.transform = `translateY(${-offset}px)`;
        id = window.setTimeout(() => {
          if (!alive) return;
          // Past one copy's height, snap back by exactly that much: the clone makes it invisible.
          const h = first.offsetHeight;
          if (offset >= h) {
            offset -= h;
            el.style.transition = "none";
            el.style.transform = `translateY(${-offset}px)`;
            void el.offsetWidth;
          }
          step();
        }, 530);
      }, hold);
    };
    step();
    return () => {
      alive = false;
      window.clearTimeout(id);
      el.style.transition = "none";
      el.style.transform = "translateY(0)";
    };
  }, [lines, hold, text]);

  const body = paragraphs.map((p, i) => <p key={i}>{p}</p>);
  return (
    <div
      className={cn("relative w-full max-w-sm overflow-hidden rounded-xl border border-border bg-card text-xs leading-5 text-muted-foreground", className)}
      style={{ height }}
      onMouseEnter={() => { paused.current = true; }}
      onMouseLeave={() => { paused.current = false; }}
    >
      <div className="absolute inset-0 overflow-hidden [mask-image:linear-gradient(transparent,black_22%,black_78%,transparent)]">
        <div ref={scroll} className="absolute inset-x-0 top-0 px-4 py-3 will-change-transform">
          <div ref={copy} className="space-y-1">{body}</div>
          <div aria-hidden className="space-y-1">{body}</div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * متن جریانی. Words resolve one after another through a small blur, like a
 * model's answer condensing into place rather than being typed. Each word is its
 * own span, so the letters inside a Persian word stay joined. A soft dot marks the
 * stream head until the last word lands. Needs the `pulse-soft` keyframes.
 */
export function StreamingText({
  text,
  gap = 60,
  fade = 300,
  className,
}: {
  text: string;
  /** Milliseconds between words. */
  gap?: number;
  /** Milliseconds each word takes to resolve. */
  fade?: number;
  className?: string;
}) {
  const words = React.useMemo(() => text.split(/\s+/).filter(Boolean), [text]);
  const [n, setN] = React.useState(0);
  const [prevWords, setPrevWords] = React.useState(words);
  if (words !== prevWords) {
    setPrevWords(words);
    setN(0);
  }

  React.useEffect(() => {
    let i = 0;
    const id = window.setInterval(() => {
      i += 1;
      setN(i);
      if (i >= words.length) window.clearInterval(id);
    }, gap);
    return () => window.clearInterval(id);
  }, [words, gap]);

  const done = n >= words.length;
  return (
    <p className={cn("leading-8", className)} aria-label={text}>
      {words.map((w, i) => (
        <React.Fragment key={i}>
          <span
            aria-hidden
            className="inline-block will-change-[opacity,filter]"
            style={{ opacity: i < n ? 1 : 0, filter: i < n ? "blur(0)" : "blur(3px)", transition: `opacity ${fade}ms ease-out, filter ${fade}ms ease-out` }}
          >
            {w}
          </span>
          {i < words.length - 1 && " "}
        </React.Fragment>
      ))}
      <span aria-hidden className="ms-1 inline-block size-2 rounded-full bg-foreground align-middle transition-opacity duration-300" style={{ opacity: done ? 0 : 1, animation: done ? undefined : "pulse-soft 1s ease-in-out infinite" }} />
    </p>
  );
}

import { cn } from "@/lib/utils";

const TWINKLE = [7, 2, 11, 5, 14, 9, 0, 12, 3, 15, 6, 10, 13, 1, 8, 4];
const RING = [1, 2, 7, 11, 14, 13, 8, 4];
const INNER = [5, 6, 9, 10];
const CORNERS = [0, 3, 12, 15];

export type MatrixVariant = "scan" | "twinkle" | "orbit" | "pulse" | "wave";

/**
 * لودر ماتریسی. A 4×4 dot matrix that whispers instead of spinning. One
 * colour-pulse keyframe does all the work; each variant is just a table of
 * delays. `scan` sweeps right to left like reading, `wave` runs diagonally from
 * the top-right corner. Needs the `matrix-pulse` keyframes.
 */
export function MatrixLoader({
  variant = "scan",
  rounded = false,
  dot = 3,
  cycle = 1200,
  label = "در حال بارگذاری",
  className,
}: {
  variant?: MatrixVariant;
  /** Drop the four corner dots. */
  rounded?: boolean;
  /** Dot size and gap in px. */
  dot?: number;
  /** One full pulse cycle in ms. */
  cycle?: number;
  label?: string;
  className?: string;
}) {
  const delay = (i: number): number | null => {
    const col = i % 4;
    const row = Math.floor(i / 4);
    switch (variant) {
      case "scan":
        return (3 - col) * (cycle / 10);
      case "twinkle":
        return TWINKLE[i] * (cycle / 16);
      case "orbit": {
        const k = RING.indexOf(i);
        return k === -1 ? null : k * (cycle / 8);
      }
      case "pulse":
        return INNER.includes(i) ? 0 : cycle * 0.16;
      case "wave":
        return (3 - col + row) * (cycle / 12);
    }
  };
  return (
    // dir=ltr so column 0 is always the physical left; the delay tables decide the direction.
    <span role="status" aria-label={label} dir="ltr" className={cn("inline-grid", className)} style={{ gridTemplateColumns: `repeat(4, ${dot}px)`, gap: dot }}>
      {Array.from({ length: 16 }, (_, i) => {
        const hole = rounded && CORNERS.includes(i);
        const d = delay(i);
        return (
          <i
            key={i}
            className={cn("block rounded-[1px] bg-foreground/25", hole && "invisible")}
            style={{ width: dot, height: dot, animation: hole || d === null ? undefined : `matrix-pulse ${cycle}ms ease-in-out ${Math.round(d)}ms infinite` }}
          />
        );
      })}
    </span>
  );
}

