"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * ذره‌بین تصویر. A round lens follows the pointer and shows the photo
 * magnified underneath it, for product shots and detailed images. The lens
 * grows in on enter and shrinks away on leave; it is decorative, so the
 * image's alt text carries the meaning.
 */
export function ImageLens({
  src,
  alt,
  zoom = 2.2,
  lens = 128,
  className,
}: {
  src: string;
  alt: string;
  /** Magnification inside the lens. */
  zoom?: number;
  /** Lens diameter in px. */
  lens?: number;
  className?: string;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [p, setP] = React.useState({ x: 0, y: 0, w: 1, h: 1, on: false });

  const track = (e: React.PointerEvent) => {
    const r = ref.current!.getBoundingClientRect();
    setP({ x: e.clientX - r.left, y: e.clientY - r.top, w: r.width, h: r.height, on: true });
  };

  return (
    <div
      ref={ref}
      onPointerEnter={track}
      onPointerMove={track}
      onPointerLeave={() => setP((s) => ({ ...s, on: false }))}
      className={cn("relative cursor-crosshair touch-none overflow-hidden", className)}
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- registry items stay framework-agnostic */}
      <img src={src} alt={alt} draggable={false} className="size-full select-none object-cover" />
      <div
        aria-hidden
        className="pointer-events-none absolute rounded-full border-2 border-white/90 shadow-[0_8px_30px_rgb(0_0_0/0.35)] transition-[opacity,scale] duration-200 ease-out"
        style={{
          width: lens,
          height: lens,
          left: p.x - lens / 2,
          top: p.y - lens / 2,
          opacity: p.on ? 1 : 0,
          scale: p.on ? "1" : "0.4",
          backgroundImage: `url("${src}")`,
          backgroundRepeat: "no-repeat",
          backgroundSize: `${p.w * zoom}px ${p.h * zoom}px`,
          backgroundPosition: `${lens / 2 - p.x * zoom}px ${lens / 2 - p.y * zoom}px`,
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * دکمه‌ی پرشونده. On hover a circle of ink grows from the exact point where
 * the pointer came in and floods the button; on leave it drains back out
 * through the point where the pointer left. Keyboard focus fills from the
 * centre. No keyframes needed, just a transition.
 */
export function FillButton({
  children,
  className,
  fillClassName = "bg-foreground",
  activeTextClassName = "text-background",
  onPointerEnter,
  onPointerLeave,
  onFocus,
  onBlur,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Colour of the flood. */
  fillClassName?: string;
  /** Text colour while filled. */
  activeTextClassName?: string;
}) {
  const ref = React.useRef<HTMLButtonElement>(null);
  const [fill, setFill] = React.useState({ x: 50, y: 50, on: false });

  const at = (e: React.PointerEvent, on: boolean) => {
    const r = ref.current!.getBoundingClientRect();
    setFill({ x: ((e.clientX - r.left) / r.width) * 100, y: ((e.clientY - r.top) / r.height) * 100, on });
  };

  return (
    <button
      ref={ref}
      type="button"
      {...props}
      onPointerEnter={(e) => { at(e, true); onPointerEnter?.(e); }}
      onPointerLeave={(e) => { at(e, false); onPointerLeave?.(e); }}
      onFocus={(e) => { if (e.currentTarget.matches(":focus-visible")) setFill({ x: 50, y: 50, on: true }); onFocus?.(e); }}
      onBlur={(e) => { setFill((f) => ({ ...f, on: false })); onBlur?.(e); }}
      className={cn(
        "relative isolate inline-flex h-11 cursor-pointer items-center justify-center gap-2 overflow-hidden rounded-full border border-foreground px-6 text-sm font-semibold transition-colors duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 [&_svg]:size-4",
        fill.on && activeTextClassName,
        className,
      )}
    >
      <span
        aria-hidden
        className={cn("pointer-events-none absolute -z-10 aspect-square w-[250%] rounded-full transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)]", fillClassName)}
        style={{ left: `${fill.x}%`, top: `${fill.y}%`, transform: `translate(-50%, -50%) scale(${fill.on ? 1 : 0})` }}
      />
      {children}
    </button>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * دکمه‌ی غلتان. On hover each word of the label rolls up out of view and a
 * copy rolls in from below, word after word from the right, so the label
 * reads as if a drum turned. Splits on words only, never letters, so Persian
 * stays joined. Pure CSS, no keyframes.
 */
export function RollButton({
  children,
  icon,
  stagger = 35,
  className,
  ...props
}: Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
  children: string;
  /** Optional trailing icon that rolls with the label. */
  icon?: React.ReactNode;
  /** ms between words. */
  stagger?: number;
}) {
  const words = children.split(/\s+/).filter(Boolean);
  const roll = (node: React.ReactNode, i: number, key: React.Key) => (
    <span key={key} className="relative inline-flex overflow-hidden">
      <span
        className="inline-flex transition-transform duration-500 ease-[cubic-bezier(0.65,0,0.35,1)] group-hover:-translate-y-full group-focus-visible:-translate-y-full"
        style={{ transitionDelay: `${i * stagger}ms` }}
      >
        {node}
      </span>
      <span
        aria-hidden
        className="absolute inset-0 inline-flex translate-y-full transition-transform duration-500 ease-[cubic-bezier(0.65,0,0.35,1)] group-hover:translate-y-0 group-focus-visible:translate-y-0"
        style={{ transitionDelay: `${i * stagger}ms` }}
      >
        {node}
      </span>
    </span>
  );
  return (
    <button
      type="button"
      aria-label={children}
      {...props}
      className={cn(
        "group inline-flex h-11 cursor-pointer items-center justify-center gap-[0.3em] rounded-control bg-primary px-6 text-sm font-semibold text-primary-foreground shadow-control focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 [&_svg]:size-4",
        className,
      )}
    >
      <span aria-hidden className="inline-flex gap-[0.3em]">{words.map((w, i) => roll(w, i, i))}</span>
      {icon != null && <span aria-hidden className="ms-1 inline-flex">{roll(icon, words.length, "icon")}</span>}
    </button>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

const INTERACTIVE = "a, button, [role=button], input, textarea, select, label, [data-cursor]";

/**
 * نشانگر حلقه‌ای. Inside the zone a small dot sits on the pointer and a ring
 * trails it with a soft lag. Over links and buttons the ring swells and
 * tints; over an element with `data-cursor="متن"` it grows into a label
 * bubble; pressing squeezes it. Only on fine pointers; touch keeps the
 * normal behaviour.
 */
export function CursorRing({
  children,
  className,
  lag = 0.18,
  size = 34,
  hideCursor = true,
}: {
  children: React.ReactNode;
  className?: string;
  /** 0–1, how quickly the ring catches up per frame. */
  lag?: number;
  /** Ring diameter at rest, px. */
  size?: number;
  /** Hide the system cursor inside the zone. */
  hideCursor?: boolean;
}) {
  const zone = React.useRef<HTMLDivElement>(null);
  const dot = React.useRef<HTMLDivElement>(null);
  const ring = React.useRef<HTMLDivElement>(null);
  const [fine, setFine] = React.useState(false);
  const [state, setState] = React.useState<{ on: boolean; hot: boolean; down: boolean; label: string | null }>({ on: false, hot: false, down: false, label: null });

  React.useEffect(() => {
    const mq = window.matchMedia("(pointer: fine)");
    const sync = () => setFine(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  React.useEffect(() => {
    const el = zone.current;
    if (!fine || !el) return;
    const target = { x: 0, y: 0 };
    const pos = { x: 0, y: 0 };
    let raf = 0;
    let first = true;

    const frame = () => {
      pos.x += (target.x - pos.x) * lag;
      pos.y += (target.y - pos.y) * lag;
      if (ring.current) ring.current.style.translate = `${pos.x}px ${pos.y}px`;
      raf = Math.hypot(target.x - pos.x, target.y - pos.y) > 0.1 ? requestAnimationFrame(frame) : 0;
    };
    const move = (e: PointerEvent) => {
      const r = el.getBoundingClientRect();
      target.x = e.clientX - r.left;
      target.y = e.clientY - r.top;
      if (first) {
        pos.x = target.x;
        pos.y = target.y;
        first = false;
      }
      if (dot.current) dot.current.style.translate = `${target.x}px ${target.y}px`;
      if (!raf) raf = requestAnimationFrame(frame);
      const hit = (e.target as Element | null)?.closest?.(INTERACTIVE);
      const label = hit?.getAttribute("data-cursor") || null;
      setState((s) => (s.on && s.hot === !!hit && s.label === label ? s : { ...s, on: true, hot: !!hit, label }));
    };
    const leave = () => {
      first = true;
      setState((s) => ({ ...s, on: false, down: false }));
    };
    const down = () => setState((s) => ({ ...s, down: true }));
    const up = () => setState((s) => ({ ...s, down: false }));

    el.addEventListener("pointermove", move);
    el.addEventListener("pointerleave", leave);
    el.addEventListener("pointerdown", down);
    window.addEventListener("pointerup", up);
    return () => {
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerleave", leave);
      el.removeEventListener("pointerdown", down);
      window.removeEventListener("pointerup", up);
      cancelAnimationFrame(raf);
    };
  }, [fine, lag]);

  const grow = state.label ? 2.4 : state.hot ? 1.7 : 1;
  const d = Math.round(size * grow * (state.down ? 0.8 : 1));
  return (
    <div
      ref={zone}
      className={cn("relative", fine && hideCursor && "cursor-none [&_*]:cursor-none", className)}
    >
      {children}
      {fine && (
        <>
          <div
            ref={ring}
            aria-hidden
            className="pointer-events-none absolute left-0 top-0 z-50"
            style={{ opacity: state.on ? 1 : 0, transition: "opacity 200ms" }}
          >
            {/* Size, not scale, changes so the label text stays crisp. */}
            <div
              className={cn(
                "flex items-center justify-center overflow-hidden rounded-full border transition-[width,height,margin,background-color,border-color] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
                state.label ? "border-transparent bg-foreground" : state.hot ? "border-foreground/30 bg-foreground/10" : "border-foreground/60 bg-transparent",
              )}
              style={{ width: d, height: d, margin: -d / 2 }}
            >
              {state.label && (
                <span className="whitespace-nowrap text-xs font-semibold text-background" style={{ animation: "fade-in 200ms 120ms both" }}>
                  {state.label}
                </span>
              )}
            </div>
          </div>
          <div
            ref={dot}
            aria-hidden
            className="pointer-events-none absolute left-0 top-0 z-50"
            style={{ opacity: state.on && !state.label ? 1 : 0, transition: "opacity 150ms" }}
          >
            <div className="-m-[3px] size-1.5 rounded-full bg-foreground" />
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * هیروی ورودی. A hero section that assembles itself in sequence: the eyebrow
 * pops, the headline rises line by line out of masks, the description
 * clears from blur and the actions float up. Behind it a soft spotlight
 * tracks the pointer over a faint grid. Needs the `pop`, `line-rise`,
 * `blur-in` and `fade-up` keyframes.
 */
export function HeroIntro({
  eyebrow,
  title,
  description,
  actions,
  spotlight = true,
  className,
}: {
  eyebrow?: React.ReactNode;
  /** One entry per headline line. */
  title: React.ReactNode[];
  description?: React.ReactNode;
  actions?: React.ReactNode;
  /** Pointer-following glow behind the content. */
  spotlight?: boolean;
  className?: string;
}) {
  const ref = React.useRef<HTMLElement>(null);
  const [glow, setGlow] = React.useState<{ x: number; y: number } | null>(null);
  const ease = "cubic-bezier(0.16,1,0.3,1)";
  const t = (step: number) => 150 + step * 120;
  const titleEnd = t(1) + (title.length - 1) * 110;

  return (
    <section
      ref={ref}
      onPointerMove={(e) => {
        if (!spotlight || e.pointerType !== "mouse") return;
        const r = ref.current!.getBoundingClientRect();
        setGlow({ x: e.clientX - r.left, y: e.clientY - r.top });
      }}
      onPointerLeave={() => setGlow(null)}
      className={cn("relative isolate flex flex-col items-center overflow-hidden px-6 py-16 text-center", className)}
    >
      {/* Faint grid that fades out toward the edges. */}
      <div
        aria-hidden
        className="absolute inset-0 -z-20 opacity-60 [mask-image:radial-gradient(ellipse_at_center,black_20%,transparent_70%)]"
        style={{
          backgroundImage:
            "linear-gradient(to right, color-mix(in oklab, var(--foreground) 8%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklab, var(--foreground) 8%, transparent) 1px, transparent 1px)",
          backgroundSize: "32px 32px",
          animation: "fade-in 1.2s ease both",
        }}
      />
      {spotlight && (
        <div
          aria-hidden
          className="absolute -z-10 size-[420px] rounded-full transition-opacity duration-500"
          style={{
            left: (glow?.x ?? 0) - 210,
            top: (glow?.y ?? 0) - 210,
            opacity: glow ? 1 : 0,
            background: "radial-gradient(circle, color-mix(in oklab, var(--foreground) 12%, transparent), transparent 65%)",
          }}
        />
      )}

      {eyebrow != null && (
        <div className="mb-5" style={{ animation: `pop 500ms ${ease} ${t(0)}ms both` }}>
          {eyebrow}
        </div>
      )}

      <h1 className="max-w-3xl text-balance font-display text-4xl font-black leading-[1.25] tracking-tight sm:text-5xl">
        {title.map((line, i) => (
          <span key={i} className="-my-[0.12em] block overflow-hidden py-[0.12em]">
            <span className="block" style={{ animation: `line-rise 900ms ${ease} ${t(1) + i * 110}ms both` }}>
              {line}
            </span>
          </span>
        ))}
      </h1>

      {description != null && (
        <p
          className="mt-5 max-w-xl text-pretty text-base leading-8 text-muted-foreground"
          style={{ animation: `blur-in 800ms ${ease} ${titleEnd + 250}ms both` }}
        >
          {description}
        </p>
      )}

      {actions != null && (
        <div
          className="mt-8 flex flex-wrap items-center justify-center gap-3"
          style={{ animation: `fade-up 700ms ${ease} ${titleEnd + 450}ms both` }}
        >
          {actions}
        </div>
      )}
    </section>
  );
}

