import { cn } from "@/lib/utils";

/** شبکه. Hairline grid that fades toward the bottom. Drop inside a `relative` parent. */
export function GridBackground({ size = 56, className }: { size?: number; className?: string }) {
  return (
    <div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 [mask-image:linear-gradient(to_bottom,black_55%,transparent)]", className)}
      style={{
        backgroundImage: "linear-gradient(to right, oklch(from var(--foreground) l c h / 6%) 1px, transparent 1px), linear-gradient(to bottom, oklch(from var(--foreground) l c h / 6%) 1px, transparent 1px)",
        backgroundSize: `${size}px ${size}px`,
      }}
    />
  );
}

import { cn } from "@/lib/utils";

/** نقطه‌ای. Tiny dots on a grid; keep it under 12% opacity so text stays readable. */
export function DotsBackground({ size = 22, className }: { size?: number; className?: string }) {
  return (
    <div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 [mask-image:linear-gradient(to_bottom,black_55%,transparent)]", className)}
      style={{ backgroundImage: "radial-gradient(oklch(from var(--foreground) l c h / 12%) 1px, transparent 1px)", backgroundSize: `${size}px ${size}px` }}
    />
  );
}

import { cn } from "@/lib/utils";

/**
 * گره. Tiled eight-point stars (شمسه) — two squares rotated 45° — the
 * same geometry as classic Persian tilework, drawn as an inline SVG tile.
 */
export function GirihBackground({ size = 56, className }: { size?: number; className?: string }) {
  const s = size;
  const inset = s * 0.29;
  const side = s - inset * 2;
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${s}' height='${s}' viewBox='0 0 ${s} ${s}'><g fill='none' stroke='rgba(128,128,128,0.35)' stroke-width='1'><rect x='${inset}' y='${inset}' width='${side}' height='${side}' rx='2'/><rect x='${inset}' y='${inset}' width='${side}' height='${side}' rx='2' transform='rotate(45 ${s / 2} ${s / 2})'/></g></svg>`;
  return (
    <div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 [mask-image:radial-gradient(ellipse_at_center,black_40%,transparent_90%)]", className)}
      style={{ backgroundImage: `url("data:image/svg+xml,${encodeURIComponent(svg)}")`, backgroundSize: `${s}px ${s}px` }}
    />
  );
}

import { cn } from "@/lib/utils";

/** هاشور. Diagonal hairlines for spacer bands and "under construction" areas. */
export function HatchBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0", className)}
      style={{ backgroundImage: "repeating-linear-gradient(-45deg, oklch(from var(--foreground) l c h / 6%) 0 1px, transparent 1px 9px)" }}
    />
  );
}

import { cn } from "@/lib/utils";

/** شفق. Three blurred blobs drifting slowly. Needs the `aurora` keyframes. */
export function AuroraBackground({ className }: { className?: string }) {
  const blob = "absolute rounded-full blur-3xl";
  return (
    <div aria-hidden className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}>
