  float px=1.4/u_resolution.y*u_dpr;
  float acc=0.0;
  vec3 col=vec3(0.0);
  for(int L=0;L<3;L++){
    float fl=float(L);
    float sectors=70.0+fl*45.0;
    float s=floor(a*sectors);
    float h=hash(vec2(s,fl*7.13+1.0));
    float z=fract(h*13.7+u_time*(0.12+h*0.22));
    float head=z*z*1.3;
    float len=(0.03+z*0.35)*u_streak;
    float arc=abs(fract(a*sectors)-0.5)/sectors*2.0*PI*r;
    float core=smoothstep(px*(1.0+z*1.5),0.0,arc);
    float along=smoothstep(head-len,head,r)*step(r,head);
    float v=core*along*z*(0.4+h);
    acc+=v;
    col+=v*mix(u_color1,u_color0,step(0.7,h));
  }
  col/=max(acc,1e-4);
  float glow=exp(-r*7.0)*0.35;
  col=mix(col,u_color0,glow/(acc+glow+1e-4));
  gl_FragColor=vec4(col,clamp(acc+glow,0.0,1.0)*u_opacity);
}`;

/** ابرفضا. Stars stretch into streaks and race out of a vanishing point, as if jumping to light speed; the pointer shifts the vanishing point a little. WebGL via ShaderCanvas. */
export function HyperspaceBackground({
  speed = 1,
  opacity = 0.9,
  streak = 1,
  className,
}: {
  speed?: number;
  opacity?: number;
  /** Streak length multiplier. */
  streak?: number;
  className?: string;
}) {
  return <ShaderCanvas fragment={FRAG} colors={["--brand", "--foreground"]} uniforms={{ u_opacity: opacity, u_streak: streak }} speed={speed} pointer className={className} />;
}

"use client";

import { GLSL_NOISE, ShaderCanvas } from "@/components/backgrounds/shader";

const FRAG = GLSL_NOISE + /* glsl */ `
uniform float u_opacity;uniform float u_count;
void main(){
  vec2 uv=gl_FragCoord.xy/u_resolution;
  float asp=u_resolution.x/u_resolution.y;
  float x=uv.x*asp;
  float t=u_time*0.3;
  float acc=0.0;
  float tone=0.0;
  for(int i=0;i<8;i++){
    float fi=float(i);
    if(fi>=u_count) break;
    float h=hash(vec2(fi,3.7));
    float cx=(fi+0.5)/u_count*asp+0.18*sin(t*(0.4+h*0.5)+fi*1.7);
    cx+=(uv.y-0.5)*0.35*(h-0.5);
    float w=0.035+0.06*h;
    float d=x-cx;
    float b=exp(-d*d/(w*w));
    float streak=noise(vec2(d*55.0+fi*9.0,uv.y*1.6-t*(0.6+h)));
    float v=b*(0.45+0.55*streak);
    acc+=v;
    tone+=v*h;
  }
  float fall=mix(0.15,1.0,smoothstep(0.0,1.0,uv.y));
  vec3 col=mix(u_color1,u_color0,clamp(tone/max(acc,1e-4)*1.6,0.0,1.0));
  gl_FragColor=vec4(col,clamp(acc*fall,0.0,1.0)*u_opacity);
}`;

/** ستون‌های نور. Soft vertical shafts of light that sway and shimmer, brightest at the top, like stage lights in haze. WebGL via ShaderCanvas. */
export function BeamsBackground({
  speed = 1,
  opacity = 0.6,
  count = 6,
  className,
