            <div className="mt-3 grid grid-cols-4 gap-2">{[1, 2, 3, 4].map((i) => <span key={i} className={`aspect-square rounded-lg border ${i === 1 ? "border-foreground" : "border-border"} bg-card`} />)}</div>
