            <div>
              <p className="mb-2 text-sm font-medium">ویژگی‌ها</p>
              <dl className="grid grid-cols-2 gap-2 text-sm">{specs.map(([k, v]) => <div key={k} className="rounded-lg bg-secondary/60 p-2.5"><dt className="text-xs text-muted-foreground">{k}</dt><dd className="font-medium">{v}</dd></div>)}</dl>
            </div>
            <Tabs defaultValue="desc" variant="underline">
              <TabsList aria-label="جزئیات"><TabsTrigger value="desc">معرفی</TabsTrigger><TabsTrigger value="specs">مشخصات</TabsTrigger><TabsTrigger value="reviews">نظرات</TabsTrigger></TabsList>
              <TabsContent value="desc" className="text-sm leading-7 text-muted-foreground">هدفون X۲ با حذف نویز فعال و ۳۰ ساعت شارژ برای سفر و کار طراحی شده. اتصال هم‌زمان به دو دستگاه و شارژ سریع ۱۰ دقیقه‌ای برای ۵ ساعت پخش.</TabsContent>
              <TabsContent value="specs" className="text-sm text-muted-foreground">مشخصات کامل در جدول بالا.</TabsContent>
              <TabsContent value="reviews" className="text-sm text-muted-foreground">۱٬۲۴۰ نظر ثبت شده.</TabsContent>
            </Tabs>
          </div>

          {/* seller box */}
          <aside className="h-fit space-y-4 rounded-2xl border border-border bg-card p-5 lg:col-span-3">
            <div className="flex items-center gap-2 text-sm"><Store className="size-4 text-muted-foreground" /><span className="font-medium">فروشگاه صوتی آوا</span><Badge variant="success" className="ms-auto">عملکرد عالی</Badge></div>
            <div className="flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck className="size-4" />گارانتی ۱۸ ماهه‌ی شرکتی</div>
            <div className="flex items-center gap-2 text-xs text-muted-foreground"><Truck className="size-4" />ارسال امروز · موجود در انبار</div>
            <div className="border-t border-border pt-4"><Price amount={price} original={2_190_000} size="md" /></div>
            <div className="flex items-center justify-between"><span className="text-sm">تعداد</span><NumberField value={qty} min={1} max={5} onChange={setQty} aria-label="تعداد" /></div>
            <Button className="w-full" onClick={() => setCartOpen(true)}><ShoppingCart />افزودن به سبد</Button>
            <p className="text-center text-[11px] text-muted-foreground">۷ روز ضمانت بازگشت · پرداخت در محل</p>
          </aside>
        </div>

        <section className="mt-12">
          <h2 className="mb-4 text-lg font-bold">کالاهای مشابه</h2>
          <Carousel slideWidth={0.5} showDots={false}>
            {similar.map((s) => (
              <div key={s} className="rounded-xl border border-border bg-card p-4"><div className="flex h-28 items-center justify-center rounded-lg bg-secondary text-3xl">🎧</div><p className="mt-3 text-sm font-medium">{s}</p><p className="text-xs text-muted-foreground">{formatToman(890_000)}</p></div>
            ))}
          </Carousel>
        </section>
      </main>

      <Sheet open={cartOpen} onOpenChange={setCartOpen} title={`سبد خرید (${fa(qty)})`}>
        <div className="flex h-full flex-col">
          <div className="flex items-center gap-3 rounded-lg border border-border p-3"><span className="text-3xl">🎧</span><div className="flex-1 text-sm"><p className="font-medium">هدفون بی‌سیم مدل X۲</p><p className="text-xs text-muted-foreground">{colors[color]} · {fa(qty)} عدد</p></div><span className="text-sm font-semibold">{formatToman(price * qty)}</span></div>
          <div className="mt-auto space-y-3 pt-6"><div className="flex justify-between text-sm"><span className="text-muted-foreground">جمع</span><span className="font-bold">{formatToman(price * qty)}</span></div><Button className="w-full">ادامه‌ی خرید</Button></div>
        </div>
      </Sheet>
    </div>
  );
}

"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { Field, Input } from "@/components/ui/input";
import { PhoneInput } from "@/components/ui/phone-input";
import { OtpField } from "@/components/ui/otp-field";
import { Stepper } from "@/components/ui/stepper";
import { RadioGroup } from "@/components/ui/radio-group";
import { SuccessCheck } from "@/components/animations/success-check";
import { fa } from "@/lib/utils";

/** ثبت‌نام پیامکی: موبایل → کد تأیید → پروفایل → پایان. */
export function OnboardingPage() {
  const [step, setStep] = React.useState(0);
  const [phone, setPhone] = React.useState("");
  const [valid, setValid] = React.useState(false);
  return (
    <div className="flex min-h-dvh items-center justify-center bg-background p-4 text-foreground">
      <div className="w-full max-w-md rounded-2xl border border-border bg-card p-6 sm:p-8">
        <Stepper current={step} steps={[{ label: "موبایل" }, { label: "کد تأیید" }, { label: "پروفایل" }]} className="mb-8" />
        {step === 0 && (
          <form className="space-y-5" onSubmit={(e) => { e.preventDefault(); if (valid) setStep(1); }}>
            <div><h1 className="text-lg font-bold">خوش آمدید</h1><p className="mt-1 text-sm text-muted-foreground">با شماره‌ی موبایل شروع کنید؛ رمز لازم نیست.</p></div>
            <div className="space-y-1.5"><span className="text-sm font-medium">شماره‌ی موبایل</span><PhoneInput value={phone} onChange={(d, v) => { setPhone(d); setValid(v); }} autoFocus /></div>
            <Button type="submit" className="w-full" disabled={!valid}>دریافت کد</Button>
          </form>
        )}
        {step === 1 && (
          <div className="space-y-5">
            <div><h1 className="text-lg font-bold">کد تأیید</h1><p className="mt-1 text-sm text-muted-foreground">کد ۶ رقمی به ۰{fa(phone)} پیامک شد.</p></div>
            <div className="flex justify-center"><OtpField onComplete={() => setStep(2)} /></div>
            <button type="button" onClick={() => setStep(0)} className="cursor-pointer text-xs text-muted-foreground hover:text-foreground">تغییر شماره</button>
          </div>
        )}
        {step === 2 && (
          <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); setStep(3); }}>
            <div><h1 className="text-lg font-bold">کمی درباره‌ی خودتان</h1><p className="mt-1 text-sm text-muted-foreground">بعداً هم می‌توانید عوض کنید.</p></div>
            <Field label="نام و نام خانوادگی" htmlFor="o-n"><Input id="o-n" placeholder="مثلاً: سارا محمدی" required /></Field>
            <Field label="ایمیل (اختیاری)" htmlFor="o-e"><Input id="o-e" type="email" dir="ltr" placeholder="you@example.com" /></Field>
            <div className="space-y-1.5"><span className="text-sm font-medium">از دکان برای چه استفاده می‌کنید؟</span><RadioGroup defaultValue="shop" options={[{ value: "shop", label: "فروشگاه دارم" }, { value: "buy", label: "خرید می‌کنم" }, { value: "dev", label: "برای مشتری‌هایم می‌سازم" }]} /></div>
            <Button type="submit" className="w-full">شروع</Button>
          </form>
        )}
        {step === 3 && (
          <div className="flex flex-col items-center py-6 text-center">
            <SuccessCheck label="حساب شما آماده است" />
            <p className="mt-3 max-w-xs text-sm text-muted-foreground">اولین محصول را اضافه کنید یا یک نگاه به داشبورد بیندازید.</p>
            <div className="mt-6 flex gap-2"><Button>رفتن به داشبورد</Button><Button variant="outline" onClick={() => setStep(0)}>از اول</Button></div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Download, Filter, MoreHorizontal, Pencil, Printer, Trash2 } from "lucide-react";
import { DataTable, type Column } from "@/components/ui/data-table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { DatePicker } from "@/components/ui/date-picker";
import { Select } from "@/components/ui/select";
import { DropdownMenu } from "@/components/ui/dropdown-menu";
import { Avatar } from "@/components/ui/avatar";
import { Stat } from "@/components/ui/stat";
import { fa, faNumber, formatToman } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

type Status = "paid" | "pending" | "shipped" | "canceled";
type Order = { id: number; customer: string; amount: number; status: Status; date: Date; items: number; [k: string]: unknown };

const STATUS: Record<Status, { label: string; tone: "success" | "warning" | "brand" | "destructive" }> = {
  paid: { label: "پرداخت‌شده", tone: "success" }, pending: { label: "در انتظار", tone: "warning" }, shipped: { label: "ارسال‌شده", tone: "brand" }, canceled: { label: "لغو شده", tone: "destructive" },
};
const names = ["مریم احمدی", "علی رضایی", "نگار کریمی", "رضا موسوی", "سارا محمدی", "امیر حسینی", "مینا صادقی", "حسین نوری", "الهام رحیمی", "کامران زارع", "فاطمه یوسفی", "بهرام کاظمی"];
const statuses: Status[] = ["paid", "pending", "shipped", "paid", "canceled", "paid", "shipped", "pending", "paid", "paid", "shipped", "paid"];
const orders: Order[] = names.map((customer, i) => ({ id: 14052 - i, customer, amount: (i * 937 + 350) * 1000 + 240_000, status: statuses[i], date: new Date(Date.now() - i * 864e5 * 1.3), items: (i % 4) + 1 }));

/** مدیریت سفارش‌ها: جدول داده با فیلتر تاریخ شمسی، وضعیت، منوی عمل و آمار بالا. */
export function AdminOrdersPage() {
  const [status, setStatus] = React.useState("all");
  const [from, setFrom] = React.useState<Date | null>(null);
  const rows = orders.filter((o) => (status === "all" || o.status === status) && (!from || o.date >= from));

  const columns: Column<Order>[] = [
    { key: "id", header: "شماره", sortable: true, cell: (o) => <span className="font-mono text-xs text-muted-foreground" dir="ltr">#{fa(o.id)}</span> },
    { key: "customer", header: "مشتری", sortable: true, cell: (o) => <span className="flex items-center gap-2"><Avatar name={o.customer} size="sm" />{o.customer}</span> },
    { key: "date", header: "تاریخ", sortable: true, cell: (o) => formatJalali(o.date) },
    { key: "items", header: "اقلام", numeric: true, cell: (o) => fa(o.items) },
    { key: "amount", header: "مبلغ", sortable: true, numeric: true, cell: (o) => formatToman(o.amount) },
    { key: "status", header: "وضعیت", sortable: true, cell: (o) => <Badge variant={STATUS[o.status].tone}>{STATUS[o.status].label}</Badge> },
    { key: "actions", header: "", className: "w-10", cell: () => <DropdownMenu align="end" trigger={<Button variant="ghost" size="icon" className="size-8" aria-label="بیشتر"><MoreHorizontal /></Button>} items={[{ label: "ویرایش", icon: Pencil }, { label: "چاپ فاکتور", icon: Printer }, { type: "separator" }, { label: "لغو سفارش", icon: Trash2, danger: true }]} /> },
  ];

  return (
    <div className="min-h-dvh bg-background p-4 text-foreground sm:p-8">
      <div className="mx-auto max-w-6xl space-y-6">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div><h1 className="text-xl font-bold">سفارش‌ها</h1><p className="text-sm text-muted-foreground">{formatJalali(new Date(), { weekday: true })}</p></div>
          <Button variant="outline" size="sm"><Download />خروجی اکسل</Button>
        </div>
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          <Stat label="فروش این هفته" value={faNumber(rows.reduce((s, o) => s + o.amount, 0))} unit="تومان" delta={12} />
          <Stat label="سفارش‌های باز" value={fa(rows.filter((o) => o.status === "pending").length)} delta={-3} />
          <Stat label="میانگین سبد" value={faNumber(Math.round(rows.reduce((s, o) => s + o.amount, 0) / Math.max(1, rows.length)))} unit="تومان" delta={6} />
        </div>
        <DataTable<Order>
          rows={rows}
          columns={columns}
          rowKey={(o) => String(o.id)}
          searchKeys={["customer", "id"]}
          searchPlaceholder="جست‌وجوی مشتری یا شماره…"
          pageSize={8}
          toolbar={
            <>
              <div className="w-40"><Select value={status} onChange={(e) => setStatus(e.target.value)} className="h-9" options={[{ value: "all", label: "همه‌ی وضعیت‌ها" }, ...Object.entries(STATUS).map(([v, s]) => ({ value: v, label: s.label }))]} /></div>
              <div className="w-56"><DatePicker value={from} onChange={setFrom} placeholder="از تاریخ" compact /></div>
              {(status !== "all" || from) && <Button variant="ghost" size="sm" onClick={() => { setStatus("all"); setFrom(null); }}><Filter />پاک کردن فیلتر</Button>}
            </>
          }
        />
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { MapPin, Scissors, Stethoscope } from "lucide-react";
import { SlotPicker, type SlotValue } from "@/components/calendar/slot-picker";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar } from "@/components/ui/avatar";
import { RadioGroup } from "@/components/ui/radio-group";
import { PhoneInput } from "@/components/ui/phone-input";
import { fa, formatToman } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";
import { atMinutes, formatTimeRange } from "@/lib/calendar-utils";

const services = [
  { value: "cut", label: "اصلاح مو", description: "۴۵ دقیقه · ۲۸۰ هزار تومان", price: 280_000, minutes: 45, icon: Scissors },
  { value: "color", label: "رنگ مو", description: "۲ ساعت · ۹۵۰ هزار تومان", price: 950_000, minutes: 120, icon: Scissors },
  { value: "consult", label: "مشاوره‌ی پوست", description: "۳۰ دقیقه · ۴۰۰ هزار تومان", price: 400_000, minutes: 30, icon: Stethoscope },
];
const hours: [string, string][] = [["10:00", "13:30"], ["14:00", "19:00"]];

/** Booked appointments of a day. Replace with your API. */
function bookedOn(key: string) {
  const seed = Number(key.slice(-2));
  return [630, 840, 1020].filter((_, i) => (seed + i) % 2 === 0).map((m) => ({ start: atMinutes(key, m), end: atMinutes(key, m + 45) }));
}

/** رزرو نوبت: سرویس، روز و ساعت خالی (جمعه‌ها و تعطیلات رسمی بسته) و تأیید. */
export function BookingPage() {
  const [service, setService] = React.useState("cut");
  const [slot, setSlot] = React.useState<SlotValue>(null);
  const chosen = services.find((s) => s.value === service)!;
  return (
    <div className="min-h-dvh bg-background text-foreground">
      <header className="border-b border-border"><div className="mx-auto flex h-14 max-w-5xl items-center gap-3 px-4"><Avatar name="سالن نگار" /><div><p className="text-sm font-bold">سالن زیبایی نگار</p><p className="flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="size-3" />تهران، سعادت‌آباد</p></div><Badge variant="success" className="ms-auto">امروز باز است</Badge></div></header>
      <main className="mx-auto grid max-w-5xl grid-cols-1 gap-6 px-4 py-8 lg:grid-cols-3">
        <section className="space-y-3"><h2 className="font-semibold">۱. سرویس</h2><RadioGroup variant="cards" value={service} onChange={(v) => { setService(v); setSlot(null); }} options={services} /></section>
        <section className="space-y-3">
          <h2 className="font-semibold">۲. روز و ساعت</h2>
          <SlotPicker key={service} value={slot} onChange={setSlot} duration={chosen.minutes} step={15} hours={hours} busy={(k) => bookedOn(k)} days={10} />
        </section>
        <section className="h-fit space-y-4 rounded-2xl border border-border bg-card p-5 lg:sticky lg:top-6">
          <h2 className="font-semibold">۳. تأیید</h2>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between"><dt className="text-muted-foreground">سرویس</dt><dd>{chosen.label}</dd></div>
            <div className="flex justify-between"><dt className="text-muted-foreground">روز</dt><dd>{slot ? formatJalali(slot.start, { weekday: true }) : "—"}</dd></div>
            <div className="flex justify-between"><dt className="text-muted-foreground">ساعت</dt><dd className="tabular-nums">{slot ? formatTimeRange(slot.start, slot.end) : "—"}</dd></div>
            <div className="flex justify-between border-t border-border pt-2 font-bold"><dt>بیعانه</dt><dd>{formatToman(Math.round(chosen.price * 0.3))}</dd></div>
          </dl>
          <div className="space-y-1.5"><span className="text-sm font-medium">شماره‌ی موبایل برای یادآوری</span><PhoneInput /></div>
          <Button className="w-full" disabled={!slot}>پرداخت بیعانه و ثبت نوبت</Button>
          <p className="text-[11px] text-muted-foreground">تا {fa(24)} ساعت قبل از نوبت می‌توانید رایگان لغو کنید.</p>
        </section>
      </main>
    </div>
  );
}

"use client";

import * as React from "react";
import { ArrowDownLeft, ArrowUpLeft, Eye, EyeOff, Plus, Wallet } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog } from "@/components/ui/dialog";
import { IbanInput } from "@/components/ui/iban-input";
import { Field, Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Odometer } from "@/components/animations/odometer";
import { cn, en, fa, faNumber, formatToman } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

const tx = [
  { id: 1, title: "واریز از کارت ۶۰۳۷", amount: 2_000_000, date: new Date(), kind: "in" as const },
  { id: 2, title: "خرید از دکان", amount: -890_000, date: new Date(Date.now() - 864e5), kind: "out" as const },
  { id: 3, title: "برداشت به شبا", amount: -1_500_000, date: new Date(Date.now() - 3 * 864e5), kind: "out" as const, pending: true },
  { id: 4, title: "بازگشت وجه سفارش #۱۴۰۴۹", amount: 640_000, date: new Date(Date.now() - 6 * 864e5), kind: "in" as const },
];

/** کیف پول: موجودی، تراکنش‌ها با تاریخ شمسی، شارژ سریع و برداشت به شبا. */
export function WalletPage() {
  const [hidden, setHidden] = React.useState(false);
  const [withdraw, setWithdraw] = React.useState(false);
  const [iban, setIban] = React.useState("");
  const [ibanOk, setIbanOk] = React.useState(false);
  const [amount, setAmount] = React.useState("");
  const balance = 2_100_000;
  const amt = Number(en(amount).replace(/\D/g, ""));
  return (
    <div className="min-h-dvh bg-background p-4 text-foreground sm:p-8">
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="relative overflow-hidden rounded-2xl border border-border bg-card p-6" style={{ backgroundImage: "radial-gradient(60% 80% at 100% 0%, oklch(from var(--brand) l c h / 22%), transparent 70%)" }}>
          <div className="flex items-center justify-between"><span className="flex items-center gap-2 text-sm text-muted-foreground"><Wallet className="size-4" />موجودی کیف پول</span><button type="button" onClick={() => setHidden((h) => !h)} aria-label={hidden ? "نمایش" : "پنهان"} className="cursor-pointer text-muted-foreground hover:text-foreground">{hidden ? <EyeOff className="size-4" /> : <Eye className="size-4" />}</button></div>
          <div className="mt-3 text-3xl font-bold">{hidden ? "•••••••" : <Odometer value={balance} unit="تومان" />}</div>
          <div className="mt-5 flex gap-2"><Button size="sm"><Plus />افزایش موجودی</Button><Button size="sm" variant="outline" onClick={() => setWithdraw(true)}>برداشت</Button></div>
        </div>

        <div className="rounded-2xl border border-border bg-card p-5">
          <p className="text-sm font-semibold">شارژ سریع</p>
          <div className="mt-3 flex flex-wrap gap-2">{[100_000, 200_000, 500_000, 1_000_000].map((v) => <button key={v} type="button" className="cursor-pointer rounded-full border border-border px-3 py-1.5 text-sm transition-colors hover:bg-accent">{faNumber(v)} تومان</button>)}</div>
        </div>

        <Tabs defaultValue="all" variant="underline">
          <TabsList aria-label="تراکنش‌ها"><TabsTrigger value="all">همه</TabsTrigger><TabsTrigger value="in">واریز</TabsTrigger><TabsTrigger value="out">برداشت</TabsTrigger></TabsList>
          {(["all", "in", "out"] as const).map((k) => (
            <TabsContent key={k} value={k}>
              <ul className="divide-y divide-border rounded-2xl border border-border bg-card">
                {tx.filter((t) => k === "all" || t.kind === k).map((t) => (
                  <li key={t.id} className="flex items-center gap-3 p-4">
                    <span className={cn("flex size-9 items-center justify-center rounded-full", t.kind === "in" ? "bg-success/15 text-success" : "bg-secondary text-foreground")}>{t.kind === "in" ? <ArrowDownLeft className="size-4" /> : <ArrowUpLeft className="size-4" />}</span>
                    <div className="min-w-0 flex-1"><p className="text-sm font-medium">{t.title}</p><p className="text-xs text-muted-foreground">{formatJalali(t.date, { weekday: true })}</p></div>
                    <div className="text-end"><p className={cn("text-sm font-semibold tabular-nums", t.kind === "in" ? "text-success" : "")}>{t.kind === "in" ? "+" : "−"}{formatToman(Math.abs(t.amount))}</p>{t.pending && <Badge variant="warning" className="mt-1">در انتظار تسویه</Badge>}</div>
                  </li>
                ))}
              </ul>
            </TabsContent>
          ))}
        </Tabs>
      </div>

      <Dialog open={withdraw} onOpenChange={setWithdraw} title="برداشت به حساب بانکی" description="تسویه‌ی شبا معمولاً تا ۲۴ ساعت کاری طول می‌کشد." footer={<><Button disabled={!ibanOk || !amt || amt > balance} onClick={() => setWithdraw(false)}>ثبت درخواست</Button><Button variant="ghost" onClick={() => setWithdraw(false)}>انصراف</Button></>}>
        <div className="space-y-4">
          <div className="space-y-1.5"><span className="text-sm font-medium">شماره‌ی شبا</span><IbanInput value={iban} onChange={(v, ok) => { setIban(v); setIbanOk(ok); }} /></div>
          <Field label="مبلغ (تومان)" htmlFor="w-a" hint={`حداکثر ${formatToman(balance)}`}><Input id="w-a" inputMode="numeric" value={amount ? faNumber(amt) : ""} onChange={(e) => setAmount(e.target.value)} placeholder="۵۰۰٬۰۰۰" error={amt > balance ? "بیشتر از موجودی است" : undefined} /></Field>
          <p className="text-xs text-muted-foreground">کارمزد: {fa(0)} تومان · واریز به نام صاحب حساب کیف پول</p>
        </div>
      </Dialog>
    </div>
  );
}

"use client";

import * as React from "react";
