];
const all = chapters.flatMap((c) => c.lessons);
const doneCount = all.filter((l) => l.done).length;
const totalMin = all.reduce((s, l) => s + l.min, 0);

/** صفحه‌ی دوره: ویدئو، سرفصل‌ها با پیشرفت، نظرات و کارت خرید چسبان. */
