            <Field label="مقصد" htmlFor="to" className="min-w-0 flex-1 basis-36">
              <Combobox key={`t${swapKey}`} className="w-full" options={cities} value={to} onChange={setTo} placeholder="شهر مقصد" />
            </Field>
            <Field label="تاریخ رفت" className="min-w-[12.5rem] flex-[1.2] basis-[12.5rem]">
              <DatePicker value={date} onChange={setDate} min={new Date()} clearable={false} weekday={false} />
            </Field>
            <Field label="مسافر" className="shrink-0">
              <NumberField value={pax} onChange={setPax} min={1} max={9} aria-label="تعداد مسافر" />
            </Field>
            <Button size="lg" className="h-10 shrink-0">جست‌وجو</Button>
          </div>
        </div>
      </section>

      <div className="mx-auto grid max-w-6xl gap-6 px-4 py-6 lg:grid-cols-4">
        <aside className="space-y-6 lg:col-span-1">
          <div className="rounded-2xl border border-border bg-card p-4">
            <h2 className="text-sm font-semibold">ایرلاین</h2>
            <div className="mt-3 space-y-2">{airlines.map((a) => <Checkbox key={a} label={a} checked={chosen.includes(a)} onCheckedChange={(on) => setChosen((c) => (on ? [...c, a] : c.filter((x) => x !== a)))} />)}</div>
          </div>
          <div className="rounded-2xl border border-border bg-card p-4">
            <Slider label="حداکثر قیمت" min={1_500_000} max={3_000_000} step={50_000} value={maxPrice} onChange={setMaxPrice} format={formatToman} />
          </div>
          <div className="rounded-2xl border border-border bg-card p-4">
            <h2 className="text-sm font-semibold">ساعت حرکت</h2>
            <div className="mt-3 grid grid-cols-2 gap-2 text-xs">{["صبح", "ظهر", "عصر", "شب"].map((t) => <button key={t} type="button" className="cursor-pointer rounded-lg border border-border px-2 py-1.5 transition-colors hover:bg-accent">{t}</button>)}</div>
          </div>
        </aside>

        <main className="lg:col-span-3">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div><h1 className="text-lg font-bold">{from} به {to}</h1><p className="text-xs text-muted-foreground">{date ? formatJalali(date, { weekday: true }) : "تاریخ را انتخاب کنید"} · {fa(pax)} مسافر · {fa(list.length)} پرواز</p></div>
            <div className="inline-flex rounded-lg border border-border bg-background p-0.5 text-xs">{sorts.map(([k, l]) => <button key={k} type="button" onClick={() => setSort(k)} className={cn("cursor-pointer rounded-md px-3 py-1 transition-colors", sort === k ? "bg-secondary font-semibold" : "text-muted-foreground hover:text-foreground")}>{l}</button>)}</div>
          </div>
          <ul className="mt-4 space-y-3">
            {list.map((f) => (
              <li key={f.id} className="grid gap-4 rounded-2xl border border-border bg-card p-4 transition-colors hover:border-foreground/25 md:grid-cols-[1fr_auto_auto] md:items-center">
                <div className="flex items-center gap-4">
                  <span className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-secondary text-sm font-bold">{f.airline.charAt(0)}</span>
                  <div className="flex flex-1 items-center gap-4">
                    <div className="text-center"><p className="text-xl font-bold tabular-nums">{fa(f.dep)}</p><p className="text-xs text-muted-foreground">{from}</p></div>
                    <div className="flex flex-1 flex-col items-center text-[11px] text-muted-foreground"><span>{f.dur}</span><span className="my-1 h-px w-full bg-border" /><span>بدون توقف</span></div>
                    <div className="text-center"><p className="text-xl font-bold tabular-nums">{fa(f.arr)}</p><p className="text-xs text-muted-foreground">{to}</p></div>
                  </div>
                </div>
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground md:flex-col md:items-start md:gap-1">
                  <span>{f.airline} · <span className="font-mono" dir="ltr">{f.no}</span></span>
                  <span className="flex gap-1.5"><Badge variant="secondary" className="text-[11px]">{f.cls}</Badge><Badge variant={f.kind === "چارتر" ? "warning" : "secondary"} className="text-[11px]">{f.kind}</Badge></span>
                </div>
                <div className="flex items-center justify-between gap-4 border-t border-border pt-3 md:flex-col md:items-end md:border-0 md:pt-0">
                  <div className="text-end"><p className="text-lg font-bold tabular-nums">{faNumber(f.price)} <span className="text-xs font-normal text-muted-foreground">تومان</span></p>{f.seats <= 3 ? <p className="text-[11px] text-destructive">فقط {fa(f.seats)} صندلی مانده</p> : <p className="text-[11px] text-muted-foreground">{fa(f.seats)} صندلی</p>}</div>
                  <Button size="sm">انتخاب</Button>
                </div>
              </li>
            ))}
            {list.length === 0 && <li className="rounded-2xl border border-dashed border-border p-10 text-center text-sm text-muted-foreground">با این فیلترها پروازی نیست. سقف قیمت را بالاتر ببرید یا ایرلاین دیگری را هم انتخاب کنید.</li>}
          </ul>
        </main>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Bell, Send } from "lucide-react";
import { AvatarGroup } from "@/components/ui/avatar";
import { PhoneInput } from "@/components/ui/phone-input";
import { AuroraBackground } from "@/components/backgrounds/aurora";
import { StarsBackground } from "@/components/backgrounds/stars";
import { GradientText } from "@/components/animations/gradient-text";
import { Sparkles } from "@/components/animations/sparkles";
import { MorphButton } from "@/components/animations/morph-button";
import { fa, faNumber } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

const LAUNCH = new Date(Date.now() + 23 * 864e5 + 5 * 36e5); // ۲۳ روز دیگر

let clock = 0;
function subscribe(onChange: () => void) {
  clock = Date.now();
  const id = window.setInterval(() => { clock = Date.now(); onChange(); }, 1000);
  return () => window.clearInterval(id);
}
/** Server snapshot is 0, so the first client render matches the HTML; the store ticks once mounted. */
function useCountdown(target: Date) {
  const now = React.useSyncExternalStore(subscribe, () => clock, () => 0);
  if (!now) return null;
  const s = Math.max(0, Math.floor((target.getTime() - now) / 1000));
  return { d: Math.floor(s / 86400), h: Math.floor((s % 86400) / 3600), m: Math.floor((s % 3600) / 60), s: s % 60 };
}

/** به‌زودی: شمارش معکوس تا تاریخ شمسی، شفق و ستاره در پس‌زمینه، دریافت شماره‌ی موبایل برای خبررسانی. */
export function ComingSoon() {
  const t = useCountdown(LAUNCH);
  const [ok, setOk] = React.useState(false);
  const cells: [number | null, string][] = [[t?.d ?? null, "روز"], [t?.h ?? null, "ساعت"], [t?.m ?? null, "دقیقه"], [t?.s ?? null, "ثانیه"]];
  return (
    <div className="relative flex min-h-dvh flex-col overflow-x-hidden bg-background text-foreground">
      <StarsBackground count={70} />
      <AuroraBackground className="opacity-70" />
      <header className="relative mx-auto flex h-16 w-full max-w-5xl items-center justify-between px-4">
        <span className="flex items-center gap-2 text-base font-bold"><span className="size-6 rounded-md bg-foreground" />نبض</span>
        <a href="#" className="text-sm text-muted-foreground hover:text-foreground">تماس با ما</a>
      </header>

      <main className="relative mx-auto flex w-full max-w-2xl flex-1 flex-col items-center justify-center px-4 py-12 text-center">
        <Sparkles count={8}><span className="rounded-full border border-border bg-card/60 px-3 py-1 text-xs backdrop-blur">نسخه‌ی اول، {formatJalali(LAUNCH)}</span></Sparkles>
        <h1 className="mt-6 text-4xl font-bold leading-[1.2] sm:text-6xl"><GradientText>داشبورد فروش‌تان</GradientText><br />به‌زودی راه می‌افتد</h1>
        <p className="mt-5 max-w-lg text-lg text-muted-foreground">همه‌ی فروشگاه‌ها و درگاه‌ها در یک صفحه، با اعداد فارسی و تاریخ شمسی. شماره‌تان را بگذارید؛ روز انتشار یک پیامک می‌فرستیم، نه بیشتر.</p>

        <div className="mt-10 grid w-full max-w-md grid-cols-4 gap-2 sm:gap-3" dir="ltr" aria-live="off">
          {cells.map(([n, l]) => (
            <div key={l} className="rounded-2xl border border-border bg-card/70 py-4 backdrop-blur">
              <p className="text-3xl font-bold tabular-nums sm:text-4xl">{n === null ? "--" : fa(String(n).padStart(2, "0"))}</p>
              <p className="mt-1 text-xs text-muted-foreground">{l}</p>
            </div>
          ))}
        </div>

        <form className="mt-10 flex w-full max-w-md flex-col gap-2 sm:flex-row sm:items-start" onSubmit={(e) => e.preventDefault()}>
          <PhoneInput className="flex-1" onChange={(_, valid) => setOk(valid)} />
          <MorphButton className="h-10 sm:w-40" loadingText="در حال ثبت…" doneText="ثبت شد" onAction={() => new Promise((r) => setTimeout(r, 1100))}>
            {ok ? <Send className="size-4" /> : <Bell className="size-4" />}خبرم کن
          </MorphButton>
        </form>
        <div className="mt-6 flex items-center gap-3 text-sm text-muted-foreground">
          <AvatarGroup
            people={[
              { name: "مریم", src: "https://i.pravatar.cc/64?u=maryam" },
              { name: "علی", src: "https://i.pravatar.cc/64?u=ali" },
              { name: "نگار", src: "https://i.pravatar.cc/64?u=negar" },
              { name: "رضا", src: "https://i.pravatar.cc/64?u=reza" },
            ]}
            size="sm"
          />
          <span>{faNumber(1_240)} نفر زودتر از شما در صف‌اند</span>
        </div>
      </main>

      <footer className="relative mx-auto flex w-full max-w-5xl flex-wrap items-center justify-between gap-3 px-4 py-6 text-xs text-muted-foreground">
        <span>© ۱۴۰۵ نبض</span>
        <nav className="flex gap-4"><a href="#">تلگرام</a><a href="#">اینستاگرام</a><a href="#">لینکدین</a></nav>
      </footer>
    </div>
  );
}

"use client";

import * as React from "react";
import { Bath, BedDouble, MapPin, Maximize2, ParkingCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Combobox } from "@/components/ui/combobox";
import { Field } from "@/components/ui/input";
import { SearchInput } from "@/components/ui/search-input";
import { SegmentedControl } from "@/components/ui/segmented-control";
import { Slider } from "@/components/ui/slider";
import { cn, fa, formatToman } from "@/lib/utils";

type Listing = {
  id: string;
  title: string;
  area: string;
  city: string;
  price: number;
  meters: number;
  rooms: number;
  baths: number;
  parking: boolean;
  kind: "sale" | "rent";
  tag?: string;
};

const cities = ["تهران", "کرج", "اصفهان", "شیراز", "مشهد", "تبریز"];
const listings: Listing[] = [
  { id: "1", title: "آپارتمان نوساز دو خواب", area: "سعادت‌آباد", city: "تهران", price: 18_500_000_000, meters: 105, rooms: 2, baths: 1, parking: true, kind: "sale", tag: "بازدید امروز" },
  { id: "2", title: "پنت‌هاوس با تراس جنوبی", area: "فرمانیه", city: "تهران", price: 42_000_000_000, meters: 210, rooms: 3, baths: 2, parking: true, kind: "sale" },
  { id: "3", title: "واحد اداری طبقه همکف", area: "جردن", city: "تهران", price: 85_000_000, meters: 68, rooms: 1, baths: 1, parking: false, kind: "rent", tag: "فوری" },
  { id: "4", title: "ویلای دوبلکس باغ‌دار", area: "مهرشهر", city: "کرج", price: 28_900_000_000, meters: 320, rooms: 4, baths: 3, parking: true, kind: "sale" },
  { id: "5", title: "استودیو مبله نزدیک مترو", area: "ونک", city: "تهران", price: 45_000_000, meters: 42, rooms: 1, baths: 1, parking: false, kind: "rent" },
  { id: "6", title: "آپارتمان نوساز سه خواب", area: "بلوار کشاورز", city: "شیراز", price: 9_800_000_000, meters: 135, rooms: 3, baths: 2, parking: true, kind: "sale" },
];

/** املاک: جست‌وجو و فیلتر خرید/اجاره، سقف قیمت تومانی، کارت‌های ملک با متراژ و امکانات. */
export function RealEstatePage() {
  const [mode, setMode] = React.useState<"sale" | "rent">("sale");
  const [city, setCity] = React.useState("تهران");
  const [q, setQ] = React.useState("");
  const [maxPrice, setMaxPrice] = React.useState(50_000_000_000);
  const [parkingOnly, setParkingOnly] = React.useState(false);

  const list = listings.filter((l) => {
    if (l.kind !== mode) return false;
    if (l.city !== city) return false;
    if (l.price > maxPrice) return false;
    if (parkingOnly && !l.parking) return false;
    if (q && !`${l.title}${l.area}`.includes(q)) return false;
    return true;
  });

  return (
    <div className="min-h-dvh bg-background text-foreground">
      <header className="border-b border-border bg-card/50">
        <div className="mx-auto flex max-w-6xl flex-wrap items-center gap-3 px-4 py-5">
          <div className="me-auto">
            <p className="text-lg font-bold">خانه یاب</p>
            <p className="text-xs text-muted-foreground">آگهی‌های تأییدشده با بازدید حضوری</p>
          </div>
          <SegmentedControl
            aria-label="نوع آگهی"
            value={mode}
            onChange={(v) => setMode(v as "sale" | "rent")}
            options={[
              { value: "sale", label: "خرید" },
              { value: "rent", label: "اجاره" },
            ]}
          />
          <Button size="sm">ثبت آگهی رایگان</Button>
        </div>
      </header>

      <div className="mx-auto grid max-w-6xl gap-6 px-4 py-6 lg:grid-cols-4">
        <aside className="space-y-4 lg:col-span-1">
          <div className="rounded-2xl border border-border bg-card p-4 space-y-4">
            <Field label="شهر">
              <Combobox options={cities} value={city} onChange={setCity} placeholder="انتخاب شهر" className="w-full" />
            </Field>
            <SearchInput value={q} onChange={setQ} placeholder="محله یا عنوان…" />
            <Slider
              label={mode === "sale" ? "حداکثر قیمت خرید" : "حداکثر اجاره ماهانه"}
              min={mode === "sale" ? 5_000_000_000 : 20_000_000}
              max={mode === "sale" ? 50_000_000_000 : 120_000_000}
              step={mode === "sale" ? 500_000_000 : 5_000_000}
              value={maxPrice}
              onChange={setMaxPrice}
              format={formatToman}
            />
            <Checkbox label="فقط با پارکینگ" checked={parkingOnly} onCheckedChange={setParkingOnly} />
          </div>
        </aside>

        <section className="lg:col-span-3">
          <p className="mb-3 text-sm text-muted-foreground">{fa(list.length)} آگهی در {city}</p>
          <ul className="grid gap-4 sm:grid-cols-2">
            {list.map((l) => (
              <li key={l.id} className="overflow-hidden rounded-2xl border border-border bg-card">
                <div
                  className="aspect-16/10 bg-secondary"
                  style={{ backgroundImage: "radial-gradient(80% 80% at 20% 0%, oklch(from var(--brand) l c h / 18%), transparent 70%)" }}
                />
                <div className="space-y-3 p-4">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <h2 className="font-semibold leading-6">{l.title}</h2>
                      <p className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground">
                        <MapPin className="size-3" />
                        {l.area}، {l.city}
                      </p>
                    </div>
                    {l.tag && <Badge variant="brand">{l.tag}</Badge>}
                  </div>
                  <p className="text-base font-bold tabular-nums">
                    {formatToman(l.price)}
                    {l.kind === "rent" && <span className="ms-1 text-xs font-normal text-muted-foreground">/ ماه</span>}
                  </p>
                  <div className="flex flex-wrap gap-3 text-xs text-muted-foreground">
                    <span className="inline-flex items-center gap-1"><Maximize2 className="size-3.5" />{fa(l.meters)} متر</span>
                    <span className="inline-flex items-center gap-1"><BedDouble className="size-3.5" />{fa(l.rooms)} خواب</span>
                    <span className="inline-flex items-center gap-1"><Bath className="size-3.5" />{fa(l.baths)} سرویس</span>
                    <span className={cn("inline-flex items-center gap-1", !l.parking && "opacity-40")}>
                      <ParkingCircle className="size-3.5" />
                      {l.parking ? "پارکینگ" : "بدون پارکینگ"}
                    </span>
                  </div>
                  <Button variant="outline" className="w-full" size="sm">درخواست بازدید</Button>
                </div>
              </li>
            ))}
          </ul>
          {list.length === 0 && (
            <p className="rounded-2xl border border-dashed border-border p-10 text-center text-sm text-muted-foreground">
              با این فیلترها آگهی‌ای پیدا نشد. سقف قیمت را بالاتر ببرید.
            </p>
          )}
        </section>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { MessageSquarePlus, Paperclip, Search } from "lucide-react";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
