              ))}
            </ul>
          )}
        </main>
      </div>

      {open && (
        <div role="dialog" aria-modal="true" aria-labelledby="ad-title" className="fixed inset-0 z-30 overflow-y-auto bg-background" onKeyDown={(e) => e.key === "Escape" && setOpen(null)}>
          <div className="mx-auto max-w-5xl px-4 py-4">
