export function EventLanding() {
  const [ticket, setTicket] = React.useState("regular");
  const [qty, setQty] = React.useState(1);
  const chosen = tickets.find((t) => t.id === ticket)!;

  return (
    <div className="min-h-dvh bg-background text-foreground">
