import { cn, fa } from "@/lib/utils";

export interface StoreLink {
  /** Store name shown large, e.g. «کافه‌بازار». */
  store: string;
  /** Small line above it, e.g. «دریافت از». */
  caption?: string;
  href: string;
  /** Your own store logo. A download glyph is used when it is missing. */
  icon?: React.ReactNode;
}

export interface HeroAppProps {
  title: React.ReactNode;
  description: string;
  stores: StoreLink[];
  /** Average store rating and the number of installs, both optional. */
  rating?: { value: number; count: string };
  /** Screen content of the phone. Falls back to a token-drawn feed. */
  screen?: React.ReactNode;
}

function ScreenMock() {
  return (
    <div aria-hidden className="flex h-full flex-col gap-3 p-4">
      <div className="flex items-center justify-between">
        <div className="h-3 w-20 rounded bg-foreground/20" />
        <div className="size-7 rounded-full bg-secondary" />
      </div>
      <div className="rounded-2xl bg-brand/15 p-4">
        <div className="h-2.5 w-16 rounded bg-brand/40" />
        <div className="mt-3 h-6 w-28 rounded bg-brand/60" />
      </div>
      {[0, 1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-3 rounded-xl border border-border p-2.5">
          <div className="size-9 rounded-lg bg-secondary" />
          <div className="flex-1 space-y-1.5">
            <div className="h-2.5 w-2/3 rounded bg-foreground/15" />
            <div className="h-2 w-1/3 rounded bg-secondary" />
          </div>
        </div>
      ))}
    </div>
  );
}

/** هیروی اپلیکیشن. Store buttons for Iranian app stores beside a phone frame. */
export function HeroApp({ title, description, stores, rating, screen }: HeroAppProps) {
  return (
    <section className="overflow-hidden px-6 pt-16 sm:pt-24">
      <div className="mx-auto grid max-w-5xl items-end gap-10 md:grid-cols-[1fr_auto]">
        <div className="pb-16 sm:pb-24">
          <h1 className="text-4xl font-bold leading-[1.25] sm:text-5xl sm:leading-[1.2]">{title}</h1>
          <p className="mt-5 max-w-md leading-8 text-muted-foreground sm:text-lg sm:leading-9">{description}</p>
          <ul className="mt-8 flex flex-wrap gap-3">
            {stores.map((s, i) => (
              <li key={s.store}>
                <a
                  href={s.href}
                  className={cn(
                    "flex h-14 min-w-40 items-center gap-3 rounded-xl border px-4 transition-colors",
                    i === 0 ? "border-foreground bg-foreground text-background hover:bg-foreground/90" : "border-border bg-card hover:bg-accent",
                  )}
                >
                  <span className="flex size-7 shrink-0 items-center justify-center [&_svg]:size-5">{s.icon ?? <Download />}</span>
                  <span className="flex flex-col">
                    <span className="text-[11px] leading-4 opacity-70">{s.caption ?? "دریافت از"}</span>
                    <span className="text-sm font-bold leading-5">{s.store}</span>
                  </span>
                </a>
              </li>
            ))}
          </ul>
          {rating && (
            <div className="mt-6 flex items-center gap-2 text-sm text-muted-foreground">
              <Rating value={rating.value} readOnly size="sm" />
              <span className="font-medium text-foreground">{fa(rating.value)}</span>
              <span>از {rating.count} نصب فعال</span>
            </div>
          )}
        </div>
        <div className="mx-auto w-64 shrink-0 md:w-72">
          <div className="relative h-[26rem] overflow-hidden rounded-t-[2.5rem] border-x-8 border-t-8 border-foreground/85 bg-card">
            <span aria-hidden className="absolute inset-x-0 top-2 z-10 mx-auto h-5 w-20 rounded-full bg-foreground/85" />
            <div className="h-full pt-8">{screen ?? <ScreenMock />}</div>
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { Search } from "lucide-react";
import { Button } from "@/components/ui/button";

export interface HeroSearchProps {
  title: React.ReactNode;
  description?: string;
  placeholder?: string;
  /** Frequent searches shown as chips; clicking one fills the field and submits. */
  popular?: string[];
  /** Small facts under the chips, e.g. «۱۲ هزار آگهی فعال». */
  facts?: string[];
  onSearch?: (query: string) => void;
}

/** هیروی جست‌وجو. For marketplaces and directories: one large search field is the call to action. */
export function HeroSearch({ title, description, placeholder = "دنبال چه چیزی می‌گردید؟", popular, facts, onSearch }: HeroSearchProps) {
  const [query, setQuery] = React.useState("");
  const id = React.useId();

  function submit(q: string) {
    const trimmed = q.trim();
    if (trimmed) onSearch?.(trimmed);
  }

  return (
    <section className="relative overflow-hidden px-6 py-20 text-center sm:py-28">
      <div aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-72" style={{ background: "radial-gradient(60% 100% at 50% 0%, oklch(from var(--brand) l c h / 14%), transparent 70%)" }} />
      <div className="relative mx-auto max-w-2xl">
        <h1 className="text-4xl font-bold leading-[1.25] sm:text-5xl sm:leading-[1.2]">{title}</h1>
        {description && <p className="mx-auto mt-4 max-w-xl leading-8 text-muted-foreground sm:text-lg">{description}</p>}
        <form
          role="search"
          className="mt-8 flex h-14 items-center gap-2 rounded-full border border-border bg-card ps-5 pe-2 shadow-[0_20px_60px_-30px_oklch(0_0_0/60%)] focus-within:ring-2 focus-within:ring-ring/60"
          onSubmit={(e) => { e.preventDefault(); submit(query); }}
        >
          <Search aria-hidden className="size-5 shrink-0 text-muted-foreground" />
          <label htmlFor={id} className="sr-only">جست‌وجو</label>
          <input
            id={id}
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            className="h-full min-w-0 flex-1 bg-transparent text-base outline-none placeholder:text-muted-foreground/70 [&::-webkit-search-cancel-button]:hidden"
          />
          <Button type="submit" className="rounded-full px-6">جست‌وجو</Button>
        </form>
        {popular && (
          <div className="mt-5 flex flex-wrap items-center justify-center gap-2 text-sm">
            <span className="text-muted-foreground">پرجست‌وجوها</span>
            {popular.map((p) => (
              <button key={p} type="button" onClick={() => { setQuery(p); submit(p); }} className="cursor-pointer rounded-full border border-border px-3 py-1 text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
                {p}
              </button>
            ))}
          </div>
        )}
        {facts && (
          <ul className="mt-10 flex flex-wrap items-center justify-center gap-x-6 gap-y-2 text-sm text-muted-foreground">
            {facts.map((f) => <li key={f} className="flex items-center gap-2"><span aria-hidden className="size-1.5 rounded-full bg-brand" />{f}</li>)}
          </ul>
        )}
      </div>
    </section>
  );
}

import { fa } from "@/lib/utils";
import { toJalali } from "@/lib/jalali";

export interface FooterMinimalProps {
  logo: React.ReactNode;
  links: { label: string; href: string }[];
  /** Social icons or trust seals at the far end; rendered as-is. */
  end?: React.ReactNode;
  copyright?: string;
}

/** پابرگ ساده. One row: logo, a few links and a slot; the Jalali year fills itself in. */
export function FooterMinimal({ logo, links, end, copyright }: FooterMinimalProps) {
  const year = fa(toJalali(new Date()).jy);
  return (
    <footer className="border-t border-border px-6 py-8">
      <div className="mx-auto flex max-w-6xl flex-col items-center gap-5 md:flex-row md:justify-between">
        <div className="flex flex-col items-center gap-1 md:items-start">
          <div className="text-base font-bold">{logo}</div>
          <p className="text-xs text-muted-foreground">{copyright ?? `© ${year} تمام حقوق محفوظ است.`}</p>
        </div>
        <nav aria-label="پابرگ">
          <ul className="flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
            {links.map((l) => <li key={l.label}><a href={l.href} className="text-sm text-muted-foreground transition-colors hover:text-foreground">{l.label}</a></li>)}
          </ul>
        </nav>
        {end && <div className="flex items-center gap-2">{end}</div>}
      </div>
    </footer>
  );
}

"use client";

import * as React from "react";
import { Clock, MapPin, Phone } from "lucide-react";
import { Button } from "@/components/ui/button";
import { fa } from "@/lib/utils";
import { toJalali } from "@/lib/jalali";

export interface FooterMegaProps {
  logo: React.ReactNode;
  description?: string;
  columns: { title: string; links: { label: string; href: string }[] }[];
  contact?: { address?: string; phone?: string; hours?: string };
  /** Newsletter heading; the form is hidden when it is missing. */
  newsletter?: { title: string; description?: string; placeholder?: string };
  onSubscribe?: (email: string) => void;
  /** Trust seals (e-namad, Samandehi). */
  seals?: React.ReactNode;
  /** Social icons. */
  social?: React.ReactNode;
  /** App store buttons. */
  apps?: React.ReactNode;
  /** Legal links on the bottom line. */
  legal?: { label: string; href: string }[];
  copyright?: string;
}

/** پابرگ کامل. For shops: newsletter on top, link columns, contact details, seals, apps and legal line. */
export function FooterMega({ logo, description, columns, contact, newsletter, onSubscribe, seals, social, apps, legal, copyright }: FooterMegaProps) {
  const year = fa(toJalali(new Date()).jy);
  const [email, setEmail] = React.useState("");
  const [sent, setSent] = React.useState(false);
  const id = React.useId();

  return (
    <footer className="border-t border-border bg-card">
      {newsletter && (
        <div className="border-b border-border px-6 py-8">
          <div className="mx-auto flex max-w-6xl flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h2 className="text-base font-bold">{newsletter.title}</h2>
              {newsletter.description && <p className="mt-1 text-sm text-muted-foreground">{newsletter.description}</p>}
            </div>
            <form
              className="flex w-full max-w-md gap-2"
              onSubmit={(e) => { e.preventDefault(); if (!email) return; onSubscribe?.(email); setSent(true); }}
            >
              <label htmlFor={id} className="sr-only">ایمیل</label>
              <input
                id={id}
                type="email"
                dir="ltr"
                required
                value={email}
                onChange={(e) => { setEmail(e.target.value); setSent(false); }}
                placeholder={newsletter.placeholder ?? "you@example.com"}
                className="h-10 min-w-0 flex-1 rounded-field border-line-field border-input bg-field px-3 text-sm outline-none placeholder:text-muted-foreground/60 focus-visible:ring-2 focus-visible:ring-ring/60"
              />
              <Button type="submit">عضویت</Button>
            </form>
            <p role="status" className="sr-only">{sent ? "ایمیل شما ثبت شد." : ""}</p>
          </div>
        </div>
      )}

      <div className="px-6 py-12">
        <div className="mx-auto grid max-w-6xl grid-cols-2 gap-8 md:grid-cols-4 lg:grid-cols-6">
          <div className="col-span-2">
            <div className="text-base font-bold">{logo}</div>
            {description && <p className="mt-3 max-w-xs text-sm leading-7 text-muted-foreground">{description}</p>}
            {contact && (
              <ul className="mt-5 space-y-2.5 text-sm text-muted-foreground">
                {contact.phone && <li className="flex items-center gap-2"><Phone className="size-4 shrink-0" /><a href={`tel:${contact.phone.replace(/[^\d+]/g, "")}`} dir="ltr" className="hover:text-foreground">{fa(contact.phone)}</a></li>}
                {contact.hours && <li className="flex items-center gap-2"><Clock className="size-4 shrink-0" />{contact.hours}</li>}
                {contact.address && <li className="flex items-start gap-2"><MapPin className="mt-1 size-4 shrink-0" /><span className="leading-7">{contact.address}</span></li>}
              </ul>
            )}
            {social && <div className="mt-5">{social}</div>}
          </div>
          {columns.map((c) => (
            <nav key={c.title} aria-label={c.title}>
              <h3 className="text-sm font-semibold">{c.title}</h3>
              <ul className="mt-3 space-y-2">
                {c.links.map((l) => <li key={l.label}><a href={l.href} className="text-sm text-muted-foreground transition-colors hover:text-foreground">{l.label}</a></li>)}
              </ul>
            </nav>
          ))}
          {(seals || apps) && (
            <div className="col-span-2 flex flex-col gap-5 md:col-span-4 lg:col-span-1">
              {seals && <div><h3 className="mb-3 text-sm font-semibold">مجوزها</h3>{seals}</div>}
              {apps && <div><h3 className="mb-3 text-sm font-semibold">اپلیکیشن</h3><div className="flex flex-col gap-2">{apps}</div></div>}
            </div>
          )}
        </div>
      </div>

      <div className="border-t border-border px-6 py-5">
        <div className="mx-auto flex max-w-6xl flex-col gap-3 text-xs text-muted-foreground sm:flex-row sm:items-center sm:justify-between">
          <p>{copyright ?? `© ${year} تمام حقوق این سایت محفوظ است.`}</p>
          {legal && (
            <ul className="flex flex-wrap gap-x-5 gap-y-1">
              {legal.map((l) => <li key={l.label}><a href={l.href} className="hover:text-foreground">{l.label}</a></li>)}
            </ul>
          )}
        </div>
      </div>
    </footer>
  );
}

