"use client";

import * as React from "react";
import { Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { faNumber } from "@/lib/utils";

export interface UsageTier {
  /** The tier applies up to and including this many units. */
  upTo: number;
  /** Price of one unit in this tier, in toman. */
  unitPrice: number;
}

export interface PricingUsageProps {
  title?: string;
  description?: string;
  /** What is being counted, e.g. «پیامک» or «سفارش». */
  unit: string;
  min?: number;
  max: number;
  step?: number;
  defaultValue?: number;
  /** Ascending by `upTo`. The whole volume is billed at the tier it lands in. */
  tiers: UsageTier[];
  /** Fixed monthly fee added to the usage cost. */
  base?: number;
  features?: string[];
  cta?: string;
  onSelect?: (volume: number, total: number) => void;
}

/** Tier a volume falls into: the first one whose ceiling covers it. */
export function tierFor(tiers: UsageTier[], volume: number) {
  return tiers.find((t) => volume <= t.upTo) ?? tiers[tiers.length - 1];
}

/** قیمت مصرفی. A slider sets the monthly volume; the unit price drops by tier and the total updates live. */
export function PricingUsage({ title = "به اندازه‌ی مصرف‌تون پرداخت کنید", description, unit, min = 0, max, step = 1, defaultValue, tiers, base = 0, features, cta = "شروع", onSelect }: PricingUsageProps) {
  const [volume, setVolume] = React.useState(defaultValue ?? Math.round(max / 4 / step) * step);
  const tier = tierFor(tiers, volume);
  const total = base + volume * tier.unitPrice;

  return (
    <section className="px-6 py-16">
      <div className="mx-auto max-w-3xl">
        <div className="text-center">
          <h2 className="text-3xl font-bold">{title}</h2>
          {description && <p className="mx-auto mt-3 max-w-xl text-sm leading-7 text-muted-foreground">{description}</p>}
        </div>
        <div className="mt-10 rounded-3xl border border-border bg-card p-6 sm:p-8">
          <Slider
            value={volume}
            onChange={setVolume}
            min={min}
            max={max}
            step={step}
            label={`تعداد ${unit} در ماه`}
            format={(v) => `${faNumber(v)} ${unit}`}
          />
          <ul className="mt-6 grid grid-cols-2 gap-2 sm:grid-cols-4">
            {tiers.map((t) => {
              const active = t === tier;
              return (
                <li key={t.upTo} aria-current={active ? "true" : undefined} className={active ? "rounded-xl border border-foreground/40 bg-secondary p-3" : "rounded-xl border border-border p-3 text-muted-foreground"}>
                  <p className="text-xs">تا {faNumber(t.upTo)}</p>
                  <p className="mt-1 text-sm font-semibold tabular-nums">{faNumber(t.unitPrice)} <span className="text-xs font-normal">تومان</span></p>
                </li>
              );
            })}
          </ul>
          <div className="mt-8 flex flex-col gap-5 border-t border-border pt-6 sm:flex-row sm:items-end sm:justify-between">
            <div aria-live="polite">
              <p className="text-sm text-muted-foreground">هزینه‌ی ماهانه</p>
              <p className="mt-1 flex items-baseline gap-2">
                <span className="text-4xl font-bold tabular-nums">{faNumber(total)}</span>
                <span className="text-sm text-muted-foreground">تومان</span>
              </p>
              <p className="mt-1 text-xs text-muted-foreground">
                {base > 0 && `${faNumber(base)} تومان اشتراک پایه به‌اضافه‌ی `}
                {faNumber(volume)} {unit} با نرخ {faNumber(tier.unitPrice)} تومان
              </p>
            </div>
            <Button size="lg" onClick={() => onSelect?.(volume, total)}>{cta}</Button>
          </div>
        </div>
        {features && (
          <ul className="mt-6 flex flex-wrap justify-center gap-x-6 gap-y-2 text-sm text-muted-foreground">
            {features.map((f) => <li key={f} className="flex items-center gap-2"><Check className="size-4 text-brand" />{f}</li>)}
          </ul>
        )}
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { cn, faNumber, faPercent } from "@/lib/utils";

export interface PricingRow {
  id: string;
  /** e.g. «یک‌ماهه», «سه‌ماهه», «سالانه». */
  name: string;
  /** Number of months this plan covers; used for the per-month price and the saving. */
  months: number;
  /** Total price of the period in toman. */
  price: number;
  /** Short tag such as «محبوب». */
  tag?: string;
  description?: string;
}

export interface PricingRowsProps {
  title?: string;
  description?: string;
  rows: PricingRow[];
  defaultValue?: string;
  cta?: string;
  onSelect?: (row: PricingRow) => void;
}

/** قیمت ردیفی. Subscription periods as selectable rows; the saving is computed against the shortest period. */
export function PricingRows({ title = "اشتراک‌تون را انتخاب کنید", description, rows, defaultValue, cta = "ادامه و پرداخت", onSelect }: PricingRowsProps) {
  const [selected, setSelected] = React.useState(defaultValue ?? rows[0]?.id);
  const name = React.useId();
  const reference = rows.reduce((a, b) => (b.months < a.months ? b : a), rows[0]);
  const perMonthRef = reference.price / reference.months;
  const current = rows.find((r) => r.id === selected) ?? rows[0];

  return (
    <section className="px-6 py-16">
      <div className="mx-auto max-w-xl">
        <div className="text-center">
          <h2 className="text-3xl font-bold">{title}</h2>
          {description && <p className="mt-3 text-sm leading-7 text-muted-foreground">{description}</p>}
        </div>
        <fieldset className="mt-8 space-y-3">
          <legend className="sr-only">دوره‌ی اشتراک</legend>
          {rows.map((r) => {
            const perMonth = r.price / r.months;
            const saving = Math.round((1 - perMonth / perMonthRef) * 100);
            const active = r.id === selected;
            return (
              <label key={r.id} className={cn("flex cursor-pointer items-center gap-4 rounded-2xl border bg-card p-4 transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring", active ? "border-foreground/50 shadow-[0_0_0_1px_var(--foreground)_inset]" : "border-border hover:bg-accent")}>
                <input type="radio" name={name} value={r.id} checked={active} onChange={() => setSelected(r.id)} className="sr-only" />
                <span aria-hidden className={cn("flex size-5 shrink-0 items-center justify-center rounded-full border", active ? "border-foreground" : "border-input")}>
                  {active && <span className="size-2.5 rounded-full bg-foreground" />}
                </span>
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="flex flex-wrap items-center gap-2 text-sm font-semibold">
                    {r.name}
                    {r.tag && <span className="rounded-full bg-brand px-2 py-0.5 text-[11px] font-medium text-brand-foreground">{r.tag}</span>}
                    {saving > 0 && <span className="rounded-full bg-success/15 px-2 py-0.5 text-[11px] font-medium text-success">{faPercent(saving)} صرفه‌جویی</span>}
                  </span>
                  {r.description && <span className="mt-1 text-xs text-muted-foreground">{r.description}</span>}
                </span>
                <span className="flex flex-col items-end">
                  <span className="text-base font-bold tabular-nums">{faNumber(r.price)} <span className="text-xs font-normal text-muted-foreground">تومان</span></span>
                  {r.months > 1 && <span className="text-xs text-muted-foreground tabular-nums">ماهی {faNumber(Math.round(perMonth))}</span>}
                </span>
              </label>
            );
          })}
        </fieldset>
        <Button size="lg" className="mt-6 w-full" onClick={() => current && onSelect?.(current)}>{cta}</Button>
      </div>
    </section>
  );
}

