"use client";

import * as React from "react";
import { ChevronDown, Menu, type LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

export interface MegaLink { label: string; href: string; description?: string; icon?: LucideIcon }

export interface MegaItem {
  label: string;
  /** A plain link when there are no groups. */
  href?: string;
  /** Columns of the panel. */
  groups?: { title: string; links: MegaLink[] }[];
  /** A highlighted card at the end of the panel. */
  feature?: { title: string; description: string; href: string; cta?: string };
}

export interface NavbarMegaProps {
  logo: React.ReactNode;
  homeHref?: string;
  items: MegaItem[];
  primary?: { label: string; href?: string };
  secondary?: { label: string; href?: string };
  sticky?: boolean;
  className?: string;
}

/** نوار با مگامنو. Top-level buttons open a full-width panel of grouped links; Escape and outside clicks close it. */
export function NavbarMega({ logo, homeHref = "/", items, primary = { label: "شروع رایگان" }, secondary = { label: "ورود" }, sticky = true, className }: NavbarMegaProps) {
  const [openIndex, setOpenIndex] = React.useState<number | null>(null);
  const [mobile, setMobile] = React.useState(false);
  const root = React.useRef<HTMLElement>(null);
  const base = React.useId();

  React.useEffect(() => {
    if (openIndex === null) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      document.getElementById(`${base}-btn-${openIndex}`)?.focus();
      setOpenIndex(null);
    };
    const onDown = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpenIndex(null); };
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);
    return () => { window.removeEventListener("keydown", onKey); window.removeEventListener("pointerdown", onDown); };
  }, [openIndex, base]);

  const open = openIndex === null ? null : items[openIndex];

  return (
    <>
      <header ref={root} className={cn("relative z-40 border-b border-border bg-background", sticky && "sticky top-0", className)}>
        <nav aria-label="اصلی" className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-6 px-6">
          <a href={homeHref} className="flex items-center gap-2 text-base font-bold">{logo}</a>
          <ul className="hidden items-center gap-1 md:flex">
            {items.map((item, i) => (
              <li key={item.label}>
                {item.groups ? (
                  <button
                    id={`${base}-btn-${i}`}
                    type="button"
                    aria-expanded={openIndex === i}
                    aria-controls={`${base}-panel`}
                    onClick={() => setOpenIndex(openIndex === i ? null : i)}
                    className={cn("flex cursor-pointer items-center gap-1 rounded-md px-3 py-2 text-sm transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", openIndex === i ? "bg-accent text-foreground" : "text-muted-foreground")}
                  >
                    {item.label}
                    <ChevronDown className={cn("size-3.5 transition-transform", openIndex === i && "rotate-180")} />
                  </button>
                ) : (
                  <a href={item.href} className="rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">{item.label}</a>
                )}
              </li>
            ))}
          </ul>
          <div className="hidden items-center gap-2 md:flex">
            <Button variant="ghost" size="sm">{secondary.label}</Button>
            <Button size="sm">{primary.label}</Button>
          </div>
          <Button variant="ghost" size="icon" className="md:hidden" aria-label="باز کردن منو" onClick={() => setMobile(true)}><Menu /></Button>
        </nav>

        {open?.groups && (
          <div id={`${base}-panel`} className="absolute inset-x-0 top-full hidden border-b border-border bg-background shadow-[0_30px_60px_-30px_oklch(0_0_0/50%)] md:block">
            <div className="mx-auto flex max-w-6xl gap-8 px-6 py-8">
              <div className="grid flex-1 gap-8" style={{ gridTemplateColumns: `repeat(${open.groups.length}, minmax(0, 1fr))` }}>
                {open.groups.map((g) => (
                  <div key={g.title}>
                    <h3 className="px-3 text-xs font-semibold text-muted-foreground">{g.title}</h3>
                    <ul className="mt-2 space-y-0.5">
                      {g.links.map((l) => (
                        <li key={l.label}>
                          <a href={l.href} onClick={() => setOpenIndex(null)} className="flex items-start gap-3 rounded-xl p-3 transition-colors hover:bg-accent">
                            {l.icon && <span className="flex size-9 shrink-0 items-center justify-center rounded-lg border border-border bg-card"><l.icon className="size-4" /></span>}
                            <span className="flex flex-col">
                              <span className="text-sm font-medium">{l.label}</span>
                              {l.description && <span className="mt-0.5 text-xs leading-6 text-muted-foreground">{l.description}</span>}
                            </span>
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>
              {open.feature && (
                <a href={open.feature.href} onClick={() => setOpenIndex(null)} className="flex w-64 shrink-0 flex-col justify-end rounded-2xl border border-border bg-card p-5 transition-colors hover:bg-accent" style={{ backgroundImage: "radial-gradient(120% 80% at 100% 0%, oklch(from var(--brand) l c h / 18%), transparent 60%)" }}>
                  <span className="text-sm font-semibold">{open.feature.title}</span>
                  <span className="mt-1 text-xs leading-6 text-muted-foreground">{open.feature.description}</span>
                  <span className="mt-3 text-xs font-medium text-brand">{open.feature.cta ?? "بیشتر بخوانید"} ←</span>
                </a>
              )}
            </div>
          </div>
        )}
      </header>

      <Sheet open={mobile} onOpenChange={setMobile} title={logo}>
        <div className="flex flex-col gap-4 overflow-y-auto p-2">
          {items.map((item) =>
            item.groups ? (
              <details key={item.label} className="group">
                <summary className="flex cursor-pointer list-none items-center justify-between rounded-md px-3 py-2.5 text-sm font-medium hover:bg-accent [&::-webkit-details-marker]:hidden">
                  {item.label}
                  <ChevronDown className="size-4 transition-transform group-open:rotate-180" />
                </summary>
                <ul className="mt-1 border-s border-border ps-2 ms-3">
                  {item.groups.flatMap((g) => g.links).map((l) => (
                    <li key={l.label}><a href={l.href} onClick={() => setMobile(false)} className="block rounded-md px-3 py-2 text-sm text-muted-foreground hover:bg-accent hover:text-foreground">{l.label}</a></li>
                  ))}
                </ul>
              </details>
            ) : (
              <a key={item.label} href={item.href} onClick={() => setMobile(false)} className="rounded-md px-3 py-2.5 text-sm font-medium hover:bg-accent">{item.label}</a>
            ),
          )}
        </div>
        <div className="mt-auto flex flex-col gap-2 border-t border-border p-4">
          <Button>{primary.label}</Button>
          <Button variant="outline">{secondary.label}</Button>
        </div>
      </Sheet>
    </>
  );
}

"use client";

import * as React from "react";
import { ArrowRight, ShieldCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PhoneInput } from "@/components/ui/phone-input";
import { OtpField } from "@/components/ui/otp-field";
import { fa } from "@/lib/utils";

export interface LoginSplitProps {
  logo: React.ReactNode;
  title?: string;
  /** Called with the ten-digit national number when «دریافت کد» is pressed. Reject to show the error. */
  onRequestCode?: (phone: string) => Promise<void> | void;
  /** Called with the phone and the typed code. Reject to show «کد درست نیست». */
  onVerify?: (phone: string, code: string) => Promise<void> | void;
  /** Seconds before «ارسال دوباره» becomes active. */
  resendAfter?: number;
  codeLength?: number;
  /** The side panel: a quote, a list of benefits or a picture. */
  aside?: React.ReactNode;
  termsHref?: string;
}

/** ورود دوستونه. Mobile number then SMS code on one side, a brand panel on the other; the panel hides on mobile. */
export function LoginSplit({ logo, title = "ورود یا ثبت‌نام", onRequestCode, onVerify, resendAfter = 120, codeLength = 5, aside, termsHref = "#" }: LoginSplitProps) {
  const [phone, setPhone] = React.useState("");
  const [valid, setValid] = React.useState(false);
  const [step, setStep] = React.useState<"phone" | "code">("phone");
  const [left, setLeft] = React.useState(resendAfter);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState("");
  const [attempt, setAttempt] = React.useState(0);

  React.useEffect(() => {
    if (step !== "code" || left <= 0) return;
    const id = window.setTimeout(() => setLeft((s) => s - 1), 1000);
    return () => window.clearTimeout(id);
  }, [step, left]);

  async function requestCode() {
    if (!valid || busy) return;
    setBusy(true);
    setError("");
    try {
      await onRequestCode?.(phone);
      setStep("code");
      setLeft(resendAfter);
      setAttempt((a) => a + 1);
    } catch {
      setError("ارسال کد انجام نشد. چند لحظه‌ی دیگر دوباره امتحان کنید.");
    } finally {
      setBusy(false);
    }
  }

  async function verify(code: string) {
    setBusy(true);
    setError("");
    try {
      await onVerify?.(phone, code);
    } catch {
      setError("کد واردشده درست نیست.");
      setAttempt((a) => a + 1);
    } finally {
      setBusy(false);
    }
  }

  const clock = `${fa(Math.floor(left / 60))}:${fa(String(left % 60).padStart(2, "0"))}`;

  return (
    <section className="grid min-h-[36rem] lg:grid-cols-2">
      <div className="flex flex-col px-6 py-10 sm:px-12">
        <div className="text-base font-bold">{logo}</div>
        <div className="mx-auto flex w-full max-w-sm flex-1 flex-col justify-center py-10">
          {step === "phone" ? (
            <form onSubmit={(e) => { e.preventDefault(); requestCode(); }}>
              <h1 className="text-2xl font-bold">{title}</h1>
              <p className="mt-2 text-sm leading-7 text-muted-foreground">شماره‌ی موبایل‌تان را وارد کنید. کد تأیید را پیامک می‌کنیم.</p>
              <label htmlFor="login-split-phone" className="mt-8 block text-sm font-medium">شماره‌ی موبایل</label>
              <PhoneInput id="login-split-phone" className="mt-1.5" value={phone} onChange={(d, v) => { setPhone(d); setValid(v); }} autoFocus />
              <Button type="submit" size="lg" className="mt-5 w-full" disabled={!valid || busy}>{busy ? "در حال ارسال…" : "دریافت کد تأیید"}</Button>
              <p className="mt-4 text-center text-xs leading-6 text-muted-foreground">ورود شما به معنای پذیرش <a href={termsHref} className="underline underline-offset-4 hover:text-foreground">قوانین و حریم خصوصی</a> است.</p>
            </form>
          ) : (
            <div>
              <button type="button" onClick={() => { setStep("phone"); setError(""); }} className="flex cursor-pointer items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground"><ArrowRight className="size-4" />تغییر شماره</button>
              <h1 className="mt-6 text-2xl font-bold">کد تأیید را وارد کنید</h1>
              <p className="mt-2 text-sm leading-7 text-muted-foreground">کد {fa(codeLength)} رقمی به شماره‌ی <bdi dir="ltr" className="font-medium text-foreground">{fa(`0${phone}`)}</bdi> پیامک شد.</p>
              <div className="mt-8 flex justify-center">
                <OtpField key={attempt} length={codeLength} onComplete={verify} disabled={busy} aria-label="کد تأیید" />
              </div>
              <div className="mt-6 text-center text-sm text-muted-foreground">
                {left > 0 ? (
                  <span>ارسال دوباره‌ی کد تا <span className="font-medium tabular-nums text-foreground">{clock}</span> دیگر</span>
                ) : (
                  <button type="button" onClick={requestCode} disabled={busy} className="cursor-pointer font-medium text-foreground underline underline-offset-4">ارسال دوباره‌ی کد</button>
                )}
              </div>
            </div>
          )}
          <p role="alert" className="mt-4 min-h-5 text-center text-sm text-destructive">{error}</p>
        </div>
        <p className="flex items-center justify-center gap-1.5 text-xs text-muted-foreground"><ShieldCheck className="size-3.5" />شماره‌ی شما فقط برای ورود استفاده میشه.</p>
      </div>
      <div className="relative hidden overflow-hidden border-s border-border bg-card lg:flex lg:items-center lg:justify-center lg:p-12">
        <div aria-hidden className="pointer-events-none absolute inset-0" style={{ backgroundImage: "radial-gradient(70% 60% at 30% 20%, oklch(from var(--brand) l c h / 22%), transparent 70%), radial-gradient(60% 50% at 80% 90%, oklch(from var(--foreground) l c h / 8%), transparent 70%)" }} />
        <div className="relative max-w-md">{aside}</div>
      </div>
    </section>
  );
}

import { BadgeCheck, ShieldCheck } from "lucide-react";
import { cn } from "@/lib/utils";

export interface TrustSeal {
  /** e.g. «نماد اعتماد الکترونیکی». */
  name: string;
  /** The issuer's verification page for your domain. */
  href?: string;
  /**
   * The seal image the issuer gives you (an <img> with their referrerpolicy and id).
   * Without it a neutral placeholder is drawn, which is fine in design but not in production.
   */
  image?: React.ReactNode;
  /** Short line under the name, e.g. «مجوز کسب‌وکار اینترنتی». */
  caption?: string;
}

export interface TrustBadgesProps {
  title?: string;
  description?: string;
  seals: TrustSeal[];
  /** "row" is a compact strip for footers and checkout; "cards" is a full section. */
  variant?: "row" | "cards";
  className?: string;
}

function Seal({ seal, size }: { seal: TrustSeal; size: "sm" | "lg" }) {
  const box = size === "sm" ? "size-16" : "size-20";
  return seal.image ? (
    <span className={cn("flex items-center justify-center overflow-hidden rounded-xl bg-white p-1.5 [&_img]:size-full [&_img]:object-contain", box)}>{seal.image}</span>
  ) : (
    <span className={cn("flex flex-col items-center justify-center gap-1 rounded-xl border border-dashed border-border text-muted-foreground", box)}>
      <ShieldCheck className="size-5" />
      <span className="text-[10px] leading-none">نشان</span>
    </span>
  );
}

/** نشان‌های اعتماد. Slots for e-namad, Samandehi and guild seals; the official images go in as-is. */
export function TrustBadges({ title, description, seals, variant = "row", className }: TrustBadgesProps) {
  if (variant === "row") {
    return (
      <ul className={cn("flex flex-wrap items-center gap-3", className)}>
        {seals.map((s) => (
          <li key={s.name}>
            <a href={s.href ?? "#"} target={s.href ? "_blank" : undefined} rel="noopener noreferrer" aria-label={s.name} title={s.name} className="block transition-opacity hover:opacity-80">
              <Seal seal={s} size="sm" />
            </a>
          </li>
        ))}
      </ul>
    );
  }
  return (
    <section className={cn("px-6 py-16", className)}>
      <div className="mx-auto max-w-4xl">
        {(title || description) && (
          <div className="mb-8 text-center">
            {title && <h2 className="text-2xl font-bold">{title}</h2>}
            {description && <p className="mx-auto mt-3 max-w-xl text-sm leading-7 text-muted-foreground">{description}</p>}
          </div>
        )}
        <ul className="grid grid-cols-1 gap-4 sm:grid-cols-3">
          {seals.map((s) => (
            <li key={s.name}>
              <a href={s.href ?? "#"} target={s.href ? "_blank" : undefined} rel="noopener noreferrer" className="flex h-full items-center gap-4 rounded-2xl border border-border bg-card p-4 transition-colors hover:bg-accent">
                <Seal seal={s} size="lg" />
                <span className="flex min-w-0 flex-col">
                  <span className="flex items-center gap-1.5 text-sm font-semibold">{s.name}<BadgeCheck className="size-4 shrink-0 text-success" /></span>
                  {s.caption && <span className="mt-1 text-xs leading-6 text-muted-foreground">{s.caption}</span>}
                </span>
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import { Download, MonitorSmartphone, QrCode } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AppStore {
  /** Store name, e.g. «کافه‌بازار», «مایکت», «سیب‌اپ», «نسخه‌ی وب (PWA)». */
  store: string;
  caption?: string;
  href: string;
  /** Your own copy of the store logo. */
  icon?: React.ReactNode;
  /** Platform hint shown as a small tag. */
  platform?: "android" | "ios" | "web";
}

export interface AppDownloadProps {
  title: string;
  description?: string;
  stores: AppStore[];
  /** A QR image or component for desktop visitors. A placeholder glyph is drawn without it. */
  qr?: React.ReactNode;
  qrCaption?: string;
  className?: string;
}

const PLATFORM = { android: "اندروید", ios: "آیفون", web: "وب" };

/** One store button. Exported so headers and footers can reuse it on its own. */
export function StoreButton({ store, caption = "دریافت از", href, icon, platform, primary }: AppStore & { primary?: boolean }) {
  return (
    <a
      href={href}
      className={cn(
        "flex h-14 items-center gap-3 rounded-xl border px-4 transition-colors",
        primary ? "border-foreground bg-foreground text-background hover:bg-foreground/90" : "border-border bg-card hover:bg-accent",
      )}
    >
      <span className="flex size-7 shrink-0 items-center justify-center [&_svg]:size-5">{icon ?? (platform === "web" ? <MonitorSmartphone /> : <Download />)}</span>
      <span className="flex min-w-0 flex-1 flex-col">
        <span className="text-[11px] leading-4 opacity-70">{caption}</span>
        <span className="truncate text-sm font-bold leading-5">{store}</span>
      </span>
      {platform && <span className="rounded-full border border-current/20 px-2 py-0.5 text-[10px] opacity-70">{PLATFORM[platform]}</span>}
    </a>
  );
}

/** دریافت اپلیکیشن. Bazaar, Myket and Sibapp buttons with a QR code for people on desktop. */
export function AppDownload({ title, description, stores, qr, qrCaption = "با دوربین گوشی اسکن کنید", className }: AppDownloadProps) {
  return (
    <section className={cn("px-6 py-16", className)}>
      <div className="mx-auto flex max-w-4xl flex-col gap-8 rounded-3xl border border-border bg-card p-8 md:flex-row md:items-center md:p-10">
        <div className="flex-1">
          <h2 className="text-2xl font-bold leading-10">{title}</h2>
          {description && <p className="mt-3 max-w-md text-sm leading-7 text-muted-foreground">{description}</p>}
          <ul className="mt-6 grid grid-cols-1 gap-3 sm:grid-cols-2">
            {stores.map((s, i) => <li key={s.store}><StoreButton {...s} primary={i === 0} /></li>)}
          </ul>
        </div>
        <figure className="hidden shrink-0 flex-col items-center gap-3 md:flex">
          <div className="flex size-36 items-center justify-center rounded-2xl bg-white p-3 text-black [&_img]:size-full [&_svg]:size-full">{qr ?? <QrCode strokeWidth={1} />}</div>
          <figcaption className="text-xs text-muted-foreground">{qrCaption}</figcaption>
        </figure>
      </div>
    </section>
  );
}

import { AtSign, Camera, Globe, Mail, MessageCircle, MessagesSquare, Phone, Send, Tv, Users, type LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

/** Networks Iranian businesses actually list. Brand logos are trademarks, so each one gets a neutral glyph; pass `icon` for your own. */
export type SocialNetwork = "telegram" | "eitaa" | "bale" | "rubika" | "instagram" | "whatsapp" | "aparat" | "linkedin" | "email" | "phone" | "website";

const NETWORKS: Record<SocialNetwork, { label: string; icon: LucideIcon }> = {
  telegram: { label: "تلگرام", icon: Send },
  eitaa: { label: "ایتا", icon: MessagesSquare },
  bale: { label: "بله", icon: MessageCircle },
  rubika: { label: "روبیکا", icon: AtSign },
  instagram: { label: "اینستاگرام", icon: Camera },
  whatsapp: { label: "واتس‌اپ", icon: Phone },
  aparat: { label: "آپارات", icon: Tv },
  linkedin: { label: "لینکدین", icon: Users },
  email: { label: "ایمیل", icon: Mail },
  phone: { label: "تلفن", icon: Phone },
  website: { label: "وب‌سایت", icon: Globe },
};

export interface SocialLink {
  network: SocialNetwork;
  href: string;
  /** The handle or number shown in the "list" and "cards" variants, e.g. «@dokan». */
  handle?: string;
  /** Replaces the default name. */
  label?: string;
  icon?: React.ReactNode;
}

export interface SocialLinksProps {
  links: SocialLink[];
  /** "icons" for footers, "list" for contact pages, "cards" for a link-in-bio page. */
  variant?: "icons" | "list" | "cards";
  className?: string;
}

/** شبکه‌های اجتماعی. Telegram, Eitaa, Bale and Rubika beside Instagram; handles stay left-to-right. */
export function SocialLinks({ links, variant = "icons", className }: SocialLinksProps) {
  if (variant === "icons") {
    return (
      <ul className={cn("flex flex-wrap items-center gap-2", className)}>
        {links.map((l) => {
          const n = NETWORKS[l.network];
          return (
            <li key={l.network + l.href}>
              <a href={l.href} aria-label={l.label ?? n.label} title={l.label ?? n.label} className="flex size-10 items-center justify-center rounded-full border border-border text-muted-foreground transition-colors hover:bg-accent hover:text-foreground [&_svg]:size-4">
                {l.icon ?? <n.icon />}
              </a>
            </li>
          );
        })}
      </ul>
    );
  }
  return (
    <ul className={cn(variant === "cards" ? "grid grid-cols-1 gap-3 sm:grid-cols-2" : "flex flex-col divide-y divide-border", className)}>
      {links.map((l) => {
        const n = NETWORKS[l.network];
        return (
          <li key={l.network + l.href}>
            <a href={l.href} className={cn("flex items-center gap-3 transition-colors", variant === "cards" ? "rounded-2xl border border-border bg-card p-4 hover:bg-accent" : "py-3 hover:text-foreground")}>
              <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-secondary [&_svg]:size-4">{l.icon ?? <n.icon />}</span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="text-sm font-medium">{l.label ?? n.label}</span>
                {l.handle && <bdi dir="ltr" className="truncate text-end text-xs text-muted-foreground">{l.handle}</bdi>}
              </span>
            </a>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import * as React from "react";
import { ShoppingBag, Trash2, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { NumberField } from "@/components/ui/number-field";
import { Sheet } from "@/components/ui/sheet";
import { fa, faNumber } from "@/lib/utils";

export interface CartItem {
  id: string;
  name: string;
  /** Unit price in toman. */
  price: number;
  /** Unit price before discount. */
  original?: number;
  quantity: number;
  /** Chosen options, e.g. «مشکی، ۲۵۶ گیگ». */
  variant?: string;
  /** Stock ceiling for the quantity field. */
  max?: number;
  image?: React.ReactNode;
}

export interface CartDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CartItem[];
  onQuantityChange?: (id: string, quantity: number) => void;
  onRemove?: (id: string) => void;
  onCheckout?: () => void;
  /** Orders at or above this total ship free; a progress line shows how much is left. */
  freeShippingFrom?: number;
  /** Which edge it slides from. "end" is the left edge in RTL, where shop carts usually sit. */
  side?: "start" | "end";
}

/** Totals of a cart: what is paid, what it would have cost, and the saving. */
export function cartTotals(items: CartItem[]) {
  const total = items.reduce((s, i) => s + i.price * i.quantity, 0);
  const full = items.reduce((s, i) => s + (i.original ?? i.price) * i.quantity, 0);
  const count = items.reduce((s, i) => s + i.quantity, 0);
  return { total, full, saving: full - total, count };
}

/** سبد کشویی. Line items with a quantity stepper, a free-shipping progress line and a sticky total. */
export function CartDrawer({ open, onOpenChange, items, onQuantityChange, onRemove, onCheckout, freeShippingFrom, side = "end" }: CartDrawerProps) {
  const { total, saving, count } = cartTotals(items);
  const left = freeShippingFrom ? Math.max(0, freeShippingFrom - total) : 0;

  return (
    <Sheet open={open} onOpenChange={onOpenChange} side={side} title={<span className="flex items-center gap-2">سبد خرید{count > 0 && <span className="rounded-full bg-secondary px-2 py-0.5 text-xs font-normal text-muted-foreground">{fa(count)} کالا</span>}</span>}>
      {items.length === 0 ? (
        <div className="flex flex-1 flex-col items-center justify-center gap-3 p-8 text-center">
          <span className="flex size-14 items-center justify-center rounded-full bg-secondary"><ShoppingBag className="size-6 text-muted-foreground" /></span>
          <p className="font-medium">سبد شما خالی است</p>
          <p className="text-sm leading-7 text-muted-foreground">هر کالایی که اضافه کنید همین‌جا می‌بینید.</p>
          <Button variant="outline" className="mt-2" onClick={() => onOpenChange(false)}>ادامه‌ی خرید</Button>
        </div>
      ) : (
        <>
          {freeShippingFrom !== undefined && (
            <div className="border-b border-border px-4 py-3">
              <p className="flex items-center gap-2 text-xs text-muted-foreground" aria-live="polite">
                <Truck className="size-4 shrink-0" />
                {left > 0 ? <span><span className="font-medium text-foreground">{faNumber(left)} تومان</span> دیگر تا ارسال رایگان</span> : <span className="font-medium text-success">ارسال این سفارش رایگان است</span>}
              </p>
              <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-secondary">
                <div className="h-full rounded-full bg-brand transition-[width] duration-500" style={{ width: `${Math.min(100, (total / freeShippingFrom) * 100)}%` }} />
              </div>
            </div>
          )}
          <ul className="flex-1 divide-y divide-border overflow-y-auto">
            {items.map((item) => (
              <li key={item.id} className="flex gap-3 p-4">
                <div className="size-20 shrink-0 overflow-hidden rounded-xl bg-secondary">
                  {item.image ?? <div aria-hidden className="size-full" style={{ background: "radial-gradient(70% 70% at 50% 40%, oklch(from var(--foreground) l c h / 12%), transparent 70%)" }} />}
                </div>
                <div className="flex min-w-0 flex-1 flex-col">
                  <p className="line-clamp-2 text-sm font-medium leading-6">{item.name}</p>
                  {item.variant && <p className="mt-0.5 text-xs text-muted-foreground">{item.variant}</p>}
                  {/* Price gets its own line: beside a 136px stepper a seven-digit total would clip in a narrow drawer. */}
                  <p className="mt-auto flex flex-wrap items-baseline gap-x-2 pt-2">
                    <span className="whitespace-nowrap text-sm font-bold tabular-nums">{faNumber(item.price * item.quantity)} <span className="text-xs font-normal text-muted-foreground">تومان</span></span>
                    {item.original && item.original > item.price && <span className="text-xs text-muted-foreground line-through tabular-nums"><span className="sr-only">قیمت قبلی </span>{faNumber(item.original * item.quantity)}</span>}
                  </p>
                  <div className="mt-2 flex items-center gap-1">
                    <NumberField value={item.quantity} min={1} max={item.max ?? 99} onChange={(q) => onQuantityChange?.(item.id, q)} aria-label={`تعداد ${item.name}`} className="h-8" />
                    <Button variant="ghost" size="icon" className="ms-auto size-8 text-muted-foreground hover:text-destructive" aria-label={`حذف ${item.name}`} onClick={() => onRemove?.(item.id)}><Trash2 /></Button>
                  </div>
                </div>
              </li>
            ))}
          </ul>
          <div className="border-t border-border p-4">
            {saving > 0 && <p className="flex items-center justify-between text-sm text-success"><span>سود شما از این خرید</span><span className="tabular-nums">{faNumber(saving)} تومان</span></p>}
            <p className="mt-2 flex items-center justify-between">
              <span className="text-sm text-muted-foreground">جمع سبد</span>
              <span className="text-lg font-bold tabular-nums">{faNumber(total)} <span className="text-xs font-normal text-muted-foreground">تومان</span></span>
            </p>
            <Button size="lg" className="mt-4 w-full" onClick={onCheckout}>ادامه‌ی فرایند خرید</Button>
            <p className="mt-2 text-center text-xs text-muted-foreground">هزینه‌ی ارسال در مرحله‌ی بعد حساب میشه.</p>
          </div>
        </>
      )}
    </Sheet>
  );
}

"use client";

import * as React from "react";
import { Check, RotateCcw, ShieldCheck, ShoppingCart, Store, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { NumberField } from "@/components/ui/number-field";
import { Price } from "@/components/ui/price";
import { Rating } from "@/components/ui/rating";
import { cn, fa } from "@/lib/utils";

export interface ProductOption {
  /** e.g. «رنگ» or «حافظه». */
  name: string;
  values: { id: string; label: string; /** CSS color for a swatch. */ color?: string; disabled?: boolean }[];
}

export interface ProductDetailProps {
  title: string;
  /** Latin model name under the title, shown left-to-right. */
  subtitle?: string;
  /** Gallery slides: images or any node. Placeholders are drawn when empty. */
  images?: React.ReactNode[];
  price: number;
  original?: number;
  rating?: { value: number; count: number };
  options?: ProductOption[];
  /** Key specs as label/value pairs. */
  specs?: { label: string; value: string }[];
  seller?: string;
  warranty?: string;
  shipping?: string;
  returns?: string;
  /** Units left; a low number shows a warning and caps the quantity. */
  stock?: number;
  onAddToCart?: (selection: Record<string, string>, quantity: number) => void;
}

/** جزئیات محصول. Gallery, options, key specs and a seller box with warranty, shipping and the add-to-cart row. */
export function ProductDetail({ title, subtitle, images = [], price, original, rating, options = [], specs, seller, warranty, shipping, returns, stock, onAddToCart }: ProductDetailProps) {
  const slides = images.length ? images : [null, null, null, null];
  const [active, setActive] = React.useState(0);
  const [quantity, setQuantity] = React.useState(1);
  const [selection, setSelection] = React.useState<Record<string, string>>(() =>
    Object.fromEntries(options.map((o) => [o.name, o.values.find((v) => !v.disabled)?.id ?? ""])),
  );
  const soldOut = stock === 0;

  return (
    <section className="px-6 py-12">
      <div className="mx-auto grid max-w-6xl gap-8 lg:grid-cols-12">
        <div className="lg:col-span-4">
          <div className="aspect-square overflow-hidden rounded-2xl border border-border bg-secondary">
            {slides[active] ?? <div aria-hidden className="size-full" style={{ background: "radial-gradient(60% 60% at 50% 45%, oklch(from var(--foreground) l c h / 14%), transparent 70%)" }} />}
          </div>
          <ul className="mt-3 flex gap-2">
            {slides.map((s, i) => (
              <li key={i}>
                <button type="button" aria-label={`عکس ${fa(i + 1)}`} aria-current={i === active ? "true" : undefined} onClick={() => setActive(i)} className={cn("size-16 cursor-pointer overflow-hidden rounded-xl border bg-secondary transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", i === active ? "border-foreground" : "border-border opacity-70 hover:opacity-100")}>
                  {s}
                </button>
              </li>
            ))}
          </ul>
        </div>

        <div className="lg:col-span-5">
          <h1 className="text-xl font-bold leading-9">{title}</h1>
          {subtitle && <p dir="ltr" className="mt-1 text-end text-xs text-muted-foreground">{subtitle}</p>}
          {rating && (
            <div className="mt-3 flex items-center gap-2 text-sm text-muted-foreground">
              <Rating value={rating.value} readOnly size="sm" />
              <span className="font-medium text-foreground">{fa(rating.value)}</span>
              <a href="#reviews" className="hover:text-foreground">({fa(rating.count)} دیدگاه)</a>
            </div>
          )}

          {options.map((o) => (
            <fieldset key={o.name} className="mt-6">
              <legend className="text-sm font-medium">{o.name}: <span className="font-normal text-muted-foreground">{o.values.find((v) => v.id === selection[o.name])?.label}</span></legend>
              <div className="mt-2.5 flex flex-wrap gap-2">
                {o.values.map((v) => {
                  const on = selection[o.name] === v.id;
                  return (
                    <label key={v.id} className={cn("flex h-9 items-center gap-2 rounded-full border px-3 text-sm transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring", v.disabled ? "cursor-not-allowed border-dashed border-border text-muted-foreground/50 line-through" : "cursor-pointer", on ? "border-foreground bg-secondary" : !v.disabled && "border-border hover:bg-accent")}>
                      <input type="radio" name={`option-${o.name}`} value={v.id} checked={on} disabled={v.disabled} onChange={() => setSelection((s) => ({ ...s, [o.name]: v.id }))} className="sr-only" />
                      {v.color && <span aria-hidden className="size-4 rounded-full border border-border" style={{ background: v.color }} />}
                      {v.label}
                      {on && <Check className="size-3.5" />}
                    </label>
                  );
                })}
              </div>
            </fieldset>
          ))}

          {specs && (
            <div className="mt-8">
              <h2 className="text-sm font-semibold">ویژگی‌های اصلی</h2>
              <dl className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">
                {specs.map((s) => (
                  <div key={s.label} className="rounded-xl bg-secondary/60 p-3">
                    <dt className="text-xs text-muted-foreground">{s.label}</dt>
                    <dd className="mt-1 text-sm font-medium">{s.value}</dd>
                  </div>
                ))}
              </dl>
            </div>
          )}
        </div>

        <aside className="lg:col-span-3">
          <div className="rounded-2xl border border-border bg-card p-5 lg:sticky lg:top-20">
            <ul className="space-y-3 border-b border-border pb-4 text-sm">
              {seller && <li className="flex items-center gap-2.5"><Store className="size-4 shrink-0 text-muted-foreground" /><span>فروشنده: <span className="font-medium">{seller}</span></span></li>}
              {warranty && <li className="flex items-center gap-2.5"><ShieldCheck className="size-4 shrink-0 text-muted-foreground" />{warranty}</li>}
              {shipping && <li className="flex items-center gap-2.5"><Truck className="size-4 shrink-0 text-muted-foreground" />{shipping}</li>}
              {returns && <li className="flex items-center gap-2.5"><RotateCcw className="size-4 shrink-0 text-muted-foreground" />{returns}</li>}
            </ul>
            <div className="flex justify-end pt-4"><Price amount={price} original={original} className="items-end" /></div>
            {stock !== undefined && stock > 0 && stock <= 5 && <p className="mt-2 text-end text-xs font-medium text-destructive">تنها {fa(stock)} عدد در انبار باقی مانده</p>}
            {soldOut ? (
              <Button className="mt-4 w-full" variant="outline" disabled>ناموجود</Button>
            ) : (
              <div className="mt-4 flex items-center gap-2">
                <NumberField value={quantity} onChange={setQuantity} min={1} max={stock ?? 99} aria-label="تعداد" />
                <Button className="flex-1" onClick={() => onAddToCart?.(selection, quantity)}><ShoppingCart />افزودن به سبد</Button>
              </div>
            )}
          </div>
        </aside>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { Check, Copy, MapPin, PackageCheck } from "lucide-react";
import { cn, fa, faNumber } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

export interface TrackingStep {
  title: string;
  /** When this step happened. Leave empty for steps that are still ahead. */
  at?: Date;
  /** Extra line, e.g. «مرکز پردازش تهران». */
  note?: string;
}

export interface OrderTrackingProps {
  /** Order number, shown left-to-right. */
  orderId: string;
  steps: TrackingStep[];
  /** Index of the step the order is in right now. */
  current: number;
  /** Shipping company and its tracking code. */
  carrier?: { name: string; code: string; href?: string };
  /** Expected delivery day. */
  eta?: Date;
  recipient?: { name: string; address: string };
  items?: { name: string; quantity: number }[];
  total?: number;
}

const time = (d: Date) => fa(`${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`);

/** پیگیری سفارش. Steps with Jalali date and time, a copyable postal tracking code and the delivery address. */
export function OrderTracking({ orderId, steps, current, carrier, eta, recipient, items, total }: OrderTrackingProps) {
  const [copied, setCopied] = React.useState(false);
  const done = current >= steps.length - 1;

  async function copy() {
    if (!carrier) return;
    try {
      await navigator.clipboard.writeText(carrier.code);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard blocked; the code is still selectable */
    }
  }

  return (
    <section className="px-6 py-12">
      <div className="mx-auto max-w-4xl overflow-hidden rounded-3xl border border-border bg-card">
        <header className="flex flex-col gap-4 border-b border-border p-6 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-muted-foreground">سفارش <bdi dir="ltr" className="font-mono font-medium text-foreground">{orderId}</bdi></p>
            <h1 className="mt-1 flex items-center gap-2 text-xl font-bold">
              {done && <PackageCheck className="size-5 text-success" />}
              {steps[current]?.title}
            </h1>
          </div>
          {eta && !done && (
            <div className="rounded-2xl bg-secondary px-4 py-2.5 text-sm">
              <span className="text-muted-foreground">تحویل تا </span>
              <span className="font-semibold">{formatJalali(eta, { weekday: true })}</span>
            </div>
          )}
        </header>

        <ol className="flex flex-col gap-0 p-6 md:flex-row">
          {steps.map((s, i) => {
            const state = i < current || (done && i === current) ? "done" : i === current ? "current" : "todo";
            return (
              <li key={s.title} aria-current={state === "current" ? "step" : undefined} className="relative flex flex-1 gap-3 pb-6 last:pb-0 md:flex-col md:items-center md:gap-0 md:pb-0 md:text-center">
                {i < steps.length - 1 && (
                  <span aria-hidden className={cn("absolute start-[15px] top-8 h-[calc(100%-2rem)] w-0.5 md:start-auto md:end-1/2 md:top-[15px] md:h-0.5 md:w-full md:translate-x-0", i < current ? "bg-brand" : "bg-border")} />
                )}
                <span className={cn("relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full border-2 text-xs font-bold", state === "done" && "border-brand bg-brand text-brand-foreground", state === "current" && "border-brand bg-card text-brand", state === "todo" && "border-border bg-card text-muted-foreground")}>
                  {state === "done" ? <Check className="size-4" /> : fa(i + 1)}
                  {state === "current" && <span aria-hidden className="absolute inset-0 rounded-full border-2 border-brand motion-safe:animate-ping" />}
                </span>
                <div className="md:mt-3 md:px-2">
                  <p className={cn("text-sm font-medium", state === "todo" && "text-muted-foreground")}>{s.title}</p>
                  {s.at && <p className="mt-1 text-xs text-muted-foreground">{formatJalali(s.at)}، ساعت {time(s.at)}</p>}
                  {s.note && <p className="mt-1 text-xs text-muted-foreground">{s.note}</p>}
                </div>
              </li>
            );
          })}
        </ol>

        <div className="grid gap-px border-t border-border bg-border sm:grid-cols-2">
          {carrier && (
            <div className="bg-card p-6">
              <h2 className="text-xs font-semibold text-muted-foreground">کد رهگیری {carrier.name}</h2>
              <div className="mt-2 flex items-center gap-2">
                <button type="button" onClick={copy} dir="ltr" className="flex cursor-pointer items-center gap-2 rounded-lg border border-border px-3 py-1.5 font-mono text-sm transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" aria-label={`کپی کد رهگیری ${carrier.code}`}>
                  {carrier.code}
                  {copied ? <Check className="size-3.5 text-success" /> : <Copy className="size-3.5 text-muted-foreground" />}
                </button>
                <span role="status" className="text-xs text-success">{copied ? "کپی شد" : ""}</span>
              </div>
              {carrier.href && <a href={carrier.href} target="_blank" rel="noopener noreferrer" className="mt-3 inline-block text-xs text-muted-foreground underline underline-offset-4 hover:text-foreground">پیگیری در سایت {carrier.name}</a>}
            </div>
          )}
          {recipient && (
            <div className="bg-card p-6">
              <h2 className="text-xs font-semibold text-muted-foreground">تحویل‌گیرنده</h2>
              <p className="mt-2 text-sm font-medium">{recipient.name}</p>
              <p className="mt-1 flex items-start gap-1.5 text-sm leading-7 text-muted-foreground"><MapPin className="mt-1.5 size-3.5 shrink-0" />{recipient.address}</p>
            </div>
          )}
        </div>

        {items && (
          <div className="border-t border-border p-6">
            <h2 className="text-xs font-semibold text-muted-foreground">اقلام سفارش</h2>
            <ul className="mt-3 divide-y divide-border text-sm">
              {items.map((it) => (
                <li key={it.name} className="flex items-center justify-between gap-4 py-2.5">
                  <span>{it.name}</span>
                  <span className="shrink-0 text-muted-foreground">{fa(it.quantity)} عدد</span>
                </li>
              ))}
            </ul>
            {total !== undefined && <p className="mt-3 flex items-center justify-between border-t border-border pt-4 text-sm"><span className="text-muted-foreground">مبلغ پرداخت‌شده</span><span className="font-bold tabular-nums">{faNumber(total)} تومان</span></p>}
          </div>
        )}
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { BadgeCheck, Minus, Plus, Star, ThumbsUp } from "lucide-react";
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Rating } from "@/components/ui/rating";
import { cn, fa, faPercent } from "@/lib/utils";
import { formatJalali } from "@/lib/jalali";

export interface Review {
  id: string;
  author: string;
  rating: number;
  date: Date;
  title?: string;
  body: string;
  /** «خریدار این محصول». */
  verified?: boolean;
  /** نقاط قوت. */
  pros?: string[];
  /** نقاط ضعف. */
  cons?: string[];
  /** How many people found it useful. */
  helpful?: number;
  /** The shop's answer. */
  reply?: string;
}

export interface ReviewsProps {
  title?: string;
  reviews: Review[];
  onWrite?: () => void;
  onHelpful?: (id: string) => void;
}

type Sort = "new" | "helpful" | "high" | "low";
const SORTS: { key: Sort; label: string }[] = [
  { key: "new", label: "جدیدترین" },
  { key: "helpful", label: "مفیدترین" },
  { key: "high", label: "بیشترین امتیاز" },
  { key: "low", label: "کمترین امتیاز" },
];

/** Average and the share of each star, five first. */
export function reviewStats(reviews: Review[]) {
  const n = reviews.length || 1;
  const average = reviews.reduce((s, r) => s + r.rating, 0) / n;
  const shares = [5, 4, 3, 2, 1].map((star) => ({ star, count: reviews.filter((r) => Math.round(r.rating) === star).length }));
  return { average, shares, total: reviews.length };
}

/** دیدگاه‌ها. Average with a star breakdown you can filter by, sortable reviews with pros and cons, and a helpful vote. */
export function Reviews({ title = "دیدگاه خریداران", reviews, onWrite, onHelpful }: ReviewsProps) {
  const [sort, setSort] = React.useState<Sort>("new");
  const [star, setStar] = React.useState<number | null>(null);
  const [voted, setVoted] = React.useState<Set<string>>(new Set());
  const { average, shares, total } = reviewStats(reviews);

  const list = React.useMemo(() => {
    const filtered = star === null ? reviews : reviews.filter((r) => Math.round(r.rating) === star);
    return [...filtered].sort((a, b) =>
      sort === "new" ? b.date.getTime() - a.date.getTime() : sort === "helpful" ? (b.helpful ?? 0) - (a.helpful ?? 0) : sort === "high" ? b.rating - a.rating : a.rating - b.rating,
    );
  }, [reviews, sort, star]);

  function vote(id: string) {
    if (voted.has(id)) return;
    setVoted((v) => new Set(v).add(id));
    onHelpful?.(id);
  }

  return (
    <section id="reviews" className="px-6 py-12">
      <div className="mx-auto grid max-w-5xl gap-10 lg:grid-cols-[18rem_1fr]">
        <aside className="lg:sticky lg:top-20 lg:self-start">
          <h2 className="text-xl font-bold">{title}</h2>
          <div className="mt-5 flex items-end gap-3">
            <span className="text-5xl font-bold tabular-nums">{fa(average.toFixed(1)).replace(".", "٫")}</span>
            <div className="pb-1.5">
              <Rating value={average} readOnly size="sm" />
              <p className="mt-1 text-xs text-muted-foreground">از {fa(total)} دیدگاه</p>
            </div>
          </div>
          <ul className="mt-5 space-y-1.5">
            {shares.map(({ star: s, count }) => {
              const share = total ? (count / total) * 100 : 0;
              const on = star === s;
              return (
                <li key={s}>
                  <button type="button" aria-pressed={on} onClick={() => setStar(on ? null : s)} className={cn("flex w-full cursor-pointer items-center gap-2 rounded-md px-1.5 py-1 text-xs transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", on && "bg-secondary")} aria-label={`${fa(s)} ستاره، ${fa(count)} دیدگاه`}>
                    <span className="flex w-7 items-center gap-0.5 tabular-nums">{fa(s)}<Star className="size-3 fill-current" /></span>
                    <span className="h-1.5 flex-1 overflow-hidden rounded-full bg-secondary"><span className="block h-full rounded-full bg-foreground/70" style={{ width: `${share}%` }} /></span>
                    <span className="w-9 text-end text-muted-foreground tabular-nums">{faPercent(share)}</span>
                  </button>
                </li>
              );
            })}
          </ul>
          <Button variant="outline" className="mt-6 w-full" onClick={onWrite}>ثبت دیدگاه</Button>
        </aside>

        <div>
          <div className="flex flex-wrap items-center gap-1 border-b border-border pb-3 text-sm">
            <span className="pe-2 text-muted-foreground">مرتب‌سازی</span>
            {SORTS.map((s) => (
              <button key={s.key} type="button" aria-pressed={sort === s.key} onClick={() => setSort(s.key)} className={cn("cursor-pointer rounded-full px-3 py-1 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", sort === s.key ? "bg-secondary font-medium text-foreground" : "text-muted-foreground hover:text-foreground")}>
                {s.label}
              </button>
            ))}
          </div>
          {list.length === 0 ? (
            <p className="py-12 text-center text-sm text-muted-foreground">دیدگاهی با این امتیاز ثبت نشده.</p>
          ) : (
            <ul className="divide-y divide-border">
              {list.map((r) => {
                const mine = voted.has(r.id);
                return (
                  <li key={r.id} className="py-6">
                    <article>
                      <header className="flex items-center gap-3">
                        <Avatar name={r.author} size="sm" />
                        <div className="min-w-0 flex-1">
                          <p className="flex flex-wrap items-center gap-2 text-sm font-medium">
                            {r.author}
                            {r.verified && <span className="flex items-center gap-1 text-xs font-normal text-success"><BadgeCheck className="size-3.5" />خریدار</span>}
                          </p>
                          <p className="text-xs text-muted-foreground">{formatJalali(r.date, { year: true })}</p>
                        </div>
                        <Rating value={r.rating} readOnly size="sm" />
                      </header>
                      {r.title && <h3 className="mt-4 text-sm font-semibold">{r.title}</h3>}
                      <p className="mt-2 text-sm leading-7 text-foreground/90">{r.body}</p>
                      {(r.pros || r.cons) && (
                        <ul className="mt-3 space-y-1.5 text-sm">
                          {r.pros?.map((p) => <li key={p} className="flex items-center gap-2"><Plus className="size-3.5 shrink-0 text-success" /><span className="sr-only">نقطه‌ی قوت: </span>{p}</li>)}
                          {r.cons?.map((c) => <li key={c} className="flex items-center gap-2"><Minus className="size-3.5 shrink-0 text-destructive" /><span className="sr-only">نقطه‌ی ضعف: </span>{c}</li>)}
                        </ul>
                      )}
                      {r.reply && (
                        <div className="mt-4 rounded-xl border-s-2 border-brand bg-secondary/50 p-3.5">
                          <p className="text-xs font-semibold">پاسخ فروشگاه</p>
                          <p className="mt-1 text-sm leading-7 text-muted-foreground">{r.reply}</p>
                        </div>
                      )}
                      <button type="button" aria-pressed={mine} onClick={() => vote(r.id)} className={cn("mt-4 flex cursor-pointer items-center gap-1.5 rounded-full border px-3 py-1 text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring", mine ? "border-foreground/40 bg-secondary text-foreground" : "border-border text-muted-foreground hover:text-foreground")}>
                        <ThumbsUp className="size-3.5" />
                        مفید بود
                        <span className="tabular-nums">{fa((r.helpful ?? 0) + (mine ? 1 : 0))}</span>
                      </button>
                    </article>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </div>
    </section>
  );
}

/* گرافیت، مینیمال فنی و تم پیش‌فرض. این بلوک را در :root بگذارید. */
:root {
  color-scheme: dark;

  /* رنگ */
  --background: oklch(0.115 0.002 285);
  --foreground: oklch(0.975 0 0);
  --card: oklch(0.14 0.002 285);
  --card-foreground: oklch(0.975 0 0);
  --popover: oklch(0.16 0.002 285);
  --popover-foreground: oklch(0.975 0 0);
  --primary: oklch(0.975 0 0);
  --primary-foreground: oklch(0.13 0 0);
  --secondary: oklch(0.2 0.002 285);
  --secondary-foreground: oklch(0.975 0 0);
  --muted: oklch(0.175 0.002 285);
  --muted-foreground: oklch(0.63 0.004 285);
  --accent: oklch(0.2 0.002 285);
  --accent-foreground: oklch(0.975 0 0);
  --destructive: oklch(0.65 0.2 25);
  --success: oklch(0.75 0.16 160);
  --warning: oklch(0.82 0.16 80);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 11%);
  --ring: oklch(0.7 0 0);
  --brand: oklch(0.8 0.165 65);
  --brand-foreground: oklch(0.22 0.06 60);

  /* زبان طراحی: فونت، فرم، خط، عمق، حرکت و تراکم */
  --radius: 0.625rem;
  --type-display-weight: 700;
  --shape-control: calc(var(--radius) - 2px);
