/** Every occasion of a Jalali year, sorted by date (holidays first on a shared day). */
export function occasionsOf(jy: number): Occasion[] {
  const hit = cache.get(jy);
  if (hit) return hit;
  const first = toGregorian(jy, 1, 1);
  const last = toGregorian(jy, 12, jalaliMonthLength(jy, 12));
  const inYear = (d: Date) => d >= first && d <= last;
  const out: Occasion[] = [];
  const push = (date: Date, title: string, holiday: boolean, kind: Occasion["kind"], approximate: boolean, hijri?: HijriDate) =>
    out.push({ key: keyOf(date), date, title, holiday, kind, approximate, hijri });

  for (const [jm, jd, title, holiday] of SOLAR) push(toGregorian(jy, jm, jd), title, holiday, "solar", false);

  // چهارشنبه‌سوری: the evening before the last Wednesday of the year.
  let wed = last;
  while (jalaliWeekday(wed) !== 4) wed = addDays(wed, -1);
  push(addDays(wed, -1), "چهارشنبه‌سوری", false, "solar", false);

  const hyFirst = toHijri(first).hy;
  const hyLast = toHijri(last).hy;
  for (let hy = hyFirst; hy <= hyLast; hy += 1) {
    for (const [hm, rule, title, holiday] of LUNAR) {
      const hd = rule === "last" ? hijriMonthLength(hy, hm) : rule;
      const { date, approximate } = fromHijri(hy, hm, hd);
      if (!inYear(date)) continue;
      const exact = !approximate && !toHijri(date).approximate;
      push(date, title, holiday, "lunar", !exact, { hy, hm, hd, approximate: !exact });
    }
  }

  out.sort((a, b) => a.date.getTime() - b.date.getTime() || Number(b.holiday) - Number(a.holiday));
  cache.set(jy, out);
  return out;
}

function indexOf(jy: number) {
  let map = byKey.get(jy);
  if (!map) {
    map = new Map();
    for (const o of occasionsOf(jy)) map.set(o.key, [...(map.get(o.key) ?? []), o]);
    byKey.set(jy, map);
  }
  return map;
}

/** Occasions of one calendar day. */
export function occasionsOn(date: Date): Occasion[] {
  return indexOf(toJalali(date).jy).get(keyOf(date)) ?? [];
}

/** The built-in provider, keyed by "YYYY-MM-DD". */
export const iranOccasions: OccasionProvider = (key) => {
  const [y, m, d] = key.split("-").map(Number);
  return occasionsOn(new Date(y, m - 1, d));
};

/** Official day off (not counting Fridays). */
export function isHoliday(date: Date) {
  return occasionsOn(date).some((o) => o.holiday);
}

export type OffDayOptions = {
  /** Weekdays off, 0 = شنبه … 6 = جمعه. Default [6]. */
  weekend?: number[];
  /** Extra closed days as "YYYY-MM-DD". */
  extra?: string[];
};

/** Weekend, official holiday, or one of `extra`. */
export function isOffDay(date: Date, { weekend = [6], extra = [] }: OffDayOptions = {}) {
  return weekend.includes(jalaliWeekday(date)) || isHoliday(date) || extra.includes(keyOf(date));
}

/** Working days from `a` to `b`, both included. */
export function businessDaysBetween(a: Date, b: Date, opts?: OffDayOptions) {
  let n = 0;
  const [from, to] = a <= b ? [a, b] : [b, a];
  for (let d = new Date(from.getFullYear(), from.getMonth(), from.getDate()); d <= to; d = addDays(d, 1)) {
    if (!isOffDay(d, opts)) n += 1;
  }
  return n;
}

/** Occasions of several years merged into one lookup, for calendar grids. */
export function occasionMap(years: number[]): Map<string, Occasion[]> {
  const map = new Map<string, Occasion[]>();
  for (const jy of years) for (const [k, v] of indexOf(jy)) map.set(k, v);
  return map;
}

/**
 * Calendar math for the VibeFarsi calendar kit: Jalali day arithmetic, month
 * grids, time-zone parts, Persian time formats, overlap layout for events,
 * multi-day lanes, booking slots and a right-to-left time scale.
 *
 * Two kinds of value: a calendar day is a key "YYYY-MM-DD" (Gregorian, Latin
 * digits, from the local y/m/d of a Date); a timed event is an instant shown
 * in a time zone (default Asia/Tehran) through Intl. Dependency-free and
 * framework-free, so it is easy to test.
 */
import { fa } from "@/lib/utils";
import { JALALI_MONTHS, JALALI_WEEKDAYS, jalaliMonthLength, jalaliWeekday, toGregorian, toJalali } from "@/lib/jalali";

export const TEHRAN = "Asia/Tehran";

export type CalendarEvent = {
  id: string;
  title: string;
  start: Date;
  end: Date;
  allDay?: boolean;
  /** 1–7 picks var(--chart-N); any other string is used as a CSS color. */
  color?: number | string;
  resourceId?: string;
  location?: string;
};

export type Resource = { id: string; title: string; subtitle?: string; avatar?: string };

/* ---------- calendar days ---------- */

const pad = (n: number) => String(n).padStart(2, "0");
const DAY = 86_400_000;

/** "2026-10-12" for the local calendar day of `date`. */
export function dayKey(date: Date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** Local midnight of a day key. */
export function fromKey(key: string) {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
}

export function addDays(date: Date, n: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + n);
}

/** Whole calendar days from `a` to `b` (positive when b is later). */
export function diffDays(a: Date, b: Date) {
  return Math.round((Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()) - Date.UTC(a.getFullYear(), a.getMonth(), a.getDate())) / DAY);
}

export function isSameDay(a: Date | null | undefined, b: Date | null | undefined) {
  return !!a && !!b && dayKey(a) === dayKey(b);
}

/** The شنبه that starts the week of `date`. */
export function startOfJalaliWeek(date: Date) {
  return addDays(date, -jalaliWeekday(date));
}

/** Seven days, شنبه to جمعه. */
export function weekDates(date: Date) {
  const s = startOfJalaliWeek(date);
  return Array.from({ length: 7 }, (_, i) => addDays(s, i));
}

/** Moves by Jalali months; day 31 clamps to the month's last day. */
export function addJalaliMonths(date: Date, n: number) {
  const { jy, jm, jd } = toJalali(date);
  const total = jy * 12 + (jm - 1) + n;
  const y = Math.floor(total / 12);
  const m = (total % 12) + 1;
  return toGregorian(y, m, Math.min(jd, jalaliMonthLength(y, m)));
}

/** Weeks (rows of 7 dates, شنبه first) covering a Jalali month, with neighbour days filling the edges. */
export function monthGrid(jy: number, jm: number, { fixedWeeks = false } = {}) {
  const first = toGregorian(jy, jm, 1);
  const start = startOfJalaliWeek(first);
  const used = jalaliWeekday(first) + jalaliMonthLength(jy, jm);
  const rows = fixedWeeks ? 6 : Math.ceil(used / 7);
  return Array.from({ length: rows }, (_, r) => Array.from({ length: 7 }, (_, c) => addDays(start, r * 7 + c)));
}

/** «مهر ۱۴۰۵» */
export function monthTitle(jy: number, jm: number) {
  return `${JALALI_MONTHS[jm - 1]} ${fa(jy)}`;
}

/** «۱۲ مهر» */
export function shortDay(date: Date) {
  const { jm, jd } = toJalali(date);
  return `${fa(jd)} ${JALALI_MONTHS[jm - 1]}`;
}

/** «امروز»، «فردا»، «دیروز» or «چهارشنبه ۲۳ مهر». */
export function dayLabel(date: Date, today = new Date()) {
  const d = diffDays(today, date);
  if (d === 0) return "امروز";
  if (d === 1) return "فردا";
  if (d === -1) return "دیروز";
  return `${JALALI_WEEKDAYS[jalaliWeekday(date)]} ${shortDay(date)}`;
}

/* ---------- time zones ---------- */

const formatters = new Map<string, Intl.DateTimeFormat>();
function formatter(tz: string) {
  let f = formatters.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", { timeZone: tz, hourCycle: "h23", year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "numeric" });
    formatters.set(tz, f);
  }
  return f;
}

export type ZonedParts = { y: number; m: number; d: number; h: number; min: number };

/** Wall-clock parts of an instant in a time zone. */
export function zonedParts(date: Date, tz = TEHRAN): ZonedParts {
  const p: Record<string, number> = {};
  for (const { type, value } of formatter(tz).formatToParts(date)) if (type !== "literal") p[type] = Number(value);
  return { y: p.year, m: p.month, d: p.day, h: p.hour % 24, min: p.minute };
}

function offsetAt(ms: number, tz: string) {
  const p = zonedParts(new Date(ms), tz);
  return Date.UTC(p.y, p.m - 1, p.d, p.h, p.min) - Math.floor(ms / 60_000) * 60_000;
}

/** The instant whose wall clock in `tz` reads y-m-d h:min. Handles past DST rules. */
export function zonedDate(y: number, m: number, d: number, h = 0, min = 0, tz = TEHRAN) {
  const guess = Date.UTC(y, m - 1, d, h, min);
  let ms = guess - offsetAt(guess, tz);
  const again = guess - offsetAt(ms, tz);
  if (again !== ms) ms = again;
  return new Date(ms);
}

/** Day key of an instant as seen in `tz`. */
export function zonedKey(date: Date, tz = TEHRAN) {
  const p = zonedParts(date, tz);
  return `${p.y}-${pad(p.m)}-${pad(p.d)}`;
}

/** Minutes since midnight in `tz`. */
export function minutesOfDay(date: Date, tz = TEHRAN) {
  const p = zonedParts(date, tz);
  return p.h * 60 + p.min;
}

/** Instant at `minutes` past midnight of a day key in `tz`. Minutes may exceed 1440. */
export function atMinutes(key: string, minutes: number, tz = TEHRAN) {
  const [y, m, d] = key.split("-").map(Number);
  return zonedDate(y, m, d + Math.floor(minutes / 1440), Math.floor((minutes % 1440) / 60), minutes % 60, tz);
}

/** "09:30" → 570 */
export function parseHm(hm: string) {
  const [h, m] = hm.split(":").map(Number);
  return h * 60 + (m || 0);
}

/* ---------- formats ---------- */

/** «۰۹:۳۰» from minutes since midnight. */
export function formatMinutes(minutes: number) {
  const m = ((minutes % 1440) + 1440) % 1440;
  return fa(`${pad(Math.floor(m / 60))}:${pad(m % 60)}`);
}

/** «۱۴:۳۰» */
export function formatTime(date: Date, tz = TEHRAN) {
  return formatMinutes(minutesOfDay(date, tz));
}

/** «۱۰:۰۰ تا ۱۱:۳۰» */
export function formatTimeRange(start: Date, end: Date, tz = TEHRAN) {
  return `${formatTime(start, tz)} تا ${formatTime(end, tz)}`;
}

/** «۱ ساعت و ۳۰ دقیقه»، «۴۵ دقیقه»، «۲ ساعت» */
export function formatDuration(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  if (!h) return `${fa(m)} دقیقه`;
  return m ? `${fa(h)} ساعت و ${fa(m)} دقیقه` : `${fa(h)} ساعت`;
}

/** Same slots as the chart kit, so events and charts share a design system's palette. */
export const EVENT_COLORS = [
  "var(--chart-1, var(--brand))",
  "var(--chart-2, oklch(0.66 0.14 250))",
  "var(--chart-3, oklch(0.7 0.14 165))",
  "var(--chart-4, oklch(0.65 0.19 20))",
  "var(--chart-5, oklch(0.62 0.16 300))",
  "var(--chart-6, oklch(0.75 0.11 200))",
  "var(--chart-7, oklch(0.6 0.03 260))",
];

/** CSS color for an event: 1–7 → palette slot; strings pass through; missing → slot by index. */
export function eventColor(color: CalendarEvent["color"], fallbackIndex = 0) {
  if (typeof color === "string") return color;
  const n = typeof color === "number" ? color - 1 : fallbackIndex;
  return EVENT_COLORS[((n % 7) + 7) % 7];
}

/* ---------- layout: timed events in a day column ---------- */

export type TimedBox<T> = {
  event: T;
  /** Minutes since midnight, clipped to the visible range. */
  start: number;
  end: number;
  /** 0–1 fractions of the visible range. */
  top: number;
  height: number;
  col: number;
  cols: number;
  /** Starts before or ends after this day. */
  clippedStart: boolean;
  clippedEnd: boolean;
};

/**
 * Places the timed events of one day side by side where they overlap. Each
 * cluster of transitively overlapping events shares a column count.
 */
export function layoutTimed<T extends Pick<CalendarEvent, "start" | "end" | "allDay">>(
  events: T[],
  key: string,
  tz = TEHRAN,
  { startHour = 0, endHour = 24, minMinutes = 15 } = {},
): TimedBox<T>[] {
  const lo = startHour * 60;
  const hi = endHour * 60;
  const dayStart = atMinutes(key, 0, tz).getTime();
  const dayEnd = atMinutes(key, 1440, tz).getTime();
  const items = events
    .filter((e) => !e.allDay && e.start.getTime() < dayEnd && e.end.getTime() > dayStart)
    .map((event) => {
      const s = event.start.getTime() < dayStart ? 0 : minutesOfDay(event.start, tz);
      const rawEnd = event.end.getTime() >= dayEnd ? 1440 : minutesOfDay(event.end, tz);
      const start = Math.max(lo, Math.min(s, hi));
      const end = Math.max(start + minMinutes, Math.min(Math.max(rawEnd, s + minMinutes), hi));
      return { event, start, end, clippedStart: event.start.getTime() < dayStart, clippedEnd: event.end.getTime() > dayEnd };
    })
    .filter((i) => i.start < hi)
    .sort((a, b) => a.start - b.start || b.end - a.end);

  const out: TimedBox<T>[] = [];
  let cluster: { item: (typeof items)[number]; col: number }[] = [];
  let colEnds: number[] = [];
  let clusterEnd = -1;
  const flush = () => {
    for (const { item, col } of cluster) {
      out.push({ ...item, col, cols: colEnds.length, top: (item.start - lo) / (hi - lo), height: (item.end - item.start) / (hi - lo) });
    }
    cluster = [];
    colEnds = [];
  };
  for (const item of items) {
    if (item.start >= clusterEnd) flush();
    let col = colEnds.findIndex((end) => end <= item.start);
    if (col < 0) {
      col = colEnds.length;
      colEnds.push(item.end);
    } else colEnds[col] = item.end;
    cluster.push({ item, col });
    clusterEnd = Math.max(clusterEnd, item.end);
  }
  flush();
  return out;
}

/* ---------- layout: multi-day bars in a week row ---------- */

export type SpanBar<T> = {
  event: T;
  /** Column indexes in `days`, from ≤ to. */
  from: number;
  to: number;
  lane: number;
  continuesBefore: boolean;
  continuesAfter: boolean;
};

/** First and last day keys an event covers. An all-day event ending at midnight does not cover that day. */
export function eventDayRange(e: Pick<CalendarEvent, "start" | "end" | "allDay">, tz = TEHRAN): [string, string] {
  const startKey = e.allDay ? dayKey(e.start) : zonedKey(e.start, tz);
  const endInstant = new Date(Math.max(e.start.getTime(), e.end.getTime() - 1));
  const endKey = e.allDay ? dayKey(endInstant) : zonedKey(endInstant, tz);
  return [startKey, endKey < startKey ? startKey : endKey];
}

/** Whether an event belongs in an all-day lane: all-day or spanning more than one day. */
export function isSpanning(e: Pick<CalendarEvent, "start" | "end" | "allDay">, tz = TEHRAN) {
  if (e.allDay) return true;
  const [a, b] = eventDayRange(e, tz);
  return a !== b;
}

/** Stacks events over a row of consecutive day keys into lanes, longest first. */
export function layoutSpans<T extends Pick<CalendarEvent, "start" | "end" | "allDay">>(events: T[], days: string[], tz = TEHRAN): SpanBar<T>[] {
  const first = days[0];
  const last = days[days.length - 1];
  const bars = events
    .map((event) => {
      const [a, b] = eventDayRange(event, tz);
      if (b < first || a > last) return null;
      const from = a < first ? 0 : days.indexOf(a);
      const to = b > last ? days.length - 1 : days.indexOf(b);
      return { event, from, to, continuesBefore: a < first, continuesAfter: b > last };
    })
    .filter((b): b is NonNullable<typeof b> => !!b && b.from >= 0 && b.to >= 0)
    .sort((x, y) => x.from - y.from || y.to - y.from - (x.to - x.from));
  const lanes: number[] = [];
  return bars.map((b) => {
    let lane = lanes.findIndex((end) => end < b.from);
    if (lane < 0) {
      lane = lanes.length;
      lanes.push(b.to);
    } else lanes[lane] = b.to;
    return { ...b, lane };
  });
}

/* ---------- booking slots ---------- */

export type Slot = { start: Date; end: Date; left: number; state: "free" | "full" | "past" };

export type SlotOptions = {
  key: string;
  /** Opening windows as ["09:00", "13:00"]. */
  open: [string, string][];
  /** Minutes per appointment. */
  duration: number;
  /** Minutes between slot starts. Defaults to duration. */
  step?: number;
  /** Booked intervals; each overlap uses one seat. */
  busy?: { start: Date; end: Date }[];
  /** Seats per slot. Default 1. */
  capacity?: number;
  tz?: string;
  now?: Date;
};

/** Slots of one day with seats left and a state; slots starting before `now` are past. */
export function generateSlots({ key, open, duration, step = duration, busy = [], capacity = 1, tz = TEHRAN, now = new Date() }: SlotOptions): Slot[] {
  const out: Slot[] = [];
  for (const [a, b] of open) {
    const close = parseHm(b);
    for (let t = parseHm(a); t + duration <= close; t += step) {
      const start = atMinutes(key, t, tz);
      const end = atMinutes(key, t + duration, tz);
      const used = busy.filter((x) => x.start < end && x.end > start).length;
      const left = Math.max(0, capacity - used);
      out.push({ start, end, left, state: start < now ? "past" : left === 0 ? "full" : "free" });
    }
  }
  return out;
}

/* ---------- right-to-left time scale ---------- */

export type Zoom = "day" | "week" | "month";

/** Maps instants to x pixels with the start on the right edge and time flowing left. */
export function timeScale(start: Date, end: Date, width: number) {
  const s = start.getTime();
  const span = Math.max(1, end.getTime() - s);
  const x = (d: Date) => width - ((d.getTime() - s) / span) * width;
  const invert = (px: number) => new Date(s + ((width - px) / width) * span);
  return { x, invert, perDay: (width * DAY) / span };
}

export type Tick = { date: Date; label: string; major: boolean };

/** Day, week (each شنبه) or month (each 1st) ticks over local calendar days in [start, end). */
export function timeTicks(start: Date, end: Date, zoom: Zoom): Tick[] {
  const out: Tick[] = [];
  for (let d = new Date(start.getFullYear(), start.getMonth(), start.getDate()); d < end; d = addDays(d, 1)) {
    const { jm, jd } = toJalali(d);
    if (zoom === "day") out.push({ date: d, label: fa(jd), major: jd === 1 });
    else if (zoom === "week" && jalaliWeekday(d) === 0) out.push({ date: d, label: shortDay(d), major: jd <= 7 });
    else if (zoom === "month" && jd === 1) out.push({ date: d, label: JALALI_MONTHS[jm - 1], major: jm === 1 });
  }
  return out;
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";

/** Copy `data-theme` from an in-tree trigger onto a portaled panel. */
export function themeOf(el: Element | null | undefined) {
  return el?.closest("[data-theme]")?.getAttribute("data-theme") ?? undefined;
}

export type FloatSide = "top" | "bottom";
export type FloatAlign = "start" | "center" | "end";

/** Viewport `position:fixed` coords for a panel anchored to `el`. */
export function floatStyle(
  el: HTMLElement,
  {
    side = "bottom",
    align = "start",
    gap = 8,
    panel,
    matchWidth,
    x,
    y,
  }: {
    side?: FloatSide;
    align?: FloatAlign;
    gap?: number;
    panel?: HTMLElement | null;
    matchWidth?: boolean;
    x?: number;
    y?: number;
  } = {},
): React.CSSProperties {
  if (x != null && y != null) return { top: y, left: x };
  const r = el.getBoundingClientRect();
  const rtl = getComputedStyle(el).direction === "rtl";
  const ph = panel?.offsetHeight ?? 0;
  const pw = panel?.offsetWidth ?? 0;
  let actual: FloatSide = side;
  if (ph) {
    if (side === "bottom" && r.bottom + gap + ph > window.innerHeight && r.top - gap - ph >= gap) actual = "top";
    else if (side === "top" && r.top - gap - ph < gap && r.bottom + gap + ph <= window.innerHeight) actual = "bottom";
  }
  const s: React.CSSProperties = {};
  if (actual === "bottom") s.top = r.bottom + gap;
  else s.bottom = window.innerHeight - r.top + gap;
  if (matchWidth) {
    s.width = r.width;
    s.left = r.left;
  } else if (align === "center") s.left = Math.max(gap, r.left + r.width / 2 - pw / 2);
  else if ((align === "start") === !rtl) s.left = r.left;
  else s.right = window.innerWidth - r.right;
  return s;
}

export function eventInside(e: Event, ...nodes: (Node | null | undefined)[]) {
  const t = e.target as Node;
  return nodes.some((n) => n?.contains(t));
}

/** Place a panel with `position:fixed` and keep it in sync with scroll/resize. */
export function useFloat(
  open: boolean,
  anchor: React.RefObject<HTMLElement | null>,
  opts: { side?: FloatSide; align?: FloatAlign; gap?: number; matchWidth?: boolean } = {},
) {
  const { side = "bottom", align = "start", gap = 8, matchWidth = false } = opts;
  const [mounted, setMounted] = React.useState(false);
  const [style, setStyle] = React.useState<React.CSSProperties>({});
  const [theme, setTheme] = React.useState<string | undefined>();
  const panel = React.useRef<HTMLDivElement>(null);

  const update = React.useCallback(() => {
    const el = anchor.current;
    if (!el) return;
    setStyle(floatStyle(el, { side, align, gap, matchWidth, panel: panel.current }));
    setTheme(themeOf(el));
  }, [anchor, side, align, gap, matchWidth]);

  React.useEffect(() => setMounted(true), []);

  React.useLayoutEffect(() => {
    if (!open) return;
    update();
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    return () => {
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update, true);
    };
  }, [open, update]);

  return { mounted, style, theme, panel, update };
}

/** Renders `children` into `document.body` so overflow:hidden ancestors cannot clip them. */
export function FloatPortal({
  open,
  mounted,
  style,
  theme,
  panelRef,
  className,
  children,
  ...rest
}: {
  open: boolean;
  mounted: boolean;
  style: React.CSSProperties;
  theme?: string;
  panelRef?: React.Ref<HTMLDivElement>;
  className?: string;
  children: React.ReactNode;
} & React.HTMLAttributes<HTMLDivElement>) {
  if (!mounted || !open) return null;
  return createPortal(
    <div ref={panelRef} data-theme={theme} style={style} className={className} {...rest}>
      {children}
    </div>,
    document.body,
  );
}

# ParsPack S3 image upload (Next.js App Router)

Implementation guide for uploading images to **ParsPack** (S3-compatible
object storage) from a Next.js App Router project. Hand this to an AI or
developer to replicate the setup from scratch.

## Overview

Upload images **server-side** through a Next.js API route. The browser sends
`multipart/form-data` to `/api/upload`; the server validates the file, uploads
it to ParsPack via the AWS SDK, and returns a public URL.

**Flow:**

```
Browser (FormData) → POST /api/upload → uploadImage() → ParsPack S3 (PutObject) → { url, key }
```

ParsPack is treated as a generic S3-compatible provider. The critical
ParsPack-specific detail is **path-style URLs** and how public object URLs are
constructed.

---

## 1. Dependencies

Install the AWS SDK v3 S3 packages (ParsPack speaks the S3 API):

```bash
npm install @aws-sdk/client-s3 @aws-sdk/s3-request-presigner
```

---

## 2. Environment variables

Add these to `.env.local` (values come from the ParsPack dashboard):

```env
S3_ENDPOINT=https://YOUR_ACCOUNT.parspack.net
S3_BUCKET=your-bucket-name
S3_ACCESS_KEY_ID=your-access-key
S3_SECRET_ACCESS_KEY=your-secret-key
S3_REGION=us-east-1
S3_FORCE_PATH_STYLE=true
```

| Variable | Required | Notes |
|---|---|---|
| `S3_ENDPOINT` | Yes | ParsPack endpoint URL (no trailing slash) |
| `S3_BUCKET` | Yes | Bucket name |
| `S3_ACCESS_KEY_ID` | Yes | ParsPack access key |
| `S3_SECRET_ACCESS_KEY` | Yes | ParsPack secret key |
| `S3_REGION` | No | Defaults to `us-east-1` (ParsPack often ignores region) |
| `S3_FORCE_PATH_STYLE` | No | Defaults to `true`. Set to `"false"` only if using virtual-host style |

**Bucket setup:** The bucket must allow public read on uploaded objects if you
use direct public URLs (this guide does). Configure that in the ParsPack panel.

---

## 3. File structure

Create these files under `lib/s3/` plus one API route:

```
lib/s3/
  client.ts      # Singleton S3Client configured for ParsPack
  urls.ts        # Public URL builder + optional presigned URLs
  upload.ts      # Upload logic (validation + PutObject)
app/api/upload/
  route.ts       # Authenticated POST endpoint
```

---

## 4. S3 client (`lib/s3/client.ts`)

ParsPack requires a custom endpoint and **path-style** addressing:

```typescript
import { S3Client } from "@aws-sdk/client-s3";

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable: ${name}`);
  return value;
}

let client: S3Client | null = null;

export function getS3Client(): S3Client {
  if (client) return client;

  client = new S3Client({
    endpoint: requireEnv("S3_ENDPOINT"),
    region: process.env.S3_REGION ?? "us-east-1",
    credentials: {
      accessKeyId: requireEnv("S3_ACCESS_KEY_ID"),
      secretAccessKey: requireEnv("S3_SECRET_ACCESS_KEY"),
    },
    // ParsPack uses path-style: https://endpoint/bucket/key
    forcePathStyle: process.env.S3_FORCE_PATH_STYLE !== "false",
  });

  return client;
}

export function getS3Bucket(): string {
  return requireEnv("S3_BUCKET");
}
```

**Key ParsPack detail:** `forcePathStyle: true` is required. Without it, the
SDK may use virtual-host style (`bucket.endpoint/key`), which ParsPack may not
support.

---

## 5. URL helpers (`lib/s3/urls.ts`)

Public URLs for ParsPack path-style buckets:

```typescript
import { GetObjectCommand } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { getS3Bucket, getS3Client } from "./client";

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, "");
}

/** Public object URL for ParsPack path-style buckets. */
export function getPublicObjectUrl(key: string): string {
  const endpoint = trimTrailingSlash(process.env.S3_ENDPOINT ?? "");
  const bucket = getS3Bucket();
  const normalizedKey = key.replace(/^\/+/, "");
  return `${endpoint}/${bucket}/${normalizedKey}`;
}

/** Optional - for private buckets. */
export async function getPresignedObjectUrl(
  key: string,
  expiresIn = 3600
): Promise<string> {
  const command = new GetObjectCommand({
    Bucket: getS3Bucket(),
    Key: key.replace(/^\/+/, ""),
  });
  return getSignedUrl(getS3Client(), command, { expiresIn });
}
```

**Example URL shape:**

```
https://YOUR_ACCOUNT.parspack.net/my-bucket/uploads/<ownerId>/<uuid>.jpg
```

---

## 6. Upload logic (`lib/s3/upload.ts`)

```typescript
import { PutObjectCommand } from "@aws-sdk/client-s3";
import { randomUUID } from "crypto";
import { getPublicObjectUrl } from "./urls";
import { getS3Bucket, getS3Client } from "./client";

const ALLOWED_CONTENT_TYPES = new Map([
  ["image/jpeg", "jpg"],
  ["image/png", "png"],
  ["image/webp", "webp"],
  ["image/gif", "gif"],
]);

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5 MB

export async function uploadImage(
  ownerId: string,
  file: File
): Promise<{ url: string; key: string }> {
  if (!ALLOWED_CONTENT_TYPES.has(file.type)) {
    throw new Error("Invalid file type");
  }
  if (file.size > MAX_FILE_SIZE) {
    throw new Error("File too large");
  }

  const extension = ALLOWED_CONTENT_TYPES.get(file.type)!;
  const key = `uploads/${ownerId}/${randomUUID()}.${extension}`;
  const buffer = Buffer.from(await file.arrayBuffer());

  await getS3Client().send(
    new PutObjectCommand({
      Bucket: getS3Bucket(),
      Key: key,
      Body: buffer,
      ContentType: file.type,
    })
  );

  return { key, url: getPublicObjectUrl(key) };
}
```

**Design choices:**

- Validate MIME type and size on the server (do not rely on client-only checks).
- Key pattern: `uploads/{ownerId}/{uuid}.{ext}` - scoped per owner, collision-safe.
- Store and return the **public URL** in the DB, not the S3 key.
- Also return `key` if you need deletion or presigned access later.

---

## 7. API route (`app/api/upload/route.ts`)

Authenticated endpoint. Adapt the session helpers to your auth system:

```typescript
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/session";
import { uploadImage } from "@/lib/s3/upload";

export async function POST(request: NextRequest) {
  const session = await getSession();
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const formData = await request.formData();
  const file = formData.get("file");

  if (!file || !(file instanceof File)) {
    return NextResponse.json({ error: "No file provided" }, { status: 400 });
  }

  try {
    const result = await uploadImage(session.user.id, file);
    return NextResponse.json(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Upload failed";
    const status =
      message === "Invalid file type" || message === "File too large" ? 400 : 500;
    return NextResponse.json({ error: message }, { status });
  }
}
```

**Contract:**

| Method | Path | Auth | Body | Success response |
|---|---|---|---|---|
| `POST` | `/api/upload` | Session cookie | `FormData` field `file` | `{ url: string, key: string }` |

**Error responses:** `401`, `400` (validation), `500` (S3 failure).

---

## 8. Client-side usage

```typescript
const MAX_IMAGE_SIZE = 5 * 1024 * 1024;
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/gif"];

async function handleImageUpload(file: File) {
  // Client-side validation (mirrors server - UX only)
  if (!ALLOWED_IMAGE_TYPES.includes(file.type)) return;
  if (file.size > MAX_IMAGE_SIZE) return;

  const formData = new FormData();
  formData.append("file", file);

  const res = await fetch("/api/upload", { method: "POST", body: formData });
  if (!res.ok) {
    const data = await res.json().catch(() => null);
    throw new Error(data?.error || "Upload failed");
  }

  const { url } = await res.json();
  // Save url into form state, then persist with your record
  setForm((f) => ({ ...f, imageUrl: url }));
}
```

**Important:**

- Field name must be `"file"` (matches `formData.get("file")` on the server).
- Do **not** set `Content-Type` manually on `fetch` - the browser sets the
  multipart boundary.
- Block form submit while upload is in progress.
- File input: `accept="image/jpeg,image/png,image/webp,image/gif"`.

---

## 9. Next.js image config (`next.config.ts`)

If you use `next/image` with ParsPack URLs, allow the ParsPack hostname:

```typescript
const nextConfig = {
  images: {
    remotePatterns: [
      {
        protocol: "https",
        hostname: "YOUR_ACCOUNT.parspack.net", // your ParsPack endpoint host
        pathname: "/**",
      },
    ],
  },
};
```

Replace the hostname with your actual ParsPack endpoint host.

---

## 10. Auth / middleware notes

Keep `/api/upload` reachable from the browser. Auth belongs inside the route
(session cookies or tokens), not only in middleware redirects. If your
middleware protects all routes, exclude `/api/upload` from unauthenticated
redirects so the route can return JSON `401` itself.

---

## 11. ParsPack-specific checklist

When implementing or debugging:

1. **`forcePathStyle: true`** on `S3Client`.
2. **Public URL format:** `{S3_ENDPOINT}/{S3_BUCKET}/{key}` - not
   `https://bucket.endpoint/key`.
3. **Bucket ACL / policy:** Objects must be publicly readable if you store
   direct URLs.
4. **Endpoint host:** Use the exact endpoint from ParsPack
   (e.g. `https://YOUR_ACCOUNT.parspack.net`).
5. **Region:** `us-east-1` is fine as a placeholder; ParsPack is
   endpoint-driven.
6. **CORS:** Not needed for server-side upload. Only needed if you switch to
   direct browser → S3 uploads.

---

## 12. Common failure modes

| Symptom | Likely cause |
|---|---|
| `Missing required environment variable` | Env vars not set in `.env.local` / deployment |
| `403` / `AccessDenied` from S3 | Wrong credentials or bucket permissions |
| Upload succeeds but image 403 in browser | Bucket/object not public |
| Wrong URL shape | `forcePathStyle` is `false` or URL builder uses virtual-host style |
| `next/image` broken | ParsPack hostname missing from `remotePatterns` |
| `401` on upload | No session cookie; user not logged in |
| `File too large` / `Invalid file type` | Server validation - check MIME and 5 MB limit |

---

## 13. Optional extensions

- **Delete on record removal:** `DeleteObjectCommand` using stored `key`.
- **Private bucket:** Skip `getPublicObjectUrl`, use `getPresignedObjectUrl`
  when serving.
- **Direct browser upload:** Presigned `PutObject` URL to reduce server memory
  use for large files.
- **Image processing:** Resize/compress with `sharp` before `PutObject`.

---

## 14. Minimal test plan

1. Set all `S3_*` env vars from ParsPack.
2. Log in as an authenticated user.
3. `POST /api/upload` with a small JPEG via curl or the UI.
4. Confirm response:
   `{ "url": "https://...parspack.net/bucket/uploads/...", "key": "uploads/..." }`.
5. Open `url` in a browser - image should load.
6. Save a record with that `imageUrl` and confirm it renders.

---

## Nginx note (self-hosted)

If uploads work locally but fail with HTTP **413** behind nginx, raise
`client_max_body_size` above your app limit (e.g. `10M`) and reload nginx.
Default nginx body size is 1 MB and rejects before the request reaches Node.

# Zarinpal payment gateway (Next.js / Node.js)

Hand this document to an AI or developer to implement Zarinpal in any
Next.js or Node.js project from scratch.

## Table of contents

1. Overview
2. Environment variables
3. Zarinpal API reference
4. Payment flow
5. Database model
6. API route: create payment request
7. API route: verify payment callback
8. Frontend integration
9. Error handling
10. Security checklist
11. Testing and sandbox

---

## Overview

Zarinpal is an Iranian payment gateway. The integration has **two steps**:

```
User clicks "Pay"
      │
      ▼
[Your Server] ──POST──▶ Zarinpal /request  ──▶ returns authority token
      │
      ▼
Redirect user to Zarinpal payment page (StartPay URL)
      │
      ▼
User completes payment on Zarinpal
      │
      ▼
Zarinpal redirects back to your callback URL with ?Authority=...&Status=OK
      │
      ▼
[Your Server] ──POST──▶ Zarinpal /verify  ──▶ returns ref_id (success)
      │
      ▼
Grant product/service to user, save transaction record
```

---

## Environment variables

```env
# Required
ZARINPAL_MERCHANT_ID=xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx

# Optional: set to true for sandbox/test mode (default: production)
ZARINPAL_SANDBOX=true

# Required: your app's public base URL (used to build the callback URL)
NEXTAUTH_URL=https://yourdomain.com
# or
NEXT_PUBLIC_BASE_URL=https://yourdomain.com
```

**Important:** `ZARINPAL_MERCHANT_ID` must **never** be exposed to the client.
Keep it server-side only.

---

## Zarinpal API reference

### Base URLs

| Mode | Base URL |
|---|---|
| Sandbox | `https://sandbox.zarinpal.com` |
| Production | `https://payment.zarinpal.com` |

### Endpoints

| Action | Full URL |
|---|---|
| Create request | `{BASE}/pg/v4/payment/request.json` |
| Verify payment | `{BASE}/pg/v4/payment/verify.json` |
| StartPay (sandbox) | `https://sandbox.zarinpal.com/pg/StartPay/{authority}` |
| StartPay (production) | `https://www.zarinpal.com/pg/StartPay/{authority}` |

### Step 1: create payment request

**POST** `{BASE}/pg/v4/payment/request.json`

Request body:

```json
{
  "merchant_id": "your-merchant-id",
  "amount": 490000,
  "callback_url": "https://yourdomain.com/api/payment/zarinpal/verify",
  "description": "Purchase description",
  "metadata": {
    "mobile": "09120000000",
    "email": "user@example.com"
  }
}
```

> **Currency:** Zarinpal API expects **Rial**. If your app stores prices in
> **Toman**, multiply by 10 before sending.
> Example: 49,000 Toman × 10 = 490,000 Rial.

Successful response:

```json
{
  "data": {
    "code": 100,
    "message": "Success",
    "authority": "A000000000000000000000000000000000",
    "fee_type": "Merchant",
    "fee": 0
  },
  "errors": []
}
```

Check `data.code === 100` and `data.authority` is present.

### Step 2: verify payment

**POST** `{BASE}/pg/v4/payment/verify.json`

Request body:

```json
{
  "merchant_id": "your-merchant-id",
  "amount": 490000,
  "authority": "A000000000000000000000000000000000"
}
```

> Send the **same amount (in Rial)** used in the request step.

Successful response:

```json
{
  "data": {
    "code": 100,
    "ref_id": 12345678,
    "message": "Paid",
    "card_hash": "...",
    "card_pan": "...",
    "fee_type": "Merchant",
    "fee": 0
  },
  "errors": []
}
```

**Verification codes:**

| Code | Meaning |
|---|---|
| 100 | Payment verified successfully (first time) |
| 101 | Payment already verified (duplicate callback) |
| Other | Failure: do not grant the product |

---

## Payment flow

1. User initiates payment on your frontend.
2. Frontend sends `POST /api/payment/zarinpal/request` with purchase details.
3. Your server validates the user and purchase details.
4. Your server calls Zarinpal `/request.json` and gets `authority`.
5. Your server saves a `pending` billing/transaction record with the `authority`.
6. Your server returns `{ paymentUrl }` to the frontend.
7. Frontend redirects user to `paymentUrl` (Zarinpal's payment page).
8. User completes (or cancels) payment on Zarinpal.
9. Zarinpal calls your `callback_url` with `?Authority=xxx&Status=OK` (or `Status=NOK`).
10. Your server reads `Authority` and `Status` from query params.
11. If `Status !== "OK"`, mark billing as `failed`, redirect user to failure page.
12. Your server finds the pending billing record by `authority`.
13. Your server calls Zarinpal `/verify.json` with `merchant_id`, `amount`, `authority`.
14. If `code === 100`: mark billing `paid`, save `ref_id`, grant product to user.
15. If `code === 101`: already verified; redirect to success page (idempotent).
16. Otherwise: mark billing `failed`, redirect to failure page.

---

## Database model

Store one record per payment attempt. Minimum required fields:

```typescript
interface BillingRecord {
  id: string;                     // unique invoice ID
  userId: string;                 // reference to user
  amount: number;                 // amount in Toman (your currency)
  status: "pending" | "paid" | "failed";
  authority: string;              // Zarinpal authority token
  refId?: string;                 // Zarinpal ref_id after successful verification
  createdAt: Date;
  updatedAt: Date;

  // Optional: depends on your product
  type?: string;                  // e.g. "plan" | "credits"
  period?: string;                // e.g. "monthly" | "yearly"
  description?: string;

  // Optional: discount support
  originalAmount?: number;
  discountAmount?: number;
  discountCode?: string;
}
```

**Key rule:** Always look up the billing record by `authority` in the verify
step. Never trust the amount from the callback query params; use the amount
stored in your database.

---

## API route: request

`POST /api/payment/zarinpal/request`

```typescript
// app/api/payment/zarinpal/request/route.ts
import { NextRequest, NextResponse } from "next/server";

const ZARINPAL_SANDBOX = process.env.ZARINPAL_SANDBOX === "true";
const ZARINPAL_BASE = ZARINPAL_SANDBOX
  ? "https://sandbox.zarinpal.com"
  : "https://payment.zarinpal.com";
const REQUEST_URL = `${ZARINPAL_BASE}/pg/v4/payment/request.json`;

function getBaseUrl(): string {
  return (
    process.env.NEXTAUTH_URL ||
    process.env.NEXT_PUBLIC_BASE_URL ||
    "http://localhost:3000"
  ).replace(/\/$/, "");
}

export async function POST(request: NextRequest) {
  // 1. Authenticate the user (use your auth system)
  const session = await getYourSession(request);
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  // 2. Validate merchant ID
  const merchantId = process.env.ZARINPAL_MERCHANT_ID;
  if (!merchantId) {
    console.error("ZARINPAL_MERCHANT_ID is not set");
    return NextResponse.json(
      { error: "Payment gateway not configured" },
      { status: 500 }
    );
  }

  // 3. Parse and validate request body
  const body = await request.json();
  // Example: body = { type: "plan", period: "monthly", discountCode: "SAVE10" }
  // Validate body here based on your product logic...

  // 4. Compute amount in Toman (server-side: NEVER trust client amount)
  const amountInToman = computeAmount(body); // your pricing logic
  const amountInRial = amountInToman * 10;

  // 5. Handle zero-amount / fully-discounted flow
  if (amountInToman <= 0) {
    const billing = await saveBillingRecord({
      userId: session.user.id,
      amount: 0,
      status: "paid",
      ...body,
    });
    await grantProductToUser(session.user.id, body); // your business logic
    return NextResponse.json({
      success: true,
      free: true,
      billingId: billing.id,
      message: "Purchase activated for free",
    });
  }

  // 6. Call Zarinpal
  const callbackUrl = `${getBaseUrl()}/api/payment/zarinpal/verify`;
  const zarinpalRes = await fetch(REQUEST_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      merchant_id: merchantId,
      amount: amountInRial,
      callback_url: callbackUrl,
      description: `Purchase for user ${session.user.id}`,
      metadata: {
        mobile: session.user.phone || "",
        email: session.user.email || "",
      },
    }),
  });

  const zarinpalData = await zarinpalRes.json();

  if (zarinpalData.data?.code !== 100 || !zarinpalData.data?.authority) {
    console.error("Zarinpal request failed:", zarinpalData);
    return NextResponse.json(
      { error: "Payment gateway error. Try again." },
      { status: 500 }
    );
  }

  const authority = zarinpalData.data.authority;
  const paymentUrl = ZARINPAL_SANDBOX
    ? `https://sandbox.zarinpal.com/pg/StartPay/${authority}`
    : `https://www.zarinpal.com/pg/StartPay/${authority}`;

  // 7. Save pending billing record
  const billing = await saveBillingRecord({
    userId: session.user.id,
    amount: amountInToman,
    status: "pending",
    authority,
    ...body,
  });

  return NextResponse.json({
    success: true,
    authority,
    paymentUrl,
    billingId: billing.id,
  });
}
```

---

## API route: verify

`GET /api/payment/zarinpal/verify`

```typescript
// app/api/payment/zarinpal/verify/route.ts
import { NextRequest } from "next/server";
import { redirect } from "next/navigation";

const ZARINPAL_SANDBOX = process.env.ZARINPAL_SANDBOX === "true";
const ZARINPAL_BASE = ZARINPAL_SANDBOX
  ? "https://sandbox.zarinpal.com"
  : "https://payment.zarinpal.com";
const VERIFY_URL = `${ZARINPAL_BASE}/pg/v4/payment/verify.json`;

const RESULT_PAGE = "/payment/result"; // adapt to your routing

export async function GET(request: NextRequest) {
  const authority = request.nextUrl.searchParams.get("Authority");
  const status = request.nextUrl.searchParams.get("Status");

  // 1. Validate callback params
  if (!authority || status !== "OK") {
    redirect(`${RESULT_PAGE}?payment=failed`);
  }

  const merchantId = process.env.ZARINPAL_MERCHANT_ID;
  if (!merchantId) {
    redirect(`${RESULT_PAGE}?payment=error`);
  }

  // 2. Find pending billing record
  const billing = await findBillingByAuthority(authority, "pending");

  if (!billing) {
    // Check if already verified (idempotent)
    const existing = await findBillingByAuthority(authority, "paid");
    if (existing) {
      redirect(`${RESULT_PAGE}?payment=success`);
    }
    redirect(`${RESULT_PAGE}?payment=notfound`);
  }

  // 3. Call Zarinpal verify: use amount from DB, not from callback
  const amountInRial = billing.amount * 10;
  const verifyRes = await fetch(VERIFY_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      merchant_id: merchantId,
      amount: amountInRial,
      authority,
    }),
  });

  const verifyData = await verifyRes.json();
  const code = verifyData.data?.code;

  // 4. Handle already-verified (idempotent)
  if (code === 101) {
    redirect(`${RESULT_PAGE}?payment=success`);
  }

  // 5. Handle failure
  if (code !== 100) {
    console.error("Zarinpal verify failed:", verifyData);
    await updateBillingStatus(billing.id, "failed");
    redirect(`${RESULT_PAGE}?payment=verify_failed`);
  }

  // 6. Success: save ref_id, grant product
  const refId = verifyData.data?.ref_id;
  await updateBillingRecord(billing.id, {
    status: "paid",
    refId: refId?.toString(),
  });
  await grantProductToUser(billing.userId, billing); // your business logic

  redirect(`${RESULT_PAGE}?payment=success`);
}
```

---

## Frontend integration

### Minimal client-side flow

```typescript
async function handlePayment(purchaseDetails: object) {
  const res = await fetch("/api/payment/zarinpal/request", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(purchaseDetails),
  });

  const data = await res.json();

  if (!res.ok || !data.success) {
    showError(data.error || "Payment failed. Try again.");
    return;
  }

  if (data.free) {
    showSuccess(data.message);
    return;
  }

  window.location.href = data.paymentUrl;
}
```

### Reading payment result on return

```typescript
const searchParams = new URLSearchParams(window.location.search);
const paymentStatus = searchParams.get("payment");

// paymentStatus values:
// "success"       - payment verified and product granted
// "failed"        - user cancelled or Status !== OK
// "verify_failed" - verification failed at Zarinpal
// "notfound"      - authority not found in DB
// "error"         - server configuration error
```

---

## Error handling

| Scenario | Cause | What to do |
|---|---|---|
| `data.code !== 100` on request | Invalid merchant ID, gateway issue | Return error to user, log details |
| `Status=NOK` on callback | User cancelled payment | Redirect to `?payment=failed` |
| `code === 101` on verify | Duplicate callback (already verified) | Treat as success (idempotent) |
| Billing record not found on verify | Invalid or expired authority | Redirect to `?payment=notfound` |
| `ZARINPAL_MERCHANT_ID` not set | Missing env var | Redirect to `?payment=error`, log server-side |
| Network timeout calling Zarinpal | Intermittent issue | Return 500 to user, do NOT grant product |

### Zero-amount / fully-discounted purchases

If a discount brings the total to `0` or below, skip the Zarinpal gateway entirely:

- Save billing as `paid` immediately.
- Grant the product to the user.
- Return `{ success: true, free: true }` with no `paymentUrl`.

---

## Security checklist

- [ ] `ZARINPAL_MERCHANT_ID` is server-side only, never sent to client.
- [ ] Amount is always computed server-side from your own pricing logic, never from client input.
- [ ] In verify step, amount comes from the stored billing record, never from callback query params.
- [ ] Product is only granted after `code === 100` (or the free flow).
- [ ] Duplicate callbacks (`code === 101`) are handled idempotently without double-granting.
- [ ] Billing record is looked up by `authority` before verifying (prevents forged callbacks).
- [ ] Use HTTPS in production for the callback URL.
- [ ] Never log `ZARINPAL_MERCHANT_ID` or full user payment details.

---

## Testing and sandbox

1. Set `ZARINPAL_SANDBOX=true` in your `.env.local`.
2. Register at [Zarinpal Sandbox](https://sandbox.zarinpal.com) to get a sandbox merchant ID.
3. Use test card numbers provided by Zarinpal in the sandbox environment.
4. After a successful sandbox payment, confirm:
   - Billing record status changes to `paid`.
   - `refId` is saved.
   - Product/subscription is granted to the user.
5. Cancel a payment and confirm `status=failed` and no product is granted.
6. Test duplicate callback by calling the verify URL twice with the same
   authority; the second call should be handled gracefully (idempotent,
   `code === 101`).

---

