    <span className="flex items-center gap-2 text-lg font-black">
      <span className="grid size-7 place-items-center rounded-lg bg-foreground text-sm text-background">ن</span>
      نقش
      <span className="size-1.5 rounded-full bg-brand" />
    </span>
  );
}

/** Header, mobile menu and footer shared by every page. `active` is the current route. */
export function Shell({ active, children }: { active: string; children: React.ReactNode }) {
  const href = useHref();
  const [open, setOpen] = React.useState(false);

  return (
    <div className="min-h-dvh bg-background text-foreground">
      <header className="sticky top-0 z-40 border-b border-border/60 bg-background/75 backdrop-blur-md">
        <nav aria-label="اصلی" className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-6 px-4 sm:px-6">
          <a href={href("/")} aria-label="استودیو نقش، خانه">
            <Logo />
          </a>
          <ul className="hidden items-center gap-1 md:flex">
            {NAV.map((l) => (
              <li key={l.href}>
                <a
                  href={href(l.href)}
                  aria-current={active === l.href ? "page" : undefined}
                  className={cn(
                    "rounded-full px-3.5 py-2 text-sm transition-colors hover:text-foreground",
                    active === l.href ? "bg-secondary text-foreground" : "text-muted-foreground",
                  )}
                >
                  {l.label}
                </a>
              </li>
            ))}
          </ul>
          <a
            href={href("/contact")}
            className="hidden h-10 items-center gap-2 rounded-full bg-foreground px-5 text-sm font-semibold text-background transition-transform hover:scale-[1.03] md:inline-flex"
          >
            شروع پروژه
            <ArrowUpLeft className="size-4" />
          </a>
          <Button variant="ghost" size="icon" className="md:hidden" aria-label="باز کردن منو" onClick={() => setOpen(true)}>
            <Menu />
          </Button>
        </nav>
      </header>
      {/* A sibling of the header: backdrop-blur would otherwise trap the fixed sheet inside it. */}
      <Sheet open={open} onOpenChange={setOpen} title={<Logo />}>
        <ul className="flex flex-col p-2">
          {[...NAV, { href: "/contact", label: "شروع پروژه" }].map((l) => (
            <li key={l.href}>
              <a
                href={href(l.href)}
                aria-current={active === l.href ? "page" : undefined}
                onClick={() => setOpen(false)}
                className="block rounded-lg px-3 py-3 text-base aria-[current=page]:bg-secondary aria-[current=page]:font-semibold"
              >
                {l.label}
              </a>
            </li>
          ))}
        </ul>
      </Sheet>

      <main>{children}</main>

      <footer className="border-t border-border">
        {active !== "/contact" && (
          <a href={href("/contact")} className="group mx-auto block max-w-6xl px-4 pt-20 pb-16 sm:px-6">
            <p className="text-sm text-muted-foreground">پروژه‌ی بعدی</p>
            <p className="mt-3 flex items-center gap-4 text-4xl font-black leading-tight sm:text-6xl lg:text-7xl">
              بیایید حرف بزنیم
              <ArrowUpLeft className="size-10 shrink-0 text-brand transition-transform duration-300 group-hover:-translate-x-2 group-hover:-translate-y-2 sm:size-14" />
            </p>
          </a>
        )}
        <div className="mx-auto grid max-w-6xl gap-8 border-t border-border px-4 py-10 text-sm sm:grid-cols-2 sm:px-6 lg:grid-cols-4">
          <div className="space-y-3">
            <Logo />
            <p className="leading-7 text-muted-foreground">استودیوی طراحی و ساخت محصول دیجیتال، از ۱۳۹۱ در تهران.</p>
          </div>
          <div className="space-y-2">
            <p className="font-semibold">صفحه‌ها</p>
            {NAV.map((l) => (
              <a key={l.href} href={href(l.href)} className="block text-muted-foreground hover:text-foreground">
                {l.label}
              </a>
            ))}
          </div>
          <div className="space-y-2">
            <p className="font-semibold">دفتر</p>
            <p className="leading-7 text-muted-foreground">تهران، خیابان ولیعصر، کوچه‌ی بهار، پلاک ۱۲</p>
            <p className="text-muted-foreground">
              <span dir="ltr">۰۲۱ ۸۸۸۸ ۱۲۱۲</span>
            </p>
          </div>
          <div className="space-y-2">
            <p className="font-semibold">شبکه‌ها</p>
            {["اینستاگرام", "لینکدین", "دریبل"].map((s) => (
              <a key={s} href="#" className="block text-muted-foreground hover:text-foreground">
                {s}
              </a>
            ))}
          </div>
        </div>
        <p className="border-t border-border py-5 text-center text-xs text-muted-foreground">© ۱۴۰۵ استودیو نقش. همه‌ی حقوق محفوظ است.</p>
      </footer>
    </div>
  );
}

"use client";

import * as React from "react";
import { Reveal } from "@/components/animations/reveal";
import { cn, fa } from "@/lib/utils";
import { Cover, PROJECTS, Shell, type Category } from "./shell";

const FILTERS: ("همه" | Category)[] = ["همه", "برند", "وب", "اپ", "محصول"];

/** نمونه‌کارها با فیلتر دسته. */
export function WorkPage() {
  const [filter, setFilter] = React.useState<(typeof FILTERS)[number]>("همه");
  const list = filter === "همه" ? PROJECTS : PROJECTS.filter((p) => p.cat === filter);

  return (
    <Shell active="/work">
      <section className="mx-auto max-w-6xl px-4 pt-16 pb-10 sm:px-6 sm:pt-24">
        <p className="text-sm text-muted-foreground">نمونه‌کارها</p>
        <h1 className="mt-3 max-w-3xl text-4xl font-black leading-tight sm:text-6xl">
          {fa(PROJECTS.length)} پروژه که دوستشون داریم
        </h1>
        <div role="group" aria-label="فیلتر دسته" className="mt-10 flex flex-wrap gap-2">
          {FILTERS.map((f) => {
            const count = f === "همه" ? PROJECTS.length : PROJECTS.filter((p) => p.cat === f).length;
            return (
              <button
                key={f}
                type="button"
                aria-pressed={filter === f}
                onClick={() => setFilter(f)}
                className={cn(
                  "inline-flex h-10 cursor-pointer items-center gap-2 rounded-full border px-4 text-sm transition-colors",
                  filter === f ? "border-foreground bg-foreground text-background" : "border-border text-muted-foreground hover:text-foreground",
                )}
              >
                {f}
                <span className={cn("text-xs", filter === f ? "text-background/60" : "text-muted-foreground/70")}>{fa(count)}</span>
              </button>
            );
          })}
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 pb-24 sm:px-6">
        <ul className="grid gap-x-5 gap-y-12 sm:grid-cols-2">
          {list.map((p, i) => (
            <li key={p.title} className={cn(i % 3 === 0 && "sm:col-span-2")}>
              <Reveal delay={(i % 2) * 80}>
                <article className="group">
                  <Cover project={p} className={cn("rounded-3xl border border-border", i % 3 === 0 ? "aspect-[16/7]" : "aspect-square")}>
                    <span className="absolute top-4 start-4 rounded-full bg-background/80 px-3 py-1 text-xs font-medium backdrop-blur">{p.cat}</span>
                  </Cover>
                  <div className="mt-4 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
                    <h2 className="text-xl font-bold">{p.title}</h2>
                    <p className="text-sm text-muted-foreground">
                      {p.client} · {p.year}
                    </p>
                  </div>
                  <p className="mt-2 text-sm text-brand">{p.metric}</p>
                </article>
              </Reveal>
            </li>
          ))}
        </ul>
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { ArrowLeft, Clock } from "lucide-react";
import { Avatar } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Reveal } from "@/components/animations/reveal";
import { cn, fa } from "@/lib/utils";
import { Photo, Shell } from "./shell";

type Cat = "مالیات" | "مدیریت مالی" | "آموزش" | "اخبار محصول";
const CATS: ("همه" | Cat)[] = ["همه", "مالیات", "مدیریت مالی", "آموزش", "اخبار محصول"];

const POSTS: { t: string; ex: string; cat: Cat; date: string; min: number; author: string; photo?: string }[] = [
  { t: "راهنمای کامل سامانه‌ی مودیان برای کسب‌وکارهای کوچک", ex: "از گرفتن کلید امضا تا ارسال اولین صورت‌حساب، قدم‌به‌قدم و با عکس.", cat: "مالیات", date: "۲۸ شهریور ۱۴۰۵", min: 12, author: "نسرین طاهری", photo: "blog-tax" },
  { t: "نسخه‌ی ۳ منتشر شد: تطبیق خودکار بانک", ex: "تراکنش‌ها هر شب وارد میشن و با فاکتورها جفت میشن.", cat: "اخبار محصول", date: "۲۰ شهریور ۱۴۰۵", min: 4, author: "تیم حسابینو" },
  { t: "جریان نقدی را چطور هر هفته بخونیم؟", ex: "سه عدد که هر صاحب کسب‌وکاری باید دوشنبه‌ها نگاه کنه.", cat: "مدیریت مالی", date: "۱۴ شهریور ۱۴۰۵", min: 7, author: "بهرام صادقی", photo: "blog-cash" },
  { t: "ارزش افزوده‌ی فصل تابستان: چک‌لیست ۱۰ دقیقه‌ای", ex: "قبل از ۱۵ مهر این موارد را بررسی کنید تا جریمه نشید.", cat: "مالیات", date: "۱۰ شهریور ۱۴۰۵", min: 6, author: "نسرین طاهری" },
  { t: "انبارگردانی پایان سال بدون تعطیل کردن فروشگاه", ex: "با شمارش چرخشی موجودی را همیشه دقیق نگه دارید.", cat: "آموزش", date: "۲ شهریور ۱۴۰۵", min: 9, author: "مهدی کریمی", photo: "blog-stock" },
  { t: "قیمت‌گذاری در تورم: کی و چقدر گرون کنیم؟", ex: "یک روش ساده بر اساس حاشیه‌ی سود و سرعت فروش هر کالا.", cat: "مدیریت مالی", date: "۲۵ مرداد ۱۴۰۵", min: 8, author: "بهرام صادقی" },
  { t: "ساخت فاکتور با لوگو و مهر در پنج دقیقه", ex: "قالب فاکتور را یک بار تنظیم کنید و همیشه استفاده کنید.", cat: "آموزش", date: "۱۸ مرداد ۱۴۰۵", min: 3, author: "مهدی کریمی" },
];

const cover = (i: number) =>
  [
    "radial-gradient(90% 90% at 80% 10%, color-mix(in oklch, var(--brand) 60%, transparent), transparent 60%), var(--secondary)",
    "linear-gradient(135deg, color-mix(in oklch, var(--brand) 40%, var(--card)), var(--card))",
    "repeating-linear-gradient(45deg, color-mix(in oklch, var(--foreground) 7%, transparent) 0 2px, transparent 2px 12px), var(--secondary)",
  ][i % 3];

/** وبلاگ با مطلب ویژه، فیلتر دسته و خبرنامه. */
export function BlogPage() {
  const [cat, setCat] = React.useState<(typeof CATS)[number]>("همه");
  const [joined, setJoined] = React.useState(false);
  const [featured, ...rest] = POSTS;
  const list = cat === "همه" ? rest : POSTS.filter((p) => p.cat === cat);

  return (
    <Shell active="/blog">
      <section className="mx-auto max-w-6xl px-4 pt-16 sm:px-6 sm:pt-20">
        <h1 className="text-4xl font-black">وبلاگ حسابینو</h1>
        <p className="mt-3 text-muted-foreground">مالیات، مدیریت مالی و آموزش، به زبان ساده.</p>

        {cat === "همه" && (
          <a href="#" className="group mt-10 grid overflow-hidden rounded-3xl border border-border bg-card lg:grid-cols-2">
            <div className="relative min-h-60 overflow-hidden" style={{ background: cover(0) }}>
              {featured.photo && <Photo name={featured.photo} alt="" eager className="absolute inset-0 transition-transform duration-700 group-hover:scale-[1.03]" />}
              <span className="absolute bottom-5 start-5 rounded-full bg-background/80 px-3 py-1 text-xs backdrop-blur">مطلب ویژه</span>
            </div>
            <div className="flex flex-col justify-center p-7 sm:p-10">
              <p className="text-xs font-semibold text-brand">{featured.cat}</p>
              <h2 className="mt-3 text-2xl font-black leading-snug transition-colors group-hover:text-brand sm:text-3xl">{featured.t}</h2>
              <p className="mt-3 leading-7 text-muted-foreground">{featured.ex}</p>
              <div className="mt-6 flex items-center gap-3 text-sm">
                <Avatar name={featured.author} size="sm" />
                <span>{featured.author}</span>
                <span className="text-muted-foreground">· {featured.date}</span>
              </div>
            </div>
          </a>
        )}

        <div role="group" aria-label="دسته‌ها" className="mt-12 flex gap-2 overflow-x-auto pb-1">
          {CATS.map((c) => (
            <button
              key={c}
              type="button"
              aria-pressed={cat === c}
              onClick={() => setCat(c)}
              className={cn(
                "h-9 shrink-0 cursor-pointer rounded-full border px-4 text-sm transition-colors",
                cat === c ? "border-foreground bg-foreground text-background" : "border-border text-muted-foreground hover:text-foreground",
              )}
            >
              {c}
            </button>
          ))}
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 py-10 sm:px-6">
        <ul className="grid gap-x-5 gap-y-10 sm:grid-cols-2 lg:grid-cols-3">
          {list.map((p, i) => (
            <li key={p.t}>
              <Reveal delay={(i % 3) * 60}>
                <a href="#" className="group block">
                  <div className="aspect-[16/10] overflow-hidden rounded-2xl border border-border" style={{ background: cover(i + 1) }}>
                    {p.photo && <Photo name={p.photo} alt="" className="transition-transform duration-700 group-hover:scale-[1.03]" />}
                  </div>
                  <p className="mt-4 text-xs font-semibold text-brand">{p.cat}</p>
                  <h3 className="mt-2 text-lg font-bold leading-snug transition-colors group-hover:text-brand">{p.t}</h3>
                  <p className="mt-2 text-sm leading-7 text-muted-foreground">{p.ex}</p>
                  <p className="mt-3 flex items-center gap-2 text-xs text-muted-foreground">
                    {p.date}
                    <span aria-hidden>·</span>
                    <Clock className="size-3" />
                    {fa(p.min)} دقیقه
                  </p>
                </a>
              </Reveal>
            </li>
          ))}
        </ul>
      </section>

      <section className="mx-auto max-w-6xl px-4 pb-24 sm:px-6">
        <div className="grid items-center gap-6 rounded-3xl border border-border bg-gradient-to-l from-brand/15 to-card p-7 sm:p-10 lg:grid-cols-2">
          <div>
            <h2 className="text-2xl font-black">خبرنامه‌ی هفتگی</h2>
            <p className="mt-2 leading-7 text-muted-foreground">هر شنبه یک مطلب کاربردی و مهلت‌های مالیاتی همون هفته. بدون تبلیغ.</p>
          </div>
          {joined ? (
            <p role="status" className="text-sm font-semibold text-success">
              ثبت شد. شنبه‌ی بعد اولین ایمیل را می‌گیرید.
            </p>
          ) : (
            <form
              className="flex gap-2"
              onSubmit={(e) => {
                e.preventDefault();
                setJoined(true);
              }}
            >
              <Input type="email" required dir="ltr" placeholder="you@company.ir" aria-label="ایمیل" className="h-11" />
              <Button type="submit" className="h-11 shrink-0">
                عضویت
                <ArrowLeft />
              </Button>
            </form>
          )}
        </div>
      </section>
    </Shell>
  );
}

