            { i: Lock, t: "رمزنگاری کامل", b: "اتصال TLS و رمزنگاری داده‌ها روی دیسک." },
            { i: RefreshCw, t: "پشتیبان روزانه", b: "تا ۳۰ روز قبل را می‌تونید برگردونید." },
            { i: KeyRound, t: "ورود دومرحله‌ای", b: "کد پیامکی یا اپ احراز هویت." },
