      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { ArrowRight, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PhoneInput } from "@/components/ui/phone-input";
import { OtpField } from "@/components/ui/otp-field";
import { Avatar } from "@/components/ui/avatar";
import { fa } from "@/lib/utils";
import { Photo, Shell } from "./shell";

type Step = "phone" | "code" | "done";

/** ورود و ثبت‌نام با شماره‌ی موبایل و کد تأیید. */
export function LoginPage() {
  const [step, setStep] = React.useState<Step>("phone");
  const [phone, setPhone] = React.useState("");
  const [valid, setValid] = React.useState(false);
  const [left, setLeft] = React.useState(0);
  const [error, setError] = React.useState("");

  React.useEffect(() => {
    if (left <= 0) return;
    const id = window.setTimeout(() => setLeft((s) => s - 1), 1000);
    return () => window.clearTimeout(id);
  }, [left]);

  const send = () => {
    setStep("code");
    setLeft(90);
    setError("");
  };

  const verify = (code: string) => {
    // Demo rule: any code except 000000 passes. Call your API here.
    if (code === "000000") setError("کد درست نیست. دوباره امتحان کنید.");
    else setStep("done");
  };

  const masked = phone ? `${fa(phone.slice(0, 4))}•••${fa(phone.slice(-4))}` : "";

  return (
    <Shell active="/login" bare>
      <div className="grid min-h-[calc(100dvh-4rem)] lg:grid-cols-2">
        <section className="flex items-center justify-center px-4 py-16 sm:px-6">
          <div className="w-full max-w-sm">
            {step === "phone" && (
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  if (valid) send();
                }}
              >
                <h1 className="text-3xl font-black">ورود یا ثبت‌نام</h1>
                <p className="mt-2 leading-7 text-muted-foreground">شماره‌ی موبایلتون را وارد کنید تا کد تأیید براتون پیامک بشه.</p>
                <label htmlFor="login-phone" className="mt-8 block text-sm font-medium">
                  شماره‌ی موبایل
                </label>
                <PhoneInput
                  id="login-phone"
                  className="mt-2"
                  value={phone}
                  autoFocus
                  onChange={(d, ok) => {
                    setPhone(d);
                    setValid(ok);
                  }}
                />
                <Button type="submit" size="lg" className="mt-6 w-full" disabled={!valid}>
                  دریافت کد تأیید
                </Button>
                <p className="mt-6 text-center text-xs leading-6 text-muted-foreground">
                  با ورود، <a href="#" className="underline underline-offset-4">قوانین</a> و <a href="#" className="underline underline-offset-4">حریم خصوصی</a> را می‌پذیرید.
                </p>
              </form>
            )}

            {step === "code" && (
              <div>
                <button type="button" onClick={() => setStep("phone")} className="mb-6 inline-flex cursor-pointer items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
                  <ArrowRight className="size-4" />
                  تغییر شماره
                </button>
                <h1 className="text-3xl font-black">کد تأیید</h1>
                <p className="mt-2 leading-7 text-muted-foreground">
                  کد ۶ رقمی به <span dir="ltr" className="font-semibold text-foreground">{masked}</span> فرستاده شد.
                </p>
                <OtpField className="mt-8" aria-label="کد تأیید" onComplete={verify} onChange={() => setError("")} />
                {error && (
                  <p role="alert" className="mt-3 text-sm text-destructive">
                    {error}
                  </p>
                )}
                <p className="mt-6 text-sm text-muted-foreground" aria-live="polite">
                  {left > 0 ? (
                    <>ارسال دوباره تا {fa(`${Math.floor(left / 60)}:${String(left % 60).padStart(2, "0")}`)}</>
                  ) : (
                    <button type="button" onClick={send} className="cursor-pointer font-semibold text-foreground underline underline-offset-4">
                      ارسال دوباره‌ی کد
                    </button>
                  )}
                </p>
              </div>
            )}

            {step === "done" && (
              <div className="text-center" role="status">
                <span className="mx-auto grid size-16 place-items-center rounded-full bg-success/15 text-success">
                  <Check className="size-8" />
                </span>
                <h1 className="mt-6 text-3xl font-black">خوش اومدید</h1>
                <p className="mt-2 leading-7 text-muted-foreground">در حال رفتن به داشبورد… ۱۴ روز رایگان شما از همین حالا شروع شد.</p>
              </div>
            )}
          </div>
        </section>

        <aside className="relative hidden overflow-hidden border-s border-border bg-card lg:block">
          <Photo name="login" alt="" eager className="absolute inset-0" />
          <div aria-hidden className="absolute inset-0 bg-gradient-to-t from-background via-background/40 to-transparent" />
          <div className="relative flex h-full flex-col justify-end p-12">
            <figure className="max-w-md">
              <blockquote className="text-xl font-bold leading-9">«اولین فاکتور رسمی را در کمتر از سه دقیقه صادر کردم.»</blockquote>
              <figcaption className="mt-5 flex items-center gap-3 text-sm">
                <Avatar name="الهام قاسمی" />
                <span>
                  <span className="block font-semibold">الهام قاسمی</span>
                  <span className="text-muted-foreground">طراح مستقل</span>
                </span>
              </figcaption>
            </figure>
          </div>
        </aside>
      </div>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Check, Minus } from "lucide-react";
import { SegmentedControl } from "@/components/ui/segmented-control";
import { Accordion } from "@/components/ui/accordion";
import { cn, faNumber } from "@/lib/utils";
import { PLANS, Shell, useHref, yearly } from "./shell";

type Cell = boolean | string;
const COMPARE: { group: string; rows: { t: string; v: [Cell, Cell, Cell] }[] }[] = [
  {
    group: "فروش",
    rows: [
      { t: "فاکتور رسمی", v: ["نامحدود", "نامحدود", "نامحدود"] },
      { t: "لینک پرداخت", v: [true, true, true] },
      { t: "یادآوری پیامکی سررسید", v: [false, true, true] },
    ],
  },
  {
    group: "مالیات و گزارش",
    rows: [
      { t: "ارسال به سامانه‌ی مودیان", v: [true, true, true] },
      { t: "گزارش فصلی ارزش افزوده", v: [true, true, true] },
      { t: "مرکز هزینه و پروژه", v: [false, false, true] },
    ],
  },
  {
    group: "تیم",
    rows: [
      { t: "تعداد کاربر", v: ["۱", "۵", "نامحدود"] },
      { t: "دسترسی نقش‌محور", v: [false, true, true] },
      { t: "چند شرکت و شعبه", v: [false, false, true] },
    ],
  },
];

const FAQ = [
  { id: "a", title: "بعد از ۱۴ روز چی میشه؟", content: "اگر پلنی انتخاب نکنید حسابتون فقط‌خواندنی میشه و هیچ اطلاعاتی پاک نمیشه." },
  { id: "b", title: "قیمت‌ها ارزش افزوده دارن؟", content: "قیمت‌های این صفحه بدون ارزش افزوده‌ی ۱۰ درصد هستن و فاکتور رسمی براتون صادر میشه." },
  { id: "c", title: "وسط دوره می‌تونم پلن را عوض کنم؟", content: "بله، مابه‌التفاوت روزشمار حساب میشه و همون لحظه امکانات جدید فعال میشن." },
];

function Value({ v }: { v: Cell }) {
  if (v === true) return <Check className="mx-auto size-4 text-brand" aria-label="دارد" />;
  if (v === false) return <Minus className="mx-auto size-4 text-muted-foreground/50" aria-label="ندارد" />;
  return <span>{v}</span>;
}

/** قیمت با تغییر ماهانه و سالانه و جدول مقایسه. */
export function PricingPage() {
  const href = useHref();
  const [cycle, setCycle] = React.useState("year");

  return (
    <Shell active="/pricing">
      <section className="mx-auto max-w-6xl px-4 pt-16 sm:px-6 sm:pt-24">
        <div className="mx-auto max-w-2xl text-center">
          <h1 className="text-4xl font-black sm:text-5xl">قیمت ساده، بدون هزینه‌ی پنهان</h1>
          <p className="mt-4 text-lg text-muted-foreground">۱۴ روز رایگان امتحان کنید، بعد پلنی که به کارتون میاد را انتخاب کنید.</p>
          <div className="mt-8 inline-flex items-center gap-3">
            <SegmentedControl
              aria-label="دوره‌ی پرداخت"
              value={cycle}
              onChange={setCycle}
              options={[
                { value: "month", label: "ماهانه" },
                { value: "year", label: "سالانه" },
              ]}
            />
            <span className="rounded-full bg-success/15 px-2.5 py-1 text-xs font-semibold text-success">دو ماه رایگان در سالانه</span>
          </div>
        </div>

        <div className="mt-14 grid gap-4 lg:grid-cols-3">
          {PLANS.map((p) => {
            const price = cycle === "year" ? yearly(p.monthly) : p.monthly;
            return (
              <article
                key={p.id}
                className={cn(
                  "relative flex flex-col rounded-3xl border p-7",
                  p.hot ? "border-brand bg-card shadow-[0_30px_60px_-30px_var(--brand)]" : "border-border",
                )}
              >
                {p.hot && <span className="absolute -top-3 start-7 rounded-full bg-brand px-3 py-1 text-xs font-semibold text-brand-foreground">محبوب‌ترین</span>}
                <h2 className="text-xl font-bold">{p.name}</h2>
                <p className="mt-1 text-sm text-muted-foreground">{p.desc}</p>
                <p className="mt-7 flex items-baseline gap-1.5">
                  <span className="text-4xl font-black tabular-nums">{faNumber(price)}</span>
                  <span className="text-sm text-muted-foreground">تومان {cycle === "year" ? "در سال" : "در ماه"}</span>
                </p>
                <p className="mt-1 h-5 text-xs text-success">{cycle === "year" ? `${faNumber(p.monthly * 2)} تومان صرفه‌جویی` : ""}</p>
                <a
                  href={href("/login")}
                  className={cn(
                    "mt-6 inline-flex h-11 items-center justify-center rounded-xl text-sm font-semibold transition-colors",
                    p.hot ? "bg-primary text-primary-foreground hover:bg-primary/90" : "border border-border hover:bg-secondary",
                  )}
                >
                  شروع ۱۴ روز رایگان
                </a>
                <ul className="mt-7 space-y-3 text-sm">
                  {p.items.map((it) => (
                    <li key={it} className="flex items-center gap-2.5">
                      <Check className="size-4 shrink-0 text-brand" />
                      {it}
                    </li>
                  ))}
                </ul>
              </article>
            );
          })}
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 py-24 sm:px-6">
        <h2 className="text-2xl font-black">مقایسه‌ی کامل پلن‌ها</h2>
        <div className="mt-8 overflow-x-auto rounded-2xl border border-border">
          <table className="w-full min-w-[40rem] text-sm">
            <thead>
              <tr className="border-b border-border bg-card/60">
                <th scope="col" className="px-5 py-4 text-start font-medium text-muted-foreground">
                  امکانات
                </th>
                {PLANS.map((p) => (
                  <th key={p.id} scope="col" className={cn("px-5 py-4 text-center font-bold", p.hot && "text-brand")}>
                    {p.name}
                  </th>
                ))}
              </tr>
            </thead>
            {COMPARE.map((g) => (
              <tbody key={g.group}>
                <tr>
                  <th colSpan={4} scope="colgroup" className="bg-secondary/40 px-5 py-2 text-start text-xs font-semibold text-muted-foreground">
                    {g.group}
                  </th>
                </tr>
                {g.rows.map((r) => (
                  <tr key={r.t} className="border-t border-border">
                    <th scope="row" className="px-5 py-3.5 text-start font-normal">
                      {r.t}
                    </th>
                    {r.v.map((v, i) => (
                      <td key={i} className="px-5 py-3.5 text-center">
                        <Value v={v} />
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            ))}
          </table>
        </div>
      </section>

      <section className="mx-auto max-w-3xl px-4 pb-24 sm:px-6">
        <h2 className="mb-6 text-2xl font-black">سؤال‌های پرداخت</h2>
        <Accordion items={FAQ} />
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Menu, ShieldCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

const BaseContext = React.createContext("");

/** Mounts the site under a path prefix, e.g. the docs preview at /preview/site/saas-site. Your app doesn't need it. */
export function SiteBase({ base, children }: { base: string; children: React.ReactNode }) {
  return <BaseContext value={base}>{children}</BaseContext>;
}

/** Internal links: href("/pricing") is "/pricing" in your app and gets the base prefix inside the preview. */
export function useHref() {
  const base = React.useContext(BaseContext);
  return React.useCallback((to: string) => (to === "/" ? base || "/" : `${base}${to}`), [base]);
}

/** Photos ship in public/sites/saas-site/. Replace the files with your own and keep the names, or change them here. */
export function Photo({ name, alt, className, eager }: { name: string; alt: string; className?: string; eager?: boolean }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- a plain <img> keeps the site framework-agnostic
    <img src={`/sites/saas-site/${name}.webp`} alt={alt} loading={eager ? "eager" : "lazy"} decoding="async" className={cn("block size-full object-cover", className)} />
  );
}

export const NAV = [
  { href: "/features", label: "امکانات" },
  { href: "/pricing", label: "قیمت" },
  { href: "/blog", label: "وبلاگ" },
];

export type Plan = { id: string; name: string; desc: string; monthly: number; items: string[]; hot?: boolean };

