            {[
              { t: "محصول", l: [["امکانات", "/features"], ["قیمت", "/pricing"], ["ورود", "/login"]] },
              { t: "منابع", l: [["وبلاگ", "/blog"], ["راهنمای مودیان", "/blog"], ["وبینارها", "/blog"]] },
