"use client";

import * as React from "react";
import { ShoppingBag, Trash2, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { NumberField } from "@/components/ui/number-field";
import { Progress } from "@/components/ui/progress";
import { faNumber } from "@/lib/utils";
import { Bag, FREE_SHIPPING, GRINDS, PRODUCTS, Shell, WEIGHTS, unitPrice, useCart, useHref } from "./shell";

const SHIPPING = 85_000;
const CODES: Record<string, number> = { RAST10: 0.1 };

/** سبد خرید با تعداد، ارسال رایگان، کد تخفیف و خلاصه‌ی سفارش. */
export function CartPage() {
  const href = useHref();
  const { lines, setQty, remove, clear } = useCart();
  const [code, setCode] = React.useState("");
  const [applied, setApplied] = React.useState<string | null>(null);
  const [codeError, setCodeError] = React.useState("");
  const [placed, setPlaced] = React.useState(false);

  const rows = lines
    .map((l) => {
      const p = PRODUCTS.find((x) => x.id === l.id);
      return p ? { line: l, product: p, unit: unitPrice(p, l.weight) } : null;
    })
    .filter((r) => r !== null);

  const subtotal = rows.reduce((n, r) => n + r.unit * r.line.qty, 0);
  const discount = applied ? Math.round((subtotal * CODES[applied]) / 1000) * 1000 : 0;
  const shipping = subtotal - discount >= FREE_SHIPPING || subtotal === 0 ? 0 : SHIPPING;
  const total = subtotal - discount + shipping;
  const toFree = Math.max(0, FREE_SHIPPING - (subtotal - discount));

  function apply(e: React.FormEvent) {
    e.preventDefault();
    const c = code.trim().toUpperCase();
    if (CODES[c]) {
      setApplied(c);
      setCodeError("");
    } else {
      setCodeError("این کد معتبر نیست.");
    }
  }

  if (placed) {
    return (
      <Shell active="/cart">
        <section className="mx-auto max-w-lg px-4 py-24 text-center" role="status">
          <h1 className="text-3xl font-black">سفارشتون ثبت شد</h1>
          <p className="mt-3 leading-8 text-muted-foreground">کد پیگیری و لینک پرداخت براتون پیامک شد. قهوه‌ها در برشته‌کاری بعدی آماده میشن.</p>
          <a href={href("/shop")} className="mt-8 inline-flex h-12 items-center rounded-full bg-foreground px-7 text-sm font-semibold text-background">
            برگشت به فروشگاه
          </a>
        </section>
      </Shell>
    );
  }

  return (
    <Shell active="/cart">
      <section className="mx-auto max-w-6xl px-4 pt-12 pb-16 sm:px-6">
        <h1 className="text-4xl font-black">سبد خرید</h1>

        {rows.length === 0 ? (
          <div className="mt-10 flex flex-col items-center rounded-3xl border border-dashed border-border py-20 text-center">
            <ShoppingBag className="size-9 text-muted-foreground" />
            <p className="mt-4 text-lg font-bold">سبدتون خالیه</p>
            <p className="mt-1 text-sm text-muted-foreground">یک قهوه انتخاب کنید، بقیه‌اش با ما.</p>
            <a href={href("/shop")} className="mt-6 inline-flex h-11 items-center rounded-full bg-foreground px-6 text-sm font-semibold text-background">
              رفتن به فروشگاه
            </a>
          </div>
        ) : (
          <div className="mt-10 grid gap-10 lg:grid-cols-[1fr_22rem]">
            <div>
              <div className="rounded-2xl border border-border p-4">
                <p className="flex items-center gap-2 text-sm">
                  <Truck className="size-4 text-brand" />
                  {toFree > 0 ? <>فقط {faNumber(toFree)} تومان تا ارسال رایگان مونده</> : <>ارسالتون رایگان شد</>}
                </p>
                <Progress value={Math.min(100, ((subtotal - discount) / FREE_SHIPPING) * 100)} className="mt-3" />
              </div>
              <ul className="mt-6 divide-y divide-border border-y border-border">
                {rows.map(({ line, product, unit }) => (
                  <li key={`${line.id}-${line.weight}-${line.grind}`} className="flex gap-4 py-5">
                    <div className="grid w-24 shrink-0 place-items-center rounded-2xl bg-secondary/60 p-3 sm:w-28">
                      <Bag product={product} className="w-3/4" />
                    </div>
                    <div className="flex min-w-0 flex-1 flex-col">
                      <div className="flex items-start justify-between gap-3">
                        <div>
                          <a href={href("/product")} className="font-bold hover:underline">
                            {product.name}
                          </a>
                          <p className="mt-1 text-xs text-muted-foreground">
                            {WEIGHTS.find((w) => w.value === line.weight)?.label} · آسیاب {GRINDS.find((g) => g.value === line.grind)?.label}
                          </p>
                        </div>
                        <button type="button" onClick={() => remove(line)} aria-label={`حذف ${product.name}`} className="grid size-9 cursor-pointer place-items-center rounded-full text-muted-foreground hover:bg-secondary hover:text-destructive">
                          <Trash2 className="size-4" />
                        </button>
                      </div>
                      <div className="mt-auto flex items-end justify-between gap-3 pt-3">
                        <NumberField aria-label="تعداد" value={line.qty} onChange={(q) => setQty(line, q)} min={1} max={10} />
                        <p className="font-bold tabular-nums">
                          {faNumber(unit * line.qty)} <span className="text-xs font-normal text-muted-foreground">تومان</span>
                        </p>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
              <button type="button" onClick={clear} className="mt-4 cursor-pointer text-sm text-muted-foreground underline underline-offset-4 hover:text-foreground">
                خالی کردن سبد
              </button>
            </div>

            <aside className="h-fit rounded-3xl border border-border bg-card p-6 lg:sticky lg:top-24">
              <h2 className="font-bold">خلاصه‌ی سفارش</h2>
              <form onSubmit={apply} className="mt-5 flex gap-2">
                <Input value={code} onChange={(e) => setCode(e.target.value)} placeholder="کد تخفیف" aria-label="کد تخفیف" dir="ltr" className="uppercase" />
                <Button type="submit" variant="secondary">
                  اعمال
                </Button>
              </form>
              {codeError && <p className="mt-2 text-xs text-destructive">{codeError}</p>}
              {!applied && !codeError && <p className="mt-2 text-xs text-muted-foreground">برای امتحان: RAST10</p>}
              <dl className="mt-6 space-y-3 text-sm">
                <div className="flex justify-between">
                  <dt className="text-muted-foreground">جمع کالاها</dt>
                  <dd className="tabular-nums">{faNumber(subtotal)} تومان</dd>
                </div>
                {discount > 0 && (
                  <div className="flex justify-between text-success">
                    <dt>تخفیف {applied}</dt>
                    <dd className="tabular-nums">−{faNumber(discount)} تومان</dd>
                  </div>
                )}
                <div className="flex justify-between">
                  <dt className="text-muted-foreground">ارسال</dt>
                  <dd className="tabular-nums">{shipping ? `${faNumber(shipping)} تومان` : "رایگان"}</dd>
                </div>
                <div className="flex justify-between border-t border-border pt-3 text-base font-bold">
                  <dt>قابل پرداخت</dt>
                  <dd className="tabular-nums">{faNumber(total)} تومان</dd>
                </div>
              </dl>
              <Button size="lg" className="mt-6 w-full rounded-full" onClick={() => { clear(); setPlaced(true); }}>
                ادامه و پرداخت
              </Button>
            </aside>
          </div>
        )}
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Check, Mountain, Package, Sprout, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Price } from "@/components/ui/price";
import { Rating } from "@/components/ui/rating";
import { SegmentedControl } from "@/components/ui/segmented-control";
import { RadioGroup } from "@/components/ui/radio-group";
import { NumberField } from "@/components/ui/number-field";
import { cn, fa, faNumber } from "@/lib/utils";
import { Bag, GRINDS, PRODUCTS, Photo, ProductCard, Shell, WEIGHTS, faDecimal, unitPrice, useCart, useHref } from "./shell";

// A single product page. In a real shop, move it to app/product/[id]/page.tsx and look the product up by id.
const PRODUCT = PRODUCTS[0];

const SPECS = [
  { i: Mountain, l: "ارتفاع", v: "۱۹۰۰ تا ۲۲۰۰ متر" },
  { i: Sprout, l: "واریته", v: "هیرلوم اتیوپی" },
  { i: Package, l: "فرآوری", v: "شسته" },
];

/** صفحه‌ی محصول با وزن، آسیاب، تعداد و افزودن به سبد. */
export function ProductPage() {
  const href = useHref();
  const [weight, setWeight] = React.useState("250");
  const [grind, setGrind] = React.useState("bean");
  const [qty, setQty] = React.useState(1);
  const [view, setView] = React.useState(0);
  const [added, setAdded] = React.useState(false);
  const { add } = useCart();

  const price = unitPrice(PRODUCT, weight);
  // Gallery: the packshot photo, the drawn bag in another colourway, and a brewing photo.
  const shot = (i: number, thumb?: boolean) =>
    i === 0 ? (
      <Photo name="product" alt={thumb ? "" : `بسته‌ی ${PRODUCT.name}`} eager={!thumb} />
    ) : i === 1 ? (
      <div className="grid size-full place-items-center">
        <Bag product={{ ...PRODUCT, tone: 2 }} className={thumb ? "w-1/3" : "w-1/2"} />
      </div>
    ) : (
      <Photo name="pour" alt={thumb ? "" : "دم کردن با قهوه‌ساز دمی"} />
    );

  return (
    <Shell active="/product">
      <nav aria-label="مسیر" className="mx-auto max-w-6xl px-4 pt-8 text-sm text-muted-foreground sm:px-6">
        <a href={href("/")} className="hover:text-foreground">
          خانه
        </a>
        <span className="mx-2">/</span>
        <a href={href("/shop")} className="hover:text-foreground">
          فروشگاه
        </a>
        <span className="mx-2">/</span>
        <span className="text-foreground">{PRODUCT.name}</span>
      </nav>

      <section className="mx-auto grid max-w-6xl gap-10 px-4 py-8 sm:px-6 lg:grid-cols-2 lg:gap-16">
        <div>
          <div className="relative grid aspect-square place-items-center overflow-hidden rounded-[2rem] bg-secondary/60">
            <div aria-hidden className="absolute size-3/4 rounded-full bg-brand/15 blur-2xl" />
            <div className="absolute inset-0">{shot(view)}</div>
          </div>
          <div className="mt-3 grid grid-cols-3 gap-3">
            {[0, 1, 2].map((i) => (
              <button
                key={i}
                type="button"
                aria-label={`نمای ${fa(i + 1)}`}
                aria-pressed={view === i}
                onClick={() => setView(i)}
                className={cn("relative aspect-[4/3] cursor-pointer overflow-hidden rounded-2xl bg-secondary/60 transition", view === i ? "ring-2 ring-foreground" : "opacity-70 hover:opacity-100")}
              >
                <span className="absolute inset-0">{shot(i, true)}</span>
              </button>
            ))}
          </div>
        </div>

        <div>
          <p className="text-sm text-muted-foreground">{PRODUCT.origin}</p>
          <h1 className="mt-2 text-4xl font-black">{PRODUCT.name}</h1>
          <div className="mt-3 flex items-center gap-2 text-sm">
            <Rating value={PRODUCT.rating} readOnly size="sm" />
            <span className="font-semibold">{faDecimal(PRODUCT.rating)}</span>
            <span className="text-muted-foreground">({faNumber(PRODUCT.reviews)} نظر)</span>
          </div>
          <div className="mt-5 flex flex-wrap gap-2">
            {PRODUCT.notes.map((n) => (
              <span key={n} className="rounded-full bg-brand/15 px-3 py-1 text-sm">
                {n}
              </span>
            ))}
          </div>
          <p className="mt-6 leading-8 text-muted-foreground">
            قهوه‌ای روشن و گلی از منطقه‌ی گدئو. برای دمی و فرانسه عالیه و اگر اسپرسوی میوه‌ای دوست دارید، روی دستگاه هم خوش‌طعمه.
          </p>

          <div className="mt-8 space-y-6 border-t border-border pt-8">
            <div>
              <p className="mb-2 text-sm font-medium">وزن</p>
              <SegmentedControl aria-label="وزن" options={WEIGHTS.map(({ value, label }) => ({ value, label }))} value={weight} onChange={(v) => { setWeight(v); setAdded(false); }} fullWidth />
            </div>
            <div>
              <p className="mb-2 text-sm font-medium">آسیاب</p>
              <RadioGroup name="grind" variant="cards" options={GRINDS} value={grind} onChange={(v) => { setGrind(v); setAdded(false); }} />
            </div>
            <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-secondary/50 p-4">
              <Price amount={price * qty} size="md" />
              <div className="flex items-center gap-3">
                <NumberField aria-label="تعداد" value={qty} onChange={(v) => { setQty(v); setAdded(false); }} min={1} max={10} />
                <Button
                  size="lg"
                  onClick={() => {
                    add({ id: PRODUCT.id, weight, grind, qty });
                    setAdded(true);
                  }}
                  className={cn("min-w-36 rounded-full", added && "bg-success text-background hover:bg-success")}
                >
                  {added ? (
                    <>
                      <Check />
                      در سبد
                    </>
                  ) : (
                    "افزودن به سبد"
                  )}
                </Button>
              </div>
            </div>
            {added && (
              <p role="status" className="text-sm">
                به سبد اضافه شد.{" "}
                <a href={href("/cart")} className="font-semibold underline underline-offset-4">
                  دیدن سبد
                </a>
              </p>
            )}
            <p className="flex items-center gap-2 text-sm text-muted-foreground">
              <Truck className="size-4" />
              سفارش تا ساعت ۱۴ امروز، همین امروز ارسال میشه.
            </p>
          </div>

          <dl className="mt-8 grid grid-cols-3 gap-3">
            {SPECS.map((s) => (
              <div key={s.l} className="rounded-2xl border border-border p-4">
                <s.i className="size-4 text-brand" />
                <dt className="mt-3 text-xs text-muted-foreground">{s.l}</dt>
                <dd className="mt-0.5 text-sm font-semibold">{s.v}</dd>
              </div>
            ))}
          </dl>
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 py-16 sm:px-6">
        <h2 className="mb-8 text-2xl font-black">شاید اینا را هم دوست داشته باشید</h2>
        <ul className="grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-4">
          {PRODUCTS.slice(1, 5).map((p) => (
            <li key={p.id}>
              <ProductCard product={p} />
            </li>
          ))}
        </ul>
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Check, Menu, Plus, ShoppingBag, Star, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet } from "@/components/ui/sheet";
import { Price } from "@/components/ui/price";
import { cn, fa } from "@/lib/utils";

const BaseContext = React.createContext("");

/** Mounts the site under a path prefix, e.g. the docs preview at /preview/site/shop-site. Your app doesn't need it. */
export function SiteBase({ base, children }: { base: string; children: React.ReactNode }) {
  return <BaseContext value={base}>{children}</BaseContext>;
}

/** Internal links: href("/shop") is "/shop" in your app and gets the base prefix inside the preview. */
export function useHref() {
  const base = React.useContext(BaseContext);
  return React.useCallback((to: string) => (to === "/" ? base || "/" : `${base}${to}`), [base]);
}

/** Photos ship in public/sites/shop-site/. Replace the files with your own and keep the names, or change them here. */
export function Photo({ name, alt, className, eager }: { name: string; alt: string; className?: string; eager?: boolean }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- a plain <img> keeps the site framework-agnostic
    <img src={`/sites/shop-site/${name}.webp`} alt={alt} loading={eager ? "eager" : "lazy"} decoding="async" className={cn("block size-full object-cover", className)} />
  );
}

export const NAV = [
  { href: "/shop", label: "فروشگاه" },
  { href: "/product", label: "پیشنهاد این هفته" },
  { href: "/about", label: "داستان ما" },
];

export type Roast = "روشن" | "متوسط" | "تیره";
export type Cat = "تک‌خاستگاه" | "ترکیبی" | "دمی";

export type Product = {
  id: string;
  name: string;
  origin: string;
  cat: Cat;
  roast: Roast;
  notes: string[];
  /** Price of a 250g bag in toman. */
  price: number;
  original?: number;
  rating: number;
  reviews: number;
  tone: number;
};

export const PRODUCTS: Product[] = [
  { id: "yirgacheffe", name: "اتیوپی یرگاچف", origin: "اتیوپی · ۲۰۰۰ متر", cat: "تک‌خاستگاه", roast: "روشن", notes: ["یاس", "لیمو", "چای سیاه"], price: 890_000, rating: 4.9, reviews: 214, tone: 0 },
