/** Header, mobile menu and patterned footer shared by every page. */
export function Shell({ active, children, overlay }: { active: string; children: React.ReactNode; overlay?: boolean }) {
  const href = useHref();
  const [open, setOpen] = React.useState(false);

  return (
    <div className="min-h-dvh bg-background text-foreground">
      <header className={cn("z-40 w-full", overlay ? "absolute inset-x-0 top-0" : "sticky top-0 border-b border-border bg-background/85 backdrop-blur")}>
        <nav aria-label="اصلی" className="mx-auto flex h-20 max-w-6xl items-center justify-between gap-6 px-4 sm:px-6">
          <a href={href("/")} aria-label="رستوران نارنج، خانه">
            <Logo />
          </a>
          <ul className="hidden items-center gap-8 md:flex">
            {NAV.map((l) => (
              <li key={l.href}>
                <a
                  href={href(l.href)}
                  aria-current={active === l.href ? "page" : undefined}
                  className={cn("text-sm transition-colors hover:text-brand", active === l.href ? "font-bold text-brand" : "text-foreground/80")}
                >
                  {l.label}
                </a>
              </li>
            ))}
          </ul>
          <div className="flex items-center gap-2">
            <a href={href("/reserve")} className="inline-flex h-11 items-center rounded-full border border-brand px-5 text-sm font-semibold text-brand transition-colors hover:bg-brand hover:text-brand-foreground">
              رزرو میز
            </a>
            <Button variant="ghost" size="icon" className="md:hidden" aria-label="باز کردن منو" onClick={() => setOpen(true)}>
              <Menu />
            </Button>
          </div>
        </nav>
      </header>
      <Sheet open={open} onOpenChange={setOpen} title={<Logo />}>
        <ul className="flex flex-col p-2">
          {[{ href: "/", label: "خانه" }, ...NAV, { href: "/reserve", label: "رزرو میز" }].map((l) => (
            <li key={l.href}>
              <a href={href(l.href)} onClick={() => setOpen(false)} className="block rounded-lg px-3 py-3 text-base hover:bg-accent">
                {l.label}
              </a>
            </li>
          ))}
        </ul>
      </Sheet>

      <main>{children}</main>

      <footer className="relative isolate mt-10 overflow-hidden border-t border-border">
        <GirihBackground size={48} className="-z-10 opacity-60" />
        <div className="mx-auto grid max-w-6xl gap-10 px-4 py-16 sm:px-6 md:grid-cols-3">
          <div className="space-y-3">
            <Logo />
            <p className="text-sm leading-7 text-muted-foreground">آشپزی خانگی شیرازی از ۱۳۷۸. همه‌چیز همون روز پخته میشه.</p>
          </div>
          <div className="space-y-2 text-sm">
            <p className="font-semibold">ساعت سرو</p>
            <p className="text-muted-foreground">ناهار ۱۲ تا ۱۶</p>
            <p className="text-muted-foreground">شام ۱۹ تا ۲۴</p>
          </div>
          <div className="space-y-2 text-sm">
            <p className="font-semibold">شعبه‌ها</p>
            {BRANCHES.map((b) => (
              <a key={b.name} href={href("/contact")} className="block text-muted-foreground hover:text-foreground">
                {b.name}، {b.city}
              </a>
            ))}
          </div>
        </div>
        <p className="border-t border-border py-5 text-center text-xs text-muted-foreground">© ۱۴۰۵ رستوران نارنج</p>
      </footer>
    </div>
  );
}

"use client";

import * as React from "react";
import { AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DateRangePicker, formatJalaliRange, rangeLength, type DateRange } from "@/components/ui/date-range-picker";
import { NumberField } from "@/components/ui/number-field";
import { RadioGroup } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { PhoneInput } from "@/components/ui/phone-input";
import { Field, Input } from "@/components/ui/input";
import { SuccessCheck } from "@/components/animations/success-check";
import { fa, faNumber } from "@/lib/utils";
import { Photo, ROOMS, Shell, useHref } from "./shell";

const DINNER = 450_000;
const TRANSFER = 1_200_000;
const TAX = 0.1;

const noop = () => () => {};

/** The home hero hands over ?from=&to=&guests= so the guest doesn't pick them twice. */
function useHandoff() {
  const search = React.useSyncExternalStore(noop, () => window.location.search, () => "");
  return React.useMemo(() => {
    const q = new URLSearchParams(search);
    const date = (k: string) => (q.get(k) ? new Date(Number(q.get(k))) : null);
    return { range: { from: date("from"), to: date("to") } as DateRange, guests: Number(q.get("guests")) || 2 };
  }, [search]);
}

/** رزرو با بازه‌ی تاریخ شمسی، تعداد مهمان، انتخاب اتاق و محاسبه‌ی هزینه. */
export function BookPage() {
  const href = useHref();
  const handoff = useHandoff();
  const [rangeState, setRange] = React.useState<DateRange | null>(null);
  const [adultsState, setAdults] = React.useState<number | null>(null);
  const [kids, setKids] = React.useState(0);
  const [room, setRoom] = React.useState(ROOMS[0].id);
  const [dinner, setDinner] = React.useState(false);
  const [transfer, setTransfer] = React.useState(false);
  const [name, setName] = React.useState("");
  const [phoneOk, setPhoneOk] = React.useState(false);
  const [done, setDone] = React.useState(false);

  const range = rangeState ?? handoff.range;
  const adults = adultsState ?? handoff.guests;
  const r = ROOMS.find((x) => x.id === room)!;
  const nights = Math.max(0, rangeLength(range) - 1);
  const guests = adults + kids;
  const tooMany = guests > r.guests;

  const roomTotal = r.price * nights;
  const dinnerTotal = dinner ? DINNER * guests * nights : 0;
  const transferTotal = transfer ? TRANSFER : 0;
  const tax = Math.round(((roomTotal + dinnerTotal + transferTotal) * TAX) / 1000) * 1000;
  const total = roomTotal + dinnerTotal + transferTotal + tax;
  const ready = nights > 0 && !tooMany && name.trim().length > 1 && phoneOk;

  if (done) {
    return (
      <Shell active="/book">
        <section className="mx-auto max-w-md px-4 py-20 text-center" role="status">
          <SuccessCheck className="mx-auto" />
          <h1 className="mt-6 text-3xl font-black">درخواست رزروتون ثبت شد</h1>
          <p className="mt-3 leading-8 text-muted-foreground">
            {r.name}، {formatJalaliRange(range)}، {fa(nights)} شب برای {fa(guests)} نفر. تا یک ساعت دیگه برای تأیید و پرداخت بیعانه باهاتون تماس می‌گیریم.
          </p>
          <a href={href("/experiences")} className="mt-8 inline-flex h-11 items-center rounded-full border border-border px-6 text-sm font-semibold hover:bg-secondary">
            تجربه‌ها را ببینید
          </a>
        </section>
      </Shell>
    );
  }

  return (
    <Shell active="/book">
      <section className="mx-auto max-w-6xl px-4 pt-12 pb-20 sm:px-6">
        <h1 className="text-4xl font-black">رزرو اقامت</h1>
        <p className="mt-3 text-muted-foreground">اول تاریخ را انتخاب کنید تا هزینه‌ی دقیق را ببینید. پرداخت بعد از تأیید تلفنی انجام میشه.</p>

        <div className="mt-10 grid gap-8 lg:grid-cols-[1fr_22rem]">
          <form
            className="space-y-10"
            onSubmit={(e) => {
              e.preventDefault();
              if (ready) setDone(true);
            }}
          >
            <fieldset className="grid gap-5 sm:grid-cols-3">
              <legend className="mb-4 text-lg font-bold">تاریخ و مهمان‌ها</legend>
              <Field label="ورود و خروج" className="sm:col-span-3">
                <DateRangePicker value={range} onChange={setRange} min={new Date()} presets={[]} placeholder="تاریخ ورود و خروج" />
              </Field>
              <Field label="بزرگسال">
                <NumberField aria-label="بزرگسال" value={adults} onChange={setAdults} min={1} max={8} />
              </Field>
              <Field label="کودک (زیر ۱۲ سال)">
                <NumberField aria-label="کودک" value={kids} onChange={setKids} min={0} max={6} />
              </Field>
            </fieldset>

            <fieldset>
              <legend className="mb-4 text-lg font-bold">اتاق</legend>
              <RadioGroup
                name="room"
                variant="cards"
                value={room}
                onChange={setRoom}
                options={ROOMS.map((x) => ({
                  value: x.id,
                  label: x.name,
                  description: `تا ${fa(x.guests)} نفر · ${fa(x.meters)} متر · ${faNumber(x.price)} تومان هر شب`,
                  disabled: guests > x.guests,
                }))}
              />
              {tooMany && (
                <p role="alert" className="mt-3 flex items-center gap-2 text-sm text-warning">
                  <AlertTriangle className="size-4" />
                  ظرفیت {r.name} {fa(r.guests)} نفره. یک اتاق بزرگ‌تر انتخاب کنید.
                </p>
              )}
            </fieldset>

            <fieldset className="space-y-3">
              <legend className="mb-4 text-lg font-bold">خدمات اضافه</legend>
              <Checkbox checked={dinner} onCheckedChange={setDinner} label="شام محلی هر شب" description={`${faNumber(DINNER)} تومان برای هر نفر`} />
              <Checkbox checked={transfer} onCheckedChange={setTransfer} label="ترانسفر از ترمینال خور" description={`${faNumber(TRANSFER)} تومان، رفت و برگشت`} />
            </fieldset>

            <fieldset className="grid gap-5 sm:grid-cols-2">
              <legend className="mb-4 text-lg font-bold">مشخصات رزروکننده</legend>
              <Field label="اسم و نام خانوادگی" htmlFor="bk-name">
                <Input id="bk-name" value={name} onChange={(e) => setName(e.target.value)} autoComplete="name" />
              </Field>
              <Field label="شماره‌ی موبایل" htmlFor="bk-phone">
                <PhoneInput id="bk-phone" onChange={(_, ok) => setPhoneOk(ok)} />
              </Field>
            </fieldset>

            <div className="lg:hidden">
              <Button type="submit" size="lg" disabled={!ready} className="w-full rounded-full">
                ثبت درخواست رزرو
              </Button>
            </div>
          </form>

          <aside className="h-fit overflow-hidden rounded-[2rem] border border-border bg-card lg:sticky lg:top-28">
            <div className="aspect-[16/9]">
              <Photo name={r.photo} alt={r.name} />
            </div>
            <div className="p-6">
              <h2 className="font-bold">خلاصه‌ی هزینه</h2>
              <p className="mt-1 text-sm text-muted-foreground">{range.from ? formatJalaliRange(range) : "تاریخ هنوز انتخاب نشده"}</p>
              <dl className="mt-6 space-y-3 text-sm">
                <div className="flex justify-between gap-3">
                  <dt className="text-muted-foreground">
                    {r.name} × {fa(nights)} شب
                  </dt>
                  <dd className="tabular-nums">{faNumber(roomTotal)}</dd>
                </div>
                {dinner && (
                  <div className="flex justify-between gap-3">
                    <dt className="text-muted-foreground">
                      شام × {fa(guests)} نفر × {fa(nights)} شب
                    </dt>
                    <dd className="tabular-nums">{faNumber(dinnerTotal)}</dd>
                  </div>
                )}
                {transfer && (
                  <div className="flex justify-between gap-3">
                    <dt className="text-muted-foreground">ترانسفر</dt>
                    <dd className="tabular-nums">{faNumber(transferTotal)}</dd>
                  </div>
                )}
                <div className="flex justify-between gap-3">
                  <dt className="text-muted-foreground">ارزش افزوده ({fa(10)}٪)</dt>
                  <dd className="tabular-nums">{faNumber(tax)}</dd>
                </div>
                <div className="flex justify-between gap-3 border-t border-border pt-3 text-base font-bold">
                  <dt>جمع کل</dt>
                  <dd className="tabular-nums">{faNumber(total)} تومان</dd>
                </div>
              </dl>
              <p className="mt-4 rounded-xl bg-secondary/60 p-3 text-xs leading-6 text-muted-foreground">بیعانه ۳۰٪ جمع کل ({faNumber(Math.round(total * 0.3 / 1000) * 1000)} تومان) بعد از تأیید تلفنی گرفته میشه.</p>
              <div className="mt-5 hidden lg:block">
                <Button type="button" size="lg" disabled={!ready} onClick={() => setDone(true)} className="w-full rounded-full">
                  ثبت درخواست رزرو
                </Button>
              </div>
            </div>
          </aside>
        </div>
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Clock, Gauge, Users } from "lucide-react";
import { Reveal } from "@/components/animations/reveal";
import { cn, faNumber } from "@/lib/utils";
import { EXPERIENCES, Photo, Shell, useHref } from "./shell";

const LEVELS = ["همه", "آسان", "متوسط", "سخت"] as const;
const LEVEL_STYLE: Record<string, string> = { آسان: "text-success", متوسط: "text-warning", سخت: "text-destructive" };

/** تجربه‌ها و تورها با فیلتر سختی. */
export function ExperiencesPage() {
  const href = useHref();
  const [level, setLevel] = React.useState<(typeof LEVELS)[number]>("همه");
  const list = level === "همه" ? EXPERIENCES : EXPERIENCES.filter((x) => x.level === level);

  return (
    <Shell active="/experiences">
      <section className="relative isolate overflow-hidden border-b border-border">
        <Photo name="stars" alt="" eager className="absolute inset-0 -z-20" />
        <div aria-hidden className="absolute inset-0 -z-10 bg-gradient-to-t from-background via-background/60 to-background/20" />
        <div className="mx-auto max-w-6xl px-4 pt-24 pb-28 sm:px-6">
          <h1 className="text-4xl font-black sm:text-6xl">تجربه‌ها</h1>
          <p className="mt-4 max-w-xl text-lg leading-8 text-foreground/75">کویر را فقط از پشت پنجره نبینید. همه‌ی تورها با راهنمای محلی و از خود اقامتگاه شروع میشن.</p>
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 py-12 sm:px-6">
        <div role="group" aria-label="سختی" className="flex flex-wrap gap-2">
          {LEVELS.map((l) => (
            <button
              key={l}
              type="button"
              aria-pressed={level === l}
              onClick={() => setLevel(l)}
              className={cn(
                "h-10 cursor-pointer rounded-full border px-5 text-sm transition-colors",
                level === l ? "border-foreground bg-foreground text-background" : "border-border text-muted-foreground hover:text-foreground",
              )}
            >
              {l}
            </button>
          ))}
        </div>

        <ul className="mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {list.map((x, i) => (
            <li key={x.id}>
              <Reveal delay={(i % 3) * 70} className="h-full">
                <article className="flex h-full flex-col overflow-hidden rounded-[2rem] border border-border">
                  <div className="h-48 overflow-hidden">
                    <Photo name={x.photo} alt={x.title} className="transition-transform duration-700 hover:scale-[1.04]" />
                  </div>
                  <div className="flex flex-1 flex-col p-6">
                    <h2 className="text-lg font-bold">{x.title}</h2>
                    <p className="mt-2 flex-1 text-sm leading-7 text-muted-foreground">{x.desc}</p>
                    <ul className="mt-4 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
                      <li className="flex items-center gap-1">
                        <Clock className="size-3.5" />
                        {x.hours}
                      </li>
                      <li className="flex items-center gap-1">
                        <Users className="size-3.5" />
                        {x.group}
                      </li>
                      <li className={cn("flex items-center gap-1", LEVEL_STYLE[x.level])}>
                        <Gauge className="size-3.5" />
                        {x.level}
                      </li>
                    </ul>
                    <div className="mt-5 flex items-center justify-between border-t border-border pt-4">
                      <p className="text-sm">
                        <span className="font-bold">{faNumber(x.price)}</span> <span className="text-muted-foreground">تومان هر نفر</span>
                      </p>
                      <a href={href("/book")} className="text-sm font-semibold text-brand">
                        اضافه به رزرو
                      </a>
                    </div>
                  </div>
                </article>
              </Reveal>
            </li>
          ))}
        </ul>
      </section>
    </Shell>
  );
}

"use client";

import * as React from "react";
import { Menu } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

const BaseContext = React.createContext("");

/** Mounts the site under a path prefix, e.g. the docs preview at /preview/site/lodge-site. Your app doesn't need it. */
export function SiteBase({ base, children }: { base: string; children: React.ReactNode }) {
  return <BaseContext value={base}>{children}</BaseContext>;
}

/** Internal links: href("/rooms") is "/rooms" in your app and gets the base prefix inside the preview. */
export function useHref() {
  const base = React.useContext(BaseContext);
  return React.useCallback((to: string) => (to === "/" ? base || "/" : `${base}${to}`), [base]);
}

/** Photos ship in public/sites/lodge-site/. Replace the files with your own and keep the names, or change them here. */
export function Photo({ name, alt, className, eager }: { name: string; alt: string; className?: string; eager?: boolean }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- a plain <img> keeps the site framework-agnostic
    <img src={`/sites/lodge-site/${name}.webp`} alt={alt} loading={eager ? "eager" : "lazy"} decoding="async" className={cn("block size-full object-cover", className)} />
  );
}

export const NAV = [
  { href: "/rooms", label: "اتاق‌ها" },
  { href: "/experiences", label: "تجربه‌ها" },
  { href: "/about", label: "درباره‌ی ما" },
];

export type Room = { id: string; photo: string; name: string; desc: string; guests: number; meters: number; beds: string; price: number; amenities: string[]; tone: number };

export const ROOMS: Room[] = [
  { id: "shah-neshin", photo: "room-shah", name: "اتاق شاه‌نشین", desc: "بزرگ‌ترین اتاق خونه با پنجره‌های ارسی و سقف گنبدی.", guests: 4, meters: 42, beds: "یک تخت دونفره و دو رختخواب سنتی", price: 4_800_000, amenities: ["حمام اختصاصی", "کرسی زمستونی", "صبحانه‌ی محلی", "چشم‌انداز حیاط"], tone: 0 },
  { id: "badgir", photo: "room-badgir", name: "اتاق بادگیر", desc: "زیر بادگیر خونه، خنک‌ترین اتاق در روزهای گرم تابستون.", guests: 2, meters: 24, beds: "یک تخت دونفره", price: 3_200_000, amenities: ["حمام اختصاصی", "صبحانه‌ی محلی", "پشت‌بام اختصاصی"], tone: 1 },
  { id: "hoz-khaneh", photo: "room-hoz", name: "اتاق حوض‌خانه", desc: "کنار حوض و درخت انار، با درِ چوبی رو به حیاط.", guests: 3, meters: 30, beds: "یک تخت دونفره و یک تخت یک‌نفره", price: 3_900_000, amenities: ["حمام اختصاصی", "صبحانه‌ی محلی", "ایوان"], tone: 2 },
  { id: "kalbe", photo: "room-kalbe", name: "کلبه‌ی کاهگلی", desc: "خانه‌ای کوچک و مستقل در انتهای باغ، برای خانواده‌ها.", guests: 5, meters: 55, beds: "دو تخت دونفره و یک رختخواب", price: 5_900_000, amenities: ["آشپزخانه‌ی کوچک", "حمام اختصاصی", "حیاط اختصاصی", "صبحانه‌ی محلی"], tone: 3 },
];

export const EXPERIENCES = [
  { id: "stars", photo: "stars", title: "شب‌گردی و رصد ستاره", desc: "با راهنمای نجوم و تلسکوپ، دور از هر نوری.", hours: "۳ ساعت", group: "تا ۱۲ نفر", level: "آسان", price: 650_000 },
  { id: "camel", photo: "camel", title: "شترسواری در غروب", desc: "از روستا تا بلندترین تپه‌ی ماسه‌ای برای تماشای غروب.", hours: "۲ ساعت", group: "تا ۸ نفر", level: "آسان", price: 900_000 },
  { id: "salt", photo: "salt", title: "تور دریاچه‌ی نمک", desc: "با ماشین آفرود تا کویر نمک و عکاسی در بازتاب آسمون.", hours: "۵ ساعت", group: "تا ۶ نفر", level: "متوسط", price: 2_400_000 },
  { id: "bread", photo: "bread", title: "پخت نان محلی", desc: "همراه با مادربزرگ روستا، از خمیر تا تنور.", hours: "۱٫۵ ساعت", group: "تا ۱۰ نفر", level: "آسان", price: 350_000 },
  { id: "hike", photo: "hike", title: "کوه‌پیمایی تا قلعه‌ی متروکه", desc: "مسیر سنگی کوتاه تا قلعه‌ای ۳۰۰ ساله با چشم‌انداز کویر.", hours: "۴ ساعت", group: "تا ۱۰ نفر", level: "سخت", price: 800_000 },
  { id: "sand", photo: "sand", title: "سندبورد", desc: "سُر خوردن روی تپه‌های ماسه با تخته و آموزش.", hours: "۲ ساعت", group: "تا ۸ نفر", level: "متوسط", price: 700_000 },
];

/** Desert dunes under a sky, drawn with theme tokens. `night` darkens the sky and adds a moon. */
export function Dunes({ tone = 0, night, className, children }: { tone?: number; night?: boolean; className?: string; children?: React.ReactNode }) {
  const sky = night
    ? "linear-gradient(to bottom, oklch(from var(--background) calc(l - 0.04) c h), var(--card))"
    : [
        "linear-gradient(to bottom, color-mix(in oklch, var(--brand) 35%, var(--card)), var(--card))",
        "linear-gradient(to bottom, color-mix(in oklch, var(--warning) 25%, var(--card)), var(--card))",
        "linear-gradient(to bottom, var(--secondary), var(--card))",
        "linear-gradient(to bottom, color-mix(in oklch, var(--destructive) 18%, var(--card)), var(--card))",
      ][tone % 4];
  return (
    <div className={cn("relative isolate overflow-hidden", className)} style={{ background: sky }}>
      {night && <div aria-hidden className="absolute top-[14%] end-[16%] size-12 rounded-full bg-foreground/90 shadow-[0_0_60px_10px_color-mix(in_oklch,var(--foreground)_25%,transparent)] sm:size-16" />}
      {!night && <div aria-hidden className="absolute top-[22%] start-[22%] size-14 rounded-full bg-brand/80 blur-[1px]" />}
      <svg viewBox="0 0 800 300" preserveAspectRatio="none" className="absolute inset-x-0 bottom-0 h-3/5 w-full" aria-hidden>
        <path d="M0 170 C 120 110, 240 110, 360 160 S 620 230, 800 140 L800 300 L0 300Z" fill="color-mix(in oklch, var(--brand) 55%, var(--background))" opacity={night ? 0.35 : 0.55} />
        <path d="M0 220 C 160 170, 300 200, 420 230 S 680 190, 800 220 L800 300 L0 300Z" fill="color-mix(in oklch, var(--brand) 70%, var(--background))" opacity={night ? 0.5 : 0.8} />
        <path d="M0 260 C 200 240, 420 280, 800 250 L800 300 L0 300Z" fill="color-mix(in oklch, var(--brand) 40%, var(--background))" />
      </svg>
      {children}
    </div>
  );
}

function Logo() {
  return (
    <span className="flex items-baseline gap-2">
      <span className="text-2xl font-black">کاهگل</span>
      <span className="text-xs opacity-70">اقامتگاه بوم‌گردی</span>
    </span>
  );
}

/** Header (transparent over the home hero), mobile menu and footer shared by every page. */
export function Shell({ active, children, overlay }: { active: string; children: React.ReactNode; overlay?: boolean }) {
  const href = useHref();
  const [open, setOpen] = React.useState(false);

  return (
    <div className="min-h-dvh bg-background text-foreground">
      <header className={cn("z-40 w-full", overlay ? "absolute inset-x-0 top-0" : "sticky top-0 border-b border-border bg-background/85 backdrop-blur")}>
        <nav aria-label="اصلی" className="mx-auto flex h-20 max-w-6xl items-center justify-between gap-6 px-4 sm:px-6">
          <a href={href("/")} aria-label="اقامتگاه کاهگل، خانه">
            <Logo />
          </a>
          <ul className="hidden items-center gap-8 md:flex">
            {NAV.map((l) => (
              <li key={l.href}>
                <a
                  href={href(l.href)}
                  aria-current={active === l.href ? "page" : undefined}
                  className={cn("border-b-2 py-1 text-sm transition-colors", active === l.href ? "border-brand font-semibold" : "border-transparent text-foreground/75 hover:text-foreground")}
                >
                  {l.label}
                </a>
              </li>
            ))}
          </ul>
          <div className="flex items-center gap-2">
            <a href={href("/book")} className="inline-flex h-11 items-center rounded-full bg-foreground px-6 text-sm font-semibold text-background transition-transform hover:scale-[1.03]">
              رزرو اقامت
            </a>
            <Button variant="ghost" size="icon" className="md:hidden" aria-label="باز کردن منو" onClick={() => setOpen(true)}>
              <Menu />
            </Button>
          </div>
        </nav>
      </header>
      <Sheet open={open} onOpenChange={setOpen} title={<Logo />}>
        <ul className="flex flex-col p-2">
          {[{ href: "/", label: "خانه" }, ...NAV, { href: "/book", label: "رزرو اقامت" }].map((l) => (
            <li key={l.href}>
              <a href={href(l.href)} onClick={() => setOpen(false)} className="block rounded-lg px-3 py-3 text-base hover:bg-accent">
                {l.label}
              </a>
            </li>
          ))}
        </ul>
      </Sheet>

      <main>{children}</main>

      <footer className="border-t border-border">
        <Dunes tone={2} className="h-24" />
        <div className="mx-auto grid max-w-6xl gap-10 px-4 py-12 sm:px-6 md:grid-cols-3">
          <div className="space-y-3">
            <Logo />
            <p className="text-sm leading-7 text-muted-foreground">روستای مصر، بخش خور و بیابانک، استان اصفهان. ۴۵ کیلومتر مونده به جندق.</p>
          </div>
          <div className="space-y-2 text-sm">
            <p className="font-semibold">رزرو و هماهنگی</p>
            <p className="text-muted-foreground">
              <span dir="ltr">۰۹۱۳ ۲۰۰ ۴۵۶۷</span>
            </p>
            <p className="text-muted-foreground">پاسخ‌گویی هر روز ۹ تا ۲۱</p>
          </div>
          <div className="space-y-2 text-sm">
            <p className="font-semibold">صفحه‌ها</p>
            {[...NAV, { href: "/book", label: "رزرو" }].map((l) => (
              <a key={l.href} href={href(l.href)} className="block text-muted-foreground hover:text-foreground">
                {l.label}
              </a>
            ))}
          </div>
        </div>
        <p className="border-t border-border py-5 text-center text-xs text-muted-foreground">© ۱۴۰۵ اقامتگاه بوم‌گردی کاهگل · دارای مجوز میراث فرهنگی و گردشگری</p>
      </footer>
    </div>
  );
}
